INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Parmak Hesabı', 'parmak-hesabi-bilal-i-lhami-koksal-pn2ce', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Parmak hesabı yapıyorum tüm hayal kırıklarıma

Islak bir şehir oluyor tüm sevdiklerim

Yorgun bir martı oluyorum ben

Hiç bir şeyim olmuyor en sevdiğim...

Dokunulmazlığıma silah çekmiş her şey

Ben gidiyorum geliyorum

Gözyaşlarım çok fazla kaldı bende

Ağlamak  için bir yer..

Bir yer.

İki yer:

Üç yemez!', 'Parmak hesabı yapıyorum tüm hayal kırıklarıma Islak bir şehir oluyor tüm sevdiklerim Yorgun bir martı oluyorum ben Hiç bir şeyim olmuyor en ...', ARRAY['Türk Edebiyatı','Şiir','Bilal İlhami Köksal']::text[], 8.5, '{"poet":"Bilal İlhami Köksal","poet_slug":"bilal-i-lhami-koksal","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/parmak-hesabi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aklını Kullan', 'aklini-kullan-alper-kuruk-h3992', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Safahatin er geç sonu sefillik,

Resmiyetin sonu ise sivillik,

Bir gün başa dert olur bu sivrilik

Gider baştan akıl,gelir delilik...

Bir pusula ancak dört yön gösterir

Akıl pusulası tek yönü verir

İbresi hep doğrulara yönelir,

Seçmek senin,başka elden ne gelir? 

Gel aklını kullan,olmasın ziyan,

Durduk yerde niçin bu telaş,isyan? 

Şükret Allah''ına kalmadın yayan

Çıplak ayaktır pabucu anlayan...', 'Safahatin er geç sonu sefillik, Resmiyetin sonu ise sivillik, Bir gün başa dert olur bu sivrilik Gider baştan akıl,gelir delilik... Bir pusu...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/aklini-kullan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nafile', 'nafile-alper-kuruk-ewhhx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İster eziyetinden

Hergün ezilsin gönlüm,

İsterse hasretinden

Yansın,kavrulsun ömrüm.

Gönlüm içinde bir yer...

Tek açan çiçek umut,

Arada vitamin ver

İstersen beni unut...

Ne yapsan o temelli

Onu söndüremezsin,

Benim de yolum belli 

Beni döndüremezsin...', 'İster eziyetinden Hergün ezilsin gönlüm, İsterse hasretinden Yansın,kavrulsun ömrüm. Gönlüm içinde bir yer... Tek açan çiçek umut, Arada vit...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/nafile-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uğurlama', 'ugurlama-bilal-i-lhami-koksal-inr1m', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '''Uğurlama'' şarkısını kendime göre düzenliyorum

Yorgun bir yağmur zamanında

Olduğum yere yığılıyorum başıma gelen her damlayla 

Başıma gelen en güzel şeydi senin aşkın

Öyle üç harfli olmasına bakma esasında zor bir şeydir aşk; 

Bak şimdi üç harfli bir şeyin açıklaması yineden üç harfli

Garip bir yeditepe oluyor bu şehir ben giderken

Belki de sırf ben gitmeyeyim diye

Yedi ayrı dert; 

Yedi ayrı engel.

Çok uzak bir yere gidiyorum

Öyle bir yer ki içimdeki seni ancak o çözer

Öyle bir şey ki bu aşk insan diz üstü çöker

Öyle bir...

Öyle ki durmadan göz yaşı döker

Hayatımdan geçen beş harfli bir şeydin rüzgar gibi

Şimdi seni hiç bir benle açıklayamıyorum

Ben burdan gidiyorum', '''Uğurlama'' şarkısını kendime göre düzenliyorum Yorgun bir yağmur zamanında Olduğum yere yığılıyorum başıma gelen her damlayla  Başıma gelen ...', ARRAY['Türk Edebiyatı','Şiir','Bilal İlhami Köksal']::text[], 8.5, '{"poet":"Bilal İlhami Köksal","poet_slug":"bilal-i-lhami-koksal","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ugurlama-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiçbir Kadın Senin Kadar Sevilmedi', 'hicbir-kadin-senin-kadar-sevilmedi-huseyin-erdogan-ii2jw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Marmara sahiline indim 

dün akşam üzeri

Suadiye''de 

dalgalara uzattım ellerimi

oralarda bari 

tutarım diye o güzel ellerini

yıllar önce değmiş olsan dahi

hala duruyormuş inan ellerinin izleri

sıcacıktın vallahi 

o harika sözlerin gibi

ısıttın yüreğimi 

inan yakıp kavurdun içimi

öylesine duygulanmıştım ki

sanki sağanak yağmur basmıştı 

senin yolunu bekleyen gözlerimi

inan ki bu güne değin kainata 

senin kadar güzel hiçbir kadın gelmedi

sevgili şiirim bil ki bu dünyada 

hiçbir kadın senin kadar sevilmedi

sen gecemde yıldız günümde güneşsin

gönlümde durmadan esen meltem yelisin

sen benim ömrümce vaz geçemeyeceğim

mahşerde bile delicesine seveceğim

her şeyimi vereceğim  tek  eşimsin

                                                    29.11.2005

                                                Hüseyin Erdoğan', 'Marmara sahiline indim  dün akşam üzeri Suadiye''de  dalgalara uzattım ellerimi oralarda bari  tutarım diye o güzel ellerini yıllar önce değm...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/hicbir-kadin-senin-kadar-sevilmedi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mirrors', 'mirrors-arif-atalay-rf8lm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'mirrors, don''t look to my face,

             I''m not a person like you showed.

             mirrors, don''t show me the real,

             the real isn''t like you showed.

             tell me mirrors tell me,

             who is entering my soul

             and stealing me from me,

             how many persons are there in my body?', 'mirrors, don''t look to my face,              I''m not a person like you showed.              mirrors, don''t show me the real,              th...', ARRAY['Türk Edebiyatı','Şiir','Arif Atalay']::text[], 8.5, '{"poet":"Arif Atalay","poet_slug":"arif-atalay","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/mirrors-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilinmeyen Yolun Yolcusu', 'bilinmeyen-yolun-yolcusu-alper-kuruk-5hg9p', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Durakta bekliyorum, bir otobüs geçecek

Bilmediğim bir semte alıp da götürecek.

Nerde ineceğimi ne gördüm,ne bilirim

Oraya varır varmaz durmadan indirecek.

Otobüs,her duraktan bir defa gelir geçer,

Binecek yolcusunu dâima kendi seçer.

İlk bindiğin durağa sanma tekrar gelirim,

Aşk şarabını insan ömründe bir kez içer...', 'Durakta bekliyorum, bir otobüs geçecek Bilmediğim bir semte alıp da götürecek. Nerde ineceğimi ne gördüm,ne bilirim Oraya varır varmaz durma...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bilinmeyen-yolun-yolcusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akıl-"siz hiç ay aşığında ağladınız mı" Kitabından', 'akil-siz-hic-ay-asiginda-agladiniz-mi-kitabindan-omer-ekinci-micingirt-1e89l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gerdan kırıp raks eyledik 

Hakk''ı akla hapseyledik

Ne söz verdik ne söyledik 

Niçin böyle y/arsızız biz

Akıl akılın kapanı 

Kur''an''la akılı tanı 

Görün Hakk''ı ve tapanı 

Kur''an yoksa y/arsızız biz', 'Gerdan kırıp raks eyledik  Hakk''ı akla hapseyledik Ne söz verdik ne söyledik  Niçin böyle y/arsızız biz Akıl akılın kapanı  Kur''an''la akılı ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ekinci Micingirt']::text[], 8.5, '{"poet":"Ömer Ekinci Micingirt","poet_slug":"omer-ekinci-micingirt","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/akil-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Devir Daim 2', 'devir-daim-2-akin-akca-ms7zu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'I.

A. SEĞMEN

Oyna seğmenim (buz tutmuş Tuz gölü üstünce

Olsun ki, tuz ruhu, tuzla buza –Oz ruhu) 

Sırtından, omuzlarından,..o sarkan eklentiler

Askerin, apoletler değil, kıyafetinden.

Oyna, çalgıyla; 

Savrul, atın yelesiyle! -

tanırız seni 

İnsanın iskeleti, içinde çarklar işleyişi

- her nereye giderse! …

(eminiz) 

C.1b

Kırgız ozanı, ormandan gelmiş mağraya yerleşmiş.

Sandalyeye bağlayan onu, kuşkusuz o kovboy; 

Şapkasını buna zorla giydirmemişti.

Bu, onun kendi özgür iradesi olmalıydı 

(ala Alaska …) 

Şaman’da mı oydu yoksa,

Gökyüzünden mutluluk, sağlık dileyen? 

(Ateş gibi) 

Ve şimdi mağarada ateş …

Çevreyi gördü, gözleri seçti.

İçeri doğru raylar uzanıyordu.

Masadaki içten renkli beyaz bor şişesini alarak; 

Kafasından aşağı boşalttı, fil su içer gibi.

Yarısı döküldü.

Şaman o ise, kızılderiliye dönüşen de oydu.

İrade, kovboy şapkasını ona giydiren; 

400 bin Kırgız’a denk miydi

(hani o her, destanı ezberinden bilen) 

(ya da 30 bin Viking’e mi denkti, Saxon’a; 

Ha, Genghis …) 

Amerika’da; 

Kızılderililerin türk olması? 

C.1a DEVİR DAİM2

Şimdi mağarada uyandı, bilinmeyen mekanda.

Kırarak elektrikli iskemleden kelepçeleri

Doğruldu, bilekleri serbest bırakarak.

Yere bırakılmış, unutulmuş bir koca baltayı –

ayna mı iki yönlü, yoksa? Labyrs, kar baltası Amazon; 

bir arkasına savurunca arka duvar; öneyken ön duvar sarsıldı

- Kaparak başladı parçalamaya duvarları.

Kan ter içinde kalmıştı, biraz mola verdi.

Televizyonu açtı, tek kanalda da maç vardı.

Everton Leeds’i 1-0 yenerken iki ölü verdi.

Sonra bir belgesel başladı, kuşlara dair.

B.2 KUBBE & ATEŞ DESTANI’NDA COLOMB YANSIMASI

Akasya şamanı, şamdanlar avucunda besili rüyasında; 

Uzun sakalını sıvazlayarak, sabah erken uyandı.

(Cameltoe, koşarken nefes almak bile fazla sığınak; 

çok fazla devede tırnak) 

O gün özel bir gündü.

Kızıyla ateşe gitti.

Sağlık, mutluluk, onların dilekleri oldu.

Gökyüzü verdi,

Kuzeyinde Sibirya’nın.

(Uygurlardan, ama Göktürklerle bu sefer el ele; 

panthera tigris altaica*, Mançurya’dan …) 

Halkını toplayarak orman dağına göçe yöneltti

Kabileyi derken Şaman; 

Geçmek üzere oradan, Gül-Cennet Bahçesi yöresine

Cennet’te ağaçlarda bağırsaklar asılıydı dallarda**.

Rüzgar esti …

Bir dombra, bu şaman yaptı.

Kazak oldu; Kırgız, eskidendi

Ve böyle böyle, Kızılderili bir şefe dönüştü.

Ve cennette Anadolu ve bu merkezde Seğmen.

“Her Kırgız Manas’ı bilir”, “hay bin kunduz” – ***

O Kırgız Ozan, Kovboy şapkası başına geçirmiş

- Her insan peki insanlıktan nasibini alır mı …

Manas destanı, Efece; Manas Şehri, bir de, Amerika’daymış. ****

Öyleyse, Ala, âla,

Aladağlar’dan mı ormanadamı, Alaska? 

II. KUBLA DEVAMI’NA …

Bir anda yükseldi göklere ve sonra okyanusa tozları düştü,

Ve gene orda tümlendi.

Yerkürenin döner-hareketli, eriyik demir çekirdeğinden

Kazandığı ek enerjiyle! 

Sanki bunu önceden biliyordu yerküre yüzeyinde,

Düştü buraya, yükseltirken kendini; 

Kıt kanat kalmış kendi çabasıyla, 

Pegasus yaparken Helle taşıyan denizi.

İçi şeffaf derin deniz balıkları sardı çevresini

Ve çekik gözlü bir deniz kızı

Gülümseyerek selam verdi onun gülümseyen çehresine.

Akvaryum bile kapıysa,

Girdiler topluca bir midye açıldığında

Onun içine..

 doluştular.

“Gökyüzünden kanatlı, suyun içine doluşmuşlar”; 

Çöle yerleşirkendi yeryüzü –

Müzikle Kubilay inşa ederken sarayı,

Sam müziği iletirken

Ve din kalmadı çölleşmede yukarıda

(ve din kalmadı Sam, afyon almadan önce her düşündüğün; 

o kayalıklar üstü; ama düşünmediği hep, eşzaman, inanoğlunun) 

Ama ormanlar semirecekti okyanus tabanında

 ve serpilecekti

Çatlalardan çıkan, fokurdayan kabarcıklar; 

Akvaryumdaki yaşamak ve enerji; 

Tümden besliyor..

Arz oluşumunda su yüzeyinde

Mor ötesi ışınımlarca bölünmüş ve bölünmüş defalarca

Ve sonra karmaşık organizmalar oluşturmayı bağcıklamayı edimlemiş

Kök hücrelerini gelecekte.

-

*Sibirya kaplanı

**Dombra (yapılışı)    efsanesi

*** Bu bölüm, gezinirken gördüğüm Tv7’deki İpekYolu belgeselinde geçenler’den derlenen bilgilerden. Çift tırnak içleri alıntı, belgesel ve resimli roman alıntı cümlecikleri

 **** (türetme)    kız-oğlan barışı v.s. de, yeğenlerden türetme :)    efe,ece

Sam: samuel taylor (bi şair) 

haliyle Kubla bölümü Kubla Khan''a atfen sayılabilir

tam adı:Devir Daim 2 (Türk Yurdu''nda) 

ilk şekil

sevgiler

ek link:http://www.osmanlimedeniyeti.com/makaleler/osmanli-kiyafetleri/ankara-seymen-segmen.html', 'I. A. SEĞMEN Oyna seğmenim (buz tutmuş Tuz gölü üstünce Olsun ki, tuz ruhu, tuzla buza –Oz ruhu)  Sırtından, omuzlarından,..o sarkan eklenti...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":117,"source_url":"https://www.antoloji.com/devir-daim-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Uzakta', 'senden-uzakta-ufuk-coban-lmi8l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Öyle yalnızım ki senden uzakta ellerim titriyor,

Karanlık öyle sessiz ki beni hiç yalnız bırakmıyor.

Gözlerin bakmasın diye hasretin dolu yaşlarla,

Başım yerden duvarlara bir türlü kalkmıyor.

Kıymetini daha iyi anlıyor insan uzaklarda,

Bir dokunuşun, bir bakışın ne demek olduğunu.

Yalnızlığın acısını daha çok hissediyor insan,

Anıların koynunda, kokunun sarhoşluğunda.

Yapabileceğim o kadar çok şey varki bu şehirde,

Hiç birini yapmak gelmiyor içimden bu şekilde.

O kadar çok şey varki söyleyebileceğim herkese,

Sana birşey söylemeden dilim varmıyor kelimelere.

Senden uzaktayım, ama bilmediğin bir şekilde,

Aslında ellerim değil senden uzakta olan,

Gözlerim değil baktığında göremeyecek olan.

Ruhunu alıp gittin, sevgim senden uzakta kalan.

29/11/2005 09:00', 'Öyle yalnızım ki senden uzakta ellerim titriyor, Karanlık öyle sessiz ki beni hiç yalnız bırakmıyor. Gözlerin bakmasın diye hasretin dolu ya...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Çoban']::text[], 8.5, '{"poet":"Ufuk Çoban","poet_slug":"ufuk-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/senden-uzakta-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırk Biri Doldurunca...', 'kirk-biri-doldurunca-alper-kuruk-0z3uy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kalbimde kök salıp tek gülsün açan

Kanımla sulanıp bende yaşayan.

Emsâlin bulunmaz,sen:yediveran,

Kırk bir maşallahla korur Yaratan...

Bende bulduk,sende bulduk biz bizi

Tanrı uygun görmüş her ikimizi,

Kan yerine sevgi bedenimizi

Dolanır,doldurur canevimizi.

Birleştirmiş Allah kaderimizi

Nazardan korusun biz çiftimizi,

Fânide terketsek birbirimizi

Buluşup da süreriz bâkimizi...', 'Kalbimde kök salıp tek gülsün açan Kanımla sulanıp bende yaşayan. Emsâlin bulunmaz,sen:yediveran, Kırk bir maşallahla korur Yaratan... Bende...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kirk-biri-doldurunca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost Yüklen', 'dost-yuklen-huseyin-sigirtmac-6u0x5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dost yüklen omzuna hayat yükünü.

Muhannete muhtaç olmamak için.

Rehber et doğruyu ara hakkını.

Muhannete muhtaç olmamak için.

İş başa düşüp de olmadan pişman.

Göz ayağa döner yeter bir düşmen.

Yürümek de yetmez gerekir koşman.

Muhannete muhtaç olmamak için.

Dar günde ölçmeli uzak yakını.

Kimler gör onarır bozuk çarkını.

İleri yürüyüp kolla arkanı.

Muhannete muhtaç olmamak için.

Her yüze güleni dost olur sanma.

Buna dünya derler sakın aldanma.

Gençlik başta iken boşa dolanma.

Muhannete muhtaç olmamak için.

Tırnağın var ise kaşı başını.

Namerde bildirme yavan aşını.

Gözüne miğfer et keman kaşını.

Muhannete muhtaç olmamak için.

Tok anlamaz derler halinden açın.

Geleceğe yön ver var iken gücün.

İbret al sözünden gel Sığırtmaç’ın.

Muhannete muhtaç olmamak için.', 'Dost yüklen omzuna hayat yükünü. Muhannete muhtaç olmamak için. Rehber et doğruyu ara hakkını. Muhannete muhtaç olmamak için. İş başa düşüp ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sığırtmaç']::text[], 8.5, '{"poet":"Hüseyin Sığırtmaç","poet_slug":"huseyin-sigirtmac","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/dost-yuklen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yollar', 'yollar-alper-kuruk-lnded', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hangi yola girersen 

Sonu ölüme çıkar,

Nerelere gidersen

Seninle gider yollar.

Kimi uzun incedir

Kimi geniş ve kısa,

Çözülmez bilmecedir

Bilineni de olsa...

Birbirine bağlanır

Kısa ve uzun yollar,

Yolculukta ağlanır

Yıllar ki nice yıllar...

Yıllar yıllara ekli

Yollar ise yollara,

Koşuyorum âhenkli

Açılmış o kollara...', 'Hangi yola girersen  Sonu ölüme çıkar, Nerelere gidersen Seninle gider yollar. Kimi uzun incedir Kimi geniş ve kısa, Çözülmez bilmecedir Bil...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yollar-80-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anneler Gününde', 'anneler-gununde-alper-kuruk-4vmq8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir anaydın sen onu benden de çok severdin

Bana pırlanta yürekli evlâdını verdin.

Sevgin bölündü şimdi kızınla damadına

Bir ad daha eklendi o mübarek adına.

Kimi kayınvalide diyor kimi kaynana...

Ne derlerse desinler sen benim için ana...

Anaların öptüğü yanakta gül açarmış,

Ananın duasıyla kişi Cennete varmış...

,', 'Bir anaydın sen onu benden de çok severdin Bana pırlanta yürekli evlâdını verdin. Sevgin bölündü şimdi kızınla damadına Bir ad daha eklendi ...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/anneler-gununde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tüm Evlilerin Evlilik Yıldönümleri İçin', 'tum-evlilerin-evlilik-yildonumleri-i-cin-alper-kuruk-zqp0u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Evlilik eskidikçe şarap gibi yıllanır

Sevgisi gönüllerde,tadı damakta kalır.

Dileriz sizinki de nice yıllarca sürsün

Birlikteliğiniz hep örnek olsun,övülsün...

Bir yılınızı daha içtenlikle kutlarız,

Sizler mutlu oldukça bizler yaşarız,varız...', 'Evlilik eskidikçe şarap gibi yıllanır Sevgisi gönüllerde,tadı damakta kalır. Dileriz sizinki de nice yıllarca sürsün Birlikteliğiniz hep örn...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/tum-evlilerin-evlilik-yildonumleri-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavisevda', 'mavisevda-ali-fuat-boga-1py2w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevda akılda mı başlar,

A canım,

Yoksa gözbebeğinde mi yüreğin?

Özlemek alın yazısı mı,

Tutsak olmak avuçlarına her bahar,

Koşarken doludizgin?

Dönüp bakmak ardına,

Kaybetmek ya da öyle bir şey,

Ve

Yitip gitmek mavisinde Akdeniz’in..', 'Sevda akılda mı başlar, A canım, Yoksa gözbebeğinde mi yüreğin? Özlemek alın yazısı mı, Tutsak olmak avuçlarına her bahar, Koşarken doludizg...', ARRAY['Türk Edebiyatı','Şiir','Ali Fuat Boğa']::text[], 8.5, '{"poet":"Ali Fuat Boğa","poet_slug":"ali-fuat-boga","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sevda-nerede-baslar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz', 'deniz-sedat-alkan-05qjd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kederlerim dalgalara.

Göz yaşlarım martılara.

Kumlar dinler, deniz ağlar.

Beni bir bu sahil anlar.

Uzak kaldım meyhaneci.

Taşı bir bir mezeleri.

Güneş doğar, yakın şimdi 

Eksik etme kadehleri.

Ölürüm ben bu akşam.

Dertler bir bir yakar beni

Seyrek gelir meyhaneci.

Söyleyemem dertlerimi.

Gelir şimdi meyhaneci.

Dindirmiyor kadehleri.

Al götür deniz beni.

Dindirirsin dertlerimi.

Götür beni uzaklara.

Sen anlarsın bir tek beni

Güneş yakın, doğar şimdi.

Derdimi göm, kederimi.', 'Kederlerim dalgalara. Göz yaşlarım martılara. Kumlar dinler, deniz ağlar. Beni bir bu sahil anlar. Uzak kaldım meyhaneci. Taşı bir bir mezel...', ARRAY['Türk Edebiyatı','Şiir','Sedat Alkan']::text[], 8.5, '{"poet":"Sedat Alkan","poet_slug":"sedat-alkan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/deniz-91-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yansıma İğrençtir Bazen', 'yansima-i-grenctir-bazen-mehmet-uluc-gqdx0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yansımanın dilinden anlamayan 

              çocuklar kadar temizsindir 

              bu sabah

şehir kaçkınlarını andırıyordur yüzün 

ve el kalınlığında bir mandolin tınısı 

alıp götürmüştür seni bu diyardan

rock şarkıcıların ilham kaynağı genç 

                bir  kızla sohbet etmişsindir o uzun 

                                     yolculukta 

sahi sen hangi kentin kadınısın

hangi yakışıklı jönün metre''si

yüzün dahil bütün ayrıntıların 

                 iğrenç bir jöntürk efsanesi', 'yansımanın dilinden anlamayan                çocuklar kadar temizsindir                bu sabah şehir kaçkınlarını andırıyordur yüzün  ve el...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Uluç']::text[], 8.5, '{"poet":"Mehmet Uluç","poet_slug":"mehmet-uluc","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yansima-igrenctir-bazen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırakamam Ben Seni Asla! ! !', 'birakamam-ben-seni-asla-fatih-demir-9e311', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen beni bırakıp gitsende

Gözüme görünme desende

Bana çok acı çektirsende

Bırakamam ben seni asla

Ölüm bile olsa sonunda

Vermem seni ellere asla

Sen böyle olduğuma bakma

Bırakamam ben seni asla

Baş koymuşum senin yoluna

Ne olur bir''tanem naz yapma

Döngel artık benim yanıma

Bırakamam ben seni asla...', 'Sen beni bırakıp gitsende Gözüme görünme desende Bana çok acı çektirsende Bırakamam ben seni asla Ölüm bile olsa sonunda Vermem seni ellere ...', ARRAY['Türk Edebiyatı','Şiir','Fatih Demir']::text[], 8.5, '{"poet":"Fatih Demir","poet_slug":"fatih-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/birakamam-ben-seni-asla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkımız Olsun', 'askimiz-olsun-fatih-arslan-m3day', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir gece,

Bir ses çınlar kulaklarında,

Musluktan akan damlalar,

Şiir yazdırır sana,

Vesile, araç; musluktan akan sudur,

İhtimalini sormayın,

Kahretsin huyumdur.

İsraftır boşa akmasın diye kalktım,

Ellerim varmadı,

Yapamadım seyre daldım,

Ahengini dinledim,

Çağrışımlar kurdum,

Bakabaka kaldım.

Ona çektim, tekrarladım,

Durmadı, durduramadım,

Yoktun, yanlızdım, sıkıldım,

Bir damla yaş düştü gözlerimden, 

Ağladım.

O ağladı, ben ağladım.

İkimiz fazla geldik odaya,

Kapatmak istedim ama titredi ellerim.

Yapamadım,

Yoksun olan saçımdan, 

Bir tel daha bıraktım.

Aynada kendime baktım,

Oysa ben bende değil,

Karanlıktım.

Damlanın yere vurduğu an,

Çin işkencesi geçiriyordu yürek,

İçimde beslediğim sevdalım,

Aç avuçlarını,

Sana yolluyorum,

Bak nasılda çarpıyor,

Bak nasılda can atıyor.

Bu musluktan akan damla; Sen

Bu gözyaşı; Ben

Gökyüzüne dolsun,

Gittikçe çoğalan bu yağmur,

Aşkımız olsun.', 'Bir gece, Bir ses çınlar kulaklarında, Musluktan akan damlalar, Şiir yazdırır sana, Vesile, araç; musluktan akan sudur, İhtimalini sormayın,...', ARRAY['Türk Edebiyatı','Şiir','Fatih Arslan']::text[], 8.5, '{"poet":"Fatih Arslan","poet_slug":"fatih-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/askimiz-olsun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fırtına Ve Liman', 'firtina-ve-liman-alper-kuruk-33eh7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gizli fırtına eser

Gönlümün limanında,

Kulluktan yok bir eser

Senin şu imânında.

Sana inanıp da ben

Sende liman alamam,

Sığ suyunda yüzerken

Batıp dibe dalamam.', 'Gizli fırtına eser Gönlümün limanında, Kulluktan yok bir eser Senin şu imânında. Sana inanıp da ben Sende liman alamam, Sığ suyunda yüzerken...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/firtina-ve-liman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ata''nın 50.Ölüm Yıldönümü İçin', 'ata-nin-50-olum-yildonumu-i-cin-alper-kuruk-urwo4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '10 Kasım 1938

10 Kasım 1988

Aradan geçen bunca yıl tam elli.

Adın hep dillerde,sevgin gönüllerde

Ölmediğin,yaşadığın besbelli...

Uzun uzun nice yıllar geçtikçe

Devrimlerin gitgide yerleştikçe,

Fikirler dâima sende birleştikçe

Kalplerde taht kuracaksın temelli.

Mustafa''ydın küçükken Kemâl oldun,

Sayılan,sevilen bir cemâl oldun,

Dehanla bütün dünyaya mal oldun

Yurda Bayrak oldun İstklâl oldun,

Özünle de sözünle de TÜRK ''sün sen

Bir tanecik KEMAL ATATÜRK ''sün sen.', '10 Kasım 1938 10 Kasım 1988 Aradan geçen bunca yıl tam elli. Adın hep dillerde,sevgin gönüllerde Ölmediğin,yaşadığın besbelli... Uzun uzun n...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ata-nin-50-olum-yildonumu-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık Yaşayacağım...', 'artik-yasayacagim-omer-golge-m6b0y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gelmezdi aklıma bu yaştan sonra

Gözlerindeki hüzne vurulacağım

Yitirip aklımı divane gibi

Düşüp gamzelerinde kaybolacağım

Damla damla sızıp gönül tasına

Sıcaklığınla kavrulacağım

Kırkından sonranın dinginliğinde

Sevda tufanında savrulacağım

Her ne hal olduysa geldi başıma

Çare yok buna da alışacağım

Tekleyen kalbimle dizin dibinde

Bir ömür boyunca yaşayacağım', 'Gelmezdi aklıma bu yaştan sonra Gözlerindeki hüzne vurulacağım Yitirip aklımı divane gibi Düşüp gamzelerinde kaybolacağım Damla damla sızıp ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Gölge']::text[], 8.5, '{"poet":"Ömer Gölge","poet_slug":"omer-golge","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/artik-yasayacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sahile Koştum Bu Sabah', 'sahile-kostum-bu-sabah-celal-topo-2jg4j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dudaklarıma bir şarkı bağlayıp

Sahile koştum bu sabah yine

Güneş yüzünü gizlemişti

Bulutların peçesiyle

Utangaç bir gelin gibi gizledi hep

Sakladı sarı saçlarını sıcak gülüşünü

Hovarda bakışlardan...

Sen aklıma geldin bir an

Burkuldu içim gözlerim nemlendi

Mavi bir mendille sildim gözyaşımı

Oturarak denizin ıslak dizlerine

Kumların tuzlu yüzünü okşadım

Titreyen ellerimle...

Çok bekledim çok...

Sahildeydim bu sabah yine

Umutlarımı asarak

Hayallerimin kırık askısına

Boş gözlerle

Geriye döndüm sessizce.....

29 / 11 / 2005  Antalya', 'Dudaklarıma bir şarkı bağlayıp Sahile koştum bu sabah yine Güneş yüzünü gizlemişti Bulutların peçesiyle Utangaç bir gelin gibi gizledi hep S...', ARRAY['Türk Edebiyatı','Şiir','Celal Topo']::text[], 8.5, '{"poet":"Celal Topo","poet_slug":"celal-topo","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sahile-kostum-bu-sabah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alice, tavşan deliğinde', 'alice-tavsan-deliginde-akin-akca-sr06y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Lewis Carroll, Alice tavşan deliğinde yok; 

Şapkadan armut çıkardı. 

Sabır, eylemdir 

Ama fal asla bakmayacağız – 

İnsani talihe şans diyenin iki kat daha tavuk karası. 

(Koşullar altı şansı ayet bile bilmeyiz 

gerektiğinde biz, Tanrı''yı; 

Ah, oh sahte değiliz)

Yumurta mı, tavuk mu 

Yumrubaz 

(Evren fazla düz)

Seç 

kendini', 'Lewis Carroll, Alice tavşan deliğinde yok;  Şapkadan armut çıkardı.  Sabır, eylemdir  Ama fal asla bakmayacağız –  İnsani talihe şans diyeni...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/alice-tavsan-deliginde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yâr! ..', 'y-r-dursun-elmas-codzf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ahir günlerinde garip ömrümün

İçinde hançersin, kakılısın yâr! 

Yaralı sinemin, mahzun gönlümün

Kırgın tellerinde takılısın yâr! 

Yel vurdu bağıma, bülbülüm ötmez

Lal oldu dillerim, kelamım yetmez

Gönül vurgunuyum, dumanım tütmez

Yürek yangınımda yakılısın yâr! 

Elveda demeden çekip gitsen de

Arayıp sormasan, gel demesen de

Bırak bu sevdayı, unut desen de

Hasret düşlerimde çakılısın yâr!', 'Ahir günlerinde garip ömrümün İçinde hançersin, kakılısın yâr!  Yaralı sinemin, mahzun gönlümün Kırgın tellerinde takılısın yâr!  Yel vurdu ...', ARRAY['Türk Edebiyatı','Şiir','Dursun Elmas']::text[], 8.5, '{"poet":"Dursun Elmas","poet_slug":"dursun-elmas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yar-76-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyler Bağışlar', 'beyler-bagislar-cansever-eyuboglu-pvjrp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '-Türkçe''nin bütün bey''lerinin şerefine...-

Esirgeyen ve bağışlayan Bey''lerin aşkına

Kıyısız yaşamları kanatlarınızla alkışlayın

Gökyüzü kırk ömürlü çınarlara el verirken

Yeryüzünü cinayetsiz gecelere bağışlayın.

Dalga dalga açılan ipek albümdeki sevdalı yüzleri

Unutmayın, bir Kars''ı, bir de kuş seslerini

Üstü kalsın, her dudak izinin kadehlerde/mendillerde

Ne demiş uçurumda açan çiçek: Beni Cemal Bey''e bağışlayın.

Nerde bir gün, bir çift Rosenberg havalansa

Anı''sıyla Melih Bey''in  apansız kederlenin

Rakı için, karanfil saçın, Telefon''un öbür ucundaki

Oktay Bey''i San Markolu güvercin''e bağışlayın.

Bir hikmeti varsa soluduğunuz kirli çağın

Düş gününüzü de emek harcıyla yaşayın

Anımsayın Nâzım Bey''i her alacakaranlıkta

Onurunuzu soğuk bir kelepçeye bağışlayın.

Ahmed Bey saçlarına kan gülleri takmış demleniyor

Kendi köklerini sevsin diye suladığınız çiçekler

Kore dağlarında paslanan tabakanın hatırı için

Son bir tutam tütününüzü Enver Bey''e bağışlayın.

Sayın ki  Evler''in utancıdır çekilen acılar biraz da

Beşiktaş''ta solgun gölgesini izleyin Behçet Bey''in

Kandiller yakın Dar Çağ''ların aşksız odalarında

Kanatlarınızı ecelsiz bir pervaneye bağışlayın.

Yüzünüzü yıkayın artık, Büyük Saat''in vaktidir

Kamulaştırın sonsuz hüzünlerini Turgut Bey''in

Bir güzellik nasıl yudumlanırsa öyle ödeyin Edip Bey''in hesabını

Sevgi ile Sevda''nızı Kar Yangını''nın yerçekimine bağışlayın.

Dönüp geri bakın son kez  İstanbul''dan Niksar''a doğru

Yakılan kitaplar, muskalı bozkırlarla tutsak Anadolu

Kulak verin, Cahit Bey''in türküsü halaylarla başlayacak

Yarın yüreğinizi üşüyerek ısıtan bir serçe''ye bağışlayın.', '-Türkçe''nin bütün bey''lerinin şerefine...- Esirgeyen ve bağışlayan Bey''lerin aşkına Kıyısız yaşamları kanatlarınızla alkışlayın Gökyüzü kırk...', ARRAY['Türk Edebiyatı','Şiir','Cansever Eyüboğlu']::text[], 8.5, '{"poet":"Cansever Eyüboğlu","poet_slug":"cansever-eyuboglu","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/beyler-bagislar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben şair değilim *', 'ben-sair-degilim-ali-riza-unal-h7v5z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mektebi ortadan,deffi tard olmuşum,

Hikmeti alâdan, muradı arz olmuşum,

Cehlimin ummanı,halimin sultanı,

Halık-ı canan,Rabbi Alâdır Rabbi alâ,

Nefsimi yokta, varıma üryan olmuşum,

Ümmüyü sadrımız açıldı, ezeli belâya,

Dönmedik düştükte, bin kahrı cefaya,

Gayrı cefamız bir oldu,bahrı sefaya,

O gaybul gayba vakıf, üryân olmuşum,

Gel pervaneyi aşikân, o ıgrayı kelâma,

Bil ki alfabe değil, var o ledünni alâya,

Peyman vermişim  terke Ahâdi kübrayâ,

Zerremiz salınmış bir vahidi deryaya,

O meâli Kur''ana, hadım-ı püryan olmuşum

Münkire meydan verme, rezil olunur

Koy kapıda varını, vezir olunur

Bu yolda er olana mürşit bulunur

Bu kelâmın sahibi Rıza görünür

Vallahi Hüda, secdeyi Rahmandır,

Abdi aczim ayan ben dildar olmuşum', 'Mektebi ortadan,deffi tard olmuşum, Hikmeti alâdan, muradı arz olmuşum, Cehlimin ummanı,halimin sultanı, Halık-ı canan,Rabbi Alâdır Rabbi al...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ben-sair-degilim-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Gözlüyorum', 'seni-gozluyorum-mehmet-postalli-nsv3s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Açtım kollarımı sonuna kadar

Seni gözlüyorum, gözlerim yolda

Sen yoksan yanımda, dünya bana dar

Seni gözlüyorum, gözlerim yolda

İçime oturdu bir garip hüzün

Beni kaygılardan ayırın, süzün

Gözümde tütüyor gülüm gül yüzün

Seni gözlüyorum, gözlerim yolda

Hayalin karşımda, kulağım seste

Adın dudağımda, dilimde beste

Nazlı çiçeklerden yaptım bir deste

Seni gözlüyorum, gözlerim  yolda', 'Açtım kollarımı sonuna kadar Seni gözlüyorum, gözlerim yolda Sen yoksan yanımda, dünya bana dar Seni gözlüyorum, gözlerim yolda İçime oturdu...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Postallı']::text[], 8.5, '{"poet":"Mehmet Postallı","poet_slug":"mehmet-postalli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seni-gozluyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Işık Kız Mumun Gözyaşları', 'isik-kiz-mumun-gozyaslari-tulay-sustam-jg7gk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'beyazlar içinde 

dimdik karşında duruyorum

hani

bir ateş yaksan

sevdana boyun eğeceğim 

hani

bir dokunsan 

gölgem vuracak yüreğine

karanlığın kulağına

beni sevdiğini söylesen

bir ömür boyu senin

''''ışık kızın'''' olacağım.

28 kasım

derin aşk kırıntıları', 'beyazlar içinde  dimdik karşında duruyorum hani bir ateş yaksan sevdana boyun eğeceğim  hani bir dokunsan  gölgem vuracak yüreğine karanlığı...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/isik-kiz-mumun-gozyaslari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçen Ömür', 'gecen-omur-ebru-rabia-berkul-18k4y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gel gitlerle

Geçiyor ömrüm

Bugün hüzün denizinde 

Boğulup giderken

Yarın sevinç

Çığlıklarıyla

Uyanıyor kalbim

Ömür bu gel-gitlere

Bu ıstırap ve

Sevinçlere

Ne kadar daha dayanır,

Ne kadar daha

Yorulmadan

Ne kadar daha

Dimdik, ayakta kalarak

Mücadele eder

Yaşamak bu kadar,

Bu kadar acımasız

Ve bu kadar

Zor mu olmalıydı?', 'Gel gitlerle Geçiyor ömrüm Bugün hüzün denizinde  Boğulup giderken Yarın sevinç Çığlıklarıyla Uyanıyor kalbim Ömür bu gel-gitlere Bu ıstırap...', ARRAY['Türk Edebiyatı','Şiir','Ebru Rabia Berkul']::text[], 8.5, '{"poet":"Ebru Rabia Berkul","poet_slug":"ebru-rabia-berkul","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gecen-omur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadınlar', 'kadinlar-ebru-rabia-berkul-pj0r7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Buğday tarlalarında

Renkleri ne olursa olsun

Buğdaydan daha parlak,

Fabrikalarda,

Sabır taşı

Olduklarının ispatı

Sakin,sessiz

O minnacık elleriyle

İp dokuyan,

Sessiz ve usulca

Çocuklarını kucaklarına 

Almayı bekleyen

Sevgilerini,

Birlikte oldukları

Her canlıya yansıtabilen

Yaşamın her alanında

Var olan

Ve

Var olmayı

Sürdürecek olan

Kadınlar,

Sabır,sevgi

Ve

Emekten oluşmuş

Kadınlar.', 'Buğday tarlalarında Renkleri ne olursa olsun Buğdaydan daha parlak, Fabrikalarda, Sabır taşı Olduklarının ispatı Sakin,sessiz O minnacık ell...', ARRAY['Türk Edebiyatı','Şiir','Ebru Rabia Berkul']::text[], 8.5, '{"poet":"Ebru Rabia Berkul","poet_slug":"ebru-rabia-berkul","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kadinlar-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düğünümüz', 'dugunumuz-alper-kuruk-fm9m8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yıl 1961,27 Temmuz...

Ben Konya/Seydişehir''li damat

Sen Gelibolu''lu gelin kız.

Çalan orkestrayla salona girerken biz

Evliliğe atılan beraber bu ilk adımdı

Sağımda ölene dek benim olacak kadındı.

Ayakta muhabbetle bekliyordu gönüller

Saadetimiz için alkış tuttu tüm eller.

Yüzlerimizdeki utançtı

Bekârlıktan son kalan bu görüntü,

Bir devri kapayıp bir devri açtı sanki

Ellerimle açtığım yüzündeki tül örtü...

Saadetti gözlerimizde ışık ışık parlayan,

Anneler,babalar,kardeşler ve dostlarla

Çepçevre yanımızı dolduran masalarda

Müşterek neş''emizdi bizimle paylaşılan...

Çalınan ''KOMPARSİTA '' yekvücut etti bizi

Gökten yağan saadet kapladı kalbimizi...

Başından geçen duyar,bu ne tatlı bir danstı? 

Bizi şimdiye kadar bağlayan bir alyanstı.

Ondan sonra var oldu saadetten zincirler

Kopmaz,kalpler ayrılmaz,ölüm olmazsa eğer...

Kadın dolusu salon içinde bence tektin

Bembeyaz duvağınla gerçekten bir melektin...

Kollarımın içinde kuş gibi uçtun,sektin,

Saadetle yapılmış yuvana girecektin...

Düğün-derneğimizin gelip çatınca sonu

Terkediverdik gittik biz sessizce salonu.

Değil asla üzgüden,sevinçten boşanmıştı

Güzel,elâ gözünün birkaç damlacık yaşı,

Böylece oluverdik biz hayat arkadaşı...

Evimize atarken birlikte ilk adımı

Yine tekrar edeyim o anki şu duamı:

''Şükürler olsun Tanrı''m verdin bu muradımı...''

Bir yatak,yorgan,yastık yetişir ikimize

Sevgilerle,saadet dolsun hep evimize...

Darısı bekârların başına olsun derim...

''DİLEĞİME'' erdiren Tanrı''ma şükrederim...', 'Yıl 1961,27 Temmuz... Ben Konya/Seydişehir''li damat Sen Gelibolu''lu gelin kız. Çalan orkestrayla salona girerken biz Evliliğe atılan beraber...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/dugunumuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayram Mesajı', 'bayram-mesaji-mehmet-postalli-xoda7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ramazan rahmetiyle cümle günahlar yunsun

Adınız cennetlikler arasında okunsun

Melekler, kevser ırmağından badeler sunsun

Ayağına çimenler, eline güller dokunsun

Bayramınız mübarek, duanız kabul olsun', 'Ramazan rahmetiyle cümle günahlar yunsun Adınız cennetlikler arasında okunsun Melekler, kevser ırmağından badeler sunsun Ayağına çimenler, e...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Postallı']::text[], 8.5, '{"poet":"Mehmet Postallı","poet_slug":"mehmet-postalli","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bayram-mesaji-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başlangıç', 'baslangic-ebru-rabia-berkul-w1gu4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her yeni gün

Yeni bir başlangıç

Yeni bir doğuş sanki

Her gün,

Farklı bir tatta

Farklı bir yerden 

Başlıyorum hayata

Bazen küskün

Bazen neşe içinde

Sevinçler de,

Hüzünler de,

Yaşadığım sürece

Sadece bana ait

Ve ben,

Hayatı bütün yönleriyle

Tamamıyla seviyor,

Kabul ediyorum.', 'Her yeni gün Yeni bir başlangıç Yeni bir doğuş sanki Her gün, Farklı bir tatta Farklı bir yerden  Başlıyorum hayata Bazen küskün Bazen neşe ...', ARRAY['Türk Edebiyatı','Şiir','Ebru Rabia Berkul']::text[], 8.5, '{"poet":"Ebru Rabia Berkul","poet_slug":"ebru-rabia-berkul","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/baslangic-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel gelelim dosta', 'gel-gelelim-dosta-ali-riza-unal-7z7q2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Suphan hicap eyler ehli avama,

Her çehrede bilki künh ar görünür,

Tende kılıf olmuş cehli civana.

Mecnuna leylâda didâr görünür,

Nikap ayan olur aşk-ı hüddama,

Cennet kaygusu olan zünnâr görünür,

Gel aşk-ı tabibe düşme harama,

Halk-a harab ehle nigâr görünür..', 'Suphan hicap eyler ehli avama, Her çehrede bilki künh ar görünür, Tende kılıf olmuş cehli civana. Mecnuna leylâda didâr görünür, Nikap ayan ...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gel-gelelim-dosta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyük büyük', 'buyuk-buyuk-hayri-padak-yaxnd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'şimdi senin gözlerin büyük

büyük büyük bakıyorsun ya dünyaya

bütün çocuklar kocamandır şimdi

ya yıldızlar, yıldızlar çok mu uzaktadır

hani diyorum kapasan gözlerini

karanlıklar çökse saçlarına

sonra bir çocukmuşum gibi gelsem

tandoğan’da çocuklarla bir seslensem seni

çiçekler taksam sana

kuşlar kız kulesi’nden yıldızları toplasa

kanat kanat serpse saçlarına 

karşıyaka’da bir rüzgar mehtabı sürüklese 

çekilse sular, ağlasam sunsam sana denizi 

açsan gözlerini 

görmesem ayça aydınlığında 

çatılmasa kaşların 

bir günah gibi girerim gözlerine

şimdi senin gözlerin büyük

büyük büyük bakıyorsun ya dünyaya

bütün büyük günahları işlese de çocuklar

ne kadar büyük görsen de çocuktur affedilir değil mi', 'şimdi senin gözlerin büyük büyük büyük bakıyorsun ya dünyaya bütün çocuklar kocamandır şimdi ya yıldızlar, yıldızlar çok mu uzaktadır hani d...', ARRAY['Türk Edebiyatı','Şiir','Hayri Padak']::text[], 8.5, '{"poet":"Hayri Padak","poet_slug":"hayri-padak","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/buyuk-buyuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceyle Sevişmelerim', 'geceyle-sevismelerim-burhanettin-akdag-23oid', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gecenin derinliklerinden akıp geliyor hüzünlerim 

Rüzgarın sırtında uçuşuyor hayallerim, uzaklaşıyor 

Gurubun kızıllığında için için yanıyor, geleceğim 

Yıldızların kuyruğuna takılmış ruhum, sallanıyor 

Göz kırpıyor kuzey yıldızı uzaklardan hasretle 

Ayın gülümsemesiyle bile dağılmıyor, sıkıntılarım… 

Masmavi bir aşkı yaşamışken seninle, doyumsuzca 

Lacivertin tam ortasında kıvranıyorum şimdi 

Kara bulutlar karartıyor umutlarımı, birer birer 

Aydınlık gecede lapa lapa yağıyor yüreğime, acılar 

Karanlığın arasından yol bulamıyor, düşüncelerim 

Durmaksızın, kesik kesik öksürüyor, hicranım 

Yutkundukça, düğümleniyor kalbime sensizliğim… 

Hazımsız ve sıkıntılı bir şafak vaktindeyim 

Sancılı doğumunu seyrediyorum güneşin 

Seherin meltem esintisinde, çocuksu bir coşku var 

Bülbül de sohbette güllerle, alacakaranlığında sabahın 

Yaşlarımın yağmuru sel olup akıyor, geçmişimden 

Baharın rengarenk çiçeklerini unutmuş artık, belleğim 

Kışın karası kirletiyor yüreğimin hazzını, bıkmadan 

Yalnızlığın ağırlığı çöküyor göğüs kafesimin üzerine 

Biniyor kirpiklerimin üzerine, tonlarca ağıtın acı yağmurları 

Yalnızlığın korkusuyla titriyor, ürkek bedenim… 

Güzellikleri unutmuş, algılamıyor artık hayallerim 

Sonbahar yağmurlarındaki gökkuşağım soluk ve renksiz 

Yedi renginin hepsi de griye dönüşmüşler semada 

Gönlümün tualinde sadece siyah ve beyaz var 

Açmıyor artık ruhumdaki bahar çiçekleri 

Hepsinin gözü yaşlı, hepsi birer hüzün tomurcukları 

Ağır basıyor yüreğimdeki umutlara siyahın karası 

Kararsız ve ağır bir uykudayım, pazarlıktayım düşlerimle 

Kesiliyor aniden gördüğüm güzellikler, en can alıcı yerinde… 

Kalkmak istemiyor göz kapaklarım, nazlanıyorlar 

Nefesim bile kesmek istemiyor, uykumun hızını 

Düşüyorum sevda uçurumlarından, aşağılara 

Yuvarlanıyorum çaresizliğin azgın dalgalarına 

Sonsuzluk pınarında, yarınlarım bile akmıyor 

Kilitlenmiş zaman, saat durmuş hicranımın üzerinde 

Yarılıyor ortadan ikiye, baştan aşağıya duygularım 

Karamsar yarısı kalıyor bende, iyimser yarısı kaçıyor 

Ama ben, hepsini geriye istiyorum duygularımın 

Yalnız gecelerimdeki ortaklıkları hiç bozulmasın diye... 

Yazık ki çok yazık, bitiyor geceyle sevişmelerim 

Gündüzün kötülükleri çoktan geldiler, kalbimin kapısına 

Kovalıyorlar gecenin gizemini hırsla, sonsuzluğa 

Patlıyor ruhumda gerçeğin sert ve acı şamarı, buz gibi… 

Ve, sonunda…. 

Bitiyor bir yalnızlık gecem daha, sensiz ve sevgin''siz….. 

(24.11.2005)', 'Gecenin derinliklerinden akıp geliyor hüzünlerim  Rüzgarın sırtında uçuşuyor hayallerim, uzaklaşıyor  Gurubun kızıllığında için için yanıyor...', ARRAY['Türk Edebiyatı','Şiir','Burhanettin Akdağ']::text[], 8.5, '{"poet":"Burhanettin Akdağ","poet_slug":"burhanettin-akdag","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/geceyle-sevismelerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Yar Kollar Beni', 'o-yar-kollar-beni-murat-demir-pq52f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yollar beni yollar beni

Dönmez  yola yollar beni

Gelen vurur giden vurur

Sözde o yar kollar beni

Dört tarafım dolu çakıl

Yol açmama yetmez akıl

Gönül der ki takma, takıl

Özde o yar kollar beni

Demesem de bu çelişki

Anlaşılmaz bir ilişki

Siz söyleyin nasıl iş ki

Közde o yar kollar beni

Ne yapsam da bitmez meyil

Hala bana derler eğil

Bayır, yamaç, batak değil

Düzde o yar kollar beni', 'Yollar beni yollar beni Dönmez  yola yollar beni Gelen vurur giden vurur Sözde o yar kollar beni Dört tarafım dolu çakıl Yol açmama yetmez a...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/o-yar-kollar-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılığı Seçtin', 'ayriligi-sectin-yusuf-onder-bahceci-53jne', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Benim masum sevdiğim,

Derdini söylemedin,

Düşünceliydin, kederliydin,

Gözlerine bakmaya kıyamazdım,

Kimbilir ne derdin vardı,

Biliyordum bana sevdalıydın,

Ama ürkektin, korkaktın,

Sana göre dert olan,

Bana göre dert olmazdı belki,

Belki kıyamadın bana,

Benimde sana kıyamadığım gibi,

Ayrılığı seçtin kaderden,

Bağrına taşlar basıp,

Kutluyorum sevdiğim,

Çünkü sen çok dürüsttün', 'Benim masum sevdiğim, Derdini söylemedin, Düşünceliydin, kederliydin, Gözlerine bakmaya kıyamazdım, Kimbilir ne derdin vardı, Biliyordum ban...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ayriligi-sectin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Damla Gözyaşım / Pişmanlığım', 'i-ki-damla-gozyasim-pismanligim-galip-sinecikli-mlta0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'şimdi 

düşünceler terazisinin tam ortasındayım

kefelerinde

dünü, bugünü ve geleceği tartıp duruyorum

sen bu kefede 

yani pişmanlıklarımı tarttığım yerde 

zerre kadar yer almıyorsun

pişmanlığım sadece incittiklerime 

beni incitenlere değil

işte sırf bu yüzden bile olsa

yerin yok mizanımda

övünç kaynağın olmayacağım senin

son eserim diyemeyeceksin benim için

yıkılışımı görmeyecek, göremeyeceksin

çünkü

senin her darben güçlendirdi beni

şimdi 

hiç olmadığım kadar mutlu

hiç tutunmadığım kadar sıkı sarıldım hayata

bu mutluluğumda da

tutunuşumda da 

sen 

yoksun

sokakta gördüğüm bir köpek bile

senden kıymetli göründü gözüme

nedense bu sabah farkettim

bala konan sinek misali tutulmuştum sana

ne kadar yanılmışım

sen sana dokunanı

üzerine konanı mahvediyormuşsun

sana dokunduğum anda

aslında kendi sonumu hazırlamışım

yanılmışım

ne kadar yanıldığımı belki geç anladım

sen hayatta yaptığım en büyük hatamdın

ama asla pişmanlığım olamazsın

sen olsan olsan

göz pınarımda biriktirdiğim

iki damla yaş olursun

ve biliyor musun? 

ben dün gece iki damla ağladım... 

_______ pişmanlığım bile değilsin 

_______ pişman olunacak şeyin bir değeri olmalı 

_______ benim pişmanlığım 

_______ üzerine basıp geçtiğim güllere...! ! ! 

www.geceyegunaydin.azbuz.com

[email protected]', 'şimdi  düşünceler terazisinin tam ortasındayım kefelerinde dünü, bugünü ve geleceği tartıp duruyorum sen bu kefede  yani pişmanlıklarımı tar...', ARRAY['Türk Edebiyatı','Şiir','Galip Sinecikli']::text[], 8.5, '{"poet":"Galip Sinecikli","poet_slug":"galip-sinecikli","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/iki-damla-gozyasim-pismanligim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uçurt Beni Sevdam', 'ucurt-beni-sevdam-kamil-soylemez-jh4qo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yeri göğü bedeni aldı sevdan

Uçuyorum şimdi  hiç durmadan

Konmak yok yere göğe

Senin sevgin özleminle uçmak düştü cana

Var ise şayet vurulup,hayattan kopmak

Olsun senin sevdanı sırtlanarak

Neyim varki sevginden başka bana

Hiçte umrumda değil

Sadece seni istiyorum

Seni istiyorum gün ve gecelerimde

Tenimde tenin gezsin 

Sessiz sakin sevecence 

Nefesin ensemde

Seviyorum desin kokun

Sinsin nefesime

Gözlerin gözlerime konsun

Öylece dursun

Biz susup,gamzelerin beden dili konuşsun

Tut ellerimi 

Uçurt beni 

Uçurt şuanki uştuğum gibi 

Seviyorum seni seviyorum aşkım

Hiçte geri dönmemecesine

Ne olur sende tut tut beni sinende

Ve gerçek sevgiyle okşa

Başını omzuma yüreğini yüreğime yasla

Baş koydum ilkkez böyle bir sevdaya

Çıktı canım seni ilk tanıdığım günden sonra

Haydi birtanem ne olursun sende sevgini fısılda

Seviyorum seni seviyorum de ve uçurt beni 

Rüzgarda uçurttuğun saçların  gibi

Yoksa ölüceğim özleminden konacağım soğuk topraklara

Haydi aşkım uçurt beni uçurt sarıp teninde sarmala

Ömrüm son bulsun sen tenin,kokun,gözlerin ve kollarında', 'Yeri göğü bedeni aldı sevdan Uçuyorum şimdi  hiç durmadan Konmak yok yere göğe Senin sevgin özleminle uçmak düştü cana Var ise şayet vurulup...', ARRAY['Türk Edebiyatı','Şiir','Kamil Söylemez']::text[], 8.5, '{"poet":"Kamil Söylemez","poet_slug":"kamil-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/ucurt-beni-sevdam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cananıma', 'cananima-alper-kuruk-r51ud', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Resmindeki gibi hep gül 

Neş''eli ol sevgilim,

Aşkınla yanan şu kalbe

Sevginle dol sevgilim.

Kulak ver yıldızlı gecelerde

Beni sessizliklerde dinle,

Vücudum senden ayrıymış ne çıkar? 

Her an ruhum seninle...

Beni yak,beni kahret

Sevginden mahrum etme,

Cennete çıksa yolun

Beni bırakıp gitme.

Resmindeki gibi hep gül

Neş''eli ol sevgilim,

Gönlümün tek Dileği

Emelim ol sevgilim...', 'Resmindeki gibi hep gül  Neş''eli ol sevgilim, Aşkınla yanan şu kalbe Sevginle dol sevgilim. Kulak ver yıldızlı gecelerde Beni sessizliklerde...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cananima-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Anadolu Kokar İken Sevmiştim', 'seni-anadolu-kokar-i-ken-sevmistim-sahin-erturk-11gc0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben seni

Al yazman ile

Şalvarın,yemenin ile

Buram,buram

Anadolu kokar iken

Doğallığınla sevmiştim? 

Kuaför değmemişti

Saçlarına? 

Ruj sürmemiştin

Dudaklarına? 

Parfümü bilmiyordun

O zamanlar? 

Oysa şimdi sen,

Açılmışsın,saçılmışsın

Birşey kalmamış üzerinde? 

Boya ile kapatmışsın

Yok etmişsin güzelliğini? 

Saçların,dudakların

Boya fabrikası gibi? 

Sana neler oldu ZELİHAM

Kime,neden

Niçin özendin? 

OJE li tırnakları

Ne yapayım ben? 

Kaşları alınmış kadını

Nasıl seveyim ben? 

Ben seni

Anadolu kokar iken

Doğallığın ile sevmiştim

Kınalı,nasırlı ellerine

Bayılıyordum ben? 

Saflığın,içtenliğin

Bir başkalıktı benim için? 

Kır çicekleri gibiydin

Katkısızdın,hormonsuzdun? 

Söylermisin ZELİHAM

Söylermisin? 

Şimdi ben senin

Neyini seveceğim? 

Nikotin kokusundan

Parfümden,Alkolden

Nefret ettiğimi

Bilmezmisin sen

Bilmezmisin sen

(29.11.2005-Yeni)', 'Ben seni Al yazman ile Şalvarın,yemenin ile Buram,buram Anadolu kokar iken Doğallığınla sevmiştim?  Kuaför değmemişti Saçlarına?  Ruj sürmem...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/seni-anadolu-kokar-iken-sevmistim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Ve Ben', 'sen-ve-ben-alper-kuruk-skqmj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şu gurbettir beni sana 

Hergün daha çok bağlayan,

Hasrettir acılarla

Gönül yaramı dağlayan.

Duy bir hıçkırık sesi

Sorma kimdir ağlayan...

Sen orada

Ben burada

Ayrılık var arada.

Sen oradan aşkla seslen

Bense şiirle coşayım,

Aşkına eren yollarda

Aç,susuz sana koşayım.

Sen oradan

Ben buradan

Yalvaralım Yaradana,

Ayrılık çıksın aradan

Hasretliği dağ dağ yıkıp

Ayaklarım altına döküp

Sen yârime kavuşayım...', 'Şu gurbettir beni sana  Hergün daha çok bağlayan, Hasrettir acılarla Gönül yaramı dağlayan. Duy bir hıçkırık sesi Sorma kimdir ağlayan... Se...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sen-ve-ben-152-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitti', 'gitti-metin-yalti-cdr2c', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'O kısacık sürede ne çok şey konuşmuştuk 

Göz göze her gelişte keşkeler çoğaltmıştık 

Pişmanlıklarımızla orda suskun kalmıştık 

Teşekkür edip çaya yanımdan kalktı gitti 

Bir bardak çay içimlik bir tanışmamız oldu 

Onda benim gördüğüm özendiğim ömürdü 

Söyleyemedikleri hepsi benim düşümdü 

Geç kalmıştım bu kez de elimi sıktı gitti

İçimde acı vardı sordum durdum kendime 

Bu kadar yıldan sonra döner misin geriye? 

Kabuk bağlı yaramı maskeleyip yüzüme 

Yarım fincan çay gibi beni bıraktı gitti 

 28,11,2005', 'O kısacık sürede ne çok şey konuşmuştuk  Göz göze her gelişte keşkeler çoğaltmıştık  Pişmanlıklarımızla orda suskun kalmıştık  Teşekkür edip...', ARRAY['Türk Edebiyatı','Şiir','Metin Yaltı']::text[], 8.5, '{"poet":"Metin Yaltı","poet_slug":"metin-yalti","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gitti-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dokunmayın Bana', 'dokunmayin-bana-yusuf-onder-bahceci-p6qmp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Saçlarıma aklar doldu gelmiyor,

Gözlerimde fer kalmadı gidiyor,

Acep eller buna neler ne diyor,

Yıllar geçti, ömür bitti gelmedi.

Gizli gizli ağlıyorum bilmiyor,

Kader bize ne düzenler ediyor,

Masum kalbim arada bir tekliyor,

Gidenler hep döndü bir sen gelmedin.

Beni benden değil ellerden sorun,

Şu halime bakıp bakıp ağlarım,

Bu derdin çaresi yoktur bilirim,

Gözlerimde gözlerini görürüm,

Dokunmayın bana içim yanıyor,

Bu yangının külü Arşa çıkıyor,

Baktırdığım fallar hüzün çıkıyor,

Dokunmayın bana hemen ağlarım,

Başıma karalar kara bağlarım,

Yıkıldı sarayım viran bağlarım,

Dokunmayın bana hemen ağlarım....', 'Saçlarıma aklar doldu gelmiyor, Gözlerimde fer kalmadı gidiyor, Acep eller buna neler ne diyor, Yıllar geçti, ömür bitti gelmedi. Gizli gizl...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/dokunmayin-bana-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayram Kokusu', 'bayram-kokusu-reyhan-sak-j6df0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İlk günahını işlediği gün ruhum

Kayboldu bayramların kokusu

Usulca terk edince beni çocukluğum

Sardı birden ölüm korkusu....

                                       

29/11/05', 'İlk günahını işlediği gün ruhum Kayboldu bayramların kokusu Usulca terk edince beni çocukluğum Sardı birden ölüm korkusu....                ...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Sak']::text[], 8.5, '{"poet":"Reyhan Sak","poet_slug":"reyhan-sak","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bayram-kokusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ya - Ya da', 'ya-ya-da-reyhan-sak-fq9d6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ya sıcak bir güneş ısıtsın tenimi 

Ya da karlara bassın ayaklarım

Ya birileri duysun sesimi

Ya da hiç konuşmayacağım....

29/11/05', 'Ya sıcak bir güneş ısıtsın tenimi  Ya da karlara bassın ayaklarım Ya birileri duysun sesimi Ya da hiç konuşmayacağım.... 29/11/05...', ARRAY['Türk Edebiyatı','Şiir','Reyhan Sak']::text[], 8.5, '{"poet":"Reyhan Sak","poet_slug":"reyhan-sak","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ya-ya-da-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aydınlığı Özlüyorum', 'aydinligi-ozluyorum-alper-kuruk-6d6hy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Karanlıklar içinde boğuluyorum

Bir canım var

Gündüzler boyu sakladığım bir can

Ki ölüyor karanlıklar içinde

İçimde doğarken hicran.

Karanlıklar içine gömülüyorum

Yıldız yıldız uzak derinliklerce.

Gönlümde bir kıvılcım aydınlık görüyorum

Aydınlığa yöneliyor gözlerim

Aydınlığı özlüyorum...', 'Karanlıklar içinde boğuluyorum Bir canım var Gündüzler boyu sakladığım bir can Ki ölüyor karanlıklar içinde İçimde doğarken hicran. Karanlık...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/aydinligi-ozluyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şu Bir Bardak Şarapta I', 'su-bir-bardak-sarapta-i-i-brahim-balci-5y31m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çölün sonsuzluğunda bir vahaymış serabın

Yanılsama haz verdi kısa sürse de aşkın

Bu bir bardak şarapta esriklik buldu ruhum

Sen ki ey Peri kızı,kadim bir Alamutsun

Veda,yar dudağından bir katre siyah kandır

Ufukta yiten  güneş,solmuş bir ihtişamdır

Şu bir bardak şarapta hasreti buldu ruhum

Sen ki ey Kraliçe,kadim bir sönmüş korsun

Küllenen ateşinin parlatırken o  korunu

Bir başka aşkmış meğer,şen edermiş ruhunu

Şu bir bardak şarapta,ihanet buldu ruhum

Sen ki ey Semiramis,kadim bir doyumsuzsun', 'Çölün sonsuzluğunda bir vahaymış serabın Yanılsama haz verdi kısa sürse de aşkın Bu bir bardak şarapta esriklik buldu ruhum Sen ki ey Peri k...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Balcı']::text[], 8.5, '{"poet":"İbrahim Balcı","poet_slug":"i-brahim-balci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/su-bir-bardak-sarapta-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hem Of Hem Şükür', 'hem-of-hem-sukur-alper-kuruk-tn1h3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben kafayı çekerim...

Felek duymuş ola ki 

Gel bir de benden çek dedi.

Bir kocaman of çektim

Koca dağlar misali.

O gün bu gün

Ofum yalnız,dağım yalnız,ben yalnız...

Üçümüz hep bir ağız

Of! Of! Of! dedik

Allah geldi aklımıza

Of değil Allah''a şükür dedik...', 'Ben kafayı çekerim... Felek duymuş ola ki  Gel bir de benden çek dedi. Bir kocaman of çektim Koca dağlar misali. O gün bu gün Ofum yalnız,da...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/hem-of-hem-sukur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözler', 'gozler-yusuf-onder-bahceci-wuljg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözlerime baksaydın,

Halimi sen anlardın,

Ayrılığın hüznüyle,

Oturupta ağlardın.

Gülen gözlerine kandım,

Beni seviyor sandım,

Meğer ne cahilmişim,

Kara gözlü sevdiğim.

Gözlerime baksa yârim,

Yüreğimi yaksa derim,

Ondan sonra Allah Kerim,

Biliyorum biliyorum.

Biliyorum biliyorum,

Ben derdimi biliyorum,

Birgün olsun aramadı,

Günden güne eriyorum.

Sevgiyle bakan gözler,

Yüreği yakan gözler,

Yârini eller almış,

O hâla yolları gözler....', 'Gözlerime baksaydın, Halimi sen anlardın, Ayrılığın hüznüyle, Oturupta ağlardın. Gülen gözlerine kandım, Beni seviyor sandım, Meğer ne cahil...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gozler-64-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle Olsun', 'seninle-olsun-suleyman-zaman-tfxp4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Giymiş libasını cicimi cici

Gül kokuşlu teni, dişleri inci

Sevindirir beni, onun gönenci

Yaşam boyu gönenç, seninle olsun

Benim fidanımsın, gonca gülümsün

Avaz, avaz söyler, dudu dilimsin

Beni mest eyleyen, zülfü telimsin

Yaşamca güzellik, seninle olsun

Buğday tenin çeldi, masum tinimi

Geçiremem sensiz, normal günümü

Aştım sana bil ki; garip sinemi

Yaşam boyu sevgi; seninle olsun

Sevmek Zamanım’ın, yaşam iksiri

Sevdiğim bir maral, sanki bir peri

Can alıcı bakar, kahve gözleri

Yaşam boyu aşkın, seninle olsun.

           29.11.2000', 'Giymiş libasını cicimi cici Gül kokuşlu teni, dişleri inci Sevindirir beni, onun gönenci Yaşam boyu gönenç, seninle olsun Benim fidanımsın, ...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Zaman']::text[], 8.5, '{"poet":"Süleyman Zaman","poet_slug":"suleyman-zaman","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/seninle-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanar Elim...', 'yanar-elim-i-brahim-ethem-bingul-h417q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Adını yazmaktan aciz bir sarhoştum

Harflerinin arasında kaybolan 

Aşkı sayfalara sığdıramaz oldum

Yazdırdı, söyletti sevdam...

Sevgimi kendime mi saklamalıyım

Ne mümkün, var mı yapan? 

Denize koşan sevda seliyim

Aşkının yağmurlarıyla çoğalan...

Gözlerinin gönüllü esiriyim

Öpemem, kıyamam, sevmeye

Bilmezsin tutuşur, yanar elim

Dokunamam senin ipek tenine...

www.iebingül.com', 'Adını yazmaktan aciz bir sarhoştum Harflerinin arasında kaybolan  Aşkı sayfalara sığdıramaz oldum Yazdırdı, söyletti sevdam... Sevgimi kendi...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yanar-elim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erken Uyan', 'erken-uyan-rifki-kaymaz-sq155', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Haydi yavrum, güzelim kalk! 

	Minik kuşlar uyandı, bak! 

	Saat çalar:Tik tiki tak...

		Erken uyan! 

		Erken uyan! 

	Uyku bitti, güne yürü,

	Hakka edip teşekkürü.

	Horoz öter: Ü ürü ürü...

		Erken uyan! 

		Erken uyan! 

	Cıvıl cıvıl bir kuş sesi...

	Düşün, mutluluk gölgesi.

	Minarede ezan sesi,

		Erken uyan! 

		Erken uyan!', 'Haydi yavrum, güzelim kalk!  	Minik kuşlar uyandı, bak!  	Saat çalar:Tik tiki tak... 		Erken uyan!  		Erken uyan!  	Uyku bitti, güne yürü, 	...', ARRAY['Türk Edebiyatı','Şiir','Rıfkı Kaymaz']::text[], 8.5, '{"poet":"Rıfkı Kaymaz","poet_slug":"rifki-kaymaz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/erken-uyan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyu Yavrum', 'uyu-yavrum-rifki-kaymaz-gtscn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir gül gibi kokarsın,

	Işıl ışıl bakarsın.

	Güllerden güller derip, 

	Yüreğime akarsın.

		Ninniyle uyu yavrum,

		Dillenip büyü yavrum.

	Rüyalarla el ele,

	Aydede gelsin dile.

	Korkular bir bir dinsin,

	Dikenler dönsün güle...

		Ninniyle uyu yavrum,

		Dillenip büyü yavrum! 

	Kulak ver ki sözüme,

	Uyku girsin gözüne.

	Mutluluk pul pul olup,

	Dökülsün gül yüzüne.

		Ninniyle uyu yavrum,

		Dillenip büyü yavrum!', 'Bir gül gibi kokarsın, 	Işıl ışıl bakarsın. 	Güllerden güller derip,  	Yüreğime akarsın. 		Ninniyle uyu yavrum, 		Dillenip büyü yavrum. 	Rüy...', ARRAY['Türk Edebiyatı','Şiir','Rıfkı Kaymaz']::text[], 8.5, '{"poet":"Rıfkı Kaymaz","poet_slug":"rifki-kaymaz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/uyu-yavrum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meyveden Çocuğa', 'meyveden-cocuga-rifki-kaymaz-gouff', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir dal ucunda küçücük iken,

	Gün gelir büyüyüp, meyve olurum.

	Henüz olgunlaşmadan koparırlarsa,

	Üzüntüden,

	Kahrolurum.

	Öbek öbek toplarlar

	Diğer meyvelerle beni.

	Bekliyorum, bir güzel,

	Bir iyi çocuk

	Tarafından yenilmemi.

	Helal olsun! 

	Afiyet olsun! 

	Yiyen tadımı unutmaz.

	

	Dilerim yedikten sonra beni çocuklar,

	Yaratana teşekkürü

	Unutmaz.', 'Bir dal ucunda küçücük iken, 	Gün gelir büyüyüp, meyve olurum. 	Henüz olgunlaşmadan koparırlarsa, 	Üzüntüden, 	Kahrolurum. 	Öbek öbek toplar...', ARRAY['Türk Edebiyatı','Şiir','Rıfkı Kaymaz']::text[], 8.5, '{"poet":"Rıfkı Kaymaz","poet_slug":"rifki-kaymaz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/meyveden-cocuga-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sordukça Mevlâyı bir eren başa', 'sordukca-mevl-yi-bir-eren-basa-ali-riza-unal-yofyh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ezelde yazılan, gelirmiş başa,

Kadere isyanmı, etmedik haşa,

Bekledik kemâli erdirdik yaşa

Sordukça mevlayı,bir eren başa,

Haya ettik bakmadık, göz ile kaşa,

Saymadık hayrımız,kakmadık başa,

Dinsiz zındık sandılar,tövbeler haşa,

Sordukça mevlayı,bir eren başa başa,

Bu millet düşmüş zurnaya marşa,

Biz diktik gözümüz,arz ile arşa,

Şeytan bile şaşkın, nefsi kargaşa,

Sordukça mevlayı,bir eren  başa.

Bu yollar ıssız giden, aşk ile aşa,

Kılavuz bul menzile,pusulan şaşa,

Sırra sûkut ile geldik, biz bu yaşa,

Sordukça mevlayı bir eren başa', 'Ezelde yazılan, gelirmiş başa, Kadere isyanmı, etmedik haşa, Bekledik kemâli erdirdik yaşa Sordukça mevlayı,bir eren başa, Haya ettik bakmad...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sordukca-mevlayi-bir-eren-basa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olayım', 'olayim-erdem-bozdogan-qjudt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Turap olayım ayağının altına,

Harap olayım aşkının yoluna,

Şarap olayım içtiğin suyuna,

İstersen bir ömür kölen olayım.

Kara gözlerine olayım sürme,

Güzel sözlerine olayım cümle,

Seven yüreğine olayım çile,

İstersen yolunda ölen olayım.

Sarıcoğlan der ki; Delin olayım,

Gerdanın altında benin olayım,

Dilersen her zaman senin olayım,

Alnına yazılan kelam olayım.

Erdem Bozdoğan, Almanya 1989

sarıcaoğlan', 'Turap olayım ayağının altına, Harap olayım aşkının yoluna, Şarap olayım içtiğin suyuna, İstersen bir ömür kölen olayım. Kara gözlerine olayı...', ARRAY['Türk Edebiyatı','Şiir','Erdem Bozdoğan']::text[], 8.5, '{"poet":"Erdem Bozdoğan","poet_slug":"erdem-bozdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/olayim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bülbüller Ötsede Gülleri Sağır 2', 'bulbuller-otsede-gulleri-sagir-2-erdem-bozdogan-q46mh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'NESİNİ ÖVEYİM GURBETİN SANA,

HAVASI DEĞİŞİK SUYU DEĞİŞİK.

HAKSIZ SAYILIRSIN HAKLI OLSANDA,

YORDAMI DEĞİŞİK YOLU DEĞİŞİK.

HALDEN ANLAYANI BULAMAZSIN Kİ,

DİNİNE HUYUNA UYAMAZSIN Kİ,

UYARSAN DOĞRUYA VARAMAZSIN Kİ,

TÖRESİ DEĞİŞİK, HUYU DEĞİŞİK.

SESİN KISIK ÇIKAR İSTERSEN BAĞIR,

BAĞIRSANDA BUNLAR İŞİTİR AĞIR,

BÜLBÜLLER ÖTSEDE GÜLLERİ SAĞIR,

DUYGUSU DEĞİŞİK, GÜLÜ DEĞİŞİK.

YERLİSİ NEŞELİ YADI KEYİFSİZ,

HOR GÖZ İLE BAKAN YÜZLER SEVİMSİZ,

KİM EVLİ KİM BEKAR BELLİ BELİRSİZ,

CANANI DEĞİŞİK CANI DEĞİŞİK.

KENDİDE İNANMAZ NASİHAT EDER,

KIÇINI AÇIPTA MEDENİYİM DER,

BİR MALI BİR DEĞİL ÜÇ-BEŞ KİŞİ YER,

NAMUSU DEĞİŞİK, NAMI DEĞİŞİK.

BÜYÜK BİR ŞEY GİBİ ATARLAR HEP POZ,

BOZDOĞAN''A GÖRE TEKNİĞİ BİR KOZ,

YABANCIYA DÜŞMAN İNSANI BOZ BOZ,

GURURU DEĞİŞİK, CİNSİ DEĞİŞİK.

Erdem Bozdoğan,Almanya 1990

                                                  SARICAOĞLAN', 'NESİNİ ÖVEYİM GURBETİN SANA, HAVASI DEĞİŞİK SUYU DEĞİŞİK. HAKSIZ SAYILIRSIN HAKLI OLSANDA, YORDAMI DEĞİŞİK YOLU DEĞİŞİK. HALDEN ANLAYANI BUL...', ARRAY['Türk Edebiyatı','Şiir','Erdem Bozdoğan']::text[], 8.5, '{"poet":"Erdem Bozdoğan","poet_slug":"erdem-bozdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bulbuller-otsede-gulleri-sagir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kartanem', 'kartanem-kamil-soylemez-qbks1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Öyle bir mevsim gelmiş

Dışarıda kar yağıyor

Sevgililer kucaklaşıp

Karda ayak sevda dağıtıyor

Bir bedende kar atıyor

Yanar söner ışıklar

Göz açıp kapamalarımda

Bana yürek satıyor

Biricik sevdiğim

Sense uzaksın gözden

Gönüldeyse sıcak ve yakın

İşte şimdi bir düşün

Kar altında sende kar tanesi yakalıyorsun

Elinle bedeninle gözünle istediğin karad çok

Kar tanesi yakalıyorsun

Yakaladıkların senin sevgin olsun

Yakalayamadıklarınsa  benim 

Şimdi birkez daha düşün 

Ve fısılda kulağıma seviyorum diye bana', 'Öyle bir mevsim gelmiş Dışarıda kar yağıyor Sevgililer kucaklaşıp Karda ayak sevda dağıtıyor Bir bedende kar atıyor Yanar söner ışıklar Göz ...', ARRAY['Türk Edebiyatı','Şiir','Kamil Söylemez']::text[], 8.5, '{"poet":"Kamil Söylemez","poet_slug":"kamil-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kartanem-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhanetin Laneti', 'i-hanetin-laneti-kadir-albayrak-mtz8u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir şiirsin sonuçta, ya dua ya intizar

Bazen satır da isim bazen zevksiz bir bahar

Sana dost değil miydi düş-te melekler bile

Gönlüm hala secde de nefesim de isyan var

Bazen gökte kuşaksın yedi renkli bir alem

Ne yazar belli değil gider gelir bir kalem

Hasret bağı üstüne atılmış düğüm gibi

Aşk pınarı başında yudum yudum bir sitem

Özlem olup yağarsın buluttan damla damla

Bir zerre nasibi yok “umut” çorak bir tarla

Bazen sabah güneşi bazen fecri akşamın

Ortasında bir yerde vuslat saklı pusu da

Karanlıkta bir çığlık bazen derin sessizlik

Bazen yüce bir tepe bazen korkunç derinlik

Zaman diye geçmişin sireni öttüğünde

Ömür manadan kaçar ölüm bile rezillik

Sokakta ayak sesi gölgesinde yankılar

Seda verir toprağın altından ölü canlar

Nihayet acıların demlendiği an gelir

Beden de bir sarsıntı depremdedir günahlar

Bir avuç toprak ile haşrolacak vücudun

Hem de gözü önünde sevgisiz bir güruhun

O öyle bir vakit ki mizan da denge ister

Şaşırdığın cehennem vebalidir gururun

Küllerin altındasın beyhudedir saklanış

Tükettin bir hayatı neye yarar bu kaçış

Mağfiret için bile zamanın yetmeyecek

İhanetin laneti, isyanıdır haykırış! ...', 'Bir şiirsin sonuçta, ya dua ya intizar Bazen satır da isim bazen zevksiz bir bahar Sana dost değil miydi düş-te melekler bile Gönlüm hala se...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ihanetin-laneti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değişik', 'degisik-erdem-bozdogan-lor6r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'NESİNİ ÖVEYİM GURBETİN SANA,

HAVASI DEĞİŞİK SUYU DEĞİŞİK.

