INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cennet Yolcusu', 'cennet-yolcusu-suleyman-tunc-ta26q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir tabut geçti pencerenin önünden

Hayal meyal sağanak yağmur gibi.

Rabbine kavuşmak için,

Acelesi vardı belli...! 

O bayrağa, bayrak O''na sarılmış,

Kan kardeş olmuşlar.

Sordum: ''''Kim bu geçen cennet yolcusu? ''''

Dediler:''''Karşıki okulun öğretmeni,

Yedinci bölüğün Hayri Asteğmeni.''''

    Bir yiğit geçti,

Peşinde direği yıkılmış dört öksüz çocuk....

Üçü erkek, biri kız.

Hilal kız okşadı, sevdi tabutu örgülü saçlarıyla.

Birisi emekledi kapı eşiğinde,

Anlamsız seyretti olan biteni.

Ömer resmini tuttu.

Diğeri dede kucağında,

Şekerini verdiler, babasını unuttu! ...

    Bir yiğit geçti,

Cansız ve hareketsiz.

Hükmedemedi bu defa kaldırımlara,

Diğer insanlar gibi.

Çünkü postalları yok! ...

Çorapları yok! ...

Ayakları yok! ...

Çünkü kopan bacakları yanı başında.

    Bir şehit geçti,

Yazmayı öğrettiği eller üstünde.

Bir kalem, bir kitap, bir defter gibi.

İlk durak cami avlusu.

Selvi gölgesinde kılındı namaz.

Okul kapısında dua,...

Edildi giderken son yolculuğa.

Bir şehit geçti pencerenin önünden,

Takılmış ardına binlerce yiğit! ...

Dayanabilirmi bu ayrılığa bilinmez,

Yaşmaklı kadın.

Bağıracak, haykıracak, boşalacak, dolacak,...

Ne mutlu ona ki,

Birazdan şehit anası olacak! ...

Bir yiğit geçti pencerenin önünden,

Uğurlandı,ü ranzalı koğuştan mermer koğuşa.

Titredi altında saygıdan toprak.

Haydi git artık! Git! Güle güle git! ...

Burası ayrılık yeri.

Acele et! Bekletme,

Cennette seni bekleyenleri.

      Zehra Tunç

   (Babasının çırağı)', 'Bir tabut geçti pencerenin önünden Hayal meyal sağanak yağmur gibi. Rabbine kavuşmak için, Acelesi vardı belli...!  O bayrağa, bayrak O''na s...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Tunç']::text[], 8.5, '{"poet":"Süleyman Tunç","poet_slug":"suleyman-tunc","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/cennet-yolcusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Güzel Sevdâlar', 'en-guzel-sevd-lar-timur-i-likan-52d1x', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sahneye Emel Sayın kadar başka kim yakışır

Televizyonda onu gören âdetâ ekrana yapışır

Her seven yürek onun sevgisinden bir parça taşır

En güzel sevdâlar hep onunla yaşanır

Engin semâlara yükselir büyüleyici sesi,

Okşar rûhumuzu

Dinledikçe dinleyesi gelir insanın,

Gönlümüzde kalır tadı tuzu

Onun sevgi dolu sıcacık yüreği,

Eritiverir karı buzu

Kederli şarkıları eşliğinde,

Gözlerimizi sarar hasret buğusu

Bu dünyaya başka bir Emel Sayın

Gelmedi gelmeyecek

Ona akan sevgi seli,

Hiç dinmedi dinmeyecek

Dantel gibi işlediği şarkıları,

Hiç ölmedi ölmeyecek

Yüreğimize nakşettiği adı,

Hiç silinmedi silinmeyecek

(29 Kasım 2005/ İstanbul) 

Timur İlikan', 'Sahneye Emel Sayın kadar başka kim yakışır Televizyonda onu gören âdetâ ekrana yapışır Her seven yürek onun sevgisinden bir parça taşır En g...', ARRAY['Türk Edebiyatı','Şiir','Timur İlikan']::text[], 8.5, '{"poet":"Timur İlikan","poet_slug":"timur-i-likan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/en-guzel-sevdalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annem', 'annem-ferit-gursoy-jm02a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yaş ilerlese de 

Büyümedim değil mi hala 

Çocuğum hala…

Evlendim anne

Çocuklarım oldu

Torunların var anne.

Koşturmuyorum eskisi gibi anne

Küçükken de terlemezdim

Sen kabul etmesen de

Büyüdüm anne

Evde yemek de pişiyor

Kirlilerim de yıkanıyor 

Hala erken yatıyorum

Üstümü açmıyorum 

Erken kalkıyorum anne

Hastalanmıyorum ama

Şimdi sen bunu duyunca 

Hastayım sanıp üzüleceksin 

Yemin anne iyiyim

Nane limon içiyorum hastalandığımda 

Mendil de taşıyorum yanımda

Ördüğün kazak hala içimde

Sıcacığım anne

Kokunu özledim 

Elinle başımı okşayışını

Osmanlı tokadını bile…

Anne

Sesini duyar gibiyim

Her eve geç gelişimde

Kapıda seni göreceğim diye

Ürkekliğin üzerimde

Elimi bile kanatmayacağım anne

Ama bana söz ver 

Bana acını göstermeyeceğine 

Beni bırakıp gitmeyeceğine

Arkandan ağıtlar yaktırmayacağına

Yetim bırakmayacağına

Toprağa anne diye sarılıp ağlatmayacağına

Söz ver anne

Söz ver.

                                                       26/11/2005', 'Yaş ilerlese de  Büyümedim değil mi hala  Çocuğum hala… Evlendim anne Çocuklarım oldu Torunların var anne. Koşturmuyorum eskisi gibi anne Kü...', ARRAY['Türk Edebiyatı','Şiir','Ferit Gürsoy']::text[], 8.5, '{"poet":"Ferit Gürsoy","poet_slug":"ferit-gursoy","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/annem-120-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hz. LUT (AS)', 'hz-lut-as-abdullah-yasar-erdogan-d2uvu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '(Kitap verilen 8. Peygamber)

            Hz.  LUT    (AS) 

Hz. Lut, İbrahim’in amca oğlu,

İbrahim’e ilk biat eden oydu.

Hz. Lut asla putlara tapmamıştı,

İmanın sarsılmaz kalesi oldu.

Hz. Lut yürüdü Hz. İbrahim ile,

Doğduğu yerlerden çıktı hicrete.

Önce Harran’a sonra Şam’a vardı,

Hz. Lut, Sodom’a gitti tevhide.

Bir sinek dağıttı Nemrud yurdunu,

İbrahim yanına aldı nurunu.

Sâre validemiz ve Hz. Lut ile,

Yurt edindiler Filistin-Sodom’u

Hububat ve meyvede güzel belde,

Orda olan olmazdı başka yerde,

Sodom ve Gomore denir oraya,

Lakin azmışlardı putperestlikte.

Şeytan bu beldeyi etti perişan,

Dedi; livatadır size yakışan.

Eğer livata yaparsanız sizler,

Yurdunuza olmaz asla yaklaşan.

Sodom halkı, azgınlığın içinde,

Zelil sapkınlıkta, erkek erkekle,

Livatacılık çıkmıştı ayyuka,

İnanmadılar Hz. Lut peygambere.

Livata yapmayan küçümsenirmiş,

Hatta o masumlar tehdit edilirmiş.

İşte böyle azgın bir topluluğa,

Lut Peygamber olarak gönderilmiş.

İmana davet etti azgınları,

İnsanlığa uymazdı yaptıkları,

Hz. Lut, gece-gündüz etmişti davet,

Doğru biliyorlardı yanlışları.

Bunlar insanlığı kaybetmişlerdi,

Yolculara da eza etmişlerdi.

Sureten insan, ruhen hayvan olmuş,

Kadın değil, erkeği sevmişlerdi.

Hz. Lut ki, herkese etmişti davet,

Eşi ve kızından geldi icabet.

Derken vefat etti O’nun hanımı,

Kızları imanda kaldı bereket.

Sodom’da yeniden evlendi Hz. Lut,

Bu kadınında özünde çıktı put.

Çok söyledi, Hakk’a tabi ol diye,

Sonunda davetten vazgeçti Hz. Lut.

Sodom halkı, Hz. Lut’u kovun dedi,

Bu hal Allah’ın azabını çekti.

Melekler geldi insan suretinde,

Hz. Lut’a Hak azabı bildirdi.

Lut, misafirlere ikramda iken,

Evi kuşattı binlerce kadem,

Misafirleri ister, azgın güruh,

Telaşa kapılmakta Lut Peygamber.

Gelenlerden biri Hz. Cebrail’di,

O’na kapıyı açmasını söyledi.

Cebrail bir avuç aldı kum,

Nadanlara attı görmedi gözleri.

Ey Lut! Biz Allah’ın elçileriyiz,

Biz bu kavmi helakla görevliyiz,

Gecenin bir kısmında yürüyüp git,

Kurtulacak olan da sadece siz.

Hz. Lut; iki kızını alıp gitti.

Gün doğarken korkunç ses işitildi.

Hz. Cebrail Sodom ve Gomore’de,

Yerin altını üstüne getirdi. 

Gökten geldi insan adetince taş,

Kanlar içinde kaldı binlerce baş.

Her taşta yazılı bir kafir ismi,

Sahibini buldu gökten gelen taş.

O korkunç sahne arşı titretirken,

Sodom halkı göklere savrulurken,

O kadın; vah kavmim diye bağırdı,

Son nefesini kafirce verirken.

Şimdi o yer dünyanın alçak yeri,

İçine aldı azgın kâfirleri.

Ölü Deniz, Lut Gölü de denir,

Yaşamaz gölde balık ve benzeri.

Lut, kızlarıyla vardı İbrahim’e,

Ne olduğunu söyledi kendine.

Böylece azgın kavimde silindi,

İnanmayan baksın Kur’an-ı Kerim’e

Lutilik, şimdi meslek sayılmakta,

Pis işi yapan da hoş anılmakta,

Sodom’un akıbetinden habersiz,

O belaya davet çıkarılmakta.

Uyan ey insan, yaşantın da yalan,

Geriye de  iyi bak var mı kalan? 

Sakın bana musibet gelmez deme,

Öğüt alıver uyarıcılardan.

Her türlü pislik, seni üzmelidir,

Tez elden İlâhi yola girmelidir.

Yoksa akıbet-ül hüsrandır hayat,

İnsan varlık  amacını  bilmelidir. 

Sodom: Şezum

Gomore: Omore

Kadem: Ayak

Nadan:  Haddini bilmez, kaba, cahil.

Şair: Abdullah Yaşar Erdoğan', '(Kitap verilen 8. Peygamber)             Hz.  LUT    (AS)  Hz. Lut, İbrahim’in amca oğlu, İbrahim’e ilk biat eden oydu. Hz. Lut asla putlara...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":99,"source_url":"https://www.antoloji.com/hz-lut-as-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Zamanın İlleti', 'bu-zamanin-i-lleti-hasan-ulusoy-el4mq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu Zamanın İlleti

Gecelerde ay derdine yıldızların yanışı

Kirlenen kumaşlara desen olan yaşlar var

Can bilmeyen hayata, camdan mamül gönüller

Kaç bağıra basılan, nice gamsız taşlar var

Arılar yurt bilmezse, kovanı akrep sarar

Arıların yağması, farenin işine yarar

Kayalar su dökerdi, bayram yeri boz toprak

Tırpan önünde seken, başaklarda bereket

Dalında şarkı söyler böceklerle her yaprak 

Dik başlı koç yiğitler, Mevla’ya açık eller

Saf tutan müminlerin, mabede sıralanışı

Her gönülde açılır billur benizli güller

Ağıtların gurbeti, gam bilmeyen gönüller

Çıldıran gecelerde ağızlarda leş kokar

Lif lif olmuş sevdalar, saklanacak yurt arar

Gönüllerin gönülsüz gönüllere yanışı

Ak perçemli güzeller, koç bakışlı mert arar.

Bağlanmış hardallara, bahtın döver bülbüller. 

Hanelerde büyük yok, huzursuz evde yatar

Dört atanın hakkını, zamana kurban ettik

Merhametsiz vicdanlar, dünya hırsıyla yanar

Nefislerin şehvete, kapılıp aldanışı

Asır fitne pazarı, öfke alan kin satar

Kırılmış hamiyetli, bereket yüklü eller.

Hep yokuşlara yönelen, yoların şaşkınıyım

İnandığım değerler, çelik çomak oyunu

Vicdanıma kan döker, merhem bilmez yaralar

Aslanların itlere inanıp aldanışı

Bu zamanın illeti marazı acı vermez

Vicdan kördür, izan yok, kimse kendini görmez', 'Bu Zamanın İlleti Gecelerde ay derdine yıldızların yanışı Kirlenen kumaşlara desen olan yaşlar var Can bilmeyen hayata, camdan mamül gönülle...', ARRAY['Türk Edebiyatı','Şiir','Hasan Ulusoy']::text[], 8.5, '{"poet":"Hasan Ulusoy","poet_slug":"hasan-ulusoy","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/bu-zamanin-illeti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eğitim, Öğretim Olsun Bir de Amaç / Öğretmenler Günü', 'egitim-ogretim-olsun-bir-de-amac-ogretmenler-gunu-sevinc-kavuk-rs5eq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Görev bilincinde yorulma sakın

Bu vatanda her hizmete minnet

Nice insanlıklar yaşadı

Nice insanlıklar varolacak gücünde

Uyanacak nice gençlikler uğruna

Hep fedakarlık bulmuştur kazanç

Bu vatan fedakarlıklarla bağışlandı işte

Yine fedakarlıkla yaşayacak ancak…

İyi ki varsın fedakar yürek! Hep varoluşlara ol emek! 

Varsın acıtıyor olsun nankörlük yığışımları

Bir tek an bir ömre bedel değerinle

Seni karşılayacak yaşam sever ruhlar olacak

Oradan da hikmetinde yine bol ol

Bu vatan o hizmetine de kalacak layık

Eğitici ruh, öğretici bilinç hakimliğine

Bu vatan bağımsızlığına baş koyanlar gibi

Fedakarlıktır yine öğretmenlik

Yoksulluk bilmezlik, bağımsızlık uğruna

Tüm bilinçselliktir 

Eğitim, öğretim her alanda buna amaç

Elitler birliği her alanda oluşsun

Ki, yüreğine ferahlıklar sunulsun

Acı ise acıya, hüzün ise hüzne

Her bedelde özgürlüğe merhaba! 

Eğitim, öğretim edindiğim bir de amaç

Bu Cumhuriyetimin genç kalışı olacak

Öğretmenler günü kutlu olsun! 

Vatan ve yavrularımız mutlu olsun! 

24 Kasım 2005  Perşembe 18.00', 'Görev bilincinde yorulma sakın Bu vatanda her hizmete minnet Nice insanlıklar yaşadı Nice insanlıklar varolacak gücünde Uyanacak nice gençli...', ARRAY['Türk Edebiyatı','Şiir','Sevinç Kavuk']::text[], 8.5, '{"poet":"Sevinç Kavuk","poet_slug":"sevinc-kavuk","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/egitim-ogretim-olsun-bir-de-amac-ogretmenler-gunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Islak MAVİ', 'islak-mavi-atahan-cakir-abantli-ywyc7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerinde azgın denizler sakinleşiyor

Mendirek oluyor o güzelim kirpiklerin

Denizler mavi ötesi renge dönüşüyor

En anlatılmazı oluyor ıslak mavilerin.

Bıkmam usanmam hep böyle bak gözlerime

O muhteşem denizlerinde kaybolup gideyim

İster meltemle ister kasırgayla gir bedenime

Parça parça eyle ıslak maviyle birleşeyim.', 'Gözlerinde azgın denizler sakinleşiyor Mendirek oluyor o güzelim kirpiklerin Denizler mavi ötesi renge dönüşüyor En anlatılmazı oluyor ıslak...', ARRAY['Türk Edebiyatı','Şiir','Atahan Çakır Abantlı']::text[], 8.5, '{"poet":"Atahan Çakır Abantlı","poet_slug":"atahan-cakir-abantli","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/islak-mavi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanlış', 'yanlis-atahan-cakir-abantli-v0mdd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Doğru insanların en kötü yanı

Zaman zaman bu hallerinden  şikayet edip,

Bu şikayetlerinin pek çok insan tarafından

Destekleniyor olmasıdır.', 'Doğru insanların en kötü yanı Zaman zaman bu hallerinden  şikayet edip, Bu şikayetlerinin pek çok insan tarafından Destekleniyor olmasıdır....', ARRAY['Türk Edebiyatı','Şiir','Atahan Çakır Abantlı']::text[], 8.5, '{"poet":"Atahan Çakır Abantlı","poet_slug":"atahan-cakir-abantli","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yanlis-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uykusuzluğum', 'uykusuzlugum-atahan-cakir-abantli-i8oem', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gün olur olur uykularım olmazdı

Karanlıklar artırırdı yalnızlığımı

Gönlüm el açar bulutlar ağlardı

Yağmurlar ıslatırdı korkularımı.

Dağ başlarında çoban ışıkları

Korkuya kafa tutardı her an

Kocamış kurtların tek umutları

Körpe kuzulardı anasından ayrılan.

Sarp kayalıklarda tüneyen kartallar

Aldıklarında et kokusunu uzaktan

Havalanıp leyi bayında dolanırlar

Sonsuz bir zevk alırlardı parçalamaktan.

Uykusuzluğumun bittiği günlerde

Karanlıkların tahtı yıkılırdı

Dostluğu tanırdım gördüklerimde

Korku,  sevgisizlik uzaklarda kalırdı', 'Gün olur olur uykularım olmazdı Karanlıklar artırırdı yalnızlığımı Gönlüm el açar bulutlar ağlardı Yağmurlar ıslatırdı korkularımı. Dağ başl...', ARRAY['Türk Edebiyatı','Şiir','Atahan Çakır Abantlı']::text[], 8.5, '{"poet":"Atahan Çakır Abantlı","poet_slug":"atahan-cakir-abantli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/uykusuzlugum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidene', 'gidene-tunahan-ermihan-2jmgl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Koyu kahve gözlerin misali

Koyu yalnızlıklar içinde hasret çekiyor yürek

Haberin olsun

Başta sanmıştım ki sadece giden sensin

Yanılmışım

Çok geçmedi üzerinden anladım

Önce sen gittin

Ardından tüm anılar ve mutlu umutlar

Ve son olarak da hayata yenik düşmüş dostluklar

Sen bir baraj kapağıydın hayatımda

Yalnızlıklarımı ve korkularımı tutan

Çok önemli ve bir o kadar da riskli bir kapaktın

Açılmazsın sanmıştım

Yanılmışım

Sen açıldın ve kapıldın akıntıya

Ardından da senden arta kalacak ne varsa

Hepsi peşinden süzülmeye başladı

Şimdi gecenin koynunda

Kokuna hasret çeken duyularımı bastırmak için

Rüyalara sığınsam da nafile

Yalan dolu ayrılıklara kurban oldu sevdamız', 'Koyu kahve gözlerin misali Koyu yalnızlıklar içinde hasret çekiyor yürek Haberin olsun Başta sanmıştım ki sadece giden sensin Yanılmışım Çok...', ARRAY['Türk Edebiyatı','Şiir','Tunahan Ermihan']::text[], 8.5, '{"poet":"Tunahan Ermihan","poet_slug":"tunahan-ermihan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gidene-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceler', 'geceler-kadir-albayrak-nee4l', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Karanlık geceye ışık yakışmaz

Kasveti başkadır hasreti başka

Gönül de ateşe duman yakışmaz

Minneti başkadır şiddeti başka

Renklerin gözü kör hayaller sultan

Geceler giymiştir simsiyah kaftan

Üstünde yıldızlar pırlanta taştan

Güftesi başkadır bestesi başka

Yüreğin çoştuğu haz-dır geceler

Teline vurduğu saz-dır geceler

Ayazı soğuğu yaz-dır geceler

Gelişi başkadır gidişi başka

O ''meshur siyahlık'' hal-i muttasıl

Bir sessiz hanende sazende fasıl

Nasıl da yakıyor gönlümü nasıl

Katranı başkadır zifiri başka

Muhayyel ne varsa gönl-ü ücrada

Sefası acısı hep bir arada

Hikmet-i sebebi vefasız yar da

Şulesi başkadır sinesi başka', 'Karanlık geceye ışık yakışmaz Kasveti başkadır hasreti başka Gönül de ateşe duman yakışmaz Minneti başkadır şiddeti başka Renklerin gözü kör...', ARRAY['Türk Edebiyatı','Şiir','Kadir Albayrak']::text[], 8.5, '{"poet":"Kadir Albayrak","poet_slug":"kadir-albayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/geceler-121-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'G i t t i...', 'g-i-t-t-i-atahan-cakir-abantli-mfg0p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gitti…

Tüm eziyetine çilesine rağmen gitti.

Bir gün elbet dünyayı terk edecek olan

Ben sen o gibi.

Bir damla gözyaşı,

Bir yutulmaz lokma bıraktı geride

Umut ile özlem ile baktık

Her seferinde yollara, ama; 

Hasretinin bitişi  hep çilenin gelişi oldu

Yine sonunda.', 'Gitti… Tüm eziyetine çilesine rağmen gitti. Bir gün elbet dünyayı terk edecek olan Ben sen o gibi. Bir damla gözyaşı, Bir yutulmaz lokma bır...', ARRAY['Türk Edebiyatı','Şiir','Atahan Çakır Abantlı']::text[], 8.5, '{"poet":"Atahan Çakır Abantlı","poet_slug":"atahan-cakir-abantli","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/g-i-t-t-i-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soruların sorunların da', 'sorularin-sorunlarin-da-necibe-sucuoglu-4d2u1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Soruların sorunların da,

Dertlerin düşüncelerin de,

A dan Z ye bütün olumsuzlukların da,

Hatta içine ettiğimiz dünyanın da

Anasını satayım diyorum; 

Satamıyorum,

Yok ki bir alan.', 'Soruların sorunların da, Dertlerin düşüncelerin de, A dan Z ye bütün olumsuzlukların da, Hatta içine ettiğimiz dünyanın da Anasını satayım d...', ARRAY['Türk Edebiyatı','Şiir','Necibe Sucuoğlu']::text[], 8.5, '{"poet":"Necibe Sucuoğlu","poet_slug":"necibe-sucuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sorularin-sorunlarin-da-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anamı Koydum Bağrıma', 'anami-koydum-bagrima-atilla-guler-rz2u4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'anamı koydum bağrıma

taçlar ördü başıma dualarıyla

yıldızlara dokunup dilek tuttum

ak düşmüş saçlarına bağladım bezleri rengarenk

üstünü örttüm masumiyetin sevgiyle

umutlarımı verdi ellerime

sımsıcak

anamı koydum bağrıma

bir ninni dolandı dilime

danayı kovamadı bostancı

ne uyudum ne büyüdüm

küçüldüm

küçüldüm

bir masal düştü bulutlardan kucağıma

dokundu değneği ile iyilik perisi

yüreğime kondu beyaz güvercin

hayatı kokladım koynunda

kocaman öpücükler damga vurdu böğrüme

direndim

anamı koydum bağrıma

dünyaya karşı geldim', 'anamı koydum bağrıma taçlar ördü başıma dualarıyla yıldızlara dokunup dilek tuttum ak düşmüş saçlarına bağladım bezleri rengarenk üstünü ört...', ARRAY['Türk Edebiyatı','Şiir','Atilla Güler']::text[], 8.5, '{"poet":"Atilla Güler","poet_slug":"atilla-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/anami-koydum-bagrima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Yoksun Anne (Ansızın Anne)', 'sen-yoksun-anne-ansizin-anne-i-brahim-nazim-ulker-ktfpb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Anne ansızın sen düştün gözlerime,

Yine sen içerime...

Anne göz yaşlarım artık Fırat''a karışıyor,

İçimde ki yagınla Munzur bile eriyor.

Ruhum zindanlarda daralıyor

Sen yoksun anne...

Sensizliğin sekizyüz ondokuzuncu gününde,

Bilmem kaç bininci saatindeyim...

Yitirilmekteyim, bitirilmekteyim,

Ölmekteyim ansızın anne...

Ne yar görür gözüm ne de kâr,

Her geçen gün yüreğime bir mıh çakar,

Erzincan''dan, Kemah''tan trenler kalkar,

Ben yokum içlerinde, sen yoksun anne...

Gece tenhileşince,

Geceye hüzün düşünce,

Velhasıl yangınlar ciğerime düşünce,

Ebedi olur sanki gece anne...

Soframda biraz zeytin var,

Biraz peynir ve çay.

Onlar dahi olur zay,

Sen olmayınca anne...

Ben gecelerden etsemde feragat,

Onlar bırakmıyor fakat,

Bende ki bu karabaht

Beni bırakır mı anne? 

Sen olaydın yanımda,

Ben yanaydım her saniye.

Sen olaydın yanımda,

Ben yine mahkum olaydım gecelere...

Deli yaşım,

Hoyrat bakışım,

Asi küheylanlığım,

Bir anda bitti anne... 

Ezanlar okunur; 

Namaz kılarım,

Nur yüzün aklıma gelir,

Secdeye akar göz yaşlarım anne... 

Anne ansızın sen düştün gözlerime,

Yine sen içerime. 

Sensizliğin sekizyüz ondokuzuncu gününde,

Bilmem kaç bininci saatinde; 

Göz yaşlarım artık Fırat''a karışıyor anne.

Dayanamıyor yangınıma Munzur bile,

Tükenmekteyim,ölmekteyim anne...

28/11/2005-Salı

İbrahim Nazım Ülker', 'Anne ansızın sen düştün gözlerime, Yine sen içerime... Anne göz yaşlarım artık Fırat''a karışıyor, İçimde ki yagınla Munzur bile eriyor. Ruhu...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Nazım Ülker']::text[], 8.5, '{"poet":"İbrahim Nazım Ülker","poet_slug":"i-brahim-nazim-ulker","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/sen-yoksun-anne-ansizin-anne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Adı Gül Olsaydı (Gerçek Aşkı Yine Onunla Anlat)', 'askin-adi-gul-olsaydi-gercek-aski-yine-onunla-anlat-i-brahim-nazim-ulker-gp9bp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gül bir çiçeksindir.

Bazen yeryüzünde bir melek,

Bazen olursun sekarat-ı mevt,

Her an alemimsim ve bir cennet.

Gül bir sevgimiz vardır sana; 

Kırmızı rengin gibi sıcak,

Bir ateş ki daha da artacak... 

Gül bir aşkımız vardır; 

Mavi rengin kadar nadir,

O kadar da yürekten ve ilahidir...

Gül bir sevdamız saklıdır; 

Yüreğimizde siyahın gibi karadır,

İçimizde, ta ruhumuzda bir yaradır...

Gül duygularımızın saflığı,

Beyazında saklı,

Bilemezsin sensizliğin karanlığını...

Gül bir çiçeksindir,

Bazen yeryüzünde bir melek,

Bazen olursun sekarat-ı mevt,

Her an alemimsin ve bir cennet...

Bu günde adın Gül olsun,

Ama sen yoksun! 

Hiç olmadın ki,

Yine belde-i hayal gibi...

29/11/2005 Saat:9:24', 'Gül bir çiçeksindir. Bazen yeryüzünde bir melek, Bazen olursun sekarat-ı mevt, Her an alemimsim ve bir cennet. Gül bir sevgimiz vardır sana;...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Nazım Ülker']::text[], 8.5, '{"poet":"İbrahim Nazım Ülker","poet_slug":"i-brahim-nazim-ulker","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/askin-adi-gul-olsaydi-gercek-aski-yine-onunla-anlat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanımda Yoksun', 'yanimda-yoksun-nurten-tarim-enjmu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nazar değdi sevgimize

Seni sensiz yaşıyorum

Zühre yıldızım

Kalp ağrım

Kader bağım

Aşka susadı kalbim

Sessizliğin çığlığı sardı bedenimi

Gökkuşağı taç oldu 

Yagmur gözyaşımı kıskandı

Kokun tenimde kaldı

Emanet miydi sevgin

Duygularım kırık cam parçası

Yüreğim paramparça

Evliyan oldum bir tanem

Sen yüreğimdeki tahtımdasın

Yalnızca yanımda yoksun

Yanımda', 'Nazar değdi sevgimize Seni sensiz yaşıyorum Zühre yıldızım Kalp ağrım Kader bağım Aşka susadı kalbim Sessizliğin çığlığı sardı bedenimi Gökk...', ARRAY['Türk Edebiyatı','Şiir','Nurten Tarım']::text[], 8.5, '{"poet":"Nurten Tarım","poet_slug":"nurten-tarim","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yanimda-yoksun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum (Ya Rabbi)', 'seni-seviyorum-ya-rabbi-i-brahim-nazim-ulker-ymp6b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yusuf''un kuyusunda,

İbrahim''in nârında,

Eyüb''ün sabrında,

Mevlânın aşkında,

Seni Seviyorum...

Batan Güneşin,doğan Ay''ında

Her bir yıldızında,

Sicim gibi yağan yağmurunda,

Çöl sıcağında,

Seni seviyorum.

Sallallahü Aleyhi Vesselem''in Ay yüzünde,

Bilâl''in o sesinde,

Mekke-i Münevverede,

Seyfullahların yüreğinde,

Seni seviyorum.

Dört mevsiminde,

Karıncanın merhametinde,

Dağlarının azametinde,

Binbir renk çiçeklerinde,

Seni seviyorum...

Yeni doğan bir bebeğin ağlamasında,

Minicik yüreğinde ki şevkat arzusunda,

Annenin uykusuzluğunda,

Kulağına okunan ezanda,

Seni seviyorum.

Denizlerinin maviliğinde,

Okyanuslarının derinliğinde,

Balıklarının şeklinde,

Fakirinin sefaletinde,

Seni seviyorum...

Allah diyen bir azizin nefesinde,

Dillerdeki şahadetlerde,

Alnımı vurduğum sana secdemde,

İsa''nın yaşlı gözlerinde,

Seni seviyorum.

Bu gün Türkiye''de

Bu gün Filistin''de

Bu gün Irak''ta,

Bu gün Afganistan''da,

Cümle-i alemde,

Seviyorum Seni.

Müslümanlığın nostalji diye anıldığı bugün de,

İllede müslümanım elhamdülillah diye,

Seviyorum seni Ya Rabbi...

28/11/2005', 'Yusuf''un kuyusunda, İbrahim''in nârında, Eyüb''ün sabrında, Mevlânın aşkında, Seni Seviyorum... Batan Güneşin,doğan Ay''ında Her bir yıldızında...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Nazım Ülker']::text[], 8.5, '{"poet":"İbrahim Nazım Ülker","poet_slug":"i-brahim-nazim-ulker","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/seni-seviyorum-ya-rabbi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana döndü sol elim', 'sana-dondu-sol-elim-guler-atas-xcuk7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sağ  elim  kime  gitse 

sol  elim  sana  döndü.

içimin sol  yanını ,

hep sana  ayırdım

bir  tutsak  gibi, yarım  kaldı 

bir  yanım

ne  zaman  yoldan  çıksa  duygularım

seni  taşıyorum,içimin  loşluğuyla

karanlık  odalara', 'sağ  elim  kime  gitse  sol  elim  sana  döndü. içimin sol  yanını , hep sana  ayırdım bir  tutsak  gibi, yarım  kaldı  bir  yanım ne  zaman...', ARRAY['Türk Edebiyatı','Şiir','Güler Ataş']::text[], 8.5, '{"poet":"Güler Ataş","poet_slug":"guler-atas","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sana-dondu-sol-elim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sahte bir kurşun', 'sahte-bir-kursun-pinar-koc-can3a', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'SAHTE BİR KURŞUN…

Ta uzaklardan  gelirken ben kollarına,

Uzun uzun yolları aşmışken yerli yersiz,

Tutamayıp ağlarım ben hayaline…

Ağlamak çözüm olsaydı tutarsızlığına,

Resimlerinle avunmak isteseydim yerli yersiz,

Sevgini kalbime gömermiydim hiç! ! 

Issız bir sahilde,yalnız bir ağaç altında,

Zehir gibi yokluğunu yaşarmıydım? ? ? 

Lanet ediyorum şimdi hayatıma,

Ilık meltemler yüzüme vururken yalnızlığımı,

Sahte bir kurşun yüreğimde kaldı…

                                                              18.02.02  21:45

                                                            pazartesi', 'SAHTE BİR KURŞUN… Ta uzaklardan  gelirken ben kollarına, Uzun uzun yolları aşmışken yerli yersiz, Tutamayıp ağlarım ben hayaline… Ağlamak çö...', ARRAY['Türk Edebiyatı','Şiir','Pınar Koç']::text[], 8.5, '{"poet":"Pınar Koç","poet_slug":"pinar-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sahte-bir-kursun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahardır Adım Güneştir Sembolüm', 'bahardir-adim-gunestir-sembolum-nurten-tarim-fbnsj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bahardır adım güneştir sembolüm

Umutsuzluğa çiçek satarım

Hasretliği süpüren rüzgarım

Gönüllere dost seyyahım

Kırgınlıkları toplayan hurdacıyım

Kış gönülleri bahara döndüren falcıyım

Kavuşamayan aşkların arasında postacıyım

İster içinde ister yanında arkadaşınım

Nefsinde sınır beyninde düşünceyim

Benliğindeki benim

Aynanım nasıl görmek istersen

Sen ne istersen ben oyum', 'Bahardır adım güneştir sembolüm Umutsuzluğa çiçek satarım Hasretliği süpüren rüzgarım Gönüllere dost seyyahım Kırgınlıkları toplayan hurdacı...', ARRAY['Türk Edebiyatı','Şiir','Nurten Tarım']::text[], 8.5, '{"poet":"Nurten Tarım","poet_slug":"nurten-tarim","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bahardir-adim-gunestir-sembolum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkmasaydım! ! !', 'korkmasaydim-pinar-koc-sleup', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'KORKMASAYDIM! ! ! 

Korkmasaydım keşke hiçbir şeyden,

Ormandaki minik tavşanlar gibi çoğu zaman…

Renk renk çiçekler arasında,

Kendinden bile korkan! ! ! 

Ağaçların yapraklarımı korkutuyordu beni,

Ağaçlar mı? ? ? 

Kaybolmuşluğum mu yoksa,

Lüzumsuz çığlıklarım,

Çığlıklarım bu yüzden miydi? ? ? 

Islak gözlerimdeki kırmızı bakışlar

 ve

korkmasaydım keşke hiçbir şeyden…

                                                       19.02.02   00:55', 'KORKMASAYDIM! ! !  Korkmasaydım keşke hiçbir şeyden, Ormandaki minik tavşanlar gibi çoğu zaman… Renk renk çiçekler arasında, Kendinden bile ...', ARRAY['Türk Edebiyatı','Şiir','Pınar Koç']::text[], 8.5, '{"poet":"Pınar Koç","poet_slug":"pinar-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/korkmasaydim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi ölmüş', 'mavi-olmus-guler-atas-1kts7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kendini mi  acıtmak  istedin

Belki canımı yakmaktı niyetin

Hava  olmak  istedim  sana

İçindeki  mavi çocuğa  ulaşmak

Çok  geç  kalmışım

Mavi  ölmüş

Bir  ölüyü  kaldırmak  kalmış  bana', 'Kendini mi  acıtmak  istedin Belki canımı yakmaktı niyetin Hava  olmak  istedim  sana İçindeki  mavi çocuğa  ulaşmak Çok  geç  kalmışım Mavi...', ARRAY['Türk Edebiyatı','Şiir','Güler Ataş']::text[], 8.5, '{"poet":"Güler Ataş","poet_slug":"guler-atas","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/mavi-olmus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkak Gölgem...', 'korkak-golgem-pinar-koc-x19r8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'KORKAK GÖLGEM…

Issız bir gecede

Gölgem bile beni terk etmişken,

Zamanı durdurmak ne mümkün! ! ! 

Duvarlarla konuşmaya başladığım o an,

Izdırap duyuyorum yüreğimde sadece…

Resimlerine bakamıyorum,

Korkuyorum…

Acı bir çığlık var gözlerinde sadece

Parçalanmış yüreğimi

Biraz daha parçalayan…

                                                   19.02.02   01:18', 'KORKAK GÖLGEM… Issız bir gecede Gölgem bile beni terk etmişken, Zamanı durdurmak ne mümkün! ! !  Duvarlarla konuşmaya başladığım o an, Izdır...', ARRAY['Türk Edebiyatı','Şiir','Pınar Koç']::text[], 8.5, '{"poet":"Pınar Koç","poet_slug":"pinar-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/korkak-golgem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Amaç', 'amac-abdulvahap-ates-zsqmm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Araç amaçlaşınca,

Amaç ta araçlaşır,

Amaçla buluşmayan,

Açlaşır da açlaşır.

Sonra aranır durur.

Susuz kalır ve kurur.

Boşluğu boş doldurur.

Kartlaştıkça kartlaşır.

Amaç kaybolur gözden,

Uzaklaşarak özden,

İnsanoğlu bu yüzden,

Mallaşır malcılaşır.', 'Araç amaçlaşınca, Amaç ta araçlaşır, Amaçla buluşmayan, Açlaşır da açlaşır. Sonra aranır durur. Susuz kalır ve kurur. Boşluğu boş doldurur. ...', ARRAY['Türk Edebiyatı','Şiir','Abdulvahap Ateş']::text[], 8.5, '{"poet":"Abdulvahap Ateş","poet_slug":"abdulvahap-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/amac-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Parlak Mavi', 'en-parlak-mavi-hatice-bediroglu-chv78', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Konakladım sahilde öğle üzeri 

Seyrettim sonsuz tatlı mavileri 

Derinliğinde kaybettim yolumu 

Kabarttı dalgaları sevgimin coşkusu

Berrak suyun altında saydım taşları

Okşadım yemyeşil yosunları 

Dayanamadım

Kucakladım koca denizi 

El salladım balıklara

Vals yaptı denizanaları etrafımda 

Martılar süzülürken gökteki mavilerde

Mavi bir rengim olsundu dileğim 

Haberim yoktu ya Deli Mavi Sevdam

Giydirmişti mavilerin en parlağını

Sevinç yağmura dönüştü 

Salkım salkım üzüm oldu yüreğimde 

'' Düş Kuruyor Gece '' adlı kitabımdan - Ocak 2008 - 

www.haticebediroglu.net', 'Konakladım sahilde öğle üzeri  Seyrettim sonsuz tatlı mavileri  Derinliğinde kaybettim yolumu  Kabarttı dalgaları sevgimin coşkusu Berrak su...', ARRAY['Türk Edebiyatı','Şiir','Hatice Bediroğlu']::text[], 8.5, '{"poet":"Hatice Bediroğlu","poet_slug":"hatice-bediroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/en-parlak-mavi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koruyamam seni', 'koruyamam-seni-guler-atas-369jy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İki  şey  öğrettiler  bize

Toplumsal  olmayan  aşk  zayıflıktır

Ve  sevgi  emektir

Emek  zaman  ister

Takvimlerden  saatlerden  bağımsız

Sevgi  anlamak  ister  şans  ister

Sevgi  elmada  kurt  değil

Dünyada  kurt  olmak  ister

Bir  kurt  gibi  çıkaramam  dişlerimi

Korkmadan  koruyamam 

Bu  toplumda  seni

Öğretilenler  ve  öğrettiklerimizle

Takvimden  bir  yaprak  düşer  gibi

Terk  edersem  seni

Anlamaya  çalış  ve  bağışla  beni', 'İki  şey  öğrettiler  bize Toplumsal  olmayan  aşk  zayıflıktır Ve  sevgi  emektir Emek  zaman  ister Takvimlerden  saatlerden  bağımsız Sev...', ARRAY['Türk Edebiyatı','Şiir','Güler Ataş']::text[], 8.5, '{"poet":"Güler Ataş","poet_slug":"guler-atas","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/koruyamam-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi Tek İsteğim...', 'simdi-tek-i-stegim-hulya-arisan-xwk69', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevgim,

tıpkı bir sevinç

nidası gibi,

coşkulu...

Aşkım,

bedenimden çıkıp

hazzın zirvesine ulaşan

ruhum kadar yoğun...

Şimdi,

tek arzum.

Ruhuma haz veren,

besleyen ruhunun.

Benim yüreğimle buluşması.

İstanbul, 29 Kasım 2005', 'Sevgim, tıpkı bir sevinç nidası gibi, coşkulu... Aşkım, bedenimden çıkıp hazzın zirvesine ulaşan ruhum kadar yoğun... Şimdi, tek arzum. Ruhu...', ARRAY['Türk Edebiyatı','Şiir','Hülya Arısan']::text[], 8.5, '{"poet":"Hülya Arısan","poet_slug":"hulya-arisan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/simdi-tek-istegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hissetmek Yaşamaktan da Öte', 'hissetmek-yasamaktan-da-ote-melih-coskun-pu6fj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şavkında boğun beni 

Bölüşmek suçsa eğer ay ışığını,

Yakın beni 

Kızıllığını türküme kattığım 

Güneşin sıcaklığında, 

Sevdamı kazıdığım ağacın gövdesinde 

Kurşunlayın bedenimi

Şiirlerimi de asın 

Yaftamın yanına

Her ölüm bir diriliştir aslında 

Söylenir meydanlarca

Susmak; 

Şimdi en gürültülü eylemdir. 

Susmak; 

Seni sensizliğinde 

Ne kadar sevdiğimi söylemektir.

Yazdığım hiçbir dize yalan değil 

Yalan değil 

Ruhumu çığlıklar içinde dağlayan o yalnızlık 

Hissetmek; 

Şimdi yaşamaktan da öte. 

Haydi yaz adımı sonsuzluğa yokluğunla 

Abıhayat içelim 

Aşkın sımsıcak koynunda. 

Ne ellerin kalır

Ellerimde oldukça 

Ne gözlerin kalır gözlerime baktıkça 

Hissetmek şimdi yaşamaktan daha da öte 

Haydi ölümsüzleştir adımı 

Sensiz bırakarak mısralarımı...

2005', 'Şavkında boğun beni  Bölüşmek suçsa eğer ay ışığını, Yakın beni  Kızıllığını türküme kattığım  Güneşin sıcaklığında,  Sevdamı kazıdığım ağac...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/hissetmek-yasamaktan-da-ote-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Yerine', 'senin-yerine-cem-cagman-o0e53', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'senin yerine düşündüm

ben sen olsaydım dün

suratına tükürürdüm

belki sende tükürdün

ben farketmedim belkide

görmedim tükürdüğünde

belki gizliydi bir hareketinde

görseydim sürünürdüm yerlerde

anlıyorsun değilmi bu olanları

duyuluyor artık ayrılık çanları

içimden sel olup akan kanları

gör de anla artık yazılanları', 'senin yerine düşündüm ben sen olsaydım dün suratına tükürürdüm belki sende tükürdün ben farketmedim belkide görmedim tükürdüğünde belki gizl...', ARRAY['Türk Edebiyatı','Şiir','Cem Çağman']::text[], 8.5, '{"poet":"Cem Çağman","poet_slug":"cem-cagman","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/senin-yerine-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben bir zekat verdim bu gun', 'ben-bir-zekat-verdim-bu-gun-mikdat-bal-y31q7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben bir zekat verdim bu gun  ister alan almasın

Bin dir fakat, yardım mümkün dost der kalan kalmasın

Tendir sakat, derdim yekün, göster yalan olmasın

Açık olur yapılanlar, bu şov değil teşviktir

Verdim fakir aldı seçti güzelleri ayırdı       

Yerdim, Bekir çaldı kaçtiı tüzelleri sıyırdı  

Gördüm hakir kaldı geçti özelleri kayırdı

Kaçık olur kapılanlar, sen sanarsın müşviktir', 'Ben bir zekat verdim bu gun  ister alan almasın Bin dir fakat, yardım mümkün dost der kalan kalmasın Tendir sakat, derdim yekün, göster yala...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ben-bir-zekat-verdim-bu-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bal gözlüm', 'bal-gozlum-guler-atas-mrwx3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni  baharda  güneş /

Seni  başımın  üstünde  bulut /

Seni  yağmur  sonrası /

Toprak  kokusu  gibi  sevmişim.

Senden  sonra  sevdim.

Bal  arılarının  /

Çiçeklere olan  aşkını.

Seni  petekte  bal  gibi /

Bal  gözlüm /

Çünkü /

Gözlerindi  veren /

Çiçekteki  bala  rengini.', 'Seni  baharda  güneş / Seni  başımın  üstünde  bulut / Seni  yağmur  sonrası / Toprak  kokusu  gibi  sevmişim. Senden  sonra  sevdim. Bal  a...', ARRAY['Türk Edebiyatı','Şiir','Güler Ataş']::text[], 8.5, '{"poet":"Güler Ataş","poet_slug":"guler-atas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bal-gozlum-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otobüs Terminalleri', 'otobus-terminalleri-kerim-ozkara-5l64j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Otobüs terminallerinde geçti ömrüm

Bir o şehir bir bu şehir süründüm

Ne ayrılıklara şahit oldum ne vuslatlar gördüm

Beni bekleyen olmadı ama ne bekleyenler gördüm

Otobüs camlarında eskidi yüzüm

Bir annem öperdi, o’da gurbette şimdi

Derdimi paylaşanım olmadı 

Bir ablam dinlerdi, o’da evlendi şimdi

Yollarda geçti ömrüm

Hep yollarda kaldı gözüm

Yine yolculuk var anlaşılan

Sevdiklerimi belki de bu son görüşüm', 'Otobüs terminallerinde geçti ömrüm Bir o şehir bir bu şehir süründüm Ne ayrılıklara şahit oldum ne vuslatlar gördüm Beni bekleyen olmadı ama...', ARRAY['Türk Edebiyatı','Şiir','Kerim Özkara']::text[], 8.5, '{"poet":"Kerim Özkara","poet_slug":"kerim-ozkara","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/otobus-terminalleri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sitem', 'sitem-kerim-ozkara-77240', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her insan gibi

Sevdiğimle olan

Hayallerim vardı benim

Sen yıkmadan önce

Senin hasretinle büyüyen

Sadece sana ait olan

Bir aşkım vardı benim

Sen bitirmeden önce

Sensizken kahrolan

Sadece senin için çarpan

Bir kalbim vardı benim

Sen sökmeden önce

Acı dolu ve çaresiz bile olsa

Senden bihaber geçmiş bile olsa

Bir hayatım vardı benim

Seni tanımadan önce

Her yerde seni aradığım

Gözlerine hiç bakamadığım

Gözlerim vardı benim

Sen ağlatmadan önce

Kara gözlüydü sanırım

sadece benim sanırdım

Bir sevgilim vardı benim

Sen Terketmeden Önce...', 'Her insan gibi Sevdiğimle olan Hayallerim vardı benim Sen yıkmadan önce Senin hasretinle büyüyen Sadece sana ait olan Bir aşkım vardı benim ...', ARRAY['Türk Edebiyatı','Şiir','Kerim Özkara']::text[], 8.5, '{"poet":"Kerim Özkara","poet_slug":"kerim-ozkara","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sitem-205-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Vardı', 'o-vardi-kerim-ozkara-uric8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aynaya baktığımda onu görüyordum gözbebeklerimde

Gece rüyalarımda,

Radyoda çalan şarkılarımda,

Yanan mumumun alevinde o vardı.

Ama ne zaman alevi tutmak istesem elim yanıyordu

Aşk buydu. Ve o görmek istemiyordu.

Ya da istediği gibi görüyordu.

Tutunacak bir daldı. 

Bir gün beni bir sardı..

O gün kollarında ölmek vardı...', 'Aynaya baktığımda onu görüyordum gözbebeklerimde Gece rüyalarımda, Radyoda çalan şarkılarımda, Yanan mumumun alevinde o vardı. Ama ne zaman ...', ARRAY['Türk Edebiyatı','Şiir','Kerim Özkara']::text[], 8.5, '{"poet":"Kerim Özkara","poet_slug":"kerim-ozkara","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/o-vardi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelmiyor', 'gelmiyor-cem-cagman-75ft9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'belki üç belkide dördüncü paket

içtim cigaramı geleceğim sabret

ev sıcak kış günü ne bu havadaki kasvet

bitmiyor işte bitmiyor çektiğim hasret

kalmadı ne gözümde ne dizimde derman

beklemezdim çıksaydı padişahtan ferman

körolasıca gözler dayanacağın kadar dayan

gelmiyor işte gelmeyecekte hiçbir zaman', 'belki üç belkide dördüncü paket içtim cigaramı geleceğim sabret ev sıcak kış günü ne bu havadaki kasvet bitmiyor işte bitmiyor çektiğim hasr...', ARRAY['Türk Edebiyatı','Şiir','Cem Çağman']::text[], 8.5, '{"poet":"Cem Çağman","poet_slug":"cem-cagman","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gelmiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-nurten-tarim-nkuug', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sözlerim karıştı

Düğümlendi kelimeler boğazıma

Nefesim çıkmıyor

Seni seviyorum

Aşkım demeği', 'Sözlerim karıştı Düğümlendi kelimeler boğazıma Nefesim çıkmıyor Seni seviyorum Aşkım demeği...', ARRAY['Türk Edebiyatı','Şiir','Nurten Tarım']::text[], 8.5, '{"poet":"Nurten Tarım","poet_slug":"nurten-tarim","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/seni-seviyorum-303-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalan Ne ki Temiz Olan? Zaman, Bu Zaman....', 'kalan-ne-ki-temiz-olan-zaman-bu-zaman-nesrin-gocmen-6llq9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kalan Ne ki Temiz Olan Zaman Bu Zaman

Çalanın sırtı pek, karnı tok ama 

Yediği naneler, tavalar kirli

Yoruldum, bezginim bakarım cama 

Alaca boyanmış havalar kirli 

.

Parça bölük oldu, dağıldı birlik

Bulaşan hastalık yurdumda körlük

Ufalan beyinde nefeste zorluk 

Zevklere doyulmuş havalar kirli 

.

Kel başlı, göbekli, utanmaz pişkin 

Helali bilmeyen, cüzdanı şişkin

Uğraşıyla gücü çirkin mi çirkin 

Beylerle uyanmış havalar kirli... 

.

Aynadan korkar mı kör olan gözler? 

Kurbanı mı olduk geçmişin bizler? 

Sanmayın silinir tarihten izler 

Suları taşımış kovalar kirli 

Umuda soyunmuş havalar kirli

29 Kasım 2005', 'Kalan Ne ki Temiz Olan Zaman Bu Zaman Çalanın sırtı pek, karnı tok ama  Yediği naneler, tavalar kirli Yoruldum, bezginim bakarım cama  Alaca...', ARRAY['Türk Edebiyatı','Şiir','Nesrin Göçmen']::text[], 8.5, '{"poet":"Nesrin Göçmen","poet_slug":"nesrin-gocmen","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kalan-ne-ki-temiz-olan-zaman-bu-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Yalnızım', 'cok-yalnizim-kerim-ozkara-ioit2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çok yalnızım çok

Seslenemiyorum 

Haykırsam duyanım yok

Çığlıklarım sanki bir fısıltı

Göremiyorum

En yüksek ışıkta bile sanki karanlık

Nedenini bilemiyorum

En mutlu günümde gözüm yaşlı

Attığım adım kararsız

Bilemiyorum

Bu mutluluğun sonu sende mi saklı…', 'Çok yalnızım çok Seslenemiyorum  Haykırsam duyanım yok Çığlıklarım sanki bir fısıltı Göremiyorum En yüksek ışıkta bile sanki karanlık Nedeni...', ARRAY['Türk Edebiyatı','Şiir','Kerim Özkara']::text[], 8.5, '{"poet":"Kerim Özkara","poet_slug":"kerim-ozkara","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/cok-yalnizim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bak işte yine sendeyim', 'bak-iste-yine-sendeyim-guler-atas-3246k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'aşklarımı da  çalmışsın

yeni  bir  aşka  yelken  açmak  istedim

okyanus  ortasında  gözlerin

bıçak

bütün  halatlarımı  kesti  gidemedim

bak  işte  yine  sendeyim', 'aşklarımı da  çalmışsın yeni  bir  aşka  yelken  açmak  istedim okyanus  ortasında  gözlerin bıçak bütün  halatlarımı  kesti  gidemedim bak ...', ARRAY['Türk Edebiyatı','Şiir','Güler Ataş']::text[], 8.5, '{"poet":"Güler Ataş","poet_slug":"guler-atas","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bak-iste-yine-sendeyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey insanlar', 'ey-insanlar-sinan-aydindag-qk4d8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bekle beni yeni dünya                                      

   Geliyorum

   Kucak kucak dalga dalga

   Kuşlara ağaçlara ve bozkırlara

   Sesleniyorum bekleyin beni.

   Yeni sayfalar açıyorum hayatımda

   Gelecege umutla bakıyor

   Yeni gelen günü selanlıyorum.

   Ovalarda papatyalar açtı

   Fidanlar boy boy yetişti

   İnsanların gülümsemesi

   Nasılda aklıma gelmişti.

   Gülün insanlar gülün

   Hayatın acılarına gülün

   Yaşayın hayatı yaşayın

   Bir daha şans yok yaşayın.', 'Bekle beni yeni dünya                                          Geliyorum    Kucak kucak dalga dalga    Kuşlara ağaçlara ve bozkırlara    Ses...', ARRAY['Türk Edebiyatı','Şiir','Sinan Aydındağ']::text[], 8.5, '{"poet":"Sinan Aydındağ","poet_slug":"sinan-aydindag","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ey-insanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haykırarak', 'haykirarak-sinan-aydindag-kfce4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Haykırarak yazmak istiyorum seni 

   Kitaplarıma defterlerime

   Haykırarak söylemek istiyorum sevdiğimi seni

   Sana ve sana

   Anlatmak istiyordum anlamıyordun

   Söylemek istediklerimi söylemeden,

   Beni çaresiz bırakıp kaçıyordun

   Oldu işte olanlar

   Sonunda bıraktın beni ortada

   Anlamadan dinlemeden ve sevmeden

   Bütün hayallerimi yıktın

   Artık bu hayattan bıktım

   Sana öpücükler ve gülücüklerle veda ediyorum

   Seni bundan sonra mahşerde bekliyorum.', 'Haykırarak yazmak istiyorum seni     Kitaplarıma defterlerime    Haykırarak söylemek istiyorum sevdiğimi seni    Sana ve sana    Anlatmak is...', ARRAY['Türk Edebiyatı','Şiir','Sinan Aydındağ']::text[], 8.5, '{"poet":"Sinan Aydındağ","poet_slug":"sinan-aydindag","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/haykirarak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köfteyim Ben', 'kofteyim-ben-emre-ozoran-hgdol', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Köfteyim ben,

Kıymaydım eskiden.

Yoğurdular, pişirdiler

Servise hazırım şimdi.

Yiyecekler beni.

Geleceği düşünmüyorum artık

Mutluyum.

Ama yiyecekler beni

O ısırış saati geldikçe aklıma, içimde...

Öleceğim,

Afiyet olunacak sayemde

Yasım tutulmayacak.

Köfte olmak zor kardeşim.

Ekmek arasına girdim şimdi,

Son yakın.

Az sonra ağıza giderim.

Kıymaydım, köfte oldum,

Yediler, lokma oldum.', 'Köfteyim ben, Kıymaydım eskiden. Yoğurdular, pişirdiler Servise hazırım şimdi. Yiyecekler beni. Geleceği düşünmüyorum artık Mutluyum. Ama yi...', ARRAY['Türk Edebiyatı','Şiir','Emre Ozoran']::text[], 8.5, '{"poet":"Emre Ozoran","poet_slug":"emre-ozoran","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kofteyim-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece', 'gece-hekim-coskun-4cldo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'incecik bir zamandı 

gel-git lerle dolu.

kendinle götürdüğün her şey 

bana ait her şeydi.

yıldızlar ve sen vardın

özlediğim gündüz gibiydi zaman.

her yer aydınlık

her şey dolunaydı.

ellerim uzaklara dokunur gibiydi

yüreğimde bir sevinç

sesimde bir titreyiş vardı.

sormuş sorgulamıştım yaşamı.

tüm giderlerimde sen

ve getirisi yaşamın kıyısındaydı zaman

kimbilir; 

kaç zamandır beklediğim çaresizliğimden.

kim sayabilir adımlarımı

cadde ve sokakları birbirine karışmış bir kentte

içinden çıkılmaz düşler kurdum

düzensiz ve sensizdim.

yangın yeri gibiydi yaşam.

ellerimle yüzümü kapayıp

parmaklarım arasından baktım.

çok saatler geçti,

çok yıllar

hala ilerliyor sandığımız yaşam

gerisin geriye götürdü bizi.

birkaç saat sonra bu gün.

bu gün sabah oldu.

uyandık uyanacak umutlarımız', 'incecik bir zamandı  gel-git lerle dolu. kendinle götürdüğün her şey  bana ait her şeydi. yıldızlar ve sen vardın özlediğim gündüz gibiydi z...', ARRAY['Türk Edebiyatı','Şiir','Hekim Coşkun']::text[], 8.5, '{"poet":"Hekim Coşkun","poet_slug":"hekim-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/gece-193-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen cehennemliksin', 'sen-cehennemliksin-sinan-aydindag-g080a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben burada hayatı kahredicem

   Sen orada gününü gün edicen

   Benim böyle kadere isyanım var.

   Bir hayat sönecek senin uğruna

   Umrunda olmadan gülüp geçeceksin

   Bir oyuncak daha bulup kendine 

   Onunlada dalganı geçeceksin

   Sonra,sonra bir başkasının aklına gireceksin

   Unutma bunu sen cehennemliksin.', 'Ben burada hayatı kahredicem    Sen orada gününü gün edicen    Benim böyle kadere isyanım var.    Bir hayat sönecek senin uğruna    Umrunda ...', ARRAY['Türk Edebiyatı','Şiir','Sinan Aydındağ']::text[], 8.5, '{"poet":"Sinan Aydındağ","poet_slug":"sinan-aydindag","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sen-cehennemliksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* Siyah Beyaz Anılarım*', 'siyah-beyaz-anilarim-seyhmus-sevilmez-57jps', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çatı katının karanlık köşesinde,

Bırakılan bir ayakkabı kutusuydu unutulan

Ve üzerine,

İlmik ilmik dantel örmüştü, örümcekler, 

Bu küçücük çeyiz sandığına sıkışıp kalmıştı 

Siyah beyaz anılarım.

Oradaydı dünlerim,

Kırışmamış yüzdeki gülücüklerim…

Oradaydı beni saran Babaannem,

Ve yıllar önce nice yitirdiğim sevdiklerim…

Oradaydı ilk göz ağrım

Ve duvarda, ikiyi beş geçemeyen donmuş zaman

Gençliğime dair ne yoktu ki orada! 

Ne yoktu ki siyah beyaz bakan anılarda..

Üşenmişti zaman, 

Küsmüşlerdi rakamlara akrep ve yelkovan.

Ne değişmemişti ki o zamandan bu zamana? 

Ne acılar çekilmemişti ki sevdalardan yana? 

Orda kaldı siyah saçlar, oysa şimdi kar beyaz

Yüreğim zamanı suçlar, ölüm gecede ayaz..

30.11.2005/ Batman', 'Çatı katının karanlık köşesinde, Bırakılan bir ayakkabı kutusuydu unutulan Ve üzerine, İlmik ilmik dantel örmüştü, örümcekler,  Bu küçücük ç...', ARRAY['Türk Edebiyatı','Şiir','Şeyhmus Sevilmez']::text[], 8.5, '{"poet":"Şeyhmus Sevilmez","poet_slug":"seyhmus-sevilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/siyah-beyaz-anilarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Al Benide Sol Yanına', 'al-benide-sol-yanina-yusuf-ter-whg15', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Canım ver aşkını bana

Kurban olayım diline

Uyut beni kollarında

Başım koyayım yoluna

Benim yarim gonca güldür

Öter  bahçede bülbüldür

Ne olursun beni güldür

Hasretim ince beline

Kollarım açarım sana

Sarılsan ne olur bana

Nazik ellerinde kına

Gel bir salına salına

Gülüzar yalan dünyadan 

Giden gelmez garip handan

Bir arzum var benim senden

Artık biline biline

Yusuf’um ben sevdalıyım

Gurbette kara çalıyım

Beklide bir gül dalıyım

Koyma beni el eline

Yusuf Ter 29.11.05

Saat 02:20 İsviçre', 'Canım ver aşkını bana Kurban olayım diline Uyut beni kollarında Başım koyayım yoluna Benim yarim gonca güldür Öter  bahçede bülbüldür Ne olu...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ter']::text[], 8.5, '{"poet":"Yusuf Ter","poet_slug":"yusuf-ter","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/al-benide-sol-yanina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm', 'olum-onur-erdogan-qnved', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yarın yıllar geçmiş

Gözler sönmüş

Işıklar hep

Arkanda

Yalnızlıklar rıhtımda

Beyazların bol

Yıllar uzun.

          O.E

         10.11.2005(02.45)', 'Yarın yıllar geçmiş Gözler sönmüş Işıklar hep Arkanda Yalnızlıklar rıhtımda Beyazların bol Yıllar uzun.           O.E          10.11.2005(02...', ARRAY['Türk Edebiyatı','Şiir','Onur Erdoğan']::text[], 8.5, '{"poet":"Onur Erdoğan","poet_slug":"onur-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/olum-234-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aç Kollarını Geleyim', 'ac-kollarini-geleyim-nurten-tarim-842es', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aç kollarını geleyim

Başımı dizine koyup uyuyayım

Kuş olsun ruhum uçsun

Gözlerinde dalsam uzaklara

Anlatmadan anlasan derdimi

Çocuklaşsam 

Ninniler söylesen bana

Saçlarımı okşasan

Eritsem bedenimi

Mutluluğunda büyütsen beni

İçinde kalıp zamanı durdursam

İsteğim çok değil sevgilim

Busen baharım

Listeledim duyguları

Gözyaşımda adın

Damlaları dizdim boynuma taktım', 'Aç kollarını geleyim Başımı dizine koyup uyuyayım Kuş olsun ruhum uçsun Gözlerinde dalsam uzaklara Anlatmadan anlasan derdimi Çocuklaşsam  N...', ARRAY['Türk Edebiyatı','Şiir','Nurten Tarım']::text[], 8.5, '{"poet":"Nurten Tarım","poet_slug":"nurten-tarim","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ac-kollarini-geleyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıllar', 'yillar-onur-erdogan-mm8vf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hep sonralardan sıkıldım artık

Çalışıp da başaramamaktan

Hep yıllar kapladı üzerimi

Yıllanmışım artık

Hep başkalarından sıkıldım

Gözleri önündeki ben

dururken

                        12.01.2003', 'Hep sonralardan sıkıldım artık Çalışıp da başaramamaktan Hep yıllar kapladı üzerimi Yıllanmışım artık Hep başkalarından sıkıldım Gözleri önü...', ARRAY['Türk Edebiyatı','Şiir','Onur Erdoğan']::text[], 8.5, '{"poet":"Onur Erdoğan","poet_slug":"onur-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yillar-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün yine', 'bugun-yine-sinan-aydindag-y7teg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bugün yine aradı gözlerim seni yanımda                     27/01/2001

   Sen yoktun hayalin vardı karşımda

