INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine Bıçak Açmıyor Ağızları', 'yine-bicak-acmiyor-agizlari-mehmet-ciftci-mhq6f', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yine bıçak açmıyor ağızları,

Gözler sabah mahmur akşam bulanık.

Herkes sanki uyur gezer misali,

Tek tük anlamsız söz o da bir anlık.

Ölüye benziyor çevremde herkes,

Hayat belirtisi yalnız bir nefes,

Burada yaşamak mahkuma kafes,

Seyran değil artık hiçbir samanlık.

Renkler anlamını kaybetti bir bir,

Harcandı tamamı tükendi sabır,

Yüzü gülen nadir, belki binde bir,

Neşe bazan uğrar o da bir anlık.', 'Yine bıçak açmıyor ağızları, Gözler sabah mahmur akşam bulanık. Herkes sanki uyur gezer misali, Tek tük anlamsız söz o da bir anlık. Ölüye b...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çiftci']::text[], 8.5, '{"poet":"Mehmet Çiftci","poet_slug":"mehmet-ciftci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yine-bicak-acmiyor-agizlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vicdan Mahkemesine Verdim Ben Seni', 'vicdan-mahkemesine-verdim-ben-seni-munevver-senol-lrdqq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Vicdan mahkemesine verdim ben seni

Dün akşam yok yere kavga çıkardın.

Olmayan hakkını, haram ettin sen bana.

Ben de seni vicdan mahkemesine verdim.

Sabıka kaydın hayli kabarık, suçun ise, vicdansız çıktı.

Meğer sen ne kadar günahkarmışsın.

Seni savunacak avukat bile bulamadılar

Hakim, davacı.. ''''son sözün ne? '''' dedi, bana 

Yıllardır çektiğim yetti canıma.

Ben davacıyım, karar sizin hakim bey

Gereği düşünüldü, karar verildi.

Vicdan cehenneminde, müebbete mahkum ettiler.

Ama temyize yolladı dosyayı, davaya itiraz etti.

Bu seferde ona verdiğim yıllarımın hesabını tutum.

Onun bana verdiği, kocaman bir sıfır çıktı.

Hakim bey, ''''eşime aşığım yanıyorum aşkımdan'''' dedi.

Termomereyle ölçtüler, saçak saçak, buz çıktı

Sen yıllarca hesabı tuturamadın aşk kitabında.

Ölüyorum dedinde, senin uğrunda.

İmamın bile sahteymiş şalomon çıktı...

     

3.12.2005  (taze taze çıtır çıtır)', 'Vicdan mahkemesine verdim ben seni Dün akşam yok yere kavga çıkardın. Olmayan hakkını, haram ettin sen bana. Ben de seni vicdan mahkemesine ...', ARRAY['Türk Edebiyatı','Şiir','Münevver Şenol']::text[], 8.5, '{"poet":"Münevver Şenol","poet_slug":"munevver-senol","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/vicdan-mahkemesine-verdim-ben-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiçek Anam (Anama)', 'cicek-anam-anama-ayhan-yavuz-acikgoz-3cm3p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çiçek anam, petek anam bal anam

Vuslatlığın ummânına dal anam

İstemiyom senden gayrı bir beşer

Herkes gitsin, sen yanımda kal anam

(istanbul-2004)', 'Çiçek anam, petek anam bal anam Vuslatlığın ummânına dal anam İstemiyom senden gayrı bir beşer Herkes gitsin, sen yanımda kal anam (istanbul...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Yavuz Açıkgöz']::text[], 8.5, '{"poet":"Ayhan Yavuz Açıkgöz","poet_slug":"ayhan-yavuz-acikgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/cicek-anam-anama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol Bilmez', 'yol-bilmez-mehmet-ciftci-sqm5d', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir söz var dilimde diyemiyorum,

Hayvanlara saygısızlık sayılır.

Neye benzeteyim bilemiyorum,

Odun desem bu haksızlık sayılır.

Ne kurala uyar ne yordam bilir,

Her yanlışta mutlaka orda olur,

Cahil desem bilmem ki nerde kalır,

Cehalete edepsizlik sayılır,

Ağzında sigara taşır devamlı,

İçi boş ya baksan yiğit endamlı,

Çatık kaşlı hem öfkeli hem gamlı,

Haksızlığı sebepsizlik sayılır.

Yüzüne akseder içinin hali,

Küfürsüz sözlere yabancı dili,

Her yere uzanır kopası eli,

Adam saysan hesapsızlık sayılır,

Tükürsen yüzüne tükrüğe yazık,

Ona göre hem çok kibar hem nazik,

Her zaman papucun arkası ezik,

Doğru giyse bu yolsuzluk sayılır.', 'Bir söz var dilimde diyemiyorum, Hayvanlara saygısızlık sayılır. Neye benzeteyim bilemiyorum, Odun desem bu haksızlık sayılır. Ne kurala uya...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çiftci']::text[], 8.5, '{"poet":"Mehmet Çiftci","poet_slug":"mehmet-ciftci","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yol-bilmez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçmakdayım..', 'kacmakdayim-taskin-erdinc-9fbvb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çıkmazla açmaz yorar beni,

Açmaza kapanır gecelere yaslanırım,

Sabahına gecenin çıkmazında kaybolurum,

Sokaklarında dolaşır, sırılsıklam uyanırım,

Bir çıkmaz ve bir açmaz sana uzanışım,

Ama bitmez bilki seninle ıslanışım,

Kurutmaz en sıcak düşlerin bile,

Çıkmazında gözlerimin,

Oysa çıkmazlar cezbeder beni,

Açmaza sokar yüreğimi,

Çıksanda düşlerimden çıkmazdayım,

Açsanda yüreğini açmazdayım,

Bebeğim sen bilirsin aslında beni,

KAÇMAKTAYIM...', 'Çıkmazla açmaz yorar beni, Açmaza kapanır gecelere yaslanırım, Sabahına gecenin çıkmazında kaybolurum, Sokaklarında dolaşır, sırılsıklam uya...', ARRAY['Türk Edebiyatı','Şiir','Taşkın Erdinç']::text[], 8.5, '{"poet":"Taşkın Erdinç","poet_slug":"taskin-erdinc","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kacmakdayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilirim Dönmez Dilim (Anama)', 'bilirim-donmez-dilim-anama-ayhan-yavuz-acikgoz-0qzok', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sana anlatsam sevgimi, bilirim dönmez dilim

