INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düştende Öte - 2', 'dustende-ote-2-tibet-avci-k24o0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sana giden son otobüs

Bu şehrin garından kalkar

Erişilmez, uzaksa yollar

Neylesin,sarılamaz kollar

Ve bastı gaza şöför

Bir duman doldu düşlerime

Düştende öte; yüreğime

O yıldızdan haber var sanki

Sanki döneceksin

Ve bir yerlerde beni düşünüp

Ağlıyor gibisin

Oysa ''''Düşbebek'''' gitti

Düşler bitti

Ama hep sendin giren düşlerime

Düştende öte yüreğime

                                                 24.02.1997', 'Sana giden son otobüs Bu şehrin garından kalkar Erişilmez, uzaksa yollar Neylesin,sarılamaz kollar Ve bastı gaza şöför Bir duman doldu düşle...', ARRAY['Türk Edebiyatı','Şiir','Tibet Avcı']::text[], 8.5, '{"poet":"Tibet Avcı","poet_slug":"tibet-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dustende-ote-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küfürbaz', 'kufurbaz-aysun-erat-p57ma', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bütün ışıkları açık bıraktım oysa..

Yine  de koyu bir karanlık içindeyim.

Kör olasıca zifiri bir karanlık! 

Akıl ve delilik arasında incecik bir çizgi mi bu? gidip geldiğim..

Dalgın gözlerle izliyorum akıp giden hayatı,

Ve içimden durdurmak geliyor insanları.

Hey! 

Kıpırdamayın artık.

Başım dönüyor fena halde

Herkes otursun oturduğu yerde

Nedir bu telaş yaşamak dediğiniz? 

Hiçbir şey olacağı yok! 

Bugün de, dünün aynısı.

Yarın da değişeceği yok.

İçimden sadece...

Aşksız geçen her güne,

Okkalı bir küfür sallamak geliyor.

Bu gidişle bir küfürbaz olacağım, bu besbelli.

Perşembenin geleceği gibi.

Yanarım ben, ona yanarım.

Gerisi hikaye...

12/2005', 'Bütün ışıkları açık bıraktım oysa.. Yine  de koyu bir karanlık içindeyim. Kör olasıca zifiri bir karanlık!  Akıl ve delilik arasında incecik...', ARRAY['Türk Edebiyatı','Şiir','Aysun Erat']::text[], 8.5, '{"poet":"Aysun Erat","poet_slug":"aysun-erat","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kufurbaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektuplar-14 08/12/2005', 'mektuplar-14-08-12-2005-mahzun-doga-aej5c', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Geri alıyoruz 

çalınmış bütün mutluluklarımızı.

Kızıl elmalı mor yanaklarımızın morsuzluğunu.

Bozulmuş oyunlarımıza geri dönüyoruz,

yıkılmış oyuncaklarımıza.

Evlerimiz geri dönüyor evcilik oyunlarına.

Çocuklarımız geri doğuyor.

Yeniden yaşlanmaya başlıyoruz.

Geri alıyoruz ömrümüzün ömrünü.

Ve iade ediyoruz 

zoraki aldırıldığımız karanlığı.

Mavinle değiştiriyoruz kızarmış bedenimizi.

Yırtıp atıveriyoruz “sahipsiz mektupları”.

Yüzsuyumuzda yıkıyoruz gülüşünün şalını.

İade ediyoruz,

İadesi olan herşeyimizi.

İademize alıyoruz iadesizlerimizi.

Suya yazmıyoruz, 

suyla yazılıyoruz umutlara şimdi.

Yıkanıyor tüm hüzünler. 

Hüznümü boğan hüzünsün.

Yaşadıklarımızın özeti yüzün.

Rengi mavi.

Ebemkuşağı mavi.

Hislerin.

Kalbindeki direnç.

Hüznüm.

İrem kadın.

Yorgun irem.

Yorgunsun.

Ayaklarında yıllarca yıllık yol.

Dilinde kitaplar dolusu kelime.

Yüreğinde yürekler dolusu sevmek.

Yorgunsun.

Yanıbaşındayım.

Yorgunum.

Dinlendiriyor şimdi, 

Yorgunluğun yorgunluğumu. 

Omuzlarına düşüyor 

sana koşmaya imkansızlığım.

Geliyorsun.

Geliyorsun.

Binlerce kez geliyorsun içime.

Ve iade ediyorum içimi içine.', 'Geri alıyoruz  çalınmış bütün mutluluklarımızı. Kızıl elmalı mor yanaklarımızın morsuzluğunu. Bozulmuş oyunlarımıza geri dönüyoruz, yıkılmış...', ARRAY['Türk Edebiyatı','Şiir','Mahzun Doğa']::text[], 8.5, '{"poet":"Mahzun Doğa","poet_slug":"mahzun-doga","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/mektuplar-14-08-12-2005-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elele', 'elele-ebru-rabia-berkul-e94gy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaşamak,

Akan bir su kenarında

Uçuşan su damlacıklarında

Yaşamak

En güzeli

Senin yanında

Seninle birlikte

Sonsuzluğa doğru

Yürür gibi

El ele tutuşarak

Yaşamak.', 'Yaşamak, Akan bir su kenarında Uçuşan su damlacıklarında Yaşamak En güzeli Senin yanında Seninle birlikte Sonsuzluğa doğru Yürür gibi El ele...', ARRAY['Türk Edebiyatı','Şiir','Ebru Rabia Berkul']::text[], 8.5, '{"poet":"Ebru Rabia Berkul","poet_slug":"ebru-rabia-berkul","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/elele-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
