INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz / Siyah', 'beyaz-siyah-ali-isik-ybu15', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sevdaya bulanmış ellerim boyuyor 

gönül sayfalarımı

beyazdan siyaha dönen satırlarım 

içime dökülüyor

gülün rengi yağıyor yüreğe

kalem

gün batımı kızıl..lığında..

uç veriyor

özlem

ruhuma batıyor..

21 kasım 2005', 'sevdaya bulanmış ellerim boyuyor  gönül sayfalarımı beyazdan siyaha dönen satırlarım  içime dökülüyor gülün rengi yağıyor yüreğe kalem gün b...', ARRAY['Türk Edebiyatı','Şiir','Ali Işık']::text[], 8.5, '{"poet":"Ali Işık","poet_slug":"ali-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/beyaz-siyah-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökler ağlıyor yine,', 'gokler-agliyor-yine-ali-osman-yilmaz-2h2o0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gökler ağlıyor yine,

Bende ağlıyorum,

Ayıp değil ya,

Her yan ıslak,

Ben sırılsıklam,

Ellerim ceplerimde,

Dolanıyorum şaşkın.

Sabah gün doğacak,

Güneş açacak yeniden,

Yağmurlarla birlikte,

Gözyaşlarımda kuruyacak,

Buhar olup yeniden,

Göklere çıkacak,

Yağmur bulutu olarak,

Yeniden yağacak,

Ey sevdiğim kadın,

Yağmur yağdığında saçların,

Göz yaşlarımla ıslanacak.', 'Gökler ağlıyor yine, Bende ağlıyorum, Ayıp değil ya, Her yan ıslak, Ben sırılsıklam, Ellerim ceplerimde, Dolanıyorum şaşkın. Sabah gün doğac...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gokler-agliyor-yine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstiyorum', 'i-stiyorum-cemile-duzgun-bzomq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Geldik, gidiyoruz işte bu handan

Dostça uzanacak el istiyorum.

Bir hışımla gelip geçen zamandan,

Hâlâ bahar yüklü dal istiyorum...

Düşmanım olsa da küsmek yok bana,

Karıncaya bile basmak yok bana,

Yaprak incitecek esmek yok bana,

Gönlümün yönünde yel istiyorum...

Nefretin, öfkenin öldüğü yere,

Mertliğin, sevginin dolduğu yere,

Vuslatın izinsiz daldığı yere,

Çabuk sürükleyen sel istiyorum...

Hiç bir tutulur mu söken ekenle,

Sefasını süren cefa çekenle? 

Ne de çok yakışır çalı dikenle

Dalında güzeldir, gül istiyorum...

Sevmeyi bilmeden yaşarım deme! 

Daha mum olmadan ışırım deme! 

Gönlüne karalar taşırım deme! 

Sevdanın rengidir, al istiyorum...

Ekinler gelirken keskin orağa

Hazanlar düşmekte yeşil yaprağa! 

Cemo‘da gidecek bir gün toprağa! 

Bedenime uyan sal istiyorum...

Cemile Düzgün', 'Geldik, gidiyoruz işte bu handan Dostça uzanacak el istiyorum. Bir hışımla gelip geçen zamandan, Hâlâ bahar yüklü dal istiyorum... Düşmanım ...', ARRAY['Türk Edebiyatı','Şiir','Cemile Düzgün']::text[], 8.5, '{"poet":"Cemile Düzgün","poet_slug":"cemile-duzgun","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/istiyorum-63-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Yâr', 'o-y-r-sair-mustafa-turani-z3lbk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'O var,  O yâr,  O hak

Var  O,  yâr O,  hak O

O yâr,  O hak,   O var

Yâr  O,   hak  O,  var O 

O hak,  O var,   O yâr

Hak O,  var O,   yar O', 'O var,  O yâr,  O hak Var  O,  yâr O,  hak O O yâr,  O hak,   O var Yâr  O,   hak  O,  var O  O hak,  O var,   O yâr Hak O,  var O,   yar O...', ARRAY['Türk Edebiyatı','Şiir','Şair Mustafa Turani']::text[], 8.5, '{"poet":"Şair Mustafa Turani","poet_slug":"sair-mustafa-turani","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/o-yar-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi Üzüldüm', 'simdi-uzuldum-ramazan-ates-59uu0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Elini tutmadım incinir diye,

Gözüne bakmadım yorulur diye,

Ben seni sarmadım söz olur diye,

Sen gidip elleri nasıl sararsın? 

Öpmedim korkudan canın yanmasın,

Saçını okşarken telin kopmasın,

Ben senin yüzüne yüzüm değmezken,

Sen gidip ellere nasıl sarıldın? 

Bir çiçektin koklamaya kıymazdım,

Bir can idin, okşamaya kıymazdım,

Pişman oldum etmediğim şeylere,

Nasıl gidip sen sarıldın ellere,

Madem gidip sen sarıldın ellere.

Ramazan Ateş/ Enschede', 'Elini tutmadım incinir diye, Gözüne bakmadım yorulur diye, Ben seni sarmadım söz olur diye, Sen gidip elleri nasıl sararsın?  Öpmedim korkud...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/simdi-uzuldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'B i r', 'b-i-r-sair-mustafa-turani-igt2f', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Allah     bir,        Allah    büyük

Bir        Allah,     büyük Allah

Allah     büyük,   Allah   bir

Büyük   Allah      bir      Allah', 'Allah     bir,        Allah    büyük Bir        Allah,     büyük Allah Allah     büyük,   Allah   bir Büyük   Allah      bir      Allah...', ARRAY['Türk Edebiyatı','Şiir','Şair Mustafa Turani']::text[], 8.5, '{"poet":"Şair Mustafa Turani","poet_slug":"sair-mustafa-turani","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/b-i-r-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eğer Bu Aşk Değilse', 'eger-bu-ask-degilse-cemile-duzgun-7bqi8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'EĞER BU AŞK DEĞİLSE

Hayalinle gülümser,günüme tat katarım,

Afacan duyguları yüreğime bir sorun

Gözgöze değdi diye divaneden beterim

Eğer bu aşk değilse,bana aşkı gösterin..! 

Sevdası öyle tutkun,sarar bütün bedeni,

Her nefesim kokluyor,değmediğim o teni

Sesindeki o ahenk sürüklemekte beni

Eğer bu aşk değilse,bana aşkı gösterin...

Aslı,Kerem’e nasıl yanmış anladım işte

Şirin’i görüyorum,çareler tükenişte,

Hangi his var Ferhat’a dağları deldirişte? 

Eğer bu aşk değilse,bana aşkı gösterin...

Karoğlan’a Karakız olmadım mı sandınız,

Belki siz de bu hasret ağında kıvrandınız,

“Her yaşta aşk mı olur” derseniz aldandınız,

Eğer bu aşk değilse bana aşkı gösterin...

Dar gelirken çemberler,giderek genişliyor

Esmer gecelerime gün iksiri işliyor,

Acaba neyin lütfu kanımı ateşliyor,

Eğer bu aşk değilse bana aşkı gösterin...

Coşkusunu tatdığım yanım var O’na feda,

Alevini kattığım kanım var O’na feda,

Kıymetli birşeyim yok,canım var O’na feda

Eğer bu aşk değilse bana aşkı gösterin...

Cemile Düzgün      aralık 2004', 'EĞER BU AŞK DEĞİLSE Hayalinle gülümser,günüme tat katarım, Afacan duyguları yüreğime bir sorun Gözgöze değdi diye divaneden beterim Eğer bu ...', ARRAY['Türk Edebiyatı','Şiir','Cemile Düzgün']::text[], 8.5, '{"poet":"Cemile Düzgün","poet_slug":"cemile-duzgun","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/eger-bu-ask-degilse-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Affet', 'affet-sair-mustafa-turani-149qs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Allah''ım ne olur affet beni

Ne olur affet beni Allah''ım

Affet beni Allah''ım ne olur

Beni Allah''ım ne olur  affet.', 'Allah''ım ne olur affet beni Ne olur affet beni Allah''ım Affet beni Allah''ım ne olur Beni Allah''ım ne olur  affet....', ARRAY['Türk Edebiyatı','Şiir','Şair Mustafa Turani']::text[], 8.5, '{"poet":"Şair Mustafa Turani","poet_slug":"sair-mustafa-turani","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/affet-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sormalı Sana', 'sormali-sana-cemile-duzgun-q1z5r', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'SORMALI SANA

Kadrin,kıymetinle,sevginle dolup

Taşarak bir ömrü vermeli sana

On sekiz içinde bir huri olup

Telli duvaklarla ermeli sana...

Nadir tomuruklar açsın eyvana

Bütün renkler çelenk kursun odana

Helali-hoş olsun ye kana kana

Ballı meyveleri dermeli sana...

Hasret çoğu değil,azıdır karar

Can’ın uzaktaysa gün neye yarar

Senli düşlerimi bir korku sarar

İpekten bir koza örmeli sana...

Hep böyle sevdanla yanıp tüterken

Gözlerim engine dalıp giderken

Saçımı ak teller talan ederken 

Sen neyi beklersin sormalı sana..? 

Cemile Düzgün-2004', 'SORMALI SANA Kadrin,kıymetinle,sevginle dolup Taşarak bir ömrü vermeli sana On sekiz içinde bir huri olup Telli duvaklarla ermeli sana... Na...', ARRAY['Türk Edebiyatı','Şiir','Cemile Düzgün']::text[], 8.5, '{"poet":"Cemile Düzgün","poet_slug":"cemile-duzgun","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sormali-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günebakan', 'gunebakan-hatice-berk-ener-i4df8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Eli şakağında düşünmeyi bilir misin

Günebakanlar  neden doğuya bakar

Asildir ışığı aydınlığı sever Günebakanlar

Kaldırımları bıçak gibi kesen

Ayakları çıplak çocukları bilir misin

-Su küçüğün söz büyüğün- davalarında

Bedenleri kurşunlara mezar olan çocukları

Her nisan yağmurunda damı akan memleketi

Leğende birikmiş çorak fikirleri

Pişti bu aşk 40 yıl pişti

Artık götürmüyorlar

Selamsız sabahsız prangalara

Sana bir iyilik

En güzel eli şakağında düşünmeyi

Sana bırakayım

Ben 

Dikenli tarlaları yakarken

Sen

Katibimin setresi uzun şarkısını söylerken

Günebakanlar yine doğuya baktı

Hatice Berk Ener', 'Eli şakağında düşünmeyi bilir misin Günebakanlar  neden doğuya bakar Asildir ışığı aydınlığı sever Günebakanlar Kaldırımları bıçak gibi kese...', ARRAY['Türk Edebiyatı','Şiir','Hatice Berk Ener']::text[], 8.5, '{"poet":"Hatice Berk Ener","poet_slug":"hatice-berk-ener","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gunebakan-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadın..ım', 'kadin-im-ali-isik-jtggt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ne güzlerin yağmuru silebildi resimlerdeki yürek izini

ne yazların güneşi kurutabildi gözyaşlarımı

döktüğüm yapraklarımda daldığım bahar sonları

uyanamadı ilk olanlarıma

donmadı sevgim kışların ayazında

artık unuttuğum kaçıncı 

hiç bir mevsimim

yağmadı ısıtmadı esmedi sarmadı 

sevmedi.. beni.. inan

senden sonra

sensiz olanlarımda

kadın..ım

öylesine içimdesinki

hala

                                    

17 kasım 2005', 'ne güzlerin yağmuru silebildi resimlerdeki yürek izini ne yazların güneşi kurutabildi gözyaşlarımı döktüğüm yapraklarımda daldığım bahar son...', ARRAY['Türk Edebiyatı','Şiir','Ali Işık']::text[], 8.5, '{"poet":"Ali Işık","poet_slug":"ali-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kadin-im-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşünme', 'dusunme-cemile-duzgun-grs09', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bilmem kaç asır geçti,ellerini çekeli,

Aklından geçirdin mi seni unuttuğumu.

Yüreğim yangın yeri,ilk kıvılcım çıkalı,

Düşünme o tadına,başka tat kattığımı...

O tat bütün dünyamı tek sana toplamakta,

Öteki ufukları bir perde kaplamakta,

Anılar yüreğime hançerler saplamakta,

Düşünme o tadına başka tat kattığımı...

Seninle geçen zaman,bir ömür sayıldı ya! 

Sıcak bakışların her anıma yayıldı ya! 

Nakış misali aşkın gönlüme oyuldu ya! 

Düşünme o tadına başka tat kattığını...

Hiç yerime koydun mu delifişek yanını,? 

Ağrılar zehretti mi,gününü,zamanını? 

Yıldızlar sürükleyip aldı mı sultanını? 

Düşünme o tadına başka tat kattığımı...

Cemile Düzgün-ağustos/03', 'Bilmem kaç asır geçti,ellerini çekeli, Aklından geçirdin mi seni unuttuğumu. Yüreğim yangın yeri,ilk kıvılcım çıkalı, Düşünme o tadına,başka...', ARRAY['Türk Edebiyatı','Şiir','Cemile Düzgün']::text[], 8.5, '{"poet":"Cemile Düzgün","poet_slug":"cemile-duzgun","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/dusunme-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Sevgili', 'eski-sevgili-ali-isik-5aa1p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'tutmadım öpücüklerimin çetelesini

hesabını yapmadım göğsüme yatışlarının

saymadım seni kaç kez sevdiğimi söylediğimi

kaydı yok sayfalarımda bana sarılışlarındaki sıcaklığın

çentik atmadım sen benim her şeyimsinlerine

hatırlamak için yaşamadım ki ikimizi

yaşananlar yaşandığı anlarca

hatırlamak için yaşanmaz ki

sevmiştik hepsi hepsi

ama, önemlisi..

bin yıl geçti sana gözlerimde ilk seslenişimin üzerinden

on asır, dile kolay 

duyduğum ilk güzel sözlerinin ruhuma değişinden

sanki hep doğar gibiyim

hiç ölmeyecekmişimcesine

kapı aralığım kadar yakın dünüm bugünüme

her daim tazem, sevdiceğim

bin yıl önceki evvelsi günüm

öylesine uzak

öylesine yakınım

bilinmeyenlerime

üzerine şiir yazılan eski sevgili

şimdilerde kendince

bilmem … hangi … senesinde…

26 kasım 2005', 'tutmadım öpücüklerimin çetelesini hesabını yapmadım göğsüme yatışlarının saymadım seni kaç kez sevdiğimi söylediğimi kaydı yok sayfalarımda ...', ARRAY['Türk Edebiyatı','Şiir','Ali Işık']::text[], 8.5, '{"poet":"Ali Işık","poet_slug":"ali-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/eski-sevgili-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Turanî'' den Vecizeler -2', 'turan-den-vecizeler-2-sair-mustafa-turani-9qynf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '* Geçmişini inkar, gençliğini ihmâl eden bir millet

   geleceğinin katilidir.

* Sahipsizlikten fuhşa düşmüş bir kadının

   fuhşu, toplumun fuhşudur.

* Ana vatan kadar güzel,

   baba hürriyet kadar tatlıdır,

* Kainatın lisanı hikmetçedir.

* Gül için bakanlar dikenleri görmezler.

* Namaz gurura değil,

   şuura vesiledir.

* Müslüman''a ne oldu da Allah denilince gocunuyor.

* O''nu biliyiorum, O biliyor, O''nu diliyorum.

* Duâ hak etmektir.

* Rasülullah''ın konu ve konuk edilmediği ortamlarda

  bulunmaktan ar ederim.

* Nefsimde gördüğüm, tıpkı bir kördüğüm,

  ezmeye öcüm, çözmeye gücüm var.

* Başımıza ne geldi ise, başımızdan geldi.

* Sözümüzü unuttuk, özümüzü kuruttuk.

* Dünyayı sevmiyorum çünkü ahmak değilim.

* Kısık sesler, raksı sedadan yoksundur.

* Kul göstersin diye hüner

  Allah kulunu hep dener.

*Gençler sizden çok şey öğrendim,,,

  Hele hele ihmali.

* Akleden affeder.

*Ey insan... Doğumun yeni hatırlatmıştı ölümün neyi hatırlatacak,

  ağlayarak gelişinle sevindik gülerek gidişin ağlatacak.', '* Geçmişini inkar, gençliğini ihmâl eden bir millet    geleceğinin katilidir. * Sahipsizlikten fuhşa düşmüş bir kadının    fuhşu, toplumun f...', ARRAY['Türk Edebiyatı','Şiir','Şair Mustafa Turani']::text[], 8.5, '{"poet":"Şair Mustafa Turani","poet_slug":"sair-mustafa-turani","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/turani-den-vecizeler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm', 'olum-adnan-serifoglu-gh0v2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ölüm nemdir benim

Yoklar durur zamansız

Nerdendir ülfetimiz

Bu senli benli halimiz

Ne zaman kuruldu bilinmez

Dünyalık hiç bir dost

Beni ölüm kadar sevmez', 'Ölüm nemdir benim Yoklar durur zamansız Nerdendir ülfetimiz Bu senli benli halimiz Ne zaman kuruldu bilinmez Dünyalık hiç bir dost Beni ölüm...', ARRAY['Türk Edebiyatı','Şiir','Adnan Şerifoğlu']::text[], 8.5, '{"poet":"Adnan Şerifoğlu","poet_slug":"adnan-serifoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/olum-237-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kül Rengi', 'kul-rengi-firat-ulker-d1hlc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Güneşin gözlerine

Beyaz bir bez parçası bağladım yine

Körebe oynuyoruz

İlkdördündü başladığımızda

Şimdi ise dolunay

Ben kaçtıkça o kovalıyordu

Ben akreptim o yelkovan

Gözleri bağlıydı ama benden hızlı koşuyordu

Güneş saatinin resimsiz takviminde

Her saat başında,yapışıyordu enseme

Artık dizlerim taşıyordu beni

Ekleminden bükülmüştü bacaklarım

Çölün en ortasında,ufak bi tepede

Çökmüştüm her şeye razı

Ve güneş tam üzerimdeydi

Kavuruyordu beni

Alnımdan süzülen ter de cabası

Çatlamış dudaklarıma işliyordu kokusu

O koca,kurak çölü yuttum bi lokmada

Rakı şişesiydim

Kum gibi çalıyordu

Saati olmuştum

Bir ayaklarımın bir başımın üzerindeydim

İçimde kum şelalesi

Bende durduğu gibi durmuyordu

İçtikçe dönüyordu dünya

Döndükçe içiyor

Çürümüş bedenimden metan gazı çıkıyordu

Yıldız kayınca

Dünya bi cigara daha yakıyordu

Ve bu sonsuz karanlık rengini

Sadece külden alıyordu

Şimdi uçuyorum bu boşlukta

Omzumda bir çift anka kanadı

Sonra bir metal uzayı

Yüreğimin tam ortasında

Düşerken,güneşe çarptım

Sardım bedenime bez parçasını

Küllere bulandım

Başımın ucunda bi göktaşı

Anlayacağınız

Artık açabilirsiniz vanaları

Tabi kaldıysa Fırat''ın

Acı,hırçın,asi damlaları..

                                                                           09.06.05/02_40', 'Güneşin gözlerine Beyaz bir bez parçası bağladım yine Körebe oynuyoruz İlkdördündü başladığımızda Şimdi ise dolunay Ben kaçtıkça o kovalıyor...', ARRAY['Türk Edebiyatı','Şiir','Fırat Ülker']::text[], 8.5, '{"poet":"Fırat Ülker","poet_slug":"firat-ulker","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/kul-rengi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuklaların Dansı', 'kuklalarin-dansi-sultan-mustafa-1cyts', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İyi yüzerdiniz siyah zamanlarda

Meneviş feryatlar asılırdı kirli tırnaklarınıza

Sabaha karşı...

Genç bir kız çığlığı alırdınız

Uyku öncesi

Rüyalarınız zakkum renkli kız

Ve siz kanla uyanır kanla pudralanırsınız

Ki

Her gecenin sonunda 

Kahvaltınız tüysüz yetim aşı...

Hadi 

Şaklatın kamçılarınızı

Yılan dilli kuklalarım

Hani

İsa’yı çarmıha geren kamçılar vardı ya

-Deve böğürtüleri çıkardı uçlarından 

Ateşler saçardı cehennemden sipariş-

İşte onları, öylece şaklatın.

Çarmıhtaki adam inlemezdi

Kamçılar kadar

Bir siz inlerdiniz şak-şaklarınızla

Akşamdan geceye

Geceden geceye

Gündüz hiç olmadı kamçılarınızda

Siz, önce, geceye mahkumdunuz

Güneş görmemiş gözlerinizde

Ses, kamçılardı

Işık, şak-şak

“Hani durmasak 

Şak-şak

Çarmıhtaki adamı oynasak

                      gün doğumlarında”

Diye bağırmayın...

Çarmıhtaki adam güneş oldu

Güneş oldu

Yumun gözlerinizi bari

-Nankörler öyle yapar-

Yumun gözlerinizi gayri

Olmaz mı kuklalarım.

Ey nasibi göz yaşı olanlar

Arı, karınca ve bilumum çalışkanlar

Haydi çalışın çalışın insanlar

Geceye çığlıklar üretin

Kuklalar sizi bekliyor 

Ki

Kamçılar, arkadaşı...', 'İyi yüzerdiniz siyah zamanlarda Meneviş feryatlar asılırdı kirli tırnaklarınıza Sabaha karşı... Genç bir kız çığlığı alırdınız Uyku öncesi R...', ARRAY['Türk Edebiyatı','Şiir','Sultan Mustafa']::text[], 8.5, '{"poet":"Sultan Mustafa","poet_slug":"sultan-mustafa","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/kuklalarin-dansi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Dokunmak İsterdim', 'sana-dokunmak-i-sterdim-diyarbakirli-sedat-kr1vc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sana dokunmak isterdim.

Her yanı başımda oturdugunda,

Anlatmak isterdim,

sevdamı.

Kacamak bakışlarında.

Yaşamak isterdim seninle,

sonsuzlugu.

O sıcacık kucagında.

Narin ellerini, ellerime almak

Bakışlarını,gülüşlerini

Katardım rüyalarıma.

Ve... gezdirmek isterdim

ellerimi,

Tel tel olan saçlarında.

Sana dokunmak isterdim.

Nefesini,nefesime katıgımda.

Kıskanırdı gözlerim,

Kıskanırdı dudaklar,

Seni anlattıgımda.

Darılırdı bana,

Tüm anlamlı anlamsız kelimeler

Seni her çagırışımda.

Sana dokunmak isterdim.

rüyalarımda.

Sevgi nüverelerinin yeşerip

Meyvalarını almak isterdim,

Diclenin kenarında.

Adlarını koymak isterdim sevgi meyvalarımızın

Diyarbekirin tarih kokan surlarında; 

-biri Rojhat,

-biri Öykü

Özgürlüğümüzü yaşatırcasına...

Sana dokunmak isterdim.

Duygularımın en doruk oldugu hareretlede.

Yanına sokulup

Masum günahlarla

Aşkın şarabını tattırmak isterdim,

Bedeninde...

Ve...

Sana dokunmak isterdim.

Saniyenin her salisesinde.

Ama

Korkardım sana dokunmaktan.

Dokunsam

Sanki bu büyünün bozulacıgından,

Bu rüyadan uyanacagımdan.

korkardım.

Sana dokunmaktan korkardım.......,

,

,

Sedat OĞUZ,

DİYARBAKIR 2005', 'Sana dokunmak isterdim. Her yanı başımda oturdugunda, Anlatmak isterdim, sevdamı. Kacamak bakışlarında. Yaşamak isterdim seninle, sonsuzlugu...', ARRAY['Türk Edebiyatı','Şiir','Diyarbakırlı Sedat']::text[], 8.5, '{"poet":"Diyarbakırlı Sedat","poet_slug":"diyarbakirli-sedat","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/sana-dokunmak-isterdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pes-Ettiren', 'pes-ettiren-firat-ulker-gzni8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Resmini çizemem ya güzelim

Yeteneğim yok

Yeteneğim olsa

Benzerin yok

Hayal etsem

Ona bile sığmıyorsun

Bak yazmaya çalışıyorum

O da olmuyor

Allahım yaratmış ben tanımlayamıyorum

Sen kimsin,nesin,ne biçim bir şeysin

Neye benzersin in misin,cin misin

Nasıl yapmalı ne etmeli de

Tarifini insanlığa vermeli

Gözüm görüyor seni,kalbim duyuyor

Ama.,

Dünya nimetleri yetmiyor be güzelim

Bari sen anlat,sen söyle

Bende yazayım,çizeyim,çalayım seni

Oysa ortak yanların çok bizimle

Kaşın,gözün,kulağın,saçın

Farkın ne bi türlü bulamıyorum

Yaradanın benzersiz fırçasından çıkmış bi tablo

Huzurun marşını iliklerimde hissettiren bi ses

Şairin keskin kalemini kıran bi teman var

N''apayım ben ya

Zırıl zırıl ağlayacağım şimdi bebekler gibi

Salya-sümük oturacağım şurda

Emziğimi ver diye bağıracağım

Ben vazgeçtim güzelim seni anlatmaya

Varsa delikanlı çıksın ortaya

Pes valla

Bu kadarı da pes..', 'Resmini çizemem ya güzelim Yeteneğim yok Yeteneğim olsa Benzerin yok Hayal etsem Ona bile sığmıyorsun Bak yazmaya çalışıyorum O da olmuyor A...', ARRAY['Türk Edebiyatı','Şiir','Fırat Ülker']::text[], 8.5, '{"poet":"Fırat Ülker","poet_slug":"firat-ulker","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/pes-ettiren-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Dair...', 'bana-dair-diyarbakirli-sedat-odnfq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bana,

Sabahlara kadar aglamam için

Sonu ayrılıkla biten,

bir sevda bıraktın,yüreğimin derin

yerinde...

Bana,

Gözlerimin hakketmediği kadar

gözyaşları.

Dudaklarımın okuyamayacagı

Yedi harfli bir mektup(ayrılık)  bıraktın,

geride.

Bogazımı döğümlercesine...

Bana,

Buzlu ve soguk bir vedayla,

Parıldayan gözler yerine,

Buruk bir özlem çeken

Titrek ve korkak bakışlar

Bıraktın,

Geride...

Bana

Hatırlamak niyetiyle

Yırtık bir resim

Artık bu yüreğin sevmemesi için

Küçücük bir kutu içinde

Bir hediye bıraktın:

''''ihaneti bıraktın''''

Geride

Ve...

Bana

Bana dair seni bıraktın

Hasretin ötesinde

Ve de.. bu gecenin derin sesizliğinde

Ölümün ötesinde...

''''seni bıraktın''''.....

Diyarbakır

Sedat oğuz', 'Bana, Sabahlara kadar aglamam için Sonu ayrılıkla biten, bir sevda bıraktın,yüreğimin derin yerinde... Bana, Gözlerimin hakketmediği kadar g...', ARRAY['Türk Edebiyatı','Şiir','Diyarbakırlı Sedat']::text[], 8.5, '{"poet":"Diyarbakırlı Sedat","poet_slug":"diyarbakirli-sedat","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/bana-dair-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eksi sonsuzdan Artı sonsuza', 'eksi-sonsuzdan-arti-sonsuza-firat-ulker-2w7n2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sayısız sayılarım var elimde

Say say bitmiyorlar

Her sayım gününde

Sayılarıma bir sayı daha ekleniyor

Artık benim için her gün sayım günü

Sokağa çıkma yasağı var sonsuza kadar

Müebbet hapis içimde sayılarım

Ve ben şimdi

Sayıların sonu ne zaman gelecek biliyorum

İçime sığmayıp patladıklarında

Yasakları çiğneyip beni vurduklarında

Ben parçalandığımda,onlar yere dökülecek

Hadi bakalım bi de siz sayın

1,2,3,4,,,,,,,,,

Kaç tane

Sayın bakalım sayın

Sonunda beni bulacaksınız

Resmimi sayılarla çizeceksiniz

-&''dan.........&''a

İşte benim,sonsuzluk

Silip bi daha sayın

Bana kadar sayın

Bi seri katil olun

Diğerlerinden farkınız

Cinayetleri tek kişide işlemek

Sıkılırsan diğerine bırak görevi

Bu sefer de seri,seri katiller olun

Hadi kolay gelsin..

                                                           24.10.05/01_44', 'Sayısız sayılarım var elimde Say say bitmiyorlar Her sayım gününde Sayılarıma bir sayı daha ekleniyor Artık benim için her gün sayım günü So...', ARRAY['Türk Edebiyatı','Şiir','Fırat Ülker']::text[], 8.5, '{"poet":"Fırat Ülker","poet_slug":"firat-ulker","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/eksi-sonsuzdan-arti-sonsuza-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beddua', 'beddua-aysun-bekci-o214b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'melektiler melektiler

dağı taşı yol ettiler

gurbet eli yar ettiler

gidin artık yaban ile

sevdiğimi bildirmedin

yüzümü hiç güldürmedin

cefan kime idi ey dost

bana niye çektirdin

acımı bana verensin

derdimi dert eden sensin

mevlam dertler sana versin

gidin artık yaban ele

ALLAh büyük sığındım ona

senin cezan kalsın ona

sevmemi çok gören sana

mevlam dertler versin versin

acımı bal eyledim 

yüreğime kilitledim

mevladan diledim

yeter artık sevmeyeceğim..', 'melektiler melektiler dağı taşı yol ettiler gurbet eli yar ettiler gidin artık yaban ile sevdiğimi bildirmedin yüzümü hiç güldürmedin cefan ...', ARRAY['Türk Edebiyatı','Şiir','Aysun Bekçi']::text[], 8.5, '{"poet":"Aysun Bekçi","poet_slug":"aysun-bekci","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/beddua-74-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdalı Serseri', 'sevdali-serseri-salim-erben-jn154', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben bu dağların haşarı çocuğu

Bana düşmez 

Yumuşak kucakta can vermek

Bir tas çorba

Bir sıcak ekmek 

Yakışmaz bana sensiz ölmek 

Bu benim kara yazım

Kim bilecek  kim görecek

Ben seçmedim bu sevdayı

Varmı seni ben gibi sevecek

Tam bir serseriyim

İki yanımdan aksın korkularım 

Sesimi aç kurtlar dinlesin

Aslan gibi gözüken

Tavşan kadar ödlek

Tilki gibi kurnaz ve sinsi

Çakallara yem olma yüreğim

Alın gündüzler sizin olsun 

Verin karanlıkları bana

Islak bir yorgan gibi 

Alsın alnımda ki bu ateşi

Sarsın karanlıkları

Kim tanır ölse kim bu

Kim bu  serseri sevdalıları', 'Ben bu dağların haşarı çocuğu Bana düşmez  Yumuşak kucakta can vermek Bir tas çorba Bir sıcak ekmek  Yakışmaz bana sensiz ölmek  Bu benim ka...', ARRAY['Türk Edebiyatı','Şiir','Salim Erben']::text[], 8.5, '{"poet":"Salim Erben","poet_slug":"salim-erben","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sevdali-serseri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hesaplaşma', 'hesaplasma-firat-ulker-fqpyg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir sigara daha sarıyorum

Yine sözünü dinlemiyorum biliyorum

Kendi ciğerlerimi karartırken

Seninkileri de sızlatıyorum

Affet bebeğim

Sensizliğe dayanamıyorum

Kendimi is rengi dumana bırakıp

Uzaklara dalıyorum

Ben tüm acılarımı sigaraya gömerken

O''da tüm zehrini bana akıtıyor

Bir tür hesaplaşma bu

Her nefeste ikimizde birbirimizden

Bi parça koparıp

Ölüme yaklaştırıyoruz

Her gün,her çakmak sesinden sonra.', 'Bir sigara daha sarıyorum Yine sözünü dinlemiyorum biliyorum Kendi ciğerlerimi karartırken Seninkileri de sızlatıyorum Affet bebeğim Sensizl...', ARRAY['Türk Edebiyatı','Şiir','Fırat Ülker']::text[], 8.5, '{"poet":"Fırat Ülker","poet_slug":"firat-ulker","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/hesaplasma-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakış', 'bakis-aysun-bekci-ndzmm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ağladım kimseler duymadı

bakışların yüreğime işledi

bir söz bekledim senden.

gitme... diyen olmadı', 'ağladım kimseler duymadı bakışların yüreğime işledi bir söz bekledim senden. gitme... diyen olmadı...', ARRAY['Türk Edebiyatı','Şiir','Aysun Bekçi']::text[], 8.5, '{"poet":"Aysun Bekçi","poet_slug":"aysun-bekci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bakis-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hz. DAVUD (AS)', 'hz-davud-as-abdullah-yasar-erdogan-ro9ww', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '(19. Kitab verilen, Büyük Peygamber) 

           Hz.  DAVUD  (AS)

Davud; “Kitâb-ı Mukaddes’te” David,

Her kitap etmektedir O’nu  teyid,

“En çok sevilen kişi, göz bebeği”

İbranice’de bu anlamda, Davud. 

Davud; kızıl saçlı, sarı benizli,

Mavi gözlü, gür ve de güzel sesli,

İyi huylu, anlayışlı, pek güçlü,

Bilinir; çok bilgili, temiz kalpli.

Yahudi zihniyeti daima belli,

Zengin olandan Peygamber gelmeli,

Meşhur sülale hep çıkardı öne,

Kendinden olmayanı hiç sevmezdi.

Talut; Yahudilere oldu lider,

O insanları Hakk’a davet eder.

Filistin lideri Calut’a savaş,

Talut; “Orduya suyla imtihan” der.

Ordu dinlemez O’nu, suyu içti,

Talut’un emri böyle dinlenmedi.

Talut, nehri geçti sabredenlerle,

Talut, Rabbinden yardım istemişti.

Davud; Talut’un ordusunda asker,

O sabırda, irade de bir lider.

Talut O’na verdi ordu sevkini,

O’nunla ordu başarıya gider.

Hakk emriyle Davud yendi Calut’u,

Allah’ta başa getirdi Davud’u.

Kur’an; Bakara’da bunu anlatır,

Cenab-ı Hakk kudretli kıldı O’nu.

Calut’u yenen Davud takdir aldı,

Talut, Davud’un aşkını kıskandı.

Talut, Davud’a hasetle bakarken,

Çok defa öldürmeye kalkışmıştı.

Bir zaman sonra Celbu harbi oldu,

Yahudiler bu savaşta mağlup oldu.

Filistin okçuları aman vermez,

Oklayıp öldürmüşlerdi Talut’u. 

Talut ölünce savaş sonar erdi, 

Davud; Medinetü’l-Halil’e  gitti.

Yehûda’nın adamları gelerek,

Davud’u hükümdar ilan etti. 

Talut’un oğlu biat etmemişti, 

O Eşboşt’a çok kişi boyun eğdi.

Davud’a inanana açtı savaşı,

Bir savaşta hayatını kaybetti.

Davud, dört kısma ayırdı günleri,

O bir kısmında ibadet ederdi.

Bir kısmında hüküm, kalanı vaaz,

Bir kısmında ise şahsi işleri.

Bir gün iki hasım geldi huzura,

“Bizi ilet doğru ve açık yola”

Konuya vakıf olup dinler, Davud.

O, Allah tarafından sınanmakta.

Davud, diledi Rabbinden Mağfiret,

Sonunda dedi; “Duamı kabul et,”

Rabbim buyurdu O’na ihsanını,

“Kalk Davud’um Hakk davayı tebliğ et.”

Böylece verildi o kutsal görev,

Hakk kelamını konuşmak ilk ödev,

“Seni yeryüzünde halife kıldık”

Rabbim ister O’ndan, hükmü hakça ver.

Hakk der; “Biz, Davûd’a Zebûr’u verdik,

O’nu size Hakk elçisi gönderdik.”

Sonradan tahrif edilmiştir Zebûr,

Kur’an gerçeğiyle O’nu hak bildik.

Davud soyu, İbrahim’e dayanır.

Musa’nın şeriatıyla inanır,

Zebûr’un dili İbranice olup,

Zebûr’un yüz elli sûresi vardır.

Zebûr’un hükmü, Tevrat ile aynı,

Kuşlar bile Davud’a duyar saygı.

Çok güzel de sesi vardır O kulun,

“Davûdi ses” işte ondan kaldı.

Değiştirilmiş Zebur yalan dolu,

Kur’an’da söylenmekte, Zebur doğru.

Ahd-i Atik O’nu suçlu gösterir,

Kur’an ispatlar yalan olduğunu.

Ahd-i Atik, zina istinat eder,

Oysa Peygamberliğe bu ters düşer.

O yalancı kavim hep şetmetmekte,

Cenab-ı Allah Kur’an’da hep över.

Hz. Davud, Hakk dininde muttasıftır,

Allah O’nu Kur’an’da has anlatır.

Darlıkta, bollukta tevekkül eder,

Dağları O’na musahhar kılmıştır.

Hz. Davud’a özel ilim verilmişti,

Kuşlar kendisiyle tesbih ederdi.

Dağların zikrini de duyardı o,

Sabahlara kadar ibadetteydi.

Davud, kurt ağzından kuzu almıştı,

Aslan üzerine biner korkmazdı.

Sapanıyla attığını vuran o,

Geceleri ibadette, o yatmazdı.

Allah katından ilimle donatmış,

O’nun elinde demir yumuşamış,

Savaşta  demirden elbise  ister,

O da demirden vücuda zırh yapmış.

Kızgın demiri eliyle yoğurdu,

Gün aşırı hep oruç tutuyordu,

Kudüs-i Şerif-i başkent yapan o,

Yetmiş yaşında Hakk’a yolcu oldu.

O İsrail oğulları lideri,

Davud; o zaman otuzunda idi.

Otuz üç yıl hükümdar oldu Davud,

Süleyman’ı yerine tayin etti.

Davûd, sapan taşı atmada usta,

Calut’u yenmişti sapanıyla.

Filistin gencinin silahı sapan,

İnsan bakmalı dünyaya Hakk nurla.

Talut: Kur’an tabiridir, Mü’min bir kişidir. Bu hükümdara Yahudi tarihi Şavel demektedir. 

Medinetü’l-Halil: Kenan ilinde bir yer (kasaba) 

Eşboşt: Talut’un oğlu.

Şetmetmek: Sövme, hakaret.

Muttasıf:  Bir özellikle vasıflanmış olan.

Musahhar: Boyun eğmek, ram olmak.

Şair: Abdullah Yaşar Erdoğan', '(19. Kitab verilen, Büyük Peygamber)             Hz.  DAVUD  (AS) Davud; “Kitâb-ı Mukaddes’te” David, Her kitap etmektedir O’nu  teyid, “En ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":117,"source_url":"https://www.antoloji.com/hz-davud-as-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim bilir', 'kim-bilir-firat-ulker-g8f2o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kim bilir

Evet o kim kimse

Her şeyi o bilir

Polisin elinde bi cinayet vardır

Hepsi katilin peşinden koşar

Arar,bulamazlar

Oysa kim''e sorsalar

O hemen bilir

Biri ölecektir kim bilir

Biri doğacaktır kim bilir

Biri sevecek diğeri sevilecektir

Tabi ki kim bilir

Ama ona kimseler danışmaz

Kimseler sormaz

Kim kim''e aşıktır,bilir misiniz? 

Bilmezsiniz

Gidin kim''e sorun

O mutlaka bilir

Kim kim''e aşıktır

Kim''in kim''e aşık olacağını

Nerden mi biliyordu

O bilir

Çünkü kim her kimse

Her şeyi bilir.. 

                                            16.10.05/03-30', 'Kim bilir Evet o kim kimse Her şeyi o bilir Polisin elinde bi cinayet vardır Hepsi katilin peşinden koşar Arar,bulamazlar Oysa kim''e sorsala...', ARRAY['Türk Edebiyatı','Şiir','Fırat Ülker']::text[], 8.5, '{"poet":"Fırat Ülker","poet_slug":"firat-ulker","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kim-bilir-48-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyanın Bayım', 'uyanin-bayim-firat-ulker-m8bp3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Boşlukta sörf yapmaktı tek yaptığı

İçi yer küreye otursada

Ayakları yere değmiyordu

Anlamsızlıklar denizine bırakmış kendini

Oltasını atmış rastgele

Görünüşte sade bi balıkçı

Avın takılmasını bekleyen,sabırlı bi balıkçı

Derya gözünde bir büyüyüp,bir küçülüyor

Bir sağa bir sola sallanıyor

Kırık-dökük sandalında

Oysa deniz öylesine sessiz,öylesine durgun ki

Hiç bir hayat belirtisi yok

Ufak bir esinti,minik bi kıpırdama

Hiç bir şey yok

Tepesinde,neredeyse denizi yok edecek kadar

Etrafı ıstan bi güneş

Onu batmakla tehdit eden eski bi sandal

Kıyıya ulaşamayacak kadar bitkin kendi

Ve onunla dalga geçen bi kaç balıktan başka

AnlAyacağınız yine hiç bir şey yok

Tahmin ettiniz öyle değil mi

İşte beklenen deniz kızı geldi

Sıradan bi hikaye degilmi

Adamı mutlu edecek,onu sıkıntılarından kurtaracak

Onun ümidi,hayali olacak

Evet hayali,rüyası

Bi kaç saniye ne kadar da heyecanlandırmıştı

Ne kadar sevindirmişti adamı

Ama işte o ses..

Uyanın bayım..! 

Yıkılmıştı,kırılmıştı yine herşey

Tekrar boşluğun dalgalarına geri dönüş

Bitmez işkencelerin tam ortasına kesin dönüş

Her zaman ki gibi düşünceler isteklerde,hayallerde kalıyor

Kilometrelerce uzaklartan bi anda geri dönmek

Gerçeği algılamak ne kadar da korkunç

Yıllar böyle tekrarlı anlarla geçiyor

Saçı sakalına,bulanık aklı sığ sulara

Yorgun bedeni sandalın kuru tahtalarına karışıyor

Artık ya bir gemi yanaşacak ve kurtaracak onu

Ya da Azrailin kucağına bırakıverecek titreyerek kendini

Yine,yine bir ses

Bayım bayım uyanın..

Gözlerinin açılmasıyla,kalbinin bi an durup

Sonra hızlı ve şiddetli bir şekilde çarpması

O kısa zaman diliminde gerçekleşirken

Sesin sahibinin onda bir dönüm noktası

Bir hayat belirtisi,hayallerinin gerçeğe dönüşü

Olacağını biliyordu

Sonra bi ara duraksadı adam

Sızdığı yerden yavaş ve dikkatle doğruldu

Siz siz ne arıyorsunuz burda

Nasıl geldiniz,beni nasıl buldunuz

Çok basit dedi kadın

Adam şok üzerine şok yaşıyordu

Ölüme terkedilmişliğin birden dirilmesi

Ne kadar basit olabilirdi ki..

Ben hep burdaydım,içinizde yaşıyordum

Beni siz çağırdınız,bende geldim

Dedi kdın..

Ben daldığınız yer,baktığınız uzaklar

Sıcak bir öpücük,tatlı bir dokunuş

Sonsuz sevginizim

Ben sizim siz de ben

Sizi seviyorum demişti kadın

Tüm bunların üzerine

Adamın yorgun kalbi bu sefer

Gerçekten durmak üzereydi

Beni seviyor musunuz diye sorarken

Sevildiğini hissetmişti

Onun yalancı bi dalga,bi rüzgar olup

Denizin başka bi köşesine atıp terketmeyeceğini

Gözlerindeki parıltıdan

Aynı kaderi paylaşmalarından

Bileklerinden sızan kandan okuyabiliyordu

Hisleri gerçekti bu sefer

Çünkü dokunabiliyordu onlara

Hiç tahmin etmemişti

Göğüsünü dimdik gerebileceğini yalanlara

Sonsuz sevginin ellerde başlayacağına

Ama oldu,başladı ve hepsi gerçekti

Şimdi ikisinin istediği tek bir şey var

Oda sevginin sonsuzluğunu birlikte

Doyasıya tatmak,yaşamak

Bir yunusun kuyruğuna takılıp,ordan uzaklaşmak

Gittikleri yerde yuvalarını kurmak

Şehrin göbeğinde minik,sıcak bir ev

Ve o eve,hatta evrene sığmayan yürekleriyle

Sevgilerini bebeklerine aktarmak..

Çalar saatini kırdı adam

Uyandırılmaya ihtiyacı yoktu artık

Çünkü bi anını bile kaçırmak istemiyordu hayatın

Yeni tanışmıştı onunla

Yıllarca süründüğüne yanıyordu

Arada aklına gelince

Meğer yaşam uzakta değil,

İçindeki kadındaymış

İşte yine bir ses

Bu sefer n''oldu diyeceksiniz

Çok şey çok

Evet evet

Birini seviyorum

Seviyorum seni,çok seviyorum

Kadınım..

                                   25.02.05/21-35', 'Boşlukta sörf yapmaktı tek yaptığı İçi yer küreye otursada Ayakları yere değmiyordu Anlamsızlıklar denizine bırakmış kendini Oltasını atmış ...', ARRAY['Türk Edebiyatı','Şiir','Fırat Ülker']::text[], 8.5, '{"poet":"Fırat Ülker","poet_slug":"firat-ulker","theme":"Türk Şiiri","is_hero":false,"total_lines":105,"source_url":"https://www.antoloji.com/uyanin-bayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizim işte', 'sensizim-iste-naciye-bildim-5mi7y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Umutlarım çoktan yol almış,gidiyor sesizce,

Bir kara bulut kalmış,birde kül yığını üstümde.

sevdanın dumanı tütermi,

Söyle beyhude.

Coşarmı sandın bu can bu bedende

hemde sesizce.

sarılıpta karanlığa sen diye ağlayabilsem,

ağlamak kalsın,bir damla yaş dökebilsem.

Susarmı,sönermi içimdeki yangının alevlerin.

Olmaz böyle şey,haksızlık bu,haksızlık gidişin.

Uzanıp ellerim gökyüzüne,avuç avuç yıldız toplasa

Dizlerim,ayaklarım yollarına adansada...

Susarmı sandın,içimdeki sızım,acım,kaderim

Bir tek kelime işte

           Ben sensizim.....', 'Umutlarım çoktan yol almış,gidiyor sesizce, Bir kara bulut kalmış,birde kül yığını üstümde. sevdanın dumanı tütermi, Söyle beyhude. Coşarmı ...', ARRAY['Türk Edebiyatı','Şiir','Naciye Bildim']::text[], 8.5, '{"poet":"Naciye Bildim","poet_slug":"naciye-bildim","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sensizim-iste-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özledim yine', 'ozledim-yine-zeliha-bicer-dfnnr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Özledim yine

Özlemlere inat

Yollara inat ise

Bekliyorum

Sensizliğe de inat ettim

Söylenmiyorum martılara

Sevgim kadar büyük

Sen kadar güzel

Ve..

Gelişin gibi olmalı kavuşmamız...', 'Özledim yine Özlemlere inat Yollara inat ise Bekliyorum Sensizliğe de inat ettim Söylenmiyorum martılara Sevgim kadar büyük Sen kadar güzel ...', ARRAY['Türk Edebiyatı','Şiir','Zeliha Bicer']::text[], 8.5, '{"poet":"Zeliha Bicer","poet_slug":"zeliha-bicer","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ozledim-yine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çağdaşlık Denen İllet', 'cagdaslik-denen-i-llet-hasan-ulusoy-mkiog', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çağdaşlık Denen İllet

Kahır yükler gönlüme, yaprakların inişi

Elveda sözü gibi acı verir yanarım

Bir köşede üşüyen güz gülüyle donarım

Dikenden yol açılır yol boyunca önüme

Bulutlar engel olur, yeni doğan günüme

Sandalları seyreder, kendimce eğlenirdim

Karşı ki çoraklaşan topraklarda bir zaman

Ağlarım üzerine, diz çökerek her zaman

Fosilleşen balıklar, kahrından yakan güneş

Zamane insanının, zehrinden bıkan güneş...

Koynunda kurbağalar, bağrında gövel ördek

Çay ağzında oynayan, deniz renkli balıklar

Hepsi muhterislerin yüzünden yok oldular 

Dur diyen yok onlara, ne devlet ne de millet

Bitirdi tabiatı, çağdaşlık denen illet', 'Çağdaşlık Denen İllet Kahır yükler gönlüme, yaprakların inişi Elveda sözü gibi acı verir yanarım Bir köşede üşüyen güz gülüyle donarım Diken...', ARRAY['Türk Edebiyatı','Şiir','Hasan Ulusoy']::text[], 8.5, '{"poet":"Hasan Ulusoy","poet_slug":"hasan-ulusoy","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cagdaslik-denen-illet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acı bademler', 'aci-bademler-baykal-kaanalp-pn6vw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir çiçek uzatırız her an

birbirimize

belki de  herkese

tavrımız açık

seçkimiz çok

seçilemeyiz bilesin

dokunur dişimize

acı bademler

unutmak lazım gelirse

hemen unutalım

acılarımızı

birbirimize söylemeden', 'bir çiçek uzatırız her an birbirimize belki de  herkese tavrımız açık seçkimiz çok seçilemeyiz bilesin dokunur dişimize acı bademler unutmak...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/aci-bademler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Solgun bir güneş', 'solgun-bir-gunes-baykal-kaanalp-ht77c', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sinemaskop değil

yaptığımız hatalar

hatta soğuk bile değil

üzerinde düşünüp

tartıştığımız

çekiciliğini hiç kaybetmeyen

solgun bir güneş

ayın bize bağışladığı

her sabah uyandığımızda

birlikte aynı sıcaklıkla', 'sinemaskop değil yaptığımız hatalar hatta soğuk bile değil üzerinde düşünüp tartıştığımız çekiciliğini hiç kaybetmeyen solgun bir güneş ayın...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/solgun-bir-gunes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni sevmenin ötesinde bir haberim yok..', 'seni-sevmenin-otesinde-bir-haberim-yok-zeliha-bicer-w2srf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni sevmemin ötesinde 

Bir haberim yok

Gün batımını izledim 

Seni anarak

Şiir dinletisindeydim bu gün

Yine özlemlerim depreşti

Bilmeden de olsa 

Söylenen tüm sözler 

Beni sana çıkardı

Dediler ki; 

Sev hep sev

Bende seviyorum işte! 

Kendimce..

Hep sana gelerek 

Hep sana çıkarak

Tüm tümcelerimde....', 'Seni sevmemin ötesinde  Bir haberim yok Gün batımını izledim  Seni anarak Şiir dinletisindeydim bu gün Yine özlemlerim depreşti Bilmeden de ...', ARRAY['Türk Edebiyatı','Şiir','Zeliha Bicer']::text[], 8.5, '{"poet":"Zeliha Bicer","poet_slug":"zeliha-bicer","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seni-sevmenin-otesinde-bir-haberim-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aydınlanma', 'aydinlanma-mehme-arslan-4gmf3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'seni

kendime olan saygımdan

ayı diyemediğim o devasa

herifle sarmaş dolaş görünce

karanlıkta üzerine ışık tutulan

tavşan gibi kalakaldım

ortalıkta öylece

10/12/2005', 'seni kendime olan saygımdan ayı diyemediğim o devasa herifle sarmaş dolaş görünce karanlıkta üzerine ışık tutulan tavşan gibi kalakaldım ort...', ARRAY['Türk Edebiyatı','Şiir','Mehme Arslan']::text[], 8.5, '{"poet":"Mehme Arslan","poet_slug":"mehme-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/aydinlanma-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yirmidört Asırdır...', 'yirmidort-asirdir-i-brahim-nazim-ulker-v4qem', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bilir misin hemşerim gurbeti? 

Gurbet günlerini, Filistin askısı geceleri? 

O gecelerde sol yanına vurululan mermileri.

Ardı arkası kesilmeyen yıkılmaları,

Istırap içindeyken bulamadığın sabahları,

Rüyanda erebildiğin vuslatları.

Bilir misin hemşerim? 

Ruhum soyutlarşırken,

Bir hayin gurbet gecesinden,

Hasret ki esir almış içerden! 

Vermiş canı yangınlara,

Savrulurken küllerim bir zalim gecenin ellerinden rüzgara; 

Ölsek mi iyi, yaşasak mı bir gün daha? 

Gurbette zaman nedir bilir misin hemşerim? 

Dondurulmuştur, çakılmıştır zaman,

Duyarsın çakılışın acısını ruhudan! 

Ve dururken kainat; 

Sen gidersin ölüme an be an...

Gurbet mum yakıp ardıklarındır.

Derlerya kaçan büyük balıktır,

Ahh, kaçan canımdır hemşerim! 

Gözlerden kan damlatandır,

Gurbet karanlıktır,

Gurbet vicdansızdır! 

Hemşerim vuslata senin için; 

Yirmidört gün kalmıştır.

Bizde kalan; 

Yimidört bıçak yarası,

Yirmidört ölüm duası,

Ve yimidört asırdır.

Yirmi dört asır...

07 ARALIK 2005 SAAT:21.00

İbrahim Nazım Ülker', 'Bilir misin hemşerim gurbeti?  Gurbet günlerini, Filistin askısı geceleri?  O gecelerde sol yanına vurululan mermileri. Ardı arkası kesilmey...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Nazım Ülker']::text[], 8.5, '{"poet":"İbrahim Nazım Ülker","poet_slug":"i-brahim-nazim-ulker","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/yirmidort-asirdir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı ''yalnızlık''', 'adi-yalnizlik-gokhan-erdal-7jrp1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dışarda bir rüzgar eser; 

yüreğimde fırtınalar,

denizler kabarır  gözlerimde 

yalnızlığım, denizin binlerce kulaç dibinde 

dışarda bir rüzgar eser

bestesi çalınır dağlarda yalnızlığımın

bir rüzgar eser buralarda 

yalnızlığım eser

yalnızlığım üşür 

beni benim yalnızlığım öldürür', 'Dışarda bir rüzgar eser;  yüreğimde fırtınalar, denizler kabarır  gözlerimde  yalnızlığım, denizin binlerce kulaç dibinde  dışarda bir rüzga...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Erdal']::text[], 8.5, '{"poet":"Gökhan Erdal","poet_slug":"gokhan-erdal","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/adi-yalnizlik-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ozlem', 'ozlem-elif-gultekin-gmz39', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Deniz,

Ozledim seni.

Cikip gelemezsin biliyorum

Bari kokunu katsan aksam ruzgarina', 'Deniz, Ozledim seni. Cikip gelemezsin biliyorum Bari kokunu katsan aksam ruzgarina...', ARRAY['Türk Edebiyatı','Şiir','Elif Gültekin']::text[], 8.5, '{"poet":"Elif Gültekin","poet_slug":"elif-gultekin","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ozlem-288-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül-i Zâr', 'gul-i-z-r-cigdem-altinoz-50bju', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '..................Gülşen-i gâhda 

gül kokan güzel,

adın güldür 

kendin gülsün

gül bana...

......................gülbahara 

senin ile erelim

gül zamanı

gül-vendinle

gel bana

....................gülenyüzlüm

gül çehrende

gül açsın 

arada bir 

hatırımı 

sor bana

.....................Gülefşanım

gül bağında 

gülbiz ol, 

güldestemsin

gül bestesi 

sun bana

....................gülfeminden

ince kelam 

dökülsün

gülden gayrı

başka çiçek 

yok bana

....................gülnihâlim

gülsün

bu kara bahtım 

gülgün rüyaları 

sen, hep

yor bana

.......................gülenaysın

gülendama

kurban ben

gül nikâbın

gülpuşunu

aç bana

........................gültenimsin

güldehanım, 

sevdiğim

gülâbdandan

gülsuları

saç bana

.........................gülelim ki

gülleşelim 

renginden

gökkuşağı

rakib olsun

hep sana

........................biraz acı

bu bülbül-ü ruşene

gülistanda

ş’ol cenneti

sun bana

.......................gülrûbasın,

sen gülşahsın.

bendenem

gülhanında 

bir köşecik

ver bana

.......................gülden ettik 

bunca sözü gülizâr

sen gülcesin

sen, buğulu nazlı yar

gayrı bitsin

bu ayrılık,

bu firak

gülriz ol da

ey gülçin-i güldenim

gülle değil 

gül gonceni 

at bana

.....................gülnaklara

gül-nisalar dolmadan

ol gülistan

gülizlere kalmadan

arş-u ala

henüz

alt üst olmadan

gülabından

bir damlacık

kat bana

......................gülümse de 

güller açsın yeniden

gülşenimsin

güldalımsın, inceden

bitsin hasret 

gel gir de gülhaneme

gül derelim

gül kokalım

sevgiden 

2005....Afyonkarahisar', '..................Gülşen-i gâhda  gül kokan güzel, adın güldür  kendin gülsün gül bana... ......................gülbahara  senin ile erelim ...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Altınöz']::text[], 8.5, '{"poet":"Çiğdem Altınöz","poet_slug":"cigdem-altinoz","theme":"Türk Şiiri","is_hero":false,"total_lines":95,"source_url":"https://www.antoloji.com/gul-i-zar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi', 'simdi-ramazan-kayak-89acn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şimdi

Bu yıl da böyle

Kopuk,kopuk içimde

Sevdan yana sabır halkaları

Güneşi ararken dağların ardında

Kendimi kor olduğumu

Gördüm şimdi', 'Şimdi Bu yıl da böyle Kopuk,kopuk içimde Sevdan yana sabır halkaları Güneşi ararken dağların ardında Kendimi kor olduğumu Gördüm şimdi...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Kayak']::text[], 8.5, '{"poet":"Ramazan Kayak","poet_slug":"ramazan-kayak","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/simdi-65-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taş duvarların ardında', 'tas-duvarlarin-ardinda-ramazan-kayak-fnj20', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Taş duvarların ardında

Sevgili kardeşim

Sana bu satırları uzaklardan yazıyorum

Umarım eline geçerde okursun

Uzun zaman oldu görüşmeyeli

O uzak şehre gittiğinden beri

Senden sonra çok şeyler değişti

Çocukluklar 

Köy yaşantımız

Sevgideki kutsal duyguları kayıp ettik 

Hep bir yerlere savrulduk ayrı,ayrı

Darmadağınık hayatlara itildik

Hani

Seher yeline kanat çırpar ya

Uçar gider bilinmeyen yerlere

Kanat çırpar ya göçmen kuşlar

Öylesine dağıldık köşelere

Nerelerdeyiz bilmiyoruz kardeşim

Şimdi bir türkü söylenir Malabadi den

Bakır madenlerinden dinlenir

Damla,damla dökülür alın teri

Gözyaşlarıyla karışık

İşte öylesine bir sevda peşinde dolanıp durduk

Öylesine bir sevda ki bu 

Bir gülücükle anlatılır

Hüzünlü bakışta

Yumruk sıkışta

Dile getirilir yürekteki kor

Şimdi bir daha gelmiştir memleketimize bahar

Nisan yağmuruyla

Kan kırmızı olmuştur her yer

Gelinciklerle

Hala türküler söylenir mi bilmem

Haykırmak istiyorum var gücümle

Biliyorum taş duvarlarda eriyecek çığlığım

Yürek bu susmak nedir bilmez işte

Ömrümüzü tükettik artarda uzak yerlerde

Bilmiyorum dönebildin mi köyümüze 

Ben taş duvarların ardında

Köyüme hasret sizlere hasret

Görmesem güneşin doğuşunu bir daha 

Kendi memleketimde

Biliyorum bir çiçek açacak yüreğimde 

Sizden yana sevgiden kardeşlikten yana 

Şu yoksul gönlümde bir çiçek açacaktır

Ben güneşi görmesem de

Taş duvarların arasında karanlık odalarda 

Karanlıkları aydınlatacak 

Bir çiçek açacak yüreğimde

Biliyorum…', 'Taş duvarların ardında Sevgili kardeşim Sana bu satırları uzaklardan yazıyorum Umarım eline geçerde okursun Uzun zaman oldu görüşmeyeli O uz...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Kayak']::text[], 8.5, '{"poet":"Ramazan Kayak","poet_slug":"ramazan-kayak","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/tas-duvarlarin-ardinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gölgem', 'golgem-abdulvahap-ates-np4sg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yemeden içmeden koştun peşimden

ne evimden çıktın ne de işimden

acıdım haline inan içimden

sendeki vefaya imreniyorum

sen mi ben ben mi sen bilemiyorum

sen ruhum gibisin bedensiz benlik

et kemik bir de sen işte ademlik

hayata bağlanmış eğreti ilmik

gölgem koş peşimden güneş batıyor

arştaki gölgeler ufku aşıyor

affet beni gölgem seni de yaktım

bir ömür ömrünü peşime taktım

sürünen haline ağlayacaktım

gölgem ecel gibi düştün ardıma

veda zamanı mı artık yurduma

gölgem bu ısrarın korkutur beni

yeis duaları okutur beni

titrettin zulümden tırsmaz bedeni

Azrail sen misin girdin düşüme

olsun gel koynuma gel de üşüme', 'yemeden içmeden koştun peşimden ne evimden çıktın ne de işimden acıdım haline inan içimden sendeki vefaya imreniyorum sen mi ben ben mi sen ...', ARRAY['Türk Edebiyatı','Şiir','Abdulvahap Ateş']::text[], 8.5, '{"poet":"Abdulvahap Ateş","poet_slug":"abdulvahap-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/golgem-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türe', 'ture-ramazan-kayak-iwvsx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Türe

Alıp götürdüler onu

Getirdikleri gibi 

Sinsi gecenin karanlığında

Giderken 

Yaşlar akıyordu gözlerinden

Öylesine kırılgan  ürkek

Yabancılar arasındaydı sanki

Namusumuzu kirletin dediler

Sevdalı

Sevdası belalı güzel kız’a

Saçlarından tutup sürükledi 

Babası ve abisi

Son umutla takıldı gözleri annesine

Sevmenin suç olduğunu söyler gibi

Annesinin çaresiz bakışları kaldı gözlerinde

Kıymayın kuzucuğuma kıymayın ne olur

Ancak kendisi duyuyordu söylediklerini

Birde nazlım dediği kuzusu

Ve karanlıkta gözden kayıp oldular

Nice zaman sonra 

Bir derenin ağzında iki silah sesi

Yırtıp geçti gecenin sesizliğinı

Namus temizlenmişti

Kızın gözlerinden akan yaşlar

Parlar gece gündüz demeden 

O derenin ağzında

Üç yürek kan ağlıyor şimdi

Bir türe uğruna

Bir can feda edilmişti 

Daha nice canlar var sırada

Kim bilir 

Uğursuz türe uğruna 

Sevmek sevilmek adına', 'Türe Alıp götürdüler onu Getirdikleri gibi  Sinsi gecenin karanlığında Giderken  Yaşlar akıyordu gözlerinden Öylesine kırılgan  ürkek Yabanc...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Kayak']::text[], 8.5, '{"poet":"Ramazan Kayak","poet_slug":"ramazan-kayak","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/ture-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimsesizlik Devri', 'kimsesizlik-devri-melih-coskun-ozkin', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Devir 

Kimsesizlik devridir 

Kalabalıklar içinde 

Ve vakit akşamdır 

Merhem gibi yarada 

En sıcak yerinde 

Terli bir ağustosun 

Dağlardan gelen serinliktir o ses

Bir devrimcinin sonsuz kere güzelleşmesidir 

Kızıl ışıklar ardında

Her karış toprağını öpmektir 

Tepeden tırnağa 

Sevgisiz ve ekmeksiz bırakılmış bir yurdun...

2003', 'Devir  Kimsesizlik devridir  Kalabalıklar içinde  Ve vakit akşamdır  Merhem gibi yarada  En sıcak yerinde  Terli bir ağustosun  Dağlardan ge...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kimsesizlik-devri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dört Duvar', 'dort-duvar-erdem-toprak-pdmls', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kalabalık yine bugün 

Dört duvar 

Duvarda asılı saat 

Aynadaki ben 

Başucumdaki hayalin

Yeterde artar bile bana,,,', 'Kalabalık yine bugün  Dört duvar  Duvarda asılı saat  Aynadaki ben  Başucumdaki hayalin Yeterde artar bile bana,,,...', ARRAY['Türk Edebiyatı','Şiir','Erdem Toprak']::text[], 8.5, '{"poet":"Erdem Toprak","poet_slug":"erdem-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/dort-duvar-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektuplar-16 10/12/2005', 'mektuplar-16-10-12-2005-mahzun-doga-p1skb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kadınım.

Yetimliğimin yetisi; 

uzaklığın. 

Yaşamın fişlenmiş en sevmek dolusu sevmesi.

Kadınım.

Anamın uzak yarısı.

Varoluşunda bulduğum yerlerim.

Yüzerken kanatlarım, 

uçarken ayaklarım, 

düşerken dayanağım.

Sütünde yüzüdürdüğüm gemilerim var.

Göğsünde yuvalanmış kuşlarım.

Her rüzgar yüreğini gösteriyor.

Yolculuğu gözlerinde başlar,

kuş yelkenlerimin.

Kadınım.

Balık sırtı acı yüklüm.

Hüznünde binlerce ölümüm.

Yas yurdu, 

rahmetin ana ülkesi.

Kadınım.

Kadınım. 

Kutsal sevdam.

Yolun en yorulmuş yorgunluğum. 

Sana ulaşmak ne büyük uğraş.

Ne ulaşılmaz uğraş sana ulaşmak.

Kadınım.

Mavi yurdum.

Bebekliğimin gece yarısı.

Kadınım.

Kadınlığım.

Öteki tarafım.

Yanan yanım.

Bilinmeyen hücrelerim.

Kalbimin atom parçası.

Seni tanımlamak ne büyük tanım.

Ne erişilmez ermişlik sana erişmek.

Sana “kadınım” diyorum kadınım.

Layıkın bir er olmak ne büyük kadınlık.

Gel götür beni bu cehennemden.

Cennetine al beni.

Kadınım.', 'Kadınım. Yetimliğimin yetisi;  uzaklığın.  Yaşamın fişlenmiş en sevmek dolusu sevmesi. Kadınım. Anamın uzak yarısı. Varoluşunda bulduğum yer...', ARRAY['Türk Edebiyatı','Şiir','Mahzun Doğa']::text[], 8.5, '{"poet":"Mahzun Doğa","poet_slug":"mahzun-doga","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/mektuplar-16-10-12-2005-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uşağum - (Yerel 1.)', 'usagum-yerel-1-mikdat-bal-1gh5b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ağlamazdum uşağum olmasa idi derdum

Devasi olsa idi aramaya giderdum

Olsam senun yaşunda neler neler ederdum

Sensun benum umudum, benden geçti  uşağum

Al bayraği elune sana geçti uşağum

Oku da bir adam ol, rehber tutma şeytani

Habu ahir ömrumde, göreyim bi faydani

Geçen sefer uyuduk, boş bulanlar meydani

İşgal etti yalanla başa geçti   uşağum

Millet şaşkun haldeydi, yanliş seçti uşağum

Kâr mi kalur yaninda, kim ne eder bulacak

Sanduktan çıkmayinca, ne çok pişman olacak

Balonlari sonecek, sanma boyle kalacak

Anketlere kanarak, dema geçti uşağum

Herkes oni anladi, geldi göçti  uşağum

Savaşlarun soninda, kuruldi çok devletler

Biz kökli bir devleduk, ama bitmez illetler

Koşar adım gideyur, dün sürunen milletler

Birbirini tutanlar, bizi geçti uşağum

Piyasada yoktiler, bayrak açti uşağum

Bozuk idi halleri biz onlari acirduk

Uyuyunca onlari önumuze geçurduk

Hem hedefi şaşurduk, hem da treni kaçurduk

Kavga ettuk vaktumuz boşa geçti uşağum

Vakit asla acimaz bizi biçti  uşağum

Gücumuzi kaybettuk, duyulmayur nidalar

Onlar bizi sevmeyur hep bizdedur hatalar

Tarihlan övunuruk, ne eylesun atalar

Onlar birer kahraman, öldi geçti uşağum

Cennet bahçelerinde mekan seçti uşağum

Senluk, benluk olmadan bencilluği yenelum

Havalari birakup  yeryüzine inelum

Uyanalum ne olur, kendumuze dönelum

Uyuduk elumuze hava geçti uşağum

Geri kalmak bizlere beyuk suçti uşağum

Önemli mi kim hakli biz olalum, siz olun

Doğri değil bu gidiş, çıkışi yok bu yolun

Ülke zarar göreyur suçi vardur her kulun

Affederdum velakin, artuk geç’ti uşağum

Kalkup da dema bana, firsat kaçti uşağum

Mikdat der senden başka kim dinlesun çağrumi

Batsun bu ehtiyarluk, çoğaltuyur ağrumi

İşte boyle uzeyur, kanatuyur bağrumi

Yakayur bir ok gibi deldi geçti uşağum

Çoği kendine döndi, hem ant içti uşağum

______________________________________', 'Ağlamazdum uşağum olmasa idi derdum Devasi olsa idi aramaya giderdum Olsam senun yaşunda neler neler ederdum Sensun benum umudum, benden geç...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/usagum-yerel-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorum (Askere Gitmeden Son Şiir)', 'gidiyorum-askere-gitmeden-son-siir-ayhan-yavuz-acikgoz-vw9lb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gidiyorum

Saklı bıraktıklarımı açığa vurmadan

Ve önemsemeden, zâten önemsemediklerimi

Yemin bozarak belki

Ama ihânet etmeden

Gidiyorum

Döneceğim zamânı tam olarak kestiremiyorum

Bilmiyorum

Belki hemen dönerim, sessiz sedâsız, ağıtlarla

Belki hiç dönemem, ağıda bile zamân bulunmaz

Gidiyorum

Serzenişlerimi bir kâğıda yazıp, zarfa kilitleyerek

Ve yemin ettirerek sevdiğime, açmaması için

Açılmayacak, okunmayacak, bilinmeyecek

Mâdem öyle, neden yazdın? 

Bilmiyorum

Gidiyorum...

(adana- 10.12.2005   13:18)', 'Gidiyorum Saklı bıraktıklarımı açığa vurmadan Ve önemsemeden, zâten önemsemediklerimi Yemin bozarak belki Ama ihânet etmeden Gidiyorum Dönec...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Yavuz Açıkgöz']::text[], 8.5, '{"poet":"Ayhan Yavuz Açıkgöz","poet_slug":"ayhan-yavuz-acikgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gidiyorum-askere-gitmeden-son-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç Bakmadım Aynalara', 'hic-bakmadim-aynalara-sami-akman-h4fu6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir rüzgâra kapıldım savurdu beni

Bir kuru yaprak gibi, düştüm sahiline

Ellerimi tutacak kimse yok benim

Yalnızlar rıhtımın damıyım ne

Yakamozlar gibi bir görünüp bir kayboldun

Alıştım artık bırakıp gitmelerine

Dayanamam sensizliğe diyordun ya

Aldandım mı sahte gülüşüne

İçimde tarifsiz haz oluşurdu canım deyişine

Belki aldandım gülüşüne, sevişine

O tarifsiz bakışına, sıcacık öpüşüne

Aldandım aldandım sana ölürüm deyişine

Bir tek resmin var teselli bulduğum

Bakıp bakıp onunla konuştuğum

Dalgın dalgın bakan gözlerinde 

Bir kaybolup, bir var olduğum

İpeksi saçlarına dokunuyorum parmağımla

Sonra okşuyorum yavaş yavaş

Kokun yayılıyor odama yokluğunda

Gecenin karanlığına inat

Şimdi yalnızlığımla baş başayım 

Geçmek bilmeyen sensiz gecelerin esiriyim

Saklandım karanlık gecelerin koynuna

Yüreğimdeki sen’i kimse bilmesin diye 

Yüzümde çizgiler oluşmuş senden sonra

Ayrılığın acısını taşıyan derin çizgiler

Her biri senden kalan birer hatıra

Öyle ya hiç bakmıyorum ki aynalara

®©', 'Bir rüzgâra kapıldım savurdu beni Bir kuru yaprak gibi, düştüm sahiline Ellerimi tutacak kimse yok benim Yalnızlar rıhtımın damıyım ne Yakam...', ARRAY['Türk Edebiyatı','Şiir','Sami Akman']::text[], 8.5, '{"poet":"Sami Akman","poet_slug":"sami-akman","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/hic-bakmadim-aynalara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sözlükleri Karıştırırken (İsmail Haydar Aksoy)', 'sozlukleri-karistirirken-i-smail-haydar-aksoy-i-smail-aksoy-sl0gs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Acı sözcüğü 

Koyu harflerle yazılmıştı 

Bütün sözlüklerde. 

(1992) .', 'Acı sözcüğü  Koyu harflerle yazılmıştı  Bütün sözlüklerde.  (1992) ....', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sozlukleri-karistirirken-ismail-haydar-aksoy-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar Yağdığında (İsmail Haydar Aksoy)', 'kar-yagdiginda-i-smail-haydar-aksoy-i-smail-aksoy-dna1h', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nicedir unutmuştun ağlamayı 

Kimlik kartını yitirmiştin 

(Hükümlüdür!) 

Ne ki kanıtlayabildin yine de kim olduğunu 

Ve şöyle seslendin adı özgürlük olan kelebeğe: 

Uç uç kelebek 

Annem sana terlik papuç alacak! 

Ne ki öldürüldü sevgili kelebeğim 

Ve bulamadı annem bir kelebek terlik papucu 

Hepimiz kokuşmuş bir gölde yaşıyoruz 

Ölü kelebeklerimizle 

Ve tutturmuşuz çılgınca bir şarkı 

''Don''t worry, be happy'' 

Ama kar yağdığında göle 

Küçük balıklar korkacak! 

(Şubat 1990. Mülteci Kampı / Danimarka)', 'Nicedir unutmuştun ağlamayı  Kimlik kartını yitirmiştin  (Hükümlüdür!)  Ne ki kanıtlayabildin yine de kim olduğunu  Ve şöyle seslendin adı ö...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kar-yagdiginda-ismail-haydar-aksoy-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Natürmort (İsmail Haydar Aksoy)', 'naturmort-i-smail-haydar-aksoy-i-smail-aksoy-75b8f', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çirkin bir orospunun sözleriyle 

Ve iğrenç kahkahalarla 

Kirleniyordu dünya. 

Gökyüzü koyu bir kusmuk gibi 

Kapanıp kalmıştı 

Yeryüzünün dişsiz ağzında. 

(Şubat 1992. Kopenhag)', 'Çirkin bir orospunun sözleriyle  Ve iğrenç kahkahalarla  Kirleniyordu dünya.  Gökyüzü koyu bir kusmuk gibi  Kapanıp kalmıştı  Yeryüzünün diş...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/naturmort-ismail-haydar-aksoy-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu İşyerinde Grev Var! (İsmail Haydar Aksoy)', 'bu-i-syerinde-grev-var-i-smail-haydar-aksoy-i-smail-aksoy-ozskm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ellerinin ardında gözlerin 

Gözlerinin ardında akışan anılar var 

Sevdalar artık 

Bir med cezir olarak anımsanır 

Ve unutulur elbet 

Artık sevemiyorum 

Yüreğimin paslı kapılarına bakıyorum 

Kocaman harflerle yazılmış: 

''BU İŞYERİNDE GREV VAR! '' 

(Nisan 1989. Ankara) .', 'Ellerinin ardında gözlerin  Gözlerinin ardında akışan anılar var  Sevdalar artık  Bir med cezir olarak anımsanır  Ve unutulur elbet  Artık s...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bu-isyerinde-grev-var-ismail-haydar-aksoy-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmak!', 'yagmak-gokten-aydogdu-gwbfr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Fırtınalar kopuyor

Karanlık gecelerde

İçim bir tuhaf

Tarifsiz acılar

Acılar yüreğimde

Evren daralıyor

Bir damla misali

Doluyor kadehime

Kimi zaman martılar havalanıyor

Umut denizine

Selam getiriyor senden

Selam getiriyor maviden

Yemyeşil bahçelerden

Güneşli gecelerden

O anlarda uçmak istiyorum

Gökyüzüne

Kanat çırpmak

Sevda sunmak

Bulut olmak 

Yağmak yağmak yağmak...', 'Fırtınalar kopuyor Karanlık gecelerde İçim bir tuhaf Tarifsiz acılar Acılar yüreğimde Evren daralıyor Bir damla misali Doluyor kadehime Kimi...', ARRAY['Türk Edebiyatı','Şiir','Gökten Aydoğdu']::text[], 8.5, '{"poet":"Gökten Aydoğdu","poet_slug":"gokten-aydogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yagmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz günler 1', 'sensiz-gunler-1-i-brahim-kilinc-omrgu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Maziyi anmayı bıraktım gülüm

Bu günü tutmaya çalışıyorum

Dönüşü olmayan güzel günleri

Artık unutmaya çalışıyorum

Gözüm pek görmüyor zararı, kârı

Ne de olsa gönül biraz yaralı

Koparıp aldılar tuttuğum dalı

Başka dal tutmaya çalışıyorum

Başka dal aramak kolay olmuyor

Gönül gönle göre gönül bulmuyor

Ne yapsam, ne etsem yerin dolmuyor

Sensiz yaşamaya çalışıyorum', 'Maziyi anmayı bıraktım gülüm Bu günü tutmaya çalışıyorum Dönüşü olmayan güzel günleri Artık unutmaya çalışıyorum Gözüm pek görmüyor zararı, ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Kılınç']::text[], 8.5, '{"poet":"İbrahim Kılınç","poet_slug":"i-brahim-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sensiz-gunler-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Taraflı', 'tek-tarafli-erdem-toprak-di34o', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni sevdim 

Ruhun bile duymadı

Duysa ne olurdu ki? 

Yanındaki heriften 

Fazlası değil

Benim payıma düşen

Yalnızlık tabi ki,,,', 'Seni sevdim  Ruhun bile duymadı Duysa ne olurdu ki?  Yanındaki heriften  Fazlası değil Benim payıma düşen Yalnızlık tabi ki,,,...', ARRAY['Türk Edebiyatı','Şiir','Erdem Toprak']::text[], 8.5, '{"poet":"Erdem Toprak","poet_slug":"erdem-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/tek-tarafli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mazi', 'mazi-necibe-sucuoglu-rfbxm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Eski bir kemanın tellerinden dökülen

Tatlı nağmeler gibi

Maziyi dinledim bugün.

Ruhumun susuzluğunu

Yıllanmış şarap tadında

Maziyle giderdim bugün.

Yüreğimin açlığını,

İlkbahar yeşilliğinde

Belleğimde kalan

Maziyle doyurdum bugün.

Hazan mevsimini yaşarken; 

Sararan yaprakların,

Kuruyan dalların

Hüznü olsa da; 

Duvara asılı

Bir sonbahar manzarası güzelliğinde

Seyrettim hayatı bu gün.', 'Eski bir kemanın tellerinden dökülen Tatlı nağmeler gibi Maziyi dinledim bugün. Ruhumun susuzluğunu Yıllanmış şarap tadında Maziyle giderdim...', ARRAY['Türk Edebiyatı','Şiir','Necibe Sucuoğlu']::text[], 8.5, '{"poet":"Necibe Sucuoğlu","poet_slug":"necibe-sucuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/mazi-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Kadeh', 'i-ki-kadeh-yasar-aslan-eb86v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir düş uyandı 

Birde bize eşlik iki kadeh 

Olmaz/sızım kapatma gözlerini 

Güneşi özledim gözlerinde 

Bu gavur ölüsü gecede 

Islak bir yağmur siniyor bedenime 

Su kurak 

Ateş sönük geliyor cehennemime 

Bir ben bir sen

Birde iki kadeh.', 'Bir düş uyandı  Birde bize eşlik iki kadeh  Olmaz/sızım kapatma gözlerini  Güneşi özledim gözlerinde  Bu gavur ölüsü gecede  Islak bir yağmu...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Aslan']::text[], 8.5, '{"poet":"Yaşar Aslan","poet_slug":"yasar-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/iki-kadeh-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acıyor', 'aciyor-necibe-sucuoglu-f4z66', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Acıyor yüreğim,

Duygularım acıyor.

Acıyor beynim,

Düşüncelerim acıyor.

Acıyı acıyla keserlermiş; 

Bir bıçak saplasam

Dindirebilir miyim ki? 

Yanıyor içim

Dışıma kar yağsa da.

Ateş yutsam,

Söndürebilir miyim ki? 

Zincirli kollarım,

Ayaklarım zincirli.

Zincirle vursam

Kırabilir miyim ki? 

Ölümle yaşam arasında

Gidip gelsem de

Daha ölmedim,

Neden yaşıyorum ki?', 'Acıyor yüreğim, Duygularım acıyor. Acıyor beynim, Düşüncelerim acıyor. Acıyı acıyla keserlermiş;  Bir bıçak saplasam Dindirebilir miyim ki? ...', ARRAY['Türk Edebiyatı','Şiir','Necibe Sucuoğlu']::text[], 8.5, '{"poet":"Necibe Sucuoğlu","poet_slug":"necibe-sucuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/aciyor-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gezegenler', 'gezegenler-necibe-sucuoglu-gviyx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gezegenler,

Adları neden gezegendirler? 

Onlar çok mu gezerler? 

Çok gezen çok bilir derler,

Ben de bilmediklerimi sorsam da,

Bana söyleseler.

Ben öğrenemedim ki; 

Beni gezdirmediler.

Sen yaramazsın dediler,

Sen anlamazsın dediler,

Bir de...

Her söylediklerinde ağlasam da

Yine de...

Sen delisin dediler.', 'Gezegenler, Adları neden gezegendirler?  Onlar çok mu gezerler?  Çok gezen çok bilir derler, Ben de bilmediklerimi sorsam da, Bana söylesele...', ARRAY['Türk Edebiyatı','Şiir','Necibe Sucuoğlu']::text[], 8.5, '{"poet":"Necibe Sucuoğlu","poet_slug":"necibe-sucuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gezegenler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut dileniyorum yıldızlardan', 'umut-dileniyorum-yildizlardan-necibe-sucuoglu-mw4i6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uyku uyku bakıyor gözlerim

Bitiminde uykusuz gecelerin.

Korku korku çarpıyor yüreğim

Sonunda cevapsız belkilerin.

Umut umut gençliğim

Bir mum gibi sönüverdi

Rüzgarıyla senelerin.

Yıldız yıldız gecelerde

Kaçıyor uykularım

Koşsam da ardından.

Kopmamak için yaşamdan

Umut dileniyorum yıldızlardan.', 'Uyku uyku bakıyor gözlerim Bitiminde uykusuz gecelerin. Korku korku çarpıyor yüreğim Sonunda cevapsız belkilerin. Umut umut gençliğim Bir mu...', ARRAY['Türk Edebiyatı','Şiir','Necibe Sucuoğlu']::text[], 8.5, '{"poet":"Necibe Sucuoğlu","poet_slug":"necibe-sucuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/umut-dileniyorum-yildizlardan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kilis''ten Şemdinli''ye Giden Kaçakçının Türküsü', 'kilis-ten-semdinli-ye-giden-kacakcinin-turkusu-i-smail-aksoy-o35s8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Reşko ve Cilo harman savuran kızın memeleridir

Oturmuş cıgara sarar emmiler

Bir çay daha demlenir şimdi bizim orda

Bir çay daha kar suyundan

Bir muhabbet daha koyulur 

Orda, mor dağların ardında

Ak sakallı dağlar, yol verin

Doru kısrağım huysuz, bastı basacak mayına

Terkimde Kilis''ten getirdiğim bir kilim

Avcumda anamın rahminden kopardığım kan pıhtısı

Beni Islahiye bile ıslah edemez gayrı

(1987. ODTÜ / Ankara) .', 'Reşko ve Cilo harman savuran kızın memeleridir Oturmuş cıgara sarar emmiler Bir çay daha demlenir şimdi bizim orda Bir çay daha kar suyundan...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kilis-ten-semdinli-ye-giden-kacakcinin-turkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürgün (İsmail Haydar Aksoy)', 'surgun-i-smail-haydar-aksoy-i-smail-aksoy-sp0pq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Özgür''e, 

Bir ozanın ülkesi sevdiği kadın ise 

Gerçek bir sürgündeyim ben, 

Ah, gerçek bir sürgünde! 

(Mayıs 1989. Acıbadem / İstanbul) .', 'Özgür''e,  Bir ozanın ülkesi sevdiği kadın ise  Gerçek bir sürgündeyim ben,  Ah, gerçek bir sürgünde!  (Mayıs 1989. Acıbadem / İstanbul) ....', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/surgun-ismail-haydar-aksoy-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Simyacı Karanlık Gecede (İsmail Haydar Aksoy)', 'i-ki-simyaci-karanlik-gecede-i-smail-haydar-aksoy-i-smail-aksoy-8rci0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Geldin, saçlarında tarçın kokusu

Ellerin başka türlü kokuyordu

Ve binbir koku karışıyordu birbirine

Ve ayrışıyordu birbirinden

Sonsuz bir dönüşüme doğru akıyorduk seninle

Sana bir de kendimi ekledim usulca

İki simyacıyı andırıyorduk karanlık gecede

Yıldızlara tutkulu

Tutuklu', 'Geldin, saçlarında tarçın kokusu Ellerin başka türlü kokuyordu Ve binbir koku karışıyordu birbirine Ve ayrışıyordu birbirinden Sonsuz bir dö...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/iki-simyaci-karanlik-gecede-ismail-haydar-aksoy-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmeyi Öğrenmek (İsmail Haydar Aksoy)', 'sevmeyi-ogrenmek-i-smail-haydar-aksoy-i-smail-aksoy-6h3z4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni sevmek yeni bir dil öğrenmek gibi

Tutuyorum ellerini, böylece yaratıyoruz birleşmek eylemini

Öpüyorum usulca seni, yumuyorsun kirpiklerini

Böylece yeniden var oluyor ''seni seviyorum'' bütün dillerde

Farkında mısın çoğaldığımızın? 

Böylece yok oluyor acı bütün sözlüklerde.

Sessizce bir geleneği sürdürüyoruz seninle

Şimdi tam ''bir geyik yolunu şaşırdı dağda'' diyerek

Öpmenin sırası memelerini

Gidişin sürgünümdür, gitme

Gidersen unuturum bütün o sözcükleri

Dilsiz kalırım, gitme', 'Seni sevmek yeni bir dil öğrenmek gibi Tutuyorum ellerini, böylece yaratıyoruz birleşmek eylemini Öpüyorum usulca seni, yumuyorsun kirpikler...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevmeyi-ogrenmek-ismail-haydar-aksoy-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hal Böyle Böyle (İsmail Haydar Aksoy)', 'hal-boyle-boyle-i-smail-haydar-aksoy-i-smail-aksoy-6xdec', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir ele gereksinim duyduğum anlardan biriydi.

Ve gitgide yakınlaşan bir ışık gibi vardın yanıma.

Korkunun gölgesinde yeşeren bir ağaçtı sevi.

Ve yaşama ulanıyordu simit kokularıyla

Simitçi çocukların ciğerlerinden yükselen sıcak soluklar.', 'Bir ele gereksinim duyduğum anlardan biriydi. Ve gitgide yakınlaşan bir ışık gibi vardın yanıma. Korkunun gölgesinde yeşeren bir ağaçtı sevi...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/hal-boyle-boyle-ismail-haydar-aksoy-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlem (İsmail Haydar Aksoy)', 'gozlem-i-smail-haydar-aksoy-i-smail-aksoy-ozucv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Anahtarlarıyla avunuyor kadın gururla

Anahtarlarıyla övünüyor

Gururlu kadın', 'Anahtarlarıyla avunuyor kadın gururla Anahtarlarıyla övünüyor Gururlu kadın...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/gozlem-ismail-haydar-aksoy-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıplak', 'ciplak-sair-bora-91k81', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bereketli göğüslerin

dudakların aşka ıslak

cennetten kovulan ırmak

yatağımda çırılçıplak

her gece gürül gürül ak

yıkık yönkerimi götür

umutsuzluğumu yıka

yarına beni değiştir

geldiğin yerlerin yeşil

gittiğin yerlerin kurak', 'bereketli göğüslerin dudakların aşka ıslak cennetten kovulan ırmak yatağımda çırılçıplak her gece gürül gürül ak yıkık yönkerimi götür umuts...', ARRAY['Türk Edebiyatı','Şiir','Şair Bora']::text[], 8.5, '{"poet":"Şair Bora","poet_slug":"sair-bora","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ciplak-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Aşkın Sonrasında Vasiyet (İsmail Haydar Aksoy)', 'bir-askin-sonrasinda-vasiyet-i-smail-haydar-aksoy-i-smail-aksoy-3wims', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir ezgi gibi geçirdim içimden seni. Pırıl pırıl. Yunmuş arınmış öylesine. Karanlıklarımı ışıtanımdın; uyandıran beni karabasanlarımdan. Şimdi ne kaldı sahi ara sıra anımsayışlardan başka? Bir tren gibi geçip gidiyor zaman. (Peki hangi vagondasın sen?)

Üç kez mırıldandım adını bilinçsizce. Çok uzak ve ıssız bir ülkenin adını duymuşcasına irkildim. (Sevmek yabancılaşmaktan başka bir şey olabilir mi?)

O kırmızı karanfili de unut. Umutsuzca ezilmiş olanı, araba tekerleklerinin ve arabesk şarkıların altında.', 'Bir ezgi gibi geçirdim içimden seni. Pırıl pırıl. Yunmuş arınmış öylesine. Karanlıklarımı ışıtanımdın; uyandıran beni karabasanlarımdan. Şim...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aksoy']::text[], 8.5, '{"poet":"İsmail Aksoy","poet_slug":"i-smail-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/bir-askin-sonrasinda-vasiyet-ismail-haydar-aksoy-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
