INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'El İzlerim', 'el-i-zlerim-akin-dursun-292di', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'daha çok ufaktım, 

o zamanlarda öğrendi gözlerim ağlamayı,

çocuksu bir yüzden akıyordu,

el izlerim, oyuncakçı camekanlarını süslüyordu

daha çocuktum...ağlıyordum...

terk edilmiş bir çocukluktu benimkisi, 

arkadaşlarım saklambaç, körebe oynarken

ellerim yüzüme dayalı bir taşın üstüne oturup

çocukluğumu izliyordum ben

daha çocuktum oysa, ağlıyor... ağlıyordum...

ufacık ellerimle avutuyordum akan yaşları

ve düşen her damlada biraz daha büyüyordum

daha çok ufaktım, hevesliydim büyümeye 

büyüyünce her şeyin olur derdi, annem 

oldu annem, oldu...

dünün damlaları bu günün koca nehri oldu 

benimle büyüdü acılar, benimle soldu güller 

bak, büyüdüm...büyüdüm... 

ama hâlâ süslüyor el izlerim, oyuncakçı camekanlarını

ağlıyorum, annem...

                                                                 12.08.2002 / 20:15 İzmir', 'daha çok ufaktım,  o zamanlarda öğrendi gözlerim ağlamayı, çocuksu bir yüzden akıyordu, el izlerim, oyuncakçı camekanlarını süslüyordu daha ...', ARRAY['Türk Edebiyatı','Şiir','Akın Dursun']::text[], 8.5, '{"poet":"Akın Dursun","poet_slug":"akin-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/el-izlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölmedim Anne', 'olmedim-anne-akin-dursun-8kk9w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'paslı bir ranzanın demirlerine

tırnakla kazınmış, özgürlük

soğuk ve acımasız bir yüz ifadesiyle duran

duvarlara perçinlenmiş adeta 

her yanım, 

her yanım özgürlüktü oysa

geçit vermeyen demir kapının 

ardında duran gardiyanları saymazsam

avunuyorum yıllardır tepemde duran, 

sönmeye yüz tutmuş bir lambayla 

sızar diyorum belki güneş, bulursa bir aralık

unuttum çünkü yıllardır gözüm nasıl kamaşır

unuttum ekmeğin kokusunu, 

memleketimin havasını,

unuttum suyun tadını,

su nasıldır...

karanlık bir hücrede yıllardır bekliyorum idamı

her yanım özgürlüğü anlatıyordu oysa

sönmeye ramak kalmış bir lamba...

okuduğum romanlar...

yazdığım şiirler...

her şey, ama her şey özgürlüğü anlatıyordu bana

unutmuşum çünkü yıllardır 

nasıl ve nerden doğar güneş...

unutmuşum düşlerin rengini...

hayal geçidini...

unutmuşum anne, unutmuşum yüzünü

bağışla beni,

keşke hep çocuk, çocuk kalsaydım

dizlerinin dibinde

şimdi gardiyanları sarmış bir telaş

dar ağacım hazırmış anne

kıyısındayım artık ömrün

yürüyorum bak, gidiyorum yavaş yavaş

üzülme sakın, üzülüp ağıtlar yakma 

az önce kamaştı gözüm...

ben ölmedim...

ölmedim...

özgürüm artık anne...

                                                                18.08.2002 / 01:45', 'paslı bir ranzanın demirlerine tırnakla kazınmış, özgürlük soğuk ve acımasız bir yüz ifadesiyle duran duvarlara perçinlenmiş adeta  her yanı...', ARRAY['Türk Edebiyatı','Şiir','Akın Dursun']::text[], 8.5, '{"poet":"Akın Dursun","poet_slug":"akin-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/olmedim-anne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Sevgili', 'senin-sevgili-akin-dursun-aw0vw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kelimeleri bile güldüren gözlerin var senin sevgili 

umutsuz anlarda sen öğrettin umut yapmayı

kırıntılar biriktirmeyi küçük küçük 

tutunup inadına hiç yakasını bırakmamayı

senden öğrendim yaşamın, koskoca bir direnmek olduğunu

senin heceleri bağırtan sesin var sevgili 

şiirler gelirdi dize, 

türküleri bile sende sevdim, sende

yol alırken hasrete kulağıma şöyle bir eğilip

son kez sen söyledin,

zaten hep sen söylerdin son sözü

sönmüş bir volkan gibi dudaklarındaydı 

ne zaman sıkıca sarılsak ayrılık bulurdu bizi 

her an patlamaya hazır saatli bomba gibi

senin ayrılığı bile ağlatan kağıttan gemilerin var sevgili 

üstüne imkansız aşklar yazdığın 

ve dipnot olarak seviyorum diye sözler eklediğin 

sonra denize indirdiğin gemilerin var sevgili

umuda yüzdürdün

hiç ama hiç umudunu yitirmeden hem de 

bense hep bu yönünü sevdim senin

   

öyle bir sevincin var ki senin sevgili,

gökkuşağı renginde, kavuşunca birbirimize

gökyüzü salıverirdi tüm yıldızları sevgimize 

ardındansa, ay dansa kaldırırdı güneşi

kıskanırlardı inan bizi

kıskanırlardı...

işte, böyle bir sevdan vardı senin sevgili



                                                              05.03.2002 / 02:00 İzmir', 'kelimeleri bile güldüren gözlerin var senin sevgili  umutsuz anlarda sen öğrettin umut yapmayı kırıntılar biriktirmeyi küçük küçük  tutunup ...', ARRAY['Türk Edebiyatı','Şiir','Akın Dursun']::text[], 8.5, '{"poet":"Akın Dursun","poet_slug":"akin-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/senin-sevgili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Teselli', 'teselli-ayda-yildiz-kv44i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yapraklari kirildi kirmizi gulun

Hanesi dustu, rengi gitti gunun

Teselli etmiyor sesi bulbulun

Gozumu moruna cevirdim sumbulun

Dert var, derman var

Saz var, soz var

Ne dermanda, ne sazda 

Icimdeki gamin verdigi haz var

Acma sakin bu mevsim

Dokulur aglarsin butun ciceklerin

Gel etme, eyleme, sana var sevesim

Kopacak cigliklari gonul sazindaki telin 

Kocamis agac verir tomurcuklarin

Tomurcuk  cicekleri topla ez

Sur ustune yarali signenin

Sen bil, sen tazele, sen sez', 'Yapraklari kirildi kirmizi gulun Hanesi dustu, rengi gitti gunun Teselli etmiyor sesi bulbulun Gozumu moruna cevirdim sumbulun Dert var, der...', ARRAY['Türk Edebiyatı','Şiir','Ayda Yıldız']::text[], 8.5, '{"poet":"Ayda Yıldız","poet_slug":"ayda-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/teselli-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diyecekti-m (n)', 'diyecekti-m-n-akin-dursun-l2zdv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şimdi sen olacaktın 

Sevginle dolacaktım.

Aşkım diye haykıracaktım

Tüm evrene seviyorum diyecektim

Seviyorum diyecektin

Aşkımı, sevgimi,

Sevgimizi anlatacaktım

Dağlara, taşlara, uçan kuşlara

Seviyorum diyecektim

Seviyorum diyecektin

Hani gitmeyecektin

Hani saracak, koklayacak, 

Öpecektin beni, 

Var gücünle haykırıp 

Seviyorum diyecektin 

Seviyorum diyecektim

Tüm insanlara, insanlığa 

Söyleyecektin seni, beni 

Sevgimizi,

Seviyorum diyecektin 

Seviyorum diyecektim

Bizi,sevgimizi...                                                                            

   

                                                         30.10.1998 / 01:50 İzmir', 'Şimdi sen olacaktın  Sevginle dolacaktım. Aşkım diye haykıracaktım Tüm evrene seviyorum diyecektim Seviyorum diyecektin Aşkımı, sevgimi, Sev...', ARRAY['Türk Edebiyatı','Şiir','Akın Dursun']::text[], 8.5, '{"poet":"Akın Dursun","poet_slug":"akin-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/diyecekti-m-n-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sadece Sevgi İstedim', 'sadece-sevgi-i-stedim-yasin-bal-sp6dd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ölmek ya da yaşamak,

Çare değil yalnızlığıma.

Anladım ki,

Sevgin gerek bana.

İçinden geldiği gibi,

samimi.

Tıpkı seni sevdiğim gibi.', 'Ölmek ya da yaşamak, Çare değil yalnızlığıma. Anladım ki, Sevgin gerek bana. İçinden geldiği gibi, samimi. Tıpkı seni sevdiğim gibi....', ARRAY['Türk Edebiyatı','Şiir','Yasin Bal']::text[], 8.5, '{"poet":"Yasin Bal","poet_slug":"yasin-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sadece-sevgi-istedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ada Yalnızlığı', 'ada-yalnizligi-akin-dursun-xdq9j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'keşfedilmeyi bekleyen 

bir ada yalnızlığı yaşıyorum

varsın kimseler sormasın 

ben sensizliği su diye içiyorum 

kimseler bilmesin, varsın

sensizliği, onlardan bile sakınıyorum

bir ada yalnızlığı yaşıyorum

ormanlarım yeşil yeşil 

mavilerim tertemiz,

çiçek çiçek baharlarım

kirlenmedi hiç bir yıldızım... 

hiç bir ağacım...

ve de ateş kırmızısı giyen ayım...

varsın kimseler kirletmesin

su diye içiyorum ben sensizliği

kimseler el sürmesin 

bir ada yalnızlığı yaşıyorum

varsın, kimseler keşfetmesin

ben sensizliği su diye, 

kana kana avuçlarından içiyorum



                                                          30.05. 2002 / 17:00 İzmir', 'keşfedilmeyi bekleyen  bir ada yalnızlığı yaşıyorum varsın kimseler sormasın  ben sensizliği su diye içiyorum  kimseler bilmesin, varsın sen...', ARRAY['Türk Edebiyatı','Şiir','Akın Dursun']::text[], 8.5, '{"poet":"Akın Dursun","poet_slug":"akin-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ada-yalnizligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Hiç Yaşadın Mı?', 'sen-hic-yasadin-mi-cansu-alkan-7imge', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen hiç dolaştın mı yıldızların arasında,

Ve hiç kayboldun mu bulutların arasında.

Hiç çıktın mı düşlerinin ufuğuna

Ve sen hiç yaşadın mı imkânsız olanı…

Sen hiç ağladın mı şöyle hıçkıra hıçkıra,

Ve hiç yürüdün mü kızgın ateşin üzerinde.

Hiç boğuştun mu azgın dalgalarla

Ve sen hiç yaşadın mı imkânsız olanı…

Sen hiç durduk yere kahkahalar attın mı? 

Hiç düşündün mü yalnızlığın acımasız,

Kalabalığın ise dayanılmaz olduğunu

Ve sen hiç yaşadın mı imkânsız olanı…

Peki ya sen imkânsız olanı yaşamaktan korktun mu? 

Peki, umuda yenik düşmekten korktun mu? 

Hiç konuştun mu kendi kendine delice

Ve sen hiç yaşadın mı imkânsız olanı…

Ve sen imkânsızlığı yaşamazken

Nereden bileceksin ki yaşamanın zevkini

Ve nereden anlayacaksın ki hayatın tadını

PEKİYA SEN HİÇ YAŞAMADINMI İMKÂNSIZ OLANI…

                                                           CANSU ALKAN

                                              03.12.05', 'Sen hiç dolaştın mı yıldızların arasında, Ve hiç kayboldun mu bulutların arasında. Hiç çıktın mı düşlerinin ufuğuna Ve sen hiç yaşadın mı im...', ARRAY['Türk Edebiyatı','Şiir','Cansu Alkan']::text[], 8.5, '{"poet":"Cansu Alkan","poet_slug":"cansu-alkan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sen-hic-yasadin-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat', 'hayat-cansu-alkan-spv81', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bazen susuzluk, bazen açlık

Bazen aşk, bazen hüzün

Bazen umuttur

Senin hayat dediğin

Bazen yeni bir doğuş

Bazen bir ölüm

Bazen de bir umutsuzluktur

Senin hayat dediğin

Bazen tatlı bir uykunun ortasında uyanmak

Bazen de bir kâbusun en kötü yerinde

Seni sensiz yaşamaktır 

Senin hayat dediğin

                                                          CANSU ALKAN', 'Bazen susuzluk, bazen açlık Bazen aşk, bazen hüzün Bazen umuttur Senin hayat dediğin Bazen yeni bir doğuş Bazen bir ölüm Bazen de bir umutsu...', ARRAY['Türk Edebiyatı','Şiir','Cansu Alkan']::text[], 8.5, '{"poet":"Cansu Alkan","poet_slug":"cansu-alkan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hayat-270-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Farz Etki', 'farz-etki-cansu-alkan-i4wk9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'FARZ ETKİ

Nasıl ki toprak yağmura

Yağmur toprağa doymuyorsa

Bende sana,

Bende sana doymuyorum bitanem

Gitmeden son kez sarıl bana 

Son kez dizinde uyut beni

Yarın ben yokum, üzülme sakın

Farz etki ben öldüm

Gitmek beni de acıtıyor

Bana da koyuyor

Koyuyor, senden uzaklarda bir başıma yaşamak

Ama üzülme farz etki ben öldüm

                                                           

                                                                                CANSU ALKAN

                                                                                                    28.09.2005', 'FARZ ETKİ Nasıl ki toprak yağmura Yağmur toprağa doymuyorsa Bende sana, Bende sana doymuyorum bitanem Gitmeden son kez sarıl bana  Son kez d...', ARRAY['Türk Edebiyatı','Şiir','Cansu Alkan']::text[], 8.5, '{"poet":"Cansu Alkan","poet_slug":"cansu-alkan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/farz-etki-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Bekliyorlar', 'seni-bekliyorlar-akin-dursun-r9wre', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Konuşunca nar çiçekleri açardı cümlelerinde 

Yeşile çalan gözlerin buluşurdu deniz mavisiyle 

Karışırdı meltemler saçlarına

Sen inadına otururdun görkemli kayalara

Göğe yakın olurdun yere uzak

Zapt ederdin tüm yıldızları

O an soyunurdu yüreğin çırılçıplak.

Bekledim bir gün, seni orada

Gelmedin... 

Bekledim, inatla

Kimseler bilmedi

Bilemezdi kimseler 

Avuçlarımdan usulca kayıp gittiğini,

Denizin mavisini çalıp 

Nar çiçeklerini katlettiğini.

Artık kırgınlıkların başkentiydi görkemli kayalar

Toplanmadı ay parçaları,kırılan yıldızlar 

Öylece orda kaldı 

Hâlâ ordalar...

24.04-24.05.2002 /23:30-01:10 İzmir', 'Konuşunca nar çiçekleri açardı cümlelerinde  Yeşile çalan gözlerin buluşurdu deniz mavisiyle  Karışırdı meltemler saçlarına Sen inadına otur...', ARRAY['Türk Edebiyatı','Şiir','Akın Dursun']::text[], 8.5, '{"poet":"Akın Dursun","poet_slug":"akin-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/seni-bekliyorlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluğun', 'yoklugun-cansu-alkan-y72df', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yokluğun mutluluğum

                Yokluğunda tattım sensizliği

                Yokluğun benim sevincim oldu…

                Yokluğunda yağmurlarda ıslandım

                Sensiz gittim yazlık sinemalara

                Ağladım geceler boyu

                Kimi zaman yokluğun kederimdi…

               Her mevsim yokluğunda ağladım

               Her yağmur damlasında seni aradım

               Yokluğun bana koymuyor artık

               Yokluğunda yokluğunu buldum…

                                            Cansu Alkan

                                   24.08.2005', 'Yokluğun mutluluğum                 Yokluğunda tattım sensizliği                 Yokluğun benim sevincim oldu…                 Yokluğunda ya...', ARRAY['Türk Edebiyatı','Şiir','Cansu Alkan']::text[], 8.5, '{"poet":"Cansu Alkan","poet_slug":"cansu-alkan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yoklugun-61-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Gibiyim', 'yagmur-gibiyim-yasin-bal-12fxu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yağmur yağıyor yine,

ıslanıyorum.

Bir sürü kuru bakışlar içinde,

bir yağmur sesi,

bir de 

patavatsızca açılan şemsiyeler.

Ne garip,

koşuşturmuyorum onlar gibi

bir sağa bir sola

Yağmur yağıyor yine

her damlası 

bir Ben oluyor

ve 

her Ben

bir Sen', 'Yağmur yağıyor yine, ıslanıyorum. Bir sürü kuru bakışlar içinde, bir yağmur sesi, bir de  patavatsızca açılan şemsiyeler. Ne garip, koşuştur...', ARRAY['Türk Edebiyatı','Şiir','Yasin Bal']::text[], 8.5, '{"poet":"Yasin Bal","poet_slug":"yasin-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yagmur-gibiyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut', 'umut-gokhan-erdal-8lcaq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Olmasa umutlarım

sevgine dair,

Dinlemezdim şarkıları,

ıslanmazdım yağmurlar altında.

Geceler boyu beklemezdim.

Olmasa umutlarım 

sevgine dair 

çoktan başımı alır giderdim.						18.02.1995 saat:01.30  sarıziyaret', 'Olmasa umutlarım sevgine dair, Dinlemezdim şarkıları, ıslanmazdım yağmurlar altında. Geceler boyu beklemezdim. Olmasa umutlarım  sevgine dai...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Erdal']::text[], 8.5, '{"poet":"Gökhan Erdal","poet_slug":"gokhan-erdal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/umut-228-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Denizkızı', 'denizkizi-osman-cetinkaya-pxn48', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sonsuz bir mavide bulmuştum kendimi

Bir gece yarısı, nedensiz

Bir arayıştı bu biliyorum

Geceleri rüyamı yazan gözlere tutulmuştum besbelli

Nerdedir, ne yapar denizin kızı

Yakamozlarını izlerken denizin

içimde dualarla

Çık dedim artık, çık yakamozlardan

Böyle bir aşk yaşamadı bu yürek

ve yaşamaz böyle bir sevda hiç bir yürek

Mehtabın ışıkları vururken denize

Gözlerimi kırpmadan baktım sonsuza

Seni aradım gece boyunca

Gücüm kalmadı

Yorgun bedenim

Kan çanağı gözlerim

Bağırdım kayalara vuran dalga seslerine

''''Seviyorum seni, seni'''' diye

Yankılandı sevdamın sesi mavi denizlere doğru

Çöktüm dizlerim üstüne

Ağladım..

Ağladım yıldızların ışığıyla yansıyan ıslak saçlarına bakarken

denize düşen gül yüzünün resmi dalgalanırken

Ayağa kalktım,

Yürüdüm sahil boyunca

Bir ayak izlerim kaldı kumsalda

Birde gözyaşlarım

Denize ağlayan gönlüm

Çık yakamozlardan artık

Gel..

Al...

Senindir...

                                                     04 KASIM 2004  ŞIRNAK', 'Sonsuz bir mavide bulmuştum kendimi Bir gece yarısı, nedensiz Bir arayıştı bu biliyorum Geceleri rüyamı yazan gözlere tutulmuştum besbelli N...', ARRAY['Türk Edebiyatı','Şiir','Osman Çetinkaya']::text[], 8.5, '{"poet":"Osman Çetinkaya","poet_slug":"osman-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/denizkizi-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben, Sen ve Biz İkimiz', 'ben-sen-ve-biz-i-kimiz-yasin-bal-ftmcf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beni sen diye

bilmeliyim.

Seni biz diye

görmeliyim.

Ancak,

bir ben bilmeliyim,

seni.

Ne onlar gibi,

ne de onların gibi', 'Beni sen diye bilmeliyim. Seni biz diye görmeliyim. Ancak, bir ben bilmeliyim, seni. Ne onlar gibi, ne de onların gibi...', ARRAY['Türk Edebiyatı','Şiir','Yasin Bal']::text[], 8.5, '{"poet":"Yasin Bal","poet_slug":"yasin-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ben-sen-ve-biz-ikimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anılarda kalan', 'anilarda-kalan-gokhan-erdal-6smgy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nerden nereye..

uyanamadığım gecelerde; 

lüks ışığı altında,

tütün yaprakları ellerimde,

ve zift kokusu burnumda 

patates haşlaması damağımda

odun ateşinde demlenmiş çayım

karaduttan ellerimin  kanı 

nerden nereye

hiç unuturmuyum o anıları

						08.03.1993 ankara', 'Nerden nereye.. uyanamadığım gecelerde;  lüks ışığı altında, tütün yaprakları ellerimde, ve zift kokusu burnumda  patates haşlaması damağımd...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Erdal']::text[], 8.5, '{"poet":"Gökhan Erdal","poet_slug":"gokhan-erdal","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/anilarda-kalan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anestezik Hayat', 'anestezik-hayat-erol-yavuz-l56cs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Zaman ağırlaştıkça, yükünü taşır

çözer kendini bilmeceler

sonra gerçeği anlamanın o tuhaf acısı

ardı sıra 

şizofren solunum, iç kanama

beyindeki tümör erittikçe kendini

olanca umudunla açtığın kapıyı

yavaşça kapat gözlerine

sonra istediğin yoldan yürü

ardına bakmadan

ellerin cebinde

denizi bulana kadar yürü

istersen ıslıkta çal 

adımladıkça yalnızlığı

üşüdükçe ellerin

uyuştur kendini

çünkü dinmenin tek yoludur zaman

unutmanın tek yoludur uyuşmak

nasılsa ilacı morfin bu aşkın

nasılsa anestezik bir hayat…

11.12.05 

Ankara', 'Zaman ağırlaştıkça, yükünü taşır çözer kendini bilmeceler sonra gerçeği anlamanın o tuhaf acısı ardı sıra  şizofren solunum, iç kanama beyin...', ARRAY['Türk Edebiyatı','Şiir','Erol Yavuz']::text[], 8.5, '{"poet":"Erol Yavuz","poet_slug":"erol-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/anestezik-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiire Sevda Yükledim', 'siire-sevda-yukledim-sahin-karakulunc-7l1om', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dağlara sevda yükledim.

Oturdum karşısına seyrettim

İçin için yandı dağ

Dumanı başından çıktı

Başı dumanlı dağ oldu.

Şiire sevda yükledim

Geçtim karşısına dinledim

Ozanın sazına düştü

Tellerinde yandı şiir

Yanık türkü oldu

Eee

Sevda bu

Düştüğü yeri yakar

9 Temmuz 2005, Devrek', 'Dağlara sevda yükledim. Oturdum karşısına seyrettim İçin için yandı dağ Dumanı başından çıktı Başı dumanlı dağ oldu. Şiire sevda yükledim Ge...', ARRAY['Türk Edebiyatı','Şiir','Şahin Karakulunç']::text[], 8.5, '{"poet":"Şahin Karakulunç","poet_slug":"sahin-karakulunc","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/siire-sevda-yukledim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl Desem', 'nasil-desem-yasin-bal-qid3y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir özürle affeder misin? 

Ya da bir başka deyişle,

affeder misin, bir gülüşle.

Ya da bir başka ifadeyle.

Affeder misin bir çırpıda.

Ya da beklesem zamanla

Affeder misin? 

Seni çok seviyorum,

desem.

Ya da

sadece

seni seveceğimi söylesem.', 'Bir özürle affeder misin?  Ya da bir başka deyişle, affeder misin, bir gülüşle. Ya da bir başka ifadeyle. Affeder misin bir çırpıda. Ya da b...', ARRAY['Türk Edebiyatı','Şiir','Yasin Bal']::text[], 8.5, '{"poet":"Yasin Bal","poet_slug":"yasin-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/nasil-desem-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gürel''e', 'gurel-e-gurkan-suzer-txs1o', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Günler çabuk geçer

		kötü günler de

Yıllar çabul geçer

		ömür de

Dostluklar geç oluşur

Dostlar geç kalmaz ama

Yıllar, ömür, geçse de ardına bakmadan

Dostlar giderken ardına bakar.

Ankara, 17.2.1998', 'Günler çabuk geçer 		kötü günler de Yıllar çabul geçer 		ömür de Dostluklar geç oluşur Dostlar geç kalmaz ama Yıllar, ömür, geçse de ardına ...', ARRAY['Türk Edebiyatı','Şiir','Gürkan Süzer']::text[], 8.5, '{"poet":"Gürkan Süzer","poet_slug":"gurkan-suzer","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gurel-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok uzaklarda şimdi', 'cok-uzaklarda-simdi-gurkan-suzer-slppo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çok uzaklarda şimdi

geçmişte yaşanan tutkular

arayışı iki tenin birbirini

Çok uzaklarda şimdi 

yaşanamamış güzel beklentiler

Çok uzaklarda şimdi

ilk gençlik çağı

yüzde oluşan sivilceler

Çok uzaklarda şimdi

geleceği uzaklarda aramak

tutkusu umutla

Çok uzaklarda şimdi

Şimdiki zamanı konuşmayalı

hep geçmiş, gelecek

Çok uzaklarda şimdi...

Ankara, 28.8.2000.', 'Çok uzaklarda şimdi geçmişte yaşanan tutkular arayışı iki tenin birbirini Çok uzaklarda şimdi  yaşanamamış güzel beklentiler Çok uzaklarda ş...', ARRAY['Türk Edebiyatı','Şiir','Gürkan Süzer']::text[], 8.5, '{"poet":"Gürkan Süzer","poet_slug":"gurkan-suzer","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cok-uzaklarda-simdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değmez..', 'degmez-i-lknur-i-din-ezml2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dünya yangın yeri olmuş dostum! 

Topla artık eteklerini. 

Değmez namertlerin ezdiği, 

İnsanların çığlık çığlığa yaşadığı 

Bu toprağa düşmeye,değmez!', 'Dünya yangın yeri olmuş dostum!  Topla artık eteklerini.  Değmez namertlerin ezdiği,  İnsanların çığlık çığlığa yaşadığı  Bu toprağa düşmeye...', ARRAY['Türk Edebiyatı','Şiir','İlknur İdin']::text[], 8.5, '{"poet":"İlknur İdin","poet_slug":"i-lknur-i-din","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/degmez-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın matemetiksel boyutu', 'askin-matemetiksel-boyutu-gurkan-suzer-rch9b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yoksa sonsuzluğun sonu

Sensizliği tanımlayamam

sevgimi 

aşkımı

anlatamam sınırlı dünyanın 

merkezi belli olmayan ekseninde

aritmetik hislerim

duygusal dünyama yetmiyorsa

kusuru bende arama

Ankara, 3.5.2002', 'Yoksa sonsuzluğun sonu Sensizliği tanımlayamam sevgimi  aşkımı anlatamam sınırlı dünyanın  merkezi belli olmayan ekseninde aritmetik hisleri...', ARRAY['Türk Edebiyatı','Şiir','Gürkan Süzer']::text[], 8.5, '{"poet":"Gürkan Süzer","poet_slug":"gurkan-suzer","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/askin-matemetiksel-boyutu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok mu aradım seni', 'cok-mu-aradim-seni-gurkan-suzer-hcavi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çok mu aradım seni

Yıllar boyunca yalnızlığımda

Hep seni mi bekledim? 

Hep sıkıntılarım, huzursızluklarım

Şaşkınlığım seni beklemekten miydi? 

Mutluluğu, sevgiyi, aşkı 

Senin için mi bekledim? 

Beni bekletmek hoşuna mı gitti? 

Bekliyorum canımcığım

dönüşünü bekliyorum,

	yine bekletiyorsun...

Ankara, 26.6.2000.', 'Çok mu aradım seni Yıllar boyunca yalnızlığımda Hep seni mi bekledim?  Hep sıkıntılarım, huzursızluklarım Şaşkınlığım seni beklemekten miydi...', ARRAY['Türk Edebiyatı','Şiir','Gürkan Süzer']::text[], 8.5, '{"poet":"Gürkan Süzer","poet_slug":"gurkan-suzer","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cok-mu-aradim-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece yarısı oldu', 'gece-yarisi-oldu-gurkan-suzer-jq35l', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gece yarısı oldu

Yat borusu çalmış gibi 

Herkes yatmaya gitti

	kapandı ışıklar

		birden.

Ankara, 26.6.2000', 'Gece yarısı oldu Yat borusu çalmış gibi  Herkes yatmaya gitti 	kapandı ışıklar 		birden. Ankara, 26.6.2000...', ARRAY['Türk Edebiyatı','Şiir','Gürkan Süzer']::text[], 8.5, '{"poet":"Gürkan Süzer","poet_slug":"gurkan-suzer","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gece-yarisi-oldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Namussuzlar!', 'namussuzlar-gurkan-suzer-btm3u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yoksa yok muydu

		bir gereği

Anamın karnına düşmemin? 

Boş muydu ülküler

Bu ülkeyi kuranlar

Aldanmışlar mıydı? 

Çok zamandır 

	bocalıyorum

Yolumu arıyorum.

Yolunu bilen yok

Numara yapıyor 

	namussuzlar! 

Ankara, 26.6.2000', 'Yoksa yok muydu 		bir gereği Anamın karnına düşmemin?  Boş muydu ülküler Bu ülkeyi kuranlar Aldanmışlar mıydı?  Çok zamandır  	bocalıyorum Y...', ARRAY['Türk Edebiyatı','Şiir','Gürkan Süzer']::text[], 8.5, '{"poet":"Gürkan Süzer","poet_slug":"gurkan-suzer","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/namussuzlar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekliyorum umutla', 'bekliyorum-umutla-gurkan-suzer-pc3wj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bekliyorum umutla

	İlkbaharın sulu sepkenlerinde

			ıslak, hasta

Kırk ikindilerin

Serin sıcaklığını

Bekliyoum hasretini

gece bir üç nöbetinin soğukluğunda

		terhis günlerini bekler gibi

İstanbul, 26.4.2002', 'Bekliyorum umutla 	İlkbaharın sulu sepkenlerinde 			ıslak, hasta Kırk ikindilerin Serin sıcaklığını Bekliyoum hasretini gece bir üç nöbetini...', ARRAY['Türk Edebiyatı','Şiir','Gürkan Süzer']::text[], 8.5, '{"poet":"Gürkan Süzer","poet_slug":"gurkan-suzer","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bekliyorum-umutla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluğa uyudun', 'mutluluga-uyudun-gurkan-suzer-5glsq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mutluluğa uyudun

	huzura 

		yarınlara	

Aşkımıza uyudun

		çocuğumuza uyudun.

Binlerce yılın yorgunu gibi

Yarınlara dinç kalakacak gibi.

Ankara, 21.5.2001', 'Mutluluğa uyudun 	huzura  		yarınlara	 Aşkımıza uyudun 		çocuğumuza uyudun. Binlerce yılın yorgunu gibi Yarınlara dinç kalakacak gibi. Ankar...', ARRAY['Türk Edebiyatı','Şiir','Gürkan Süzer']::text[], 8.5, '{"poet":"Gürkan Süzer","poet_slug":"gurkan-suzer","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/mutluluga-uyudun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Namus', 'namus-gurkan-suzer-th718', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Namusludur bizim mahalleli

Bakmazlar kimsenin kızını, ırzına

Geçerken dikkat etmeli

	yan bakmamalı 

		konuya komşuya

Hani derler ya

	gözün arkada kalmasın diye...

Ahmet Bey,

	sabahları repo yapar,

		memurun hakkını yer

	akşamları hasbıhal eder

		Memur Hakkı Bey’le

			namus, şeref üzerine

Melih Bey piyanisttir,

	konservatuar okumamışsa da

		taş çıkartır okuyanlara

	                 kapıcı Hıdır Efendi’nin hakkındadır gözü

Afitap yirmisinde

		Mahalleye yeni taşındı

			orospu mu, orospu.

Herkesin gözü üzerinde.

Ahmet Bey, Hakkı Bey, Melih Bey, Hıdır Efendi

		bir hakkın peşindeler

			namus sözü üzerine.

Ankara, 9.2.2000', 'Namusludur bizim mahalleli Bakmazlar kimsenin kızını, ırzına Geçerken dikkat etmeli 	yan bakmamalı  		konuya komşuya Hani derler ya 	gözün a...', ARRAY['Türk Edebiyatı','Şiir','Gürkan Süzer']::text[], 8.5, '{"poet":"Gürkan Süzer","poet_slug":"gurkan-suzer","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/namus-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaktayım', 'uzaktayim-gurkan-suzer-drk5o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uzaktayım 

Olmama gerekenden 

çok uzakta

Yaşantım, isteğim, sen,

Çok uzaktayım

	hayallerimden.

Berlin, 27.2.1999', 'Uzaktayım  Olmama gerekenden  çok uzakta Yaşantım, isteğim, sen, Çok uzaktayım 	hayallerimden. Berlin, 27.2.1999...', ARRAY['Türk Edebiyatı','Şiir','Gürkan Süzer']::text[], 8.5, '{"poet":"Gürkan Süzer","poet_slug":"gurkan-suzer","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/uzaktayim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varlıkla yokluk çizgisinin', 'varlikla-yokluk-cizgisinin-gurkan-suzer-iu3z9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Varlıkla yokluk çizgisinin

2000 km uzağındayım

TRT INT var aramızda

Hoş insanlar

	sen inanmasan da

Gece oldu uyudun biliyorum.

O yüzden aramıyorum

	sesini içimden dinliyorum

Kulaklarım hasret sana 

		ben değil.

Uyuyorsun şimdi

	Biraz huzursuz belki

Kıyamıyorum dokunmaya, okşamaya

	Ellerim hasret sana 

                                ben değil

Bir hafta çok değil

		ayrılık için biliyorum

Ülkeler ayrı

	yüreğim değil.

Berlin, 27.2.1999', 'Varlıkla yokluk çizgisinin 2000 km uzağındayım TRT INT var aramızda Hoş insanlar 	sen inanmasan da Gece oldu uyudun biliyorum. O yüzden aram...', ARRAY['Türk Edebiyatı','Şiir','Gürkan Süzer']::text[], 8.5, '{"poet":"Gürkan Süzer","poet_slug":"gurkan-suzer","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/varlikla-yokluk-cizgisinin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boş sokaklar', 'bos-sokaklar-gurkan-suzer-i0uip', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Boş sokaklar

tanımadık dostlar

tanıdık bir yemekte

unutulan anıların peşindeyiz

Sadece bu an için 

	hatırlanmış anılar

Kimbilir hangi yakın dostun

Hayat arkadaşının haberi var? 

Kimbilir? 

Yoksa değerli mi oluyor insan

Yokluğunda dostlarının? 

Berlin, 27.2.1999', 'Boş sokaklar tanımadık dostlar tanıdık bir yemekte unutulan anıların peşindeyiz Sadece bu an için  	hatırlanmış anılar Kimbilir hangi yakın ...', ARRAY['Türk Edebiyatı','Şiir','Gürkan Süzer']::text[], 8.5, '{"poet":"Gürkan Süzer","poet_slug":"gurkan-suzer","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bos-sokaklar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Bedende Bir Kalp', 'i-ki-bedende-bir-kalp-yasin-bal-31mlg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yüreğine

yüreğimi ekliyorum.

Kanımız

ortak dolaşsın diye.

Bir sen 

nefes al,

bir ben.

İkimiz, 

bir ben olalım.

Ama sığmayalım

bir bedene.

Ne ben,

ne de

sen', 'Yüreğine yüreğimi ekliyorum. Kanımız ortak dolaşsın diye. Bir sen  nefes al, bir ben. İkimiz,  bir ben olalım. Ama sığmayalım bir bedene. Ne...', ARRAY['Türk Edebiyatı','Şiir','Yasin Bal']::text[], 8.5, '{"poet":"Yasin Bal","poet_slug":"yasin-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/iki-bedende-bir-kalp-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzun zamandır', 'uzun-zamandir-gurkan-suzer-cjl8v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Uzun zamandır

Yazmıyorum aşk üzerine

Uzun zamandır

yaşantım aşk üzerine

Yaşadıkça yazacaklarını

anlatamıyor insan

yaşadıklarını.

Ankara, 14.2.1999', 'Uzun zamandır Yazmıyorum aşk üzerine Uzun zamandır yaşantım aşk üzerine Yaşadıkça yazacaklarını anlatamıyor insan yaşadıklarını. Ankara, 14....', ARRAY['Türk Edebiyatı','Şiir','Gürkan Süzer']::text[], 8.5, '{"poet":"Gürkan Süzer","poet_slug":"gurkan-suzer","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/uzun-zamandir-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanki', 'sanki-gurkan-suzer-j2ubq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sanki

	Tanrısal bir güç

Hayatımın aşkını, eşimi

	diğer yarımı

Geçici olarak yerleştikleri eve

Beni 

cüzdanını kaybeden arkadaşımı 

Ona götürmek üzere

		bekletti.

Saçından tırnağına

huyundan ruhuna

bana bir lütuf 

	Tanrıdan

Ankara, 14.2.1999', 'Sanki 	Tanrısal bir güç Hayatımın aşkını, eşimi 	diğer yarımı Geçici olarak yerleştikleri eve Beni  cüzdanını kaybeden arkadaşımı  Ona götür...', ARRAY['Türk Edebiyatı','Şiir','Gürkan Süzer']::text[], 8.5, '{"poet":"Gürkan Süzer","poet_slug":"gurkan-suzer","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sanki-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Afrika’dan uçuyorum', 'afrika-dan-ucuyorum-gurkan-suzer-fs2yb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Afrika’dan uçuyorum

On bin metreden seyrediyorum

		karanlık toprakları

Bir şey yok

	sadece karanlık

Hayalinse aydınlık bu uçakta

Arada bir girdiğimiz türbülanslar

	içimi bir hoş etse de

Bekliyorum öpeceğim anı

			seni.

Sevmek

	sevmek

		seni

3.12.1998', 'Afrika’dan uçuyorum On bin metreden seyrediyorum 		karanlık toprakları Bir şey yok 	sadece karanlık Hayalinse aydınlık bu uçakta Arada bir g...', ARRAY['Türk Edebiyatı','Şiir','Gürkan Süzer']::text[], 8.5, '{"poet":"Gürkan Süzer","poet_slug":"gurkan-suzer","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/afrika-dan-ucuyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni seviyorum', 'seni-seviyorum-gurkan-suzer-dz8jw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni 

seviyorum

		seni

		     bekliyorum

				seni...

Seni senin

	benim gibi

	     seviyorum.

Dakar, 3.12.1998.', 'Seni  seviyorum 		seni 		     bekliyorum 				seni... Seni senin 	benim gibi 	     seviyorum. Dakar, 3.12.1998....', ARRAY['Türk Edebiyatı','Şiir','Gürkan Süzer']::text[], 8.5, '{"poet":"Gürkan Süzer","poet_slug":"gurkan-suzer","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/seni-seviyorum-306-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Afrika', 'afrika-gurkan-suzer-utfin', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Afrika

Art of Africa

Maskeler aldım 

	korkunç suratları var

Ahşaptan oymuşlar

	içleri boş

Heykeller aldım ince uzun 

		siyah 

			güzel

Hepsi senin için 

Afrikayı almak istedim 

Fazla çirkin geldi

Herşeyi uzaktan güzel

Uzaktan sevdim Afrikayı

Senin sevginin tersine! 

Uzaktan çekilmiyor hiç bir anı

Tutatamadıktan sonra elini.

Dakar, 3.12.1998', 'Afrika Art of Africa Maskeler aldım  	korkunç suratları var Ahşaptan oymuşlar 	içleri boş Heykeller aldım ince uzun  		siyah  			güzel Hepsi...', ARRAY['Türk Edebiyatı','Şiir','Gürkan Süzer']::text[], 8.5, '{"poet":"Gürkan Süzer","poet_slug":"gurkan-suzer","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/afrika-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Avunuyoruz işte', 'avunuyoruz-iste-gurkan-suzer-lf7jb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Avunuyoruz işte

Kimimiz

	otobüse binebildik diye

Kimimiz 

	şükür oturacak yer bulduk diye

Kimimiz 

	arabamızda iyi müzik dinleyebiliyoruz diye.

Avunuyoruz işte

	yaşıyoruz diye.

Ankara, 31.12.1998', 'Avunuyoruz işte Kimimiz 	otobüse binebildik diye Kimimiz  	şükür oturacak yer bulduk diye Kimimiz  	arabamızda iyi müzik dinleyebiliyoruz di...', ARRAY['Türk Edebiyatı','Şiir','Gürkan Süzer']::text[], 8.5, '{"poet":"Gürkan Süzer","poet_slug":"gurkan-suzer","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/avunuyoruz-iste-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sömürgelerin sonu', 'somurgelerin-sonu-gurkan-suzer-uvk6b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güzel olan ne varsa

Beyaz adama ver Tanrım

Kara adam halinden memnun

Umrunda bile değil 

Suyun öte yanında ne var 

		ne yok? 

Dakar, 2.12.1998', 'Güzel olan ne varsa Beyaz adama ver Tanrım Kara adam halinden memnun Umrunda bile değil  Suyun öte yanında ne var  		ne yok?  Dakar, 2.12.19...', ARRAY['Türk Edebiyatı','Şiir','Gürkan Süzer']::text[], 8.5, '{"poet":"Gürkan Süzer","poet_slug":"gurkan-suzer","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/somurgelerin-sonu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlık', 'karanlik-gurkan-suzer-89jnm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kara insanlar

Karanlık ruhlar

Kara Afrika

İnsanlar,

	ruhlar,

		Afrika

Karanlık sadece.

Dakar, 30.11.1998', 'Kara insanlar Karanlık ruhlar Kara Afrika İnsanlar, 	ruhlar, 		Afrika Karanlık sadece. Dakar, 30.11.1998...', ARRAY['Türk Edebiyatı','Şiir','Gürkan Süzer']::text[], 8.5, '{"poet":"Gürkan Süzer","poet_slug":"gurkan-suzer","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/karanlik-79-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herşey yolunda', 'hersey-yolunda-gurkan-suzer-fvxfx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Rüzgar dindi

Dalgalar duruldu

Çocuklar kumsalda

		oynuyorlar

Daha büyükleri 

	karşı cinsin peşinde

Turistler

	herkesin derdinde

Dalgalar usulca kıyıya vuruyor

Güneş tam tepede

Herşey yolunda

Teşekkürler Tanrım

	Herşey yolunda.

Kuşadası, 2.9.1998', 'Rüzgar dindi Dalgalar duruldu Çocuklar kumsalda 		oynuyorlar Daha büyükleri  	karşı cinsin peşinde Turistler 	herkesin derdinde Dalgalar usu...', ARRAY['Türk Edebiyatı','Şiir','Gürkan Süzer']::text[], 8.5, '{"poet":"Gürkan Süzer","poet_slug":"gurkan-suzer","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hersey-yolunda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm tercihi', 'olum-tercihi-gurkan-suzer-i5uf3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'O kadar rahat mı

Tercih etmek ölümü? 

Kaçmamak ecelden

Üstelik son kaçınılmazsa,

Kabüllenir mi insan? 

Yoksa delice kaçmaya mı çalışır? 

Ya da durduk yerde

Bırakır mı yaşamı 

		ölüme

Ne götürüyor insanı

	tercihli sona

		bu kadar rahat

Gurur,

	kibir,

		vatanseverlik

	NE? 

Kuşadası, 1.9.1998', 'O kadar rahat mı Tercih etmek ölümü?  Kaçmamak ecelden Üstelik son kaçınılmazsa, Kabüllenir mi insan?  Yoksa delice kaçmaya mı çalışır?  Ya ...', ARRAY['Türk Edebiyatı','Şiir','Gürkan Süzer']::text[], 8.5, '{"poet":"Gürkan Süzer","poet_slug":"gurkan-suzer","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/olum-tercihi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tekrar Gelicek misin?', 'tekrar-gelicek-misin-yasin-bal-42080', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir ertesi gün çiği gibisin.

Hani çiçeklerin üstünde.

Sadece birkaç dakikalık.

Bekle bile diyemeden,

bir ertesi gün daha.

Bekle demek için,

sadece sormak için

bir daha hangi ertesi gün

benimlesin...', 'Bir ertesi gün çiği gibisin. Hani çiçeklerin üstünde. Sadece birkaç dakikalık. Bekle bile diyemeden, bir ertesi gün daha. Bekle demek için, ...', ARRAY['Türk Edebiyatı','Şiir','Yasin Bal']::text[], 8.5, '{"poet":"Yasin Bal","poet_slug":"yasin-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/tekrar-gelicek-misin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hacı yatmaz..', 'haci-yatmaz-i-lknur-i-din-a089q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'En mutlu aşklar bile, 

Acı şiir yazdırır insana. 

Şairler en acı şiirlerini 

Yüreklerine banarak yazarlar. 

Bir teselli arar her aşık, 

Bazen bir gülüş, 

Bazen bir dokunuş. 

Her evlilik sadakat bekler 

Her eş de vefa.. 

As olan yalnızlık korkusudur 

Yalan söyler her aşk 

Yalancıdır her aşık 

Kapılar kapanacak korkusu 

İnsanı evlilik cüzdan sahibi yapar!', 'En mutlu aşklar bile,  Acı şiir yazdırır insana.  Şairler en acı şiirlerini  Yüreklerine banarak yazarlar.  Bir teselli arar her aşık,  Baze...', ARRAY['Türk Edebiyatı','Şiir','İlknur İdin']::text[], 8.5, '{"poet":"İlknur İdin","poet_slug":"i-lknur-i-din","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/haci-yatmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerim ufukta', 'gozlerim-ufukta-gurkan-suzer-27c0f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözlerim ufukta

Ufuk uzakta

Ne bir gemi geliyor,

Ne bir martı kanatlanıyor

Hava rüzgârlı

	ufuk uzaklaşıyor iyice

Gün batmak üzre

	kızardı ufuk, gök 

			hafiften

Gruba bakarken

	bu son fasıl olmamalı 

			diyorum içimden.

Kuşadası, 1.9.1998', 'Gözlerim ufukta Ufuk uzakta Ne bir gemi geliyor, Ne bir martı kanatlanıyor Hava rüzgârlı 	ufuk uzaklaşıyor iyice Gün batmak üzre 	kızardı uf...', ARRAY['Türk Edebiyatı','Şiir','Gürkan Süzer']::text[], 8.5, '{"poet":"Gürkan Süzer","poet_slug":"gurkan-suzer","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gozlerim-ufukta-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Milyarderler ve ben', 'milyarderler-ve-ben-gurkan-suzer-v4rj6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Milyarderler ve ben

Karşı karşıyayız

	Kuşadasında

Onlar buraya gelmek için 

	Binlerce dolar ödüyor

Ben daha azını

Onlar dünyanın en büyük gemisindeler

Ben karada....

Onlar,

	ne kadar büyük olsa da 

bir insan yapısındalar

Benimse ayağım 

		Tanrı yapısında...

Kuşadası, 1.9.1998', 'Milyarderler ve ben Karşı karşıyayız 	Kuşadasında Onlar buraya gelmek için  	Binlerce dolar ödüyor Ben daha azını Onlar dünyanın en büyük ge...', ARRAY['Türk Edebiyatı','Şiir','Gürkan Süzer']::text[], 8.5, '{"poet":"Gürkan Süzer","poet_slug":"gurkan-suzer","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/milyarderler-ve-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgilim benim', 'sevgilim-benim-gurkan-suzer-l533j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sıcaklardan bunalıp denize girmek 

	kadar rahatlatıcı 

			bir gülüşün

Taze, nefis bir sabah kahvaltısı 

		lezzeti gibi dudakların

Sembolerle tanıtmaya çalışıp da 

	anlatılamayacak kadar gizemli

		

Sevgilim benim

Ankara, 26.7.1998', 'Sıcaklardan bunalıp denize girmek  	kadar rahatlatıcı  			bir gülüşün Taze, nefis bir sabah kahvaltısı  		lezzeti gibi dudakların Sembolerle...', ARRAY['Türk Edebiyatı','Şiir','Gürkan Süzer']::text[], 8.5, '{"poet":"Gürkan Süzer","poet_slug":"gurkan-suzer","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sevgilim-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek seni', 'sevmek-seni-gurkan-suzer-l8s22', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kurtulmak gibi

Sıkan bir ayakkabıdan 

Çorabı çıkarıp soğuk çarsafta 

		ayağını gezdirip

			ayağını bulmak gibi

Haz verici ve doğal

Uyandığımda seni bulmak yanımda

Sıkıcı bir yaşamdan sonra

	Mutluluğa ermek gibi.

		Sevmek seni.

Ankara, 23.7.1998.', 'Kurtulmak gibi Sıkan bir ayakkabıdan  Çorabı çıkarıp soğuk çarsafta  		ayağını gezdirip 			ayağını bulmak gibi Haz verici ve doğal Uyandığım...', ARRAY['Türk Edebiyatı','Şiir','Gürkan Süzer']::text[], 8.5, '{"poet":"Gürkan Süzer","poet_slug":"gurkan-suzer","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sevmek-seni-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değerli anılar', 'degerli-anilar-gurkan-suzer-c3buz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Değerli olanlar 

		kullanılmış anılardır

Başkalarının anıları

		pek önemsenmez.

Moskova, 11.12.2005', 'Değerli olanlar  		kullanılmış anılardır Başkalarının anıları 		pek önemsenmez. Moskova, 11.12.2005...', ARRAY['Türk Edebiyatı','Şiir','Gürkan Süzer']::text[], 8.5, '{"poet":"Gürkan Süzer","poet_slug":"gurkan-suzer","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/degerli-anilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara perçemli kız', 'kara-percemli-kiz-gurkan-suzer-sw86q', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tasadüfen yaşadığımız ülkede

Garip bir şansla buluştuk,

			görüştük

Tesadüften arınıp kasten

			azimle arzuladım 

Mutluluk, huzur seninle 

		anlam buldu yaşamımda

Varlığın kara perçemlerinle 

			kirpik altı bakışların

Hırçınlığın ve huzursuzluğunla

Sende beni sana bağlayan 

			bir şeyler var

				ismini henüz koyamadığım.

Ankara, 17.6.1998.', 'Tasadüfen yaşadığımız ülkede Garip bir şansla buluştuk, 			görüştük Tesadüften arınıp kasten 			azimle arzuladım  Mutluluk, huzur seninle  	...', ARRAY['Türk Edebiyatı','Şiir','Gürkan Süzer']::text[], 8.5, '{"poet":"Gürkan Süzer","poet_slug":"gurkan-suzer","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kara-percemli-kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlık saçlı kız', 'karanlik-sacli-kiz-gurkan-suzer-hmzi5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kaybolan cüzdan mıydı? 

		bulunan aşk mı? 

Tesadüf mü hayat

Kader mi başa gelen? 

Müdahale etmeli mi? 

etmemeli mi? 

Kaçar mı karanlık saçlı kız,

		kaderimi beklersem? 

Ankara, 27.4.1998.', 'Kaybolan cüzdan mıydı?  		bulunan aşk mı?  Tesadüf mü hayat Kader mi başa gelen?  Müdahale etmeli mi?  etmemeli mi?  Kaçar mı karanlık saçlı...', ARRAY['Türk Edebiyatı','Şiir','Gürkan Süzer']::text[], 8.5, '{"poet":"Gürkan Süzer","poet_slug":"gurkan-suzer","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/karanlik-sacli-kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlık, çıkmaz sokaklar', 'karanlik-cikmaz-sokaklar-gurkan-suzer-bj5ce', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Karanlık, çıkmaz sokaklar

Islak, puslu, pis köşeler

Yerde yatan evsizler

		birbirine sokulmuş

Evimde otururken düşünüyorum

Sıcak, samimi	

	Kuru ve rahatım,

		yalnızım

Neden, ne zamandır, nasıl? 

Yalnızım, 

		O kadar.

Ankara, 20.4.1998', 'Karanlık, çıkmaz sokaklar Islak, puslu, pis köşeler Yerde yatan evsizler 		birbirine sokulmuş Evimde otururken düşünüyorum Sıcak, samimi	 	K...', ARRAY['Türk Edebiyatı','Şiir','Gürkan Süzer']::text[], 8.5, '{"poet":"Gürkan Süzer","poet_slug":"gurkan-suzer","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/karanlik-cikmaz-sokaklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ege’nin büyülü yumuşak müziği', 'ege-nin-buyulu-yumusak-muzigi-gurkan-suzer-4xegi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ege’nin büyülü yumuşak müziği

Dostluk adalarından sekerek 

			Aşıyor Ege’yi

Buluşturuyor komşuları

Buğulu bakan aşık gözler

Puslu, sinsi, küçük oyunlar

Kandırmalar hep aşk için.

Ankara, 20.4.1998', 'Ege’nin büyülü yumuşak müziği Dostluk adalarından sekerek  			Aşıyor Ege’yi Buluşturuyor komşuları Buğulu bakan aşık gözler Puslu, sinsi, kü...', ARRAY['Türk Edebiyatı','Şiir','Gürkan Süzer']::text[], 8.5, '{"poet":"Gürkan Süzer","poet_slug":"gurkan-suzer","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ege-nin-buyulu-yumusak-muzigi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen!', 'sen-cem-cagman-h01xv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sen dilim de şarkısın

kalbimde ki sancısın

damarımdan akarsın

gönül nasıl yanmasın

derde  dermansın

katlime fermansın

gönlüme sultansın

kimseler  bilmesin

söyleyemem kimseye

karar verdim   ölmeye

enson durakta inmeye

derdim le inleye inleye', 'sen dilim de şarkısın kalbimde ki sancısın damarımdan akarsın gönül nasıl yanmasın derde  dermansın katlime fermansın gönlüme sultansın kims...', ARRAY['Türk Edebiyatı','Şiir','Cem Çağman']::text[], 8.5, '{"poet":"Cem Çağman","poet_slug":"cem-cagman","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-703-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümü babamın', 'olumu-babamin-gurkan-suzer-8rafq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Onaltı yıl geçse de

		unutmamışım....

Anlam veremediğim bir yolculuktan sonra

Sabahın kör bir vaktinde

ve yağmur çiselemiş yollarında 

Ankara’ya dönmüştüm.

Garip bir sevinçti içimdeki

Anneannem ağlamıştı yol boyu da

		bir şey dememişti bana

Belki de kandırmıştım kendimi

		dua ederken yol boyunca.

Sonra on iki yaşımın çocuk sorumluluğuyla

		fiş almıştım Keçiören taksisine

	- o zamanlar taksimetre yoktu ki

Ve yine gri bulutların altında

		ıslak yolalrında Ankara’nın

				yuvama dönüyordum

Hacı Murat taksi zorla da çıksa Asfalt yokuşunu

Sonunda Şengül Mahallesi Üçgül Sokak 7/9 

				duruyordu karşımda.

Kapıda karşılaştığım kapı komşu teyze

			gülmeye çalışsa da

				gitmiyordu sanki bazı işler yolunda

Bizimkileri alt katta bırakığ eve koşuyordum ki

Sabahın köründe kapımız açıktı

			ve yüz mumluk ampulün ışığı

				hüzünle süzülüyordu aradan.

Eniştem ve dayımdı beni karşılayan 

Ben yıkılmış, ararken annemi

	Unutmuşum sormayı babamı

			unutmuştu birileri onu

Eline sımsıkı sarılıp Eniştemin

			Teyzeme gittim.

Korkunç gerçeği kabullenmeye çalışıyordum

			kimse söylemese de bana

Hatırlıyorum işte, unutmadım o günü

Oysa hatırlamıyorum babamın boyunu

Hatta bilmiyorum bıyıkları var mıydı, yok muydu? 

	Unutmasam da kokusunu.

Ankara, 19.3.1998', 'Onaltı yıl geçse de 		unutmamışım.... Anlam veremediğim bir yolculuktan sonra Sabahın kör bir vaktinde ve yağmur çiselemiş yollarında  Ankar...', ARRAY['Türk Edebiyatı','Şiir','Gürkan Süzer']::text[], 8.5, '{"poet":"Gürkan Süzer","poet_slug":"gurkan-suzer","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/olumu-babamin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siz yoktunuz', 'siz-yoktunuz-gurkan-suzer-i5hwz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Siz yoktunuz

	doğduğumda

Yoktunuz ilk ağlayışımda

Siz olmadınız avutan beni

		yokluğunda dostlarımın

Olmadı bir yakınlığınız

Siz bulunmadınız yanımda

		yitikliğinde sevdanın

Bulamadınız çare yokluğa

Siz yok oluşumda bulunmadınız

			yalnızlığımda

Siz, sessiz, ürkek, uzaktınız

			yoktunuz.

Ankara, 31.3.1998', 'Siz yoktunuz 	doğduğumda Yoktunuz ilk ağlayışımda Siz olmadınız avutan beni 		yokluğunda dostlarımın Olmadı bir yakınlığınız Siz bulunmadını...', ARRAY['Türk Edebiyatı','Şiir','Gürkan Süzer']::text[], 8.5, '{"poet":"Gürkan Süzer","poet_slug":"gurkan-suzer","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/siz-yoktunuz-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni görmek', 'seni-gormek-gurkan-suzer-rfntl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni görmek 

Puslu gökyüzünde

Yitip giden yıldız gibi

Seni duymak

Sessiz, derin bir huzur senfonisi

Seni susmak

Dinlerken dört mevsimi Vivaldi’den

Seni öpmek

Suyu kana kana içmek gibi

Seni sevmek

	Sevmek gibi doyumsuz.

Ankara, 27.3.1998', 'Seni görmek  Puslu gökyüzünde Yitip giden yıldız gibi Seni duymak Sessiz, derin bir huzur senfonisi Seni susmak Dinlerken dört mevsimi Vival...', ARRAY['Türk Edebiyatı','Şiir','Gürkan Süzer']::text[], 8.5, '{"poet":"Gürkan Süzer","poet_slug":"gurkan-suzer","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seni-gormek-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşünüyorum seni bütün gün', 'dusunuyorum-seni-butun-gun-gurkan-suzer-5szuk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Düşünüyorum seni bütün gün

		uykumun dışında

Rüyalarımda görüyorum seni 

		gece boyunca

Yine de yaranamıyorum sana

Açınca gözlerini kocaman kocaman

		Sabah karanlığında

Kendimi görmek yansıyan parlaklığında

Güneşli bir gün başlarken umutla

Ankara, 18.3.1998', 'Düşünüyorum seni bütün gün 		uykumun dışında Rüyalarımda görüyorum seni  		gece boyunca Yine de yaranamıyorum sana Açınca gözlerini kocaman ...', ARRAY['Türk Edebiyatı','Şiir','Gürkan Süzer']::text[], 8.5, '{"poet":"Gürkan Süzer","poet_slug":"gurkan-suzer","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/dusunuyorum-seni-butun-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alın Yazısı', 'alin-yazisi-alper-kuruk-wg409', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Öyle bir yazıdır ki bu

Ne Türkçe''ye benzer,ne Hintçe''ye,

Ne İngilizce''ye,ne de Çince''ye...

Velhasıl hiçbir yazıya benzemez bu yazı...

Okumak için uğraşıyorum bazı

Seçemiyorum ne bir kelimesini,

Ne de bir harfini.

Nasıl bir yazıdır edemem tarifini? 

Gözüme ilişen munis iki kelime 

Ki ilgilidir onlarla cümle.

Bunlar:doğum ve ölümdür...

İşte bunların arasını dolduran

Ve mukadderâta tâbi olan

Bir meçhûldür ömür...', 'Öyle bir yazıdır ki bu Ne Türkçe''ye benzer,ne Hintçe''ye, Ne İngilizce''ye,ne de Çince''ye... Velhasıl hiçbir yazıya benzemez bu yazı... Okumak...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/alin-yazisi-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boş Zamanlarımda', 'bos-zamanlarimda-gurkan-suzer-3e7ot', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Boş zamanlarımda

Kitaplar okuyorum,

	siyaset, tarih ekonomi

		ve aşk üzerine

Şiirler okuyorum

	toplumcu, bireysel, aşık

İşe gidiyorum, çalışıyorum akşama kadar

Televizyon seyredip, radyo dinliyorum

Boş zamanlarımda

Kitap yazıyorum, şiir yazıyorum

		Senin için, aşk üzerine

Seni düşünerek geçiriyorum

		Dolu anlarını zamanımın.

Ankara, 18.3.1998', 'Boş zamanlarımda Kitaplar okuyorum, 	siyaset, tarih ekonomi 		ve aşk üzerine Şiirler okuyorum 	toplumcu, bireysel, aşık İşe gidiyorum, çalış...', ARRAY['Türk Edebiyatı','Şiir','Gürkan Süzer']::text[], 8.5, '{"poet":"Gürkan Süzer","poet_slug":"gurkan-suzer","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bos-zamanlarimda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıkıldım kovalamaktan', 'sikildim-kovalamaktan-gurkan-suzer-ixsqh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sıkıldım kovalamaktan 

Sıkıldım,

	sıkıldım

Yoruldum peşinden insanların

			koşmaktan

Yalnız kalmaktan,

		terk edilmekten,

			sıkılmaktan 

				usanmaktan.

Bıktım artık,

	bıktım

		melankoliden.

Ankara, 18.3.1998', 'Sıkıldım kovalamaktan  Sıkıldım, 	sıkıldım Yoruldum peşinden insanların 			koşmaktan Yalnız kalmaktan, 		terk edilmekten, 			sıkılmaktan  		...', ARRAY['Türk Edebiyatı','Şiir','Gürkan Süzer']::text[], 8.5, '{"poet":"Gürkan Süzer","poet_slug":"gurkan-suzer","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sikildim-kovalamaktan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Defne Dalı', 'defne-dali-suna-aras-4z97d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hani bana defne dalı getirecektin

Hakkâri’de çocuklar okula gidecekti

Türküsünü İstanbul’ da söyleyecekti Zilan

Biraz mavi biraz bulut biraz da güneş hani

Kimse ölmeyecekti.

Hani bana defne dalı getirecektin

Beyaz kuşlar konacaktı aşkımın mavisine

Ay ışığı vuracak dağlardan buralara

Başımdan aşağıya döküp sevinecektim

Biraz deniz biraz yosun biraz da Fırat hani

Kimse ölmeyecekti.

Barış ölüm orucunda sevgilim

Aşkımızı sen vurdun

Gök bir yırtık çaput sarkıyor üstümüze

Denizlerin kuğuları boğuldu

Biraz sevgi biraz sevda bitmeyecek aşk hani

Hani bana defne dalı getirecektin.', 'Hani bana defne dalı getirecektin Hakkâri’de çocuklar okula gidecekti Türküsünü İstanbul’ da söyleyecekti Zilan Biraz mavi biraz bulut biraz...', ARRAY['Türk Edebiyatı','Şiir','Suna Aras']::text[], 8.5, '{"poet":"Suna Aras","poet_slug":"suna-aras","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/defne-dali-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimlik-2-', 'kimlik-2-zulfikar-yapar-kaleli-ube0e', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'image src=''http://www.antoloji.com/siir/media/11/www_antoloji_com_346511_751.GIF''400'' height=''300''

embed src= http://www.discoverturkey.com/muzik/istiklal_marsi.mp3

font face=''Comic Sans MS'' color=''black'' size=''0,5''

Sen ey vatanın onuru, mahzun olma dalgalan

Yalvarırım ey rüzgarlar kesmeyin hızı bir an

Kasırgalar aşka gelir, nağmeler yolda kalır

Sen düşersen ben düşerim, toprağım olur viran.', 'image src=''http://www.antoloji.com/siir/media/11/www_antoloji_com_346511_751.GIF''400'' height=''300'' embed src= http://www.discoverturkey.com/...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kimlik-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kal', 'kal-turan-ozturk-ugrt0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İlle de gideceksen

Sana

Kal demeyeceğim..

Eğer 

Gideceksen ille de

Valizini 

Ben getireceğim..

Hangi şair

Hangi mısrasında

Hangi şarkı

Hangi notasında 

Diyecekse desin..

Ben 

Sana

Kal, kal,kal

Demeyeceğim..

15/01/2005', 'İlle de gideceksen Sana Kal demeyeceğim.. Eğer  Gideceksen ille de Valizini  Ben getireceğim.. Hangi şair Hangi mısrasında Hangi şarkı Hangi...', ARRAY['Türk Edebiyatı','Şiir','Turan Öztürk']::text[], 8.5, '{"poet":"Turan Öztürk","poet_slug":"turan-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kal-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sivri Sinek', 'sivri-sinek-fatih-demir-dzzx6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uykumun en tatlı yerinde geldin

Vızzz Vızzz deyip başmın etini yedin

Beni iki günde deliye çevirdin

Yakalarsam bittin sen sivri sinek

O kadar küçüksün ki seni zor görüyorum

Ama burada bir yerde olduğunu biliyorum

Seni öldürmek için siper alıyorum

Yalakarsam bittin sen sivri sinek

İzini sessizce sürüyorum

Seni zor da olsa takip ediyorum

Evin her yerine tuzak kuruyorum

Yakalarsam bittin sen sivri sinek

Suçum neydi ki benim

Niye gelip de kanımı emdin

Sayende bir deri bir kemik gibiyim

Yakalarsam bittin sen sivri sinek', 'Uykumun en tatlı yerinde geldin Vızzz Vızzz deyip başmın etini yedin Beni iki günde deliye çevirdin Yakalarsam bittin sen sivri sinek O kada...', ARRAY['Türk Edebiyatı','Şiir','Fatih Demir']::text[], 8.5, '{"poet":"Fatih Demir","poet_slug":"fatih-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sivri-sinek-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-fatih-demir-9qole', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'S...eni herşeyden çok seviyorum

E...llerimi açtım ALLAH''ıma dua ediyorum

N...e ölmeyi istiyorum nede sensizliği

 İ...nan gözlerim yolda hep seni bekliyorum

S...evmek neye yararki sensiz olunca

E...llerini bir başkası tutunca

V...eda etmek o kadar da kolay olsa

 İ...nan bana zindana döner sensiz bu dünya

Y...ağmur gibi gözyaşlarım sensizliğe

O...lmaz diyemiyorum bir türlü yüreğime

R...esmini öpüyorum sensiz gecelerimde

U...yku tutmuyor gözlerimi birtanem

M...atemliyim yine bu gece..', 'S...eni herşeyden çok seviyorum E...llerimi açtım ALLAH''ıma dua ediyorum N...e ölmeyi istiyorum nede sensizliği  İ...nan gözlerim yolda hep ...', ARRAY['Türk Edebiyatı','Şiir','Fatih Demir']::text[], 8.5, '{"poet":"Fatih Demir","poet_slug":"fatih-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/seni-seviyorum-307-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kâbus', 'k-bus-alper-kuruk-9unrh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kasvetli olursa hava 

Kâbusla dolar rüya.

Böyle bir gecede gözlerimi kapadım

Rüya âlemine daldım.

Bu âlemde herkes donjuan olur

Herkes kendine göre bir eş bulur.

Var mıdır hiç evlenmeyen dünyada? 

Onlar dahi evlenirler rüyada...

Çok büyüktür mâzinin bu âleme tesiri

Her insan bu âlemde tahayyülünün esiri.

Ben de güzel tahayyüllerle girdim bu âleme

Önümde bir aşk merdiveni belirdi kademe kademe.

En üst kademede taçlı,güzel bir peri

Aşkından oluvermiştim âniden serseri.

Çıktım yavaş yavaş en üst kata

Kuş bakışı bir nazar atfettim alta.

Uçurum kenarında bulunuyordum

Korkudan gözüm açıldı,bölündü uykum.

Meğer karyolunun kenarına gelmişim

Rüya âleminin aşk perisine ulaşmakiçin

Bir basamak daha çıksam hemen düşecekmişim...', 'Kasvetli olursa hava  Kâbusla dolar rüya. Böyle bir gecede gözlerimi kapadım Rüya âlemine daldım. Bu âlemde herkes donjuan olur Herkes kendi...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kabus-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üç noktanın ikisi...', 'uc-noktanin-ikisi-samiha-i-kbal-y7kn7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Eserken rüzgar, ağlarken gök 

Aldırmadık ağaçların direnişine

Ağaçlar kadar olamadık

Noktaladık.

Bir nokta değil üç nokta koyduk

Sevdamızın ardına

Sen herzaman yaptığın gibi

Düz yollara yönlendirdin adımlarını

Bana uçurumlar kaldı  aşılacak

Gercek aşkın ne olduğunu bilmeden

İyi bir nedendir belki, hayat adına verilen

Soğumuş bir kül yığınıdır, yangınlar cıkarmak mı? 

Ben sevgilinin cesedini bile gözden cıkarmışken...

Essiz bir ustalıkla yapacağım bu işi

Sabrın yüreğinden kavrayıp, inkara kalkışmadan

Unutsam diyorum, geçmişi geleçeği

Silsem diyorum şu üç noktanın ikisini.', 'Eserken rüzgar, ağlarken gök  Aldırmadık ağaçların direnişine Ağaçlar kadar olamadık Noktaladık. Bir nokta değil üç nokta koyduk Sevdamızın ...', ARRAY['Türk Edebiyatı','Şiir','Samiha İkbal']::text[], 8.5, '{"poet":"Samiha İkbal","poet_slug":"samiha-i-kbal","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/uc-noktanin-ikisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatamadığım', 'anlatamadigim-aytekin-orhan-vom6q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen benim anlatamadığım sevdam.

Sen benim yaşamla olan kavgam.

Sen benim gizemli dünyam.

Sen benim,

Sen benim hayata baktığım aynamsın. 

Sen benim soluduğum hava,

Sen benim içimde yanan yangınsın,

Bildiğim söndüremediğim…

Sen benim atan her kalp atışımsın,

Duyduğum dindiremediğim…

Sen benim…

Ve daha birçok şey…

15/04/2005', 'Sen benim anlatamadığım sevdam. Sen benim yaşamla olan kavgam. Sen benim gizemli dünyam. Sen benim, Sen benim hayata baktığım aynamsın.  Sen...', ARRAY['Türk Edebiyatı','Şiir','Aytekin Orhan']::text[], 8.5, '{"poet":"Aytekin Orhan","poet_slug":"aytekin-orhan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/anlatamadigim-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdalım ateş', 'sevdalim-ates-aytekin-orhan-qutod', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Heyy güneş sana sesleniyorum

Yakma içimi artık yeter

Zaten yanıyor benim yüreğim

Cehennemden beter

O gittiğinden beri… 

Senin sıcaklığın ne ki 

Benim gövdemde volkanlar kaynar

Düşlerime kor ateşler düşüyor

O gittiğinden beri…

Neden saklanıyorsun bulutların arkasına

İçimdeki yangın sanadamı ulaştı yoksa

Ben o ateşle yaşıyorum anlasana

O gittiğinden beri…

11/09/2003', 'Heyy güneş sana sesleniyorum Yakma içimi artık yeter Zaten yanıyor benim yüreğim Cehennemden beter O gittiğinden beri…  Senin sıcaklığın ne ...', ARRAY['Türk Edebiyatı','Şiir','Aytekin Orhan']::text[], 8.5, '{"poet":"Aytekin Orhan","poet_slug":"aytekin-orhan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sevdalim-ates-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşık Dudağı', 'asik-dudagi-alper-kuruk-p6hae', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Susuzluktan çatlak çatlak olmuş

Kurak toprak gibidir 

Aşka susamış dudak...

Nemle karış karış karışan

Çatlak toprak

Nasıl verirse bitkiye can,

Aşıkının dudağına kavuşan

Aşka susamış dudak

Birçok bûseler alacak,

Neme doyan toprak gibi

O da öpüşe doyacak.

Yavaş yavaş kımıldayarak

Açılan bu dudaklardan

Topraktan fışkıran bitki yerine

Şehvet dolu aşk sözleridir çıkan...', 'Susuzluktan çatlak çatlak olmuş Kurak toprak gibidir  Aşka susamış dudak... Nemle karış karış karışan Çatlak toprak Nasıl verirse bitkiye ca...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/asik-dudagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dumanlı gözlerinle ağla', 'dumanli-gozlerinle-agla-aytekin-orhan-98qnu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'beklediğin rüzgarlar hiç esmeyecek,

uğramayacak bu limana o gemiler...

kurtulamayacaksın yalnızlığından! 

kahve karanlığı içinde,

hıçkıra hıçkıra dökülecek yaşlar,

dumanlı gözlerinden ağlayacaksın...

hiç gelmeyecek o adam! 

sırma saçlarını tarayan,

rüyalarını okşayan... 

terkedip gittiğinde düşünmedin,

düşünmedin gururundan yaşadıklarını...

sildin bir kalemde yazılmamışçasına,

hiç yaşanmamış gibi...

sıra sende şimdi; 

ağla hazan yağmurlarıyla,

karanfil kokusuyla, mevsim sonbahar...

yüzündeki derin çizgilerle,

kızıl karanlıkta yalnızlığınla...

dumanlı gözlerinle ağla...

11/10/2003', 'beklediğin rüzgarlar hiç esmeyecek, uğramayacak bu limana o gemiler... kurtulamayacaksın yalnızlığından!  kahve karanlığı içinde, hıçkıra hı...', ARRAY['Türk Edebiyatı','Şiir','Aytekin Orhan']::text[], 8.5, '{"poet":"Aytekin Orhan","poet_slug":"aytekin-orhan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dumanli-gozlerinle-agla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine gel', 'yine-gel-aytekin-orhan-tqm9z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gidişin beni bitirir,

Sonu olur yüreğimdeki heyecanın.

Söner gözerimdeki ateş! 

Bir kıvılcım çakar bedenimden,

İnzivaya çekerim kendimi başka gözlerden... 

Her nereye gidersen yine gel,

Dön bana geri gel,

Bu beden sensiz yaşamaz,

Salma boşluğa geri gel...

24/05/2005', 'Gidişin beni bitirir, Sonu olur yüreğimdeki heyecanın. Söner gözerimdeki ateş!  Bir kıvılcım çakar bedenimden, İnzivaya çekerim kendimi başk...', ARRAY['Türk Edebiyatı','Şiir','Aytekin Orhan']::text[], 8.5, '{"poet":"Aytekin Orhan","poet_slug":"aytekin-orhan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yine-gel-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonu yok', 'sonu-yok-aytekin-orhan-zpa3t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Cevap olarak veremedik,

Kendimizde saklı olan sevgimizi...

Saplandıkça nağmeler yüreğimize,

Biz sadece dinlemekle yetindik

Sonunu getiremedik...

01/05/2005', 'Cevap olarak veremedik, Kendimizde saklı olan sevgimizi... Saplandıkça nağmeler yüreğimize, Biz sadece dinlemekle yetindik Sonunu getiremedi...', ARRAY['Türk Edebiyatı','Şiir','Aytekin Orhan']::text[], 8.5, '{"poet":"Aytekin Orhan","poet_slug":"aytekin-orhan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sonu-yok-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçamazsın', 'kacamazsin-aytekin-orhan-m5tjj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Unutulmuşluğun hikayesidir yalnızlık; 

Boşalan kadehlere mahkum. 

Gecenin o yalancı yüzü,

Ve bir yerlerden sesi duyulan o tanıdık melodi…

Kaçamazsın, ne kadar kaçmak istesen de 

Ve birden haykırırsın,

Sesin çınlar beyninin kıvrımlarında…

İnkar etsen de hatırlarsın.

Çünkü; 

Çıkmıyordu ki aklından,

Çıkmayan can gibi…

20/04/2005', 'Unutulmuşluğun hikayesidir yalnızlık;  Boşalan kadehlere mahkum.  Gecenin o yalancı yüzü, Ve bir yerlerden sesi duyulan o tanıdık melodi… Ka...', ARRAY['Türk Edebiyatı','Şiir','Aytekin Orhan']::text[], 8.5, '{"poet":"Aytekin Orhan","poet_slug":"aytekin-orhan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kacamazsin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Gece', 'o-gece-nurten-tarim-y1ru9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşkımızı tenimizde yaşadık

Yıldızlar üzerimizde ipek örtü oldu 

Terimizi beden kadehinde içtik

İçip içip sarhoş olduk o gece

Zaman durdu

Ne geçmiş nede gelecek

Sen ile ben vardık o gece

Suya kanıksamış gibi

Ay ışığında seviştik 

Sevda gülünü kokladık hissettik aşkımızı

Melekler eşliğinde şarkımızı söyledik

Hasretliğimiz ağladı o gece

Her gecenin bu gece olmasını diledik

Korkuları pişmanlıkları  keşkeleri

Susamışlığın fütursuzluğu içinde erittik 

Gönül bahçemizdeki çiçek kokuları sardı bedenimizi

Andımızı buselerle temizledik

İmzaladık o gece', 'Aşkımızı tenimizde yaşadık Yıldızlar üzerimizde ipek örtü oldu  Terimizi beden kadehinde içtik İçip içip sarhoş olduk o gece Zaman durdu Ne ...', ARRAY['Türk Edebiyatı','Şiir','Nurten Tarım']::text[], 8.5, '{"poet":"Nurten Tarım","poet_slug":"nurten-tarim","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/o-gece-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boş Kadeh', 'bos-kadeh-alper-kuruk-dtjma', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gittim aşkın meyhanesine 

Yâr idi orada barmen,

Geldi yanıma işveyle

Şarap istedim hemen

İçerde bir o vardı bir de ben.

Sundu dudaklarını kadeh yerine

Ne bitmez bir içkiymiş bu? 

İçtikçe kadeh kendi kendine doldu...

Bir yudumda sarhoş olmuştum

Sadece sarhoş olan değildi vücudum

Sarhoştu hem de kalbim ve ruhum...

Fasılasız bu kadehi diktikçe

Kızarıyordu gittikçe...

Dolu kadehler ayyaşa tesir edemezken

Daha ilk yudumda mest olmuştum ben.

Hangi keskin bir meyle dolu

Ki boş kadeh sihirlemişti ruhu...', 'Gittim aşkın meyhanesine  Yâr idi orada barmen, Geldi yanıma işveyle Şarap istedim hemen İçerde bir o vardı bir de ben. Sundu dudaklarını ka...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bos-kadeh-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye -2-', 'sevgiliye-2-alper-kuruk-x5iph', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşkınla tutuşup yansın bu garip gönlüm

Hep seni sevmekle son bulsun ömrüm.

Seni seven olmayacak bil ki benden başka

Gel seninle başlayalım her an yeni bir aşka.

Gün bambaşka doğar âşık gönüllerde

Aşk için can verir bülbül güllerde.

Sev güzelim içime sevgini boşalt

Sensiz geçen günlerim inan sayılmaz hayat.', 'Aşkınla tutuşup yansın bu garip gönlüm Hep seni sevmekle son bulsun ömrüm. Seni seven olmayacak bil ki benden başka Gel seninle başlayalım h...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sevgiliye-2-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şairim Ben', 'sairim-ben-sadik-kilicarslan-jv5w6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şairim ben şair,

Gözyaşı dökmeden ağlayabilirim,

Yürümeden dağlar aşabilirim.

En amansız sevdada bile,

Ya aslı benim yada kerem benim.

Şairim ben şair,

Canım alındı,ama ölmedim...', 'Şairim ben şair, Gözyaşı dökmeden ağlayabilirim, Yürümeden dağlar aşabilirim. En amansız sevdada bile, Ya aslı benim yada kerem benim. Şairi...', ARRAY['Türk Edebiyatı','Şiir','Sadık Kılıçarslan']::text[], 8.5, '{"poet":"Sadık Kılıçarslan","poet_slug":"sadik-kilicarslan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sairim-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çığlık', 'ciglik-sadik-kilicarslan-zydbj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Oy havar...

Yine çığlık...

Yine haykırışlar...

Ne zaman bi çocuk ağlasa 

Benim yüreğim kanar.

Millet uzaya çıkmiş umrumda mı

Bir çocuğun yarasına derman olamadıktan sonra.

Atomu parçalasanız umrumda mı

Bir çiçek veremedikten sonra,bu kanayan yarali yüreğe.

Ne zaman bi çocuk ağlasa

Aklıma gelir yıllar önce çekilmiş afkanistanlı kızın resmi,

Ve yıllar geçti...

Ne o kızın bakıslarını değiştirebildik nede dünyamızı

Ne zaman bi çocuk ağlasa

Aklıma gelir somalideki çocuklar

Açlıktan bitkin düşmüş cılız,çaresiz vücutlar

Ve sorarım kendime

Hic mi suçum yok bunda.

Kaderi mi bu açlık,kaderi mi bu yoksulluk

Ağlayan çocukların....', 'Oy havar... Yine çığlık... Yine haykırışlar... Ne zaman bi çocuk ağlasa  Benim yüreğim kanar. Millet uzaya çıkmiş umrumda mı Bir çocuğun yar...', ARRAY['Türk Edebiyatı','Şiir','Sadık Kılıçarslan']::text[], 8.5, '{"poet":"Sadık Kılıçarslan","poet_slug":"sadik-kilicarslan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ciglik-80-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur 2', 'yagmur-2-sadik-kilicarslan-gwl6o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nasılda yağıyor,

Deli gibi...

Buradayım diyor sanki

Herşeye rağmen buradayım...', 'Nasılda yağıyor, Deli gibi... Buradayım diyor sanki Herşeye rağmen buradayım......', ARRAY['Türk Edebiyatı','Şiir','Sadık Kılıçarslan']::text[], 8.5, '{"poet":"Sadık Kılıçarslan","poet_slug":"sadik-kilicarslan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yagmur-2-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giderim', 'giderim-vahit-aycil-lns3v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'giderim sevdiğim anları bırakıp

penceremi ve sayfalarımı anlamsız 

öylece gider susarım

sorarlarsa yutarım,sesimi söyleyemem

aynalara küser,yüzümü saklarım,adım adım gider kaybolurum

ben seni sevdiğim zaman yağmurlara büründü bu şehir

içimin nehirleri çorak şimdi 

sen ve umutlar,artık yok şimdi.

yanlızlığın garında, mahsum bakışlar yok artık

uçuyor siyah uçurtmalar düşler ülkesinde

yapraklar gibi düşüyor toprağa benliğim

ve ben giderim istememezliğinden

bırakırım avuçlarına bakışlarımı...

bırakırım rüzgara nefesimi

ve son nefesimi alıp giderim...', 'giderim sevdiğim anları bırakıp penceremi ve sayfalarımı anlamsız  öylece gider susarım sorarlarsa yutarım,sesimi söyleyemem aynalara küser,...', ARRAY['Türk Edebiyatı','Şiir','Vahit Ayçil']::text[], 8.5, '{"poet":"Vahit Ayçil","poet_slug":"vahit-aycil","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/giderim-51-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürek İster', 'yurek-i-ster-emre-yildirim-vf4wv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yürek ister sevdalar,

Buğulu bir camın altında,

Güneşli bir günün başlangıcında,

Daha yeni yeni vururken günün ilk ışıkları,

Pencerenizin altında uyanıp,

Güne onsuz başlamayı göze almak ister...

Bunu göze alabilirmisiniz? ...', 'Yürek ister sevdalar, Buğulu bir camın altında, Güneşli bir günün başlangıcında, Daha yeni yeni vururken günün ilk ışıkları, Pencerenizin al...', ARRAY['Türk Edebiyatı','Şiir','Emre Yıldırım']::text[], 8.5, '{"poet":"Emre Yıldırım","poet_slug":"emre-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yurek-ister-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'XXX Sevdalar Vardır', 'xxx-sevdalar-vardir-zeki-ergin-an2tr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'tutamazsın

taşan ırmağı

set çekemezsin

sel sel olur katar önüne geleni

çoşkukça çoşar yol boyu

sevdalar vardır

sevdalı insanlar

coşar çoştukça

dağları aşar

koşar koştukça

koşar

_erenköy 11aralık2004', 'tutamazsın taşan ırmağı set çekemezsin sel sel olur katar önüne geleni çoşkukça çoşar yol boyu sevdalar vardır sevdalı insanlar coşar çoştuk...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevdalar-vardir-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dileğim', 'dilegim-necat-necdet-demircan-ktbvi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tebessüm fısılda geceye

Kör karanlığa bak umuyla

Gülümse! 

İp atlasın yüreğin

Zifir sancılar biter elbet sabahleyin

Kapatma gözlerini

Sal rüzgâra hislerini

Dileğim:

Yağmur sonrası gün ışığı tadında gülümsesin gözlerin

Güneş hep yüreğine doğsun sonsuza değin…

"Zamanında biriktirdiğin tebessümlerin rengidir; hatıralar..."', 'Tebessüm fısılda geceye Kör karanlığa bak umuyla Gülümse!  İp atlasın yüreğin Zifir sancılar biter elbet sabahleyin Kapatma gözlerini Sal rü...', ARRAY['Türk Edebiyatı','Şiir','Necat Necdet Demircan']::text[], 8.5, '{"poet":"Necat Necdet Demircan","poet_slug":"necat-necdet-demircan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/dilegim-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göreve Çağrı', 'goreve-cagri-ramazan-ates-2a4ot', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gurbet çiçekleri bir bir soluyor,

Yüreklere ateş düştü yandın mı? 

Genç fidanlara bir bir soluyor,

Yüreklere ateş düştü yandın mı? 

Kimi yandı başkasının yüzünden,

Kimi öldü, sarhoiların hızından.

Kimi gitti hayırsızın kızından,

Yüreklere ateş düştü yandın mı? 

Kimi çocuk daha dört beş yaşında,

Kimi gençti ondört onbeş yaşında,

Kimi büyük aklı fikri başında,

Yüreklere ateş düştü yandın mı? 

Acı ama düşmeyince bilinmez,

İzi kalır ömür boyu silinmez.

Gurbetcinin niye yüzü hiç gülmez? 

Yüreklere ateş düştü yandın mı? 

Gurbet çiçekleri solmasın diye,

Artık ciğerimiz yanmasın diye,

Göreve çağırdım kendimi bile,

Yüreklere ateş düştü yandın mı? 

Tehlikeyi uzak tutsak güllerden,

Sahip çıksak soldurmasak erkenden,

Hep sevelim okşayalım yürekten,

Ne yanalım, ne yakalım gurbette,

Hep gülelim, sevinelim gurbette.

Ramazan Ateş/Enschede-8.12.2005', 'Gurbet çiçekleri bir bir soluyor, Yüreklere ateş düştü yandın mı?  Genç fidanlara bir bir soluyor, Yüreklere ateş düştü yandın mı?  Kimi yan...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/goreve-cagri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masal', 'masal-sadik-kilicarslan-k1gtz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Baba bana bir masal anlat

İçinde silahlar olmasın.

Baba bana bir masal anlat

İçinde kimse ölmesin.

Padişahın kızı hasta olmasın

Olmasın uzak diyarlarda canavarlar

Sevenler kavuşsun

Aşmak gerekmesin kaf dağlarını

Baba düştüm tökezledim bu yolda

Tut baba kaldır beni,

Baba canım  yanıyor...

Baba merak ettim neden taşlarlar meyve veren ağacı.

Baba şu gökyüzündeki güzel kuşa bak

Niye pat diye düştü.

Yoksa onlarda uçaklar gibi motoru bozulunca düşüyorlar mı.

Baba ev ne avcı ne? 

Baba av mı olmalıyım avcı mı? 

Baba canım yanıyor,

Neden  elde silahlar can almaya cıkar insanlar...

Baba niye sustun? 

Tamam baba masal anlatma.

Baba  bana hayallerini anlat

Nasıl bir dünya istediğini

Baba anlat...

Bana nasıl bir dünya bıraktığını...

Baba bana masalda olsa güzellikleri anlat..', 'Baba bana bir masal anlat İçinde silahlar olmasın. Baba bana bir masal anlat İçinde kimse ölmesin. Padişahın kızı hasta olmasın Olmasın uzak...', ARRAY['Türk Edebiyatı','Şiir','Sadık Kılıçarslan']::text[], 8.5, '{"poet":"Sadık Kılıçarslan","poet_slug":"sadik-kilicarslan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/masal-108-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saklambaç Oynuyoruz', 'saklambac-oynuyoruz-kadir-ozdemir-6aryt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'SAKLAMBAÇ OYUNU 

K.maraşın asil ve kültürlü atmosferinde başladı yaşamım. 

Asalet diyorum çünkü...

Unutuldu bu günlerde bu kelimenin anlamı. 

İlk orta lise derken geçip giden yıllar. 

Farkında olmadan yaşandı bir çok olaylar...... 

Hani derler ya... 

''o insanlar ki derya içredirler ama deryayı bilmezler.''

İşte tam bunun gibi geçti gençlik yılları. 

Komşu komşunun külüne muhtaçtı. 

Komşu kızını namus sayardık. 

Mahalleden geçerken başımız hep öndeydi. 

Ne kimsenin penceresine nede Karısına-kızına  bakardık. 

Eğer tanıdık biriyse gördüğümüz yüzümüzü hafif bir mahçubiyet kaplar:

Gülümseyerek ''merhaba''derdik. 

Eğer çok yakın bir tanıdıksa hal hatır sorar 

İki dakikalık bir hoşlamayla geçip giderdik. 

Sahi yazlar vardı bizde.... 

Konu komşu toplanıp yapılan bulgur kaynatmalar, 

Pestil, şıra ve kışlık ekmek hazırlıkları.... 

Kışlar vardı karlı soğuk kış günleri... 

Her sabah kar kürünen damlar 

Sonra karla dolan sokaklarda açılan yollar. 

Birlikte çıkılırdı sokağa, birlikte açılırdı yollar. 

Hep birlikte el birliğiyle. 

Böyle geçti yıllar. 

Örneğin hanımlar; her sabah evin önünü süpürmek onların göreviydi. 

Sabah duayla işine uğurlanınca eşler, 

Kısadan bir ev toparlanır 

Sokağa çıkılıp kapı önü sulanır ve süpürülürdü. 

Ne kadarda önemli bir şeymiş bu süpürme işe şimdi anladım. 

Bir komşu kapı önünü süpürmeye çıkmasa o gün işler biter bitmez onun ziyaretine gidilirdi 

Çünkü bilinirdi ki çok önemli bir derdi olmasa sabah mutlaka süpürürdü... 

Ödünç alıp vermeler ve komşu kavgalarıyla, küsüp barışmalarla geçen yıllar.. 

Derken üniversite okumak için çıkılan sıla... 

İşte deryadan çıkıp göle düşüldüğü an. 

Geçen zaman.... 

Görülen olaylar.... 

ve yaşam. 

Birbirini tanımayan yığınlar.... 

Birbirini yolda görse yön değiştiren kapı komşuları.... 

Kapıda karşılaşınca seni görmemek için dönülen sırtlar.... 

İki samimi insan buldun sayalım çok şanslısın. 

Ama bir ihtiyacın olsa Allah yardım etsin der ve kapısını kapar. 

Sokak süpürmek mi oda ne? 

Birlikte yapılan tek şey var oda ne biliyormusunuz. 

Saklambaç oyunu. 

Geriye ne mi kaldı? 

Kap kaç ve hırsızlık dolu bir mega köy. 

Olduk mega köylüler..... 

kadir_26_07_2005', 'SAKLAMBAÇ OYUNU  K.maraşın asil ve kültürlü atmosferinde başladı yaşamım.  Asalet diyorum çünkü... Unutuldu bu günlerde bu kelimenin anlamı....', ARRAY['Türk Edebiyatı','Şiir','Kadir Özdemir']::text[], 8.5, '{"poet":"Kadir Özdemir","poet_slug":"kadir-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/saklambac-oynuyoruz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül ve Yağmur', 'gul-ve-yagmur-ali-nafile-94bbv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gül ve yağmurdan benim                                               

Başıma gelen                                                         

Acımasız yağan                                                     

Zalim kokan                                                         

Ardından

Ve

Bir başıma koyup beni

Kahpe gecelerde

Uçup giden

Ben yanarım

Gece yanar

Ben kanarım

Gece kanar

Vurulurum sol yanımdan

Düşlerim kanar

Gül ve yağmurdan gelir

Ne gelirse

Önce salkım salkım 

Islatır yağmur

Sonra çağırır gül

Koşarım 

Sarhoş

Sanki ben bülbül

Gül ve yağmurdan

Geldi

Ne geldiyse başıma

Başka değil', 'Gül ve yağmurdan benim                                                Başıma gelen                                                          ...', ARRAY['Türk Edebiyatı','Şiir','Ali Nafile']::text[], 8.5, '{"poet":"Ali Nafile","poet_slug":"ali-nafile","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/gul-ve-yagmur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçış', 'kacis-sadik-kilicarslan-x9xmr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yolunu beklerken daha dün,

Kaçıyorum bugün senden gizlice...

Kalbime baktımda iyice,

Anladım ki sende herkes  gibisin...', 'Yolunu beklerken daha dün, Kaçıyorum bugün senden gizlice... Kalbime baktımda iyice, Anladım ki sende herkes  gibisin......', ARRAY['Türk Edebiyatı','Şiir','Sadık Kılıçarslan']::text[], 8.5, '{"poet":"Sadık Kılıçarslan","poet_slug":"sadik-kilicarslan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kacis-50-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zâlim', 'z-lim-timur-i-likan-u614s', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kendini dünyâda bâki sanırsın

Zâlim nefsine mi hemen kanarsın

Zulme ve pisliğe her an dalarsın

Dünyâya meyletme sakın yanarsın

Yetimi hor görüp iter kakarsın

Mâsumun canını neden yakarsın

Arkana bir sürü azgın takarsın

Dünyâya meyletme sakın yanarsın

Yaptığın yanına sanma kâr kalır

Bu dünyânın malı dünyâda kalır

Ahrette yanında amelin kalır

Dünyâya meyletme sakın yanarsın

İblisin yolunu tutup gidersin

Helâl, haram demez ne varsa yersin

İyiliği değil,  şerri seversin

Dünyâya meyletme sakın yanarsın

Timur İlikan der ki yapma, etme

Garibe, yetime sakın zulmetme

Gel Hakk yoluna gir, ateşe girme

Dünyâya meyletme sakın yanarsın

(11 Aralık 2005/ İstanbul)', 'Kendini dünyâda bâki sanırsın Zâlim nefsine mi hemen kanarsın Zulme ve pisliğe her an dalarsın Dünyâya meyletme sakın yanarsın Yetimi hor gö...', ARRAY['Türk Edebiyatı','Şiir','Timur İlikan']::text[], 8.5, '{"poet":"Timur İlikan","poet_slug":"timur-i-likan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/zalim-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir hayat', 'bir-hayat-kadir-ozdemir-j5401', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir yürek 

Bir sevgi 

Bir adam gerek... 

Bir yürekte bir sevgiye adam gerek....

Bir adam gibi yüreğe bir sevgi gerek...

Bir sevgiye adam gibi yürek gerek... 

Beklemek beklemek beklemek.... 

Bir gün var olabileceğini ümit etmek. 

Zor olan beklemek değil elbet. 

İki hayat 

Bir sevgi 

Bir yürek 

Evet bir yürek 

Bir yürek olmak 

Bir yürek kalabilmek gerek. 

İşte zor olan bu olsa gerek. 

Sevgiyle bağlanan bir çift yürek 

Birlikte atınca oluyor tek yürek 

İşte onu bağlayan şey sevilmek 

Evet sevmek değil sevilmek 

Sevilmek ve sürekli bunu hissetmeyi beklemek 

Unuttuğumuz bir ilahi kanun var. 

Her doğan birgün yaşlanacak yıpranacak 

İlk günkü duygulara takılıp kalan yürek 

Kabullenmekte zorlanıyor olsa gerek 

Zaman geçiyor yıpranıyor her yürek 

İblis mesaide üretiyor hezeyanlar 

Seni sevmedi sevmeyecek 

İşte hakikati bilmek demek 

İblise yenilmeden sevmek gerek 

Zaman geçiyor herşey değişiyor 

Değişmeyen şey sevgi olmalı elbet 

Şimdi sormak gerek. 

Sevmek mi yoksa sevilmek mi? 

İlk bakışta kolay bir soru 

Ama ya düşününce acaba hangisi doğru? 

Sorunun cevabı elbette sevilmek olmalı.... 

Kadir_01_06_2005', 'Bir yürek  Bir sevgi  Bir adam gerek...  Bir yürekte bir sevgiye adam gerek.... Bir adam gibi yüreğe bir sevgi gerek... Bir sevgiye adam gib...', ARRAY['Türk Edebiyatı','Şiir','Kadir Özdemir']::text[], 8.5, '{"poet":"Kadir Özdemir","poet_slug":"kadir-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/bir-hayat-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Orda kimse varmı acaba?', 'orda-kimse-varmi-acaba-kadir-ozdemir-fptmp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Orda kimse varmı acaba? 

İçinde çocuksu masum gülücükler olan 

Yaşamı seviç ve mutlulularla geçmiş. 

Üzülmüş vede üzmüş. 

Orda kimse varmı acaba? 

İnsanlar tanımış... 

Hayatı öğrenmiş...

Aldanmış... 

Aldatılmış...

Ama yılmamış... 

Orda kimse varmı acaba? 

Yaşadıklarından bir çok şey öğrenmiş 

Yıpranmış 

Yıkılmış 

Ama tükenmemiş. 

Orda kimse var mı acaba? 

Sorumluklarını bilen 

Yaşamı sorgulayan 

Yapacaklarını ve yapamayacaklarını bilen. 

Orda kimse var mı acaba? 

Kul olduğunu unutmadan 

İsyan etmeden herşeye 

''hoştur senden gelen'' diye bilen. 

Yok... yok... yok... 

Hep isyan ve yok yakarış. 

Oysa böyle olmamalıydı. 

İçinde kaynayan volkan ne enerjisi yüklüyor insana. 

Bir isyanın türküsünü mü? 

Ya kul olmak unutuldu mu? 

Ebedi hakikatler? 

Bir gönül değil bin gönül yansa bile sonuç aynı. 

Sabırla ve metanetle Allahtan yardım dile! 

Yanık bağırların dile getirdiği dua ile..... 

kadir_01_07_2005', 'Orda kimse varmı acaba?  İçinde çocuksu masum gülücükler olan  Yaşamı seviç ve mutlulularla geçmiş.  Üzülmüş vede üzmüş.  Orda kimse varmı a...', ARRAY['Türk Edebiyatı','Şiir','Kadir Özdemir']::text[], 8.5, '{"poet":"Kadir Özdemir","poet_slug":"kadir-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/orda-kimse-varmi-acaba-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baş Ağrısı', 'bas-agrisi-sadik-kilicarslan-rttfm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Herşey başağrısı

Sonu gelmez faturalar

Canını sıkan işe yaramaz insanlar

Yoldaki çukurlar

Herşey ama herşey başağrısı

Kaçarsın bir süre

Sonra yine düşersin ortasına başağrısının

Seversin başınağrır

Sakın sevme.

Unutmazsan başınağrır

Boşver hepsini unut

İstekler başağrısı yapar

Sakın isteme.

Tatile falan gitme,hasta olma

Başın ağrır sonra

Verem olursun valla

başın ağrırsa

Uyuma başın ağrır

Uyuyanların hali belli.

Saçmalama sakın

başını ağrıtırlar sonra.

Yazma ulan yazma sakın! 

Ömür boyu başın ağrır...', 'Herşey başağrısı Sonu gelmez faturalar Canını sıkan işe yaramaz insanlar Yoldaki çukurlar Herşey ama herşey başağrısı Kaçarsın bir süre Sonr...', ARRAY['Türk Edebiyatı','Şiir','Sadık Kılıçarslan']::text[], 8.5, '{"poet":"Sadık Kılıçarslan","poet_slug":"sadik-kilicarslan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bas-agrisi-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dua', 'dua-sadik-kilicarslan-ownbo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Allah bir ağız versin sana,

Yanlız beni konuş.

Allah bir göz versin sana,

yanlız beni gör.

Allah bir kulak versin sana,

Yanlız beni işit...', 'Allah bir ağız versin sana, Yanlız beni konuş. Allah bir göz versin sana, yanlız beni gör. Allah bir kulak versin sana, Yanlız beni işit......', ARRAY['Türk Edebiyatı','Şiir','Sadık Kılıçarslan']::text[], 8.5, '{"poet":"Sadık Kılıçarslan","poet_slug":"sadik-kilicarslan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/dua-136-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hz. SÜLEYMAN (AS)', 'hz-suleyman-as-abdullah-yasar-erdogan-62aic', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '(20. Büyük Peygamber) 

       Hz.  SÜLEYMAN  (AS) 

Hz. Davud’un oğlu, doğdu Kenan’da,

Yetişti büyük peygamber yanında.

İsrail’in üçüncü kralıdır o,

Pek kıymetlidir Allah’ın katında.

Rabbim O’na çok ihsanda bulundu,

Hem Peygamber, hem de hükümdar oldu.

Bütün hayvanat dilini öğretti,

O’nun yolu, Hakk için doğru yoldu.

Cin ve hayvanattan ordusu vardı,

Bu askerlerini bir gün topladı.

Karınca vadisinden geçerken,

O’nunla konuşan karınca vardı.

Karınca kavmine nida ederken,

Hz. Süleyman duydu ordan geçerken,

Şükretti Rabbine indi secdeye,

O kendinden geçerdi şükrederken.

Kur’an; Sa’d’da O’nu tarif ediyor,

Rabbim hastalıkla imtihan diyor.

Sabır ve tevekkül abidesi o,

Böylece sağlığına kavuşuyor.

Rüzgara da hükmeder Hz. Süleyman,

Cin ve Şeytanlara oldu komutan.

Onlar üzerinde tasarrufu var,

O gelmiştir Davud hanedanından.

Soylu ve asil atları var O’nun,

Her şey emrinde idi, büyük kulun.

Kuşlar haber verirdi diyarlardan,

Kayboluşu da meşhurdur Hudhud’un.

Hudhud der; “Sebe halkı putçu olmuş,

Puta taptığından Hakk unutulmuş.

O kraliçe Belkıs, nadan mal ile,

Bundan dolayı benim kayboluş.”

Hz. Süleyman mektup yazdı Belkıs’e,

Verdi emrini, Hudhud’a tavsiye,

Hudhud, mektubu Belkıs’a uzattı.

Belkıs mektubu okudu böylece.

Belkıs, Süleyman’a elçi gönderdi,

Elçide hediyeler yüklenmişti,

Hz. Süleyman kabul etmez bunları,

“Mal değil, gayem Hakk’a davet idi.”

İfrit adlı cin, bu işte görevde,

Belkıs tahtı, Hz. Süleyman önünde.

Davete gelip tahtı görmüş Belkıs,

Süleyman’a mülâyemet gönlünde. 

Belkıs âlemlerin Rabbine teslim,

Dedi: “Kendime ne yazık etmişim,

Süleyman elinde calib-i dikkat,

O Hakk peygamberine şahadetim.”,

Peygamberliği kırk yıl sürdü denir,

Adı pek çok efsanede geçmiştir.

O2nun yüzüğüne aklı selimler,

“Mührü Süleyman” adını vermiştir.

Kudüs’ü refah içinde yaşattı,

Kur’an’da, Enbiya O’nu anlattı.

Beytül Makdis’i inşa eden odur,

Devleti Mısır’dan Fırat’a vardı.

Arz-ı Mevud demiştir Yahudiler,

Orayı kendilerinin bilirler.

Bu yüzdendir kan ağlar Orta Asya,

Onlar fitne vermekte mahirdirler.

Hz. Süleyman adaletiyle meşhur,

Etrafında dolanır binlerce nur.

İbadethane için Cin’e emir,

Orda asasına dayanmış durur.

Hakk’tan ölüm hükmü Süleyman’a,

Tecelli, dayanırken asasına.

Ağaç kurdu asayı kemirir durur,

Hz. Süleyman kavuşur Mevlâsına.

Ruh bedeni terk edende çok zaman,

Heybetlice dikilir Hz. Süleyman.

Nur yaratıklar dahi bilmez gaybı,

Ruhsuz bedenle heybette Süleyman.

Museviler Süleyman mabedinde,

İbadet eder Tevrat ellerinde.

Süleyman’dan sonra bölündü onlar,

İsrail ve Yahuda ikilemde. 

Süleyman kıssasına bakıverdik,

O güzel kıssadan dersler edindik.

Dünya nimetleri azdırmaz bizi,

O Peygamberleri rehber bildik.

Hudhud: (Hüdhüd)  Çavuş kuşu, ibibik

Nadan: Haddini bilmez, cahil.

Mülâyemet: Yumuşaklık, uygunluk.

Beytül Makdis: Mescid-i Aksa

Şair: Abdullah Yaşar Erdoğan', '(20. Büyük Peygamber)         Hz.  SÜLEYMAN  (AS)  Hz. Davud’un oğlu, doğdu Kenan’da, Yetişti büyük peygamber yanında. İsrail’in üçüncü kral...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":87,"source_url":"https://www.antoloji.com/hz-suleyman-as-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle Olmak', 'seninle-olmak-sadik-kilicarslan-v2p4o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Üşürdüm bazen,

Gözlerinde Ağrı''nın en yücesinde

Akardım gözlerinden,

Adım Dicle olur, adım Fırat olur

Taş kesilirdim nemrutta

Gözlerinde gördüm,

Ürgüpte kayalara oyduğum evimizi

Mutluluğu gördüm umutla bakan gözlerinde

Ve yanında olmak istedim,

İyi gunde kötü günde...', 'Üşürdüm bazen, Gözlerinde Ağrı''nın en yücesinde Akardım gözlerinden, Adım Dicle olur, adım Fırat olur Taş kesilirdim nemrutta Gözlerinde gör...', ARRAY['Türk Edebiyatı','Şiir','Sadık Kılıçarslan']::text[], 8.5, '{"poet":"Sadık Kılıçarslan","poet_slug":"sadik-kilicarslan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/seninle-olmak-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Töre', 'tore-erkan-arslan-90w6u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Açıl sihirli kapı açıl gireceğim ben 

Akranı olmuşken içinde yaşanan ömrün

Gönlüme bir demet gül eski hayatlar veren

Visaline ermişim içinde koca ömrün

Ömrü yorgunluğunda görmeksizin düşünmek

Sarı öküz parasına kurmuşken hayatı

Sür karasabanı bin traktöre vakti çek

İki yavuklunun gönlünde yerimiz vardı…

Bir genç iki ömrün içini görmüşüz diyor

İki ihtiyar nine hayat çekiştirirken

Toprağın bağrına yaslanır sırtımızda kar

Artar yürek yangınlarım can çekiştirirken

                                           Aralık  1999', 'Açıl sihirli kapı açıl gireceğim ben  Akranı olmuşken içinde yaşanan ömrün Gönlüme bir demet gül eski hayatlar veren Visaline ermişim içinde...', ARRAY['Türk Edebiyatı','Şiir','Erkan Arslan']::text[], 8.5, '{"poet":"Erkan Arslan","poet_slug":"erkan-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/tore-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derbeder', 'derbeder-erkan-arslan-tw938', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sebepsiz bekleyiş,yararsız kelimeler,

Dökülseler,lekelenseler,kirlenseler,

Basiretini kaybetti zor düşünceler,

Uyudum,azaldı,kısaldı mesafeler.

Bir dost,sade hayat,hayali askerler,

Savaşta sessizler,sessizce ölmekteler.

Elimde kor,doğruyu sor,derin geceler! 

Ölünmez,tükenmez,hasret yüklü saatler.

Bir sedirde cansız,uzanmakta derbeder.

                                          Haziran 1996', 'Sebepsiz bekleyiş,yararsız kelimeler, Dökülseler,lekelenseler,kirlenseler, Basiretini kaybetti zor düşünceler, Uyudum,azaldı,kısaldı mesafel...', ARRAY['Türk Edebiyatı','Şiir','Erkan Arslan']::text[], 8.5, '{"poet":"Erkan Arslan","poet_slug":"erkan-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/derbeder-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neleri Öğrendim Senin Sayende', 'neleri-ogrendim-senin-sayende-munevver-senol-74f8c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hastalığın bana büyük bir ders oldu.

Neleri anladım senin sayende.

Böyle bir hataya düşmem bir daha.

Tecrübe kazandım senin sayende.

Kimselere haber vermemeyi öğrendim.

Günah keçisine döndüm sayende.

Güldüm kabahat oldu, ağladım kabahat

Benim adıma kararları bile 

Onlar verdi sayende

Hasalığın bana büyük bir ders oldu.

Neleri anladım senin sayende.

Böyle bir hataya düşmem bir daha.

Tecrübe kazandım senin sayende.

Çok şeyler öğrendim senin sayende.

Gerçek dostlarımı gördüm senin sayende.

                    

27.11.2002', 'Hastalığın bana büyük bir ders oldu. Neleri anladım senin sayende. Böyle bir hataya düşmem bir daha. Tecrübe kazandım senin sayende. Kimsele...', ARRAY['Türk Edebiyatı','Şiir','Münevver Şenol']::text[], 8.5, '{"poet":"Münevver Şenol","poet_slug":"munevver-senol","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/neleri-ogrendim-senin-sayende-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutma(Sizler Olmadan Asla...)', 'unutma-sizler-olmadan-asla-sadik-kilicarslan-1n5c1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Birgün yorulursan dostlarını aramaktan

Aşık olmaktan,sevmekten korkarsan

Ardına baktığında birşey göremiyorsan,

Bir çiçeği koparabiliyorsan acımasızca

Gözünü kırpmadan vurabiliyorsan bir kuşu

Unutabiliyorsan afrikadaki afganistandaki..,

Aç,susuz acı çeken çocukları,

Unutabiliyorsan gülmeyi ağlamayı

Göremiyorsan o küçük tohumdan çıkan mucizeyi

Feda edemiyorsan parayı inandığın şeyler için

Yoksa bir idealin iyi-kötü

Ne işin var bu başıbozuk dünyada

Düzeltmeyeceksen birşeyleri...', 'Birgün yorulursan dostlarını aramaktan Aşık olmaktan,sevmekten korkarsan Ardına baktığında birşey göremiyorsan, Bir çiçeği koparabiliyorsan ...', ARRAY['Türk Edebiyatı','Şiir','Sadık Kılıçarslan']::text[], 8.5, '{"poet":"Sadık Kılıçarslan","poet_slug":"sadik-kilicarslan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/unutma-sizler-olmadan-asla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir ben mi yüreğim?', 'bir-ben-mi-yuregim-lokman-ali-yavuz-3d3z9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir ben mi ıslandım yağmurda yüreğim? 

Kaleler ıslanmadı mı? 

Bir benim mi yaşlarım oldu? 

Ya gök, gök delinmedi mi sağnaklarda? 

Bir benim mi başıma kar yağdı? 

Kurtların başına  yağmadı mı? 

Bir ben mi sallandım depremde yüreğim? 

Kuleler sallanmadı mı zelzelede? 

Bir ben mi  yaşayamadım sevda ayazında? 

Kaç kişi sağ çıktı, zemheri soğuğundan? 

Bir ben mi dalgaya yakalandım sanki? 

Devasa gemiler yakalanmadı mı? 

Bir benim mi  dallarım düştü arada? 

Devrilen çınarları görmedin mi? 

Bir  benim mi yollarım kapandı? 

Tipide kalanları duymadın mı? 

Of ffffffffffff  yüreğim of. Biliyorsun 

Hepsi  O’nun  hasretindendir.', 'Bir ben mi ıslandım yağmurda yüreğim?  Kaleler ıslanmadı mı?  Bir benim mi yaşlarım oldu?  Ya gök, gök delinmedi mi sağnaklarda?  Bir benim ...', ARRAY['Türk Edebiyatı','Şiir','Lokman Ali Yavuz']::text[], 8.5, '{"poet":"Lokman Ali Yavuz","poet_slug":"lokman-ali-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bir-ben-mi-yuregim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-sadik-kilicarslan-stxtj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Açtığım kapıların hepsi sana çıkıyor

Nereye gitsem hep sen

Kokun heryere sinmiş

kaçamıyorumda,

senden, kendimden, bizden..

Uğraştırma beni

Yetmedi mi çektirdiklerin 

Herşeyimi aldın beni bile

Kusura bakma artık

''''bende sana yetecek kadar ben kalmadı''''', 'Açtığım kapıların hepsi sana çıkıyor Nereye gitsem hep sen Kokun heryere sinmiş kaçamıyorumda, senden, kendimden, bizden.. Uğraştırma beni Y...', ARRAY['Türk Edebiyatı','Şiir','Sadık Kılıçarslan']::text[], 8.5, '{"poet":"Sadık Kılıçarslan","poet_slug":"sadik-kilicarslan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sen-704-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benden Bana Beddua', 'benden-bana-beddua-ramazan-ates-8te3p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir damla yaş kalsa gözümde,

Onun için akarsa gözüm kör olsun.

Görsem ki ateşe düşmek üzere,

Uzanıp tutarsam kolum kırılsın.

Çok şeyler söyledim beni duymadı,

Duyduda aslında önem vermedi,

Şimdi geçmiş karşıma affet diyor,

Onu affedersem dilim tutulsun.

Gaddarsın diyorlar, halden bilmezsin,

Haldende bilirim, gaddar da değilim.

İnsansa herkese değer veririm,

Bir ona gülersem, kalbim taş olsun.

Yaşamak herkesin hakkıdır tamam,

Yaratılanı severim, hiçte kıyamam,

Mutlu olmak yaşamak isterim ama,

Onunla olursam bu canım çıksın.

Ramazan Ateş/Enschede-5.12.2005', 'Bir damla yaş kalsa gözümde, Onun için akarsa gözüm kör olsun. Görsem ki ateşe düşmek üzere, Uzanıp tutarsam kolum kırılsın. Çok şeyler söyl...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/benden-bana-beddua-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Panorama adam desem yeri var', 'panorama-adam-desem-yeri-var-mikdat-bal-0x21i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne ararsan onda vardır hayır, şer

Panorama adam desem yeri var

Hoş görünür ama kasılıp şişer

Bu da benim hatam desem yeri var

Cama benzer elmas gibi görülür

Bilemezsin niçin, nasıl kırılır

Bir şey dersin nefret eder, darılır

Esirgesin Hüdam desem yeri var

Yanlış arar sangi kendi gaf etmez

Över isen güler, acı laf etmez

Bir hatanı bulsa asla affetmez

Bir celsede idam desem yeri var

Neden bu böyledir soramazsın sen

Aleyhine bir şey yoramazsın sen

Yanlış gösterince yaramazsın sen

Hoş gelmiyor sedam desem yeri var

Bal der elif gibi olsun er ise

Ne edeyim düşüncesi şer ise

Biri kalkıp ona hocam der ise

Geçti benim modam desem yeri var', 'Ne ararsan onda vardır hayır, şer Panorama adam desem yeri var Hoş görünür ama kasılıp şişer Bu da benim hatam desem yeri var Cama benzer el...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/panorama-adam-desem-yeri-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nehrin İçinde', 'nehrin-i-cinde-yilmaz-donmez-0i2n2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözbebeğinin akından çıkan nehrin ortası, 

Çağlar hiç iz bırakmadan, akar gürül gürül. 

Sonsuzluktan kaynar nehir, azgın akan dalgası, 

Dar eder içimi sanki pır.. pır...', 'Gözbebeğinin akından çıkan nehrin ortası,  Çağlar hiç iz bırakmadan, akar gürül gürül.  Sonsuzluktan kaynar nehir, azgın akan dalgası,  Dar ...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Dönmez']::text[], 8.5, '{"poet":"Yılmaz Dönmez","poet_slug":"yilmaz-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/nehrin-icinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya', 'ruya-sadik-kilicarslan-q8pv9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Adın vardı gülümseyen dudaklarımda

Birde resmin, başucumda

Hayalin vardı gözlerimin önünde

Ben sana bakıyordum sen bana

Gözlerin ağlamaklıydı

Birşeye üzülmüş gibiydin

Ellerini uzatıp gel diyordun

Ellerimi uzatıyorum ellerim boşlukta

Ve seni arıyordum,

Rüyalarımda...', 'Adın vardı gülümseyen dudaklarımda Birde resmin, başucumda Hayalin vardı gözlerimin önünde Ben sana bakıyordum sen bana Gözlerin ağlamaklıyd...', ARRAY['Türk Edebiyatı','Şiir','Sadık Kılıçarslan']::text[], 8.5, '{"poet":"Sadık Kılıçarslan","poet_slug":"sadik-kilicarslan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ruya-220-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırlarda Bahar', 'kirlarda-bahar-altay-taskin-k8cxw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kış bitti bahar geldi

Güneş ışıklarını gönderdi

Toprak da çok sevindi

Açtı papatyalar eteklerini

                            Çiçeklerle elele

                            Oynayın birlikte

Şarkı söylüyor kuşlar

Kelebekler konacak yer arar

Koşun koşun çocuklar

Kırlarda size de yer var

                             Kuşlarla dil dile

                             Şarkı söyleyin birlikte', 'Kış bitti bahar geldi Güneş ışıklarını gönderdi Toprak da çok sevindi Açtı papatyalar eteklerini                             Çiçeklerle elel...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kirlarda-bahar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ter ve Tuz', 'ter-ve-tuz-necmettin-sari-zy011', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir yere,

bir yürek tüm ağırlığıyla çöktü mü

kanayan bir yüz kırmızı bir karanfile dönüşür 

bir özlemi,

bir kundakta uzun uzadıya beslemeye dönüşür umut

yarını birkaç bin hasret için

yeniden sağma sızısı başlar

ve o gece doğan o çocuk ihtiyaç

yarın hayatta ilk gününü geçirir,

titreyen bir kaygıyı koynuna alıp 

yakın bir sömürüye yerleşir.

Bir cep aynası,bir tabaka, 

ve bir muhtar çakmağı

önce gösterişli bugün titreyen bir ömre dönüşür

bir de üç cepli bir yelek olsa hani, ayakta durulacaktır.

Buğday tarlasına açılan

çamurdan bir kanal gibidir ellerindeki hatlar

ve Beulah düşlerindeki ülkedir ancak

serin bir yaylada gümüş bir ay gülümser

bir kirpi o an, bir tırpan vuruşuyla canını bırakır gider.

Ter tuzludur,

hayat da öyle bugün

dilini kaşıyan arsız susuzluk 

gırtlağına bir taş gibi iniyor

damarlarını geren güneş Keşişboğan’da yüzüyor

Kumocağı’nda askerlik anıları,

arpada sarışın fukaralık, 

gövdesinde her ezilen günden arta kalanlar,

hepsi tuzdan hayatlar,

hepsi terleyerek terk eder hayatını.

Kehribar tespih hacdan gelmiştir

yarın buğdayın

kaç teneke geldiğini söyleyecek taşlar

midesine saplanan bu hesapsız korkuyu,

saya çarpa vurgulamaya bir de.

tespih hediye edilmiş

ve değişmiştir

oysa ömrü hep aynıdır

ve tırnakla söke söke alınmıştır

hediye hayatlardan farklı darbeler taşır ömrü

ve keskin bir tırpanın,

taştan bir duvarın önünde hep eğilmiştir

bir çatan samanın orta yerinde

soluk sarı rengi benimsemiştir.

Necmettin SARI

  (28.11.2000)', 'Bir yere, bir yürek tüm ağırlığıyla çöktü mü kanayan bir yüz kırmızı bir karanfile dönüşür  bir özlemi, bir kundakta uzun uzadıya beslemeye ...', ARRAY['Türk Edebiyatı','Şiir','Necmettin Sarı']::text[], 8.5, '{"poet":"Necmettin Sarı","poet_slug":"necmettin-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/ter-ve-tuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzanmak Aydınlığa', 'uzanmak-aydinliga-altay-taskin-pkkyl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'karanlık tünelimizde ilerlerken

duyguların görünmediği

kırık hayaller serpilmiş belki

ıslatmayan yağmur denilen

ellerimizi uzatmışız nokta aydınlığa

erişemiyoruz ama

uzak çok uzak

gerçeklerin aydınlığına

bir an önce ulaşmak...', 'karanlık tünelimizde ilerlerken duyguların görünmediği kırık hayaller serpilmiş belki ıslatmayan yağmur denilen ellerimizi uzatmışız nokta a...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/uzanmak-aydinliga-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alimim', 'alimim-altay-taskin-rfovn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dünya alimlerine saygıyla

o yanan ampuller

            dönen tekerlekler

                      uzaklardan gelen sesler

                      daha daha neler

                      ben alim değilim hepsini bilemem

Alimim beyninde dolaşabilsem

izin verir misin bir saniye de olsa

inişli çıkışlı damarlarının üstünde

kanatlanıp uçarım dünyanın çevresinde

sevincimden ölsem bile yine de gam yemem...', 'Dünya alimlerine saygıyla o yanan ampuller             dönen tekerlekler                       uzaklardan gelen sesler                      ...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/alimim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabahın Seheri', 'sabahin-seheri-altay-taskin-38wp5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kıskanma ey gönül sabahın seherinde öten bülbüller

Onlar sevinç deryasına düşmüşler şarkı söylerler

Birinde saz birinde kadeh hepsinde dans işleri cümbüş

Sen ne oldun kara bulutlara bürünüp sarmaş dolaş gezer

Bırak elini onlardan onlar seni de şenliğe davet ederler', 'Kıskanma ey gönül sabahın seherinde öten bülbüller Onlar sevinç deryasına düşmüşler şarkı söylerler Birinde saz birinde kadeh hepsinde dans ...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sabahin-seheri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Susun', 'susun-atila-gunal-4snay', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sadece bir dakika

Lütfen

Her şeyi durdurun

Dünya da dursun

Lütfen

Sadece bir dakika

Kırmızı ışığın

Sarı ışığa döndüğü an

Hep beraber homurdanan otomobiller,

İkizlere takke satan pazarcı amca

Bir dakika durun ne olur

Susun bir dakika

Okullarda ziller çalmasın mesela

Çığlık çığlığa derse koşan çocuklar

Durun bir dakika

Rayların üzerinde 

Yeri göğü inleterek umut taşıyan tren

Denizi yırtarcasına ıslık çalan vapur

Bir dakikacık susun

Sesiniz camlarımızı titretiyor hızınızdan

Siz de susun ne olur savaşan uçaklar

Bir dakika sadece

Bombalar atmayın kimselere

Ağlamasın anneler parçalanan çocuklarına

Lütfen susun

Maviliğinle içimizi okşarken

Fırtınalarınla ocakları söndüren deniz

Bir dakika dur ne olur

Ben bugün

Bir can

Bir umut

Bir yaşam geldi dünyaya diyeceğim

İlk doğanın ağlamasını

Herkesin duymasını istiyorum…

Lütfen bir dakika susun

Dinleyin bir dakika

Bu ses,bu ağlama sesi

Yaşama merhaba sesidir

Susun ve dinleyin ne olur

Bir tek onun sesi duyulsun semalarda

İçimize sevgi

İçimize barış

İçimize dünya getirsin

HOŞGELDİN BEBEK…', 'Sadece bir dakika Lütfen Her şeyi durdurun Dünya da dursun Lütfen Sadece bir dakika Kırmızı ışığın Sarı ışığa döndüğü an Hep beraber homurda...', ARRAY['Türk Edebiyatı','Şiir','Atila Günal']::text[], 8.5, '{"poet":"Atila Günal","poet_slug":"atila-gunal","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/susun-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyan', 'uyan-altay-taskin-up2up', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uyan bu gece uyuma düşüm

İstemediğim düşler görmüşüm

Bir iple çekeceğim sabahı

Uçmayan balon gibi sönmüşüm

Ne istersin o karanlıklardan

Avucunu açıp yalancıktan

Gözler görmez gerçeği kapalı

Çek şansını şu şans torbasından', 'Uyan bu gece uyuma düşüm İstemediğim düşler görmüşüm Bir iple çekeceğim sabahı Uçmayan balon gibi sönmüşüm Ne istersin o karanlıklardan Avuc...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/uyan-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Martılar', 'martilar-mehmet-ali-cetin-x9c70', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çığlık çığlığa 

Beyaz kanatlı martılar süzülür

Altında ve üstünde mavinin 

Rüzgara tutunur özgürlük 

O ada senin bu ada benim

Bir şehir vapurunun en arkasında 

Ekmek simit ne bulursa

Yolcudur boğaz tokluğuna', 'Çığlık çığlığa  Beyaz kanatlı martılar süzülür Altında ve üstünde mavinin  Rüzgara tutunur özgürlük  O ada senin bu ada benim Bir şehir vapu...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Çetin']::text[], 8.5, '{"poet":"Mehmet Ali Çetin","poet_slug":"mehmet-ali-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/martilar-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazdım', 'yazdim-firat-ulker-x6dif', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Geceleri yazmak gelir içimden

Oturur,yazarım düşünmeden

Tek yaptığım yazmaktı

Bir şairin kaleminden

Geceleri geceler gelir aklıma

Ağlayan şair mısraları

Ve karanlık bir de

Gelmiş,geçmiş,gelecek..

Umutsuzluk çökünce içime

Resmini çizer kalemim

Hayatı en karanlık yerinden

Ben siyahlarımı anlatırım

Beyazlarımı yaşarım

Düşünmeden,tartmadan

Gözünüzdeki yaşa aldırmadan

Yazarım..

Güzel olacak mı diye düşünmem

Bir okurun gözünden

Ben sadece yazarım..

Sizler okurken 

Belki de anlamıyorsunuz kalemimden

Belki de onun en ince yerinden

Sizler okurken

Ben çoktan gitmişim

Çoktan gömülmüşüm

Başka yazılara,başka başka yolculara

Hayat aktıkça dilimden

Yolcular yaraladıkça derinden

Zaman durdu ya gözlerinden

Ben hala yazıyorum..

Sizler yine anlamayın beni

Anlamaya çalışmayın sözlerimi

Deli saçması deyin 

Güldükçe içinizden

Ben yazıyorum yine

Siyahın en karasını

Zifirinin en gecesini

Siz güldükçe ben

Hep yazacağım gecemden

Siz ağladıkça ben

Bakacağım pencereden

Ve bir gün

Arap kızını öldüren

Beyaz bir çığ düşecek,şehrin tepesinden

Hiç tatmadığım,görmediğim

Mutluluklar kusarım kağıda

Peteğinde bal olur

Tatlanırım okudukça

Ama hiç yaşamadım

Hep yazdım.,

Yazdıkça okudum,

Okudukça ağladım,

Ağladıkça yazdım,

Yazdıkça okudum,

Okudukça ağladım..

Bu kısır döngü hiç bitmedi

Senden sonra bile

Zincirin hiç bir halkası kopmadı

Değişen tek bişey var

Gözyaşlarım

Acıdan değil,mutluluktan

Ölüm geldi dediler

Kağıt bitti dediler

Kalem,uç kalmadı

Kimse yazamayacak dediler

Son kalem benim elimde

Son cümle onun ucunda

Yazacağım çok şey vardı

Sana yazacağım çok şey

Ama o altından değerli

Son çizgilerle yazıyorum,

Son cümlemi

Ben

Seni

Çok

Seviyorum..', 'Geceleri yazmak gelir içimden Oturur,yazarım düşünmeden Tek yaptığım yazmaktı Bir şairin kaleminden Geceleri geceler gelir aklıma Ağlayan şa...', ARRAY['Türk Edebiyatı','Şiir','Fırat Ülker']::text[], 8.5, '{"poet":"Fırat Ülker","poet_slug":"firat-ulker","theme":"Türk Şiiri","is_hero":false,"total_lines":76,"source_url":"https://www.antoloji.com/yazdim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyümek', 'buyumek-sadik-kilicarslan-inh88', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayat bazen çok garip geliyor bana

Erken büyüdüğümü düşünüyorum

Hala çocukca şeyler yapmak istiyorum

Şekerim elimden alındı diye ağlamak mesela 

Suya kıyafetlerim ile girmek

Yemiş ağacının en tepesindeki en olgunlaşmiş yemişi,

Almak istiyorum düşmek pahasına.

Küçük kıskançlıklardan kavga etmek 

Sonrada hicbirşey olmamış gibi

Kaldığım yerden devam etmek istiyorum

Erken büyüdüğümü düşünüyorum 

Çünkü hala çamurlu boş arsada top oynamak istiyorum 

Ve azar işitmek kirlenmiş üstüm için

Evet erken büyüdüm

Şirinlik yapmak istiyorum etrafıma

Gülsün, gülümsesin istiyorum beni görenler

Hüzün dersen fazlasıyla yaşadım kimse yaşamasın

Sonra erken büyüdüğümü farkettim

Ve büyüdüğüm için  yapamadıklarımı...', 'Hayat bazen çok garip geliyor bana Erken büyüdüğümü düşünüyorum Hala çocukca şeyler yapmak istiyorum Şekerim elimden alındı diye ağlamak mes...', ARRAY['Türk Edebiyatı','Şiir','Sadık Kılıçarslan']::text[], 8.5, '{"poet":"Sadık Kılıçarslan","poet_slug":"sadik-kilicarslan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/buyumek-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nereden Nereye', 'nereden-nereye-altay-taskin-qy9kf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yunus gibi biçareyim

Ellerde divane

Yalnız kalırsam

Dünyada neyleyim

Görününce gözdeyim

Seslenince dilde

Çıkıp dolaşırsam

Nerede dinleneyim

Uzak dosta uğrayım

Azıcık halini sorayım

Hasta olursam

Derman nerede bulayım

Hep haktan yanayım

Ki hak arayım

Hak''tan ayrılırsam

Kıvılcımla yanayım', 'Yunus gibi biçareyim Ellerde divane Yalnız kalırsam Dünyada neyleyim Görününce gözdeyim Seslenince dilde Çıkıp dolaşırsam Nerede dinleneyim ...', ARRAY['Türk Edebiyatı','Şiir','Altay Taşkın']::text[], 8.5, '{"poet":"Altay Taşkın","poet_slug":"altay-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/nereden-nereye-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oruç', 'oruc-firat-ulker-4jyi3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Senden sonra

Sevda ramazanlarında

Oruç tuttum aşk adına

Sensizliğin ilk imsağında başladım

Ve iftarlar hiç gelmeyecek

Bu oruç asla bozulmayacak

Ta ki zemzem dudaklarından

Bir damla içene kadar..', 'Senden sonra Sevda ramazanlarında Oruç tuttum aşk adına Sensizliğin ilk imsağında başladım Ve iftarlar hiç gelmeyecek Bu oruç asla bozulmaya...', ARRAY['Türk Edebiyatı','Şiir','Fırat Ülker']::text[], 8.5, '{"poet":"Fırat Ülker","poet_slug":"firat-ulker","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/oruc-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nedir Çaresi', 'nedir-caresi-sadik-kilicarslan-mqde3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nedir çaresi

Hiç olmadık bir anda hissedilen yanlızlığın

Nedir durduk yere akan bu gözyaşlarının çaresi

Nedir bu arayış herşeyim var dediğin anda başlayan

Nedir bu yeri doldurulamayan boşluk

Bir sevgi,bir hasret,bir umut...', 'Nedir çaresi Hiç olmadık bir anda hissedilen yanlızlığın Nedir durduk yere akan bu gözyaşlarının çaresi Nedir bu arayış herşeyim var dediğin...', ARRAY['Türk Edebiyatı','Şiir','Sadık Kılıçarslan']::text[], 8.5, '{"poet":"Sadık Kılıçarslan","poet_slug":"sadik-kilicarslan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/nedir-caresi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siyahın Tayfı', 'siyahin-tayfi-firat-ulker-yi98x', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu günlerde

Bir isyandır tuttu beni

Sabotaj diyorlar adıma

Asi olmuşum

William Tell''in yayında

Robin Hood''un okunda

Kardelen olmuşum buz dağlarının eteğinde

Gece olmuşum gündüzün eşiğinde

Ben bu günlerde böyleyim işte

Onca konuşmaların,bağrışların içinde

Sessizce şiir yazıyorum

Bunalımım bu günlerde

Hırçın ve de yırtıcı

Resimden nefret ediyorum

Oysa,oysa alışmıştım bu maskeli baloya

Şimdi onları da boyuyorlar

Sahteliğin gizemi

Bikaç kremde,rimelde,rujda

Herkes bi oyundur tutturmuş gidiyor

Gizlenip,kaçıyorlar

Ve ben gönüllü ebeyim yine

Şu lanet saklambaç hengamesinde

Ama oyuna bi son vereceğim

Birinizi yakalayıp sobelediğimde

Diğerleri mi

Ne gerek var

Yakaladım ya bir tane

Hey insanlar 

Hadi gelin

Yeni bir oyun biliyorum

Onu oynayalım

Adı mı

Birbirinizi karşılıksız sevmece

Hadi ben başlıyorum

Arkamdan gelin

Hey ne var,ne oldu

Sıkıldınız mı

Ne zaman mı bitecek

Bunun bir oyun olduğunu unuttuğunuzda

Ama siz alışmışsınız oynamaya

Peki koşun,gidin

Saklanın paskalya kabuklarınıza

Bir gün beni anlayacaksınız ama,

Ama..,

Çukura bir adım kaldığında

Şimdi hepinize iyi geceler

Elinizde tek bir renk var artık

Siyah..,

Boyayın dünyayı boydan boya..

                                                              25.08.05/00-43', 'Bu günlerde Bir isyandır tuttu beni Sabotaj diyorlar adıma Asi olmuşum William Tell''in yayında Robin Hood''un okunda Kardelen olmuşum buz dağ...', ARRAY['Türk Edebiyatı','Şiir','Fırat Ülker']::text[], 8.5, '{"poet":"Fırat Ülker","poet_slug":"firat-ulker","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/siyahin-tayfi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günün Yorgunluğu', 'gunun-yorgunlugu-nurten-tarim-dzmvm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Günün yorgunluğunu attım geceye

Senin yokluğunda

Anlattım yıldızlara

İstedim seni göndersin 

Seni görmek için baktım her yana

Yapraklarda şebnemler adını yazmış 

Ilık meltem esintisinde şarkımızı dinledim

Hasretin bulutlandı

Yağmurun damlalarında sen

Yaşamak için seninle ıslandım', 'Günün yorgunluğunu attım geceye Senin yokluğunda Anlattım yıldızlara İstedim seni göndersin  Seni görmek için baktım her yana Yapraklarda şe...', ARRAY['Türk Edebiyatı','Şiir','Nurten Tarım']::text[], 8.5, '{"poet":"Nurten Tarım","poet_slug":"nurten-tarim","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gunun-yorgunlugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suç bendemi?', 'suc-bendemi-aytekin-orhan-vdm28', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güzelliğini içti sayfalar

Yudum yudum 

Kokladı tenini sindire sindire

Çoğaldı, çığ gibi zerafetin.

Sığmadı.

Süzüldü  nehirlere...

19/11/2005', 'Güzelliğini içti sayfalar Yudum yudum  Kokladı tenini sindire sindire Çoğaldı, çığ gibi zerafetin. Sığmadı. Süzüldü  nehirlere... 19/11/2005...', ARRAY['Türk Edebiyatı','Şiir','Aytekin Orhan']::text[], 8.5, '{"poet":"Aytekin Orhan","poet_slug":"aytekin-orhan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/suc-bendemi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üstü kalsın', 'ustu-kalsin-aytekin-orhan-ptodj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'toz tutmuş çekmecelerde mahkum

bedelini ödediğim aşkın.

bir daha anılmayacak,

güzelliğinin tüketildiği masalarda...

sen kadehlerde olacaksın,

rakı, peynir, kavun

boğulacaksın...

hesabın ödendi.

üstü kalsın.

15/11/2005', 'toz tutmuş çekmecelerde mahkum bedelini ödediğim aşkın. bir daha anılmayacak, güzelliğinin tüketildiği masalarda... sen kadehlerde olacaksın...', ARRAY['Türk Edebiyatı','Şiir','Aytekin Orhan']::text[], 8.5, '{"poet":"Aytekin Orhan","poet_slug":"aytekin-orhan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ustu-kalsin-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Coşkusu', 'ask-coskusu-alper-kuruk-tt9y6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gönlüm unutmaz seni

Hatırlar o bûseni,

Gün geçse,yol uzasa

Beklerim hep gelmeni.

Aşkınla yanmaktayım

Seni ben anmaktayım,

Beni sevmesen bile

Seviyor sanmaktayım.

Güzelim sevişelim

Neş''eye erişelim,

Saadetimiz için

Bir ahde girişelim.', 'Gönlüm unutmaz seni Hatırlar o bûseni, Gün geçse,yol uzasa Beklerim hep gelmeni. Aşkınla yanmaktayım Seni ben anmaktayım, Beni sevmesen bile...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ask-coskusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz Şaririz', 'biz-saririz-yurdagul-ozay-kvy14', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Güllerin bagina mestiz ezelden

Biz ask kadehini tadanlardaniz

Feyz alir kalemler her bir güzelden

Ariyiz bala bal katanlardaniz

Öyle bir sevdaya müptelayiz ki

Gönül meyhanemiz kalemdir saki

Öyle bir hayale sevdaliyiz ki

Içmeden de sarhos olanlardaniz

Gönül hitabinin ustasiyiz biz

Sevda kitabinin mahlasiyiz biz

Hos sohbetle dostun hastasiyiz biz

Gönülden gönüle akanlardaniz

gönlümüzde yol var ince seçilmez

Güzele rehberiz öte geçilmez

sairlik badedir asksiz içilmez

Sevk ile doldurup sunanlardaniz

Sirra sir oluruz sirri bilince

Gönül murat alir siir dilince

Biz bizi taniriz dostu görünce

Güllerle açilan gülistandaniz

Biliriz dert ile gamin darini

Buluruz o derdin ask esrarini

Dünyanin zevkini bütün varini

Bir dize siirde alanlardaniz', 'Güllerin bagina mestiz ezelden Biz ask kadehini tadanlardaniz Feyz alir kalemler her bir güzelden Ariyiz bala bal katanlardaniz Öyle bir sev...', ARRAY['Türk Edebiyatı','Şiir','Yurdagül Özay']::text[], 8.5, '{"poet":"Yurdagül Özay","poet_slug":"yurdagul-ozay","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/biz-saririz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cumhuriyet Bayramı', 'cumhuriyet-bayrami-alper-kuruk-4v49u', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben Cumhuriyetin çocuğu

Cumhuriyet ne güzelmiş...

Atatürk''le büyüklerimiz elele vermiş

Ekimin 29 unda 1923 ün

Dünyaya duyurulmuş Cumhuriyet olduğu

Devletimizin ve ülkümüzün.

Kutlu olsun bayramı bütünümüzün...', 'Ben Cumhuriyetin çocuğu Cumhuriyet ne güzelmiş... Atatürk''le büyüklerimiz elele vermiş Ekimin 29 unda 1923 ün Dünyaya duyurulmuş Cumhuriyet ...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/cumhuriyet-bayrami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Farkındalık', 'farkindalik-firat-ulker-jauhq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bazen kelimeler yetmez

Bazen resim,müzik,şiir

Bazen hiçbir şey yetmez

Anlatamazsın,nutkun tutulur

Boğazın düğüm düğüm olur

Beynin durur,bedenin donar,kalbin susar

İşte o an

Ruhunu kaybetmiş bir cesetsindir

Ölüden tek farkın

Cansızlığının farkındalığıdır

Bu farkında oluşluluk

Seni farkında olmayışa sürükler

Dirhem dirhem azalırsın

Bir mum gibi erir yok olursun

Uçurumlara yaklaşırsın

Karanlık,uzun yollarda sürüklenirken

Sonra gözlerin bir ışık arar,bir umut

İrtifa kaybeden bi uçağın havada kalmaya çalışması gibi

Kanının son damlasıyla

Son gücünle,son uzanışınla

Dibine girdiğin yerin,puslu karanlıklarını yırtarak

Bir yıldız koparmaya çalışırsın gökyüzünden

Farkında olmadan bazenleri ararsın

Bulduğunda önce rahatlarsın

Sonra pişmanlık sarar her yanını

Gözbebeklerine gelen uyartıları

Sorumsuzca,düşüncesizce görüşlerine kızarsın

Seni bu karanlık,derin çukurlara iten kuvvetin 

Ne olduğunu anlamaya çalışmadığına yanarsın

Önce pişmanlık yaşları akar gözlerinden

Sonra mutluluktan ağlarsın

Her anın farkında olunması gerektiğini anlarsın

Tekrar ağlarsın

Gözyaşlarınla oluşturduğun denizde

Yaşamayı dilediğin mutlu anlara yelken açarsın

Ta ki..,

Demir attığın anın farkında olmayışına kadar..

                                                                                   03.09.03/02-14', 'Bazen kelimeler yetmez Bazen resim,müzik,şiir Bazen hiçbir şey yetmez Anlatamazsın,nutkun tutulur Boğazın düğüm düğüm olur Beynin durur,bede...', ARRAY['Türk Edebiyatı','Şiir','Fırat Ülker']::text[], 8.5, '{"poet":"Fırat Ülker","poet_slug":"firat-ulker","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/farkindalik-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol Ver Gönlüm Vefasız Yare', 'yol-ver-gonlum-vefasiz-yare-yurdagul-ozay-0hc8v', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Faydası yok  kor olup da her gün yanmaya

Yol ver gönlüm yol ver gitsin vefasız yare

Gece gündüz kahır içip küsüp dünyaya

Yol ver gönlüm yol ver gitsin vefasız yare

Derman olmaz yaramıza derdi çeksek de

Dönüp bakmaz yüzümüze boyun büksek de

Bilinmedi kıymetimiz candan geçsek de

Yol ver gönlüm yol ver gitsin vefasız yare

Yaradan dan başkasına kul olmayız biz

Baharı görmeyen dala gül olmayız biz

Kanasa da her gün yara derman derdimiz

Yol ver gönlüm yol ver gitsin vefasız yare

Unut artı unut gönlüm bizi yıkanı

Bir sevda uğruna her gün ömrü yakanı

Gidenin düşme peşine dönüp arkanı

Yol ver gönlüm yol ver gitsin vefasız yare', 'Faydası yok  kor olup da her gün yanmaya Yol ver gönlüm yol ver gitsin vefasız yare Gece gündüz kahır içip küsüp dünyaya Yol ver gönlüm yol ...', ARRAY['Türk Edebiyatı','Şiir','Yurdagül Özay']::text[], 8.5, '{"poet":"Yurdagül Özay","poet_slug":"yurdagul-ozay","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yol-ver-gonlum-vefasiz-yare-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne yıllar gördüm', 'ne-yillar-gordum-tuncay-akdeniz-8xq80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dünya yaşamına,ömür yetmiyor,

Efkarlı bakışla,ne yıllar gördüm.

Yüreklerde yanan,hasret bitmiyor,

Ayrılığa giden,ne yollar gördüm.

Dertliden dertlidir belalı başım

Dağlar taşlar oldu benim sırdaşım

Aşığım mecnunum sevda yoldaşım

Uğruna gezdiğim ne çöller gördüm

Varlığı bilinmez karışık alem

Sevgiyi sevdayı yazandır kalem

O insan bildiğin almaz bir selam

Hatıra uzanan ne eller gördüm

Bedendeki ruhum aşkla beslenir

Kuş kafes içinde dala seslenir

Edepler boyanır haya süslenir

Arında ihramsız ne kullar gördüm

O tatlı dillerin sözüne kandım

Özünü öz bildim özümdür sandım

Döktüğü yaşına gözümü bandım

Yağmur sevdasına ne seller gördüm

Sürmesen kalbine güzellik harcı

Rabbim can verendir alacak borcu 

Tuncay kulsun olma gönül kırıcı

Acı tatlı söyler ne diller gördüm', 'Dünya yaşamına,ömür yetmiyor, Efkarlı bakışla,ne yıllar gördüm. Yüreklerde yanan,hasret bitmiyor, Ayrılığa giden,ne yollar gördüm. Dertliden...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ne-yillar-gordum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Utanırım...', 'utanirim-pinar-koc-2vfht', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hüzünler bekler beni,

Sonbaharın sarı yapraklarında…

Taş olmuş kalbim için,için ağlar

Sabahlara dek…

Kimse görmez göz yaşlarımı 

Utanırım…

Sensizlikten ağlayan yüreğimi 

Gösteremem kimselere 

Utanırım…

Kaybolmuşluğumu bilirim sadece

Sensizliğimin içinde

Kahrolurum,

Utanırım…

Yalanlarımı bilirim,

Kendimi kandırdığım,

Bana göre pembe,

Sana göre kapkara yalanlarımı…

Utanırım…

Hazan yaprakları bilir beni,

Bir beni,

Birde sensiz beni…

Sadece onlara anlatırım,

Anlatırım,

Anlatamadıklarıma 

Utanırım…

Gök gözlü dedem bilir beni,

İçimdeki göğü,

İçimdeki gözleri…

Bir o bilir benim gözlerimi,

Birde gökyüzünde ki gözlerin…

Gözlerine bakmaya 

Utanırım…

Uykusuz gecelerim bilir beni 

Sıcak ekmek gibi kokan

Karanlıklarım bilir! 

Bir gecelerim bilir,

Birde göz kapaklarım…

Kapatamam gözlerimi 

Utanırım…

Bir şiirlerim bilir beni,

Bir de derin şarkılarım…

Ne okuyabilirim şiirlerimi,

Ne de şarkılar söyleyebilirim,

Çığlık çığlığa dağlarıma…

Sana şarkılar söylemeye 

Utanırım…

                                                           28.05.2002   05:28', 'Hüzünler bekler beni, Sonbaharın sarı yapraklarında… Taş olmuş kalbim için,için ağlar Sabahlara dek… Kimse görmez göz yaşlarımı  Utanırım… S...', ARRAY['Türk Edebiyatı','Şiir','Pınar Koç']::text[], 8.5, '{"poet":"Pınar Koç","poet_slug":"pinar-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/utanirim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakmadan Görmek...!', 'bakmadan-gormek-pinar-koc-2yfm0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dalıp giderim çoğu zaman,

Düşüncelerimin renkli fotoğraflarına…

Delice çeviririm sayfaları,

Çoğunu görmeden bakar giderim…

Görmek istediklerime bakar,

Bakmak istemediklerimi

Görmem…

                                           03.05.2002    01:59', 'Dalıp giderim çoğu zaman, Düşüncelerimin renkli fotoğraflarına… Delice çeviririm sayfaları, Çoğunu görmeden bakar giderim… Görmek istedikler...', ARRAY['Türk Edebiyatı','Şiir','Pınar Koç']::text[], 8.5, '{"poet":"Pınar Koç","poet_slug":"pinar-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bakmadan-gormek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O kadar uzaktasın ki', 'o-kadar-uzaktasin-ki-firat-ulker-onaap', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Duygu yüklü bi çığlığım

Son sürat sana geliyorum

Bana o kadar uzaktasın ki

Dağlarına çarpmadan eteklerine düşüyorum

Serseri bi kurşunum

Hedefimsin sana geliyorum

Bana o kadar uzaktasın ki

Yüreğine saplanmadan avucuna düşüyorum

Ufacık bi fidanım

Bütüm gücümle büyüyorum

Bana o kadar uzaktasın ki

Yükseliyorum,yükseliyorum değemiyorum

Gökyüzünde bir yıldızım

Kayarak sana geliyorum

Bana o kadar uzaktasın ki

Saçlarına düşmeden parçalanıyorum

Kara buluttan çıkan bi yağmur damlasıyım

Hiç bi yere dokunmadan sana yağıyorum

Bana o kadar uzaktasın ki

Sana değmeden buharlaşıyorum

Okyanusta bi dalgayım

Büyüyerek sana geliyorum

Bana o kadar uzaktasın ki

Vücuduna çarpmadan çekiliyorum

Ve ben artık bi körüm

Ne yana baksam seni görüyorum

Her yer çok karanlık

Yani bana o kadar uzaktasın..', 'Duygu yüklü bi çığlığım Son sürat sana geliyorum Bana o kadar uzaktasın ki Dağlarına çarpmadan eteklerine düşüyorum Serseri bi kurşunum Hede...', ARRAY['Türk Edebiyatı','Şiir','Fırat Ülker']::text[], 8.5, '{"poet":"Fırat Ülker","poet_slug":"firat-ulker","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/o-kadar-uzaktasin-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masada Kaldım', 'masada-kaldim-firat-ulker-fqq1r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Koca dünya aslında

Küçük bir ameliyathanedir

İçinde kesici kurt dişleri

Yırtıcı hayvanlar,uyuşturucu böcekler

Şok edici enflasyon,narkoz etkili dertler

Ve daha biçok şey var

Hayat denen zaman

Bir organ nakli için gereken süredir

Bizler bir anadan alınıp

Diğer bi anaya veriliyoruz

Bizi doğuran annemizden alıyorlar

Toprak anaya gömüyorlar

İşte bu kısa zaman dilimi iyi geçiyorsa

Ameliyat başarılıysa

İşini bilen doktorların,hemşirelerin

Ellerinden geçmişsin demektir

Ama bir de masada kalmak var

Bundan herkes korkuyor

Fakat ben korkmuyorum

Beni bu nakilden kurtaracak,ölümsüzleştirecek

Üzerinde korkusuzca,endişesizce

Kendimi tamamen bırakarak uzanabileceğim

Güvenip,sevebileceğim bir sevgilim var

Sen varsın bebeğim..

Seni tüm masumluğum ve içtenliğimle

Tamamı ile gerçek bi sevgi ile seviyorum

Seni çok seviyorum..

Dudaklarım,ruhum,varlığım,bedenim

Her şeyimle seninim

Sonsuzluğa sevgilim

Bunu hakedecek ne yaptım bilmiyorum ama 

Şans işte 

Masada kaldım..', 'Koca dünya aslında Küçük bir ameliyathanedir İçinde kesici kurt dişleri Yırtıcı hayvanlar,uyuşturucu böcekler Şok edici enflasyon,narkoz etk...', ARRAY['Türk Edebiyatı','Şiir','Fırat Ülker']::text[], 8.5, '{"poet":"Fırat Ülker","poet_slug":"firat-ulker","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/masada-kaldim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ye...Ye...Ye...', 'ye-ye-ye-alper-kuruk-41zzd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Söğütlüçeşmenin sivrisineği

Kavaklıderenin kurbağası

Elele verip gençliği temsile hevesli...

Yaylı sazlar,telli sazlar ve nefesli...

Ağızlarda bir müzik Ye...Ye...Ye...

Ne yersen ye,ne yersen ye,

Bırakma da birşey geriye,

Dönme de geriye

İlericilik dediğin de bu değil mi ki? 

Mini etekler çıkalıberi

Uyandırdı softanın kinini,

Ne durursun be kızım hanım-hanımcık

Atıver gitsin üstündekini...

Açlıktan çıkar herşey

Doyur şu aç gözlülerin gözlerini.

İlericilik bu,garpçılık bu

Dâima ileriye,dönme geriye

Ye...Ye...Ye...Ye...Ye...Ye...Ye..Ye...Ye...

Neydi eskiden hamamda bırakılan? 

Söyleyin,söyleyin,çekinmeyin.

Öyleyse ben diyeyim siz dinleyin:

H i ç...

Şimdi diskotekte bir sallan,bir yuvarlan

Bir de üstüne Ye...Ye...Ye...

Bir de ondan...

Dur babam dur! bu gidiş nereye? 

Dedik ya canım dâima ileriye...

Yoluna durma sözüm ona bu tiplerin

Softa kafalı! gerici! ne anlarsın ki sen? 

Karşındakini deden mi sandın cepheden cepheye koşan? 

Karşındakini nenen mi sandın sırtında mermi taşiyan? 

Haydi oradan,kafasız,sersem! 

Dünya değişti şimdi,buğday biçerim darı ekersem.

Hele şöyle bir de yağ çekersem

Ekmeden,biçmeden de ambarlarım dolar,taşar

Ondan sonra ye babam ye....

Ye...Ye...Ye...

Memleket böyle refaha kavuşur,böyle kalkınır,

Özgür,medenî insan böyle yaşar.

Sözlerime inanmayın,alt tarafı mizahtır,hicivdir

Alınıp ta kızmaya kalkan bence ahmaktır.

Lâf aramızda ama alınmayanlar için

Bir ufacık tokmaktır...

Ne demişler eskiler:''Anlayana sivrisinek saz...''

Anlamayan kendini ördek sanan

Koca bir k a z....', 'Söğütlüçeşmenin sivrisineği Kavaklıderenin kurbağası Elele verip gençliği temsile hevesli... Yaylı sazlar,telli sazlar ve nefesli... Ağızlar...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/ye-ye-ye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sırlı gözler', 'sirli-gozler-ugur-aydin-2-2p5ja', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bir ayrılık  acısı saklıydı yüreğinde

birde ayakalrının arasına düşürdüğü otobüs bileti

yitiremek üzere olduğu umutları vardı ellerinde.

boşaltdı birden yesil gözlerinden yaş...

içim doldu bende ağlamak üzereyim arkadaş

eğildim aldım bileti yerden

sizden düştü bu galiba diyerek başladım söze erken

sırlı gözlerle baktı gözlerimin içine

sesi titiriyordu luzum kalmadı derken

durmamıştı yesil gözlerinden akan yaş

içim doldu bende ağlamak üzereyim arkadaş....

bir parca pecete uzandı ön koltuktan

silindi gözlerinden akan yaş

umutla sarıldı boynuma

senden ayrıltıktan sonra bende ağladım  arkadaş', 'bir ayrılık  acısı saklıydı yüreğinde birde ayakalrının arasına düşürdüğü otobüs bileti yitiremek üzere olduğu umutları vardı ellerinde. boş...', ARRAY['Türk Edebiyatı','Şiir','Uğur Aydin 2']::text[], 8.5, '{"poet":"Uğur Aydin 2","poet_slug":"ugur-aydin-2","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sirli-gozler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pişmanlığa Ne Gerek Var', 'pismanliga-ne-gerek-var-dilek-hokkaomeroglu-a2pd1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sonbahar hüznünü yaşıyorum

gök yüzünde çığlıklar

 geceyi korkutuyorlar.

avuçlarımda hala geçmişten izler

yıldızlarda bir ömrün

dilekleri var...

hangi yıla baksam

boşa çıkmış umutlar...

ben ben olmayalı,

nasıl geçmiş yıllar...

ellerimde kaldı papatyalar.

gözyaşlarım avuçlarımda,

bir bir toplandılar...

sel oldu taştı anılar.

mum ışığında başkaydı sevdalar

sonbaharda düşen

son yaprak ve pişmanlıklar.

geçip giden hayatlar,

şimdi

pişmanlığa ne gerek var...', 'sonbahar hüznünü yaşıyorum gök yüzünde çığlıklar  geceyi korkutuyorlar. avuçlarımda hala geçmişten izler yıldızlarda bir ömrün dilekleri var...', ARRAY['Türk Edebiyatı','Şiir','Dilek Hokkaömeroğlu']::text[], 8.5, '{"poet":"Dilek Hokkaömeroğlu","poet_slug":"dilek-hokkaomeroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/pismanliga-ne-gerek-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unuttum', 'unuttum-derya-uysal-r0zpk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sen yalnız gecelerimin soluğusun 

gün ağarırken ellerini bıraktığım 

çocukluğumsun. 

Severken düşünemediğim 

Unutmak için hatırladığım 

Yarını olmayan 

Yarim kalamayan 

Hayalimsin.. 

Gördüğüm güzelliklere 

Hep senin adını verdim 

Denizin sesinde tadın var 

terleyen avuç içlerimde 

Şimdi 

Yalnızca 

Büyük puntolarla 

Unuttum yazar. 

Desem de yine de inanma 

Nasıl ki kanmadıysan boyadığım pembe rüyalarla 

Var unuttuğuma da inanma 

Nasıl ki hatırlamıyorsan 

İşte öyle, 

Öyle kanma..', 'sen yalnız gecelerimin soluğusun  gün ağarırken ellerini bıraktığım  çocukluğumsun.  Severken düşünemediğim  Unutmak için hatırladığım  Yarı...', ARRAY['Türk Edebiyatı','Şiir','Derya Uysal']::text[], 8.5, '{"poet":"Derya Uysal","poet_slug":"derya-uysal","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/unuttum-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dün', 'dun-perihan-dosgul-wlkub', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dün yine gezdiğimiz sokaklarda aradım seni

Her adımın da, her nefesinde seni aradım...

Seni aradım, mutluluk dolu gözlerini

Hasretle tutuşan yüreği

Göz pınarlarımdaa akan yaşları

Durdurmak istedim, şahitlik yapsınlar

 Aşkıma aşkıma diye...

Olmadı yenik düştüm, hasret kokan ayrılığına

Sıcacık ellerine, şimşek gibi yakan bakışlarına

Öpücüğüne...', 'Dün yine gezdiğimiz sokaklarda aradım seni Her adımın da, her nefesinde seni aradım... Seni aradım, mutluluk dolu gözlerini Hasretle tutuşan...', ARRAY['Türk Edebiyatı','Şiir','Perihan Dosgül']::text[], 8.5, '{"poet":"Perihan Dosgül","poet_slug":"perihan-dosgul","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/dun-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masum Aşklar Ağlıyor', 'masum-asklar-agliyor-firat-ulker-3h8o4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kirlenmiş dünya,kirlenmiş insanlar

Hava,su,toprak

Hayat kirlenmiş

Kıyamet günü gelmeden kopmuş

Nefes alınmıyor

Küçülüyor,daralıyor dünya

Canlılar boğuluyor

Hayat son deminde

Masum aşklar ağlıyor

Duygularda kirlenmiş

Sevgi saygı kalmamış

Çıkar ilişkilerine dayalı bir dünya doğuyor

Ufak fakat tehlikeli bir bebek

Ciğerlerine oksijen değil kir yağıyor

Kendi değil 

Masum aşklar ağlıyor

Binlerce ufak göletler oluşuyor

Her bir canlı gölgesinde

Simsiyah su birikintileri

İç karartıcı,ürkütücü

Duygu köreltici,kalem kırıcı

İlham perilerini tek tek kurşuna dizen

Katil bir dünya büyüyor

Şiir,resim,müzik

Tüm sanat dalları toprağa veriliyor

Masum aşklar ağlıyor

Bir ateş gibi büyüyor bu virüs

Sıçradığı yeri yakıyor

Teker teker ölüyor masum aşıklar

Bir sen kalıyorsun bir de...

Bense fırat''ım gözlerinde

Nehir olup kızıl dudaklarına gömülüyorum

Bir sen kalıyorsun bu lanet olası yerde

Masum aşklara ağlayan

Masum aşkım,sen

Sen kalıyorsun geride.,

Gözbebeklerin kurudu,ağlamıyorsun

Sonunda bende öldüm güzelim

Gül yüzünü dök toprağıma

Belki bir gün biri gelir

Koklar bu çiçeği

Çektiğimiz acılar dolar içine

Ve der ki

Masum aşklar ağlıyor..

                                                           06.20.03/02-35', 'Kirlenmiş dünya,kirlenmiş insanlar Hava,su,toprak Hayat kirlenmiş Kıyamet günü gelmeden kopmuş Nefes alınmıyor Küçülüyor,daralıyor dünya Can...', ARRAY['Türk Edebiyatı','Şiir','Fırat Ülker']::text[], 8.5, '{"poet":"Fırat Ülker","poet_slug":"firat-ulker","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/masum-asklar-agliyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Dağ Başında', 'bir-dag-basinda-salim-erben-fwd5j', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir dağ başında 

Bir uçurum kenarında 

Açan kır çiçeklerinin 

Eriyen sevdalı bakışlarını 

Nasıl boyun büktüklerini 

Bilirmisin. 

Onlar sevgiye inat açarlar 

kimselerin uğramayacağını 

bile bile açarlar 

Aşka sevgiye inat 

Hasretle  beklerler 

Gelmeyeceğini bile bile 

Bende seni bir kış günü 

Bir dağ başına 

Bir uçurum kenarında 

Bir kardelen edasıyla beklerim 

Bütün güllere inat ölesiye zalım

Belki gelirsin diye', 'Bir dağ başında  Bir uçurum kenarında  Açan kır çiçeklerinin  Eriyen sevdalı bakışlarını  Nasıl boyun büktüklerini  Bilirmisin.  Onlar sevgi...', ARRAY['Türk Edebiyatı','Şiir','Salim Erben']::text[], 8.5, '{"poet":"Salim Erben","poet_slug":"salim-erben","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bir-dag-basinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak Bu İse...', 'yasamak-bu-i-se-alper-kuruk-fksix', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Nerde o şair ve o güzel deyişi nerde? 

'' İç bâde,güzel sev,varsa aklın,şuurun...''der de

İnsanı bırakmazdı bu söz  gamda,kederde,

Güç verir ve şifa olurdu sanki her derde...

Kestiler zehrimi tümden,kısmen meyimden de...

Sağlıklı hayat için buna değer de....

İnsanım ki cismen var olduğum bu bedende

Yaşamak isterim ömrümü özgürce ben de...', 'Nerde o şair ve o güzel deyişi nerde?  '' İç bâde,güzel sev,varsa aklın,şuurun...''der de İnsanı bırakmazdı bu söz  gamda,kederde, Güç verir v...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yasamak-bu-ise-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bütün sıfatları yükledim gülen yeşil gözlerine..', 'butun-sifatlari-yukledim-gulen-yesil-gozlerine-derya-uysal-krpan', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bugun ayrılık rüzgarı vuruyor pencereme, 

Oysa ben sensizliği düşleyip 

bastırmıştım en giz yanıma... 

Sen benim en büyük yasağımdın... 

yasaklara inat sevmiştim 

aydınlığını gözlerinin. 

Candın sen bir vakitten sonra bedenime.. 

Aşktı sana beni getiren 

sonrasında en insan yanım beni sende tutan.. 

Bütün sıfatları yükledim gülen yeşil gözlerine.. 

Aşktın sen, 

sevdaydın en kızılından... 

Anaydın/anamdın en çaresiz anlarımda sığındığım... 

Şafak yüzüme vuruyor, 

almaya geldi seni kör karanlık... 

GİTMEler en son hecesini tüketti... 

Heceleri uzatmalı bu gece.. 

sesleri bölük pörçük etmeli.. 

KALlar gelmeli ardından 

ve yeni heceler eklenmeli sevdaya dair... 

sevdam! en insan yanım; 

firari türküler eşliğinde çıkmalı bu gece 

ve feda eyleminin en büyüyüğünü yapmalı 

kör karanlığın orta yerinde. 

pimini çekmeli senli duyguların 

bir veda sözcüğü eşliğinde...', 'Bugun ayrılık rüzgarı vuruyor pencereme,  Oysa ben sensizliği düşleyip  bastırmıştım en giz yanıma...  Sen benim en büyük yasağımdın...  yas...', ARRAY['Türk Edebiyatı','Şiir','Derya Uysal']::text[], 8.5, '{"poet":"Derya Uysal","poet_slug":"derya-uysal","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/butun-sifatlari-yukledim-gulen-yesil-gozlerine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aç Yüreğini Üşüyorum', 'ac-yuregini-usuyorum-nurten-tarim-4vp4l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aç yüreğini üşüyorum

Gireğim içine sar beni

Yıldızım deme 

Kayar giderim enginlere

Alemlerin otesine 

N''oolur  ayrılık olmasın yazgımızda

Tut elimi

Şalele olup düşelim 

Irmağın yatağına

Hayat suyu götürsün denizlere', 'Aç yüreğini üşüyorum Gireğim içine sar beni Yıldızım deme  Kayar giderim enginlere Alemlerin otesine  N''oolur  ayrılık olmasın yazgımızda Tu...', ARRAY['Türk Edebiyatı','Şiir','Nurten Tarım']::text[], 8.5, '{"poet":"Nurten Tarım","poet_slug":"nurten-tarim","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ac-yuregini-usuyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Önce vede Sonra', 'once-vede-sonra-serkan-asilbas-frxfe', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Önce boş boş bakarsın karşına,

Sonrada yavaş yavaş etrafına,

Ellerin ağzını kapatır, gözlerin kapanır.

Yutkunursun... gözlerin açılır.

Önce boş boş bakarsın karşına,

Sonrada yavaş yavaş etrafına,

Ellerin ağzını kapatır, gözlerin açılır.

Yutkunursun... Gözlerin kapanır.

Sonra,

Yanaklara yuvarladıkça yaşlar,

Adı konulmadık bir ağıt başlar.

Göz kapakları ağır ağır düşer,

Gözler düşünce girdabında kaybolur,

Buğulu bir camı andırır adeta.

Başını çeviremezsin etrafına,

Yutkunamazsın artık, boğazın düğümlenmiştir.

Sana seslenir yanındaki dostların,

Canını acıtır bu ayrılık, duymak istemezsin.

Fakat seslerini beyninin her köşesinde duyarsın.

Sadece sessizlik sessizlik istersin.

Ama lügat acizdir o anda konuşamazsın.

Kaçmak istersin herkesten herşeyden, kaçamazsın.

Ağlamamak istersin oda farketmez.

Beynin gözyaşlarınada hükmedemez, ağlarsın.', 'Önce boş boş bakarsın karşına, Sonrada yavaş yavaş etrafına, Ellerin ağzını kapatır, gözlerin kapanır. Yutkunursun... gözlerin açılır. Önce ...', ARRAY['Türk Edebiyatı','Şiir','Serkan Asılbaş']::text[], 8.5, '{"poet":"Serkan Asılbaş","poet_slug":"serkan-asilbas","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/once-vede-sonra-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yıldönümü', 'bir-yildonumu-alper-kuruk-hw8mt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şükürler olsun Tanrı''m ne güzel geçti zaman

Tam kırk bir yıl öncesi bugün yapmıştık nişan...

Bu güzel yıllarımız nice yılla uzasın

Anısı ruhumuzda,tadı damakta kalsın...

Geçen bunca sürede sevgi acıyı yedi

Yedikçe de semirdi,başkası var mı? dedi.

İşte biz bu günlere böyleliklerle geldik

Çevre çirkin olsa da biz sevdikçe güzeldik...

Dilimizden düşmedi bizim ortak şarkımız:

'' Para, pul mühim değil,mühim olan aşkımız...''

Biz bu teranelere inanarak yaşadık

Gönlümüz hep genç kaldı,vücut ile yaşlandık...

Şimdi demek gerekir; '' kırk bir kere Maşaaallah! ''

Sağlık versin,aşkımız yıllar sürsün İnşaaallah...', 'Şükürler olsun Tanrı''m ne güzel geçti zaman Tam kırk bir yıl öncesi bugün yapmıştık nişan... Bu güzel yıllarımız nice yılla uzasın Anısı ruh...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bir-yildonumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Helga', 'helga-abdulvahap-ates-szjuc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir Türk Alman’a

Gönül kaptırır

Bu sarışına aşkla açılır

Evlenelim der

Bir gün bir barda

O an gülümser

Sevgiyle Helga

Elini tutar

Özlemle bakar

Alır çakmağı

Sigara yakar

Ali tedirgin

Her hali gergin

Bir problem var

Dinimiz farklı

Ailem sorar

Sormakta haklı

Ben de istemem

Hem evlenemem

Gel dinimden ol

Da evlenelim

Ömür uzun yol

Huzur bulalım

Düşünür Helga

Der ki İslam zor

Mış gibi yapmam

Zaten yapamam

Beş vakit namaz

Erken kalkmak var

Her anın niyaz

Yapamam aksar

Ali der yok be

Boş ver namazı

O bir ucube

Sofu niyazı

Peki ya oruç

Oruç tutamam

Sabretmek çok güç

Hem dayanamam

Peki örtünmek

Hiç sorun değil

Safdillik demek

Çağdaşlık değil

Din okulunda 

Bile yasak o

Çağdaş kafada

Bir safsata o

İçkisiz hayat

Ben katlanamam

Faizsiz hayat

Gerçeğe tezat

Helga afallar

Sigara yakar

Üfler dumanı

Ali’ye bakar

Der Aliciğim

Canım sevdiğim

Bu Müslümanlık

Sana uymuyor

Hıristiyanlık

Hiç ters durmuyor

Yaşamadığın

Bu dini bırak

Yakınlaştığın

Dinimde olmak

Kilise yakın

Hıristiyan ol

Zaten dininin

Sana karı yok', 'Bir Türk Alman’a Gönül kaptırır Bu sarışına aşkla açılır Evlenelim der Bir gün bir barda O an gülümser Sevgiyle Helga Elini tutar Özlemle ba...', ARRAY['Türk Edebiyatı','Şiir','Abdulvahap Ateş']::text[], 8.5, '{"poet":"Abdulvahap Ateş","poet_slug":"abdulvahap-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":69,"source_url":"https://www.antoloji.com/helga-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dert Çömleği', 'dert-comlegi-kamber-bal-gi7uc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Düştüm dünyamdan habersiz

Çırpındığım yer dert çömleği

Gönül ahudiyarındayım dilsiz

Hıçkırdığım yer dert çömleği

Ne var ala başı baştan

Baş kurtula her bir düşten

Çıkar oldum bin bir işten

Sızlandığım yer dert çömleği  

Kim güler ki kimin haline

Hemen düşer onun yerine

Çekilmez ızdırap gülünde

Tozlandığım yer dert çömlerği

Yerim göğüm bir zindan

Yanarım odsuz ahım duman

Çalar dururum sessiz bir keman

Bal''landığım yer de dert çömleği', 'Düştüm dünyamdan habersiz Çırpındığım yer dert çömleği Gönül ahudiyarındayım dilsiz Hıçkırdığım yer dert çömleği Ne var ala başı baştan Baş ...', ARRAY['Türk Edebiyatı','Şiir','Kamber Bal']::text[], 8.5, '{"poet":"Kamber Bal","poet_slug":"kamber-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dert-comlegi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Halimiz', 'halimiz-rifki-kaymaz-dayao', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her yer bir başka alem, dert üstüne dert verir

İnsan bir mum misali, gün gün yanarak erir.

Evler ateş pahası, kira ödenmez ücret

Yaşamak güç bir sınav, çalış, didin ve sabret.

Çarşı, Pazar çıkmak zor, fiatlar el yakıyor

Sanki dört bir tarafta, zam ırmağı akıyor.

Bakkala borç yığılır, rakam üstüne rakam...

Ne zaman bir araya gelecek iki yakam.

Sana cevap vermeye tenezzül etmez memur

“Bugün git, yarın gel! ” le geçmektedir bir ömür.

Sen emek vermektesin dökerek alın teri...

Köşeleri dönmekte, rüşvetle birileri.

Sözü uzatmak kolay, işi yapmak ise zor,

“İnsan” olayım dersen, önce vicdanına sor.', 'Her yer bir başka alem, dert üstüne dert verir İnsan bir mum misali, gün gün yanarak erir. Evler ateş pahası, kira ödenmez ücret Yaşamak güç...', ARRAY['Türk Edebiyatı','Şiir','Rıfkı Kaymaz']::text[], 8.5, '{"poet":"Rıfkı Kaymaz","poet_slug":"rifki-kaymaz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/halimiz-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimsesizlikten Kimsesizliğe', 'kimsesizlikten-kimsesizlige-halis-babat-4ywd3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kimsesiz çiçekler bıraktım sana,

kırların hasret kokan ruzgarlarında.

kimsesiz kelebekler bıraktım sana,

dağların mermi uçlu yamaçlarında.

kimsesizce kalıp, kimsesizliğimi bıraktım sana,

Firari kimsesizliğimle kaldığım uzaklığında.

son çiçeğimi kopardım aşkın bahçesinden,

son bir kez kokladım,

başıboş ve avare bir hasretle.

martıların denizle sevişmesini izledim,

balıkların kaçışmasını.

yaşadığımız günlerin hülyasına daldım.

güzeldi.

gelecek günlerin hayalini kurdum.

sensizliğin ağına ve 

ölümün ustura ağzına takıldı.

Ve son birkez kimsesizce ağladım,

ayağıma pranga gibi dolanan kimsesizliğime.

Ve ben gidiyorum,

Sensizliği taşıyarak tüm yorgunluğumla.

Ve ben gidiyorum,

ölüm evde misafir,

Azrail ise soframda...

Kimsesizliğimle veda ediyorum,

benim gibi kimsesiz olan yalnızlığıma.

Ve ben gidiyorum, ve ben gidiyorum,

sensiz kalacağım kuytu mezarıma.

kimsesizim,

gidiyorum işte,

katil kimsesizliğimle.

Sana son bir veda, sana son bir bakış,

sana son bir buse

ve kimsesizce bir haykırış:

elveda...! 

Gidiyorum yeni bir kimsesizliğe,

yalnız ve kimsesizce.', 'Kimsesiz çiçekler bıraktım sana, kırların hasret kokan ruzgarlarında. kimsesiz kelebekler bıraktım sana, dağların mermi uçlu yamaçlarında. k...', ARRAY['Türk Edebiyatı','Şiir','Halis Babat']::text[], 8.5, '{"poet":"Halis Babat","poet_slug":"halis-babat","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/kimsesizlikten-kimsesizlige-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Bana- Ben Sana Dönelim Artık', 'sen-bana-ben-sana-donelim-artik-kamber-bal-bn9ga', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mevsimler, geldi geçti yenisine kadar

Sen bana-ben sana dönelim artık

Sönmüş hayatımız, dönmez zar

Sen bana-ben sana dönelim artık

Bugün son baharın son günleri

Kalmadı soldu cemalin gülleri

Sustu bak, ötmüyor gönül bülbülleri

Sen bana-ben sana dönelim artık

Yemiş-yaprak dersen hepsi sarı

Bende hal kalmadı, dinmez gönlümün ahuzarı

Gül be hey gülüm! yapma inat sen de gayrı

Sen bana-ben sana dönelim artık

Kader hicrana battı, sonsuz kuyu

Kurumuş çeşmim yaşı akmaz suyu

İnat ne inat! terkeyle bu huyu....

Sen bana-ben sana dönelim artık

Yaşayan bir sen, bir de ben var

Mazide kaldı bütün sana yalvaranlar

Yolumuz bitti, belli ki Bal bu  kadar

Sen bana- ben sana dönelim artık', 'Mevsimler, geldi geçti yenisine kadar Sen bana-ben sana dönelim artık Sönmüş hayatımız, dönmez zar Sen bana-ben sana dönelim artık Bugün son...', ARRAY['Türk Edebiyatı','Şiir','Kamber Bal']::text[], 8.5, '{"poet":"Kamber Bal","poet_slug":"kamber-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sen-bana-ben-sana-donelim-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cinzelzele', 'cinzelzele-rahim-tas-y7lhr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Cinzelzele 

Uyuyordu sarsıntı başladığında 

Ayaklandı 

Dar geldi beyaz çadırı boğuluyordu 

Yardım istedi 

Kursağındakileri atmak için 

Prefabrik konuta kondu 

Burası değildi yeri, anladı 

Tatmin olmadı 

Eller üstünde taşındı 

Özlemini duyduğu 

Huzur bulacağı 

İçini boşaltacağı 

Kalıcı konutlara 

Ölmüştü 

Ama biliyordu 

Hatta emindi 

Yeni bir ruh göçüyle

Yeniden ayaklanacağını… 

11 Aralık 2005

Rahim TAŞ', 'Cinzelzele  Uyuyordu sarsıntı başladığında  Ayaklandı  Dar geldi beyaz çadırı boğuluyordu  Yardım istedi  Kursağındakileri atmak için  Prefa...', ARRAY['Türk Edebiyatı','Şiir','Rahim TAŞ']::text[], 8.5, '{"poet":"Rahim TAŞ","poet_slug":"rahim-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/cinzelzele-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Analar', 'analar-ramazan-kayak-y9huw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Analar

Analar vardır melek yüzlüdür

Analar vardır tatlı sözlüdür

Analar vardır ceylan gözlüdür

Analar vardır gam çile yüklüdür

            Analar, analar

Analar vardır evladına can veren

Analar vardır gençliğinden vazgeçen

Analar vardır saçlarını ak eden

Analar vardır yoksullukla yaşayan

            Analar, analar

Analar vardır ağlayıp gülmeyen

Analar vardır çöplüklerde sürünen

Analar vardır sokaklarda dilenen

Analar vardır evladını özleyen 

             Analar, analar 

                                                                                        

                              Ramazan Kayak', 'Analar Analar vardır melek yüzlüdür Analar vardır tatlı sözlüdür Analar vardır ceylan gözlüdür Analar vardır gam çile yüklüdür             A...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Kayak']::text[], 8.5, '{"poet":"Ramazan Kayak","poet_slug":"ramazan-kayak","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/analar-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Liseli kız', 'liseli-kiz-ramazan-kayak-yr92s', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Liseli kız

Sokaklardayım sokaklar sensiz sokaklar ıslak buz gibidir

İstesem de gelmezsin bilirim sensizliğimi paylaşmaya

Bir başıma kalmışım yalnızlık denizinde neredesin 

En güzel günlerim seni beklemekle geçiyor

Liseli kız sevgi nedir seni sevmek nasıldır 

                                            Yoksa bilmez misin? 

Sevda denizinde bu kalbim sensiz harap kırgın

İle de seni ister bu divane perişan laf dinlemez gönlüm

Beni bırakmış yalnızlıklar ülkesinde yine senin peşinde

Ellimde değil koşarım peşinde hiç istemesem de 

Liseli kız sevgi nedir seni sevmek nasıldır 

                                             Yoksa sen bilmez misin? 

Sensizlikte ömür nasıl yaşanır günler nasıl geçer bilir misin? 

İnsanın içine kaç bahar gelip gider umutsuzca

Bilir misin tutsaklığı senin o kara gözlerinden

Ezilmek sürünmek nedir sevdanın hasretliği peşinde 

Liseli kız sevgi nedir seni sevmek nasıldır 

                                              Yoksa sen bilmez misin? 

                                                 Yoksa sen bilmez misin? 

                                                             Liseli kız', 'Liseli kız Sokaklardayım sokaklar sensiz sokaklar ıslak buz gibidir İstesem de gelmezsin bilirim sensizliğimi paylaşmaya Bir başıma kalmışım...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Kayak']::text[], 8.5, '{"poet":"Ramazan Kayak","poet_slug":"ramazan-kayak","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/liseli-kiz-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Müjde', 'mujde-ramazan-kayak-5ikd2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Müjde

Terk etiğim şehir

Sana geliyorum sokaklarına 

Şimdi bende varım eskiden olduğu gibi

Uzak bırakıldığım hayat kavgama

Müjde

Yaz kış demeden çalışan insanlara

Yemek bulamayan sokaktaki çocuklara

Yürekleri hasretle dolu analar

Sizinleyim susuzluktan çatlamış toraklar

Uslandırmaz beni hiçbir rutubetli oda

Selam olsun her kese şu darağacı var ya 

Taş havlulara dikenli tellere 

Karanfillere güllere doğan güneşe

İnşaatlarda çalışan kardeşlere 

Müjde terk etiğim şehir 

Artık senin kollarındayım 

Al bu yürek senindir ey koca şehir', 'Müjde Terk etiğim şehir Sana geliyorum sokaklarına  Şimdi bende varım eskiden olduğu gibi Uzak bırakıldığım hayat kavgama Müjde Yaz kış deme...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Kayak']::text[], 8.5, '{"poet":"Ramazan Kayak","poet_slug":"ramazan-kayak","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/mujde-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen hala yoksun', 'sen-hala-yoksun-ramazan-kayak-clfpw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen hala yoksun

Sular duruldu fırtına dindi 

Hala yoksun sen

Bir kere gelmiyorsun diye

Kör kuyulardadır yüreğim

Kaç şafak oldu karanlıklardayım

Sensiz günler zindandan beter

Gelmeni bekler bu yorgun gözler

Yaş kalmadı göz pınarlarımda

Sen hala yoksun

Sabır halkaları koptu içimde 

Tutamıyorum bendeki o diğer beni

Yakıyor içimi yokluğunun ateşi

Dön bekliyor seni kırılgan yüreğim 

Günler mevsimlerle geçiyor ömrümden

Sen hala yoksun

Çiçekler dikmiştim gönül bağıma 

Geleceksin diye tüm yollarına

Kaç bahar böyle senin uğruna

Geldi geçti seni beklerken

Sen hala yoksun

Yağmurlar yağıyor sensiz bağrıma

Boğuluyorum sen hala yoksun

Tükendi ömrüm senin uğruna

Mezara konuluyorum sen hala yoksun

                                  Sen hala yoksun', 'Sen hala yoksun Sular duruldu fırtına dindi  Hala yoksun sen Bir kere gelmiyorsun diye Kör kuyulardadır yüreğim Kaç şafak oldu karanlıklarda...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Kayak']::text[], 8.5, '{"poet":"Ramazan Kayak","poet_slug":"ramazan-kayak","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sen-hala-yoksun-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cahil çocuk', 'cahil-cocuk-ramazan-kayak-5by68', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Cahil çocuk

Bir güzel sevmiştim

Siverek ten uzak bir köyde

Ağaçsız susuz okulsuz yolsuz

Köyden

Bilmiyordu okumayı yazmayı

Saf tertemiz köylü kızı

Gel dedim uzaklara gidelim

Okullu olan suları akan yerlere

Bana bakıp dudak büktü

Başını eğdi yere baktı

Yanaklarından aşağı gözyaşları aktı

Gözlerimin içine, içine bakıp

 Hüzünle

Cahil çocuk dedi

Ya köyüm toprağım

Okumamış bu halkım

Ben buranın insanıyım uzakların değil

Ben köyümün parçasıyım

Gözyaşlarını sildi sessizce

Yanaklarımdan öptü özlemle 

Güle, güle 

Cahil çocuk dedi

Cahil çocuk..', 'Cahil çocuk Bir güzel sevmiştim Siverek ten uzak bir köyde Ağaçsız susuz okulsuz yolsuz Köyden Bilmiyordu okumayı yazmayı Saf tertemiz köylü...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Kayak']::text[], 8.5, '{"poet":"Ramazan Kayak","poet_slug":"ramazan-kayak","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/cahil-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Görme', 'gorme-abdulvahap-ates-403aa', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bele nefsini bele

Baht dile talih dile

Ben yanayım sen diye

Sen beni görme bile

Dile olmazı dile

Günleri iç nafile

Gözlerim çeksin çile

Sen dönüp  bakma bile

Öle bu canım öle

İçin için bir güle

Gençliğim gitti sele

Sen yazık deme bile

Pula kul oldun pula

Al öteye tapula

Yandığım  nankör kula

Beddua etmem bile', 'Bele nefsini bele Baht dile talih dile Ben yanayım sen diye Sen beni görme bile Dile olmazı dile Günleri iç nafile Gözlerim çeksin çile Sen ...', ARRAY['Türk Edebiyatı','Şiir','Abdulvahap Ateş']::text[], 8.5, '{"poet":"Abdulvahap Ateş","poet_slug":"abdulvahap-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gorme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unuttun Beni', 'unuttun-beni-ramazan-ates-4wd8f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İşte bak ki aramaz sormaz oldun,

Günler geçti işte, unuttun beni.

Derdin ki ben sensiz nefes alamam,

Günler geçti işte, unuttun beni.

Sevgin heves miydi gelip geçici? 

Özlemin, hasretin arzu istek mi? 

Senden ayrılamam, dayanamam derdin,

Günler geçti işte, unuttun beni.

Sevgi sanırdım da öyle bakardım,

Gözlerin gözümde yalanmış meğer.

Elin elimdeyken içim yanardı,

Günler geçti işte, unuttun beni.

Belkide içinden pişmanlık geçmiş,

Huysuzum, kabayım, yaşımda geçmiş.

Haklısın, anlarım, bana değmezmiş,

Günler geçti işte, unuttun beni.

Beni üzen ne mi? Seni sevdiğim,

Canım diye sana gönül verdiğim.

Sen inanmasan da gerçek sevdiğim,

Günler geçti işte, unuttun beni.

Yıllar geçse de unutamam seni.

Ramazan Ateş/Enschede-6.12.2005', 'İşte bak ki aramaz sormaz oldun, Günler geçti işte, unuttun beni. Derdin ki ben sensiz nefes alamam, Günler geçti işte, unuttun beni. Sevgin...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/unuttun-beni-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canımdan Ötem', 'canimdan-otem-hulusi-kilic-fjiv4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Canımdan ötem! 

Sen; güne,güle,güneşe...

Güzel olan herşeye layıksın.

Şımarık sevgilimsin

Sen benimsin; benim kalacaksın!', 'Canımdan ötem!  Sen; güne,güle,güneşe... Güzel olan herşeye layıksın. Şımarık sevgilimsin Sen benimsin; benim kalacaksın!...', ARRAY['Türk Edebiyatı','Şiir','Hulusi Kılıç']::text[], 8.5, '{"poet":"Hulusi Kılıç","poet_slug":"hulusi-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/canimdan-otem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Rüzgara Çağrı', 'deli-ruzgara-cagri-ramazan-ates-1ypg7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hadi artık yağmur yağsın,

Ağlamam belli olmasın.

Şimşek çaksın, gök gürlesin,

Hıçkırığım duyulmasın.

Essin deli rüzgar essin,

Yanan ateşimi kessin,

Artık fırtınalar kopsun,

Beni alıp benden gitsin.

Ne baharım yazım kaldı,

Ne kelamım sözüm kaldı.

Ağardı saç kışa döndüm,

Gurbette yaşarken öldüm.

Ramazan Ateş/Enschede-12.03.2004', 'Hadi artık yağmur yağsın, Ağlamam belli olmasın. Şimşek çaksın, gök gürlesin, Hıçkırığım duyulmasın. Essin deli rüzgar essin, Yanan ateşimi ...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/deli-ruzgara-cagri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyle Ne Yapmalıyım', 'soyle-ne-yapmaliyim-nurten-tarim-3h20a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kader demek kolayı seçmektir

Oysa ki insan kendi kaderini yazar

Kumsalda yürürken güneşim derdin

Hayal ettiğim düşlerim sendin

Ama güneş batmadan

Bir adım atmalıyım

Güzellikleri canlandırıp

Yeniden hayat bulmalıyım

Sen yüreğimdesin bebek kokulum

Deniz gözlüm

Güneş saçlım

Gel gör ki ben ne yapmalıyım

Söyle ne yapmalıyım', 'Kader demek kolayı seçmektir Oysa ki insan kendi kaderini yazar Kumsalda yürürken güneşim derdin Hayal ettiğim düşlerim sendin Ama güneş bat...', ARRAY['Türk Edebiyatı','Şiir','Nurten Tarım']::text[], 8.5, '{"poet":"Nurten Tarım","poet_slug":"nurten-tarim","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/soyle-ne-yapmaliyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arabistan''da Kadın Olmak', 'arabistan-da-kadin-olmak-ufuk-bayraktar-6jbo8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'orada kadının kimliği yok; 

edebi bir bezetiş değil bu; 

gerçekten yok! 

daha doğarken yok sayılıyorlar, 

hiç sayılıyorlar... 

kara çarşafın altında kalıyor umutları 

yaşamları... 

orada kadının söz hakkı yok; 

dudu dilleri kara çarşafın altında, 

kadının sesi yok... 

bütün bir ömür kara yasında 

o çarşafın altında; 

kadının gözyaşı yok! 

orada kadının yüzü yok 

oğul yabancıdır bir yaştan sonra; 

kapanır kucağı babanın 

ocağı; 

kadının evi yok! 

orada 

kadının adı yok!', 'orada kadının kimliği yok;  edebi bir bezetiş değil bu;  gerçekten yok!  daha doğarken yok sayılıyorlar,  hiç sayılıyorlar...  kara çarşafın...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Bayraktar']::text[], 8.5, '{"poet":"Ufuk Bayraktar","poet_slug":"ufuk-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/arabistan-da-kadin-olmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can Çiçeğim', 'can-cicegim-ramazan-ates-az2ve', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Artık son bahardım, kışa dönerken,

Sen çıktın karşıma, can çiçeğim sen.

Dertler beni boğup acı çekerken,

Sen tuttun elimden can çiçeğim sen.

Yürek açtın, gönül verdin sen bana,

Destek oldun, umut verdin sen bana.

İnsanlardan köşe bucak kaçarken,

Sen çıktın karşıma can çiçeğim sen.

Senle sevdim ben hayatı yeniden,

Sen gönlüme ışık yaktın yeniden.

Seni sevdi, sana aşık bu gönül,

Can çiçeğim sana sevgim derinden,

Sen hoplattın şu gönlümü yerinden.

Ramazan Ateş/Enschede-12.11.2004', 'Artık son bahardım, kışa dönerken, Sen çıktın karşıma, can çiçeğim sen. Dertler beni boğup acı çekerken, Sen tuttun elimden can çiçeğim sen....', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/can-cicegim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş', 'dus-hulusi-kilic-thu4g', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne kadar güzel,düşlemek! 

Seninle sahiller boyu yürümek,

Kırlarda koşmak

Ve doyasıya sarılıp öpüşmek,

Bahçede çiçek toplamak,

Kuşları izlemek seninle...

Gece yıldızların altında oturmak,

Günü yaşayıp,yarını konuşmak seninle...

Sevinçleri ve hüznü yaşamak

Ve birlikte ağlayıp gülmek seninle

Bir ömür birlikte yaşayp

El ele gitmek bilinmeyene...

Ama artık umut etmek de yetmiyor

Ben artık düşlemek değil,

Yaşamak istiyorum...', 'Ne kadar güzel,düşlemek!  Seninle sahiller boyu yürümek, Kırlarda koşmak Ve doyasıya sarılıp öpüşmek, Bahçede çiçek toplamak, Kuşları izleme...', ARRAY['Türk Edebiyatı','Şiir','Hulusi Kılıç']::text[], 8.5, '{"poet":"Hulusi Kılıç","poet_slug":"hulusi-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/dus-146-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unut Beni-1', 'unut-beni-1-suleyman-yavuz-zoesc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ölüm gibi karşımdasın

Uzaksın bana

Gelmek isterim yanına

Koymuyor eller beni

İsterim ki mutlu ol

Unut herşeyi

Sil benliğinden beni

Ve sonra yak bir bir resimleri

Unut beni

Bilitim kolay olmaz

Olmayacak

Unuttuğun her anı

Acıtır canını

Yırttığın her resim

Mahveder seni

Unut beni unut

Bakma ardına bir daha

Bilirim acı verir ayrılık insana

Unutmak ise daha beteri

Ama lütfen 

Sevsende beni 

Sen önce unut beni

Terk et geçmişe dair 

Herşeyi', 'Ölüm gibi karşımdasın Uzaksın bana Gelmek isterim yanına Koymuyor eller beni İsterim ki mutlu ol Unut herşeyi Sil benliğinden beni Ve sonra ...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Yavuz']::text[], 8.5, '{"poet":"Süleyman Yavuz","poet_slug":"suleyman-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/unut-beni-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostluğa Törpü', 'dostluga-torpu-kamil-at-pzgip', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Keskin törpü salladık dostluğa

Karlıdır diye yanaşmadık dağa

Anlaşmadık silah çektik toprağa

Bizden sonra gelecek dedik.

Başkası bilmez kendi yükseldik

Kiminde kıtken uyuyunca çaldık

Günahtır diye toprakta bunaldık

İçinde define yükselecek dedik.

Gelenekler beyinde kapladı bizi

Çıkarcılar söylediler dövdük dizi

Daha çok yaşı bulmadı onsekizi

Çoktan anaçtır evlenecek dedik.

Kendimize küstük dosttan ıradık

Tozlu saçlarımızı çivilerle taradık

Karanlıkta el yordamıyla aradık

Dostlukta ne, kim bilecek dedik.

Kamil sene ikibini buldu geçiyor

Körler zalimi tuttu dosttan kaçıyor

Beyler vergisini aldı bizi biçiyor

Beddua ettik geberecek dedik.', 'Keskin törpü salladık dostluğa Karlıdır diye yanaşmadık dağa Anlaşmadık silah çektik toprağa Bizden sonra gelecek dedik. Başkası bilmez kend...', ARRAY['Türk Edebiyatı','Şiir','Kamil At']::text[], 8.5, '{"poet":"Kamil At","poet_slug":"kamil-at","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dostluga-torpu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyanalım Artık', 'uyanalim-artik-ramazan-ates-a1z33', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Halkın derdini dile,

Getiririm şiirle,

Beni dinleyen dostlar,

Kulak versin sözüme.

Gurbet bizi yutuyor,

Acılara atıyor.

Gün be gün eriyoruz,

Bizi bizden çalıyor.

Gençliğimiz gitti bak,

Sönüyor pek çok ocak,

Eğer tedbir almazsak,

Bir nesil yok olacak.

Türk nesli yok olacak.

Ramazan Ateş/Enschede-14.10.2003', 'Halkın derdini dile, Getiririm şiirle, Beni dinleyen dostlar, Kulak versin sözüme. Gurbet bizi yutuyor, Acılara atıyor. Gün be gün eriyoruz,...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/uyanalim-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çöl', 'col-i-lker-caliskan-nelgb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İçimdeki tüm güzellikleri savurdu,

Umarsız esen samyeli.

Sessiz ve ıssız bir çöl gibi

Gündüz kavrulan yüreğim

Gece buz kesiyor şimdi!', 'İçimdeki tüm güzellikleri savurdu, Umarsız esen samyeli. Sessiz ve ıssız bir çöl gibi Gündüz kavrulan yüreğim Gece buz kesiyor şimdi!...', ARRAY['Türk Edebiyatı','Şiir','İlker Çalışkan']::text[], 8.5, '{"poet":"İlker Çalışkan","poet_slug":"i-lker-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/col-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaprak Dökümü', 'yaprak-dokumu-hulusi-kilic-c1vxy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kurumuş otlar üzerinde yapayalnız

Bir ağaca yaslanıp kalacaksın

Gözlerinde yaş,içinde burukluk olacak

Ve her yirmibir aralıkta

Yaprak dökümünü yaşayacaksın...

Senin içinde hep sonbahar rüzgarları,

Bende ise fırtınalar kopacak! 

Başkalarının kolunda yürüyeceksin

Nil yeşili gelinliğinle...

Üzerine savrulan konfeti değil

Bana yaşattığın fırtınanın döktüğü

Solgun yapraklar olacak...

O gün gülüm; 

Gözünde bir damla yaş,içinde hüzün

Elinde bir kuru yaprak olacak...', 'Kurumuş otlar üzerinde yapayalnız Bir ağaca yaslanıp kalacaksın Gözlerinde yaş,içinde burukluk olacak Ve her yirmibir aralıkta Yaprak dökümü...', ARRAY['Türk Edebiyatı','Şiir','Hulusi Kılıç']::text[], 8.5, '{"poet":"Hulusi Kılıç","poet_slug":"hulusi-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yaprak-dokumu-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değmez Üzülmene', 'degmez-uzulmene-suleyman-yavuz-m10jg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne varsa aşka dair

Bitti bunu bil

Unuttum ben seni

Bilirim üzer acıtır

Bu seni

Ama anlamalısın beni

Çünkü unuttum seni

Ve bilmelisin ki

İnan aşk bitince

Çekilmez oyunları

Kırmaktansa her an birbirini

Terk etmektir en iyisi

Şimdi ben yaptım

Unuttum seni

Sıra sende unut beni

Ve de ki kendine

Bir rüya gördüm

Başı sonu belli olmayan bir rüya

Ağlayarak bitti işte

Uyanınca ise unuttum de 

Kendi kendine

Ve üzülme artık

Değer mi  ben gibisine..', 'Ne varsa aşka dair Bitti bunu bil Unuttum ben seni Bilirim üzer acıtır Bu seni Ama anlamalısın beni Çünkü unuttum seni Ve bilmelisin ki İnan...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Yavuz']::text[], 8.5, '{"poet":"Süleyman Yavuz","poet_slug":"suleyman-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/degmez-uzulmene-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Yaşattığın', 'bana-yasattigin-hulusi-kilic-4nv9k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şimdi senden uzaklarda

Yapayalnız ne haldeyim; 

Bilmezsin sen,bilemezsin! 

Yüreğim kan ağlar oldu

İçim doldu,gülüm soldu; 

Görmezsin sen,göremezsin! 

Yollarıma karlar doldu

Gözyaşlarım kan oldu

Umutlarım hep yok oldu; 

Sevmedin sen,sevemedin!', 'Şimdi senden uzaklarda Yapayalnız ne haldeyim;  Bilmezsin sen,bilemezsin!  Yüreğim kan ağlar oldu İçim doldu,gülüm soldu;  Görmezsin sen,gör...', ARRAY['Türk Edebiyatı','Şiir','Hulusi Kılıç']::text[], 8.5, '{"poet":"Hulusi Kılıç","poet_slug":"hulusi-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bana-yasattigin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdiğim', 'sevdigim-ramazan-kayak-crxio', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevdiğim

Açmadım bir daha 

Kapısını gönül evimin

Bahçesini öyle bıraktım 

  Bıraktığın gibi 

                   Sevdiğim

Biliyorum

Çoktan solmuştur

O çok sevdiğin kırmızı karanfiller

Artık sevinç yok orda

Şimdi

Mezarlık sensizliğindedir

Susuz topraklar gibi

Filizlenen bir şey kalmamıştır 

Hazana dönmüştür orda zaman

Yaprakları dökülmüştür umutlarımın

Mevsimlerden habersizdir orda günler

Sensizlikte yaşam nasıldır

Bilemezsin 

      Sevdiğim

Nasıl geçer günler

Sabahlar kaç gözle beklenir

Umutlar nasıl bir,bir yok olur

Yaşama sevinci nasıl biter 

                             Bilemezsin

Öylesine

Düşkün ve tutkundum sana

Senle yaşamıştık baharları

Beraber ıslanmıştık yağmurlarda

Candan sevilmeyi sende öğrenmiştim

Dikenli yolları senle aşmıştım

Yoksulluğa haksızlığa direnmeyi

El ele kenetlenmeyi senle başarmıştım

Umutla sabır etmeyi

Kavuşmayı özlemlerin ardından

Hasretle kucaklaşmayı 

              Öğretmiştin bana

Sevdiğim

Beni zamansız bırakıp gittin

Ne vardı ötelerde beni terk etin 

Kayıp etmişim her şeyi sensiz

Sabrın halkaları kopmakta içimde

Umutlar bırakıp gitmiş 

Azap nehir ine kapılmış bedenim

Seni arıyorum

                  Yoksun

Kendimi arıyorum bulamıyorum 

Tutunacak bir dalım kalmadı

Savruluyorum

          Bedenimdeki bu kasırga ile

Öylesine terk etinki giderken

Beni de götürmüş gibisin

                      Sanki yokum ya

Ben senin hasretine 

         Yokluğuna dayanamam

Ya buralardan giderim

Ya peşinden gelirim 

                      Sevdiğim….', 'Sevdiğim Açmadım bir daha  Kapısını gönül evimin Bahçesini öyle bıraktım    Bıraktığın gibi                     Sevdiğim Biliyorum Çoktan so...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Kayak']::text[], 8.5, '{"poet":"Ramazan Kayak","poet_slug":"ramazan-kayak","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/sevdigim-77-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceler', 'geceler-hulusi-kilic-0rjpy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Anlamak olanaksız geceleri...

Gecelerde değil mi; 

Sevdiklerimizden ayrılışımız,

Umutsuzluklara düşmemiz...

Ve kapkara dört duvar içinde

Kendi başımıza kalmamız; 

Milyarlarca insana rağmen.

Ama yine de

O gecelerde değil mi; 

Ayrı kaldığımız yerleri,

Kavuşamadığımız insanları

Düşleriz saatler boyu...

Geceler!', 'Anlamak olanaksız geceleri... Gecelerde değil mi;  Sevdiklerimizden ayrılışımız, Umutsuzluklara düşmemiz... Ve kapkara dört duvar içinde Ken...', ARRAY['Türk Edebiyatı','Şiir','Hulusi Kılıç']::text[], 8.5, '{"poet":"Hulusi Kılıç","poet_slug":"hulusi-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/geceler-125-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ekinoks', 'ekinoks-duygu-dinc-yj69b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir akşamdaymış umut

Bir şiirdeymiş hüzün

Mutluluk heryerdeymiş

Gözleri kapamak yersizmiş

Bir varmış bir yokmuş

Ama evvel zamandaki özlenen günlerin

Gelecek zamanda yaşanması meçhulmuş

Gözlerini kısmış deniz

İçini çekmiş güneş

Karmakarışıklık düzenmiş meğer…

İçinden gelmeliymiş

Kahkaha da, hıçkırık da…

Ağlamış

Yokmuş sebebi aslında

Uykusuzmuş gözleri

Yorgunmuş dizleri

Boşaymış sözleri…

Yürümeliymiş

Biliyormuş

Ama bazen bilmek yetmiyormuş

Solgunmuş yüzü

Yaşanmışlıklar hastalıkmış

Geçmiş

Ama her geçmiş

Gelecekte açılacak bir kapının anahtarıymış

Atamazmış ki geçmişini

Yine biliyormuş

Ve yine elinden bir şey gelmiyormuş

Üşümüş

Elleri üşümüş

Gözleri üşümüş

Sözleri üşümüş

Isınacak bir kelime

Sıcak bir kalem bulamıyormuş

Yine bekleme gelmiş

Yine yaşanacaklar

İstediğinden daha uzaktaymış

Uzanıp yakalamak istediklerine

Günlerce yürüyüp ulaşabilirmiş

Zormuş

Ama bu karşılaştığı ilk zor değilmiş ki…

Ne zorlar görmüş

Kendini bilmeden

Kişisel karar veremeden…

Bazen ne zor oluyormuş yaşamak

24 saat

“Ölsem daha mı iyi ”düşüncesi

Bir gülücükte

Bir öpüşte

Hayatı arama gafleti…

Bazen düşünmek

Yaşamaktan daha zormuş

Kuytuymuş

Köşeleri de

Kenarları da…

Ekinoks…

Yalanmış…

Hiçbir zaman

Gündüz geceye eşit olmamış

Geceler hep uzunmuş

Bir ömür kadar uzun

Düşünerek geçermiş geceler

Gündüzlerse muhabbetle…

Bir gemi yapmış umuttan

Karanlıktan aydınlığa

Yürü demiş

İstersen uçak olabilirsin

Gemi bile gülmüş geçmiş

Umutlar bazen

Sadece kendinin inanabileceğin yalanlardır

Farkındaymış

Acı olan buymuş…

Bir sigara daha yakmış

Ve bir gemi daha yakmış hayatından

Kendini taşıyan…

Umutsuzlukmuş yiyip bitiren kendini

Yine biliyormuş

Ve yine elinden gelen bir şey yokmuş…

Yummuş gözlerini

Geceyi aranmış

Gündüz ise

Yanıbaşındaymış…

Ellerini kaldırmış

Tanrıya yakarmış

“Sonsuza kadar mutlu olayım”

Ama bilmiyormuş

Mutsuzluksuz mutluluk

Bir hiçmiş…

Her mutluluğun tadını alabilmek için

Bir parça mutsuzluk şartmış

Düşünmüş

Hep yaptığı şey…

Kendinden nefret etmiş

Mutluluğu alkolde aradı diye

Sarhoşluk çözümdür

Ama geçici bir süre için…

Ona daha kalıcı bir çözüm lazımmış

Ve yıllardır yapması gerekeni yapmış:

Kendiyle barışmış…

Biliyormuş

Başından beri biliyormuş

Ve ilk kez elinden gelen bir şey varmış

Şükran duymuş

Ellerini tekrar kaldırmış

“Tanrım

Seni

Ve kendimi seviyorum

İyi ki varsın…”

Rahatlamış

Dostlarını düşünerek

Sevenlerini düşünerek

İntihardan vazgeçmiş

Yaşamalıymış

Kendisi için

Etrafındakiler için…

Bakmış

Tek hayat kendisininkiymiş

İlgilenmesi gereken…

10.12.05', 'Bir akşamdaymış umut Bir şiirdeymiş hüzün Mutluluk heryerdeymiş Gözleri kapamak yersizmiş Bir varmış bir yokmuş Ama evvel zamandaki özlenen ...', ARRAY['Türk Edebiyatı','Şiir','Duygu Dinç']::text[], 8.5, '{"poet":"Duygu Dinç","poet_slug":"duygu-dinc","theme":"Türk Şiiri","is_hero":false,"total_lines":119,"source_url":"https://www.antoloji.com/ekinoks-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Resim', 'resim-suleyman-yavuz-u7qv7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir ev resimi çizdim

Bir yanı göl kıyısında 

Bir yanı dağ yamacında

Kiremitti çatısı

Ahşaptı yapısı

Gül doluydu bahçesi

Ormandı bir yakası

Tam ortasındaydı güzelliklerin

Cıvıl cıvıldı herşeyi

Patikaydı yolu

Eşsiz güzellik dolu

Sağı ve solu

Herşey tastamamdı

Ben vardım resimde 

Eksik ise sendin

O çerçevede

Ve giremeyeceksinde

Çünkü ben sensiz

Yalnız mutluyum

Bozma gelipte resmimi

Yaşları indirme

Kanatma kalbimi yine', 'Bir ev resimi çizdim Bir yanı göl kıyısında  Bir yanı dağ yamacında Kiremitti çatısı Ahşaptı yapısı Gül doluydu bahçesi Ormandı bir yakası T...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Yavuz']::text[], 8.5, '{"poet":"Süleyman Yavuz","poet_slug":"suleyman-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/resim-67-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalem Kağıttan Utanır, Ben Gözlerinden', 'kalem-kagittan-utanir-ben-gozlerinden-melih-coskun-ra83b', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kalem kağıttan utanır 

Ben gözlerinden.

Ne zaman ağzımı açacak olsam 

Dilime dolanır bütün kelimelerim 

Ne zaman bakacak olsam gözlerine 

Yarım bırakıp kaçarım yazdığım şiirleri

Kaç deniz kurur

Kaç garip yürek bezer canından 

Kalem direnir yine de

Tek mısra vermez mavi kanından

Adının hiçbir harfi olmadan

Yazdım en güzel dizelerimi 

Sonra unutup eşsiz sandığım güzelliğini 

Delice bağlandım 

Sensiz geçirdiğim her bir anıma. 

İki kişilik yalnızlık yok 

İnatla yalanlıyor bunu bütün cümlelerim

Yalnız kalabalıklar 

Sadece ucuz aşk romanlarında. 

Kendimden çıktığım bütün yolculuklar 

Sana varıyor şimdi sadece

Yıllardır yürüdüğüm caddelerde kayboluyor 

Beynimin sol yarısı, 

Seni bulduğum her adreste 

Kendi hüviyetimi kaybediyorum...

Şimdi beni sensizliğine aşık ettin ya 

Artık ne seninle yapabiliyor yüreğim

Ne de sensiz...

2005', 'Kalem kağıttan utanır  Ben gözlerinden. Ne zaman ağzımı açacak olsam  Dilime dolanır bütün kelimelerim  Ne zaman bakacak olsam gözlerine  Ya...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/kalem-kagittan-utanir-ben-gozlerinden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*yaşıyorsun*', 'yasiyorsun-ramazan-ates-hinyx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir yiğittin, tüm dünyaya hükmeden,

Bir bozkurttun, esarete düşmeyen.

Bir liderdin, hiç gaflete düşmeyen.

Yaşıyorsun, gönüldesin, kalptesin.

Başbuğ oldun, Bozkurtların önünde,

Ülkü dedin, ülkücüler peşinde.

Yılmadın sen, zindanlara girdin de,

Yaşıyorsun, gönüldesin, kalptesin.

Tüm dünyada bilge lider sendin sen,

Türk Dünyası seni sevdi yürekten.

Yalnız sendin onlara destek veren,

Yaşıyorsun, gönüldesin, kalptesin.

Vatan dedin, bayrak dedin, din dedin.

Sen ömrünce verdiğin sözde durdun,

Türk olanlar seni nasıl unutsun? 

Yaşıyorsun, gönüldesin, kalptesin.

Bekçi oldun, bu vatana, bu yurda,

Yedirtmedin onu, çakala, kurda,

Hainler hiç sevinmesinler boşa,

Yaşıyorsun, gönüldesin, kalptesin.

Zaman oldu zindanlara koydular,

Zaman oldu sana muhtaç oldular.

Bozkurtların senden ilham aldılar,

Yaşıyorsun, gönüldesin, kalptesin.

Bu gün yoksun, madden sen aramızda,

Unutmadık, sen varsın aklımızda.

Başbuğ sensin, yine Türk Dünyası’nda.

Yaşıyorsun, gönüldesin, kalptesin.

Bozkurtlarız, sana kalpten bağlıyız,

Dün nasılsa, bugün yine aynıyız.

Unutmak yok, çıkmadıkca canımız.

Senin sevgin çok büyük ve çok derin,

Yaşıyorsun, gönüldesin, kalptesin.

Ramazan Ateş/Enschede-04.04.1998', 'Bir yiğittin, tüm dünyaya hükmeden, Bir bozkurttun, esarete düşmeyen. Bir liderdin, hiç gaflete düşmeyen. Yaşıyorsun, gönüldesin, kalptesin....', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/yasiyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pusulamsın', 'pusulamsin-hatice-bediroglu-boh2s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'En mütevazı yemek bile

Şölene dönüşüyor 

Bir başka akıyor 

Suyun lezzeti 

Hep yeşil de kalıyor 

Yapraklarım 

Görünüyor dışarıdan

Yüreğimin atışları

Anlamıyorum ki

Nasıl geçtiğini günlerin

Sana hiç doyamadan

Hızla uçuyor zaman 

Gözüm, elim, yüreğim 

Sıcacık sabah güneşim 

Masmavi deryam 

Gerçeğim 

Düşlerim

Sonu yok bu hikâyenin

Pusulamsın 

Her zaman

Sevdayı gösteren

'' Düş Kuruyor Gece '' adlı kitabımdan - Ocak 2008 -

www.haticebediroglu.net', 'En mütevazı yemek bile Şölene dönüşüyor  Bir başka akıyor  Suyun lezzeti  Hep yeşil de kalıyor  Yapraklarım  Görünüyor dışarıdan Yüreğimin a...', ARRAY['Türk Edebiyatı','Şiir','Hatice Bediroğlu']::text[], 8.5, '{"poet":"Hatice Bediroğlu","poet_slug":"hatice-bediroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/pusulamsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gün Döneceğim', 'bir-gun-donecegim-hulusi-kilic-5loit', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben:Hulusi Kılıç! 

Uzaklarda da olsam eğer,

Bir gün; 

Sürem dolduğunda bu dünyada,

Cesedim ve ruhumla:Ben! 

Bu kara yazgılı topraklarda,

Bir meşe ağacının altında olmalıyım...

Kışın kardelenlerin sevincini,

Baharda nevruz ateşini,

Yazın ekinlerin bereketini,

Sonbaharda bağ bozumunu

Ve asırlar boyu; 

Bu insanların yazgısını paylaşmalıyım...

Ben:Hulusi Kılıç,

Bir gün...', 'Ben:Hulusi Kılıç!  Uzaklarda da olsam eğer, Bir gün;  Sürem dolduğunda bu dünyada, Cesedim ve ruhumla:Ben!  Bu kara yazgılı topraklarda, Bir...', ARRAY['Türk Edebiyatı','Şiir','Hulusi Kılıç']::text[], 8.5, '{"poet":"Hulusi Kılıç","poet_slug":"hulusi-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bir-gun-donecegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Götürmek', 'goturmek-sair-ferudun-9my6d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bakıyorum çevreme,

Götüren götürene....

Tüm bunları görünce,

İster istemez

Soruyorum,kendi kendime....

Ben ne götürdüm diye? ....

Bizim götüreceğimiz,

Yüce mevlamın 

Bize bahşettiği mide kadar....

Ama o da; 

Sadece bir öğün.....

Onun da gideceği yer malum....

Diyeceksin ki,

Kana karışanlar ne olacak? 

Eeeeee......

Müsaade ette

O kadar yaşayalım......', 'Bakıyorum çevreme, Götüren götürene.... Tüm bunları görünce, İster istemez Soruyorum,kendi kendime.... Ben ne götürdüm diye? .... Bizim götü...', ARRAY['Türk Edebiyatı','Şiir','Şair Ferudun']::text[], 8.5, '{"poet":"Şair Ferudun","poet_slug":"sair-ferudun","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/goturmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoksa Ne?', 'yoksa-ne-ramazan-ates-rs1wq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Duygular alemindeyim,

Yüregim kıpır kıpır.

Heyecan duyuyorum bazen,

Yoksa bunun adı, aşk mı ne? 

Nefes alamıyorum bazen,

Sesim titriyor konuşurken.

Soğuk soğuk terliyorum,

Yoksa bunun adı, aşkı mı ne? 

Dışarı bakıyorum, her yer tozpembe.

Belli bir hafiflik buluyorum kendimde.

Ayaklarım yere değmiyor, uçuyorum,

Yoksa bunun adı, aşk mı ne? 

Kar altında geziyorum çeketsiz,

Üşümüyorum, sanki yanıyor içim.

Sabaha kadar dolaşmak istiyorum öylece,

Yoksa bunun adı, aşk mı ne? 

Yemiyor, içmiyorum ben artık,

Uykuyu bile terk ettim nerdeyse.

Neşeliyim, mutluyum, gülebiliyorum bide,

Yoksa bunun adı, aşk mı ne? 

Çok değiştiğimin farkındayım,

Herşey tozpembe görünür oldu,

Artık ağlamıyorum, gülüyorum hemde,

Yoksa bunun adı, aşk mı ne? 

Sona mı geldim yoksa, ecel mi görünüyor gözüme? 

Ramazan Ateş/Enschede-31.12.1999', 'Duygular alemindeyim, Yüregim kıpır kıpır. Heyecan duyuyorum bazen, Yoksa bunun adı, aşk mı ne?  Nefes alamıyorum bazen, Sesim titriyor konu...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yoksa-ne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'S a y ı k l a m a l a r', 's-a-y-i-k-l-a-m-a-l-a-r-birsen-ates-32khj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sınırlarımı zorladım

hayat 

artık borçlu değilim

alacağım olsun bunca zaman

yağan yağmurlardan

ki arınayım 

uzun ve yorucu bir yol

iki arada bir nefes mola

yorgun bir ruh 

aykırı düşünceler

paranoid  sayıklamalarla

geçen yıllar

sınırlarımı zorladım

hayat

bu sefer kararlıyım

ardımda kalan izleri siliyorum

yeni doğan güne umut biriktiriyorum', 'sınırlarımı zorladım hayat  artık borçlu değilim alacağım olsun bunca zaman yağan yağmurlardan ki arınayım  uzun ve yorucu bir yol iki arada...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/s-a-y-i-k-l-a-m-a-l-a-r-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Kaybetmek', 'seni-kaybetmek-hulusi-kilic-x847n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bana,

Yollarda sürekli başım eğik

Ve neden dalgın yürüdüğümü,

Senin yanındayken

Neden suskun kaldığımı soruyorsun...

-söyleyemem gülüm-

Seni çok ama çok seviyorum; 

Oysa sen bunu bilmiyorsun...', 'Bana, Yollarda sürekli başım eğik Ve neden dalgın yürüdüğümü, Senin yanındayken Neden suskun kaldığımı soruyorsun... -söyleyemem gülüm- Seni...', ARRAY['Türk Edebiyatı','Şiir','Hulusi Kılıç']::text[], 8.5, '{"poet":"Hulusi Kılıç","poet_slug":"hulusi-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/seni-kaybetmek-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmesini bilen var mı.', 'sevmesini-bilen-var-mi-ercan-akbay-3j3xr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevmesini bilen var mı

   Sevilipte seven var mı

   Bu dünya da gülen var mı

   Bütün aşklar yalan olmuş.

   Kalpler kalplere

   Gözler gözlere

   Diller dillere

   Yalancı olmuş.

   Kerem gibi yanan var mı

   Aynı kalpte kalan var mı

   Hatırlayıp soran var mı

   Bütün aşklar yalan olmuş.

   Kalpler kalplere

   Gözler gözlere

   Diller dillere

   Yalancı olmuş...

                              M.Kürdi Şarkı

                              Beste ve Güfte...Ercan Akbay

                              TRT  1996 Haftanın Şarkısı Yarışması 1.lik Ödülü

                              Solistler.. Vedat Çetinkaya   Nesrin Körükçü.', 'Sevmesini bilen var mı    Sevilipte seven var mı    Bu dünya da gülen var mı    Bütün aşklar yalan olmuş.    Kalpler kalplere    Gözler gözl...', ARRAY['Türk Edebiyatı','Şiir','Ercan Akbay']::text[], 8.5, '{"poet":"Ercan Akbay","poet_slug":"ercan-akbay","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sevmesini-bilen-var-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Dilim Varmıyor*', 'dilim-varmiyor-ramazan-ates-5p18v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen bir ulu çınardın, gölgende biz büyüdük,

Gösterdiğin hedefe, inanarak yürüdük.

Sen ölmedin Başbuğum, kalbimizde yaşarsın,

Senin sevdan çok büyük, gönüllerden taşarsın.

Sen ki Türk Dünyası’na Önder olmuş kişisin,

Dünya Türklüğü lideri, Başbuğ Türkeş’isin.

Fikrin hep yaşayacak, sen orda rahat uyu,

Unutmak hainliktir, Ulu Çınar Başbuğ’yu.

Türk-İslam sancağını, bir ömür hep taşıdın,

Yılmadın, yıkılmadın, sen ömrünü harcadın.

Vatan millet ugruna, çok acıya katlandın,

Davanda haklılığı yaşarken ıpatladın,

Senin yerin boş kaldı, dolmayacak bir daha,

Senin gibi Başbuğ’u gelmeyecek bir daha.

Türk Dünyası arkandan büründü acılara,

Senin gidişin bile ne muhteşem manzara.

Milyonlar arkanda, tekbirlerle uğurlandın,

Bize Başbuğ’lugunu o günde ıspatladın.

Sana öldü diyemem, dilim varmıyor buna,

Seven Fatiha okusun, Başbuğ’umun ruhuna.

Ramazan Ateş/Enschede-2.6.1997', 'Sen bir ulu çınardın, gölgende biz büyüdük, Gösterdiğin hedefe, inanarak yürüdük. Sen ölmedin Başbuğum, kalbimizde yaşarsın, Senin sevdan ço...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/dilim-varmiyor-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Düşünmek', 'seni-dusunmek-hulusi-kilic-3g9fo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni düşünmek; 

Karlı zirvelerinde Torosların

Yaban güllerini düşlemek gibi,

Çıplak yamaçlarında Beydağı''nın

Ormanı düşlemek gibi,

Karanlık gecelerinde Niğde''nin

Güneşli günleri düşlemek gibi,

Kışlarında Güneydoğu''nun

Baharı düşlemek gibi,

Merdiveni dayamışken kırkına

Çocukluğu düşlemek gibi,

Dört duvarı arasında maphusun

Özgürlüğü düşlemek gibi,

Ateşleri arasında savaşın

Barışı düşlemek gibi birşey...', 'Seni düşünmek;  Karlı zirvelerinde Torosların Yaban güllerini düşlemek gibi, Çıplak yamaçlarında Beydağı''nın Ormanı düşlemek gibi, Karanlık ...', ARRAY['Türk Edebiyatı','Şiir','Hulusi Kılıç']::text[], 8.5, '{"poet":"Hulusi Kılıç","poet_slug":"hulusi-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/seni-dusunmek-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suya yazılan şiir', 'suya-yazilan-siir-samiha-i-kbal-f8te3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yumak yumak iptim bir bebeğin elinde

Ve çobanın elinde eğri büğrü bir değnek

Boyum boyumdan uzundu öğle vakitlerinde

Gelecek seheri özlerdim hep bu seherde

Sezinlerdim bir mezarın ninnilerini

En çok severdim o ilahi nağmeyi

Ki o geceyi gündüze çevirirdi

Sadece uyurum diyemem ki gecelerimde

Tükenmeyecek yazılarımı sulara yazdım

Alın yazımdan daha derin bir de asılsız

Seslenemedim bir türlü kulaklarıma,

O açmak bilmez goncaların gizeminde

Sadece yürürüm diyemem ki sokaklarımda

Bir kabusun en derin yerinde 

Unuturum geri kalan yarısını

Sayha sayha paketlenmiş ölümü

Ben gözyaşlarımla düşündüm

Ve ölümün penceresinden baktım

Ta uzaklara

Beyaz gölgemden habersiz.', 'Yumak yumak iptim bir bebeğin elinde Ve çobanın elinde eğri büğrü bir değnek Boyum boyumdan uzundu öğle vakitlerinde Gelecek seheri özlerdim...', ARRAY['Türk Edebiyatı','Şiir','Samiha İkbal']::text[], 8.5, '{"poet":"Samiha İkbal","poet_slug":"samiha-i-kbal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/suya-yazilan-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Krizi', 'sevgi-krizi-hulusi-kilic-03s8m', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çevremi sarıyorlarmış,

Engeller koyuyorlarmış,

Birleşip karşı çıkıyorlarmış,

Tehditler savuruyorlarmış...

Varsın olsun! 

Umrumda mı sanki? 

Seni kalbimden çıkaramayacaklar...', 'Çevremi sarıyorlarmış, Engeller koyuyorlarmış, Birleşip karşı çıkıyorlarmış, Tehditler savuruyorlarmış... Varsın olsun!  Umrumda mı sanki?  ...', ARRAY['Türk Edebiyatı','Şiir','Hulusi Kılıç']::text[], 8.5, '{"poet":"Hulusi Kılıç","poet_slug":"hulusi-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sevgi-krizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Savaş', 'savas-hulusi-kilic-h5lpl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Biliyor musun birtanem; 

Artık seni

Karanlık geceyle,

Yoğun sisle,

Şiddetli tipiyle,karla,

Soğuk günlerle,

Zorlu çamurlu yollarla,

Kanla,kavgayla; ölümle,

Ve yalnızlıklarla anımsar oldum.

Zorunluyum bunlara; 

Seni sevmenin savaşını veriyorum...', 'Biliyor musun birtanem;  Artık seni Karanlık geceyle, Yoğun sisle, Şiddetli tipiyle,karla, Soğuk günlerle, Zorlu çamurlu yollarla, Kanla,kav...', ARRAY['Türk Edebiyatı','Şiir','Hulusi Kılıç']::text[], 8.5, '{"poet":"Hulusi Kılıç","poet_slug":"hulusi-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/savas-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnat', 'i-nat-hulusi-kilic-p9387', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kar yağıyor bahara inat,

Sis çöküyor gözlere inat,

Geceler güneşe inat,

Yollar yolcuya inat,

Dağlar ovaya inat,

Somurtuyorlar gülene inat...

Ne oluyor bunlara? 

Hepsi de bize inat!', 'Kar yağıyor bahara inat, Sis çöküyor gözlere inat, Geceler güneşe inat, Yollar yolcuya inat, Dağlar ovaya inat, Somurtuyorlar gülene inat......', ARRAY['Türk Edebiyatı','Şiir','Hulusi Kılıç']::text[], 8.5, '{"poet":"Hulusi Kılıç","poet_slug":"hulusi-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/inat-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koşul', 'kosul-hulusi-kilic-uvwzb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hey sen! 

Aslan yelesi gibi saçlı,

Sarışın güzel kız...

Tenin

Bu kadar açık olmasaydı,

Ben de 

Başkasını sevmeseydim,

Kim bilir; 

Belki seni severdim...', 'Hey sen!  Aslan yelesi gibi saçlı, Sarışın güzel kız... Tenin Bu kadar açık olmasaydı, Ben de  Başkasını sevmeseydim, Kim bilir;  Belki seni...', ARRAY['Türk Edebiyatı','Şiir','Hulusi Kılıç']::text[], 8.5, '{"poet":"Hulusi Kılıç","poet_slug":"hulusi-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kosul-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimlik', 'kimlik-i-brahim-kilinc-bchzy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kimliğiyle derdi olanlar varsa

Bizleri bu işe karıştırmasın

Türk oğlu Türküz biz dünya yıkılsa

Çakalı bozkurtla yarıştırmasın

Türklük kimliğimiz, mührü dünyada

Aksini düşünen hayâl, rüyada

Ya da kem düşünür, aklı riyada

Sabrın da sınırı var, taşırmasın

Şan ile, şerefle devlet kuran Türk

Sizi bir yerlere seçip koyan Türk

Taşır bu sancağı en son kalan Türk

Gerçeği hayalle karıştırmasın

Oyunları bozup tarih yazan Türk

Haçlıya yıllarca mezar kazan Türk

Yarın asker olur bugün ozan Türk

İşi bu noktaya ulaştırmasın

Atılır ileri, bir daha dönmez

Gönlümüzde yanan bu ateş sönmez

Bu vatan bölünmez, bu bayrak inmez

Alt kimlik üst kimlik karıştırmasın', 'Kimliğiyle derdi olanlar varsa Bizleri bu işe karıştırmasın Türk oğlu Türküz biz dünya yıkılsa Çakalı bozkurtla yarıştırmasın Türklük kimliğ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Kılınç']::text[], 8.5, '{"poet":"İbrahim Kılınç","poet_slug":"i-brahim-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kimlik-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşayamam', 'yasayamam-hulusi-kilic-yk3h1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir gülün dallarında,kuşların kanadında,

Her nefes alışımda; anmadan yaşayamam.

Saçının bir telini,içten gülen yüzünü,

O güzelim yüzünü; öpmeden yaşayamam.

Şu sevdalı başımda,döktüğüm göz yaşımda,

Kalbimin atışında; duymadan yaşayamam.

Her adım atışımda,her gün seni karşımda,

Geceleri düşümde; görmeden yaşayamam...', 'Bir gülün dallarında,kuşların kanadında, Her nefes alışımda; anmadan yaşayamam. Saçının bir telini,içten gülen yüzünü, O güzelim yüzünü; öpm...', ARRAY['Türk Edebiyatı','Şiir','Hulusi Kılıç']::text[], 8.5, '{"poet":"Hulusi Kılıç","poet_slug":"hulusi-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yasayamam-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasihat [sevmeden sevilmeden sakın evlenme 2 ]Tüm bekarlara', 'nasihat-sevmeden-sevilmeden-sakin-evlenme-2-tum-bekarlara-ercan-akbay-itg0n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kötü söz söyleyen,dillere düşme

   Dalını hep kıran, ellere düşme

   İyi düşün öyle evlen güzelim

   Darda kalıp kara günlere düşme.

   Güzellikte geçer,şanda şöhrette

   Bütün iş bir ömür,sevebilmekte

   Öyle kolay değil,çekip gitmekte

   Kafeste kuş gibi,tellere düşme.

   Aşkının kıymeti,kadri bilinsin

   Vefadan bi haber kalplere düşme

   İyi düşün öyle evlen,güzelim

   Bir top ateş iken,küllere düşme.

   Varlıkta,bollukta,gün gelir biter

   Elinin tersiyle seni de iter

   Gençlikte gül gibi,sararıp gider

    İyi düşün öyle evlen güzelim....

                                   26.6.2003', 'Kötü söz söyleyen,dillere düşme    Dalını hep kıran, ellere düşme    İyi düşün öyle evlen güzelim    Darda kalıp kara günlere düşme.    Güze...', ARRAY['Türk Edebiyatı','Şiir','Ercan Akbay']::text[], 8.5, '{"poet":"Ercan Akbay","poet_slug":"ercan-akbay","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/nasihat-sevmeden-sevilmeden-sakin-evlenme-2-tum-bekarlara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Katlettik masumiyeti', 'katlettik-masumiyeti-guler-atas-a4svh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hiroşima da büyütemediğim çocuk

Senden sonra..........

Vietnamlı çocukları da büyütemedim

Utandırmak için insanlığı

Afganlı,  ıraklı çocukları yolladık yanına

Biliyorum ki...........

Üstünüze yağmur.... gibi ölüm döken eller

Bir gün tutarken çocuğunun elinden.

Dünyanın masumiyetini kurşuna dizdiği için..

Mutlaka utanacak ellerinden..

Küçücük dünyanın kocaman yürekleri...

Açlık ve ölüm mahkumu çocuklarım..

Ellerim suçlu.. okşayamadığı için yaralarınızı..

Belki / tırnak ucuyla dokunsam...

Alabilirim ruhunuzdaki acıyı...

Gözlerinizden akan

Kopan kolunuzun bacağınızın acısı değildi...

Dünyanın her herhangi bir yerindeki....

Annelerin babaların elleriydi....

Onların yürekleriydi ki... yakan sizi...

Yalnızca kendi çocuklarını severlerdi...

Hiroşimalı,  Vietnamlı, Afganlı, Iraklı,Somalili çocuklar

Bağışlamayın önceliklerimizi,

Bağışlamayın çelişkilerimizi

Bağışlamayın bizi.....

Şimdi ...kalkmalıyız hep birlikte...

Evlerimizi temizlemeliyiz...

Dünyanın bütün ışıklarını yakmalıyız

Karartılmış gecelerin üstüne..

Konuklarımız geliyor dostlarım...

Konuklarımız var bu gün...

Hiroşima dan,Vietnam dan, Afganistan dan,  Iraktan, Afrika dan

Açın kapıları.. uzatın ellerinizi... 

Halaylar çekeceğiz hep birlikte..

Utandırmak için...

İşgalci katilleri...... 

                                                            01/12/2004', 'Hiroşima da büyütemediğim çocuk Senden sonra.......... Vietnamlı çocukları da büyütemedim Utandırmak için insanlığı Afganlı,  ıraklı çocukla...', ARRAY['Türk Edebiyatı','Şiir','Güler Ataş']::text[], 8.5, '{"poet":"Güler Ataş","poet_slug":"guler-atas","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/katlettik-masumiyeti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sağ yanım acımasız kendine bile', 'sag-yanim-acimasiz-kendine-bile-guler-atas-16owc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne  sen  benden  gidiyorsun

Ne ben  açıyorum  kalbimin  kilidini

Kabus  gibi  bir  kızıl derili  büyüsüyle

Sönüyor  aramızdaki  yangın

Sağ  yanım  acımasız  kendine  bile.

Saldırgan, hırçın ,vahşi

Sahrada  karadul

Öbür  yanım  öyle  sakin  öyle  sende

Kocaman bir  duvar beni  ikiye  bölen

Topla  beni. çıkar  içimdeki  kabileleri

Bir  kez  daha  geldim,

Tut   iki  elimi  açığa  çıkar,

Karanlık  odalarda, korkutulmuş

Ne  varsa, beni  götüren  senden.

                                                          13/10/2004', 'Ne  sen  benden  gidiyorsun Ne ben  açıyorum  kalbimin  kilidini Kabus  gibi  bir  kızıl derili  büyüsüyle Sönüyor  aramızdaki  yangın Sağ  ...', ARRAY['Türk Edebiyatı','Şiir','Güler Ataş']::text[], 8.5, '{"poet":"Güler Ataş","poet_slug":"guler-atas","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sag-yanim-acimasiz-kendine-bile-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahkum', 'mahkum-cihan-kaya-hspv0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'SEVDİĞİNE MAHKUM OLMAYAN; 

ÖZGÜR DEĞİLDİR! ..

Not: Gayri ötesini yazamadım.......', 'SEVDİĞİNE MAHKUM OLMAYAN;  ÖZGÜR DEĞİLDİR! .. Not: Gayri ötesini yazamadım..........', ARRAY['Türk Edebiyatı','Şiir','Cihan Kaya']::text[], 8.5, '{"poet":"Cihan Kaya","poet_slug":"cihan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/mahkum-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YıLaN', 'yilan-asima-azra-yl6em', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sana dokunmayan yılan bil ki

bin yaşına girmeden daha

sokulacaktır ocağına...

Başını ezsen yıldıramazsın

koynuna almışsan bir defa

kapılacaksın tuzağına

ve alışacaksın kan kaybına! ...

Aralık Şiirleri/5

a.a', 'Sana dokunmayan yılan bil ki bin yaşına girmeden daha sokulacaktır ocağına... Başını ezsen yıldıramazsın koynuna almışsan bir defa kapılacak...', ARRAY['Türk Edebiyatı','Şiir','Asima Azra']::text[], 8.5, '{"poet":"Asima Azra","poet_slug":"asima-azra","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yilan-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toprağın Koynuna Girdiler', 'topragin-koynuna-girdiler-ercan-cengiz-864sa', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir uçtan bir uca, kenetlenir birbirine

Toprağın ezgisiyle düşenler

Düşenler ki kanlarıyla yarını gösterdiler

Seyit Rıza, Alişer...

İbrahim, Deniz, Mahir...

Mazlum, Hayri, Ağit, Kemal...

Bütünleştiler

Çarkın dişlilerinden kopan ezgilerle

Munzur''da, Fırat''ta, Dicle''de

Maltepe''de Cevahirle

Bütünleştiler... toprakla, suyla...

Tank, top, idam sehpalarındaki

Zayıflıktır zalimin gücü,

Yetmedi çağlayışına, yetmeyecek hewal.

Ayak altındaki beden silkiniyor artık

Doğrulup silkinmesi karanlığı ürkütür.

Ölümün izi vardır derin uykularda

Yaşamanın sırrı bugünlerde belirir

Çarkın dişleri arasında kalmış 

Bir ezgili yürek

Çekip alır rengini zalimin elinden.

Fırat''ın çağlayışına kattılar seslerini

Küllerinden doğanlar...

Süzüle süzüle patikalardan geldiler

Toprağa yayılıp kapladılar suyu

Berrak sular içinde halklar sofrasına

Yarınlara...

(Ezgilerde Kaldı Yüreğim 1.Kitap)', 'Bir uçtan bir uca, kenetlenir birbirine Toprağın ezgisiyle düşenler Düşenler ki kanlarıyla yarını gösterdiler Seyit Rıza, Alişer... İbrahim,...', ARRAY['Türk Edebiyatı','Şiir','Ercan Cengiz']::text[], 8.5, '{"poet":"Ercan Cengiz","poet_slug":"ercan-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/topragin-koynuna-girdiler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Tarihin Dipnotu', 'bir-tarihin-dipnotu-ercan-cengiz-9rxmj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir Tarihin Dipnotu

kaplumbağa gezerdi tendür kokusu altında 

meşenin yaprağından tenime girdiğinde 

kül renkli, kör olmuş duman kaplardı her yanı 

üşürdüm gözü yaşlı tutuşurdu orman

tepeler çıplak, meteriste keklik 

soyuma yönelmiş soysuz

çıplak kayaların çatırtısı gelirdi 

hışmından yanan toprağın yüzüne 

damarından darbe yemiş meşe ağacı 

Munzur''un yatağında uç verirdi 

şafağa çıkan ülkenin ezgisinde bir başka mevsim 

tarih notunu böyle geçecekti

sorgudaydılar, hücrede sürgündeydiler 

ataları gibi meşe diplerinde

nesilden nesile taşırılan mirasın derinliğinde 

muhasebesidir yaşanılan

(Ezgilerde Kaldı Yüreğim 1.Kitap)', 'Bir Tarihin Dipnotu kaplumbağa gezerdi tendür kokusu altında  meşenin yaprağından tenime girdiğinde  kül renkli, kör olmuş duman kaplardı he...', ARRAY['Türk Edebiyatı','Şiir','Ercan Cengiz']::text[], 8.5, '{"poet":"Ercan Cengiz","poet_slug":"ercan-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bir-tarihin-dipnotu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmiyorum', 'bilmiyorum-yahya-ozcan-1pfkh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Karmakarışık bir yoldayım

Sırtımda koskoca bir kaya

Yaşıyor muyum yoksa öldüm mü

Bilmiyorum…? 

Saklanmalı mıyım bir yerlerde

Yoksa çıkmalımıyım ortaya,

Ruhumun tüm çıplaklığıyla

Buradamıyım yoksa değimliyim

Bilmiyorum…? 

Kaç cinayet işlemeliyim

Kaç şarjör boşaltmalıyım,

Kalleşliğin ve kardeşliğin beynine

Ne zaman, nerde, nasıl ölmeliyim

Bilmiyorum…? 

Kazanmak mı daha kolay

Yoksa kaybetmek mi

Sevmek mi daha kolay

Yoksa çekip gitmek mi

Bilmiyorum…? 

Hangi sanat hangi edebiyat

Tercüme eder beni.

Kimin bedeni söndürür

İçimdeki bu ateşi

Karanlıklar içindeki ışıkmısın

Yoksa yüreğimdeki karanlık mı

Bilmiyorum…? 

Seni çok mu sevmeli

Yoksa nefret mi etmeli

Bilmiyorum…? 

Adın yalnızlık mı? 

Yoksa adını yalnızlığa mı yazmalı

Bilmiyorum…?', 'Karmakarışık bir yoldayım Sırtımda koskoca bir kaya Yaşıyor muyum yoksa öldüm mü Bilmiyorum…?  Saklanmalı mıyım bir yerlerde Yoksa çıkmalımı...', ARRAY['Türk Edebiyatı','Şiir','Yahya Özcan']::text[], 8.5, '{"poet":"Yahya Özcan","poet_slug":"yahya-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/bilmiyorum-63-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Munzur''un İki Yüzü', 'munzur-un-i-ki-yuzu-ercan-cengiz-dvppa', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Munzur''a patikadan gidilir hewal

hain pusular arkasında

nişangahlar,

tayyere, kobra

tank, top sesleriyle karışık 

köy yerlerinde kaçışan çocuklar

ağıtlar arasında

erkenden büyüyenler...

diğer yüzünde Munzur''un 

faşizmin o iğrenç kahkahası vardır

ihanete, bitirmeye

yol açılır

işbirlikçileriyle...

(Ezgilerde Kaldı Yüreğim 1.Kitap)', 'Munzur''a patikadan gidilir hewal hain pusular arkasında nişangahlar, tayyere, kobra tank, top sesleriyle karışık  köy yerlerinde kaçışan çoc...', ARRAY['Türk Edebiyatı','Şiir','Ercan Cengiz']::text[], 8.5, '{"poet":"Ercan Cengiz","poet_slug":"ercan-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/munzur-un-iki-yuzu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'a-Polemikçi', 'a-polemikci-mikdat-bal-0rj84', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dinledikçe insan bıkar dilinden

Yanlış bulur yanlış söyler, bu herif

Hep şikayet bir şey gelmez elinden

Yanlış bilir yanlış eyler, bu herif

Her zaman konuşur söz olsun diye

Demez okkalı söz, öz olsun diye

Senden beklediği koz olsun diye

Yanlış olur yanlış yeğler, bu herif

Gülerken yüzüne intikam güder

Her şeye devamlı itiraz eder

Ne seni bırakır ne kendi gider

Yanlış kalır yanlış eğler, bu herif

İşi gücü yoktur hep seni izler

Darbeyi vuracak fırsatı gözler

Bildiği taşıma manasız sözler

Yanlış alır yanlış bağlar, bu herif

Bal der siyah söyler senin beyazı

Kapatır gözünü çıkar avazı

Ne şehit ne gazi, bizim niyazi

Yanlış ölür yanlış ağlar, bu herif

Ozan Mikdadi', 'Dinledikçe insan bıkar dilinden Yanlış bulur yanlış söyler, bu herif Hep şikayet bir şey gelmez elinden Yanlış bilir yanlış eyler, bu herif ...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/a-polemikci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutsuz Aşk', 'umutsuz-ask-erol-korkut-v10qb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Cansız âlemin can pazarında

Acınası ciğer paremsin

Nasılda incittiler güzel kalbini

Amacı belirsiz gafil insanlar

Neden sanki sundular yalan rüyalar

Sana ne söylesem bilemiyorum

Enkazlar altında kalmış gibiyim

Nasıl çıkılır yolu bulamıyorum

İncinirsin diye soramıyorum

Seneler nasıl geçti bak bir hatırla

En güzel günlerimiz hayal oldular

Vaat edilen gün gelip geçtide

İncinirsin! Ne oldu diye soramıyorum

Yalnızlık garipmiş sonra anladım

Olsun ben seni sensizde yaşadım

Rüyalar hayaller bir bir peşine

Umutsuzda olsa seni aradım

Mabedi sen yaptım sende ağladım.', 'Cansız âlemin can pazarında Acınası ciğer paremsin Nasılda incittiler güzel kalbini Amacı belirsiz gafil insanlar Neden sanki sundular yalan...', ARRAY['Türk Edebiyatı','Şiir','Erol Korkut']::text[], 8.5, '{"poet":"Erol Korkut","poet_slug":"erol-korkut","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/umutsuz-ask-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzüldüğüm akşamdı', 'uzuldugum-aksamdi-elazigli-mustafa-kaya-kns02', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'üzüldüğüm akşamdı

ruhuma çöktü gölgeler

kimsenin görmediği

bir göğün altındayım

korkusuz kelimeler yazdım

senin gözlerine sunacağım

bir filmin akışı gibi

özgür ve rahat

kalbini dolduracağım…

Mustafa kaya

13.12.2005  /  tuzla

www.mustafakaya.net', 'üzüldüğüm akşamdı ruhuma çöktü gölgeler kimsenin görmediği bir göğün altındayım korkusuz kelimeler yazdım senin gözlerine sunacağım bir film...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/uzuldugum-aksamdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pamuk lifi olmak', 'pamuk-lifi-olmak-elazigli-mustafa-kaya-5yj89', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kaçıncı buruşturup attığım

ne yazdığımı bilmiyorum

bir yanda yüreğimdeki sancılar

bir yanda da,

kendime yabancılaşıyorum.

içimin aynası sanki

kül renkli bulutlar.

fırtınalı havada

bir pamuk lifiyim

elimde bir resmin

ölünceye kadar onu seyredeceğim….

Musafa kaya

13.12.2005 / kartal

www.mustafakaya.net', 'kaçıncı buruşturup attığım ne yazdığımı bilmiyorum bir yanda yüreğimdeki sancılar bir yanda da, kendime yabancılaşıyorum. içimin aynası sank...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/pamuk-lifi-olmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sedir', 'sedir-elazigli-mustafa-kaya-tmanx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'merak etmişsin

gözyaşı ve yalnızlık hücremi

binlerce alev,

sessizlik ve yalnızlık kaplı

bir oda,

duvarları kireç badanalı

üst üste kitaplar

tahta bir iskemle

küçük bir masa ve kağıtlar.

sabahı gelmez gecelerde,

uzanıp kaldığım

keten kaplı kerevit bir sedir.

çiçeği açmayan bir saksı

ve bakmaya korktuğum bir ayna.

eski bir kilim ve 

köşede

dualarıma sığındığım,

gündüzüm gecem

serili seccadem …

Mustafa kaya

13.12.2005 / kadıköy

www.mustafakaya.net', 'merak etmişsin gözyaşı ve yalnızlık hücremi binlerce alev, sessizlik ve yalnızlık kaplı bir oda, duvarları kireç badanalı üst üste kitaplar ...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sedir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erbil’den Karabağ’a', 'erbil-den-karabag-a-esat-erbil-p7gw3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Anlatma bana....

Özgürlük ne olduğunu 

Ben onu....

Uzun zamandan beri anlamışım 

Ama tadını,

Rengini hiçte.... bilmemişim 

Azerbaycan ah  Azerbaycan! ! ! 

Ne bir tuhaf olayda seninle tanıştım 

Bir Türkmen olarak 

Seni gönlümde sakladım 

Sanki yüz yıldan beri 

birbirimizle kardeş gibiyiz. 

Öykümüz bence 

Gizli bir destan olacak.

Allahım ne güzelmiş 

Bu karabağ insanları 

Yüzleri ak, gönülleri temiz.... 

Gök rengi gibi... maviliğe benzer

Gözlerinin rengine ey sevgilim.

Gel sarıl kollarıma

Gel yüzdür beni karabağ göllerinde

Eğer yoksada. 

Gezdir beni

O, cennet ormanlarında 

Çünkü..... asla

Ben kaybolmuşum, boğulmuşum 

Gözlerinin.. damla... damla 

Hasret..........selinde.', 'Anlatma bana.... Özgürlük ne olduğunu  Ben onu.... Uzun zamandan beri anlamışım  Ama tadını, Rengini hiçte.... bilmemişim  Azerbaycan ah  Az...', ARRAY['Türk Edebiyatı','Şiir','Esat Erbil']::text[], 8.5, '{"poet":"Esat Erbil","poet_slug":"esat-erbil","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/erbil-den-karabag-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şeref.. Ne dekektir?', 'seref-ne-dekektir-esat-erbil-ntuxm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şeref.... Hayattır 

Şeref.... Ölümdür 

Şerefle  yaşamak 

Bil hak yolumdur.

Ne mukaddestir

Şeref sözcüğü 

Anlamı büyük... Çokta pahalı 

Hayatı kapsar kimi anlarsa.

Şerefliler ....

Onu her zaman korur.

Her kim kayıp ederse 

Hayatı biter 

Ölüm demektir.

Şerefsizlerse....

Onu tanımaz.... 

Çocuk oyuncağı gibi 

Her gün kayıp eder 

Şerefe saygısı 

Asıldan yoktur

Çünkü kendini

Şerefsiz... Bilir.

Şeref... Güneştir

Şeref... Namusturö

Şeref... Her şeydir. 

Esat Erbil', 'Şeref.... Hayattır  Şeref.... Ölümdür  Şerefle  yaşamak  Bil hak yolumdur. Ne mukaddestir Şeref sözcüğü  Anlamı büyük... Çokta pahalı  Hayat...', ARRAY['Türk Edebiyatı','Şiir','Esat Erbil']::text[], 8.5, '{"poet":"Esat Erbil","poet_slug":"esat-erbil","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/seref-ne-dekektir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meşhur Erbil’im', 'meshur-erbil-im-esat-erbil-23qtx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Erbilimi süslendiren yüksek meşhur Kale’di,  

Birde sultan Muzaffer’in minaresi laledir,

Tarihlerde değeri var bütün yerden aladı,        

         Ataların yurdu olan serbest şanlı Erbil’ im,

          İnsanlığa kolun açar ölmez ünlü Erbil‘im,

Milletin uygarlığı da  örnek olmuş her yana,  

Bütün dünya varlığını değiştirmem  vatana,   

Satmam özgür toprağını bulanırsam al kana,  

          Ataların yurdu olan serbest şanlı Erbil’ im,

          İnsanlığa kolun açar ölmez ünlü Erbil ‘im,

İşgal oldu güzel şehrim yabancılar elinde,

Türkçülük için çalışan,engel durdu yolunda, 

Döndü giden soydaşlarım umutları dilinde,    

         Ataların yurdu olan serbest şanlı Erbil’ im, 

         İnsanlığa kolun açar ölmez ünlü Erbil’ im,

Esat  Erbil', 'Erbilimi süslendiren yüksek meşhur Kale’di,   Birde sultan Muzaffer’in minaresi laledir, Tarihlerde değeri var bütün yerden aladı,          ...', ARRAY['Türk Edebiyatı','Şiir','Esat Erbil']::text[], 8.5, '{"poet":"Esat Erbil","poet_slug":"esat-erbil","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/meshur-erbil-im-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimliğim', 'kimligim-esat-erbil-jd5c9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sormayın kimliğimi,

Sormayın benden,

Ne olduğumu? 

Yeter beni dinleyin,

Dilimi anlayın

Beni duydunuz mu? 

Ha....! ! Duymadınız mı? 

Yoksada ben lâlmıyım? 

Sözümü anlatabilmedim! 

Yada.....

Siz sağır mısınız 

Beni duymuyorsunuz? 

Öyleyse....

Onu çözmeye çalışacağım:

Ben bir Türkmen’im

Erbil Doğum''luyum

Kerkük Yandaşıyım

Kifir ile Tuzdan

Ayrı değilim

Tela fer, Dakuk ve Mendeli

Soydaşıyım

Soyum Türk...

Dinim İslam.....

Bütün dünya Türkleri ile

Kan kardeşiyim.

Not:

Kifri, Tuz, Telafer, Dakuk ve Mendeli Irak Türkmenlerin meşhur İlçeleridir.', 'Sormayın kimliğimi, Sormayın benden, Ne olduğumu?  Yeter beni dinleyin, Dilimi anlayın Beni duydunuz mu?  Ha....! ! Duymadınız mı?  Yoksada ...', ARRAY['Türk Edebiyatı','Şiir','Esat Erbil']::text[], 8.5, '{"poet":"Esat Erbil","poet_slug":"esat-erbil","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/kimligim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oyuncak Olma', 'oyuncak-olma-esat-erbil-qaspt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çalişma sinirsiz seni kırarlar

Habersiz kalırsan çetin vurarlar,

Doğru yola elbet engel kurarlar,

Bakma gül yüzlere gülüp oynıyor,	 		

Çevren çok bozuk ortam kaynıyor.	  		

 	Saygı gösterdim haddini aştı, 

Yakın doslar bile işimden çaştı,

Insanlık bilmeyen kalpleri taştı,

  Ağlamak gelmemiş biz ustalara,		

Her zaman ilaciz tüm hastalere.		

Aldanmam dünyada mülk ile caha,

Hasretim karşıdır inan yüz aha, 		

Bir gün isyan etmem yüce Allaha,

Yükümü taşırım sırtımdan atmam,	    

                           Türk soydan gelmişim dostumu satmam.				

Bir işi tutarsam doğru tutarım,

Gerginlik çıkmasın derdi yutarım,

Şayet birlik olsa yadı utaram,  

Doğru sözümüz bir, iki etmeyiz,

Davayı düşünüp boşa gitmeyiz.		

Esat  Erbil', 'Çalişma sinirsiz seni kırarlar Habersiz kalırsan çetin vurarlar, Doğru yola elbet engel kurarlar, Bakma gül yüzlere gülüp oynıyor,	 		 Çevre...', ARRAY['Türk Edebiyatı','Şiir','Esat Erbil']::text[], 8.5, '{"poet":"Esat Erbil","poet_slug":"esat-erbil","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/oyuncak-olma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vatan böyle mi sevilir?', 'vatan-boyle-mi-sevilir-mikdat-bal-n6bqo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne olacak bu halimiz

Vatan böyle mi sevilir? 

Kan ağlıyor ehalimiz

Vatan böyle mi sevilir? 

Bir beyanat bir kaç nutuk

Gerçekte çok şey unuttuk

Çalışmadık hep uyuduk 

Vatan böyle mi sevilir? 

Şehitleri unutmak mı? 

Katilleri hoş tutmak mı? 

İnsanları avutmak mı? 

Vatan böyle mi sevilir? 

Bölücüyle bir olup da

Halkı ikiye bölüp de

Buna da bir kulp bulup da

Vatan böyle mi sevilir? 

Mikdat der ki yalanlarla

İş yürümez pilanlarla

Utanın son olanlarla

Vatan böyle mi sevilir?', 'Ne olacak bu halimiz Vatan böyle mi sevilir?  Kan ağlıyor ehalimiz Vatan böyle mi sevilir?  Bir beyanat bir kaç nutuk Gerçekte çok şey unutt...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/vatan-boyle-mi-sevilir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz', 'beyaz-elazigli-mustafa-kaya-a9zhv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ahh..

şu göklerin altında

hüzün bulutlarını

ruhuma döken sevgilim.

yağmurlu geceme saplandın

yeniden

bir masa örtüsü gibi,

anıları

ayaklarımın altından çekilen.

geceye sarılışın

kar gibi 

beyaz bir gecelik.

aynadaki sensin.

seni kıskandım.

bir dağın erimesinden farksızım.

kalbime döktün duygularımı.

kelimelerin arasına saklandım,

hayalet kadar

hafif ve sessiz.

ahh…bir rüya ancak,

gözlerini

benim gözlerimde 

açacak...

Mustafa kaya

13.12.2005 / sarayburnu

www.mustafakaya.net', 'ahh.. şu göklerin altında hüzün bulutlarını ruhuma döken sevgilim. yağmurlu geceme saplandın yeniden bir masa örtüsü gibi, anıları ayaklarım...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/beyaz-154-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün ışığındasın şimdi', 'gun-isigindasin-simdi-guler-atas-1u77c', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mevsimsiz gitmiştin / bahardı...

Zamansız dönmek istiyorsun / kıştayız..

Aştım yalnızlığı........

bir sokak lambasının altında..

Bütün kirlerini örterek dünyanın..

Ayı aldım her gece koynuma...

Öptüm dudaklarından........

Sarıldım loşluğuna / içti içimi..

Her gece çekti seni içimden..

Kopardı  / canımı acıta acıta....

Açığa çıkardı karanlıkta kalan yerlerini..

Kalmamışsın ki.........

Bu akşam ay acıtmadı canımı..

Bandım seni..

Ay ışığı altında yağmur tanelerine..

Gün ışığındasın şimdi..', 'Mevsimsiz gitmiştin / bahardı... Zamansız dönmek istiyorsun / kıştayız.. Aştım yalnızlığı........ bir sokak lambasının altında.. Bütün kirle...', ARRAY['Türk Edebiyatı','Şiir','Güler Ataş']::text[], 8.5, '{"poet":"Güler Ataş","poet_slug":"guler-atas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gun-isigindasin-simdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğretmen', 'ogretmen-i-brahim-pataz-o28w7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dağlar arasında, ücra bir köye,

Bin bir güçlüklerle, varır öğretmen.

Yağmurda, tipide, yollarda yaya,

Bu ülkeye hizmet verir öğretmen.

   Bilir ki, artınca okuyan yazan,

   Herkes bir iş yapar, kalmaz, boş gezen,

   O zaman kurulur, mutlu bir düzen

   Ufkun ötesini, görür öğretmen.

Yararlı işlerde,  artınca yarış,

Kalpler sevgi dolar, ülkeler barış,

Emeli, umudu bu sona, varış,

Önder olur, önde yürür öğretmen.

   Eğiterek. Öğreterek herkesi,

   Cehaleti,  yok etmektir ilkesi,

   Söz konusu, olduğunda ülkesi,

   Ne yorulur, ne de, durur öğretmen.

Kendini unutmuş, görev aşığı,

İnsanlık beşiği, ilmin eşiği,

Çevresine yaymak için ışığı,

Alev alev  yanar, erir öğretmen.

   Alsın diye herkes, bilgiden payı,

   Şevk ile dolaşır, beldeyi köyü,

   Yapmak için yurdu,  dünkünden iyi,

   Geleceğe, mührün vurur öğretmen.

Aydınlık çığırda, bellidir, izi,

Bu günden, yarına, hazırlar bizi,

ELEMİ: Saygıyla selamlar sizi,

Herkes duyar, senle gurur öğretmen.

İbrahim PATAZ

     22/05/2004 ADANA', 'Dağlar arasında, ücra bir köye, Bin bir güçlüklerle, varır öğretmen. Yağmurda, tipide, yollarda yaya, Bu ülkeye hizmet verir öğretmen.    Bi...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Pataz']::text[], 8.5, '{"poet":"İbrahim Pataz","poet_slug":"i-brahim-pataz","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/ogretmen-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaderin Yolunda Çıktın Önüme', 'kaderin-yolunda-ciktin-onume-i-brahim-pataz-tator', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayatın yolunda çıktın önüme,

Oturdun özüme yer ettin beni.

Kalbimden yol bulup, girdin kanıma,

Kendine sevdalı yar ettin beni.

   Aşk bağladı ayağımı elimi,

   Hiç kimseye söyleyemem halimi,

   Bilmiyorum akil miyim deli mi? 

   Çözümü imkansız, sır ettin beni.	

Ben kendi halinde soğuk bedendim,

Aha kurban oldum, sana adandım,

Aşkın eli ile dal dal budandım,

Koydun ateşine kor ettin beni.

   Gölgen gibi adım adım izlerdim,

   Göremezsem, hasretinle özlerdim,

    Seni sevdiğimi senden  gizlerdim,

    Şimdi el aleme, der ettin beni.

Günüm, geleceğim, benim her şeyim,

Seninle çoğalıp gidecek soyum,

Böyle bir  Leyla’nın ben Mecnun’uyum,

Yollarında ahu zar ettin beni.

   ELEMİ der: başka hayal kuramam,

   Bu nasıl duygudur, karşı duramam,

   Neye baksam farklı bir şey göremem,

   Senden başkasına kör ettin beni.

İbrahim PATAZ

           24/01/2005 ADANA', 'Hayatın yolunda çıktın önüme, Oturdun özüme yer ettin beni. Kalbimden yol bulup, girdin kanıma, Kendine sevdalı yar ettin beni.    Aşk bağla...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Pataz']::text[], 8.5, '{"poet":"İbrahim Pataz","poet_slug":"i-brahim-pataz","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/kaderin-yolunda-ciktin-onume-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Iraklının Feryadı', 'iraklinin-feryadi-i-brahim-pataz-0ginu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu ne biçim uygarlıktır? 

Evim barkım yıkılıyor.

Özgürlük denip adına,

İnsan kanı dökülüyor.

   İşgal oldu topraklarım,

   Çiğnendi bütün haklarım,

   Elsiz kolsuz çocuklarım,

   Toprağa can ekiliyor.

Zalim girdi ülkemize,

Çoluk çocuk eze eze,

Teröristlik neyimize,

Kurşun bize sıkılıyor.

   İnsandır ortak adımız,

   Nedir sizin muradınız? 

   Arşa çıktı feryadımız,

   Bedenden ruh çekiliyor.

Her ne olsa da ırkımız,

Eşittik yoktu fakımız,

Zilleti çeken halkımız,

Şehirlerim yakılıyor.

   Gece gündüz üstümüze,

   Yağa dursun bomba füze,

   İlkel işkenceler bize,

   Başa çivi çakılıyor.

ELEMİ diyor ellerim,

Diyemem varmaz dillerim,

Ölümü kutsal bellerim,

Şeref namus yok oluyor.

İbrahim PATAZ

     08/05/2004 ADANA', 'Bu ne biçim uygarlıktır?  Evim barkım yıkılıyor. Özgürlük denip adına, İnsan kanı dökülüyor.    İşgal oldu topraklarım,    Çiğnendi bütün ha...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Pataz']::text[], 8.5, '{"poet":"İbrahim Pataz","poet_slug":"i-brahim-pataz","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/iraklinin-feryadi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buz Yangınlarındayım', 'buz-yanginlarindayim-evina-berfin-euo33', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'seni her özlediğimde, 

ben biraz daha sen oluyorum

her sen oluşumda 

seni daha çok özlüyorum 

özlemek yangınsa eğer, 

ben ayazlardayım 

güneşsiz sabahlarda gözlerini.. 

nefesini arıyorum bu koca kentte

yüreğimde buz yangınları 

yağmurlar biriktiriyorum kirpiklerimde

saclarım ellerine öksüz 

kar taneleri takıyorum her bir teline  

avuçlarımda yokluğun 

ve ben seni özlüyorum 

daha bir sen oldukça 

yoksun... 

sensizliğe üşüyorum

12 Aralık 2005', 'seni her özlediğimde,  ben biraz daha sen oluyorum her sen oluşumda  seni daha çok özlüyorum  özlemek yangınsa eğer,  ben ayazlardayım  güne...', ARRAY['Türk Edebiyatı','Şiir','Evina Berfin']::text[], 8.5, '{"poet":"Evina Berfin","poet_slug":"evina-berfin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/buz-yanginlarindayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'El Oldum', 'el-oldum-huseyin-sigirtmac-7ui10', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hasretlik ömrümü etti bin pare.

Engel çok arada bulamam çare.

Halimi anlamaz bildirsem yare.

Duygu deryasında git ve gel oldum.

Gönül isyan eder kavuşmak için.

Dizimde derman yok ulaşmak için.

Çok istedim ama değişmek için.

Ben bende değilim yare kul oldum.

Yarin hasretiyle ayıkmaz başım.

Bir filiz yeşertmez akan göz yaşım.

Tenhaları ettim yaren yoldaşım.

Aşkı sevda ile yanıp kül oldum.

Yarin olmadığı gurbet her diyar.

Sığırtmaç bu yüzden çeker gam, efkar.

Kavuşmaya engel aşılmaz dağlar.

Göz görmez, el ermez, yare el oldum.', 'Hasretlik ömrümü etti bin pare. Engel çok arada bulamam çare. Halimi anlamaz bildirsem yare. Duygu deryasında git ve gel oldum. Gönül isyan ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sığırtmaç']::text[], 8.5, '{"poet":"Hüseyin Sığırtmaç","poet_slug":"huseyin-sigirtmac","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/el-oldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Kuşu', 'gonul-kusu-mehmet-isikoglu-nr8h4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'GÖNÜL KUŞU

Havalarda uçar uygun dal arar 

Göklerin sultanı veremez  karar

Hürriyet zevkini sonsuz tadarken

Akıla gelmedik hayaller kurar.

Yüksekten seyreder her dala konmaz.

Ne kadar yalvarsan  sözüne kanmaz.

Usta bir avcının ani bakışı

Düşürür aşağı daha da onmaz

İşte bir havalı tatmış o anı

Yarası göğsünde acıyor canı

Bağlanmış kanatlar, uçmak imkansız.

Sessizce bekliyor acil dermanı

Olan olmuş kim anlar kuş dilinden

Hiç kimseler bilmez onun halinden

Tabipler hocalar bulamaz çare

Derman ancak avcısının elinden', 'GÖNÜL KUŞU Havalarda uçar uygun dal arar  Göklerin sultanı veremez  karar Hürriyet zevkini sonsuz tadarken Akıla gelmedik hayaller kurar. Yü...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Işıkoğlu']::text[], 8.5, '{"poet":"Mehmet Işıkoğlu","poet_slug":"mehmet-isikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gonul-kusu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gümüş Ebe Cevher Dede', 'gumus-ebe-cevher-dede-ali-kaybal-lkvbz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Köyün üstüne düşmeden günün ilk ışıkları

Horozlar bile ötmeden çıkardılar dışarı.

Günün doğuşunu seyre dalarlardı sabah erken

Kahvaltıyı yaparlar bir yandan horozlar öterken.

Cevher dedenin elinde bıçak söğüdü yontuyor

Süt sağacak gümüş ebe, elinde bakraç tutuyor.

Bardak bardak süt içmeyi çok sevdiğini biliyorlar

Küçük Ahmet uyanınca süpriz yapmak istiyorlar.

Koyunların ardı süre koşmak en büyük zevkiydi

Yemyeşil bir dünyada hep güzellik sahibiydi.

Güneş ışıkları cama düşmeye başlamıştı

Gözüne düşen ışıkla Ahmet''de uyanmıştı.

Gümüş ebe avucunun içine şeker almış

Ahmed''i görününce o an dede kala kalmış.

Bir iki damla göz yaşı süzülür sakalından

Gümüş ebe saçlarını okşuyordu ardından.

Oğullarından kalan tek hatıraydı Ahmed''i

Şefkat yoğrulan kalbinden acısı hiç dinmedi.', 'Köyün üstüne düşmeden günün ilk ışıkları Horozlar bile ötmeden çıkardılar dışarı. Günün doğuşunu seyre dalarlardı sabah erken Kahvaltıyı yap...', ARRAY['Türk Edebiyatı','Şiir','Ali Kaybal']::text[], 8.5, '{"poet":"Ali Kaybal","poet_slug":"ali-kaybal","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gumus-ebe-cevher-dede-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayram Olması', 'bayram-olmasi-ali-kaybal-amn80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bayram denince,

İçimi bir coşku kaplamıyor,

Ramazan da geçmesin,

Bırak, her gün orucumu tutayım,

İftar saatini bekler gibi,

Kapıdan gireceksin diye bekleyeyim,

Herkes iftar topunu,

Ha atıldı,

Ha atılacak, az kaldı,

Diye, koşturup beklerken,

Ben,

Gözlerim kapıda,

Ha vurdu, ha vuracak diye,

Kalbimin atışlarını dinleyeyim,

Son günüm arefe olsun,

Açlığa alıştı bu beden,

Suzusluğa alıştı bu ten,

Yalnız,

Yokluğuna alışamadı bu gönlüm,

Dursuz zaman,

Geçmesin artık sensiz bir an,

Son günün akşamında,

Saat 12''de dursun bütün saatler,

Bütün ihtişamıyla,

Gökyüzünde ay,

Etrafında yıldızlar dursun,

Gecenin karanlığında,

Bilir misin? 

Beni onlar avutacak,

Ertesi günü biliyorum,

Bana bayram olmayacak,

Herkes gidip gelecek,

Benim ruhumsa bomboş,

Herkes hatır soracak,

Benim gözlerim aranacak,

Zannedersin dünya loş,

Çünkü sen yoksun,

Keyfim,

Gönül zindanlarından dışarı çıkmayacak.', 'Bayram denince, İçimi bir coşku kaplamıyor, Ramazan da geçmesin, Bırak, her gün orucumu tutayım, İftar saatini bekler gibi, Kapıdan gireceks...', ARRAY['Türk Edebiyatı','Şiir','Ali Kaybal']::text[], 8.5, '{"poet":"Ali Kaybal","poet_slug":"ali-kaybal","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/bayram-olmasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylülde', 'eylulde-ali-kaybal-4iupu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yaprağını açar kırmızı, pembe,

Ateş düşürür gönülden gönüle,

Bilinmedik aşklar gizlidir gülde,

Güz gülleri gibi çık gel eylülde.

Ağaç yaprağını yere indirir,

Rüzgar önünde bir, bir sürüklenir,

Gönlümün sahibi çıkıp da gelir,

Yeni bir hayata başlar eylülde.

Rüzgarlar estikçe kollar sarılır,

Hayaller içinde aşka varılır,

Bir dünya kurulur, kalbe sığılır,

Seninle gelecek saklar eylülde.

Tarlalar sürülür, bağlar bozulur,

Sevgiler dikilir, tohum gömülür,

Rüzgarlar esse de güzel görünür,

Üzüm taneleri güler eylülde.', 'Yaprağını açar kırmızı, pembe, Ateş düşürür gönülden gönüle, Bilinmedik aşklar gizlidir gülde, Güz gülleri gibi çık gel eylülde. Ağaç yaprağ...', ARRAY['Türk Edebiyatı','Şiir','Ali Kaybal']::text[], 8.5, '{"poet":"Ali Kaybal","poet_slug":"ali-kaybal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/eylulde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Bahçesinde Dursam', 'gul-bahcesinde-dursam-ali-kaybal-b7koj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gül bahçesinde dursam, gönlüm alınmıyormuş,

Zevk vermiyor sözün, har olmazsa gönlümüzde,

Yâr yoksa, sırça köşkün olsun kalınmıyormuş,

Cennet olur viran, yâr oldukça sevgimizde.', 'Gül bahçesinde dursam, gönlüm alınmıyormuş, Zevk vermiyor sözün, har olmazsa gönlümüzde, Yâr yoksa, sırça köşkün olsun kalınmıyormuş, Cennet...', ARRAY['Türk Edebiyatı','Şiir','Ali Kaybal']::text[], 8.5, '{"poet":"Ali Kaybal","poet_slug":"ali-kaybal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gul-bahcesinde-dursam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabah Namazı-"hakikatın gözyaşları" Kitabından', 'sabah-namazi-hakikatin-gozyaslari-kitabindan-omer-ekinci-micingirt-jamlc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gök rayiha kokar zikreder sular 

Fecir delallenir sabah namazı

Zikir şükür fikir cezbe huşular 

Vakit hilâllenir sabah namazı

Aşığın aşkıdır fecirde hüzün 

Selatinler âh saflar tek dizin 

Mâziyle ağlaşın gidin bir gezin 

Mısra celallenir sabah namazı

Ulucami Fatih hû Eyüp Sultan 

Cıvıl cıvıl kuşlar efsunlu mekân 

Semavat bahçesi ravza-i rıdvân 

Ayyıldız allanır sabah namazı

Davete icabet gelmez nisaba

Yâr ''in mektubudur okunan sâbâ

Koş İsra sofrası taltif ashaba

Huşuyla ballanır sabah namazı

Ruha sürur verir kalplere huzur

Alınlar secdeden Mi’rac’a yürür

Toplanır melekler hazır bulunur 

Gönüller güllenir sabah namazı

Kalp ehli markatta aşkın vaazı 

Suskun güzellikler ruhumda sızı 

Lütfeyle Allah’ım affeyle bizi 

Ağuşlar dillenir sabah namazı

Şuur mevsimidir aklet vakti az

Hû hû sesleriyle eserken poyraz

Vuslat hasretiyle ağlaşsak biraz

Seher Bilâllenir sabah namazı', 'Gök rayiha kokar zikreder sular  Fecir delallenir sabah namazı Zikir şükür fikir cezbe huşular  Vakit hilâllenir sabah namazı Aşığın aşkıdır...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ekinci Micingirt']::text[], 8.5, '{"poet":"Ömer Ekinci Micingirt","poet_slug":"omer-ekinci-micingirt","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sabah-namazi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Okul Yolunda', 'okul-yolunda-ali-kaybal-bttny', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ekim ayı girince ben görürdüm hazanı,

Yeli dokunur, döker ağaç yaprağını,

Soğuğa aldırmadan, yüklenmiş çantasını,

Okul yolunda bekler, gönül sevdalısını.

Mutluluk duyuyorum ben, okulun yolunda,

Huzuru bulduğum yer, bir de senin kolunda.

Sevgiyle sahibini arıyor bakışların,

Köle ediyor beni, kapından çıkışların,

Belik, belik örülmüş, uzun siyah saçların,

Prenses tacı gibi olmuş toka takışların.

Seninle yürüyorum ben okulun yolunda,

Arayıp buluyorum aşkı senin kolunda.

Toplan zili çalınca, buz gibi oluyorum,

Kendimi senden uzak, kutupda buluyorum,

Teneffüs olsun diye fırlanıp dönüyorum,

Şavkı sende bulmasam, kor gibi sönüyorum.

Seninle koşuyorum ben okulun yolunda,

Seninle yaşıyorum, yanımda sen bulun da.', 'Ekim ayı girince ben görürdüm hazanı, Yeli dokunur, döker ağaç yaprağını, Soğuğa aldırmadan, yüklenmiş çantasını, Okul yolunda bekler, gönül...', ARRAY['Türk Edebiyatı','Şiir','Ali Kaybal']::text[], 8.5, '{"poet":"Ali Kaybal","poet_slug":"ali-kaybal","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/okul-yolunda-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşler Gibiyim', 'dusler-gibiyim-harun-kuscu-id9ov', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gülerken simada ince mimikler

Ben gönülden akan yaşlar gibiyim

Ruhumu kapladı sahte kimlikler

Beyhude yaşayan başlar gibiyim

Umut yalan çıktı sinemde acı

Dertlerim biterken başlıyor sancı

Sahipsiz bedende gönül kiracı

Bahara varmayan kışlar gibiyim

Boşluğa seslensem hicrandır yankı

Bekledim gelmedi öyle bir anki

Gecede yaşama gelmişim sanki

Sonu hüsran olan düşler gibiyim.

harun kuşcu

silifke /mersin', 'Gülerken simada ince mimikler Ben gönülden akan yaşlar gibiyim Ruhumu kapladı sahte kimlikler Beyhude yaşayan başlar gibiyim Umut yalan çıkt...', ARRAY['Türk Edebiyatı','Şiir','Harun Kuşcu']::text[], 8.5, '{"poet":"Harun Kuşcu","poet_slug":"harun-kuscu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/dusler-gibiyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tebrikler', 'tebrikler-fahrettin-selcik-og2fi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'T E B R İ K L E R 

,Kırsal kesimden geldin İzmire

Güveniyordun  öz benliğine,

Kesimin doğallığı vardı üstünde,

Buldun kendini muhasebeci pençesinde.

Gözlerin ışıl ışıl parlıyordu,

Güneş gibi ışın saçıyordu,

Bütün oklar üstüne çevrildi,

Birisinden de koruma geldi.

Hayata kiraz bahçesinden başlamak,

Bir yandan geçmişten kopmamak,

Tabi senin de hakkındır mutlu olmak,

Kolay değil hani boşluğunu doldurmak.

Allah vermiş fizik ve güzellik,

Hayat da olmaz her şey dört dörtlük,

Görülse de bazı şeyler eksik,

Yinede aranır yaşanır evlilik.

Tanrıdan dilerim isteklerini versin,

Arzu ve emellerini gittiğin yerde göresin,

Diliyorum doyuma ve mutluluğa eresin,

Tebrik için Fahrettin daha fazla ne desin? 

Temmuz  2005', 'T E B R İ K L E R  ,Kırsal kesimden geldin İzmire Güveniyordun  öz benliğine, Kesimin doğallığı vardı üstünde, Buldun kendini muhasebeci pen...', ARRAY['Türk Edebiyatı','Şiir','Fahrettin Selçik']::text[], 8.5, '{"poet":"Fahrettin Selçik","poet_slug":"fahrettin-selcik","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/tebrikler-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanayici', 'sanayici-fahrettin-selcik-rohmk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'S A N A Y İ C İ

anaySici  olduk diye övünürüz,hepimiz,

 Tabiî ki hakkımız,sıfırdan bu noktaya gelmişiz

Yoktan var ederek G.S.M hasıla yaratıyoruz,

İstihdam katkımızla iş ve aş dağıtıyoruz.

Hizmet için kurulmuş Odalarımız var,

Unvan için seçilmiş görevli bolluğu var,

Sanayici olarak siyasete giremiyoruz,

Politikanın beterini odalara taşıyoruz.

Sanayicilik fikir ve emek yoğun  bir iştir,

Mayası hammadde,sermaye ve emektir,

Devlete millete hasıla ve mal üretir

Maliyeye on başlıkta vergi  öder,para getirir,

Sanayici,devletin kadrosuz,maaşsız neferi,

Fabrika bizim değil aslında devletin yeri,

Kazanılan nemalar maliye den girer içeri,

Hata yapar kazanamazsan gel,ir iflas çemberi.

Ülkemizde  planlama,teşvik ve takdir yok,

Bürokrasi ve siyasette ahkam kesen çok,

Demek gerekir,biliyorsan gel de elini sok,

Bilmezler ki,halimiz nicedir, söyleyeyim:BOM BOK.

Fahrettin Selçik  12.12.2005 İZMİR

 E L K İ M A   T R A F O -İ Z M İ R', 'S A N A Y İ C İ anaySici  olduk diye övünürüz,hepimiz,  Tabiî ki hakkımız,sıfırdan bu noktaya gelmişiz Yoktan var ederek G.S.M hasıla yaratı...', ARRAY['Türk Edebiyatı','Şiir','Fahrettin Selçik']::text[], 8.5, '{"poet":"Fahrettin Selçik","poet_slug":"fahrettin-selcik","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sanayici-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyüteceğim Sevgimi', 'buyutecegim-sevgimi-huseyin-erdogan-khht0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sevgili şiirim

sensin benim hülyam

sensin benim bir tek dünyam

inan ki ömrüm boyunca 

hiç bitmeyecek sana sevdam

ah! şu anda keşke 

senin sımsıcacık yanında olsam,

güçlü kollarımla 

sımsıkıcasına seni sarsam sarsam

ölünceye değin

seni asla bırakmasam

senin yüreğine bir ırmak gibi 

durmadan sevgimi aksam

seni ömrünce 

sevda yağmurlarımda sırılsıklam ıslatsam

bil ki yaşadıkça

hayallerimde olsa da 

hiç bırakmayacağım senin o güzel ellerini

sahillerde yüreğimde gezdireceğim seni

her gittiğim yere götüreceğim şiirimi

fotoğraflarından ezberleyeceğim

her santimetre kareni

sevdikçe seveceğim seni

seninle dolduracağım içimi

günden güne daha da büyüteceğim sevgimi

                         12.12.2005

                       Hüseyin Erdoğan', 'sevgili şiirim sensin benim hülyam sensin benim bir tek dünyam inan ki ömrüm boyunca  hiç bitmeyecek sana sevdam ah! şu anda keşke  senin sı...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/buyutecegim-sevgimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdayla Gelen', 'sevdayla-gelen-babur-pinar-2bifx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kozmik bir aşk düştü uzak dağlara

Orada yalnızlğın göğsünde açıldı yara

orada ceylan orada kuş

zapt olunmaz kanın hışırtısını duydu

Serhat  Amed  Zaho ve Atruş

giydi halka biçilmiş ateşten gömleği

ve yüzyıllık korku

sürgün edildi çorak bozkırlarına dünya’nın

Bereketli topraklar

taşımaz oldu kurak zulmünü tiranın 

Ölümün soğuk duruşunu

sokmadı eşikten içeri bahar 

Gece ıssızlığı düş kırıklığı halkın

ve kardeş bıçağının ucundaki kına

merhem olmadı Fırat’ın aşk yarasına

Ovaların dinginliğini bağ bozumda

terk ederek başkaldırdığı uçurumda

kuşlar gibi özgür yaşamak 

sevdalısı olmadan kazanılamaz artık', 'Kozmik bir aşk düştü uzak dağlara Orada yalnızlğın göğsünde açıldı yara orada ceylan orada kuş zapt olunmaz kanın hışırtısını duydu Serhat  ...', ARRAY['Türk Edebiyatı','Şiir','Babür Pınar']::text[], 8.5, '{"poet":"Babür Pınar","poet_slug":"babur-pinar","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sevdayla-gelen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeniden Başlamak Ne Güzel', 'yeniden-baslamak-ne-guzel-babur-pinar-1xiwj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kıran görmüş sözler külünü

düş çanağına koy şairin

Sarsılır gece gündüz şiirin 

imge dalgasıyla gökyüzü

Dev makineler bir kitabı

hayata taşıyor yeniden

Misafir ediyor ashabı

sevda habercisi kardelen

Nasıl da değişiyor doğa

her mikro saniye her saat

Bir güne sığan her dakika

yeniden varoluyor hayat

Yaşadım diyebilmek ala

gitmek gönül rahatlığıyla 

İmgesel kuş dalgalarıyla

sarsılabilmek ömre bedel

Eline uzanırken bir el

güne merhaba demek iyi

Seninle ah kaçak sevgili

yeniden başlamak ne güzel', 'Kıran görmüş sözler külünü düş çanağına koy şairin Sarsılır gece gündüz şiirin  imge dalgasıyla gökyüzü Dev makineler bir kitabı hayata taşı...', ARRAY['Türk Edebiyatı','Şiir','Babür Pınar']::text[], 8.5, '{"poet":"Babür Pınar","poet_slug":"babur-pinar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yeniden-baslamak-ne-guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırıntı Şiirler (XIV)', 'kirinti-siirler-xiv-ozgur-celik-byrdi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ben seni kazanabilmek için

tüm kaybetmeleri göze almıştım...', 'ben seni kazanabilmek için tüm kaybetmeleri göze almıştım......', ARRAY['Türk Edebiyatı','Şiir','Özgür Çelik']::text[], 8.5, '{"poet":"Özgür Çelik","poet_slug":"ozgur-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/kirinti-siirler-xiv-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İntihar Ettim', 'i-ntihar-ettim-seyfettin-bilal-ozluk-7tsx7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevgim korkuyla beraber büyüdü içimde

Sevdikçe korktum

Korktukça daha çok sevdim

Er geç birilerini boğacaktı bu duygular biliyorum

Neden sonra farkına varıyor insan

Ayağına takılan bütün taşları 

Yoluna kendi döşediğinin..

Benim yarınlara inancım senden yüklüydü

Daha cesaretliydim

Planı çatılmamış yarınlara ektiğim umutlar

Er geç açacaktı biliyordum

Deli sevdalı çocuk yüreğinin

Nicelerinin uğruna kıyametler kopardığı

Değersiz değerlere sırt dönmüş güvenli saflığında

Bir sonsuzluk buldun kendine

Ve hayatımızın resmini çizdim duvarlarımıza

Sonra birden yeşil bir kentte

Ilık bir yaz gecesinde astın beni.

Sevdalı ömrümün dakikası beş para etmedi ödedim

Cümlelerim seni taşımaktan yorgun düştü

Son sözün ve son anın

Efendisi olmaya bilenmiş yüreğine yenildim

Geçmişten nefes alıp geçmiçe nefes verdim

Anılar kemirdi yüreğimi

Felç oldu hislerim

Zamanın çoktan dibe çöktüğü kum saatimin belinden

Tek bir saniye bile süzülmüyordu

Ters çevirmeye cesaretim yoktu

Çünki yeniden başlayacak bir hayatın

Korkağı olmuştum.

Aşkların sonunda hüzün vardır

Ya sen hüznü boğarsın yada o seni boğar

Ama birisi kanatlarını kırarsa eğer

Yaralı kuş rolünü soyunacağına

Yürümeyi denemelisin hayata dönmelisin

Bunları düşünebilmek bile kendime dönüşümdü

Ve sonunda infaz ediyordu içimde

O gece yüreğimdem sağ çıktıysan eğer

Ölen ben olurdum

O gece hayatın lekesiz bir anında

Seni intihar ettim

Şimdi katil benim! 

Artık gecemde bir boşluksun yavaş yavaş

Taze anıların altına gömülüyorum

Ve sana ait olduğunu sandığım herşeyin

Aslında bana ait olduğunu anlıyorum

Hiçbir duygunun tek ilhamı değilsin

Kendimi yeniden keşfettikçe seni kaybediyorum

Ve ufkuma sensizliği korkusuzca geriyorum.

Beni, bizle başbaşa bıraktığından beri

Tek duam bizden yana

Ya senin, benim gibi sevmen

Ya da benim senin gibi, beni bırakıp gitmen

Ama bize bırakmak yalnız sana yakışır....', 'Sevgim korkuyla beraber büyüdü içimde Sevdikçe korktum Korktukça daha çok sevdim Er geç birilerini boğacaktı bu duygular biliyorum Neden son...', ARRAY['Türk Edebiyatı','Şiir','Seyfettin Bilal Özlük']::text[], 8.5, '{"poet":"Seyfettin Bilal Özlük","poet_slug":"seyfettin-bilal-ozluk","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/intihar-ettim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdiğim Ağlattı Beni', 'sevdigim-aglatti-beni-yusuf-onder-bahceci-cdmmf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ayrılığı yıktı beni,

Sokaklara attı beni,

Seven dostlar üzülmesin,

Sevdiğim ağlattı beni.

Yıllar oldu arıyorum,

Her geçenden soruyorum,

Gelmeyecek biliyorum,

Sevdiğim ağlattı beni.

Kalbim kırık yaralıyım,

Derdi dağlar sıralıyım,

Şimdi bilmem nereliyim,

Sevdiğim ağlattı beni.....', 'Ayrılığı yıktı beni, Sokaklara attı beni, Seven dostlar üzülmesin, Sevdiğim ağlattı beni. Yıllar oldu arıyorum, Her geçenden soruyorum, Gelm...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevdigim-aglatti-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'a-Arkama bakmadan döner giderim', 'a-arkama-bakmadan-doner-giderim-mikdat-bal-f2j5m', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Unuttuysan eğer, verdiğin sözü

Arkama bakmadan döner giderim

Yanlış bende derim bağrımda sızı

Kimseyi yakmadan yanar giderim

Sevmezsen aşkıma etme hakaret

Madem sevmiyorsun söyle tekrar et

Bir tanem diyordun hadi inkâr et

Dediğin yalana kanar giderim

Gözyaşlarım seller gibi akıyor

Yârim bana eller gibi bakıyor

O bakışlar çöller gibi yakıyor

Yakmaz artık yakmaz, donar giderim

Seni unutmamı isteme benden

Kahrolurum bana böyle demenden

Gidiyorum ama ayrılmam senden

İsmini gönlümde anar giderim

Hasretin bağrıma kor gibi düşer

Buna can dayanmaz ruh bile pişer

Artık bundan gayri gözlerim şişer

Böyle vefasızı kınar giderim

Ozan Mikdadi', 'Unuttuysan eğer, verdiğin sözü Arkama bakmadan döner giderim Yanlış bende derim bağrımda sızı Kimseyi yakmadan yanar giderim Sevmezsen aşkım...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/a-arkama-bakmadan-doner-giderim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhtiyacım var sana', 'i-htiyacim-var-sana-tulay-i-cen-pghlr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni yaşamak  günlerce,

Geleceksin diye beklemek.

Esen rüzgarda,doğan güneşte.

Seni bulmak istiyorum.

Yağmurun sesinde seni duymak,

Seni yaşamak günlerce.

Acını gömmek mezara,

Üstüne toprak atmak isterim,

rahatlıyacaksan.

Kalbimdeki acı toprakta  atsam dinmeyecek

Seni hep anacak hatırlayacak

Sevgim mezara kadar.

Yüreğimdeki seni asla gömmeyeceğim.

Yıllar gecsede hep orda kalıcaksın.

Sana sitem etsemde, isyanda etsem,

Gözlerindeki bakış silinmeyecek 

gözlerimde.

Sen yaşayacaksın,ben yaşadıkça

Sevgim mezara kadar mezarden sonra bile.

01/05/1994', 'Seni yaşamak  günlerce, Geleceksin diye beklemek. Esen rüzgarda,doğan güneşte. Seni bulmak istiyorum. Yağmurun sesinde seni duymak, Seni yaş...', ARRAY['Türk Edebiyatı','Şiir','Tülay İçen']::text[], 8.5, '{"poet":"Tülay İçen","poet_slug":"tulay-i-cen","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ihtiyacim-var-sana-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tefekkür-il Mevt', 'tefekkur-il-mevt-abdullah-odabas-ztlx3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gel gönül biraz da böyledüşünek,       	

Bu başa gelecek nice haller var,        	

Bir gün edeceğiz cihandan sefer,        	

Gidip de gelinmez nice yollar var.    

O yola giderken azık almalı,            	

Arapça söylerler, dilden bilmeli,       	

Suali kabire cevap vermeli,             	

Elleri çomaklı nice kullar var.         	

Ameli salihin var ise senin,            		

Toprakta çürümez yatsan da tenin,       	

Cennet bahçesinden bir bahçe yerin,     	

Zümrütten budaklı nice dallar var.      	

Yok ise amelin haller yamandır,

Tükenmez bitmez hayli zamandır,

Cehennem çukuru kara dumandır,

Azabı elim nice haller var.

Mevla cümlemize etsin inayet,

Kurtarıp gafletten versin hidayet,

Habib-i zişanım kılsın şefaat,

Şeriat harici nice haller var.

Meftuni aklını alsanya başa,

Yazıken yolunu uğratma kışa,

İsterisen elli-yüz sene yaşa,

Cihanda ebedi kalmış kimler var.', 'Gel gönül biraz da böyledüşünek,       	 Bu başa gelecek nice haller var,        	 Bir gün edeceğiz cihandan sefer,        	 Gidip de gelinm...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Odabaş']::text[], 8.5, '{"poet":"Abdullah Odabaş","poet_slug":"abdullah-odabas","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/tefekkur-il-mevt-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Teselliname', 'teselliname-abdullah-odabas-9grhb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nasihat ve öğüt almak istersen,         	

Cihanedopdolu, ölümde vardır.           	

Yıkılup haneler tarumar olur,           	

Cihane dopdolu, ölümde vardır.          	

Nice bin annesiz kuzular meler,         	

Kuzusuz anneler dağları deler,          	

O ela gözlerden yaşları siler,          		

Cihane dopdolu, ölümde vardır.          	

Dünyanın ahiri harabe zardır,           	

Münafık başına bu dünya dardır,     	

Hakikat görmeyen o gözler kördür,       	

Cihane dopdolu, ölümde vardır.          	

Nebiler dünyadan eyledi firar,         	

Gafiller dünyayı bağrına basar,         	

Hilebaz, oyunbaz seni de yorar,         	

Cihane dopdolu, ölümde vardır.          	

                            		

Ebu Cehil, Şeddat hele Firavun,

Hz.Musa''ya çok etdi oyun,

Musa ise kırda güderdi koyun,

Cihane dopdolu, ölümde vardır.

Hesap et bunları gafletten uyan,

Annenden dünyaya gelmiştin üryan,

Yüklendi yükümüz gidiyor kervan,

Cihane dopdolu, ölümde vardır.

Mizan et kendini burada tartıl,

Yarın mahşer günü yürümez batıl,

Çoğalacak derdin söylemez bu dil,

Cihane dopdolu, ölümde vardır.

Meftuni bu sözler kendi özüne,

İlmühali öğret oğlun kızına,

Ruz-ı cezada vurma dizine,

Cihane dopdolu, ölümde vardır.', 'Nasihat ve öğüt almak istersen,         	 Cihanedopdolu, ölümde vardır.           	 Yıkılup haneler tarumar olur,           	 Cihane dopdolu...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Odabaş']::text[], 8.5, '{"poet":"Abdullah Odabaş","poet_slug":"abdullah-odabas","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/teselliname-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başınızsağolsun', 'basinizsagolsun-abdullah-odabas-ot3xo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir dost vefatına

Muhbiri sadıkın müjde kelamı, 		 

Muhterem kardaşım o hüsnü hali, 		 

Teşrifi mübarek ali makamı, 		 

Başınız sağ olsun; tebrik ederim. 		 

Yürümüş dünyada müstakim yolda, 	 

Tarikı Hüdadır hem Nakşikolda,		 

Son nefes tevhidi söylemiş dilde, 		

Başınız sağ olsun; tebrik ederim. 		

Okuduk mektubu gözler yaşardı, 

Gönülde muhabbet gülü yeşerdi, 

O hazreti bize bir niğmet verdi. 

Başınız sağ olsun; tebrik ederim. 

Şimdi beraberdir Çorum’la Zile, 

Sanki dost bülbüller konmuşlar güle, 

Cennet bahçesinde dostlar el ele, 

Başınız sağ olsun; tebrik ederim. 

Ağlıyor Meftuni, sızlanır Sami, 

Kelime-i tevhit ahir kelamı, 

Hazreti Şeyhinin o büyük şanı,

Başımız sağ olsun; tebrik ederim.', 'Bir dost vefatına Muhbiri sadıkın müjde kelamı, 		  Muhterem kardaşım o hüsnü hali, 		  Teşrifi mübarek ali makamı, 		  Başınız sağ olsun; t...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Odabaş']::text[], 8.5, '{"poet":"Abdullah Odabaş","poet_slug":"abdullah-odabas","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/basinizsagolsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O ince sızım', 'o-ince-sizim-halil-colak-178pl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İstanbul akşamlarında sen varmışsın

Gönüllerde yer alan sen sultanmışsın

Başımdan çıkıp giden ablam dumanmışsın

Bu hasretlik kardeşim hep böyle gitmez

Yollar uzak ben yorgunum yol uzun

İstanbul kalabalık ve pahalı be kuzum

Sazın bamtellide çalmaz kopmuş be kuzum

Hasretliktir kalbimdeki olan o ince sızım

Halil Çolak  12.12.2005 Ankara', 'İstanbul akşamlarında sen varmışsın Gönüllerde yer alan sen sultanmışsın Başımdan çıkıp giden ablam dumanmışsın Bu hasretlik kardeşim hep bö...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/o-ince-sizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşün', 'dusun-tulay-i-cen-pezig', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dalmışım gözlerinin ufkuna.

Baktıkca gözlerinin içine,

Kopar içimde fırtımalar.

Düşün benim içimde kopan fırtınaları.

Dalga dalga  büyür beni benden götürür.

Sen bir ateşsin yakan kavuran,

söndüremez kimse alevlenen ateşi.

Düşünmem  başka birinin varlığını.

Tek sen varsın  benim içimde.

Düşün ne kadar derin senin ateşin.

Düşündükce seni sarıyor bütün benliğimi.

Tek sen varsın beni benden alan,

Ben hep sensiz, seni istiyorum.

Ulaşmak  sana cok zor dağlar kadar yücesin

Varlığını içimde hissediyorum.

Sen yaşıyor ve benimlesin.

Ben yaşadıkca  sen yaşayacaksın

bu bedende.

Seni gömmem maziye, yaşayan can gibisin.

Asla,asla gömmem.

Düşümsün.Düşündüğümsün.Düşlediğimsin.

02/12/1997', 'Dalmışım gözlerinin ufkuna. Baktıkca gözlerinin içine, Kopar içimde fırtımalar. Düşün benim içimde kopan fırtınaları. Dalga dalga  büyür ben...', ARRAY['Türk Edebiyatı','Şiir','Tülay İçen']::text[], 8.5, '{"poet":"Tülay İçen","poet_slug":"tulay-i-cen","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/dusun-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Dosta', 'bir-dosta-abdullah-odabas-nxki7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu mahzun gönlümü şadedan mektup,       	

On Eylül Salı gün bize erişti.          		

Hasretinle yanan divane gönlüm,         	

Yeni baştan yane yane tutuştum.          	

İhbar etti bugün hal-i ahvali,          		

İki dostun kavuştuğu ol hali,           		

Değme bu gönlüme ağır yaralı,           	

Yeni baştan yane yane tutuştum.          	

Okuttum Ferhada, ben de dinledim,       	

İç dünyamda için için inledim.          	

Bir an olsun sizi gözden ırmadım,       	

Yeni baştan yane yane tutuştum.          	

Kurban olam yazı yazan ellere,

Durri mercan bal akıtan dillere,

Mektup değil bülbül konmuş güllere,

Yeni baştan yane yane tutuştum.

Büyük niğmet varis ekmel efendim,

Uyar beni yar kadrini bileyim,

Lutfeyle efendim ben de güleyim,

Yeni baştan yane yane tutuştum.

Meftuniyem derde lokmanım yetiş,

Aciz biçareyim Hünkarım yetiş,

Himmet et son nefes imdada yetiş,

Yeni baştan yane yane tutuştum.', 'Bu mahzun gönlümü şadedan mektup,       	 On Eylül Salı gün bize erişti.          		 Hasretinle yanan divane gönlüm,         	 Yeni baştan y...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Odabaş']::text[], 8.5, '{"poet":"Abdullah Odabaş","poet_slug":"abdullah-odabas","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bir-dosta-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuru Gül', 'kuru-gul-serkan-asilbas-8ol0x', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Eleleydik o ağacın altında temmuz akşamında,

Ilık maltem rüzgarları eserken,

Uzun saçların dalgalanıyordu.

Gözlerimi senden alamıyordum.

Senin yanındayken sevdana susuyordum.

Beraberken bile seni özlüyordum.

Yürümeye başladık ağaçaların arasındaki,

Eski patika yolda,

Elini hiç bırakmadım saatlerce,

Yanında hayal kurdum seninle birlikte,

Yavaş yavaş evine yaklaşıyorduk.

Cebinden bir mektup çıkardı.

Bana verdi, öptü yanağımdan,

Sonrada dönüp koşarak gitti.

Açtım mektubu,

Şaştım kalmıştım birdenbire,

Sanki o anda dünya başıma yıkıldı.

Aşkın beni de benden aldı,

Senden bana son hatırabir kuru gül kaldı.', 'Eleleydik o ağacın altında temmuz akşamında, Ilık maltem rüzgarları eserken, Uzun saçların dalgalanıyordu. Gözlerimi senden alamıyordum. Sen...', ARRAY['Türk Edebiyatı','Şiir','Serkan Asılbaş']::text[], 8.5, '{"poet":"Serkan Asılbaş","poet_slug":"serkan-asilbas","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kuru-gul-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbet Acısı', 'gurbet-acisi-abdullah-odabas-0nxyp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Karetti canıma, firak-ı gurbet,         	

Lutfeyle kardaşım bir selam gönder,     	

Bu gönül gamkusar sizlere müştak,       	

Lutfeyle kardaşım ya teşrif buyur.      	

Ne dosta kavuştuk, ne de yarana,        	

Devasız dertlere ilaç verene,           		

Bizden selam olsun bizi sorana,         	

Lutfeyle kardaşım ya teşrif buyur.      	

Kesildi bahane, yoktur tutarım,         	

Sizlerin aşkıyla yanıp tüterim,         	

Bilmem ki, Mecnun''um daha beterim,    

Lutfeyle kardaşım ya teşrif buyur.      	

Efendim ne halde, halini sorsam,        	

Elpençe huzuru divanda dursam,          	

Olacak mı kısmet bir dahi görsem,       	

Lutfeyle kardaşım ya teşrif buyur.      	

Mübarek siması cevher sözleri,

Görür mü gözlerim kamer yüzleri? 

Ayırman duadan nolur bizleri,

Lutfeyle kardaşım ya teşrif buyur.

Siz de olmazsanız bizi kim arar? 

Melul gönlümüzü ya kimler sorar? 

İşte bir amel ki Halika yarar,

Lutfeyle kardaşım ya teşrif buyur.

Sizdeki feyizden bize de ağdı,

Virane kalbime bir güneş doğdu,

Kurak diye, rahmetler yağdı,

Lutfeyle kardaşım ya teşrif buyur.

Affet Meftuniye keremler buyur,

Sizdeki ahvali bize de duyur,

Cennet makam olsun içindeyse hur,

Lutfeyle kardaşım ya teşrif buyur.', 'Karetti canıma, firak-ı gurbet,         	 Lutfeyle kardaşım bir selam gönder,     	 Bu gönül gamkusar sizlere müştak,       	 Lutfeyle karda...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Odabaş']::text[], 8.5, '{"poet":"Abdullah Odabaş","poet_slug":"abdullah-odabas","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/gurbet-acisi-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Masum Sevdiğim', 'benim-masum-sevdigim-yusuf-onder-bahceci-7jzze', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Alırlar seni elimden,

Verirler dert ile elem,

Benim sevgim tâ derinden,

Benim masum sevdiğim.

Gözleri hep gülerdi,

Bana sabır dilerdi,

Ne sitemler ederdi,

Benim masum sevdiğim.

Gözleri var karalı,

Yüreğim hep yaralı,

Bu dağların maralı,

Benim masum sevdiğim.

Gözlerinde yaşlar vardır,

Bakışları çok mânadır,

Seven kalbi hep ağlatır,

Benim masum sevdiğim....', 'Alırlar seni elimden, Verirler dert ile elem, Benim sevgim tâ derinden, Benim masum sevdiğim. Gözleri hep gülerdi, Bana sabır dilerdi, Ne si...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/benim-masum-sevdigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yolculuğa Dair', 'bir-yolculuga-dair-hikmet-kavas-76qt0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sen otobüse binerken

bir gölge indi aynı anda otobüsten

ve şakağıma dudaklarınla tutturduğun cümle

uçup gitti o gölgeyle beraber

ne kadar saklamak istediysem de var gücümle

sen otobüse binerken

kulağıma fısıldadığın dizeyi baston gibi tutarak

yürüdüm eve kadar

masada yarım bıraktığın çay

lavaboya düşmüş saçının teli

bilmem ne yapmalı nasıl etmeli

gittin

ülkemin sınırlarıyla oynuyor o gölge

bulut bulut 

çiy çiy yağıyorum ak kağıtların çorağına

kavgaya geç kalma

şeriat ve sömürü burun buruna

kemiğe dayanacak bıçak vardı bir

küf tuttu o bıçak

her yanımız alçak

yoldaşları beslemeye devam et postaylan

postaylan gir kolumuza

hüzün kolay

gölge de kaybolur gider

bulutu ardındaki güneşle beraber

ama borçluyuz

mutluyuz çünkü bu yolu seçtiğimiz için

ödeyelim borcumuzu

borçlu ölmek çok çirkin', 'sen otobüse binerken bir gölge indi aynı anda otobüsten ve şakağıma dudaklarınla tutturduğun cümle uçup gitti o gölgeyle beraber ne kadar sa...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Kavas']::text[], 8.5, '{"poet":"Hikmet Kavas","poet_slug":"hikmet-kavas","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/bir-yolculuga-dair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık Yalnızı Oynar', 'yalnizlik-yalnizi-oynar-necmi-unsal-2t98t', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Buz tutmuş havsalam  ayaz dolan yüreğimde.

Sürüklenir sevdam  bu dipsiz ve dik  eğimde.

Çürüdü ellerde  kalbe inmeyen dualar.

Büküldü bellerde  insicam buldu belalar.

Erişti sükutlar  yürekte yanan ateşe.

Parıldar yakutlar, paslı beyinde telaşe.

Ağır bir bezginlik  esirliğinde hayatın.

Sağır bir gezginlik  körlüğünde seyahatın.

Masum, ürkek, bakir  bakışlarda soru şaşkın.

Zalim, korkak, hakir  isyanlar diz boyu, taşkın.

Asırlar sıtmalı,  hastaya ateş verilmiş.

Beyinler sıkmalı,  kafadan diken derilmiş.

İsimler kavgalı, hep toprak olmuş sonları.

Cisimler kargalı, zaman leş yapmış onları.

Kör olursa gözler, fani sevdaya tutulur.

Kor  olursa közler,   fani beladan kurtulur.

Bu uzun nehirde membalar derinden kaynar.

Bu tenha şehirde  yalnızlık yalnızı oynar.

15 Temmuz 2004 Perşembe, Danimarka-Køge 20.48 *6+8', 'Buz tutmuş havsalam  ayaz dolan yüreğimde. Sürüklenir sevdam  bu dipsiz ve dik  eğimde. Çürüdü ellerde  kalbe inmeyen dualar. Büküldü beller...', ARRAY['Türk Edebiyatı','Şiir','Necmi Ünsal']::text[], 8.5, '{"poet":"Necmi Ünsal","poet_slug":"necmi-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yalnizlik-yalnizi-oynar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mezuniyet Tezi', 'mezuniyet-tezi-savas-dincbas-baqam', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ruhum at koşturacak,dolu dizgin

bütün hayatlar boyunca

sonsuzluğa dek

yüce sevgiye doğru

sevmenin özüne vardım seninle

sen benim mezuniyet tezimsin

sana olan sevgim ulaştıracak beni

o yüce sevgiye

onlarca,binlerce de sürse

bedenlenişim

seninle başladı

seninle bitecek bu tezim

her defasında bulacağım seni

her defasında,bekle beni

ve aynı bedende

güzelliğin ruhuna çok yakışıyor...', 'ruhum at koşturacak,dolu dizgin bütün hayatlar boyunca sonsuzluğa dek yüce sevgiye doğru sevmenin özüne vardım seninle sen benim mezuniyet t...', ARRAY['Türk Edebiyatı','Şiir','Savaş Dinçbaş']::text[], 8.5, '{"poet":"Savaş Dinçbaş","poet_slug":"savas-dincbas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mezuniyet-tezi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayallerle Yaşıyorum', 'hayallerle-yasiyorum-yusuf-onder-bahceci-nj3m0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Güzellerde olmaz vefa,

Yıllarca çekmişim cefa,

Süremedim bir gün sefa,

Hayallerle yaşıyorum.

Sevdiğimi getirseler,

Seni seven bu deseler,

Güzel sözler söyleseler,

Hayallerle yaşıyorum.

Ellerde ne güzeller gördüm,

Gözlerime güler gördüm,

Saçlarını tel tel ördüm,

Hayallerle yaşıyorum.

Sevdiğimi eller almış,

Mutluluğum yarım kalmış,

Seven dostlar hâni nolmuş,

Hayallerle yaşıyorum......', 'Güzellerde olmaz vefa, Yıllarca çekmişim cefa, Süremedim bir gün sefa, Hayallerle yaşıyorum. Sevdiğimi getirseler, Seni seven bu deseler, Gü...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hayallerle-yasiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlham Perisi Arıyorum', 'i-lham-perisi-ariyorum-sahin-erturk-rufgx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Beni ben olarak sevecek

Benimle ağlayıp,gülecek

Şiirlerime yazacağım

İlham perisi arıyorum

Girmedik sokak bırakmadım

Gitmedik şehir bırakmadım

Arıyor hala arıyorum

İlham perisi arıyorum

Tüm albümleri karıştırdım

Bir polis gibi araştırdım

Sarışın,Kumral,Esmerlerden

İlham perisi arıyorum

Duygularımı çoşturacak

Beni peşinden koşturacak

Bir Zühre,Leyla arıyorum

İlham perisi arıyorum

Yalnızlığım kalsın geride

Olabilir ismi FERİDE

İstanbulda,Afyon,Mersinde

İlham perisi arıyorum

Kalbimde ebedi kalacak

Beni mutluluğa boğacak

Sözünün eri,mert olacak

İlham perisi arıyorum

(12.12.2005-Yeni)', 'Beni ben olarak sevecek Benimle ağlayıp,gülecek Şiirlerime yazacağım İlham perisi arıyorum Girmedik sokak bırakmadım Gitmedik şehir bırakmad...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ilham-perisi-ariyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğime Yazdım Seni...', 'yuregime-yazdim-seni-i-brahim-ethem-bingul-k3u5n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kurak çöle dönmüş sîneme

Bin avuç ümitsin sevginle

Dokunulmamış özlemlerime

Hayat getirdin gözlerinle...

Sevda şarkımın satır aralarında

Keşfedilmemiş nağmesin

Bestakârın suskun notasında

Aşkı bekleyen bir mevsimsin... 

İtiraf edemedim kendime bile

Bir dünya kuruyorum senin sevginle

Aşkını sessizce ört üstüme

Duymasın ay. güneş bile...

Titrer ellerim yazamam ismini

Yazılan sevgi dolu cümleleri

Kalemim kıskanır seni senden

Bilmez ki yüreğime yazdığımı seni...

www.iebingül.com', 'Kurak çöle dönmüş sîneme Bin avuç ümitsin sevginle Dokunulmamış özlemlerime Hayat getirdin gözlerinle... Sevda şarkımın satır aralarında Keş...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yuregime-yazdim-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Işığı Gözlerinin Hasreti', 'ay-isigi-gozlerinin-hasreti-ayfer-ersoy-uf4la', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir şeyler var belli 

Fırtına mı? Kopmayı bekleyen... 

Çok sessiz yüreğim 

Öfkeli mi? Şevkatli mi? Belirsiz... 

Arnavut kaldırımında 

Çakıl taşıyım sanki 

Araya sıkışmış; nefessiz... 

Hiç düşünmemiştim böyle kalabalığın arasında ıssızlığı... 

Her şey bir damla yürek yangını 

Her şey bir damla su... 

Nefesim tıkanıyor sanki 

Kelimeler düğümlenmiş boğazıma 

Bıraksam: iki damla göz yaşı hıçkırığı... 

Bir şeyler uğulduyor kulaklarımda 

Yıldızsız gecelerin ateş böceğini arar gibiyim.... 

Sonra birden 

Aniden 

Sessizlik çöküyor duvarlardan 

Aralık pencereden kemanın sesi gelen 

Sokağın ıssızlığına çağırıyor yüreğimi... 

Yüreğim 

Sokağın ıssızlığına bırakıyor kendini 

Ruhum hapsedilmiş dört duvarın arasına 

Yüreğim başıboş.... 

Eksik yanını arar gibi dolanıyor sokak aralarında 

Köhne bir meyhanenin yorgun şarkıcısını dinlerken buluyorum yüreğimi... 

“At kadehi elinden bin parçaya bölünsün” diyor şarkısında... 

“Dökülsün meyler yere hatıralar gömülsün” 

Keman bir başka söylüyor şarkıyı kadın bir başka... 

Yüreğim sessizce dinliyor şarkıyı 

Ne kadeh bin parçaya bölünüyor ne de hatıralar gömülüyor 

Çıkıyor köhne meyhaneden birkaç kadeh içmiş... 

Hatıralar avuçlarında... 

Güne kavuşmaya var vakit diyor yüreğim bana... 

Daha başıboş saatlere takılacak belli... 

Kordon boyu dar geliyor o an boğuluyor... eve götür beni diyor... 

Eve götür ruha karşımadan yürek olmuyor... 

Alıp getiriyorum yüreğimi eve ruhumun yanına... 

Avucunda hatıralar yüreğimin kırıntıları oluyor ruhuma karışıyor... 

Arnavut kaldırımına sıkışmış çakıl taşı olmak bile yetiyor..... 

Gün üzerime doğuyor........ 

Ve sokak ayak sesleriyle uyanıyor...... 

Bir şeyler var belli... 

Ama fırtına değil kopacak olan... 

Koca bir volkan... 

İçinde ay ışığı gözlerinin hasreti yanan.... 

                                                        Bir İzmir gecesi 09.12.2005', 'Bir şeyler var belli  Fırtına mı? Kopmayı bekleyen...  Çok sessiz yüreğim  Öfkeli mi? Şevkatli mi? Belirsiz...  Arnavut kaldırımında  Çakıl ...', ARRAY['Türk Edebiyatı','Şiir','Ayfer Ersoy']::text[], 8.5, '{"poet":"Ayfer Ersoy","poet_slug":"ayfer-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/ay-isigi-gozlerinin-hasreti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dar Alanda Paslaşanlar', 'dar-alanda-paslasanlar-sahin-erturk-thzd1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şiirlerin bir harika

Kalpten geçen söylenmiyor

Vurmuyorlar balta,taşa

Dar alanda paslaşanlar

Yalakalık yapıyorlar

Şiir değil yazdıkları

Şair oldum sanıyorlar

Dar alanda paslaşanlar

Hece desen,hece değil

Öykü desen,öykü değil

Saçma,sapan yazıyorlar

Dar alanda paslaşanlar

Bazıları kuduracak

Onu,bunu kandıracak

Yine bana saldıracak

Dar alanda paslaşanlar

(12.06.2007)', 'Şiirlerin bir harika Kalpten geçen söylenmiyor Vurmuyorlar balta,taşa Dar alanda paslaşanlar Yalakalık yapıyorlar Şiir değil yazdıkları Şair...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/dar-alanda-paslasanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hani Yazın Gelecektin', 'hani-yazin-gelecektin-yusuf-onder-bahceci-09jmr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şimdi seni çok özlerim,

Uzun yıllar yol gözlerim,

Etki etmezki sözlerim,

Hani yazın gelecektin.

Yıllar oldu bir gelmedin,

Gelip beni bir görmedin,

Kalbim kırık hiç bilmedin,

Hani yazın gelecektin.

Yıllar oldu bekliyorum,

Günü güne ekliyorum,

Kalbim kırık tekliyorum,

Hani yazın gelecektin.

Ayrılıkmış hep kaderim,

Ömrüm zayi çok kederim,

Söyle sensiz ne ederim,

Hani yazın gelecektin....', 'Şimdi seni çok özlerim, Uzun yıllar yol gözlerim, Etki etmezki sözlerim, Hani yazın gelecektin. Yıllar oldu bir gelmedin, Gelip beni bir gör...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hani-yazin-gelecektin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saklayacağım...', 'saklayacagim-nurdane-diken-z123y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni kalbimde saklayacağım

-İnan saklayacağım.

Yazdığım şiirlerle,

-Yazılarımla,

Şarkılarımla, notalarımla

-Türkülerimle

Seni gözlerimde saklayacağım.

-İnan saklayacağım.

Yitirilmiş günlerin adına

Yasemin kokulu baharlar tadına

Sevdaya bulanmış, dostluk hatırına

Seni ellerimde saklıyacağım..

Gözlerim bir alev olacak

Yangını sana koşacak

Yüreğim aşkınla anıtlaşacak

Seni ruhumda saklayacağım..

Erguvan gecelerimin bulutusun

Bu gönül seni nasıl unutsun

Günler geceleri kovalasın

Gözlerim ebediyen kapansın

Seni yenibahara saklayacağım..

-Saklayacağım..

-Sakladım..

-Saklı..........

03.11.05- 23.20-İst....', 'Seni kalbimde saklayacağım -İnan saklayacağım. Yazdığım şiirlerle, -Yazılarımla, Şarkılarımla, notalarımla -Türkülerimle Seni gözlerimde sak...', ARRAY['Türk Edebiyatı','Şiir','Nurdane Diken']::text[], 8.5, '{"poet":"Nurdane Diken","poet_slug":"nurdane-diken","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/saklayacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatımda Bir Ud sesi...', 'hayatimda-bir-ud-sesi-pinar-koc-ghws1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yorgun bir gece 

Ve

Simsiyah gökyüzü…

Uzaklardan acı bir Ud sesi duyuyorum…

Duyamıyorum! ! ! 

‘unutturamaz seni hiçbir şey’çalıyor sanki! ! ! 

Nefes alamadığını hissettiğim anlarda,

Bu Ud sesi ciğerlerini açacak! ! ! 

Gözlerinin görmediği anlarda,

Beyaz bulutlar arkasından çıkan

Simsiyah gözler,gözlerin olacak…

Kulaklarının duymadığı anlarda,

Uzaklardan gelen acı bir Ud sesini

Devr-i Alem dinleyecek,

Senin kulakların yerine…

                                                             18.08.2001  13:45

                                                              pazar', 'Yorgun bir gece  Ve Simsiyah gökyüzü… Uzaklardan acı bir Ud sesi duyuyorum… Duyamıyorum! ! !  ‘unutturamaz seni hiçbir şey’çalıyor sanki! ! ...', ARRAY['Türk Edebiyatı','Şiir','Pınar Koç']::text[], 8.5, '{"poet":"Pınar Koç","poet_slug":"pinar-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hayatimda-bir-ud-sesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sebepsizlikler içinde bir bitiş...', 'sebepsizlikler-icinde-bir-bitis-pinar-koc-xyh98', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Komik şeylerle uğraşıyoruz,

Şu koskoca ve altında ezildiğimiz dünyada…

Belki tamamen sevseydim kendimi,

Ezilmezdim,kırılmazdım ve yok olmazdım,

Sebepsizlikler içinde…

Sebeplenmezdim,suçlanmazdım,

Boynum eğik,

24 yaşında gözünde yaş kalmamış,

bir yaşlı olmazdım…

haraboldum,parçalandım ve bittim…

sönük bir dünyada parlayan elmas gibiydim! 

Küçük,

kara bir kömür parçası oldum…

kırılıp unufak olabilen…

yanan,

yandıkça tüten,

tüttükçe biten…

                                                .. 1999', 'Komik şeylerle uğraşıyoruz, Şu koskoca ve altında ezildiğimiz dünyada… Belki tamamen sevseydim kendimi, Ezilmezdim,kırılmazdım ve yok olmazd...', ARRAY['Türk Edebiyatı','Şiir','Pınar Koç']::text[], 8.5, '{"poet":"Pınar Koç","poet_slug":"pinar-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sebepsizlikler-icinde-bir-bitis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vakit dardı', 'vakit-dardi-unal-karabulut-97t66', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Vakit dardı  ve

İçimde sana karşı bir kıpırtı vardı

Sanki bir yolculuk sırasında 

Bir kahve molası kadar kısaydı 

15 dakikalık bir zaman dilimi miydi

oysa vakit sıkıntısının olmadığı bir yerde 

vaktin seninle geçmesi …….

Ertelendi vakit nedeniyle duygular

Yapılması gereken onca iş vardı

Okunması gereken bir kitap

Dikilmesi gereken bir ağaç

Okşanası saçları bir yetim

Yaşanması gereken bir ömür vardı

Vakit dardı  ve 

Filistin de ağlayan bir çocuk vardı

Bosna’nın bir ah ı vardı

Irak’taki zulmün hesabı sorulmayacak mıydı 

İnsanın sermayesi zamandı 

Eriyen zaman kar mı yoksa  zarar mıydı

Oysaki vakit dardı

Şimdi yaşlandım 

Elimde bir baston yokken yarım hissediyorum kendimi

Tıpkı sen yokken yarım hissettiğim gibi

Ömrüm eridi güneş görmüş bir buz kütlesi gibi

geriye dönüp baktığımda

gökyüzüne doğru yükselen biraz buhar

Bunu görebiliyorum

Sermayemden geriye kalan 

Beklide birkaç dakika

Artık vakit daha da dar benim için

vakit geçsinde gideyim diye bekliyorum

vaktin dar olmadığı mekana 

Hep korktum 

Bir gün karşılaşırız da 

Bana sitemle dersin ki 

Yapacağın işler bitti mi

Bitmedi bir tanem bitmedi

Vaktim buna yetmedi! 

Vakit dardı ve ölümün bile güzeli vardı

Vaktin dar olmadığı zaman ve mekanda buluşmak dileğiyle ….

Vakit dardı ve ölümden sonra bir hayat vardı

07.10.2005', 'Vakit dardı  ve İçimde sana karşı bir kıpırtı vardı Sanki bir yolculuk sırasında  Bir kahve molası kadar kısaydı  15 dakikalık bir zaman dil...', ARRAY['Türk Edebiyatı','Şiir','Ünal Karabulut']::text[], 8.5, '{"poet":"Ünal Karabulut","poet_slug":"unal-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/vakit-dardi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlama Yeter', 'aglama-yeter-selahattin-yetgin-r7973', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hoşça kal demeden, ah yunus gözlüm, 

Duman yalnızlığın dağında öldüm. 

Volkandım severken, şimdiyse söndüm, 

Hazindir ayrılık, ağlama yeter. 

Aşkımızdan uzak, artık sensizim, 

Boşlukta kimsesiz ve nedensizim, 

Kapandı gözlerim, nursuz, fersizim, 

Yoruldu bedenim, baston ol yeter. 

Seninle yaşandı en güzel günler, 

Aşkımıza ettik kutsal yeminler, 

Bir hiç uğrunaydı, bitti sevgiler, 

Anılara dalıp yaşamak yeter. 

Acıları katıp aşk kadehine, 

Bir dikişte içtik şifa yerine, 

Şimdi sürmeler çek o gözlerine, 

Bir umudun kalsın elinde yeter.', 'Hoşça kal demeden, ah yunus gözlüm,  Duman yalnızlığın dağında öldüm.  Volkandım severken, şimdiyse söndüm,  Hazindir ayrılık, ağlama yeter....', ARRAY['Türk Edebiyatı','Şiir','Selahattin Yetgin']::text[], 8.5, '{"poet":"Selahattin Yetgin","poet_slug":"selahattin-yetgin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/aglama-yeter-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '** Aşk-ı Memnu*', 'ask-i-memnu-seyhmus-sevilmez-rzbyw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hiç sevdayı bilmeden, yazıldık belasına

Her taraf mayın olsa, dinlemez aşk-ı memnu

Sağlam çatı örmeden, asıldık kalasına

Koynunda hain olsa, inlemez aşk-ı memnu

Korkulardan kaçılmaz, mecbur onu yaşarsın

Yasak kapı açılmaz, duvarları aşarsın

Mesafeler ölçülmez, hemen ona koşarsın

Aşklara kâhin olsa, anlamaz aşk-ı memnu

Aşkınla dile gelen, güfteler kalsa yaza 

Gerçek sevdayı bilen, kişiler düşmüş aza

Nağme nağme inleyip, ağlarsa teller saza

Dans eden şahin olsa, tınlamaz aşk-ı memnu

Doyumsuz yüze bakıp, sonunda hicran bulsa 

Kızıl gözyaşı akıp, seven yüreğe dolsa 

Aşk alevini yakıp, cehennemlere salsa 

Zindanda rehin olsa, dinlemez aşk-ı memnu 

Fısıldanıp duracak,  yaprak döken yelleri

Kızgın gürzle vuracak, ten okşayan elleri

Bu isyanlar sürecek, kapandıkça yolları

Aşk kokan reyhan olsa, çınlamaz aşk-ı memnu

12.12.2005/ Batman', 'Hiç sevdayı bilmeden, yazıldık belasına Her taraf mayın olsa, dinlemez aşk-ı memnu Sağlam çatı örmeden, asıldık kalasına Koynunda hain olsa,...', ARRAY['Türk Edebiyatı','Şiir','Şeyhmus Sevilmez']::text[], 8.5, '{"poet":"Şeyhmus Sevilmez","poet_slug":"seyhmus-sevilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ask-i-memnu-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Koy Adını...', 'sen-koy-adini-muammer-celik-h3iuf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ne ormanın sessizliği

ne doğanın ıssızlığı

gideremez yalnızlığımı! ...

yalnızlığım sensizliktir

sensizliğim densizliktir! ..

ne dur’dan anlarım

ne git’ten

ben, 

bir tek senden anlarım! ...

BirDeli

11.12.2005', 'ne ormanın sessizliği ne doğanın ıssızlığı gideremez yalnızlığımı! ... yalnızlığım sensizliktir sensizliğim densizliktir! .. ne dur’dan anla...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sen-koy-adini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilenen Ay Bileklerimde', 'bilenen-ay-bileklerimde-kadri-karahan-n8dye', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bir kere daha kestim bileklerimi gece ve 

sana ay kanadım …

ince bir serzeniş oldu kış kuşatmalarına 

seğirmesi gözlerimin deli sözlerimin yaz

bağırması

asılı kaldım bir azılı bıçak bıçak araladım 

tüm kapıları – bir gün bir baktım boşluğu

yaraladım 

bir dün bir baktım tek başına mı ağladım 

sek

bu fotoğraflar eskiriz diyordum o köşede

ne bileyim bu ezgilere ölürüz tütüyordum

arabesk kuytularım öptüğüm kaldırımlar

süpürdüğüm toz toz 

hani bir başka güzeldi ya zaman istanbul

uç kendim uç

aç kendim aç

hani o köşe bucakların bir başka çocuğu 

süründüğüm tuz buz 

parçalar camlarına ıslandığım yağmurlar 

bu sancıların üstesi soluğu susuyordum 

bir efkârı mı düştü şimdi takvime dağlar

kar

kalp ne kadar dağlar lapa lapa yağar mı

karaladım

kaderi kadeh sarhoşluğu – tüm hoyratlığı

içten içtim hiçliğim tıkalı kaldım kor takılı

çağırması

sere serpe uzanması yılgın şiirlerim gibi

bir ince sesleniş oldu an kuşanmalarına

ona aşk ağardım 

ve bir kere daha kestim bileklerimi gece 

kk

11 Aralık 2005 istanbul

www.kadrikarahan.net', 'bir kere daha kestim bileklerimi gece ve  sana ay kanadım … ince bir serzeniş oldu kış kuşatmalarına  seğirmesi gözlerimin deli sözlerimin y...', ARRAY['Türk Edebiyatı','Şiir','Kadri Karahan']::text[], 8.5, '{"poet":"Kadri Karahan","poet_slug":"kadri-karahan","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/bilenen-ay-bileklerimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluğunda', 'yoklugunda-elif-betul-ozturk-4tcul', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir şarkıymış meğer dilimden hiç düşmeyen,

Aklımda sadece nakaratı kalmış.

Her fırsatta mırıldanmışım...

Göz yaşlarımmış meğer gözlerimden süzülen.

Eskiden konuşmaya bile çekindiğim sokaklarda,

Şimdi hıçkıra hıçkıra ağlıyorum.

İnan utanmıyorum,

Bağırıyorum,çağırıyorum...

Ellerim de bir boşluk hep seni arıyorum.

Saat daha erken,ben şişenin dibine vurmuşum bile,

Bir yudum bile fazla iken,birtane daha içiyorum.

Ben sabitim,herşey dönüyor.

Hayal meyal resmin,

Daha da net gözlerimde.

Artık hiçbirşey beni ilgilendirmiyor.

Bir elimde şişem,bir elimde sigaram, 

Sanki seni çekiyorum içime.

Zaman durmuyor,gece yarısı oldu bile...

Biliyorum! 

Her adımda sana daha fazla yaklaşıyorum.

İçimdeki ne sevinç ne hüzün.

Şuanda hiçbirşey hissetmiyorum.

Eğilip kokluyorum kenarlarında açan çiçeklerini,

Dayanamayıp toprağını avuçluyorum.

İçki kokan nefesimle,ismini tekrarlayıp,

Yeniden, yeniden ölmek istiyorum! 

Belki yanına gelemem ama...

Ben seni,

Güneşin aynı zaman da doğup,

Aynı zaman da battığı yerde bekliyorum.', 'Bir şarkıymış meğer dilimden hiç düşmeyen, Aklımda sadece nakaratı kalmış. Her fırsatta mırıldanmışım... Göz yaşlarımmış meğer gözlerimden s...', ARRAY['Türk Edebiyatı','Şiir','Elif Betül Öztürk']::text[], 8.5, '{"poet":"Elif Betül Öztürk","poet_slug":"elif-betul-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yoklugunda-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyle Biri', 'oyle-biri-gulsen-gonenc-xpx1a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çarpık çurpuk yaşamlara kulak verirsen,

Dillenmemiş sözcüklere mahkum,

Teslim olmuş temsili aşkları duyarsın.

Bildiğini sananlar bilmiyor,

Bilmediğini sananlar biliyor.

Herkes ne bildiğini biliyor da,

Kimse doğrusunu bilmiyor.

Bilin doğruyu:

Öyle biri yok!', 'Çarpık çurpuk yaşamlara kulak verirsen, Dillenmemiş sözcüklere mahkum, Teslim olmuş temsili aşkları duyarsın. Bildiğini sananlar bilmiyor, B...', ARRAY['Türk Edebiyatı','Şiir','Gülsen Gönenç']::text[], 8.5, '{"poet":"Gülsen Gönenç","poet_slug":"gulsen-gonenc","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/oyle-biri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasemenler Esmeri Yüreğimde', 'yasemenler-esmeri-yuregimde-kamil-soylemez-0sljk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tutuşup,gidiyorum ellerin ellerimde

Bir buzul eriyor,bir mum içim derinliğinde

Öyle güzel gülüyor ki gözlerin

Mimiklerin gamzesi gözlerime

Bir ay doğuyor......

Bir güneş....

Ömrüm seherinde..

Bu gece..

Bir orman büyüyor

Bir göl,gözlerimizde

Yüzmek geçiyor ikimizinde aniden düşünde

Bu çılgınlıkmı sence

Bu soğuk kış gününde yüzmek

Varsın olsun be sevdam

Yoksa nerede sönecek bu ateş

Nerede yol bulacak bu çılgın sevda

Sen sarılıp,kokun çektiğimde bağrıma

Uçuyorum bitanem uçuyorum 

Haydi tut geceyi dudaklarınla

Tüket beni geride kalan zaman gibi

Yumdum ben gözlerimi

Seni seyrediyorum şimdi

Herşeyin ta gerçeği sen sevgilimi

Bir peri sin şimdi

Bir mülüfer göl üzerinde

Yakomozun gizlendiği bir kelebeksin

Özlemin sendedir gerçek resmi

Buselerinde 

Nefesim nefesinde büyüyor

Buselerin sıralanırken buselerime

Titriyorm....

Sen muhteşemin teninde

Bir kuş çırpınışı göğsümde

Tutmasan ellerimden bilirim küsecek kendine

Bulutları siliyor

Sine sine yağan yağmur üstümüzde

Altımızda bir koltuk 

Meşeden çıkan renkler alevinde

Apaçi işareti siniyor üstümüze

Uzanıp,yatmak varya ateşin çevresinde

Seninle sere serpe

Bir boşluk çıkıyor önümüze

Uçmak bu olsa gerek düşüyor 

YSM esmeri yüreğimde', 'Tutuşup,gidiyorum ellerin ellerimde Bir buzul eriyor,bir mum içim derinliğinde Öyle güzel gülüyor ki gözlerin Mimiklerin gamzesi gözlerime B...', ARRAY['Türk Edebiyatı','Şiir','Kamil Söylemez']::text[], 8.5, '{"poet":"Kamil Söylemez","poet_slug":"kamil-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/yasemenler-esmeri-yuregimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aç Tavuk', 'ac-tavuk-mehmet-ayhan-gunaydin-rm2q3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'AÇ TAVUK

‘Aç tavuk rüyasında darı görürmüş’.

Ben de gördüm. 

Kebabçıdaydım.

Hayra yorun! 

Bir değil hem de, 

Bir de 

Buçuğunu ısmarlamıştım.

M. Ayhan Günaydın.

     9 Aralık 2005 

         Ankara', 'AÇ TAVUK ‘Aç tavuk rüyasında darı görürmüş’. Ben de gördüm.  Kebabçıdaydım. Hayra yorun!  Bir değil hem de,  Bir de  Buçuğunu ısmarlamıştım....', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ayhan Günaydın']::text[], 8.5, '{"poet":"Mehmet Ayhan Günaydın","poet_slug":"mehmet-ayhan-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ac-tavuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Nefes', 'bir-nefes-mehmet-ayhan-gunaydin-bvpcp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'BİR NEFES

Çileyle yoğrulmuş hamurumuz.

Hepi topu bir nefes alıyoruz işte,

Budur bizim de, bütün varımız yoğumuz.

M. Ayhan Günaydın.

    12 Aralık 2005 

          Ankara', 'BİR NEFES Çileyle yoğrulmuş hamurumuz. Hepi topu bir nefes alıyoruz işte, Budur bizim de, bütün varımız yoğumuz. M. Ayhan Günaydın.     12 A...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ayhan Günaydın']::text[], 8.5, '{"poet":"Mehmet Ayhan Günaydın","poet_slug":"mehmet-ayhan-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bir-nefes-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessizliğim', 'sessizligim-mehmet-ayhan-gunaydin-tzetg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'SESSİZLİĞİM.

Böyle sessiz durduğuma,

Bakma sen.

İçimde; 

Ne tufanlar, 

Ne fırtınalar kopuyor.

Bir bilsen.

M. Ayhan Günaydın.

   12 Aralık 2005 

          Ankara', 'SESSİZLİĞİM. Böyle sessiz durduğuma, Bakma sen. İçimde;  Ne tufanlar,  Ne fırtınalar kopuyor. Bir bilsen. M. Ayhan Günaydın.    12 Aralık 20...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ayhan Günaydın']::text[], 8.5, '{"poet":"Mehmet Ayhan Günaydın","poet_slug":"mehmet-ayhan-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sessizligim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Günlerde', 'bu-gunlerde-mehmet-ayhan-gunaydin-jdf68', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'BU GÜNLERDE

Ben, beni sevmiyorum ki

Bu günlerde.

Sen nasıl seveceksin? 

Bu hal böyle giderse

Bilmem ki,

Sen nasıl güleceksin? 

M. Ayhan Günaydın.

     9 Aralık 2005 

          Ankara', 'BU GÜNLERDE Ben, beni sevmiyorum ki Bu günlerde. Sen nasıl seveceksin?  Bu hal böyle giderse Bilmem ki, Sen nasıl güleceksin?  M. Ayhan Güna...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ayhan Günaydın']::text[], 8.5, '{"poet":"Mehmet Ayhan Günaydın","poet_slug":"mehmet-ayhan-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bu-gunlerde-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret', 'hasret-i-lknur-er-1qut5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hasret koşuyor kollarıma

Kahretsin yine yakalandık

Oysa hep arkamı dönerim kendisine

Yinede bir yol bulur

Gelir konar kalbimin kenarına

Sinsice', 'Hasret koşuyor kollarıma Kahretsin yine yakalandık Oysa hep arkamı dönerim kendisine Yinede bir yol bulur Gelir konar kalbimin kenarına Sins...', ARRAY['Türk Edebiyatı','Şiir','İlknur Er']::text[], 8.5, '{"poet":"İlknur Er","poet_slug":"i-lknur-er","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/hasret-308-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vicdansızlar', 'vicdansizlar-yusuf-onder-bahceci-zt9g0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözleri hep yaşla dolu,

Bu ayrılık neden oldu,

Bu Dünya''da onu buldu,

Vicdansızlar vicdansızlar.

Seven kalbi deliriyor,

Gönlü ferman dinlemiyor,

Dertleri var inlemiyor,

Bu garibin bu garibin.

Gözlerinde yaşlar vardır,

Fani Dünya ona dardır,

Allah Kerim Allah birdir,

Bu garibin bu garibin...', 'Gözleri hep yaşla dolu, Bu ayrılık neden oldu, Bu Dünya''da onu buldu, Vicdansızlar vicdansızlar. Seven kalbi deliriyor, Gönlü ferman dinlemi...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Önder Bahçeci']::text[], 8.5, '{"poet":"Yusuf Önder Bahçeci","poet_slug":"yusuf-onder-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/vicdansizlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni dağların rüzgarı sevmesi gibi sevdim', 'seni-daglarin-ruzgari-sevmesi-gibi-sevdim-samiha-i-kbal-2evor', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerimdeki dalga

Gözlerimdeki mavi beyaz köpüklü dalga

Rüyalarımdaki çoçuk

Rüyalarımdaki sarışın mavi gözlü çocuk

Hayatımdaki gerçek

Hayatımdaki acı ama gerçek

Adın.

Seni  dağların rüzgarı sevmesi gibi sevdim', 'Gözlerimdeki dalga Gözlerimdeki mavi beyaz köpüklü dalga Rüyalarımdaki çoçuk Rüyalarımdaki sarışın mavi gözlü çocuk Hayatımdaki gerçek Hayat...', ARRAY['Türk Edebiyatı','Şiir','Samiha İkbal']::text[], 8.5, '{"poet":"Samiha İkbal","poet_slug":"samiha-i-kbal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/seni-daglarin-ruzgari-sevmesi-gibi-sevdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Böyle Bırakmayacaktın', 'beni-boyle-birakmayacaktin-serap-demirturk-ddmu5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Beni böyle bırakmayacaktın. 

Egsoz dumanları, 

Rüzgarın uğultusu 

Ve senin uzaklaşan sesin, 

Yıkıldım! 

Beni böyle bırakmayacaktın. 

Verilen sözler, 

Kurulan düşler 

Ve senin veda eden elin, 

Kahroldum! 

Beni böyle bırakmayacaktın. 

Güzel gözlerin, 

Bükük boynun 

Ve giremediğim kalbin 

Yok oldum!', 'Beni böyle bırakmayacaktın.  Egsoz dumanları,  Rüzgarın uğultusu  Ve senin uzaklaşan sesin,  Yıkıldım!  Beni böyle bırakmayacaktın.  Verilen...', ARRAY['Türk Edebiyatı','Şiir','Serap Demirtürk']::text[], 8.5, '{"poet":"Serap Demirtürk","poet_slug":"serap-demirturk","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/beni-boyle-birakmayacaktin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiçekler', 'cicekler-metin-yalti-d891k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Pencerem önünde menekşeler var 

Biri mor, bir pembe beyazı da var 

Sevdiğim gözlerde ışıklısı var 

Bana yüzündeki gülüşün yeter

Mor menekşem demiş beni çok sever

Sevdiği gözlerde benim rengim var 

Ortalık karışmış bense bihaber

Olmaz böyle dedim barışın yeter

Pembe içerlemiş gördüm üzüldüm.

Birazcık konuşup gönlünü aldım

Baktım beyaz mahzun ona yaklaştım

Asma yüzün dedim duruşun yeter

Çiçekli kadınlı yaşam bambaşka 

Baktıkça onlara gelirim aşka

Metin''in onlarla havası başka

Bana çiçek gibi kokuşun yeter

12/12/05', 'Pencerem önünde menekşeler var  Biri mor, bir pembe beyazı da var  Sevdiğim gözlerde ışıklısı var  Bana yüzündeki gülüşün yeter Mor menekşem...', ARRAY['Türk Edebiyatı','Şiir','Metin Yaltı']::text[], 8.5, '{"poet":"Metin Yaltı","poet_slug":"metin-yalti","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/cicekler-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duy Beni / Annem', 'duy-beni-annem-serap-demirturk-epg1l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bilmediğimi nasıl özlerim? 

Anlamadığımı nasıl severim? 

Sen sımsıkı sarılırken sıcacık yorganına,

Ben taşları yastık eder de yatarım.

Sen ağlarken annem diye,

Ben anne diyemeden yaşar giderim.

Ben annemi özlemiyorum,

Anne nedir bilmem ki.

Ben yuvama gitmiyorum,

Yuva nedir hiç tatmadım ki.

Dün yolda bir resim buldum,

Bir çocuk annesine sarılmış; 

Daldım gittim nedensizce.

Sus derim susmaz yüreğim.

Neden akar gözyaşlarım,

Bilmiyorum...

Neden sokak benim evim? 

Neden babam almaz eve? 

Nedenler doldu başıma? 

Üşüdüm..

Adım Mehmet''miş, Ahmet''miş; 

Kimin umurundaymışım! 

Donsam burda kime ne! 

Orda bir kalabalık var.

Sordum neden burda insanlar

Evleri yok mu onların da...

Sokak çocukları için dedi biri

Yürüyoruz da...onun için...

Onun için burdayız..

Gel sen de...

Gülmek bana yakışmaz gülsem.

Sustum kaldım öylece..

Neden sonra dedim ki

Var mı yapacak bir iş? 

Ekmek alacağım,

Var mı bir iş? 

Çekil git,

Kapama önümüzü; 

Pankart görünmüyor! 

Sus,konuşmacıyı dinle! 

Dinledim...

Bizi anlatıyordu...

Ev diyordu, yuva diyordu.

İş diyordu, aş diyordu.

Duymadılar seslendim.

Görmediler, burdayım.

Çekildim kenara; 

Yürüyüp gittiler.

Sokağımla beni,

Başbaşa bıraktılar.

Uzakta, derinden bir ses,

Yavrum der; gidemem.

Annem! 

Annem! 

Al beni,

Sar beni.

Yoruldum, üşüdüm.

Duy beni.', 'Bilmediğimi nasıl özlerim?  Anlamadığımı nasıl severim?  Sen sımsıkı sarılırken sıcacık yorganına, Ben taşları yastık eder de yatarım. Sen a...', ARRAY['Türk Edebiyatı','Şiir','Serap Demirtürk']::text[], 8.5, '{"poet":"Serap Demirtürk","poet_slug":"serap-demirturk","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/duy-beni-annem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TespiT', 'tespit-kamil-at-qwgt5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İnsanın körü her an görebilceğini

Düşünür ve mutlu olur

Sakalı bıyığı köse olan da

ölene kadar

Birgün sakalım çıkacak der

Öyle avunur

Üç

Hiç bir şey bilmeyen, o kadar bilgisiz ki

Kendisini herkesten 

Bilgili hiseder 

Bilgisizliğinden ne kadar 

Bilgisiz olduklarını 

Bilmiyorlar...

Okuyan cahiller', 'İnsanın körü her an görebilceğini Düşünür ve mutlu olur Sakalı bıyığı köse olan da ölene kadar Birgün sakalım çıkacak der Öyle avunur Üç Hiç...', ARRAY['Türk Edebiyatı','Şiir','Kamil At']::text[], 8.5, '{"poet":"Kamil At","poet_slug":"kamil-at","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/tespit-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korktum', 'korktum-gul-birmutlu-15ddn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bekledim hep sonsuzluğun sonunun gelmesini

ben sona gidemedim

her bekleyişimde aldım kötü haberleri

gidenler gitmek istemeyenlerdi

korktum gideceğim o an bende gitmek istememekten

dünyamda her şeyin değişip beni de rehaveti içine almasından

rahata alışıp Hak yolundan ayrılmaktan', 'bekledim hep sonsuzluğun sonunun gelmesini ben sona gidemedim her bekleyişimde aldım kötü haberleri gidenler gitmek istemeyenlerdi korktum g...', ARRAY['Türk Edebiyatı','Şiir','Gül Birmutlu']::text[], 8.5, '{"poet":"Gül Birmutlu","poet_slug":"gul-birmutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/korktum-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dayan', 'dayan-gul-birmutlu-d8xl4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sakın ağlama 

dayan bütün acılara

hayat seni sevmiyorsa

değer mi hayat için ağlamaya? 

                                      kastamonu', 'sakın ağlama  dayan bütün acılara hayat seni sevmiyorsa değer mi hayat için ağlamaya?                                        kastamonu...', ARRAY['Türk Edebiyatı','Şiir','Gül Birmutlu']::text[], 8.5, '{"poet":"Gül Birmutlu","poet_slug":"gul-birmutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/dayan-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur yağıyor çiçeklerin üzerine', 'yagmur-yagiyor-ciceklerin-uzerine-samiha-i-kbal-eafrt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gün üstümüze rahmet yağdırıyor bugün

Gülen gözleri boğuluyor çocukların

Ellerinde oyuncakları

Bir saçak altı arıyorlar sığınacak

Anneler sarkıyor camlardan

Kimileri kapılara koşuyor

Bir sahipleniş kaplıyor sokakları

Günahsız kalplerde bir isyan

Öpülesi gözlerde kıvılcımlar peydah oluyor

Neden kızıyorsunuz güzel gözlü çoçuklar

Sevinin

Ne mutlu sizlere ki

Burada yağmur yağıyor

Çiçeklerin üzerine

           Mermi değil.', 'Gün üstümüze rahmet yağdırıyor bugün Gülen gözleri boğuluyor çocukların Ellerinde oyuncakları Bir saçak altı arıyorlar sığınacak Anneler sar...', ARRAY['Türk Edebiyatı','Şiir','Samiha İkbal']::text[], 8.5, '{"poet":"Samiha İkbal","poet_slug":"samiha-i-kbal","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yagmur-yagiyor-ciceklerin-uzerine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgar Ve Ben', 'ruzgar-ve-ben-serkan-karabulut-4n5vr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'akıp giden sensizlik 

bir denizin hışır hışır köpürmesi 

icimde sana kabaran binlerce dalga 

ve sana yanması her ateşin 

neden bu kadar kimsesiz rüzgar 

neden her sabah aynı serinlikle alnımda üşür 

yalın ayak çamur icinde bir çocuk 

her vakit rüzgarla neden ağlar kederine 

sırtımda zıpkın gibi duran ayrılık 

canımı yakan tel tel uzaklaşan sacların 

dirhem dirhem kopuyorsun benden 

ellerin.......vazgecemediğim 

yaprak gibi düşüyor kalbimden 

esiyor rüzgar gene bir başka 

yatıyor çırıl çıplak bedeniyle çocuk 

rüzgar ve ben ağlıyoruz 

bu defa ölen kederimiz 

not: sonsuz teşkkürler sana.......', 'akıp giden sensizlik  bir denizin hışır hışır köpürmesi  icimde sana kabaran binlerce dalga  ve sana yanması her ateşin  neden bu kadar kims...', ARRAY['Türk Edebiyatı','Şiir','Serkan Karabulut']::text[], 8.5, '{"poet":"Serkan Karabulut","poet_slug":"serkan-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ruzgar-ve-ben-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gecelik', 'bu-gecelik-serkan-karabulut-p9iu9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'seni ürkek adımlarımın kırbacı 

seni yalnızlığımın adım adım takipcisi 

seni göz bebeğimin feri 

almının kırış kırış çizgisi 

ve ey seni 

yaşamın ellerime sunduğu nadir çicek 

seni öte dünyalarımın kahramanı 

ve karmaşası beynimin 

yılan gibi süzülen deligine 

sinsi mi sinsi her kuşku da başlayan hezilasyon....... 

ve gözlerimizin buluştuğu o parlak yıldız 

susma ne olur 

bu gece bütün perdelerini aç 

bembeyaz giysileriyle bir kız 

ay ay parlasın bırak 

bırak süzülsün incecik bir ışık olup 

sıcak sıcak dokunsun gözlerine 

bir gecelik olsun 

bir yıldız kadar yakın 

bırak dokunayım ellerine 

susma ne olur 

anla kaç asfalt döküldü üzerime 

kaç tır sabah tan akşama sırtımda dolanır 

kaçıncı akşamdan kalma ıssızlık bu 

bu kacıncı dünyadır üstüme yıkılır........ 

unuttum herşeyi kendi bilgeliğinde 

yerin yer olduğunu.....? 

ayın her gece neden parladığını anlıyorum şimdi 

ve bakıyorum geride kalanlara 

ve her gece seninle aglıyorum yalnızlığıma 

bu gece yıldızlar cekiyor beni 

herşeyi bir kez döndürüyorum senin ekseninde 

bir kez daha koparıyorum kıyametleri 

ve giriyorum her defasında kendi cehennemime 

artık perdeni kapat 

gözlerini al 

al yasaklı ellerini 

zindanlarca kapattım 

zincirlerce kilitledim seni 

ve attım anahtarını yüregimin derinliklerine 

not: teşekkürler', 'seni ürkek adımlarımın kırbacı  seni yalnızlığımın adım adım takipcisi  seni göz bebeğimin feri  almının kırış kırış çizgisi  ve ey seni  ya...', ARRAY['Türk Edebiyatı','Şiir','Serkan Karabulut']::text[], 8.5, '{"poet":"Serkan Karabulut","poet_slug":"serkan-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/bu-gecelik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Buse', 'son-buse-zahide-handan-erengil-rj77x', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hüzün dolu gözler yaşlara boğuldu,

Dünya karardı dönmez oldu.

Gülen yüzler gülmez mi? 

Giden geri gelmez mi? 

Hatıralar sarardı soldu,

Bir hayat perişan oldu.

Gönül vazgeçmeyecek,

Bu sevda hiç bitmeyecek.

Düşünüyorum neden,niye? 

Daha yaşı çok genç diye,

Azrail bakmıyor göz yaşıma,

Aldırmıyor,kaçtı yaşına.

Nereden buldun bu adresi? 

Ölümün sessiz,soğuk nefesi,

Sana oldu hediyesi,

Yarin acı son busesi.', 'Hüzün dolu gözler yaşlara boğuldu, Dünya karardı dönmez oldu. Gülen yüzler gülmez mi?  Giden geri gelmez mi?  Hatıralar sarardı soldu, Bir h...', ARRAY['Türk Edebiyatı','Şiir','Zahide Handan Erengil']::text[], 8.5, '{"poet":"Zahide Handan Erengil","poet_slug":"zahide-handan-erengil","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/son-buse-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Başka Sevda', 'bir-baska-sevda-serkan-karabulut-fccn0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'dağ yürür 

orman yürür 

sen yürürdün 

mutlu olurduk bir kuytuluk bulduğumuzda 

parklar sevişmelerin mekanı 

ve yıldızların baştan aşağı dökülmesi ilk öpüşte 

hangi oltada balık olma hevesi 

seni dolu dizgın sürer aşka....... 

sarılmalar hangi sevda kaçkını yüreğinde 

ah zamansız gelen herşey gibi yitik olan 

sevda 

ve kalbimin milimetrik coğrafyasına tutsak imkan 

hangi hesapla artıya döner herşey 

hangi mizan seni bana denkler 

bağrımın yanık yitik yeri 

başı koyduğum aşk 

boynun bir giyotinlik canı 

herşeyin başladığı ve bittigi 

son öpüştur alnımda izi hala dudaklarının 

ve dağ dag yürüyen 

orman orman soluyon 

candır canımın içindeki 

sen ki yaralı bir serce 

incecik bedeniyle taşımış bunca acıyı 

yarandır. yaramı kanatan 

her çırpınışta inleten semayı 

birden çöken sessizlik 

bir yıldızın kayması 

durup dururken saplanan ağrı bögrüme 

hazzı bitmiş sevişmelerin 

hayallerin doyum noktası 

yitirilmiş onca şey 

canın yongası 

ben böyle yenilmişsem 

yitip gitmişse bir yanım 

her anımsayışta bir ana yeniden doğuruyorsa seni 

ve her doğumda yeniden büyüyorsa içimde sevda 

bilki dağ dağ yürüyen benim 

orman orman koşan ben 

anaç bedenimi sunuyorum sana 

yeni doğumlar için 

yeni sevdalara 

not: teşekkürler', 'dağ yürür  orman yürür  sen yürürdün  mutlu olurduk bir kuytuluk bulduğumuzda  parklar sevişmelerin mekanı  ve yıldızların baştan aşağı dökü...', ARRAY['Türk Edebiyatı','Şiir','Serkan Karabulut']::text[], 8.5, '{"poet":"Serkan Karabulut","poet_slug":"serkan-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/bir-baska-sevda-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Gömleği', 'deli-gomlegi-serkan-karabulut-c11ps', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'her yanım ayrılılıyor, her ayrı bir yerden 

bir deli gömleği gibi zaman 

bölük bölçük yırtılıyor beynimde 

ey susmaların şanlı kahramanı 

ey sırtımda kalbur gibi duran yaşam 

örtünü ört 

ve yok ol bu utanc aynasından 

vuruluyor herkes bir yerde 

bir yerde bir cenaze yıkanıyor 

biri kesiyor bilekten damarlarını 

biri ha bire içiyor..zehir zıkkım zamanı 

ah diyorum lanet olası 

ah...... yaşam.... 

kaç kalibrelik hangi marka silahını kuşanıyorsun 

ve hangi hanceri sadece benim için biliyorsun... 

paydos vaktindir şimdi 

ey anaların anası 

acının kol gezdiği her yerde izin 

izlerin..her biri her yerimde 

yaşamın ve ölmenin 

bir şarkı gibi fısıldıyor kulaklarıma sevgilim 

bak sende duy 

mutlu aşk yoktur diyor.....ozan 

bir şırınga gibi şah damarıma giriyor 

ilahi kudret gibi her bir sözün 

sevgilim.... 

aşklarda erteleniyor', 'her yanım ayrılılıyor, her ayrı bir yerden  bir deli gömleği gibi zaman  bölük bölçük yırtılıyor beynimde  ey susmaların şanlı kahramanı  ey...', ARRAY['Türk Edebiyatı','Şiir','Serkan Karabulut']::text[], 8.5, '{"poet":"Serkan Karabulut","poet_slug":"serkan-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/deli-gomlegi-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kariâ/h', 'kari-h-atif-okan-j6vae', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'izini sürdüğümüz gerilerde olmasın

sahi neyi ararız mısralarda karia

en içte bir şeyleri kaybettiğimiz kesin

yoksa bir merdivenle varılırdı Allah''a

sahi neyi ararız sözcüklerde karia

uzayıp giden yollar kendimize varmasın! 

sahi nere gideriz h/ecelerle kariâ

en derinde yolların kaybolduğu kesin

yoksa bir adımda ulaşılır sonsuza

sahi nere varılır bu harflerle kariâ

gülleri ve gölü; dizeleri ve sözü

dağıt kelebekler gibi

tek tek harften mürekkep

bütün ben-î  âdemi

dağıt dağları da 

renkli yumaklar gibi

ey kâri bilir misin

nedir o kariâ? 

çok güçlü bir rüzgar ki o

yıkar bütün sözleri

eğirmek için sonra

kızgın ateşlerinde

buhurumeryem açan 

eğri harfleriyle

kızıl bir bahçe olur 

sözcüklerle haviye

haydi dağıt külümü mısralara kariâ

bir gün bir titrek dize

belki bir gül diye

uzatılır Allah''a

belki bir gün

gül diye...

             Atıf   OKAN

            12/12/2005', 'izini sürdüğümüz gerilerde olmasın sahi neyi ararız mısralarda karia en içte bir şeyleri kaybettiğimiz kesin yoksa bir merdivenle varılırdı ...', ARRAY['Türk Edebiyatı','Şiir','Atıf Okan']::text[], 8.5, '{"poet":"Atıf Okan","poet_slug":"atif-okan","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/karia-h-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nereye Gitsem', 'nereye-gitsem-melih-baki-5zspt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Süheyla''ya...

Dizilmiş 

    basamak

       basamak.

Sevgi harfleri

            Gökyüzüne

                   Merdiven gibi..

Ay''a

  Güneşe

    Yıldızlara

            doğru,

Ayda sen

  Güneşte sen

    Yıldızlarda sen.

Yüreğim yare sorar

           Hangisine ben

                      Gitsem..

2004-Adana

(Ağlar Yüreğim Dağlar da Ağlar:şiir kitabı Karahan kitabevi yay.2005/Adana)', 'Süheyla''ya... Dizilmiş      basamak        basamak. Sevgi harfleri             Gökyüzüne                    Merdiven gibi.. Ay''a   Güneşe   ...', ARRAY['Türk Edebiyatı','Şiir','Melih Baki']::text[], 8.5, '{"poet":"Melih Baki","poet_slug":"melih-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/nereye-gitsem-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bi Haber', 'bi-haber-tayfun-karakas-rr8xw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sukunetin izlerini taşıyor sevgimiz

ne ayrı nede tam beraberiz

ayrıldığımızda daha yakın kavuşunca başka yerlerdeyiz

ne tam sevgili ne de bir başka birşeyiz

dünyayı saran bir sevda değil bizdeki

yuvayı değil yatağı ancak ısıtabiliyor bedenlerimiz

ne sevgi ne şehvet bizdeki 

birşey var ama ne bilmiyorum

bendeki ferhat aşkı değil sende şirin değilsin

mecnun kimden yana leyla kim 

eğer aşk değilse seni görünce içimi ısıtan ne

ne dir bu sendeki ben bendeki sen ne

acaba eskiler çok aşk yaşadıda

bize kırıntı aşklarmı kaldı

yoksa biz küllerimi yakmaya çalışıyoruz

kaknüs değiliz yanınca yok oluyoruz 

bir yol var yürüyoruz

sonunu ne sen nede ben biliyoruz

ben artık çok yoruldum

sevdam sana duyurulur

tayfun karakaş 

[email protected]

https://www.youtube.com/watch?v=9EjvNP0fLAg', 'sukunetin izlerini taşıyor sevgimiz ne ayrı nede tam beraberiz ayrıldığımızda daha yakın kavuşunca başka yerlerdeyiz ne tam sevgili ne de bi...', ARRAY['Türk Edebiyatı','Şiir','Tayfun Karakaş']::text[], 8.5, '{"poet":"Tayfun Karakaş","poet_slug":"tayfun-karakas","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bi-haber-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Münevver Şenol', 'munevver-senol-munevver-senol-l8yju', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'MÜNEVVER ŞENOL 

(akrostiş)

Mutluluğun resmine benzer 

Üzümler asmada gezer 

Nehirler yağmurdan taşar 

Ela gözlerin derin bakar 

Vaz gecmem diye kalp atar 

Vah çeker yar göçmem diyor 

El ele tutuşalım ver gidiyor 

Ruhum sensiz nasıl göçer diyor 

Şad olsun günün güzeliği 

Esmerleşiyor hep sevdiği 

Naza gelmem söz verdiği 

Olmaz diyor yar gittiği 

Lamba gibi yanar gördüğü… 

Yusuf Ter 01.12.05 

Saat 19:30 İsviçre 

Çok değerli dostum, Sayın Yusuf Ter Beyefendinin bana itaf bu guzel şiirini sizlerle paylaşıyor ve huzurunuzda ona teşekkür ediyorum.', 'MÜNEVVER ŞENOL  (akrostiş) Mutluluğun resmine benzer  Üzümler asmada gezer  Nehirler yağmurdan taşar  Ela gözlerin derin bakar  Vaz gecmem d...', ARRAY['Türk Edebiyatı','Şiir','Münevver Şenol']::text[], 8.5, '{"poet":"Münevver Şenol","poet_slug":"munevver-senol","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/munevver-senol-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölmek Zamanı', 'olmek-zamani-adem-tok-12lxi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '_yeşermek:

susamışlığıdır ölümün

samurayın bırakmamasıdır düşerken

kılıncını elinden

ölmek zamanının aslında burada

yeniden doğmanın olduğunu

suda yosun gibi nefessiz

tutunması gazelin 

yeniden rengine

YAŞAMI YAŞATANLARA

onurdur nefes almak; 

ölürken dahi nefessiz kalmamak! 

saygıyla..._

                                                   (09.12.05) 

                                                     ümraniye', '_yeşermek: susamışlığıdır ölümün samurayın bırakmamasıdır düşerken kılıncını elinden ölmek zamanının aslında burada yeniden doğmanın olduğun...', ARRAY['Türk Edebiyatı','Şiir','Adem Tok']::text[], 8.5, '{"poet":"Adem Tok","poet_slug":"adem-tok","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/olmek-zamani-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilinçaltı-mağara (nûn-kâf)', 'bilincalti-magara-n-n-k-f-atif-okan-ncmu0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'su (n)  ağına düşürmüş günün ışıklarını

başını karanlığa yaslayan kör çocuklar

ben (k) ara sözcüklerle konuşan bir ağızım

bir gözüm ki gittikçe içlerinden göçmüşüm

denize açılmış dudaklarımsa tuz kokar

ölü balıklar belki biraz da çürük yosun

d/ağları d/işlemişim küflü toprak kokusu

koy(n) umda okuttuğum melek beni unuttu

bilmemekse bilmekten daha iyidir marâ

ol mahîler derya çün deryayı bilmezler

bense bir katreyim deryalar hamuş bende

yedi nûn uyudun kâf uyan gözlerim şaşır

başım omuzumda iken sayıkladığıma bakma! 

sen de düş bir ormana bana baktığın zaman 

beni bir yangın gibi ormanlara bırakma

karanlık ağzında iken ben alevden bir kuşun! 

                                           Atıf  OKAN', 'su (n)  ağına düşürmüş günün ışıklarını başını karanlığa yaslayan kör çocuklar ben (k) ara sözcüklerle konuşan bir ağızım bir gözüm ki gitti...', ARRAY['Türk Edebiyatı','Şiir','Atıf Okan']::text[], 8.5, '{"poet":"Atıf Okan","poet_slug":"atif-okan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bilincalti-magara-nun-kaf-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızıma', 'kizima-zahide-handan-erengil-oxyb6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sana demiştim bir gün,

Sende anne olacaksın.

O zaman beni anlıyacaksın.

İşte oldun,minicik bebeğini,

Yanında buldun.

Nasıl bir duygu anlatabilir misin? 

Zannetmiyorum,titriyor sesin.

Büyük sorumluluk,artık o senin

Bak nasıl da sana dikkatle bakıyor.

Göğsünü de yakalamış,sıkı sıkı tutuyor.

Adını ÖZÜM koydun,

Senden bir parça biliyordun.

Yorulmuştun uykuya daldın,

Ben de Özüm ü yanından aldım.

Biraz huysuzlandı,naz etti,

Sonra kendini teslim etti.

Ah mini mini yumurcak,

Şimdiden biliyor anneden ayrılmayacak..

İkinizide öptüm,Tanrı ya,

Sizi bana verdiği için şükrettim.

Anladın mı şimdi,annelik nasıl bir tattı? 

Artık bu sevgi benim için iki kattı.

Sen ve Özüm,

Renksiz dünyama renk kattı.', 'Sana demiştim bir gün, Sende anne olacaksın. O zaman beni anlıyacaksın. İşte oldun,minicik bebeğini, Yanında buldun. Nasıl bir duygu anlatab...', ARRAY['Türk Edebiyatı','Şiir','Zahide Handan Erengil']::text[], 8.5, '{"poet":"Zahide Handan Erengil","poet_slug":"zahide-handan-erengil","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kizima-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herşey görünmez', 'hersey-gorunmez-baykal-kaanalp-ct9bp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'her defasında

yıksanda kumdan kalemi

yeniden koşacağım peşinde gülün

adamakıllı aldanacağım

ve ıslanacağım özgürlüğün

tatsız ikliminde

sevmediğim biçimde

biçimsizliğine aldırmaksızın

bütün sızıntılar içinde

yoğuracağım kalpsizliğini

tüm yortuların

hiç inanmasamda

kuşlar bile

taze günlerini

yanlarında taşırlar

göçtükleri sıcak iklime

yük olmamak için

her defasında

yeniden aldatılacağım

sevdiklerim tarafından

tabi ya beni ancak

sevdiklerim aldatabilir

sevmeyen neden aldatsın

kurşun yüklü

demir tavındaki

sıcaklığı ellerimde kalmış

kançanağı gözlerimi

gözlerim ki yalnızca

gördüğünü sanır

o kadar içten baksada

herşeyi göremez insan

ne kadar istese de!', 'her defasında yıksanda kumdan kalemi yeniden koşacağım peşinde gülün adamakıllı aldanacağım ve ıslanacağım özgürlüğün tatsız ikliminde sevme...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/hersey-gorunmez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karşı konulmaz zamana', 'karsi-konulmaz-zamana-baykal-kaanalp-5hm3f', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ciğerler üşütülür

belirsiz bir ayazla

çikolata tadında

yemiş sıcaklığında

kurutulur tüm ıslaklıklar

çıkarsama zannetme

kaptırılan her onuru

yetersiz kalır

birkaç damla gözyaşı

anlatabilmek için

çekilen binbir türlü

acımasız hüzünleri

bakışlar durulmaz

karşı konulmaz zamana

durdur ki, çarpmasın

sana doğru esen

fırtınamsı dalgalar

maviliği şüpheli

arkadaşlığı yersiz', 'ciğerler üşütülür belirsiz bir ayazla çikolata tadında yemiş sıcaklığında kurutulur tüm ıslaklıklar çıkarsama zannetme kaptırılan her onuru ...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/karsi-konulmaz-zamana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kısa tel', 'kisa-tel-baykal-kaanalp-zoeqy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sahip olduğun tek şey

seni sıkan yıldıran

yaşantına ket vuran

ince bir tel

koparamadığın sazın

kalın tellerine inat

durmuş orda öylece 

sana bakıyor

anlıyorsun ki

onsuz olmuyor

ince telsiz

seslerin hepsi kalın

gitmiyor, ilerlemiyor

mızrap bu illa 

kısa tele dokunacak

tiz bir ses alacak

öyle sürecek melodi', 'sahip olduğun tek şey seni sıkan yıldıran yaşantına ket vuran ince bir tel koparamadığın sazın kalın tellerine inat durmuş orda öylece  sana...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kisa-tel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem', 'ozlem-sair-harun-parlament-d0leg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yok olan herşey gibi sende cekip gittin hayatımdan

Hep adını soruyorlar bana,

Adını söyleyemiyorum? 

Hırçın bir yağmurdu diyemiyorum.

Şiirimde kalıyor herşey,

Dokunduklarım yalan oluyor.

Issız sesin kalıyor ortalarda,

Adsız ama gözlerin kaldığı yerden

Mısralar başlar konuşmaya,

Adını soruyorlar söyleyemiyorum.

Birazdan bilerek susuyorum,

Sonra şiirimi okuyorum.

Seni çizdiğim bir kağıda

Gözlerine bakıyorum.

Bilerek ağlıyorum,

Adını soruyorlar? 

Susun diyor şiirim? 

Herkes susuyor.

Ve seni anlatıyorum yanlan yanlış,

Soruyorlar? 

Bilerek ağlıyorum,

Umut...

Hırçın Bir Yağmurdu O...', 'Yok olan herşey gibi sende cekip gittin hayatımdan Hep adını soruyorlar bana, Adını söyleyemiyorum?  Hırçın bir yağmurdu diyemiyorum. Şiirim...', ARRAY['Türk Edebiyatı','Şiir','Şair Harun_parlament']::text[], 8.5, '{"poet":"Şair Harun_parlament","poet_slug":"sair-harun-parlament","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ozlem-289-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzigârlı sone', 'ruzig-rli-sone-atif-okan-b2huo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'zindanı bir mâh/kumun ümit yıkımın oğlu

de ki bekleyişler siyâh atlara bindi

aşıp gittiler çoktan dar vuslat yokuşunu

ne ki beklerim seni ne ki yağmurlar dindi

desem ki burada bu yağmur ormanında

en ağaç yüzümle var olmanın cürmünü

dağladı dağ yüreğim dağa yandı yadı dağ

taşıyorum ey tanrım sen olmanın yükünü

de ki kararsızlığımın o yılgın çarmıhında

unutulmuş bir kaç çelimsiz gül kanıyor

bilsen en güzel düşler efletun bulutlarla

donanarak aniden som gökler soyunuyor

aşksa hep bitecek bir yangın gibi..sonra

külünü dumanını savuracak rüzgâra

                                        Atıf  OKAN', 'zindanı bir mâh/kumun ümit yıkımın oğlu de ki bekleyişler siyâh atlara bindi aşıp gittiler çoktan dar vuslat yokuşunu ne ki beklerim seni ne...', ARRAY['Türk Edebiyatı','Şiir','Atıf Okan']::text[], 8.5, '{"poet":"Atıf Okan","poet_slug":"atif-okan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ruzigarli-sone-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bal tadında...!', 'bal-tadinda-pinar-koc-4ko0j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sana balım desem,

Arılar utanır,sana baktığında

Kendi yaptıkları acı tatlardan…

Sana aşkım desem,

Leyla ile Mecnun,

Kerem ile Aslı kıskanır 

Yaşayamadıkları hayattan…

Sana son nefesim desem,

Çıkmaz inanır mısın ciğerlerimden

Bırakmaz,vermez ölüm gibi seni…

Sen benim biricik varlığım,

Sen benim son nefesim,

Ve aşkımın en tatlı tadısın………

                                                      20.11.05  06:01', 'Sana balım desem, Arılar utanır,sana baktığında Kendi yaptıkları acı tatlardan… Sana aşkım desem, Leyla ile Mecnun, Kerem ile Aslı kıskanır ...', ARRAY['Türk Edebiyatı','Şiir','Pınar Koç']::text[], 8.5, '{"poet":"Pınar Koç","poet_slug":"pinar-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bal-tadinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Resmine Bakınca Dururum', 'resmine-bakinca-dururum-ercan-cengiz-zbkp7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Resmine Bakınca Dururum

deniz güleç, yüzü dalga dalga 

nehirlere uzanır kolları

sırtlarda sabahın güneşi 

ılık bir rüzgar eserdi saçlarına 

adalarda martılar yükselmiş 

bir çıngırak sızmıştı meşenin dibine 

dalgalarda kaldı gözlerim 

resmin ışıldasın 

gölgelere vursun gözbebeğin 

yüzünü aradım dalga dalga

gülümsemeni 

sorgulayan gözlerini 

dalgalandı saçların denizden başağa 

Toprak Tutsun Külümü', 'Resmine Bakınca Dururum deniz güleç, yüzü dalga dalga  nehirlere uzanır kolları sırtlarda sabahın güneşi  ılık bir rüzgar eserdi saçlarına  ...', ARRAY['Türk Edebiyatı','Şiir','Ercan Cengiz']::text[], 8.5, '{"poet":"Ercan Cengiz","poet_slug":"ercan-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/resmine-bakinca-dururum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyan', 'i-syan-zahide-handan-erengil-2qf5f', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aramadın ne zamandır darıldım.

Döneceksin diye ümitlere kapıldım.

Yolunu gözlemekten yoruldum.

Umurumda değil ne sıcak ne soğuk,

Ne ay ne yıl ne de mevsimler,

Elimde sana ait tozlu ve soluk resimler.

Kimi siyah beyaz,kimi renklı,

Hepsi birbirinden ahenkli,bir başka zevkli.

Hep içten tebessümün,hep neşeli halin,

Umurumda değil,yıllar da mevsimler de zalim.

Yüreğimde burukluk,gözümde yaş,

İstemeden uzaklaşıyoruz,yavaş yavaş.

Gönülde rüyaydı erken bitti,

Her güzel şey gibi o da terk etti.

Uçtu sevdanın güzel günleri,

Baktım ki kalmıştı,yalnızca külleri.

İçimden sökmek istiyorum anıları ve acıları,

Sensiz yaşamak istemiyorum.

Ne bugünü,ne de yarınları.', 'Aramadın ne zamandır darıldım. Döneceksin diye ümitlere kapıldım. Yolunu gözlemekten yoruldum. Umurumda değil ne sıcak ne soğuk, Ne ay ne yı...', ARRAY['Türk Edebiyatı','Şiir','Zahide Handan Erengil']::text[], 8.5, '{"poet":"Zahide Handan Erengil","poet_slug":"zahide-handan-erengil","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/isyan-120-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyandayım', 'i-syandayim-tulay-i-cen-6lxcj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İsyandayım,

İsyandayım yine yanımda sen yoksun,

Kader diyeceksin ama değil.

İnsan kendi kaderini kendi yazar.

Sen benim kaderimi yazdın.

İsyandayım bu yüzden sana ve kendime.

Herşeye yeniden başlamak kolaymı.

beni terk eden sen oldun.

yarı yolda bırakıp giden sen, sen.

İsyanım sana.

İçimde sen varken herşeye yeniden başlanırmı.

Gecenin karanlığında bile duyguları saklamak zor,

Zor.

Aramıza dağlar,yollar,denizler değil,

Soğuk toprak girdi.

İsyanım bundan,

Yollar aşılır,Denizler gecilir,Dağlar aşılır.

Kara toprak aşılmıyor,gecilmiyor.

19/03/1998', 'İsyandayım, İsyandayım yine yanımda sen yoksun, Kader diyeceksin ama değil. İnsan kendi kaderini kendi yazar. Sen benim kaderimi yazdın. İsy...', ARRAY['Türk Edebiyatı','Şiir','Tülay İçen']::text[], 8.5, '{"poet":"Tülay İçen","poet_slug":"tulay-i-cen","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/isyandayim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*İçimdeki Yüz', 'i-cimdeki-yuz-talip-kaplan-nwiw6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözüm aynaya çarptı

Bana bakıyor gibiydi adam

Yaklaştım

O da bana doğru geldi

Dikkatlice baktım yüzüne

Yüzümü inceliyordu

Kızgın mıydı

Üzgün mü yoksa

Göz göze geldik

Öylece bakışıyorduk

Gözlerinin arkası felaketti

İçi yüzüne yansıdı

Gözlerimin önünde

Gözlerinden aktı

O düşüp parçalandığında

Ben dimdik ayaktaydım

________ gözlerim yaşlı...

(10 Ağustos 2004)', 'Gözüm aynaya çarptı Bana bakıyor gibiydi adam Yaklaştım O da bana doğru geldi Dikkatlice baktım yüzüne Yüzümü inceliyordu Kızgın mıydı Üzgün...', ARRAY['Türk Edebiyatı','Şiir','Talip Kaplan']::text[], 8.5, '{"poet":"Talip Kaplan","poet_slug":"talip-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/icimdeki-yuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merhaba 1', 'merhaba-1-tulay-i-cen-5iydc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Merhaba. Bu akşam her zamanki gibi seninleyim.sen benim karanlık dostumsun,karanlıklar içinden gelen dost.sensiz gecen bir günün akşamındayım yani karanlıkta artık akşamlar benim dostum oldu.Sende biliyorsun akşam olunca ben sana daha yakın oluyorum aramıza kimse girmiyor.

Akşamın karanlığında gelen sevgili,

Bilirmisin ne zamandır beklendiğini.

Sen bir gölge misali

Sıcaklığın hissedilmiyor.

Gelde beklenti bitsin.

Karanlık arkadaşım oldu.

Aydınlıksa içimi yakan bir yara.

Gündüzün aydınlığı yakıyor beni.

Olumsuzluklar sıra sıra diziliyor.

Karanlık öylemi..

Bütün cirkinliklerin üzerine

perde gibi örtülüyor.

Kimse sevmez karanlığı.

Karanlık benim dostum,

Arkadaşım,

Sırdaşım oldu.

Nedeni sorma.

SEN BİLİYORSUN.

09/05/1998', 'Merhaba. Bu akşam her zamanki gibi seninleyim.sen benim karanlık dostumsun,karanlıklar içinden gelen dost.sensiz gecen bir günün akşamındayı...', ARRAY['Türk Edebiyatı','Şiir','Tülay İçen']::text[], 8.5, '{"poet":"Tülay İçen","poet_slug":"tulay-i-cen","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/merhaba-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğum Günü', 'dogum-gunu-i-brahim-yavuz-1c24y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dilerim bir ömür boyu

Gönlüne hep neşe dolsun

İyi ki doğdun güzelim

Doğum günün kutlu olsun

Tanrım seni unutmasın

Kötülerle bir tutmasın

Gönlünde güneş batmasın 

Doğum günün kutlu olsun

Olmasın derdin kederin

Eksilmesin sevenlerin

İçimde başkadır yerin

Doğum günün kutlu olsun

Günlerin geçmesin boşa

Ayağın değmesin taşa

Uzun ve huzurlu yaşa

Doğum günün kutlu olsun

Gözlerinde yaş olmasın

Mevsimlerin kış olmasın

Hayallerin düş olmasın 

Doğum günün kutlu olsun 

Seni ben çok seviyorum

Mutluluklar diliyorum

Nice yıllara diyorum

Doğum günün kutlu olsun', 'Dilerim bir ömür boyu Gönlüne hep neşe dolsun İyi ki doğdun güzelim Doğum günün kutlu olsun Tanrım seni unutmasın Kötülerle bir tutmasın Gön...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Yavuz']::text[], 8.5, '{"poet":"İbrahim Yavuz","poet_slug":"i-brahim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/dogum-gunu-60-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fakir Fukara', 'fakir-fukara-yusuf-ter-1yran', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bakıyor hayata gözleri  masum 

çigarayı bırakalı yıllar olmuş

sakalı sacı ağarmış

avuçlarına nasır 

dolmuş işten / ezilmekten

...............yüreğimde bir Of kalmış

sarı dişler gülüşlerini gizler

renkler utanır girdabında

boynu bükülür yana

gözleri parlıyor karanlıkta

gülmekten

ayakları şişmiş 

sokaklarda dolaşmaktan

kirpikleri arasında

çok genç ve çok geç kalmışlığın  görüntüsü 

hala hiç mavi dans etmemiş

hiç ağlamamış çocuk düşleri

yüreği ile göğsü arasına

hiç kalp taşımmış dünya sanki 

...............................yüreğine düşleri 

...............................................sıkışmış bir taş sanki yeryüzüne

bir kuş kadar ağır ve hafif canında

elleri nasırını gözleri ufukları

sırtı dünyanın yükünü taşıyamıyordu 

ara sokaklarda

ne garip dolaşır birbirine diller

ne gariptir fakir fukara

dünya sığmıyor dünyaya

kimin umurunda

adım Yusuf’muş Anlım Ter

kimin umurunda…



Yusuf Ter 05.12.05

Saat 17:13 İsviçre', 'bakıyor hayata gözleri  masum  çigarayı bırakalı yıllar olmuş sakalı sacı ağarmış avuçlarına nasır  dolmuş işten / ezilmekten .................', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ter']::text[], 8.5, '{"poet":"Yusuf Ter","poet_slug":"yusuf-ter","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/fakir-fukara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anımsamıyorum..', 'animsamiyorum-hulya-arisan-qn7x9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Geçmişime dalıyorum,

anıları yaşıyorum.

Hafızama,

sis çökmüş.

Seni 

anımsıyamıyorum...

İstanbul, 12 Aralık 2005', 'Geçmişime dalıyorum, anıları yaşıyorum. Hafızama, sis çökmüş. Seni  anımsıyamıyorum... İstanbul, 12 Aralık 2005...', ARRAY['Türk Edebiyatı','Şiir','Hülya Arısan']::text[], 8.5, '{"poet":"Hülya Arısan","poet_slug":"hulya-arisan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/animsamiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen gittin', 'sen-gittin-samiha-i-kbal-10b40', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen gittin

Sonbaharın altın renkli şeridi dolandı

Çiçeklerin yaz yeşilliği arasına

Yasa büründü geceler

Sen gittin

Aklımda bir şair

Şairden bir şehir kaldı

Adı biz olan şehir

Ve şehirde bir ben kaldı 

Sen gittin

Zamansız gitmeler durağında

Boynu bükük bir garip kaldı

Sen gittin

Huzuru pay eden güneş

Işığını çekti üzerimizden

Yağmurlarda yağmaz oldu

Viraneye döndü gönül köşkümüz 

Kötülük geçicidir demiştim 

Ancak nur sönmez

Aşk ve acı bölünmez

Sen gittin

Adını koyamadığım yokluğa

Bir kısa sevda

Uzaklaşan bir sevdalı rüzgar', 'Sen gittin Sonbaharın altın renkli şeridi dolandı Çiçeklerin yaz yeşilliği arasına Yasa büründü geceler Sen gittin Aklımda bir şair Şairden ...', ARRAY['Türk Edebiyatı','Şiir','Samiha İkbal']::text[], 8.5, '{"poet":"Samiha İkbal","poet_slug":"samiha-i-kbal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sen-gittin-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çanakkale Destanı', 'canakkale-destani-selcuk-karabulut-51p7x', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu ne sis ve karanlık görmüyor gözlerim,

Sularda  kan var kızıla  boyandı ellerım,

Yığınla geldiler kırk bayraktan millet,

Çekmedik kahrını bize yakısmaz zillet,

İşte  siz kimbilir  hangi ildensiniz,

Bana vuran  nedense hep soluk  beniz,

Geçilmez,aşılmaz dağlara vurulmaz deniz,

Siz küçük tepeler biz sizin efendiniz,

Koşarak  geldim sipere elimde var silah,

Bana vuranın yoktur  sinesinde  ilah,

Ya  ölürüm ya kalırım demeden kalktım,

Al bayrağı kanımla  kefenıme  taktım,

Conkbayırı,Seddülbahir kızıl renkli dumanda,

Boğduk düşmanı satır bıçak kamayla,

Neden gelip çatttınız siz bizlere,

Canla alınan yeri canla veririz size.

Geçilmez buralar akmaz  tersine sular,

Akan kanımı kırmızıı  bayragım  yalar,

Bu mekan bizim çekin gidin geriye,

Ne zamandır kedi aslana  verir  terbiye.', 'Bu ne sis ve karanlık görmüyor gözlerim, Sularda  kan var kızıla  boyandı ellerım, Yığınla geldiler kırk bayraktan millet, Çekmedik kahrını ...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Karabulut']::text[], 8.5, '{"poet":"Selçuk Karabulut","poet_slug":"selcuk-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/canakkale-destani-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pakistan''a mektup', 'pakistan-a-mektup-arife-bolat-atzoj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dünya bir ana

Pakistan o ananın göğsünde

Ağlayan bir bebek

Nice ananın yüreğinde bir yara

Bu yaraya ne ilaçlar yetecek

Ne de para

Hani bir gün önce

Bahçemde koşan

Gözlerime kömür karası gözleriyle bakan

Düştüğünde oturup ağlayan

Çantası şimdi yıkık tavanın altında

Elleri kara toprak altında

Canı canımda, nefesi kalmadı daha

Dünya bir ana

Pakistan o ananın göğsünde

Ağlayan bir bebek

Hani bir gün önce

Bana evladım diyen

Seccadesi koltuğunda

Tesbihi asılı boynunda

Başında ak örtüsü, hani derler ya ''anam! ''

Benim de anam vardı

Ve şimdi öksüzüm

Ve şimdi seccadesi cansız bedenin altında

Ve şimdi tesbihi hala cansız teninin yanında

Ve şimdi başındaki ak örtüsü, kefeni 

Anam

Dünya bir ana

Pakistan o ananın göğsünde

Ağlayan bir bebek

Hani bir gün önce

Benim de babam diye boynuna sarıldığım

Benimde ak sakalına bakarak

Yılları daha da tanıdığım

Uzun yıllardan beri

Başından çıkarmadığı şapkası

Elinde tesbihi, öksürüğü hala kulağımda

Bastonunu elinde sımsıkı tutardı ya

Ama şimdi yok, yok, yok

Ben şimdi boynu bükük bir yetimim

Dünya bir ana

Pakistan o ananın göğsünde

Ağlayan bir bebek

Hani bir gün önce

Kardeşim diye dert yandığım

Oturup yanında ağladığım

Aynı kandan aynı candan

Sanki aynı beden

Sanki ben o, o ben kardeşim

Ve şimdi ne evlat

Ve şimdi ne ana, ne baba, ne de kardeş

Hiçbiri yok saniyelerin içinde kaybettim onları

Ben bir yığın taşın altında

Ruhum gidenlerin yanında

Dünya bir ana

Pakistan o ananın göğsünde

Ağlayan bir bebek', 'Dünya bir ana Pakistan o ananın göğsünde Ağlayan bir bebek Nice ananın yüreğinde bir yara Bu yaraya ne ilaçlar yetecek Ne de para Hani bir g...', ARRAY['Türk Edebiyatı','Şiir','Arife Bolat']::text[], 8.5, '{"poet":"Arife Bolat","poet_slug":"arife-bolat","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/pakistan-a-mektup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yollarıma gözüküver', 'yollarima-gozukuver-evren-dalgic-gnj1y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uyma dedim bana sen,

iyisi mi beni dinleme,

aklını başka şeylere ver,

ne bileyim düşün çiçekleri.

uslanmaz sözlerim olur,

ille de sen dediğim; 

sıtmaların tutar ara sıra.

Böyle gör halimi; 

aşıklığıma ver.

Arada sırada da olsa; 

dinleme beni; sadece yollarıma çıkıver.

seni sevdiğim komik gelsin,

anlatırken arkadaşlarına,

o elma yanağına; 

inceden bir tebessüm konduruver.

Aldığım çiçekleri,

köşe başını dönünce at çöplüğe.

İsmim bazen gelsin aklına,

bazen; 

dilinin ucunda unutuver.

Razı olduğum öyle çok  şey var ki; 

unuttuğum birşey var ise; 

onu da sen hatırlatıver.

İster sev ister sevme beni,

hiçbir şey istemem de senden; 

bazen güldüğün; 

bazen görmezden geldiğin o köşeden; 

arada sırada çıkıp da; 

o dalgın gözlerime gözüküver.

(Ankara 2005)', 'Uyma dedim bana sen, iyisi mi beni dinleme, aklını başka şeylere ver, ne bileyim düşün çiçekleri. uslanmaz sözlerim olur, ille de sen dediği...', ARRAY['Türk Edebiyatı','Şiir','Evren Dalgıç']::text[], 8.5, '{"poet":"Evren Dalgıç","poet_slug":"evren-dalgic","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yollarima-gozukuver-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığım', 'yalnizligim-sebahattin-kacar-15qzg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yalnızlığım, bir başka bu akşam. 

Sanki daha bir yalnızım, 

Kimseler yok yanımda. 

Sanki sen bile yoksun. 

Nasıl olduğunu bilmediğim, 

Bilmediğin bir yerlerde, 

Hiçbir yerde, 

Aradığım bir yerlerdesin. 

Özlediğimsin. 

Ama kavuşamadığım. 

Beklediğimsin. 

Ama göremediğim. 

Gel cananım, gel. 

Nerelerdesin sen? 

Gözlerim katran karası oldu artık. 

Nurunla canlandır şu garibi. 

Sözlerinle, dudaklarının arasından çıkacak bir sözle 

Hayat ver şu garibe. 

Yemyeşil olsun gözlerin bu akşam,

Sabahlara kadar seyredeyim ben o gözlerini. 

Masmavi olsun gözlerin, 

Ben onlarda sabaha kadar yüzeyim. 

Kapkara olsun gözlerin, 

Ben onlarda yok olayım. 

Dalgalansın saçların, 

Rüzgârlara yol göstersin. 

Buğday tarlaları,

Senin saçlarına bakarak öğrensin salınmayı. 

Çiçekler, kopsun gelsin dallarından, 

Dalga dalga saçlarına. 

Kaşların yok mu o kaşların. 

Kızmak nasıl olur ya, 

Herkes öğrenir onları görünce. 

O mahzun duruşuna ne güzel yaraşır kaşların. 

Titrerdi hani ya dudakların. 

Kıpkırmızı olurdu da, 

Rengine özenirdi, 

Kirazlar, elmalar. 

Heyhat cananım nerelerdesin? 

Çok beklettin, çok özlettin kendini. 

Senin nurlu yüzüne cümle âlem kurban. 

Ben bin kere kurban. 

Gözyaşlarımdasın yine bu akşam. 

Denizlere yol arayan gözyaşlarım. 

Ateşlere arkadaş gözyaşlarım. 

Özlem dolu yüreğimdeki 

Ateşlere yoldaş gözyaşlarım. 

Ey cananım, ey sevdiğim. 

Nerelerdesin? 

Bekliyorum. 

Ne olur gel. 

Ne olur sokul yanıma artık. 

Tut elimden. 

Bak gözlerime, gözün gibi. 

Işık tut yollarıma. 

Sana varacak yollara. 

Sen kokan rüzgârları getir bana. 

Yakup´um sana bu akşam. 

Gözlerim görmez oldu başka bir şey. 

Gel, gel canım gel. 

Gel Yusuf yüzlüm gel...', 'Yalnızlığım, bir başka bu akşam.  Sanki daha bir yalnızım,  Kimseler yok yanımda.  Sanki sen bile yoksun.  Nasıl olduğunu bilmediğim,  Bilme...', ARRAY['Türk Edebiyatı','Şiir','Sebahattin Kacar']::text[], 8.5, '{"poet":"Sebahattin Kacar","poet_slug":"sebahattin-kacar","theme":"Türk Şiiri","is_hero":false,"total_lines":61,"source_url":"https://www.antoloji.com/yalnizligim-96-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değişmeli', 'degismeli-murat-polat-2-i70bf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaşam bir sır her zaman

Çözmek mümkün olmuyor.

Hep bir perde, hep sis.

Sormadayız durmadan biz kimiz? 

Meraktayız nasıl olacak sonumuz...

Gelecek hep karanlık mı

Görmek mümkün değil.

Görmek ister miydik,

Oda belli değil.

Fakat mutlaka bir şeyleri

Değiştirmeliyiz!', 'Yaşam bir sır her zaman Çözmek mümkün olmuyor. Hep bir perde, hep sis. Sormadayız durmadan biz kimiz?  Meraktayız nasıl olacak sonumuz... Ge...', ARRAY['Türk Edebiyatı','Şiir','Murat Polat 2']::text[], 8.5, '{"poet":"Murat Polat 2","poet_slug":"murat-polat-2","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/degismeli-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derimki', 'derimki-murat-polat-2-nsmks', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Akıllı bir insan sormaz bu soruyu

Ne kendine, ne geri kalana.

Ben kimim, neyim, neredeyim diye.

Belki ben ararım bu soruların cevabını

Belki ben bununla yaşarım.

Derim ki; 

Mutluluk nedir? 

Derim ki; 

Sevmek nedir? 

Derim ki; 

Bağlılık nasıl olur, kime? 

Derim ki; 

Yaşamak nedir? 

Nasıl mutlu olunur? 

Derim ki; 

Ölüm nedir?', 'Akıllı bir insan sormaz bu soruyu Ne kendine, ne geri kalana. Ben kimim, neyim, neredeyim diye. Belki ben ararım bu soruların cevabını Belki...', ARRAY['Türk Edebiyatı','Şiir','Murat Polat 2']::text[], 8.5, '{"poet":"Murat Polat 2","poet_slug":"murat-polat-2","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/derimki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dinlersen', 'dinlersen-murat-polat-2-m20id', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Anlatacak öyle çok şeyim var ki sana

Sensizliğimi, çaresizliğimi.

Kelimeleri dizebilirsem, eğer dinlersen.

Nasıl eridiğimi, demiştim ya hani mum gibi

Nasıl ezildiğimi,umutsuz..

Dinlersen anlarsın belki de

Sevmiştin sende bir zamanlar.

Sen unuttun ama,anlatırım dinlersen

Unutamamayı,anlatırım istersen

Sen uzaklaşırken benden

Nasıl bağlandığımı,

Nasıl ağladığımı bir çocuk gibi.', 'Anlatacak öyle çok şeyim var ki sana Sensizliğimi, çaresizliğimi. Kelimeleri dizebilirsem, eğer dinlersen. Nasıl eridiğimi, demiştim ya hani...', ARRAY['Türk Edebiyatı','Şiir','Murat Polat 2']::text[], 8.5, '{"poet":"Murat Polat 2","poet_slug":"murat-polat-2","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dinlersen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğum Günü', 'dogum-gunu-murat-polat-2-wfxr6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gitmiştim belki de istediğim yere

Bu 22 Mayıs’ta.

Gidemedim yine buradayım...

Çirkinlik ve acılarına rağmen.

Sevgili, sevmek, gülmek...

Belki yaşamak  bana yakışan.

Bir daha deneyeceğim

Tüm her şeyi silerek,

Yeniden...', 'Gitmiştim belki de istediğim yere Bu 22 Mayıs’ta. Gidemedim yine buradayım... Çirkinlik ve acılarına rağmen. Sevgili, sevmek, gülmek... Belk...', ARRAY['Türk Edebiyatı','Şiir','Murat Polat 2']::text[], 8.5, '{"poet":"Murat Polat 2","poet_slug":"murat-polat-2","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/dogum-gunu-61-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duygu Denizi', 'duygu-denizi-sebahattin-kacar-dgqgz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hani bir sabah uyanıp, 

Gözlerimizi taa uzaklara dikmiştik. 

Sen dünyanın bir ucunda, 

Ben dünyanın öbür ucunda. 

Ben seni arardım, 

Sen de beni. 

Buluşabilme arzusu sarardı içimizi. 

Senden bir koku, 

Bir haber, 

Bir ses, 

Bir selam 

Gelecek mi diye 

Görebileceğimi sandığım yere kadar 

Bakıp kalmıştım. 

Ayrılık, ah yaman ayrılık. 

Arada dönüp yine bakarım, 

Senin de baktığını bilerek…

Sen sanki güneş, 

Ben senden kopan ay. 

Sen uçan kuşların altın kanadı, 

Ben sana yetişecek rüzgar. 

Sen gökten düşen bir damla, 

Ben seni bekleyen çorak toprak. 

Sen destanlar yazdıran, 

Cennet bahçelerinin süsü, 

Nadide bir gül, 

Ben kokunu getirecek rüzgarı 

Bekleyen bülbül. 

Senin gözlerinin rengi, 

Denizlerden, gökyüzünden de mavi, 

Bütün yeşilliklerden daha yeşil, 

Benim seni arayan gözlerim, 

Ağlamaktan, umutsuzluktan katran karası. 

Sen, cümle alemi hayrete koyacak kadar güzel, 

Ben ferhat’a yoldaş, ben mecnun’a adaş, 

Alemi hayrette koyacak kadar virane. 

De cananım, 

Leyla’dan geçme faslındayım. 

Baktığım her yerde 

Gördüğümü sandığım sen, 

Artık hep ben. 

İçimi kavuran, 

Cayır cayır yakan o özleme sebep 

Artık Ben. 

Seninle ezelde sözleştiğimiz gibi 

Seni içimde bulan Ben. 

Bir bende buluşan ben. 

Artık hep Ben, 

Hep ben. 

Aynada bakınca gördüğüm sen 

Yine ben. 

Yağmur olmak için dolaşan bulutlar, 

Ben denizinden, 

Duygu denizinden.', 'Hani bir sabah uyanıp,  Gözlerimizi taa uzaklara dikmiştik.  Sen dünyanın bir ucunda,  Ben dünyanın öbür ucunda.  Ben seni arardım,  Sen de ...', ARRAY['Türk Edebiyatı','Şiir','Sebahattin Kacar']::text[], 8.5, '{"poet":"Sebahattin Kacar","poet_slug":"sebahattin-kacar","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/duygu-denizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Döndür Beni', 'dondur-beni-murat-polat-2-770db', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Unutmuştum sevmeyi

Dokunmaya sevgiliye.

Unutmuştum gülmeyi

Şöyle içten gülmeyi.

Nasılda kandırmışım kendimi

Hep rolle, alkolle

Bitti mi Allah’ım bu kabus? 

Döndür artık beni gerçeğe.', 'Unutmuştum sevmeyi Dokunmaya sevgiliye. Unutmuştum gülmeyi Şöyle içten gülmeyi. Nasılda kandırmışım kendimi Hep rolle, alkolle Bitti mi Alla...', ARRAY['Türk Edebiyatı','Şiir','Murat Polat 2']::text[], 8.5, '{"poet":"Murat Polat 2","poet_slug":"murat-polat-2","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dondur-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönemiyorum', 'donemiyorum-murat-polat-2-dawf9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Öyle karışık ki duygularım

Bir düğüm oldu.

Öyle anlamsız ki her şey

Sanki bir bir sır oldu.

İşte öyle bir an..

Taşıyorum nedensiz

Aştım yine kendimi

Onu arıyorum ümitsiz.

Kendimi arıyorum! 

Bulamıyor kayboluyorum.

Dönemiyorum...

                                                                               

                     07/03/1986

          (o doğdu bugün, ben cansız)', 'Öyle karışık ki duygularım Bir düğüm oldu. Öyle anlamsız ki her şey Sanki bir bir sır oldu. İşte öyle bir an.. Taşıyorum nedensiz Aştım yine...', ARRAY['Türk Edebiyatı','Şiir','Murat Polat 2']::text[], 8.5, '{"poet":"Murat Polat 2","poet_slug":"murat-polat-2","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/donemiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorular? ? ?', 'sorular-meram-yalinizoglu-shw9w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Her anını benimle geçirmek istedin mi? 

Ya hep gözlerimde kendini görmek için çırpındın mı? 

Asırlarca gözlerime hiç gözünü kırpmadan bakabilir misin? 

Sesimi her an duymak için,

Uzun süre telefon başında beni aramaya uğraştın mı? 

Telefonda konuşurken kapamak sana ölüm acısı verdi mi? 

Yanından gitmeyim diye ateşlere kaldın mı? 

Kokumu, içine taa derinlerine çekip ciğerlerinin,

İçinden çıkmasın diye nefesini tuttun mu? 

Mutluluğumla mutlu olup,

Üzüntümle sende kahırlandın mı? 

Ya da,

Beni mutlu etmek için varını yoğunu ortaya koydun mu? 

Bana varmak için 

Yürümek yerine tüm hızınla koştun mu? 

Yanında olmadığım anlarda; 

Ne yapıyor, ne düşünüyor diye kafanı yordun mu? 

Seni düşünmediğimi düşünüp,

İçinin kor kor yandığı oldu mu? 

Kalbinin sızladığı oldu mu? 

Beni aklından hiç çıkarmadığın,

Ve hiç çıkaramayacağına inandığın? An dahi? 

Her şeyde beni buldun mu? 

İçtiğin çay, su, yediğin yemek, 

Dumanını ciğerlerine doldurduğun

Sigaran oldum mu? 

Oturduğun yerde,

Yürüdüğün yolda,

Baktığın her yerde

Benim sana gülen yüzümü gördün mü? 

Dünyanda ben olmazsam 

Yaşamanın sana çok acı geleceğini hissettin mi? 

Hiç düşündün mü? 

Benimleyken tereddütlerin hiç oldu mu? 

Kaygıların? 

Korkuların? 

Benim için nelerden vaz geçebileceğini

Hiç sıraladın mı aklında? 

Olmazsa olmazlarını bile bırakıp

Onların yerine beni koyabileceğine inandın mı? 

Ve onlardan çok daha fazla 

Olmazsa olmazın olduğuma yürekten inandın mı? 

Gecenin karanlığında gökyüzüne yıldızlara bakıp

O karanlığı benim yüzümü hayal ederek,

Aydınlattın mı gözlerinde, hayalinde? 

Ya da gündüz

Güneşe bakıp; 

Benim daha parlak, daha yakıcı olduğumu 

Geçirdin mi içinden? 

Benim varlığımın sana hayat

Yokluğumun ölüm olduğuna inandın mı? 

Beni kaybetme korkun

Gündüz uyanıkken dahi kabusun oldu mu? 

Hayattaki en büyük tek kaygın

Benim seni bırakma ihtimalim oldu mu? 

Bunu her düşündüğünde

Kalbine binlerce bıçağın saplandığını hissettin mi? 

Beni tanıdıktan sonra; 

Bensiz hayatı yaşayamıyacağını

Ruhun, bedenin, kalbin, gözlerin, ellerin,

Haykıra haykıra sana söyledi mi? 

Yüreğinin ne kadarını avuçlarıma bırakabilirsin? 

Beni ne kadar hak ettiğini hiç düşündün mü?', 'Her anını benimle geçirmek istedin mi?  Ya hep gözlerimde kendini görmek için çırpındın mı?  Asırlarca gözlerime hiç gözünü kırpmadan bakabi...', ARRAY['Türk Edebiyatı','Şiir','Meram Yalınızoğlu']::text[], 8.5, '{"poet":"Meram Yalınızoğlu","poet_slug":"meram-yalinizoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":63,"source_url":"https://www.antoloji.com/sorular-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilemezsin', 'bilemezsin-meram-yalinizoglu-ydwvd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Özlemi ilk seninle tattım

Bu acının hüznünü

Sensizliğin dayanılmaz yükünü

Bilemezsin seni ne çok özlediğimi

Gözlerinin koyuluğunu

Ellerinin sıcaklığını

Sözlerinin yumuşaklığını

Bilemezsin seni ne çok özlediğimi

Her uykudan kalkışımda

Başımı her yastığa kıyuşumda

Yaşamımın her anında

Bilemezsin seni ne çok özlediğimi

Nefes almak bile anlamsız

Suyun serinliği, ateşin sıcaklığı

Kana kana özlem var sadece

Bilemezsin seni ne çok özlediğimi...', 'Özlemi ilk seninle tattım Bu acının hüznünü Sensizliğin dayanılmaz yükünü Bilemezsin seni ne çok özlediğimi Gözlerinin koyuluğunu Ellerinin ...', ARRAY['Türk Edebiyatı','Şiir','Meram Yalınızoğlu']::text[], 8.5, '{"poet":"Meram Yalınızoğlu","poet_slug":"meram-yalinizoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bilemezsin-50-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-serkan-asilbas-61fsg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen,

Ilık bir yaz akşamı,

Sevinç şarkıları söylemek,

Kumsalda çıplak ayakla dolaşmak,

Özgürce yaşamak gibiydin.

Sen,

Sevgiliye yazılan şiir,

Gönderilen mektup,

Gözlerine bakarak verilen gül,

Kulaklara fısıldanan sevgi sözcükleri gibiydin.

Sen,

Karanlıktaki aydınlık,

Rüyalardaki gerçek,

Resimlerdeki sonsuzluk,

Hiçbir zaman sönmeyen ateş gibiydin

Sen,

Dillerdeki melodi,

Gözlerdeki güzellik,

Nefeslerdeki sıcaklık,

Ve yüreklerdeki aşk gibiydin.

Sen,

Kışın yağan kar,

İlkbaharda açan çiçek,

Yağmurdan sonraki toprak kokusu,

Hayatın içindeki yaşama sevinci gibiydin.

Sen, hayatı anlamlı kılan herşeydin.', 'Sen, Ilık bir yaz akşamı, Sevinç şarkıları söylemek, Kumsalda çıplak ayakla dolaşmak, Özgürce yaşamak gibiydin. Sen, Sevgiliye yazılan şiir,...', ARRAY['Türk Edebiyatı','Şiir','Serkan Asılbaş']::text[], 8.5, '{"poet":"Serkan Asılbaş","poet_slug":"serkan-asilbas","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sen-705-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Susuyorsun', 'susuyorsun-atilla-kucukala-4qwr0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yolunda çok gölgeler öptü ayaklarımı

hep bir başkasının

ayak izlerinden yürüdüm

senin ardından 

sevgi filmine geç kalan

derme çatma bir koltuğa

oturmaya zorlanan o seyirci

hep ben oldum

alışkanlıklar pazarında

sevgi satansa sendin

sana kim inanır artık

sarı saçlı esmer kadın,

dudaklarından

kaç gece çıkar

bilemezsin

ama susuyorsun

onca sessizlik arasında

tek senin sessizliğinin depremi

titretiyor yüreğimi

güzelliğinin bende saklı tohumlarını

avucumdan alacakaranlıklara

savurdun ya

bir kırmızı toprağın akrabasıdır

artık ellerin

ellerin

öpülemeyecek kadar

ölüdür biliyor musun? 

ama ben öpüyorum

dudaklarımda

ilk yağmur sonrası toprağı

gözlerimin kaçkını

iki damla yaşın ortağı

sen susuyorsun

çıkınımda yüreğimi taşıyorum ben yine

azalmış sevgilere azık diye

sonradan görme suratlarında

                               yüreğimin

sakallaşmış sevgiler büyütüyorum

sen yüreğime jilet atıyorsun

her sabah

ben sana kanıyorum

birden rütbeleşiyor yüzün

gözlerin

bildik bir karakter kumandanı

susuyorsun ya 

ben çekip gidiyorum

iki çatılmış kaş oluyor ayaklarım

ısmarlama haykırışlar buluyorum yollarında

biliyorum hiç gelmedin

ama şimdi gidiyorsun

birden rütbeleşiyor yüzün

bana hüzünler emrediyorsun

sen yine susuyorsun ya

ben duyuyorum

uzak iklimlerin sonrasında

yüreğimin

bir umut parçalarına

basarak geçeceksin

sevgi selini

etme

dinle beni

bu güneş

ikimizi ayrı ayrı ışıtmaya yetmez

gel damarlarında pişmanlık yağlarını biriktirme sen

yüreğim ikimize de yeter', 'Yolunda çok gölgeler öptü ayaklarımı hep bir başkasının ayak izlerinden yürüdüm senin ardından  sevgi filmine geç kalan derme çatma bir kolt...', ARRAY['Türk Edebiyatı','Şiir','Atilla Küçükala']::text[], 8.5, '{"poet":"Atilla Küçükala","poet_slug":"atilla-kucukala","theme":"Türk Şiiri","is_hero":false,"total_lines":65,"source_url":"https://www.antoloji.com/susuyorsun-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kardelen', 'kardelen-cem-han-17s4s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Günün ortasında her yer kararmışsa,

Fırtınaların çığlıkları dünyayı sarmışsa,

Havanın soğukluğu ve korkuların içini titretmişse

Sevdiğinden umduğun cevabı alamamışsan,

Duyguların yağan kar tipisiyle harmanlaşmışsa,

Yeryüzünde beyazdan başka renk görünmüyorsa,

Telaşlanma sevgilim! ! ! 

Elbette açacak Kardelen,seni mutlu etmek için.', 'Günün ortasında her yer kararmışsa, Fırtınaların çığlıkları dünyayı sarmışsa, Havanın soğukluğu ve korkuların içini titretmişse Sevdiğinden ...', ARRAY['Türk Edebiyatı','Şiir','Cem Han']::text[], 8.5, '{"poet":"Cem Han","poet_slug":"cem-han","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kardelen-81-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecekondu', 'gecekondu-atilla-kucukala-isw2k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Koca kent

bir tepenin

yolunda yoruluyor', 'Koca kent bir tepenin yolunda yoruluyor...', ARRAY['Türk Edebiyatı','Şiir','Atilla Küçükala']::text[], 8.5, '{"poet":"Atilla Küçükala","poet_slug":"atilla-kucukala","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/gecekondu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm Orucu', 'olum-orucu-atilla-kucukala-iix2n', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Karanlıklar oturmuş

yasaların balkonuna 

akşamları örüyordu

iki ışık

gökyüzünü çıkardı

ölümün cebinden', 'Karanlıklar oturmuş yasaların balkonuna  akşamları örüyordu iki ışık gökyüzünü çıkardı ölümün cebinden...', ARRAY['Türk Edebiyatı','Şiir','Atilla Küçükala']::text[], 8.5, '{"poet":"Atilla Küçükala","poet_slug":"atilla-kucukala","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/olum-orucu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya Malı', 'dunya-mali-i-rfan-kayagil-6e0ju', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dünya malı hepsi yalan

Biter ömür nedir kalan

Belki bu gün iyi yaşar,

Hesap verir bir gün, çalan

x

Sevgi bize içten gerek

İnsanlığa yüce erek

Dost olurduk yılanla

Yalansız, olsa engerek

x

Saymayın kalan günleri ömürden

Örümcek ağına takılınca beden

Takvim yaprakları gibi düşer 

Zamanını bilmez ki beşer

x

İyilik  yap, bir gün kıymeti bilinir,

Kötü isen, namın çabuk silinir.

Ne mezarlar doldu kötülerle, 

Nefretle anılır.

Kefenin cebi olsa, ne götürülecek sanılır.

Zenginin borusu ötmez o gün

Mahşer duyar ki, sur çalınır.

x

Kusur yaratan da değil kuldadır.

Gönülden inanırsan hidayet yoldadır

Özünde ara her şeyi

Mutluluk ne parada ne puldadır.', 'Dünya malı hepsi yalan Biter ömür nedir kalan Belki bu gün iyi yaşar, Hesap verir bir gün, çalan x Sevgi bize içten gerek İnsanlığa yüce ere...', ARRAY['Türk Edebiyatı','Şiir','İrfan Kayagil']::text[], 8.5, '{"poet":"İrfan Kayagil","poet_slug":"i-rfan-kayagil","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/dunya-mali-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüştük', 'gulustuk-atilla-kucukala-oxrlb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şimdi bizi 

bir sokak çocuğunun gülüşü ayırabilir,

ayrı mutluluklara tuzak diye

ağlayabiliriz unutulmayışına

o nedensiz gülüşümüzün,

nedensiz taşırız tozlarını

karanlığımızı çırptığımız 

o son kavşağın,

yürürüz dostluğun

dönülmeyecek iki ayrı sokağında

adımlarımızı büyültürüz,

yüreklerimizi küçültmek için

düşeriz bir gülüşün yoluna,

çünkü biz artık 

sararmış albümleri taşımalıyız içimizde

eski bir türkü gibi söylemeliyiz adlarımızı

içten ve uzak,

ne çiçekler topladım senin için

kabuk bağlamış yaralar tarlasından

bir sana kokmayacak,

herşeydin

papatya gülüşünle sen,

az kazısam şimdi

dallanmış endişen,

senin adını bilmeyen

sevinçlerimi sulamalıyım yarın

yoksa çürürler umarsız

köküne su verilmemeli

kuruyan dalların,

beklersek sularımız da tutuşacak

yangından kaçan

iki karıncanın telaşıyla

kaçmamız gerek şimdi

dürüst ayaklarımızla bu sevgiden

kalırsak ellerimiz kirlenecek

sonra, kötü kokacak saçlarımız

bir karanfil ölecek 

düşümüzün yastığında,

artık üzülmek

yüreğimizi köze düşürmez ki bizim,

gidersek

bir gülüşün ayırdığı uçlara gideriz

gidelim', 'Şimdi bizi  bir sokak çocuğunun gülüşü ayırabilir, ayrı mutluluklara tuzak diye ağlayabiliriz unutulmayışına o nedensiz gülüşümüzün, nedensi...', ARRAY['Türk Edebiyatı','Şiir','Atilla Küçükala']::text[], 8.5, '{"poet":"Atilla Küçükala","poet_slug":"atilla-kucukala","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/gulustuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolculuk', 'yolculuk-fatma-guven-mnwro', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güneyin,doğuda kesiştiği noktada,

Yüreğin kaldıramadığı yükü omuzlayıp,

Bir derin nefesi doldurup ciğerlere,

Yürü dedim kendime.

Bu yıkılışın,yalnızlığın yengi değil.

Bir adım daha at,

Güven kendi benliğine.

Dostlarının sevgisini çıkınla,

Koy gurbet heybesine.', 'Güneyin,doğuda kesiştiği noktada, Yüreğin kaldıramadığı yükü omuzlayıp, Bir derin nefesi doldurup ciğerlere, Yürü dedim kendime. Bu yıkılışı...', ARRAY['Türk Edebiyatı','Şiir','Fatma Güven']::text[], 8.5, '{"poet":"Fatma Güven","poet_slug":"fatma-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yolculuk-103-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gölgelerin Göz Yaşları', 'golgelerin-goz-yaslari-aylin-onder-5lc8y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gölgelerin göz yaşlarına basa basa gittin.

Alışılmışlığın ancak ok yarası olabilir,

Bir daha hiç tadamayacağım, figan adın.

Saçlarının karası ay ışığını sevdirdi,

Şimdi yarasalar bile düşmanın...

Ne uzun bir varoluş.

Kalbinin atışını duyamadığım uzaklık azap.

Ne çınarlar kök saldı gönlümüze bunca sene,

Ve nasıl sevildik ki; 

Çöllerde güller yetişmesiyle rastlanır benzerine.

Sinende buldum kendimi,

Sinemde ömür bildi seni.

Gölgelerin göz yaşlarına basa basa gittin.

Alışılmışlığın ancak ok yarası olabilir,

Bir daha hiç tadamayacağım, figan adın.

Gözlerinin mavisi denizleri sevdirdi, 

Şimdi yunuslar bile sana dargın...', 'Gölgelerin göz yaşlarına basa basa gittin. Alışılmışlığın ancak ok yarası olabilir, Bir daha hiç tadamayacağım, figan adın. Saçlarının karas...', ARRAY['Türk Edebiyatı','Şiir','Aylin Önder']::text[], 8.5, '{"poet":"Aylin Önder","poet_slug":"aylin-onder","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/golgelerin-goz-yaslari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mecalim yetmez', 'mecalim-yetmez-ali-galip-sari-y5dyi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sana benzemeye benzerim ya ben,

Gözlerin olmaya mecalim yetmez...

Başkası şair der adıma; yalan! 

Sözlerin olmaya mecalim yetmez...

                     11.12.2005/Ankara', 'Sana benzemeye benzerim ya ben, Gözlerin olmaya mecalim yetmez... Başkası şair der adıma; yalan!  Sözlerin olmaya mecalim yetmez...         ...', ARRAY['Türk Edebiyatı','Şiir','Ali Galip Sarı']::text[], 8.5, '{"poet":"Ali Galip Sarı","poet_slug":"ali-galip-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/mecalim-yetmez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Böyleyim', 'ben-boyleyim-hasan-can-mk4h7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gidiyorum...

Ne unuttuysam geride,

Sende kalsın,

Sakın gözlerime bakarken,

Gözlerin yaşarmasın,

Alt tarafı geldim ve gidiyorum.

Geldiğimde nasıl güldüyse gözlerin,

Giderkende öyle olmalı,

Gülmelisin, sana yakışan bu.

Evet güzel anılarımız oldu seninle,

Delice sevdik birbirimizi,

İyi gün kötü gün,

Yaşadık aşka ait ne varsa.

Bazen kaybettiklerime beraber üzüldük,

Yitip giden hayallerine ağladık,

Görmezden geldik bazı şeyleri.

Sahilde yürüdük el ele,

Çimenlere uzandık ve başını göğsüme yasladın,

Aşk şarkıları söyledik karanlık gecelerde,

Sevgi sözcükleri fısıladadık birbirimize,

Sevdik en büyüğünden,

Deli dolu günlerimiz oldu seninle

Evet haklısın yaşadık aşkı en iyi şekilde.

Ama gidiyorum, sakın birşey sorma.

Gidiyorum...

Ardıma bakmayacağım,

Görmek istemiyorum üzüldüğünü,

Biliyorum unutursun günün birinde,

Sakın ağlama, geçer birgün acın ve nefretin.

Belki birgün yine karşılaşırız,

Ve hesaplaşmak istersin,

İçinde birikmiş ne varsa söyleyebilirsin.

Beni hakir gör,

Ben böyleyim...', 'Gidiyorum... Ne unuttuysam geride, Sende kalsın, Sakın gözlerime bakarken, Gözlerin yaşarmasın, Alt tarafı geldim ve gidiyorum. Geldiğimde n...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/ben-boyleyim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekliyorum', 'bekliyorum-fatma-guven-2vhjb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yüreğimde ateş,avuçlarımda umut,

Tüm hücrelerimde,

Yaşam kavgası var.

Sevda yüklüyüm can dost,

Öfke doluyum.

Damlalarını boşaltmaya hazır,

Yağmur damlaları gibi,

Kopacak fırtınayı bekliyorum.', 'Yüreğimde ateş,avuçlarımda umut, Tüm hücrelerimde, Yaşam kavgası var. Sevda yüklüyüm can dost, Öfke doluyum. Damlalarını boşaltmaya hazır, Y...', ARRAY['Türk Edebiyatı','Şiir','Fatma Güven']::text[], 8.5, '{"poet":"Fatma Güven","poet_slug":"fatma-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bekliyorum-93-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Final', 'final-mehmet-dogan-8-ybxyn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Fırtınalar içinde 

Boğuşmaktan yorgunum

Göğsüne sığınayım	 

Öyle duygusalım ki bügün

Ağlasammı gülsemmi bilemiyorum

Sıkıldım buralardan 

Seninle dağlara göçsem

Yağmurların altında 

Sırılsıklam öpüşsek sevişsek

İliklerime kadar titresem 

Duyularım körelirse 

Uyar beni 

Çimdik 

Diş istiyorum

Biraz heyecan hırs 

On sekizlik güç ellisinde olmaz mı 

Olsun

Bir rüya macera diyelim

Fındığı cevizi takma dişle kırmak bu mu

Bilemiyorum 

Ben aynaya bakmak 

Kendimle yüzleşmek istiyorum 

Gördün mü

Alnında derin izler

Göz etrafı mor halkalar

Şakakların etekleri firarî kırlar 

Ayaklarının altından akmış seneler 

İşte sonunda pamuk dedesin 

Aynadaki adam 

Ne diyeceksin 

Bir elime baston 

Koluma seni istiyorum 

Bizden geçmiş 

Geçmiş güzel karıcığım 

Oğlanları everelim 

Gelinler istiyorum 

Yanımda yöremde torun 

Torunlar 

Dilencilere benzedim be 

Ne çok istiyorum 

Varsa eğer kaderde 

Son yazmadan önce perde 

Hep beraber el ele 

Finali görmek istiyorum', 'Fırtınalar içinde  Boğuşmaktan yorgunum Göğsüne sığınayım	  Öyle duygusalım ki bügün Ağlasammı gülsemmi bilemiyorum Sıkıldım buralardan  Sen...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Doğan 8']::text[], 8.5, '{"poet":"Mehmet Doğan 8","poet_slug":"mehmet-dogan-8","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/final-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağladığım Saat', 'agladigim-saat-fatih-demir-cbnn1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gecenin karanlığı bastığı zamanda

Hani geceleri ağladığım saat varya! 

Yüreğim derinden sızlar o anda

Hani geceleri ağladığım saat varya! 

Durmadan seni, düşünürüm deli gibi

O zaman içim inler udun teli gibi

Gözden akan olur yağmur seli gibi

Hani geceleri ağladığım saat varya! 

Yanlızlık çaresizlik çöker üstüme

O an bir türlü uyku girmez gözüme

Bütün dertler hücum eder beynime

Hani geceleri ağladığım saat varya!', 'Gecenin karanlığı bastığı zamanda Hani geceleri ağladığım saat varya!  Yüreğim derinden sızlar o anda Hani geceleri ağladığım saat varya!  D...', ARRAY['Türk Edebiyatı','Şiir','Fatih Demir']::text[], 8.5, '{"poet":"Fatih Demir","poet_slug":"fatih-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/agladigim-saat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vakti gelince...', 'vakti-gelince-ali-galip-sari-momnz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Takvimler eskiten bir sevda düşün,

Vazgeçip gitmenin vakti gelince...

Her hüznü bir ömre bedel olandan,

Acıtan,inciten... değiverince...

Sonra istersen sen, gidersin gülüm,

Bütün lügatlerin sustuğu anda,

Bir katre olmak mı, zor şey sevmeden,

''''Yunuslar'''' yüzdüren dipsiz ummanda! 

                                                      11.12.2005/Ankara', 'Takvimler eskiten bir sevda düşün, Vazgeçip gitmenin vakti gelince... Her hüznü bir ömre bedel olandan, Acıtan,inciten... değiverince... Son...', ARRAY['Türk Edebiyatı','Şiir','Ali Galip Sarı']::text[], 8.5, '{"poet":"Ali Galip Sarı","poet_slug":"ali-galip-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/vakti-gelince-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meriç''in Şiiri', 'meric-in-siiri-aynur-uluc-qgmym', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'işte, uzatıyorum kalbimi

her bir parçasını özenle kestim 

elim uzdur

ezber ettim doğramayı 

yeniden

yeniden çıkarıp gün ışığına 

tuzlu suda ovmayı 

ezber ettim 

gözlerim ışıdı

musalla taşında doğdum yeniden 

bir ebe sürme çekti gözlerime 

bir ebe ''meriç'' dedi

korkma dikiş tutmazsa

özgürlüğe dik

musallayı da boş ver

okyanusa sal göğsü kesik bedenimi', 'işte, uzatıyorum kalbimi her bir parçasını özenle kestim  elim uzdur ezber ettim doğramayı  yeniden yeniden çıkarıp gün ışığına  tuzlu suda ...', ARRAY['Türk Edebiyatı','Şiir','Aynur Uluç']::text[], 8.5, '{"poet":"Aynur Uluç","poet_slug":"aynur-uluc","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/meric-in-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Sana Mahkûm', 'ben-sana-mahk-m-ali-deniz-kaya-8k1wb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir sabah uyanmışım

Sensizliğin şafağına

Ellerimde gül dikenleri

Kollarıma takılmış bilezikler

Ve gözlerim…

Soğuk karanlıkta arıyor gözlerini

Sensiz güçsüz bacaklarım

Yürüyor beni uğultuların arasına doğru

Yanağımda parmaklıklar…

Ve bağırıyorum en kifayetsiz sözcükleri

Ben mahkûm edilmişim 

Sensiz geçen gecelere

Ve kurşun dizelenmiş böğrüme

Gardiyanın küfürlü sözcükleri

Kulağımda uğultu 

Ve sensin hayallerimde

Arıyor gözlerim gözlerini

Gökyüzünün bana gözüken en dip ucunda

Çıkıp geliyorum yanına… Çünkü

 Ben sana mahkûm edilmişim

Senden habersiz geçen soğuk gecelerimde

Çünkü ben idama mahkûm edilmişim

Umut ikliminde 

Bir feryat susun diye.', 'Bir sabah uyanmışım Sensizliğin şafağına Ellerimde gül dikenleri Kollarıma takılmış bilezikler Ve gözlerim… Soğuk karanlıkta arıyor gözlerin...', ARRAY['Türk Edebiyatı','Şiir','Ali Deniz Kaya']::text[], 8.5, '{"poet":"Ali Deniz Kaya","poet_slug":"ali-deniz-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ben-sana-mahkum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Sonradır', 'hayat-sonradir-hasan-maral-8ldkk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '“sonra…. Çok sonra gözyaşı olup akmak ta var bir yerlerden.”

Kara haberler damlıyor dudaklarından

Tam şuraya, kalbime! 

Bir deprem gibi gecenin bir yarısında

Acısız, kansız ve sessiz vuruyorsun beni

Enkazlar arasında bulunan bir ben yok

Nedense üç kıştır hiç üşümüyorum

Kaç kış sürecek bilmiyorum

Ama çok sıcak  günlerde

Senden soğuk kelimeler duyuyorum

Üşüyorum sonra, mevsim yaz

Sen çocukken seni düşlerimde seviyordum

Ama hep yediğim dondurmanın yarısı gibiydin

Birazdan eriyip gidecek gibi

Sarıldığım yastık sendin

Okulda defterimin üst kısmına sadece seni karalıyordum

Karnemde ilk beşim sendin ve galiba ilk kırığımda

Bir  kaç koca adam minik kelimelerle dövüyordu beni

Babandı, babamdı ve üç adamdı

Çünkü seni sevmem kulakları sağır ediyordu

“sevmeyeceksin onu” tamam baba

yalan söyledim  “seviyorum seni hala”

insanlar yıllar geçince büyüyordu

ama çocuklar tam beş yıl büyümüyordu

altıncı yılda kalpler büyüyordu

boş kalınca bu kalpler

hüzünler büyüyordu

eskiden gece ilk işim yatağa fırlamaktı

eskinin üzerinden biraz zaman geçti

yatak uzaklaştı benden, tıpkı sen gibi

gece ilerleyince uyku yerine seni uyuyordum

sabah ancak kalkabiliyordum senden', '“sonra…. Çok sonra gözyaşı olup akmak ta var bir yerlerden.” Kara haberler damlıyor dudaklarından Tam şuraya, kalbime!  Bir deprem gibi gece...', ARRAY['Türk Edebiyatı','Şiir','Hasan Maral']::text[], 8.5, '{"poet":"Hasan Maral","poet_slug":"hasan-maral","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/hayat-sonradir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anamın Gelini', 'anamin-gelini-mehmet-dogan-8-qzgyk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Takılı kaldın bakışlarıma

Göz bebeğimde dolanır durursun 

Oysa geceler boyu uykularım kaçkın 

Gözlerim mahmur 

Seni anıyorum seni 

Kucakladığım hasretim 

Kulakların çınlasın 

Bu hatıralar bu yadigârlar senin 

Oyalı yazma al mendil içinde mi 

Perçemindeki saç tellerin

Senelerimi bekleyen resmin güler uzaktan. 

Yaklaştım baktım da 

Senin allıkların, güzelliklerin yok mu

Hani maskara, rastık ojelerin

Paris ithali losyonların

Güzellik uzmanları 

Yörük çadırlarına  uğramaz mı 

Doğal ve yalın kalmışsın

Kalkık burun fındığa benzer mi 

Badem içi çekik gözlerin 

Kudretten sürmeli gezer 

Ok oktur kirpiklerin

Kıvrışır da geriye döner 

Kızken dudakların kiraz mı ezerdi 

Nedir o al al tetirler 

Kaşların hilâli hilâla eklesin 

Zülüf gölgesi gamzelerine düşer 

Ay tutulmaz mı 

Tutulsun anamın gelini 

Tutulsun! 

Bakışın yaman 

Duruşun yaman 

Gülümsemen anama benzer…', 'Takılı kaldın bakışlarıma Göz bebeğimde dolanır durursun  Oysa geceler boyu uykularım kaçkın  Gözlerim mahmur  Seni anıyorum seni  Kucakladı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Doğan 8']::text[], 8.5, '{"poet":"Mehmet Doğan 8","poet_slug":"mehmet-dogan-8","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/anamin-gelini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğimi Bırakıyorum', 'yuregimi-birakiyorum-fatma-guven-xa7my', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tut ki; yüreğimi bırakıyorum ellerine.

Yalansız,çıkarsız,riyasız.

Çiçeğe duyulan hayranlık,

Yağan yağmurun çiselemesi gibi.

Hazanda dökülen yaprağın hüznü gibi.

Tut ki; yüreğimi bırakıyorum ellerine,

Bir can,can olarak  sevebilesin diye.', 'Tut ki; yüreğimi bırakıyorum ellerine. Yalansız,çıkarsız,riyasız. Çiçeğe duyulan hayranlık, Yağan yağmurun çiselemesi gibi. Hazanda dökülen ...', ARRAY['Türk Edebiyatı','Şiir','Fatma Güven']::text[], 8.5, '{"poet":"Fatma Güven","poet_slug":"fatma-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yuregimi-birakiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Huzurmu batiyor', 'huzurmu-batiyor-husamettin-guven-6gwfq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne yapmadim ki soyle sana 

seni attim mi yabana

nasil olduda kiydin bana

soyle huzurmu mu batiyor

         buyuk sevk le bakiyorken 

         canim dan can katiyorken

         senin icin oluyorken

         soyle huzurmu batiyor

takdiri Allaha biraktim

seni ona havaal ettim

sense beni rezil ettin

soyle huzurmu batiyor', 'Ne yapmadim ki soyle sana  seni attim mi yabana nasil olduda kiydin bana soyle huzurmu mu batiyor          buyuk sevk le bakiyorken         ...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/huzurmu-batiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir rüya gibi yankılanır', 'bir-ruya-gibi-yankilanir-mehmet-selim-tolay-ig81r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Eğerki anlarsanız beni,

siz,gölgelerin ayak sesleri! 

anlamı dar ve sarp sokaklardan geçmekteyim.

İçimde bir güzellik ki anlatılmaz sanki bir doğum neş''esi

mutluluğun alemi mukaddesteki anlamlı güneşi

ve benliğime dolan hislerin bana getirdiği hamd sesleri

Şimdi o ses gelince bana

mehmet ali yankılanır bir rüya gibi 

işte sevinç işte mutluluk işte huzur

kanımızda canlılık ailemizde ferahlık

anlatılmaz yaşanır böylesi bir rahatlık

kare kare büyür içimizdeki vakur

mehmet alı yankılanır bir rüya gibi', 'Eğerki anlarsanız beni, siz,gölgelerin ayak sesleri!  anlamı dar ve sarp sokaklardan geçmekteyim. İçimde bir güzellik ki anlatılmaz sanki bi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Selim Tolay']::text[], 8.5, '{"poet":"Mehmet Selim Tolay","poet_slug":"mehmet-selim-tolay","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-ruya-gibi-yankilanir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cekilmiyor yalan dunya', 'cekilmiyor-yalan-dunya-husamettin-guven-dqya8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kime neyi anlatayim

Bu derdi kime satayim

Garip misim ben batayim

Cekilmiyor yalan dunya

Gece gunduz nedir bilmem

Boynum bukuk neden gulmem

Bir teselli veren bulmam

Cekilmiyor yalan dunya

Cok agirdir tasiyamam 

Bu dertle ben yasayamam

Gun gormeden gecti zaman

Cekilmiyor yalan dunya

Bir laf duydum ezdi beni

Taa derinden sarsti  beni

 Soke ederek uzdu beni

Cekilmiyor yalan dunya', 'Kime neyi anlatayim Bu derdi kime satayim Garip misim ben batayim Cekilmiyor yalan dunya Gece gunduz nedir bilmem Boynum bukuk neden gulmem ...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cekilmiyor-yalan-dunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Hüzünle Beslenir', 'sevgi-huzunle-beslenir-sultan-mustafa-wti68', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yıllar önce hüzünler sevgiyle harmandı

İnsan nice zaman bu harmanda yıkandı

Gün oldu hüzün öne geçti ağladı insan

Gün oldu sevgiyle doldu taştı ağlayan

Akan her gözyaşı ya sevgi ya hüzündür

Hüznün olmadığı yerde nefretler büyür

Bir nesil yetiştirdik melale yabancı

Biraz sefih biraz ayyaş biraz yalancı...

Dertliydi “melali anlamayan nesil”den

Ahmet Haşim de. Lakin kanundur ezelden

Sevgi hüzünle beslenir, hüzünle büyür

Hüznün olmadığı yerde sevgi de ölür.', 'Yıllar önce hüzünler sevgiyle harmandı İnsan nice zaman bu harmanda yıkandı Gün oldu hüzün öne geçti ağladı insan Gün oldu sevgiyle doldu ta...', ARRAY['Türk Edebiyatı','Şiir','Sultan Mustafa']::text[], 8.5, '{"poet":"Sultan Mustafa","poet_slug":"sultan-mustafa","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevgi-huzunle-beslenir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi Sabahlar', 'mavi-sabahlar-sultan-mustafa-mccx6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tutun biriniz elimden

Mavinin en karanlık noktasında

Denize atın beni

Mavilerle yıkanayım

Mavilerle arınayım

Yağmurlar mavi yağsın baharda

Karlar mavi düşsün saçlarıma

Mavice dağıtsın rüzgarlar

Sana perde bulutları

Ve sana dönüşüm

Mavi sabahlardan birinde olsun.', 'Tutun biriniz elimden Mavinin en karanlık noktasında Denize atın beni Mavilerle yıkanayım Mavilerle arınayım Yağmurlar mavi yağsın baharda K...', ARRAY['Türk Edebiyatı','Şiir','Sultan Mustafa']::text[], 8.5, '{"poet":"Sultan Mustafa","poet_slug":"sultan-mustafa","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/mavi-sabahlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünyâlar Tatlısı', 'duny-lar-tatlisi-timur-i-likan-4om9x', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevdim seni canım hep ölesiye

Olur mu ki aşkta hiç veresiye

Geldim kapına bir tanem sev diye

Doyulur mu ki hiç aşka sevgiye

Dünyâlar tatlısı canımsın benim

Canımın içinde cansın sevdiğim

Bedenimde akan kansın sevgilim

Doyulur mu ki hiç aşka sevgiye

Sevginle ben dolup dolup taştım

Nice engelleri hep seninle aştım

Sana kavuşana dek çok yol aştım

Doyulur mu ki hiç aşka sevgiye

Bir tek sensin benim arzum, emelim

Hüzünü, kederi kabre gömelim

Sevdâmızı kana kana içelim

Doyulur mu ki hiç aşka sevgiye

Bir tek günüm bile sensiz geçmesin

Senden başka bir eş gönlüm seçmesin

Aklından başka bir hayâl geçmesin

Doyulur mu ki hiç aşka sevgiye

(12 Aralık 2005/ İstanbul)', 'Sevdim seni canım hep ölesiye Olur mu ki aşkta hiç veresiye Geldim kapına bir tanem sev diye Doyulur mu ki hiç aşka sevgiye Dünyâlar tatlısı...', ARRAY['Türk Edebiyatı','Şiir','Timur İlikan']::text[], 8.5, '{"poet":"Timur İlikan","poet_slug":"timur-i-likan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/dunyalar-tatlisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Isyan ediyorum', 'isyan-ediyorum-husamettin-guven-jg6bw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Agliyarak ben dogmusum

Cilelerle yogrulmusum

Dert kupunde bogulmusum

Isyan ediyorum insanlara

Nede kara bahtim varmis

Kimse beni anlamazmis

Yavrularim garip kalmis

Isyan ediyorum insanlara

Sevgi saygi yitirilmis

Hatir gonul bitirilmis

Kahpelikler hak bilinmis

Isyan ediyorum insanlara', 'Agliyarak ben dogmusum Cilelerle yogrulmusum Dert kupunde bogulmusum Isyan ediyorum insanlara Nede kara bahtim varmis Kimse beni anlamazmis ...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/isyan-ediyorum-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kan, Kusmuk ve Aşk', 'kan-kusmuk-ve-ask-nermin-altindag-f9iz7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '... ne ben usta bir şairim

... ne sen uğruna aşk şiirleri yazılacak (kadar)    sevgili

İsmi olamayn birşeysin

Hem herşeyim

Hem hiçbirşeyim

-di''li geçmiş zamana terkettiğim hikayemsin

Üfürüklü gecelerin

Göğe açılan ellerinde

Küfürlerini dilime hapsettiğim

Hapsettiğim ve dilime işkence ettiğim

Lanetli ahitlerin

Bekçisine dair ettiğim beddularda

Şiirime takılmış

Eski bir hikayenin

Üçüncü tekil kişisisin

Kan, kusmuk ve aşk

Midesine ağırlık

Yuttuğu dana

Nesli tükenmiş kobranın

Hayalini

Çivilemeliyim dolunaya

Her sabah düşlerimi taciz eden

Her tacizde göğsümü terleten

Her tacizde cesedimi tepeleyen

Her öldüğümde yeniden dirilten

Tecavüz eden ve dirilten

Dirilten ve göbek bağımda

Boy verip yeşeren

Yeşerdikçe kusmuğuma kan karıştıran

Çoban yıldızının...

Hazmına muktedir değilim

Öldürdükçe dirilten

Bu aşkın mahreci

Süveydanın ipleriyle sürüklenen

Araftır

Midemde

ve bil cümle uzuvlarımda

Tepintisi

Yuttuğum

Devasa dananın

Aşk

İsmi lazım değil hanelerin

Kârsız semayesi

Tükürüklü gündüzlerin

Kesik bileklerinde

Bol bulamaç savurduğum

Aşk cümleciklerinin

Atasına

Hükümler verdiğim

Şiirime takılmış

Eski bir hikayenin

Üçüncü tekil kişisisin

-di''li geçmiş zaman hikayemsin...

Nisan 1999 Düzce/ Aralık 2005 Kadırga', '... ne ben usta bir şairim ... ne sen uğruna aşk şiirleri yazılacak (kadar)    sevgili İsmi olamayn birşeysin Hem herşeyim Hem hiçbirşeyim -...', ARRAY['Türk Edebiyatı','Şiir','Nermin Altındağ']::text[], 8.5, '{"poet":"Nermin Altındağ","poet_slug":"nermin-altindag","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/kan-kusmuk-ve-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-firat-ulker-ecqht', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Günün tam orta yerinde

Güneş battı 

Akşam oluyor gözlerimde

Karanlık bakışlarımın arasında

Sokak lambası oluyor

Hayata dair umutlarım

Zaman olmak istiyorum

Yaşananlara aldırmadan

Çekip gitmek istiyorum

Tükendikçe büyümek

Ve asla geri dönmemek için

İsyiyorum her şeyi içimde eritmek

Ama..,

Tüketemediğim bişey var içimde

Atıyorum uzaklara

Unutup,,

Her adımımla yok olmak istiyorum

Sonunda olduğum yere çakılıyorum

Fırlattığım duygular

Bumerang olup konuyor yüreğime

Her şeyi bıraktım geride

Kendimi,ailemi,alkolü ve de sigarayı

Lakin nefes almayı

İşte onu bırakamıyorum

Çünkü nefesi ciğerlerim değil

Yüreğim alıyor

Alınan her oksijen

İçimdeki seni besliyor

Sen ne kadar beni kirletsende

Bana ne kadar acı çektirsende

Seni yaşatıyorum

Seni yaşayarak içimde

Sence hangimiz ölür önce

Bence..,

Hiç kimse..

                                      12.12.04/00-54', 'Günün tam orta yerinde Güneş battı  Akşam oluyor gözlerimde Karanlık bakışlarımın arasında Sokak lambası oluyor Hayata dair umutlarım Zaman ...', ARRAY['Türk Edebiyatı','Şiir','Fırat Ülker']::text[], 8.5, '{"poet":"Fırat Ülker","poet_slug":"firat-ulker","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/zaman-269-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanrı'' ya Olan Sevgimden..', 'tanri-ya-olan-sevgimden-zeliha-bicer-aecj8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Biriktirdim içimde 

Ne varsa yaşamdan.

Taşıdım kendimce,

Mutluluğu,mutsuzluğu

Çaresizliği,aşkı sevdayı

Hüznü,sevinci

Bunca yüke rağmen

Kamburlaşmadı sırtım

Çünkü...

Tanrı'' ya olan sevgimdi

Kuvvetimin temeli...', 'Biriktirdim içimde  Ne varsa yaşamdan. Taşıdım kendimce, Mutluluğu,mutsuzluğu Çaresizliği,aşkı sevdayı Hüznü,sevinci Bunca yüke rağmen Kambu...', ARRAY['Türk Edebiyatı','Şiir','Zeliha Bicer']::text[], 8.5, '{"poet":"Zeliha Bicer","poet_slug":"zeliha-bicer","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/tanri-ya-olan-sevgimden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Susmalarım Sana Değil', 'susmalarim-sana-degil-zeliha-bicer-t9o36', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Susmalarım, sana değil

Belki, kendime çoğu zaman

Belki de geçmesini istemediğim

Zamana..

Susmalarım, sendeki ben belki

Böyle suskunlarımda

Anlar mısın beni? 

Elimi tutar mısın zamansız? 

Kimbilir 

Belki bu zamanlarda

Alır mısın beni duygularına?', 'Susmalarım, sana değil Belki, kendime çoğu zaman Belki de geçmesini istemediğim Zamana.. Susmalarım, sendeki ben belki Böyle suskunlarımda A...', ARRAY['Türk Edebiyatı','Şiir','Zeliha Bicer']::text[], 8.5, '{"poet":"Zeliha Bicer","poet_slug":"zeliha-bicer","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/susmalarim-sana-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Insanligin gozu doymaz', 'insanligin-gozu-doymaz-husamettin-guven-wavui', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Iyi dusun para herseyi almaz

Bu dunya kimseye kalmaz

Hic bir zaman kefenler cepli olmaz

Nedense insanligin gozu doymaz

Parayi goc sanip aldanma sakin

Olum insana nefden yakin

Sukretmez dunyayi ustune yapin

Nedense insanligin gozu doymaz

Soyleyim ben sana bu dunya fani

Hasta olup dusersin yataga yani

Pismanlik duymadan gel degis gayri

Nedense insanligin gozu doymuyor', 'Iyi dusun para herseyi almaz Bu dunya kimseye kalmaz Hic bir zaman kefenler cepli olmaz Nedense insanligin gozu doymaz Parayi goc sanip alda...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/insanligin-gozu-doymaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçırma Gözlerini', 'kacirma-gozlerini-adem-aktas-yazgibozan-2iyz0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dünya yıktı beni, büktü boynumu iki büklüm

ardına bile bakmadı giderken…

Bak..! iyi bak gözlerime

Artık yeniliyorum kaçırma gözlerini

Bazen buruk bir sevinçte

Bazen anlamlı sanılan ucuz kelimelerdeymiş 

Hayat; 

Bazen de bir kalemin ucundaymış….

Yakışıksız dünyaya yine yakışıksız bir güneş

Ve ardından o yakışıksız dünyada 

Yine yakışıksız bir ben…

Yaşlanıyorum galiba

Milim milim eriyor kemiklerim

Milim milim iniyor perde gözlerime,

Ama sen bak gözlerime,iyi bak

Kaçırma yalvarırım gözlerini

Saçlarımdaki her ak, tertemiz ve pak

Alın teri anlıyor musun..? 

Belki kalemin ucundaki hayatı yakalayamadım

Belki elimdeki yılları harcadım 

Hafta hafta,ay ay, yıl yıl…

Belkide beni hatırlayacak bir dünya bırakamadım

Ama sen yine de bak gözlerime olur mu,

Kaçırma gözlerini yatağımın yarısı..

Gözlerin gözlerimde öleyim 

öleceksem de…', 'Dünya yıktı beni, büktü boynumu iki büklüm ardına bile bakmadı giderken… Bak..! iyi bak gözlerime Artık yeniliyorum kaçırma gözlerini Bazen ...', ARRAY['Türk Edebiyatı','Şiir','Adem Aktaş Yazgıbozan']::text[], 8.5, '{"poet":"Adem Aktaş Yazgıbozan","poet_slug":"adem-aktas-yazgibozan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/kacirma-gozlerini-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat mı..?', 'hayat-mi-adem-aktas-yazgibozan-airrt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayat; 

Evrenin faniliğini kendine yedirebildiğin kadar güzeldir..', 'Hayat;  Evrenin faniliğini kendine yedirebildiğin kadar güzeldir.....', ARRAY['Türk Edebiyatı','Şiir','Adem Aktaş Yazgıbozan']::text[], 8.5, '{"poet":"Adem Aktaş Yazgıbozan","poet_slug":"adem-aktas-yazgibozan","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/hayat-mi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değişik', 'degisik-ahmet-sefer-kocer-jxrzd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gene sahne aldı hinoğlu hinler

Oyun aynı piyonları değişik

Bu nasıl bayram ki kusulur kinler

Hedef aynı silahları değişik

Gene aynı çaput, aynı paçavra

Hep aynı slogan, aynı palavra

Barış der, dostluk der hep vura kıra

Hesap aynı mizanları değişik

Sabah vurur, akşam çıkar ekrana

Hemen arka çıkar üç beş kokana

Aslında gerçeği bilen çok ama

Gerçek aynı, sunanları değişik

İnsan haklarından dem vura vura 

Hesap veriyoruz dinsiz gâvura

Vatana ihanet moda bu sıra

Düşman aynı yalanları değişik

       -1996-', 'Gene sahne aldı hinoğlu hinler Oyun aynı piyonları değişik Bu nasıl bayram ki kusulur kinler Hedef aynı silahları değişik Gene aynı çaput, a...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Sefer Kocer']::text[], 8.5, '{"poet":"Ahmet Sefer Kocer","poet_slug":"ahmet-sefer-kocer","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/degisik-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ara Alem', 'ara-alem-firat-ulker-6ttxb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Düşlerin gerçek olması mıdır hayat

Yoksa hayatımız mıdır düş

İkisini de birbiri içinde yaşıyorum

Gözlerim açık uyuyorum

Rüyamda sen varsın

Dudaklarını öpüyorum

Tanrım sanki gerçek

Tenini hissedebiliyorum

Dokunuşlarını sayabiliyor

Saçlarını okşuyabiliyor

Ellerini tutabiliyor

Gözlerine de bakabiliyorum

Ve ben bütün bu olanları

Sanal ve gerçek alemde 

Aynı anda yaşayabiliyorum

Sanki olayları çifter çifter yaşıyorum

Sanki tekrar yapıyorum

Yaşadıklarımı unutmamak için

Şimdi martılar uçuşuyor

Sonsuz maviliğe beyaz benekler serpilmiş gibi

Dalgaların sesi geliyor

Emanet köpükleri

Sahile bırakıp geri dönerken

Bir gemi yanaşıyor kıyıya

İçinden insanlar iniyor

Her biri ıslak kumlara

Binlerce iz bırakıyor

Sanki mutluluğun imzasını atıyorlar sahile

Ama deniz

Silip götürüyor bütün izleri

Mutluluğu da alıp götürüyor derinlerine

Deniz canlılarına armağan ediyor her birini

Güneş şimdi battı

Kızıla boyandı etraf

Her yer yakamoz

İçtiğim sigaraları teker teker denize atıyorum

Gitar var elimde

Sahilde bir ateş yanıyor

Ateşin yanında bir şarap

Bir de esmer ıslak vücudun

Uzanıyoruz kumlara

Karışıyoruz birbirimize

Bir rüya gibi değil mi

Yoksa gerçek mi

Ayırt edemiyorum

Uyanmak ya da uyumak istemiyorum

Arada bir yerde

Sanal ve gerçeğin dışında

Ayrı bir alemde

Sonsuza dek

Seninle sevişmek istiyorum..

                                                           09.11.02/23:00', 'Düşlerin gerçek olması mıdır hayat Yoksa hayatımız mıdır düş İkisini de birbiri içinde yaşıyorum Gözlerim açık uyuyorum Rüyamda sen varsın D...', ARRAY['Türk Edebiyatı','Şiir','Fırat Ülker']::text[], 8.5, '{"poet":"Fırat Ülker","poet_slug":"firat-ulker","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/ara-alem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çakıl Taşları', 'cakil-taslari-i-rfan-kayagil-3tjre', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sert ve sağlam durur çakıl taşları

Oysa her bastığınızda nasılda kaypak

Savrulurlar dört bir yana yok ki başları.

Yine de serttir çakıl taşları başlarına buyruk

Hep ses çıkarırlar ezildikçe

Bir işe yarar mı bu, sizce? 

Duymaz kimse seslerini,

Ne üst üste durabilirler sağlamca

Ne yan yana arkadaşça.

Bu yüzden kıymetsizdir çakıl taşları

Oysa bir kürek çimento 

Bağlar onları biribirlerine

Nice yapıların temelidir onlar

Bunu yapan birleştirici unsurlar.

Tek başlarına ne de kıymetsizdir 

Bu taşlar,

Bütün güç birlikle başlar,

Nice eserlerin temelidir çakıl taşları

Aslında bütün çakıl taşları; 

Ekmeğini taştan çıkaranların göz yaşları…

Ankara, Aralık 2005', 'Sert ve sağlam durur çakıl taşları Oysa her bastığınızda nasılda kaypak Savrulurlar dört bir yana yok ki başları. Yine de serttir çakıl taşl...', ARRAY['Türk Edebiyatı','Şiir','İrfan Kayagil']::text[], 8.5, '{"poet":"İrfan Kayagil","poet_slug":"i-rfan-kayagil","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/cakil-taslari-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Defterimde Yarım Kalan Sen..', 'defterimde-yarim-kalan-sen-zeliha-bicer-2dg6r', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Defterime yazdığım,onca şiirlerden

Bazıları yarım.

Elime kalemimi her aldığımda

İçim acımış demek ki.

O yarımlıklarda, yazamamışım,

Çok istesem bile.

İşte sen! 

Böyle kalmışsın yüreğimde...', 'Defterime yazdığım,onca şiirlerden Bazıları yarım. Elime kalemimi her aldığımda İçim acımış demek ki. O yarımlıklarda, yazamamışım, Çok iste...', ARRAY['Türk Edebiyatı','Şiir','Zeliha Bicer']::text[], 8.5, '{"poet":"Zeliha Bicer","poet_slug":"zeliha-bicer","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/defterimde-yarim-kalan-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adem''in İtirafı', 'adem-in-i-tirafi-alper-kuruk-gf3xx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yasaklanmış o meyva kabarttı iştahımı

Şeytana uyup yaptım kaçamak siftahımı,

Gücendirdim bir kere yaratan Alah''ımı

Şimdi gökler kapsamaz çıkardığım âhımı.

Cennetinden dünyana atılmışım  bu yüzden

Affın için yıllarca sana tevbe ederken

Farkına varmamışım, kaçırıvermişim gözden

Güzelllikleri gördüm Havva ile yeniden.

Dünyada da Cennetten köşeler varmış meğer

Görür güzellikleri insan isterse eğer,

Sevgilerden doğuyor bence bütün sevgiler

Fâni olsa da dünya yaşamaya da değer...', 'Yasaklanmış o meyva kabarttı iştahımı Şeytana uyup yaptım kaçamak siftahımı, Gücendirdim bir kere yaratan Alah''ımı Şimdi gökler kapsamaz çık...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/adem-in-itirafi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen beni kayp ettin', 'sen-beni-kayp-ettin-husamettin-guven-k5g97', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Arasanda bulamazsin

Birdaha kandiramazsin

Bana kendini sevdiremezsin

Sen beni kayp ettin

Diz cokupte yalvarsanda

Sevdigini haykirsanda

Aglayipta sizlasanda

Sen beni kayp ettin

Yoluma hali sersende

Bana dunyalari versende

Sana muhtacim desende

Sen beni kayp ettin

Sensizlik zor desende

Her gece ruyanda gorsende

Tovbe edip ozur dilesende

Sen beni kayp ettin', 'Arasanda bulamazsin Birdaha kandiramazsin Bana kendini sevdiremezsin Sen beni kayp ettin Diz cokupte yalvarsanda Sevdigini haykirsanda Aglay...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-beni-kayp-ettin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlık Yeşil', 'karanlik-yesil-adem-aktas-yazgibozan-9pvxl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yine karanlık bir sabah! 

Güneş yine bütün şaklabanlığıyla gülümsüyor

Ama karanlık duvarların ve karanlık gözlerin

Bu sabahın güzelliğini zifiri bir karanlığa boğmaya yetiyor.

Yine seni düşünüyorum ve yine karanlık bir sabah

Kaynamış suya yeni aldığım kokulu çayı atarken…

Bana şefkat dolu baktığın günler geliyor aklıma

o çıtır ekmekleri bölüp ağzıma attıkça.

En sevdiğim elbisemi giyip ortalıkta dolaşıyorum

Güneşin ihtişamından sıyrılıp bana görünmeyi başaran aya bakarak

Ve dayanamıyor ağlıyorum

Penceremden giren kapkara ışıkları inadına görmüyorum

Çatlatıyor çiçeklerim beni yine güzellikleriyle

Sonra kahkahayı basıyorum aynadaki bana

Ama tuhaf o bana gülümsemiyor bile…

Karanlık bir sabah işte ….! 

Yanımda olmadığın bir sabah yoksun ya..

Kahretsin…

Yine karanlık bir sabah işte….', 'Yine karanlık bir sabah!  Güneş yine bütün şaklabanlığıyla gülümsüyor Ama karanlık duvarların ve karanlık gözlerin Bu sabahın güzelliğini zi...', ARRAY['Türk Edebiyatı','Şiir','Adem Aktaş Yazgıbozan']::text[], 8.5, '{"poet":"Adem Aktaş Yazgıbozan","poet_slug":"adem-aktas-yazgibozan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/karanlik-yesil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Huzurum yok su dunyada', 'huzurum-yok-su-dunyada-husamettin-guven-xbjwu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sabah aksam gezer oldum

Evden barkdan ben sogudum

Stres icinde boguldum

Huzurum yok su dunyada

Problemsiz gunum olmaz

Nedenini aklim almaz

Hic yok yere kalp kirilmaz

Huzurum yok su dunyada

Sanki bende yasiyorum

Mutsuzlukdan kaciyorum

Dert kupuyum sasiyorum

Huzurum yok su dunyada

Yavrular icin yasiyorum

Dert yukunu tasiyorum

Hep icime atiyorum

Huzurum yok su dunyada', 'Sabah aksam gezer oldum Evden barkdan ben sogudum Stres icinde boguldum Huzurum yok su dunyada Problemsiz gunum olmaz Nedenini aklim almaz H...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/huzurum-yok-su-dunyada-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekâr Düşüncelerde', 'bek-r-dusuncelerde-alper-kuruk-tuozt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gidiyor bilmediği bir yere

Ayağı kadere bağlı ömrü

Günlerle getiriyor sevâbı

Gecelerde günahla öpüşüyor.

Umut kararıyor bulutlarda

Gerçek iniyor yağmur yağmur

Genç kız teri burcu burcu

Bekâr odalarında...

Ölümsüzlüğü taşıyor ölüm

İnsanlara değil ruhlara.

Karanlık aşkı itiyor gönül

Aydınlığa açık pencerelerinden,

Bir bekâr çıkıyor sokaklara 

Soğuk yataklı evinden.

Ayaklarında uzun yollar

Başında kesiksiz düşünceler

Yürüyor,yürüyor bilmediği bir yere

Etrafta tek-tük ışıklı evler.

Belki düşüncelerinin bitiminden

Geri dönecek güzelliklere,

Belki gidecek,gidecek yine kararsız

Karşısına çıkıncaya dek

Ya ölüm ya da güzel kız...', 'Gidiyor bilmediği bir yere Ayağı kadere bağlı ömrü Günlerle getiriyor sevâbı Gecelerde günahla öpüşüyor. Umut kararıyor bulutlarda Gerçek in...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bekar-dusuncelerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Memleketim', 'memleketim-ahmet-sefer-kocer-eo6eb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben toprağında doğmuşum

Çığlığım, ezan seslerine karışmış

Koşup oynamışım, düşe kalka

Körpe bedenimden akan kanlar

Toprağına karışmış

Atam, ecdadım, şehitlerim

Kanımı kanlarına katmış

Yoğurmuş, yoğurmuş; 

Anaların ninnileri, ağıtları

Kılıç sesleri, nal sesleri

Sevdayla hasretle dolu dolu

Hoyratla, bozlakla

Bir kavrulmuş ki:

Yürek olmuş bedenime memleketim

Türkiye sevdalısı bir yürek

Gözyaşlarım pınarlarına karışmış

Yağmış üstüme rahmet rahmet

Yorgan olmuş bozkırlara, ekinlere bembeyaz

Dövmüş bedenimi dolu dolu

Koku olmuş kır çiçeklerine

Anamın gözyaşları, şehidimin al kanı

Sinmiş bedenlere memleketimin kokusu

Anamın kokusu olmuş

Memleketim anam Anadolu''m

Hasretim, sevdam, yavuklum

Havam, ekmeğim, suyum

Ocağım, yuvam memleketim

Memleketim kederim, yasım

Sevincim, coşkum, tutkum

Namusum, arım memleketim', 'Ben toprağında doğmuşum Çığlığım, ezan seslerine karışmış Koşup oynamışım, düşe kalka Körpe bedenimden akan kanlar Toprağına karışmış Atam, ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Sefer Kocer']::text[], 8.5, '{"poet":"Ahmet Sefer Kocer","poet_slug":"ahmet-sefer-kocer","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/memleketim-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-i-rfan-kayagil-isedr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yalnızlığı sordun da 

Sana söylemedim mi? 

Sevdanın karasını, 

Sarsaydın yarasını

Al canım yarısını, 

İstedin  Vermedim mi ? 

Dersen aşka ihanet

Anlatmamak hiyanet

Bu  kuluna merhamet

Verdin istemedim mi? 

Gönlüm elbet derbeder

Senden ise bihaber

Bu can sana fedadır

Olmayaydı ayrılık,

Cehennem de sefadır.

Haziran 2002  Ankara', 'Yalnızlığı sordun da  Sana söylemedim mi?  Sevdanın karasını,  Sarsaydın yarasını Al canım yarısını,  İstedin  Vermedim mi ?  Dersen aşka ih...', ARRAY['Türk Edebiyatı','Şiir','İrfan Kayagil']::text[], 8.5, '{"poet":"İrfan Kayagil","poet_slug":"i-rfan-kayagil","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ayrilik-314-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acı Gönül Bestesi', 'aci-gonul-bestesi-alper-kuruk-m215c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir acı duyduğunuz gün olursa

Ki insan oldukça acı duyacaksınız

O geceyi unutamayacaksınız.

Dinleyin geceyi içten

Karanlık sizlere birşeyler söyleyecek

Dikkat kesilsin kulaklarınız.

Dinleyin,dinleyin durmadan

Bir inilti duyacaksıız

Karanlıklardan süzüle süzüle gelen.

Dinleyin sabrınız tükenmesin

Dişinizi sıkın birazcık daha

Bu duyduğunuz inilti

Bir ölecek hastanın iniltisi değil.

Bu,ne de bir insan sesi

Belki bu inildeyen bence

Acı bir gönül bestesi...

Artık bize düşen tek şey 

Yatağa girip erkence

Yıldızlara göz yaşını göstermeksizin

Ağlamak karanlığa doğru.

Ben ağlasam da yıldız yıldız gülen gök

Yine hepimzin,

Yine hepimizin.', 'Bir acı duyduğunuz gün olursa Ki insan oldukça acı duyacaksınız O geceyi unutamayacaksınız. Dinleyin geceyi içten Karanlık sizlere birşeyler...', ARRAY['Türk Edebiyatı','Şiir','Alper Kürük']::text[], 8.5, '{"poet":"Alper Kürük","poet_slug":"alper-kuruk","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/aci-gonul-bestesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Güzele Yanmışsan', 'bir-guzele-yanmissan-i-rfan-kayagil-kmeli', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir güzele yanmışsan

Gözlerine kanmışsan; 

Koşup durup peşinden

Ah çekiverme içinden.

Söndürmezsen korunu

Şaşırırsın yolunu; 

Bir gün olur yakalar

Yapma öyle şakalar.

Sakın fazla aldanma; 

Söylenen her yalana,

O da seni severse; 

Yap istersen ne derse.

Sürdürmesin oyunu; 

Seviyorsan huyunu,

O güzelin aşkından

Aklın gider başından...

Ankara 2001', 'Bir güzele yanmışsan Gözlerine kanmışsan;  Koşup durup peşinden Ah çekiverme içinden. Söndürmezsen korunu Şaşırırsın yolunu;  Bir gün olur y...', ARRAY['Türk Edebiyatı','Şiir','İrfan Kayagil']::text[], 8.5, '{"poet":"İrfan Kayagil","poet_slug":"i-rfan-kayagil","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bir-guzele-yanmissan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Sevgili En Sevgili', 'ey-sevgili-en-sevgili-necmiye-sarpkaya-arbuf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ey sevgili en sevgili

Gül yüzlü güzel benizli efendim

Keşke anlayabilseydik seni

Keşke anlatabilseydik

Çağlar aşan kutlu beyanlarını 

Duyurabilseydik

Kör sağır kalplere

Kapalı gönüllere

Duyurabilseydik

Perdekar örümcekler olabilseydik

Nur ellerinle uçurduğun

Barış güvercinleri olabilseydik

Mübarek ellerinle derlediğin

Bir demek gül olabilseydik

Kanatsaydı  dillerimizi gönüllerimizi

Dikenleri kanatsaydı Efendim

Yaksa yaksaydı aşk ateşlerin

Gönüllerimizi yaksaydı

Birer Meryem

Birer Asiye

Birer Ebu Bekir

Olabilseydik

Olabilseydik keşke

Yanlış ateşlerde yandık

Yanlış şafaklarda uyandık

Yanlış boyalarla boyandık

Yıllar yılı  Efendim

Kim bilir kimimiz hangimiz

Hangi günahların koynuna yuvarlandık

Bembeyaz ömür sayfalarını karaladık

Ömür sermayesini tükettik Efendim

Ağrı dindirecek yetimlerin var

Ateşlere atılmayı bekleyen İbrahimlerin var

Gül bitiren yağmurlarını bekliyorlar

Gel Efendim gel ne olur gel

Sensizlik girdabında

Zehrini yudumladık hayatın

Onca günahlara

Onca kusurlara rağmen

Senin büyüklüğün kadar

Emeller umutlar beklentiler büyüttük

Tutunduk verdiğin sözlere

Müjdelerinin ipek çehresine tutunduk

Ümit varız hala senden yana

Ey vefalı ey cefalı dost en dost

Kapına geldik selatu selamların

Sıcacık gölgesinde

Beyaz dualarımızın gölgesinde

Yetiş Ya Resul

Gönül Kabesinin karasına rağmen

Seni bekliyoruz

Seni özlüyoruz

Ellerimizde demet demet güller

Dillerimizde yüzlerce binlerce selatu selamlar

Gözlerimizde pişmanlık yaşları ile kapına geldik

Ne olur gel gel imdada yetiş Efendim 

Gel ne olur gel yetiş imdada yetiş

(12/12/2005)', 'Ey sevgili en sevgili Gül yüzlü güzel benizli efendim Keşke anlayabilseydik seni Keşke anlatabilseydik Çağlar aşan kutlu beyanlarını  Duyura...', ARRAY['Türk Edebiyatı','Şiir','Necmiye Sarpkaya']::text[], 8.5, '{"poet":"Necmiye Sarpkaya","poet_slug":"necmiye-sarpkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/ey-sevgili-en-sevgili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgar', 'ruzgar-sebahattin-kacar-u451x', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Öpücüklerimi kondurdum,

Sana esen rüzgara,

Özlem kokan rüzgara.

Kalbimde bir fırtına kopardın.

Sevda fırtınası bu fırtına.

Aklımda hep o güzel yüz.

Senin yüzün.

Dudaklarımda hep o şarkı.

Güftesi de, bestesi de,

Seni anlatan o şarkı.

Aşkın şarkısısın sen.

Aşkımsın sen.', 'Öpücüklerimi kondurdum, Sana esen rüzgara, Özlem kokan rüzgara. Kalbimde bir fırtına kopardın. Sevda fırtınası bu fırtına. Aklımda hep o güz...', ARRAY['Türk Edebiyatı','Şiir','Sebahattin Kacar']::text[], 8.5, '{"poet":"Sebahattin Kacar","poet_slug":"sebahattin-kacar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ruzgar-123-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağladığıma Bakma', 'agladigima-bakma-humeyra-yilmaz-2fowh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'her gece yokluğun, aklımın en ücra köselerinde yatmışken pusuya

bir kurşun yetmez, hasretinin eceline susayan canına

neferime eksem de bahara inat hazan çiçeklerimi

seni görmeden satmayacağım bedenimi bu toprağa 

sol yanımın sahiplenemediğim soğuğundan

ayazını da al öyle git bari bu şehrin kalabalığından

ben gündüzden çaldığım güneşle yakarım soluk benizli gölgeleri

sen de bu arada geri dönmek için hazırlan

göz yaşlarıma demir atan toz pembe düşlerimi

umudun açık denizlerine döksem daha mı iyi

yaşanmış güzel çirkin her şeyin hatırına

hadi uzat ellerini de bir kez daha bırakıyım avucuna yüreğimi 

biraz daha beklersem eriyip gideceğim yokluğunun verdiği şaşkınlıktan 

geç kalmaktan korkuyorum bir tanem hayatı yakalayamamaktan 

bana geldiğinde yüzündeki çizgileri 

şakaklarına değil de gerdanına paralel bulmaktan….

gel de kırılsın artık beni hapsettiğin kafesin parmaklıkları

yokluğuna doydum tıka basa…üzerine içtiğim gecelerin sancıları

bedenimde sakladığım kokunla yıkandığımı görmüş, öfkelenmiş 

dün almaya geldi ay…vermedim…gülüşüne dizdiğim ıslak yıldızlarını

bir kelepçe kollarımda sensizliğe direniyorum

senden geriye kalan son ihtimalse bile

ölme hakkımı kullanmak istemiyorum 

geçte olsa geleceksin biliyorum

ağladığıma bakma…seni beklemeyi de en az senin kadar seviyorum…', 'her gece yokluğun, aklımın en ücra köselerinde yatmışken pusuya bir kurşun yetmez, hasretinin eceline susayan canına neferime eksem de bahar...', ARRAY['Türk Edebiyatı','Şiir','Hümeyra Yılmaz']::text[], 8.5, '{"poet":"Hümeyra Yılmaz","poet_slug":"humeyra-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/agladigima-bakma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaş Yirmibir', 'yas-yirmibir-erkan-arslan-n8zqb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Adam olmakmış,işin gerçeği bir adam.

Çoçukluğa her an özlem duyan birisi.

Bir dilin lugatında sözçük olup adam.

Yaş yirmi bir,giyinirim ''''zan'''' elbisesi.

Siyah beyaz.her türlü canlanır şekiller.

Mıhlı zamanın rehperi bir saat gibi.

Geriye dönemem,sefil bir vahşi bekler.

Mıhlı zamanın akrebi,bir saat gibi.

Saklanırdı çoçukluk elbiseme cehrem.

Bir ayağım üç tekerli bisikletimde.

Her vakit kalkmak bilmez,oturur zaman.

Bir zoraki misafir gibi yan köşede.

Tutunur kırılmaz yalnızlığıma hatlar.

Bir tütün sigara içerim hayat gibi.

Beni benden uzak kıldı,sırlı aynalar.

Yaş yirmi biri giyerim bir ''''vaad'''' gibi.

Yelek cebimde babadan kalma tabakam.

Bir başkadır,sen saplan adam soluğuna.

Yıllanmış yürürken bir garip adam.

Eski esvaplarım tutunun çoçukluğa.

Bir delikanlı mı oluvermiştim hemen. 

Yanımda ki yavuklumun en güzel resmi.

Tarhların çekildiği.bahtımda güller açan.

Beklerim bir başka doyunsuz sevgilimi.

Vakitli vakitsiz içimde buğulanan.

Efsunlu çoçukluğumun gözü körebe.

Zamanı söküpte,çıkardım saatimden.

Her cetvelden dönerken bu yaş yirmibire.

                                                                   Nisan 1996', 'Adam olmakmış,işin gerçeği bir adam. Çoçukluğa her an özlem duyan birisi. Bir dilin lugatında sözçük olup adam. Yaş yirmi bir,giyinirim ''''za...', ARRAY['Türk Edebiyatı','Şiir','Erkan Arslan']::text[], 8.5, '{"poet":"Erkan Arslan","poet_slug":"erkan-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/yas-yirmibir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buzdan Duvar', 'buzdan-duvar-sebahattin-kacar-hcm8s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Parçalanmış duygular var kalbimde.

Unutulmuş anılar, silik yüzler var beynimde.

Tam dokunacağımı sandığım zaman hayallerime,

Buzdan bir duvar, yakar kalbimi, durur önümde.', 'Parçalanmış duygular var kalbimde. Unutulmuş anılar, silik yüzler var beynimde. Tam dokunacağımı sandığım zaman hayallerime, Buzdan bir duva...', ARRAY['Türk Edebiyatı','Şiir','Sebahattin Kacar']::text[], 8.5, '{"poet":"Sebahattin Kacar","poet_slug":"sebahattin-kacar","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/buzdan-duvar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Bahçesinin Güllerini Serenlerdensin', 'ask-bahcesinin-gullerini-serenlerdensin-yavuz-bayram-caliskan-zwz1e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yıllar geçse de hayalimden silemem,

Seni sevdim, nedenini bilemem,

Nazlansan da ayrı kalamam,

Su gibi ekmek verenlerdensin.

Bir yan bakışınla sarardım, soldum,

Aşk badesi ile yüreğine doldum,

Söylenecekse ben aşık oldum,

Kaş gibi göz verenlerdensin.

Hatırımdan çıkmıyor vurulduğun gözün,

Bakıyor diline söylesin özün,

Versin artık duramam sözün,

Ömür gibi zamanı soranlardansın.

Saçlarının tellerine güller bağlasam,

Gözlerine bakıp bakıp ağlasam,

Sevda ateşiyle yüreğimi dağlasam,

Bu goncanın güllerini derenlerdensin.

Bütün çektiklerim senin dilinden,

Tutabilseydim sımsıkıca elinden,

Çekip kendime ıssızlarda belinden,

Aşk bahçesinin güllerini serenlerdensin.

Mihneti kendime dert ettim bitirdi,

Dertlerimi dert ortağıma götürdü,

Ihlamurlar altındaki aşka yatırdı,

Kader olup kalbini verenlerdensin.

Uğraşma, yorma kendini boşuna,

Ömür bu olmaz işler gelir başına,

Öyle böyle derken elli yaşına,

Ömür olup ufuklara varanlardansın.', 'Yıllar geçse de hayalimden silemem, Seni sevdim, nedenini bilemem, Nazlansan da ayrı kalamam, Su gibi ekmek verenlerdensin. Bir yan bakışınl...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ask-bahcesinin-gullerini-serenlerdensin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hz. İLYAS (AS)', 'hz-i-lyas-as-abdullah-yasar-erdogan-etrre', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '(21. Büyük Peygamber) 

      Hz.  İLYAS  (AS) 

Hz. Harun’a dayanır O’nun nesebi,

Benû İsrail O’nu kabul etmedi,

Hakk elçisi olduğunu söyler kavme,

Kur’an, Saffat’ta; “O Peygamberlerdendi.”

Hz. İlyas Aleyhisselam’ın o kavmi,

İsrail Oğulları’ndan bir boy idi.

Bu kavim, Ba’lebek denilen yerdedir.

Ba’l diye bilinen puta secdedeydi.

Hz. İlyas’ı tebliğci gönderdi Rabbim,

İlyas dedi: “Allah’a uyun ey kavmim,”

Yalancılıkla suçladı kavmi O’nu,

İlyas der: “Yapmayın, O her yerde Kerim.”

İlyas gönderilmiş Peygamberlerdendi,

Kur’an; Şûâra’da Allah böyle dedi.

Doğru yolu anlattı onlara İlyas,

Onlar; “Bize Ba’l putumuz yeter” dedi.

İlyas’ı İsrailliler tanımadı,

Hz. İlyas duada; şikayet onları; 

“İhsan olunan nimetleri değiştir”

Allah da üç sene yağmur yağdırmadı.

Nesebi Hz. Harun’a dayanır O’nun,

Tebliğcisidir isyankâr-azgın Benu’n,

Benu İsrail Kabilesi çok azgın,

Şam civarındaki o Bek şehri bunun.

Kur’an’da Enbiya ve Saffat anlatır,

O Allah’tan tebliğ görevi almıştır.

Bazı kaynak; masalla anlatır O’nu,

Hakk: “Hakikat O Mü’min kullarımdandır”.

Muhakkak İlyas da Peygamberlerdendi,

Bize her zaman gerek Allah ne dedi.

O’nun için rivayetler çok olsa da,

O Hakk’ı tebliğ eden bir peygamberdi.

Bek’in kralı; İlyas’a önce inandı,

Sonra İlyas’ı öldürmeye de kalktı.

Yedi yıl dağlarda yaşamıştır denir,

O zaman El-Yese’yle yaşamaktaydı.

İsrail oğullarında çok Peygamber,

Onun için kıssa sayılmaz muteber.

Hakk Kur’an’da varsa eğer bir emare,

Bizce o kutsal görevde saygıdeğer.

Kerim: Asalet, şeref ve cömertlik sahibi.

Şair: Abdullah Yaşar Erdoğan', '(21. Büyük Peygamber)        Hz.  İLYAS  (AS)  Hz. Harun’a dayanır O’nun nesebi, Benû İsrail O’nu kabul etmedi, Hakk elçisi olduğunu söyler ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/hz-ilyas-as-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek, Beklemek Zor', 'sevmek-beklemek-zor-i-sa-tekin-xof2b', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevmek beklemek zor

Hayat,kokulu gül bahçesi değil

Sensizliğin dikenidir ayrılıklar

İnceden inceye kanatır yüreğimi

Fitil tutmaz bu yaram

Özlemleri koklamak istemiyorum artık 

Hasretin gölgesinde değil

Gönül güneşinde olmak istiyorum

Yanmak, yanmak istiyorum

Kavrulmak istiyorum sevdana

Küllerim savrulsun dört yana

Gül bahçemde...

Kırmızı birgül olsun', 'Sevmek beklemek zor Hayat,kokulu gül bahçesi değil Sensizliğin dikenidir ayrılıklar İnceden inceye kanatır yüreğimi Fitil tutmaz bu yaram Öz...', ARRAY['Türk Edebiyatı','Şiir','İsa Tekin']::text[], 8.5, '{"poet":"İsa Tekin","poet_slug":"i-sa-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevmek-beklemek-zor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmek İstiyorum', 'bilmek-i-stiyorum-humeyra-yilmaz-pnf88', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yalın bir haldeyim! ! ! 

yalnızlığım kulağıma seni fısıldarken

gözlerimin beyazı cehennem kırmızısına

uykularım geceye yenik…

sonsuzluğu soluyorum

hayal perileri kokunu getirdikçe odama…

taşa çevirdiğin yüreğimin yerinde esen yellerle 

aklım sana devriliyor yine çaresizce…

bedenime saplanmış ayaklarım isyan kokuyor…

g e l m i y o r s u n ___ g e l e m i y o r u m

gebereceğim bu kokudan…

mavinin umuttan uzak bir tonunu yakalıyorum

ruhum yükseldikçe arşa…

en azından şunu söyle bana! ! ! 

Ö l ü y o r _ m u y u m? ...', 'yalın bir haldeyim! ! !  yalnızlığım kulağıma seni fısıldarken gözlerimin beyazı cehennem kırmızısına uykularım geceye yenik… sonsuzluğu sol...', ARRAY['Türk Edebiyatı','Şiir','Hümeyra Yılmaz']::text[], 8.5, '{"poet":"Hümeyra Yılmaz","poet_slug":"humeyra-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bilmek-istiyorum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kusur Bizim', 'kusur-bizim-mehmet-cetinkaya-4aln8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dünya denen meşakkati, sarmışız da sırtımıza,

Biliyorum gömecekler, bizi bir gün arzımıza.

Körüz biz görmemişiz, dostumuz gelmiş karşımıza,

Kusur bizim bağışla, ateş olma sıratımıza.

Ne ettimse öldüremedim, nefis denen illeti,

Bir beni yaksa fedayım, yakıyor cümle ümmeti,

Gel güldür bizi dost, al üstümüzden şu mihneti,

Kusur bizim bağışla, ateş olma sıratımıza.

Ayıp günah demez eller, hemen vurur yüzümüze,

Bakarız ufuklara, dost görünür mü gözümüze,

Araya araya bulsak, dermanı şu dizimize,

Kusur bizim bağışla, ateş olma sıratımıza.

Anadolu yürek yaylamızda, eser serin yeller,

Tebessüm etsen de yeter, açar bahçemizde güller,

Öpmek için uzat desek, uzanır mı bize eller,

Kusur bizim bağışla, ateş olma sıratımıza.

(30.11.2005  Tavşanlı) 

Ozan FEDAİ KOÇ ''a İthafımdır)', 'Dünya denen meşakkati, sarmışız da sırtımıza, Biliyorum gömecekler, bizi bir gün arzımıza. Körüz biz görmemişiz, dostumuz gelmiş karşımıza, ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çetinkaya']::text[], 8.5, '{"poet":"Mehmet Çetinkaya","poet_slug":"mehmet-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kusur-bizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Çıkar', 'ne-cikar-humeyra-yilmaz-minwz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'takınsan yürekli tavrını

gelsen kapıma

taş soğuğu göğsümü 

yumuşatsa nefesin 

ezberleyemediğim 

türkünü söylesen 

bir kez daha

yansa yıkılsa ciğerim 

sınırlarıma ektiğin direnişlerini 

toplarken kirpiklerimle

gözüme hasretin kaçmasa

bedenim sürünürken 

aklımın kaldırımlarında

yaralanmasa ellerim 

kanamasa dizlerim 

olmaz mıydı? 

ben sadece baharları içinde besleyen 

küçük bir fidanım

sen ölüp ölüp dirildiğini söyleyen koca çınar

madem öyle

bir kere de benim için ölsen ne çıkar!', 'takınsan yürekli tavrını gelsen kapıma taş soğuğu göğsümü  yumuşatsa nefesin  ezberleyemediğim  türkünü söylesen  bir kez daha yansa yıkılsa...', ARRAY['Türk Edebiyatı','Şiir','Hümeyra Yılmaz']::text[], 8.5, '{"poet":"Hümeyra Yılmaz","poet_slug":"humeyra-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ne-cikar-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Git-me', 'git-me-humeyra-yilmaz-i4ms0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir sabah ayazında gözümün içine baka baka doğan güneşin 

Sırlarını saklamamı istercesine yakarışları içinde dönerken gün 

Aklımı göç mevsiminde bir kuşun kanadına takışıma mı yanayım 

Gidiyorum deyişin var ya içim erir ama kabuğum saklar görmez kimse

Susuşumda bekleyen cümlelerin mayhoşluğu gelir dilime damağıma 

Üstüne denizleri de içsem geçmez tadı bilirim 

Akşamı beklemeden örter günü koyu gri ağlamaklı bulutlar 

İçime akarken asi yüreğinin baş kaldırışı damla damla

Ne sana ne de Tanrıyadır isyanım

Hep geç kalan zamana yüklenirken aklımın bir ucu

Sorgusuzca bir vazgeçişin eşiğine takılıp kalır

Bir ayağı sürgünde diğeri toprağa ekili 

Yabancı değil bu hissettiklerim 

Belki biraz daha kalsan hatırlayabilirim', 'Bir sabah ayazında gözümün içine baka baka doğan güneşin  Sırlarını saklamamı istercesine yakarışları içinde dönerken gün  Aklımı göç mevsim...', ARRAY['Türk Edebiyatı','Şiir','Hümeyra Yılmaz']::text[], 8.5, '{"poet":"Hümeyra Yılmaz","poet_slug":"humeyra-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/git-me-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Sana Gömdüm', 'beni-sana-gomdum-humeyra-yilmaz-w1qcz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yedi kat gömdüm yüreğimi yüreğine 

kefenimin cebine sığan sadece

hasretinin ayazında buz kesmiş ellerim 

ve sana söyleyemediğim cümlelerim...

yetişemediğim zamanın gölgesinde

güneşine hasret kaldı saç diplerim

şimdi yedi kat altındayım yüreğinin

köklenmek filizlenmekti niyetim 

oysa toprağında daha çok üşümekteyim...

sızlayan kemiklerimin arasından 

süzülen ışıkla kamaşmıyor 

alışsa da karanlığın siyahına gözlerim

acılardan acı beğeniyorum 

ve bekliyorum 

kırıldı kırılacak

artık çıyanların doladığı ince belim...

nasıl da hevesliydim sen de ölmeye

ve beni sana gömdüm 

ama şimdi 

avazıma emanet suskunluklarım 

sadık bir dost gibi

sustukça ağlıyorum

sustukça ölüyorum

hem de diri diri...

a n l a _ şimdi yedi kat dibindeyim yüreğinin

köklenmek filizlenmekti niyetim 

oysa toprağında daha çok _ ü ş ü m e k t e y i m...', 'Yedi kat gömdüm yüreğimi yüreğine  kefenimin cebine sığan sadece hasretinin ayazında buz kesmiş ellerim  ve sana söyleyemediğim cümlelerim.....', ARRAY['Türk Edebiyatı','Şiir','Hümeyra Yılmaz']::text[], 8.5, '{"poet":"Hümeyra Yılmaz","poet_slug":"humeyra-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/beni-sana-gomdum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbet', 'gurbet-humeyra-yilmaz-zykyg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sakın seni bırakacağımı düşünme

Dalgasını kırdığım denizlerin dibinde

Gelmek istemez miyim zizil parmaklım

Memleketimi koklamak yanık teninde

Buralarda kuzu kurda emanet çoban firarda

Derdim bendini aştı uykularım darda

Sağım solum içi insan dolu çukur 

Ruhumdan eser kalmadı ama aklım başımda

Asılı kaldı bedenim kızıl şafakta

Diyorlar derdinin dermanı kara toprakta

Hasreti uzatmak değil benim niyetim

Sen hep açık tut baharının bağrını

Yolum düşer elbet katarım kendimi bir rüzgara……..', 'Sakın seni bırakacağımı düşünme Dalgasını kırdığım denizlerin dibinde Gelmek istemez miyim zizil parmaklım Memleketimi koklamak yanık tenind...', ARRAY['Türk Edebiyatı','Şiir','Hümeyra Yılmaz']::text[], 8.5, '{"poet":"Hümeyra Yılmaz","poet_slug":"humeyra-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gurbet-105-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnce Çizgi', 'i-nce-cizgi-humeyra-yilmaz-77wp5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Korktum_________! ! ! 

cesaret edilememiş her şeyin altında 

e z i l m e k t e n 

bildikleriyle yetinişi sevdiklerimin 

be n i_ k a h r e d e r k e n

dudaklarına konmuş yalan tebessüme 

mahkum edildi 

g ö z _ b e b e k l e r i m 

isyan bayrağım dalgalandı 

ş a f a ğ ı n _ ş a k a ğ ı n d a 

yine de haykırışım asılı kaldı

G ü l h a n e _ p a r k ı n d a 

bir ceviz ağacının dalında 

şimdi ben 

bütün vazgeçmişliğimi yüklenip

sıradan bir göç mevsiminde 

tam da ölmeye 

h a z ı r l a n ı r k e n 

gölgelerime ışık tutan 

bu adam da kim____________? ? ?', 'Korktum_________! ! !  cesaret edilememiş her şeyin altında  e z i l m e k t e n  bildikleriyle yetinişi sevdiklerimin  be n i_ k a h r e d ...', ARRAY['Türk Edebiyatı','Şiir','Hümeyra Yılmaz']::text[], 8.5, '{"poet":"Hümeyra Yılmaz","poet_slug":"humeyra-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ince-cizgi-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeter ki Gel', 'yeter-ki-gel-humeyra-yilmaz-9vuv9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yoksun ya! 

Şimdi acıtıyor işte göğsüme çarpan yel…

Bulut karası gözlerimde kalan son damlayı da 

Sana harcayacağım / yeter ki GEL …', 'Yoksun ya!  Şimdi acıtıyor işte göğsüme çarpan yel… Bulut karası gözlerimde kalan son damlayı da  Sana harcayacağım / yeter ki GEL …...', ARRAY['Türk Edebiyatı','Şiir','Hümeyra Yılmaz']::text[], 8.5, '{"poet":"Hümeyra Yılmaz","poet_slug":"humeyra-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yeter-ki-gel-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönlüm Yastadır', 'gonlum-yastadir-i-sa-tekin-3dfzl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Vuruldum o gözlere

Kalbim hastadır

Gidin söyleyin o yarâ

Gönlüm yastadır', 'Vuruldum o gözlere Kalbim hastadır Gidin söyleyin o yarâ Gönlüm yastadır...', ARRAY['Türk Edebiyatı','Şiir','İsa Tekin']::text[], 8.5, '{"poet":"İsa Tekin","poet_slug":"i-sa-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gonlum-yastadir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşi Görmedim', 'gunesi-gormedim-ramazan-ates-a1s1n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ah kardeşim, dinle beni olmaz mı? 

Onbeş yıldır ben güneşi görmedim.

Avrupa’yı sana nasıl anlatsam? 

Onbeş yıldır ben güneşi görmedim.

Avrupa’nın soluk yüzlü insanı,

Sevgisizler nerden bilsin şefkati,

Sevda ne ki? İç çekeni sezmedim,

Onbeş yıldır ben güneşi görmedim.

Yağmur yağar hep evlere dolarız,

Basık hava, yavaş yavaş solarız.

Kır çiçeği, lale, sümbül dermedim,

Onbeş yıldır ben güneşi görmedim.

Saat altı, hayat biter çok yerde.

Her şey açık yüzlerinde yok perde.

Namus diyen, ahlak diyen duymadım,

Onbeş yıldır ben güneşi görmedim.

Dikkat ettim hep eriyen biz olduk.

Hem ezildik, çoğu yerden kovulduk.

Alnım açık, Türküm diye gezmedim,

Onbeş yıldır ben güneşi görmedim.

Hata bizde, kusur bizde, suç bizde,

Anlatmadık, öğretmedik, çok bizde.

Çok gençlere bizim genç diyemedim,

Onbeş yıldır ben güneşi görmedim.

Avrupa’nın zıkkım çalsın parası,

Ne arabası nede güzel karısı.

Biliyorum güzel resim çizmedim,

Onbeş yıldır ben güneşi görmedim.

Doğu nere? Güneş nerden doğar ki? 

Ne tan yeri, nede kuşluk vaktini,

İnan bana, hep doğrudur sözlerim,

Doğmuyor mu? Ben güneşi görmedim.

Onbeş yıldır ben güneşi görmedim.

Ramazan Ateş/Enschede-04.11.1999', 'Ah kardeşim, dinle beni olmaz mı?  Onbeş yıldır ben güneşi görmedim. Avrupa’yı sana nasıl anlatsam?  Onbeş yıldır ben güneşi görmedim. Avrup...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/gunesi-gormedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seyr-ü sefer', 'seyr-u-sefer-sair-ahrazi-29e0m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ölüm bir başka mevkîdir; ne semâdır ne toprak! 

Ölüm; baktıkça bir rüyâdan aksetmiş kadar pak.

Kaçanlar,ağlaşanlar.Hangi yoldan gitse insan,

Ölüm en son duraktır,ölüm en mecbûrî sapak.

* * *', 'Ölüm bir başka mevkîdir; ne semâdır ne toprak!  Ölüm; baktıkça bir rüyâdan aksetmiş kadar pak. Kaçanlar,ağlaşanlar.Hangi yoldan gitse insan,...', ARRAY['Türk Edebiyatı','Şiir','Şair Ahrazi']::text[], 8.5, '{"poet":"Şair Ahrazi","poet_slug":"sair-ahrazi","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/seyr-u-sefer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan', 'i-nsan-sair-ahrazi-2wk2v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kaybolan tek sen misin? Ey merhamet! 

Var mıdır insanda şerden başka his? 

En güzel şehrinde ev ev sohbet et,

Bir hazin mevzûdur insandan bahis.

Sanki hiç vâdetmemiş Hak mahşeri,

Sanki mülkün sâhibidir kat be kat.

Hiç düşünmemiş yeri,ulvî gökleri,

Hâşâ! Avcundaki yoldur kâinat.

Açsa bir efsunlu mevsimden bahar,

Aldanır yıllarca.Sormaz kendine; 

‘’Hangi tat Dünyâ’ya bir lezzet katar? ’’

Hangi ten var,toprak olmasın yine? 

Mustariptir kalp bu inkârdan.Yazık! 

Her nasıl aldıysa rûh,öz cismini,

Verecektir bir gün elbet,çok açık; 

Belki tek birrini belki bin mislini! 

* * *', 'Kaybolan tek sen misin? Ey merhamet!  Var mıdır insanda şerden başka his?  En güzel şehrinde ev ev sohbet et, Bir hazin mevzûdur insandan ba...', ARRAY['Türk Edebiyatı','Şiir','Şair Ahrazi']::text[], 8.5, '{"poet":"Şair Ahrazi","poet_slug":"sair-ahrazi","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/insan-86-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittin', 'gittin-ramazan-ates-jroa6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İlk bahar sanmıştım, güz olup gittin.

Açan gül gibiydin, toz olup gittin.

Küçüktün, körpeydin, cana yakındın,

Kapanmaz yaralar açıp da gittin.

Sanırdım herşeyi sende bulurum.

Seninle bir ömür mutlu olurdum.

Belkide yeniden hayat bulurum,

Sen hayel dünyamı yıkıp da gittin.

Kim derdi ki sende kötülük olsun? 

Kim derdi aşkını bırakıp gitsin? 

Bu gönül nasıl tahammül etsin? 

Gönlüme zehiri atıp da gittin.

Sana inanmıştım, seni sevmiştim.

Gönlümde sana bir saray kurmuştum.

Şu kısa ömrümü sana vermiştim,

Sen benim ömrümü tüketip gittin.

Gittin de ne oldu? Mutlu mu oldun? 

Şu koca dünyada bak yalnız kaldın.

Üç kuruş paraya nasıl aldandın? 

Sen senin ruhunu satıpda gittin.

Servete aldan ma, tez gelip geçer,

Rüyalar, gözünü açınca biter.

Pişmanlık şimdi fayda mı eder? 

Sen bütün her şeyi yok edip gittin.

Ramazan Ateş/Enschede-02.09.1997', 'İlk bahar sanmıştım, güz olup gittin. Açan gül gibiydin, toz olup gittin. Küçüktün, körpeydin, cana yakındın, Kapanmaz yaralar açıp da gitti...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gittin-108-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessiz Garip', 'sessiz-garip-cem-cagman-rzgjp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sessiz garip bir köşede

hayal kurar arada sırada

çaresizliğime çare arar

öylece dururum masada

düşünmek büyük işkence

kahr ederken olan bitene

tutuyorum  tek tek çetere

alırım hesabı günü gelince

düşürürsem bir punduna

uykusuz gecelerim adına

bırakmam hesabı yarına

bakarım seninde  tadına', 'sessiz garip bir köşede hayal kurar arada sırada çaresizliğime çare arar öylece dururum masada düşünmek büyük işkence kahr ederken olan bite...', ARRAY['Türk Edebiyatı','Şiir','Cem Çağman']::text[], 8.5, '{"poet":"Cem Çağman","poet_slug":"cem-cagman","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sessiz-garip-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık Boşuna', 'artik-bosuna-ramazan-ates-goqdy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen, yaşadıkca, var oldukca bu dünyada,

Hep beni arayacaksın, ama boşuna.

Ne yapsan nafile, kalacağım aklında,

Hep beni arayacaksın, ama boşuna.

Herkes hürmet edip dinlese de sözünü,

Servetin bol olsa, güldürse de yüzünü,

Gönlün dinlemeyip isyan edecek sana,

Hep beni arayacaksın, ama boşuna.

Şöhretin olsa ne olur, için yanıyor,

Yüzün gülse bile senin, gönlün sızlıyor.

Gündüzleri hayalinde, gece rüyanda,

Hep beni arayacaksın, ama boşuna.

Aynalar da söyleyecek gerçeği sana.

Bir küçük resim, bir işaret, bir hatıra,

Sen her zaman başını çevirip de yana,

Hep beni arayacaksın, ama boşuna.

Çok çektim acıyı, acı yetti bak bana.

Günlerce ağladım, çok düştün sen aklıma.

Yeter, ben uslandım. Aklım geldi başıma.

Sen beni arayacaksın ama boşuna,

Dünyayı bağışla, seni sevmem bir daha.

Ramazan Ateş/Enschede-01.12.1997', 'Sen, yaşadıkca, var oldukca bu dünyada, Hep beni arayacaksın, ama boşuna. Ne yapsan nafile, kalacağım aklında, Hep beni arayacaksın, ama boş...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/artik-bosuna-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Polis', 'polis-ramazan-ates-ftoc2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hakk’a hizmet aşkıyla,

Doludur bizim polis.

Vatandaşı, insanı,

Seviyor bizim polis.

Hak yolundan ayrılmaz.

Kırılırda eğilmez.

Haksızlığı affetmez.

Dürüsttür bizim polis.

Albayrağı gönderde,

Tutmaktır vazifesi.

Düşmanın emelini,

Yıkar hep bizim polis.

Kırar hain elleri,

Bu vatanı korur o,

Can dediğin nedir ki? 

Ölürde bizim polis.

Din, iman, namus ona,

Emanet vatan ona.

Şer gelmez hiç birine,

Nöbetci bizim polis.

Asker onun gardaşı,

Nöbette arkadaşı.

Severler vatandaşı.

Dosttur hep bizim polis.

Türkiye bu can vatan,

Albayrak vede Kur’an.

Yolunda o canından,

Olmakta,  şehit polis.

Ramazan Ateş/Enschede-4.7.2001', 'Hakk’a hizmet aşkıyla, Doludur bizim polis. Vatandaşı, insanı, Seviyor bizim polis. Hak yolundan ayrılmaz. Kırılırda eğilmez. Haksızlığı aff...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ateş']::text[], 8.5, '{"poet":"Ramazan Ateş","poet_slug":"ramazan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/polis-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhanet', 'i-hanet-ethem-turan-vbtpx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İhanet koymadım hiçbir zaman adını 

Hatta düşünmedim bile bir an olsun 

Hayatımı adadım sana santim santim serdim ömrümü

Üzerine basıp gidesin diye mi

İçimden çektim acımı 

Belli etmedim üzülür ezilirsin diye

Kara bağlar bağladım gönlüme 

Ve bir o kadarda güldüm sevinesin diye

Hiç mi kalbin sızlamadı  hiç mi duygulanmadın 

Bir kez olsun düşünmedin mi neden diye

Çok mu yaşadık saadeti 

Yoksa çabuk mu doyduk birbirimize 

Bak ağacın olmuş meyveleri gibi 

Düşüyor umutlarımız  bir bir yere

Bizi ısıtan sevgimiz

Yazın meltemi gibi kaybolup gidiyor

Sonbaharın serin rüzgarları ile

Ömür tükettim iyisi, güzeli,kötüsü ile

Arı olmadım geçen ömrümde

Çiçek çiçek gezip polen toplamadım 

Nefsimi beslemedim bal yapıp

Eşek arısı da almadım dilimin üzerine

Yılanla da sarılıp yatmadım hiç

Hayat pınarı da olamadım ama 

Gönül dostu oldum kısacık ömrümde

Duvarın nemden kabardığı gibi

Yavaş yavaş döküldü benim bedenimde

Ölüm, ölüm olsa bile  affetmiyor bu gönül

Sen ne dilersen dile', 'İhanet koymadım hiçbir zaman adını  Hatta düşünmedim bile bir an olsun  Hayatımı adadım sana santim santim serdim ömrümü Üzerine basıp gides...', ARRAY['Türk Edebiyatı','Şiir','Ethem Turan']::text[], 8.5, '{"poet":"Ethem Turan","poet_slug":"ethem-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/ihanet-79-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektuplar-18 12/12/2005', 'mektuplar-18-12-12-2005-mahzun-doga-jfyik', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Biliyorsun.

Yoktum. 

Senden önce.

Yer’in olmadan öncesi, 

su ve toprağın yabancı zamanı.

Ay’ın uyumsuzluğu, 

maddenin önemsizliği.

Bildiğim tek şeydi seni bilmek.

Biliyordum.

Biliyorsun.

Şimdi.

Biliyoruz. 

Sadece biz.

Saçlarının kokusu herkesçe unutulmuş.

Sadece ben biliyorum.

Tenin yaşamın en yasak bölgesi.

Sadece ben biliyorum.

Yüreğin yaşamanın kanıtı.

Sadece ben biliyorum.

Ellerim senin.

Gözlerim, gülüşlerim.

Sadece sen biliyorsun.

Hücrelerim senin.

Sen’im.

Sadece sen biliyorsun.

İkimiz.

Uzak iki ülke.

Canımız çiziliyor.

Yokuz.

Kovuluyoruz sevincin doruğundan.

Hiçbir gülmek tam değil.

Bakışlarımız yarım.

Ellerimiz.

Nefeslerimiz yarım.

Sadece biz biliyoruz.

Ruhlarımız yarım.

Biliyorsun.

Ne zaman birleşsek.

Su doğacak evrende.

Ateş yanacak ilk kez.

Dağlar sıraya dizilecek.

Ayrılacak birbirlerinden gökler.

Yıldızlar yerlerini alacak.

Yağmurla tanışacak toprak.

Ayrılacak geceyle gün.

Biliyorsun.

Ne zaman birleşsek.

Renkler ayrışacak tenimizde.

Mavi''yi alacağız ikimiz.

Rahmin turkuaz.

Sadece ikimiz biliyoruz.

Ne zaman birleşsek.

Kıyameti koparacağız.

Biliyorsun.

Sadece biz biliyoruz.', 'Biliyorsun. Yoktum.  Senden önce. Yer’in olmadan öncesi,  su ve toprağın yabancı zamanı. Ay’ın uyumsuzluğu,  maddenin önemsizliği. Bildiğim ...', ARRAY['Türk Edebiyatı','Şiir','Mahzun Doğa']::text[], 8.5, '{"poet":"Mahzun Doğa","poet_slug":"mahzun-doga","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/mektuplar-18-12-12-2005-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masum Çocuk', 'masum-cocuk-cahit-pehlivan-jhrby', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yıllar önce evinden ayrılmış,

Dünya’da ne dostu, nede arkadaşı varmış.

Hayatını bin bir cefayla yaşamış,

Bir masum çocuğun yaşam anısıymış.

Zaten o’nun Anne ve babası da,

Hayatta daima kahrettirmişler O’na,

Ne ekmeği, ne suyu olmamış sofrasında,

Ama gözyaşları her şeyi olurmuş, bu çocuğa,

Kendince bir sürü hayaller kurarmış,

Onlardan bir kurtuluş, bir çıkar ararmış,

Ama ne bir tane çıkar yol varmış,

Ne de onu kurtaracak insanlar.

Canı bir şey istemiş olsa dahi,

Ancak ona bakarak, geçirirmiş gözlerini,

Uzansa tokat yeyip, laf işitecek ki,

Ellerini sıkıp ağlarmış, kime ne desin ki? 

Kimse anlamıyormuş işte, bu çocuğun halini,

Sokaklarda sabahlıyormuş, evi gibi,

Park taşları yastığı olurmuş, tüy gibi,

Masum çocuk diye itilirmiş, kim ilgilenir ki? 

Üstü yırtık ve dökükmüş, bin pişman.

Ona yardım edecek bir insan evladı,

Doğrusu,çıkarmadı kader onun karşına 

Koruyup, gösteremediler de doğruyolu, O’na.

Toprağın bağrında O şimdi rahat uyusun,

Onun anısına dikili, masum bir anıtı olsun,

Onu görüp, onu duyan saygı duysun,

O masum çocuktan da, yalnızca ibret alınsın.

Onun mezarından ayrılınca,

Onun gibi niceleri var, şu dünyada.

Onlar anılıp, yardımcı olunursa,

O garip masum çocuk, 12 yaşında,

Yoksul bir yaşantı içinde,

Ayrıldığı bu Dünya’ya belkide,

Bir kerecik mutluyum diyecekse,

Mezarında hep ağlayan o gözleri,

Bir kerecik olsun gülecekse,

O zaman şükranlarını iletecektir sizlere,

Masum çocuk için çok geç oldu artık.

Bu Dünya’da ne gülecek, ne ağlayacak,

Aramızdan ayrıldı, hiç anlayamadık.

Bir sürü çilelerin kurbanıyken O.

Keşan', 'Yıllar önce evinden ayrılmış, Dünya’da ne dostu, nede arkadaşı varmış. Hayatını bin bir cefayla yaşamış, Bir masum çocuğun yaşam anısıymış. ...', ARRAY['Türk Edebiyatı','Şiir','Cahit Pehlivan']::text[], 8.5, '{"poet":"Cahit Pehlivan","poet_slug":"cahit-pehlivan","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/masum-cocuk-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SANA nehir benim sevgim! !', 'sana-nehir-benim-sevgim-hilal-gul-aydin-mrzox', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sana nehirdi benim sevgim

Ateşi sanaydı bu tenimin

Yarasa harflerle,

Baş sayfasına çizdim seni kaderimin.

Her noktada büyükçe

Her virgülde devleşti,

Sana olan hasretim.

Damla başına ağıt yaktırdım bu aşka

Ya olmalıydı senle hayat

Yada, 

Bitmeliydi bu ömür.

Kafeslerini açtım bütün biçare sevdaların.

Gönlüme girmesi gereken 

Ve sana yaraşan bir ehemmiyetle

Halleşiyorum bana bıraktığın özleminle..

Dışarıda ayaz..

Elleri soğuk yorganımın.

Yüzüm yok oluyor ıslandıkça her dakika.

Zindanlarımda gardiyanlar.

Ceplerinde yarım bıraktığım aşklarım.

Kovalayan kovalayana duygularımı.

Kimsenin umurunda değil.

Seni sevişlerim.

Korkuyla senin aranda mekik dokuyor yüreğim.

Her bakışımda gözlerine,

Beynime indiriyorlar bir daha dönmeyeceğini..

Suya yazıyorum kimse görmesin diye,

Kazıyorum benliğime kokunu.

Ben sana hasretimi,

Her gece yastığımın ücra köşelerine bırakıyorum.

Kimseye duyurmadan.

Sonra her gece beni sana uyandırıyorum.

Sen olmadan doğmayacak hiçbir güneş sabahlarıma.

Söz verdiler yıldızlar,

Gitmeyecekler sen gelmeden.

Sen sussan da bekleyecekler.

Çünkü; 

Benim aşkım SANA! ! ! 

Çünkü; 

Sana nehir benim sevgim,

Ve sanadır bütün ateşi tenimin', 'Sana nehirdi benim sevgim Ateşi sanaydı bu tenimin Yarasa harflerle, Baş sayfasına çizdim seni kaderimin. Her noktada büyükçe Her virgülde d...', ARRAY['Türk Edebiyatı','Şiir','Hilal Gül Aydın']::text[], 8.5, '{"poet":"Hilal Gül Aydın","poet_slug":"hilal-gul-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/sana-nehir-benim-sevgim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cansız Aşk', 'cansiz-ask-hilal-gul-aydin-prcnn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sana hoş geldin deyip öyle gitmek vardı.

Ama kusuruma bakma,

eğer bir kez daha baksaydım gözlerine.

İnan dayanamazdım.

Uzun zaman olmuş alışalı yokluğuna. 

Seni de görmeyeli.

Bütün bir ömrümü senin geleceğin günü beklemekle geçirdim.

Seni bir kez daha görüp, sonra ölebilmek için

Gittiğin günkü yerdeyim üstelik.

Telvelerin altında güneşin en çok vurduğu

ve ayrılığın en çok koyduğu yerde

Ellerim titrerdi seni görünce karşımda, 

nedendir bilmem ne zaman gülsen 

sana sevdiğimi fısıldardı koca Fırat

gittiğin an bitti bütün dünyam.

Paramparça oldu senin kahrından umutlarım.

Sessiz gidişine üzüldüm en çok beni gerçekten sevmeyişine.

Hayallerimi aldı benim dediğim ellerin.

Ve ben hala senin beni bıraktığın yerdeydim.

Saf sevgiler oldu yalnızlığımda avunduğum.

Her sevgiliye gıpta ile baktım.

Nereye baksam yüreğimle karşılaştım.

Bir fırtına gibi sarstı yokluğun

o kadar da uğraştım

sensiz kalmayayım diye

olmadı, yapamadım.

Güllere sevda şarkılarım yazıldı senden sonra buralarda

çınar altları doldu efkârlanıp ağlayanlarla.

Zamana inattı benim hallerim.

Meğer ben sana elini uzattığın kadar.

Yakın yerdeyim

her susuş bir son oldu bana

oysa ne kadar alışmıştım onca acıya

hasretlerimi aldı sözlerin

benim en güzel çağlarıma yağmurlar yağdı

yollara vurdum her dakika 

hasret dediğim türküleri

sensizliği çekemedi bu zavallı kalbim

kaderime kurban mıydım acaba

yoksa zembereğe zehir mi aradılar? 

Sonra beni mi buldular karartacak.

Yok, edecek gün ışıklarımı...

Bak onca şey oldu burada.

Bir kere olsun gelip dedin mi? 

''''Sevdiğim sağmı yüreğin''''

istemedim ayrılığı tattırmak sana

hissettirmek istemedim 

bu kadardı bana sevgin

giderken yüzüme dönüp tek kelime etmedin.

Sabahlara kadar kâbuslarım oldu.

senden bana kalan bu şehir

sahte oyunlar ürettiler bana

sende yoktun üstelik

bu gün geliyormuşsun

umurumda değil

sana vicdanını bırakıyorum hesap sormayı beklediğim

bir de bensiz çınar altlarını

karanfil kokulu çayları

masum Fırat’ı

seni kızına bırakıyorum adını taşıdığım

sevgilere, aşklara

veda etmedim ben hiç sana

ne Fırat tan geçebildim ne de sensiz edebildim

sirkindim ve kendimdeyim.

Bıraktığın yerde şimdi cansız bedenim.', 'Sana hoş geldin deyip öyle gitmek vardı. Ama kusuruma bakma, eğer bir kez daha baksaydım gözlerine. İnan dayanamazdım. Uzun zaman olmuş alış...', ARRAY['Türk Edebiyatı','Şiir','Hilal Gül Aydın']::text[], 8.5, '{"poet":"Hilal Gül Aydın","poet_slug":"hilal-gul-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":65,"source_url":"https://www.antoloji.com/cansiz-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keşan’lı Güzele', 'kesan-li-guzele-cahit-pehlivan-up7ph', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seyyah oldum, geziyorum yurdumu,

Geziyorum, batımı doğumu,

Görüyorum güzelim Anadolu’mu

Görüyorum, cennet yurdumu,

Şimdi durak verdim Keşan’da,

Yarenler başı olmuşuz burada,

Sazıma dokunurum ellerimle,

Aşk nameleri yakarım, sözümle,

Duyasın beni diye hayatım.

Senin içindir, sözüm sazım,

Senin için çıkar avazım.

Seni görmek için geliyorum,

Yollar bozuk olan o mahallenize,

Geçerken evinizin önünden,

Her yerde seni arıyorum ben.

Bana bakıp gülüyorsun pencereden,

Bakışlar bir şey anlatmıyor nafile,

Bir çift söz olsun, etmek isterim seninle,

İsmim..... demiştin bana bir kere,

Avunuyorum bu sözünle işte,

Gece gündüz karşımda duruyor,

Bana gülümseyen hayallerinde,

Hayatım ne olursun üzme beni,

İnan çok ama çok seviyorum seni,

Yüce Tanrım, size neden böyle özendi ki? 

Bir sihir mi? Büyü mü? Çözemedim ki.

Sevgilim bu mısralarım şahit sözüme,

Gönül ferman dinlemez, seni sevdim bir kere.

Bana istersen hayır, istersen evet de,

Sana aşk çağrısı yapıyorum, 

Bu kırık dökük ve aynı zamanda,

Kimsesiz mısralarımın sözleriyle size. 

Keşan', 'Seyyah oldum, geziyorum yurdumu, Geziyorum, batımı doğumu, Görüyorum güzelim Anadolu’mu Görüyorum, cennet yurdumu, Şimdi durak verdim Keşan’...', ARRAY['Türk Edebiyatı','Şiir','Cahit Pehlivan']::text[], 8.5, '{"poet":"Cahit Pehlivan","poet_slug":"cahit-pehlivan","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/kesan-li-guzele-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayallerim yanıyor', 'hayallerim-yaniyor-kamuran-gunduzalp-pzxlg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Isyan etti yürek 

bir kelimede noktalandı acılar. 

Dua edercesine döküldü dudaklarımdan ismin, 

nerdesin? 

Dışarıda kar yağıyor sevgili 

o sevdiğin kasımpatı çicekleri, 

kaldı karların altında.... 

Şöminedeki alev aşk''a davetkar 

yanıyor hayaller 

Gece yarılarında ki yalnızlığın sesi 

dalgaların sesine eş 

kayboluyor mavilerde 

nerdesin? 

Anlamadı gönül 

herşeyin bittiğini 

terkedip,gittiğini 

çaresizce soruyor esen rüzgarlara 

nerdesin? 

Bir serçe gibi sekeliyor gönül 

ha düştü ha düşecek.. 

köprü altındaki dilenci 

bir baykuşun gözleriyle bakarken 

iç çekiyor 

perde ardı yasak aşk''lara 

Köşe başında bekleyen fahişenin 

donmuş gözyaşları yanaklarında, 

ağlamıyor... 

Onun feryadı daha büyük 

yırtıyor geceyi, 

unuttun, unuttun beni burda TanrIm 

Nerdesin? .. 

10/ 12/ 05', 'Isyan etti yürek  bir kelimede noktalandı acılar.  Dua edercesine döküldü dudaklarımdan ismin,  nerdesin?  Dışarıda kar yağıyor sevgili  o s...', ARRAY['Türk Edebiyatı','Şiir','Kamuran Gündüzalp']::text[], 8.5, '{"poet":"Kamuran Gündüzalp","poet_slug":"kamuran-gunduzalp","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/hayallerim-yaniyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşlanıyoruz Galiba', 'yaslaniyoruz-galiba-cahit-pehlivan-uvz72', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Daha dün gibi idi, her şeyler

Evet, evet hatırlıyorum. O günleri...

Elime ilk kalemimi, kitabımı,

İlk çantamı ve silgimi alışımı,

Bir parçacıkta olsa hatırlıyorum.

Üzerimde beyaz yakalı kara önlükle,

Evimizden ayrıldığım anları,

Annemin de yanağıma kondurduğu, öpücüğünü,

Babamın, o zamana kadar hissetmediğim

Baba eliyle, elimden tutup okuluma götürdüğü, günü.

Sonra, günler, aylar ve hatta yıllar

Dolu, dizgin geçiyordu. O zamanki yaşantılar.

Orta ve lisede gül fidanı gibi

Bir gençliğin sahibi idim.

Ah! .... evet, evet bir sahibi...

İlk kurlar, ilk flörtler, ilk aşk melodileri,

Galiba, yine ilk defa, o zamanlar algıladım dı,

Şarkılarla bizlere anlatılmak istenenleri, 

Yine o zamanlarda, bir pay alırdım kendime,

İnsanı çılgın denizlere döndüren şarkılardan

Neler, neler gelip geçti o zamanlarda,...

Hani yaşlıların bir deyimi olacaktı ya:

“Köprülerin altından ne sular aktı.”

Gibi bir şey; o dönemlerimin anlatısı,

Sonra İzmir, Kordon boyu eğlenceleri,

Karşıyaka gemisi ve Karşıyaka’nın

Rengarenk zevkli ve neşeli geceleri,

Hani o gecelerde insan yaşlanacağını,

Hiç aklına getirmek istemiyordu. Neden ki? 

Sevgilinin kolu kolumda, elleride ellerimde.

Sıcaklığını hissederdim. Kalbimin her sektesinde.

Bin bir hayaller kurardım. Onunla birlikte.

Küçücük bir kafeteryada kurulan, büyük bir dünya,

O dünya ile bahşedilmiş koca bir yaşantıya

Renk katarlardı, anne babaya çocuklarda 

İç içe yaşardık, “Dam”ın yanındaki bir kafeteryada

Kurduğumuz bu rüyadaki, bizim olan dünyada.

Sonra yudumlanan içkiler, mezeler.

Sigaralarımızla duman duman olmuş.

Bizimle iç içe geçip var olan evrenler,

Ah! .... neydi o günler, neydi bilmiyorum.

Sanki o zamanlar mevsimler hiç yoktu.

Yada mevsimler vardı ama, sonbahar...

Ah! ... evet, sanki bu mevsim hiç yoktu.

Ne bileyim. Vardı da ben farkında mı değildim? 

Allah’ım bize, neden üç mevsim bahşetmedin? 

Ne gerek vardı sonbahara? Öyle değil mi? 

Bu mevsim daha birkaç yıl önce yoktu da; 

Yeni keşfedilip, bize bahşedilmiş gibi,

Her yıl bu mevsimin gelişi, bir öncekinden daha sükseli,

Bizleri ise, daha da etkileyici oluyor. Neden ki? 

Hani şöyle kordon’da, bir teknenin içinde,

Dudağımdaki nargilenin verdiği huş içinde,

Mevlana misali, döner dururdum İzmir’in dört köşesinde.

Bir körfezinde, Karşıyaka’sında, Fahrettinin’de,

İnci, inci gerdanlık olan Çeşme ilçesinde,

Yalılarında, hem küçüğünde, hem güzelinde, 

Cıvıl cıvıl kaynayan sebilli kemerinde,

Konak’ta ki saat kulesinde, camiisinde...

Dolanıyorum, canım İzmir’in  her köşesinde,

Nargilemin bana haz veren, her nefesinde,

Fuar’ında, Alsancağ’ında, Kadife Kalesinde,

Ah! ... o zamanlar Kordon''da gezerken,

Denizde hiç dalga yok mu idi? Bilmiyorum.

Ama şimdi bu körfezin dalgası bana,

Beyaz beyaz  kucaklaşarak gelip vurunca, kıyıya,

Sanki, bana daha önce bahşetmiş olunanlara,

Sahip olmak ister gibi coşuyorlar,

Emanetlerini geri almak ister gibi sesleniyorlar.

Kıyıya vurup geri geri dönen dalgalarla,

Bu dalgaların melodileri, beni çok korkuttu.

Gelmişi, geçmişi benden sanki geri istiyordu.

Bu isteğine ne diyeceğimi, inan ki bilemedim.

Hatta, körfezdeki akşam ufkunun izlencesini,

Gözümdeki gözlükler olmasa idi. Hissedemeyecektim.

Ya o imbatın tatlılığıyla, bir sağa bir sola,

Savrulan saçlarımın yerinede; kırarmış saçlarla,

Elimde de bir asa ile; kucak açıyorum, imbata

Bu hesaplaşmamı yaparken, bir kanepe üzerinde,

Gün batmak üzere idi. Akşam grubunun kollarında,

Her şeyime, yıllardır ortak olan gözlerimle,

Körfezi süzerken, martılar uçuşuyordu.

Eskisi gibi, bir karşıyaka gemisinin üzerinde,

Ya gençler, evet evet ya şu gençler,

Onlarda daha önce bizim oynadığımız filmlerde,

Kimi yeni jön, aktör, kimileride aktris.

Kendi hayat filmlerinde rol almışlar,

Ve hepside başrol oynuyorlar.

Felek denen o nesneden, sanki intikam alıyorlar.

Bu yaşlarda, insan böyle düşünüp algılıyor.

Biraz yaşlanınca, o feleğin elinde bir piyon oluyor.

Yaşamını idame ettirmek için; tıpkı o piyon gibi,

Daima düzgün olacak, hayattaki yolun.

Yaşlanmak ise; doğal bir olgu, tasası olamaz bunun.

Çıkartmalarına fırsat verme, kollarımda dursun, kolun.

Onlarla da birlikte olduğun müddetçe,

Neşe, mutluluk, bahtiyarlıkla dolacaktır. Ömrün.

Allah’ım benim gibi ihtiyarlıyoruz galiba dedikçe,

Bir zehaba, bir tasaya düşmesin artık hiçbir kulun.

İzmir&Kars', 'Daha dün gibi idi, her şeyler Evet, evet hatırlıyorum. O günleri... Elime ilk kalemimi, kitabımı, İlk çantamı ve silgimi alışımı, Bir parçac...', ARRAY['Türk Edebiyatı','Şiir','Cahit Pehlivan']::text[], 8.5, '{"poet":"Cahit Pehlivan","poet_slug":"cahit-pehlivan","theme":"Türk Şiiri","is_hero":false,"total_lines":100,"source_url":"https://www.antoloji.com/yaslaniyoruz-galiba-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Çiçek', 'tek-cicek-ethem-turan-lf12j', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne kadar çiçek ismi varsa saymak istiyorum 

Bahçede yetişen. dağda yetişen,vadide ve yaylada yetişen 

Hepsini ama hepsini saymak geliyor içimden 

Ama birini ayrıca söylemek istiyorum 

Seni

Çiçeklerin dertlere deva olduğunu okudum 

Sen zaten benim ilacımsın

Çiçeklerin güzel koktuğunu duydum 

Sen  mis kokumsun 

Dediler ki çiçekler çok güzeldir

Güldüm için için senin yanında mı diye

Çiçek tohumun ve üründür dediler 

Düşündüm sen zaten annesin diye

Ulu ağaçlar geldi aklıma 

Ve bir o kadarda minik otlar 

Hepsinin telaşı bir çiçek mi açmaktı diye

Sen benim ömrümde açan tek çiçektin 

Ölene dek solmamak üzere', 'Ne kadar çiçek ismi varsa saymak istiyorum  Bahçede yetişen. dağda yetişen,vadide ve yaylada yetişen  Hepsini ama hepsini saymak geliyor içi...', ARRAY['Türk Edebiyatı','Şiir','Ethem Turan']::text[], 8.5, '{"poet":"Ethem Turan","poet_slug":"ethem-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/tek-cicek-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Sıradaymış Melek', 'son-siradaymis-melek-nurdan-unsal-jj82h', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kavrulmuş topraktan putlarım

yazısız yüzüm güneşe aya dönük

soysuzdur ölüm  zamansız

meleklerin sırası şimdi

aşk şeytana yakıştı

12.12.2005', 'kavrulmuş topraktan putlarım yazısız yüzüm güneşe aya dönük soysuzdur ölüm  zamansız meleklerin sırası şimdi aşk şeytana yakıştı 12.12.2005...', ARRAY['Türk Edebiyatı','Şiir','Nurdan Ünsal']::text[], 8.5, '{"poet":"Nurdan Ünsal","poet_slug":"nurdan-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/son-siradaymis-melek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rahibe', 'rahibe-kamuran-gunduzalp-rn36x', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gece yarısı, 

Terkedilmişken yalnızlığına 

Aksini gördü aynada 

O sadece bir kadındı 

Tüm güzelliğiyle 

Kendini İSA''ya gelin adamış, 

Bakire duygularıyla, 

Karanlık gecelerde 

Dişiliğiyle mücadele eden... 

Kendisini seyretti rahibe 

Güzel gögüslerine kaydı eli, 

Saçlarnı okşadı, 

Titreyen dudaklarına baktı 

Kendini kendi gözlerinden kıskandı 

Bir çan sesiyle ürperdi 

Hayal dünyasından uyanıp 

Giydi siyah cübbeyi, 

Sorumluluklarını yükledi sırtına 

İsyan ederek kadınlığına, 

Yönlendi kilise yoluna.... 

Dua ederken ''İSA''ya,ağlıyordu 

Tövbe etti kadınsal duygular yaşadığına,,, 

03-04-05', 'Gece yarısı,  Terkedilmişken yalnızlığına  Aksini gördü aynada  O sadece bir kadındı  Tüm güzelliğiyle  Kendini İSA''ya gelin adamış,  Bakire...', ARRAY['Türk Edebiyatı','Şiir','Kamuran Gündüzalp']::text[], 8.5, '{"poet":"Kamuran Gündüzalp","poet_slug":"kamuran-gunduzalp","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/rahibe-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırda kelebek kovalarken adını unutan çocuk', 'kirda-kelebek-kovalarken-adini-unutan-cocuk-samiha-i-kbal-5edxt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Düşümde düşündüm

Düşünülmemiş düşleri

Çam ağaçlarının yapraklarını yoldum

Saçlarını ördüm.

Kırda kelebekleri kovalarken 

Adımı unuttum.

Gereğinden fazla yaşamışım

Upuzun yalnızlığımda

Buluş ve kaybedişten hemen sonra

Düşümde düşündüm.

Düşümde bile yakıştıramadım

Ölümü çocuklara

Savaşı büyüklere yakıştıramadığım gibi

Silahı sevmediğim, kavgayı bilmediğim gibi

Düşümde düşündüm

Görkemini gözyaşının 

Bu kaçıncı uyku

Bu kaçıncı uyanış

Bu kaçıncı unutuluşu İSMİN.', 'Düşümde düşündüm Düşünülmemiş düşleri Çam ağaçlarının yapraklarını yoldum Saçlarını ördüm. Kırda kelebekleri kovalarken  Adımı unuttum. Gere...', ARRAY['Türk Edebiyatı','Şiir','Samiha İkbal']::text[], 8.5, '{"poet":"Samiha İkbal","poet_slug":"samiha-i-kbal","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kirda-kelebek-kovalarken-adini-unutan-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kardeşime', 'kardesime-halis-babat-v1tze', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu sabah bir gazetenin ara sayfalarında okudum:

Bir abi ve kardeşin dramını.

Abi bir fabrikada hamallık yapıp, kardeşini okutmaya çalışıyormuş.

kardeş okulda son derece başarılı,

ama top oynamayı da çok severmiş.

Her okul çıkışında arkadaşlarıyla sokakta top oynarmış.

Ve yine birgün sokakta top oynarken,

bir mağazanın camını kırmış.

Mağaza sahibi abiyi kenara çekip,

bir aylık maaşını almış.

Abi bunun üzerine kardeşini tokatlamış.

Kardeş gururuna yediremeyip, yaşamını noktalamış.

Sonra abi aynı silahla,bir sonraki kurşunla,

hayatına son vermiş.

İki yaşam bir nefrete kurban olup,

iki beden bir bedende yok olmuş.

Bu sabah bir gazetenin ara sayfalarında okudum:

Bir abi ve kardeşin dramını.

Sanki gazetenin sayfalarına gömülmüş,

bir mazi çığlığıydı yazılanlar.

Nefretin sevgiyi yok ettiği,

sarılışların,kendini sillelere teslim ettiği,

kardeş bakışların düşmanlaştığı satırlardı.

Ve beni, benden koparıp, uzaklaştıran bir dramdı.

Ansızın mazi perdesi,

isyan edercesine yırtılıverdi.

Beyaz siyahlaşıp kapkaranlık oldu aydınlık.

Yor''lu zamandayken, miş''li zamanda buldum kendimi.

Ve işte o an, o an gözlerimin şafağında,

ateşten bir nehir gibi aktı pişmanlık.

Bir avcının namlusunu, ceylana doğrulturcasına,

doğrultmuştum, tokadımı kardeşime,

yalvarırcasına dur! Dur ellerim dur! Diyordum.

Ama durmuyordu kırılası ellerim.

Geçmişteki nefreti, şimdi yaşla karşılıyordu,

lanet olacası gözlerim.

Ve utanıyordu, utanıyordu geçmişimden  şimdim.

Kızarmış yüzü,  yaşarmış gözleriyle,

öyle suskun bakıyordu ki kardeşim.

Her nefeste bir daha ölmek istedim.

Şimdi uzağım, anlıyorum,

seni ne çok sevdiğimi kardeşim.

Neden sanki sevgi ulaşılmadığında güzeldir? 

İnsan sevdiğinin kıymetini uzaktayken daha iyi anlarmış.

neden kardeşim,neden..? 

Yakınlığın kardeşi kardeşten uzaklaştırması neden?', 'Bu sabah bir gazetenin ara sayfalarında okudum: Bir abi ve kardeşin dramını. Abi bir fabrikada hamallık yapıp, kardeşini okutmaya çalışıyorm...', ARRAY['Türk Edebiyatı','Şiir','Halis Babat']::text[], 8.5, '{"poet":"Halis Babat","poet_slug":"halis-babat","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/kardesime-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabahların müjdesi', 'sabahlarin-mujdesi-samiha-i-kbal-dphh9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu gece kızıl gözlerin ucundayım

Kaba ses denizinde bir can simidi ararken

Sessizlik yetişti ellerime

Yüzler yüzlerden dönük, yıldızlar çarpışırken

Ve ararken

Doğru olanı sayısız defalar

Bir muştudan habersiz

Kara kediler boğuşuyordu yüreğimde

Ve böyle anlarda

Yüreğimin tercümanı puslu gözlerimdir

Orada ise gerçeğin en çirkini yalanın en güzeli

Avunduğum tek sermayemdir.

Aslında

Parmaklar arasında bir tutam saçta

Gizlidir bütün açılar

Sizler de bilmelisiniz kadirşinas geceleri

Ağlamalısınız gecelerin arka yüzüne

Ağlayın, inci gözyaşlarınızı mumyalayın

Onlar bir günahın kefaretidirler

Ve sabahın müjdesidirler...', 'Bu gece kızıl gözlerin ucundayım Kaba ses denizinde bir can simidi ararken Sessizlik yetişti ellerime Yüzler yüzlerden dönük, yıldızlar çarp...', ARRAY['Türk Edebiyatı','Şiir','Samiha İkbal']::text[], 8.5, '{"poet":"Samiha İkbal","poet_slug":"samiha-i-kbal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sabahlarin-mujdesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İster miydim istemezdim', 'i-ster-miydim-istemezdim-samiha-i-kbal-gdt9w', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İstemezdim,

Gölde dans etmeyi

Bir kuğuyla.

Nemrud’un beton güneşinde

İster miydim konuşmak

Dil balığıyla

Havadan sudan.

Yaşamak istemezdim

Altı ay gündüzü,

Altı ay geceyi

Kutuplarda, kutup ayılarıyla.

İster miydim 

Dinlemek

Bethoven''ın yeni bestesi

Cehennem nağmelerini

Zebaniler eşliğinde.

Yine ister miydim,

Güneşin hiddetinden

Gölge olmak

Bulutlara.

Hiç istemez miydim,

Sohbet etmeyi

Rasulüm''le,

rüyamda

Bir saniye...

Ah ne çok isterdim

Kul olmayı RABB ''ime

Hayatımda her saniye', 'İstemezdim, Gölde dans etmeyi Bir kuğuyla. Nemrud’un beton güneşinde İster miydim konuşmak Dil balığıyla Havadan sudan. Yaşamak istemezdim A...', ARRAY['Türk Edebiyatı','Şiir','Samiha İkbal']::text[], 8.5, '{"poet":"Samiha İkbal","poet_slug":"samiha-i-kbal","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ister-miydim-istemezdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi bir sevda düştü hayallerime', 'mavi-bir-sevda-dustu-hayallerime-samiha-i-kbal-76vcf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Deniz belli ki yorgun

Gözlerin gibi mavi ve durgun.

Duygu yüklü vapurumun sığındığı

Son limanda

Mavi bir sevda düştü hayallerime

Ölen şehirde 

Öldüren şehirde

Bir mavi kalmış,

O da gözlerinde.

Neyi beklersin yorgun sahillerde

Hangi gerçeği? 

Bense,

Çılgın nehirler akıtmak isterim içimde.

Her göz kırpışta 

Akseder gönlüme

Serencamın mutluluğu

Kalbim sahrada bütün mutlulukları aşar

Susuzlukla kuruyan dudaklar

Bu mavilikle coşar.', 'Deniz belli ki yorgun Gözlerin gibi mavi ve durgun. Duygu yüklü vapurumun sığındığı Son limanda Mavi bir sevda düştü hayallerime Ölen şehird...', ARRAY['Türk Edebiyatı','Şiir','Samiha İkbal']::text[], 8.5, '{"poet":"Samiha İkbal","poet_slug":"samiha-i-kbal","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/mavi-bir-sevda-dustu-hayallerime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lirik 4', 'lirik-4-fevzi-cebe-uqg5u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ben seni gerçekten sevdim

ben seni gerçek gibi sevdim

			

08.03.2004.22.09', 'ben seni gerçekten sevdim ben seni gerçek gibi sevdim 			 08.03.2004.22.09...', ARRAY['Türk Edebiyatı','Şiir','Fevzi Cebe']::text[], 8.5, '{"poet":"Fevzi Cebe","poet_slug":"fevzi-cebe","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/lirik-4-eski-bir-yalan-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimsin sen', 'kimsin-sen-samiha-i-kbal-ii66u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şişelerdeki   badeler gibi yıllanmış

Gönüllerde sevdan

Sahi kimdin sen? 

Masal bahçelerinin

Hiç solmayan çiçeği mi? 

Yorgun göçmen kuşlarının

Kanatlarını kaldıran sonbahar rüzgarı mı? 

Sahi sen kimdin? 

Anamın belediği benimle birlikte beşiğe

Sıcacık.

Alacakaranlıkta gözlerin

Birer ateş topu

Yıkıyor gönül tabularını

Sahi kimsin sen? 

Çilekeş aşkların davetsiz konuğu.

Yürekteki fırtınanın devrilen ağaçları

Yuvasız kalan kuşları.

Göl ortasında susuzluğa susamış

Bir nilüfer mi? 

Çöl ortasında yağmura aşık

Bir bedevi mi? 

Sahi kimsin sen? 

Bir yerlere yazmıştım adını

Bulabilirsem...', 'Şişelerdeki   badeler gibi yıllanmış Gönüllerde sevdan Sahi kimdin sen?  Masal bahçelerinin Hiç solmayan çiçeği mi?  Yorgun göçmen kuşlarını...', ARRAY['Türk Edebiyatı','Şiir','Samiha İkbal']::text[], 8.5, '{"poet":"Samiha İkbal","poet_slug":"samiha-i-kbal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kimsin-sen-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlıklar Ülkesine Gidiyorum.', 'karanliklar-ulkesine-gidiyorum-ali-osman-yilmaz-6w8eq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Atımı dört nala,

Karanlıklar vadisine doğru,

Sürmekteyim.

Gün ışığı tükenene kadar,

Gecenin koynuna doğru,

Kapkara bir yalnızlığa,

Kanat açmış,

Atımı çatlatırcasına,

Dört nala koşturmadayım.

Senden çok uzaklara,

Hatta kendimden bile,

Uzaklara,

Senin ve benim,

Birlikte olamayacağımız,

Karanlıklar ülkesine,

Gidiyorum.', 'Atımı dört nala, Karanlıklar vadisine doğru, Sürmekteyim. Gün ışığı tükenene kadar, Gecenin koynuna doğru, Kapkara bir yalnızlığa, Kanat açm...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/karanliklar-ulkesine-gidiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendinin Olman İçin', 'kendinin-olman-i-cin-ercan-cengiz-ysuvl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zaman prangalara vurulmuştu

Acının gizemi karanlıklar içinde

Beyinlere oturtulmuş bir yelkovan

Eldeki kadehle tokuşurdu emeğin

Çaresizliğindir, yükündür

Kamburundur.

Ayağın sarp yollara düşerdi

Konuşmamanın,

Konuşamamanın ölçütü

Duyuramadığın çığlığındı

Karanlığın gizemi...

Katledilen doğacındı damar damar

Yayılmış acılarının bileşkesi,

Tarihin o acılardadır senin, sallanır

Kazınır dirhem dirhem.

Konuşamaman zamana kurulmuştu

Zaman prangalara vurulmuştu

Ürperirim ki

Boğuk sesin duyurmaz çileni

Acını, açlığını gidermez.

Karanlığın gölgesi yükselirdi,

Ağırdır

Vurunca da sırtından vurur

Uyan, 

Uyan ki

Kendinin olman için...

(Ezgilerde Kaldı Yüreğim 1.Kitap)', 'Zaman prangalara vurulmuştu Acının gizemi karanlıklar içinde Beyinlere oturtulmuş bir yelkovan Eldeki kadehle tokuşurdu emeğin Çaresizliğind...', ARRAY['Türk Edebiyatı','Şiir','Ercan Cengiz']::text[], 8.5, '{"poet":"Ercan Cengiz","poet_slug":"ercan-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/kendinin-olman-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Var mısın,Orda mısın', 'var-misin-orda-misin-ahmet-erdem-kaya-iewpn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '-----Yaklaş

 Siyahına çiğ düşmüş gecelerime,

 Yoldaş ol

 Ak matemimin içine............

 Ziyama yaklaş...

------ Koş

 Hayal edilen ol, güllerin çehresindeki

 nara koş...

 Bilsen yanmak sevdanın koynunda ne hoş...

 Durma içimdeki yangınına koş......

------Bak

 Mahlukatı ardınsıra döndüren bir alev umut

 vakit yalan olunca yorumsuz dönüşlerine 

 dönde bir bak......

------Düş

 Gözlerim gözlerinden düştü,

 bir gülden kopan dikenler gibi

 ben sende değilim,

 Sense artık gecelerimde uykumu bölen

 Yabancı bir düş........ 

-------Gör 

 Tüm ağmaların gözleri kamaştı,

 sevgimin şavkından,

 Hadi sende gör şeytanın gör dediğini 

 Durma gör........', '-----Yaklaş  Siyahına çiğ düşmüş gecelerime,  Yoldaş ol  Ak matemimin içine............  Ziyama yaklaş... ------ Koş  Hayal edilen ol, gülle...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Erdem Kaya']::text[], 8.5, '{"poet":"Ahmet Erdem Kaya","poet_slug":"ahmet-erdem-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/var-misin-orda-misin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Yağmur Demeliyim', 'sana-yagmur-demeliyim-ahmet-erdem-kaya-l4jd2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hangi toprak sevmez baharda yağmuru

 Ben yağmur demeliyim sana.......

Gözlerden boşalan yaşlarla kentin yıkanan yalnız kaldırımları değil midir

 üzerinde gezdiren bütün bir ömrün selini

  Sabah oluyor bak bu şehirde

  ve ben sana hiç söylemedim bak şimdi söylüyorum

  ben seni çok seviyorum;   Dinle; 

 Ben sana yağmur demeliyim.

 Her kederin ötesindeki yokuluklarında

 sevdaların ölmediği iklimlerin serin rüzgarları değil miydi seni bana getiren

 Sen yağmur olmalısın çorak topraklara dökülen

 Ve ben yağmur demeliyim sana, Sen yağmurum olmalısın........', 'Hangi toprak sevmez baharda yağmuru  Ben yağmur demeliyim sana....... Gözlerden boşalan yaşlarla kentin yıkanan yalnız kaldırımları değil mi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Erdem Kaya']::text[], 8.5, '{"poet":"Ahmet Erdem Kaya","poet_slug":"ahmet-erdem-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sana-yagmur-demeliyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pervane', 'pervane-sinan-oktay-zdsdb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevmez pervane ateşe su dökeni

Yanar zanneder ateş kendi için 

Dualar etmiştir,tohumdan agaç oluncaya dek.

Yandırır, bir çift gözdeki kıvılcımla..

Dönmek için ateşinde aşkın,

Yanmak için ateşinde aşkın.', 'Sevmez pervane ateşe su dökeni Yanar zanneder ateş kendi için  Dualar etmiştir,tohumdan agaç oluncaya dek. Yandırır, bir çift gözdeki kıvılc...', ARRAY['Türk Edebiyatı','Şiir','Sinan Oktay']::text[], 8.5, '{"poet":"Sinan Oktay","poet_slug":"sinan-oktay","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/pervane-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreği Beyaza Bulanmış Adam', 'yuregi-beyaza-bulanmis-adam-melih-coskun-yccjq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Elleri, yüzü kir pas içinde 

Ama yüreği beyaza bulanmış bir adam 

Sevgisini kuşanıp 

Dünyanın en güzel dizeleriyle dayanırsa kapına 

Gülümsemeni eksik etme gözlerinden.

O adam aşkını kavgasıyla harmanlayıp

Dağlara meydan okumaktadır her gece 

Ve yorgun dizlerine inat 

Ayakta durmaya çalışıyorsa karşında bir adım daha

Bir nefes daha solumaya çalışıyorsa her şeye rağmen 

Bu senin,adamın yüreğine düşürdüğün beyazlıktandır.

Kurtul artık yüreğinin pas tutan yanından 

Sevmeyi öğren en az sevildiğin kadar 

Hatta daha da fazlası.

Elleri, yüzü kir pas içinde 

Ama yüreğinde sevdasıyla bir adam 

Tepeden tırnağa aşka kesip 

En güzel dizeleriyle dayanırsa kapına 

Yüreğinden akan beyazlığı uzat 

Bil ki sendendir bütün şairliği bu adamın...

2003', 'Elleri, yüzü kir pas içinde  Ama yüreği beyaza bulanmış bir adam  Sevgisini kuşanıp  Dünyanın en güzel dizeleriyle dayanırsa kapına  Gülümse...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yuregi-beyaza-bulanmis-adam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin çok derin bakışın yeter', 'gozlerin-cok-derin-bakisin-yeter-cengiz-ozkan-g0umw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Alev alev yaktın köz oldu bu can, 

Pervaneyim sana sevdaya yanan, 

Sen zalim bir kasap ben aşka kurban, 

Boğazıma hançer salışın yeter. 

Düşmüşsem diline, onurdur bana, 

Emir kim ben kimim, ricamdır sana, 

Kızdıysan at tokat, o güldür bana, 

Uzaktan uzağa gülüşün yeter..

Barışalım artık gel inat etme

Bu aşkı sevdayı bırakıp gitme 

Uçurumdayım ben sakın ha itme

Gözlerin çok derin bakışın yeter

Mecnun edip çöle saldın bedeni, 

Efsunlu gözlerle avladın beni, 

Ser koymuşum yola alırım seni, 

Koynumda bir gece kalışın yeter.', 'Alev alev yaktın köz oldu bu can,  Pervaneyim sana sevdaya yanan,  Sen zalim bir kasap ben aşka kurban,  Boğazıma hançer salışın yeter.  Düş...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Özkan']::text[], 8.5, '{"poet":"Cengiz Özkan","poet_slug":"cengiz-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gozlerin-cok-derin-bakisin-yeter-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Figanı bülbül', 'figani-bulbul-sinan-oktay-fl530', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Parçalanır kayalarda fiğanı, 

                           garip bülbülün.

Parçalar zaman elbet kayaları,

                          fiğanında bülbülün.

Yaşamaz çölde kaya arar bülbülüm.

Yaşasın ister güle olan faryadı fiğanı bülbülüm.', 'Parçalanır kayalarda fiğanı,                             garip bülbülün. Parçalar zaman elbet kayaları,                           fiğanında ...', ARRAY['Türk Edebiyatı','Şiir','Sinan Oktay']::text[], 8.5, '{"poet":"Sinan Oktay","poet_slug":"sinan-oktay","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/figani-bulbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana bu da yeter', 'bana-bu-da-yeter-ahmet-erdem-kaya-087lm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Pimi çekildi özlemlerimin.........

Kaybolan sevdaların kentini yakabilirim her an

      Soluk yüzlerin geldi ilkin aklıma

       zemheri gecelerinde mütevekkil çocukların yüzü gibi

       Anladım sen kimsesiz, sokak çocuğu suretinde de yine sendin.

 Ve sen beni o zaman da anlamadın...........

      Ayrılığın kolkanat olduğu sokak 

      ve o sokakların biçare kandilleri gibi muttasıl

      gözlerde sönen alevler,  seni aydınlatmadılar............

 Gönlümde.......

Bunca darbe ve bunca çıkmaz,

anlamıyor yüreğim

              

         Bana bir iyilik yap çık kahpe suretlerin ardından

         bürün eski haline öğle gel, 

         Kendin söyle,

         söylenmesi gerektiği gibi,  söylenmesi gerekeni

       VE BOŞLUKLARDA SÜKUTUN ÇIĞLIK GİBİ DÜŞSÜN  İSTER

   

       iSTERSEN  EYVALLAH DE GİT BANA BU DA YETER', 'Pimi çekildi özlemlerimin......... Kaybolan sevdaların kentini yakabilirim her an       Soluk yüzlerin geldi ilkin aklıma        zemheri gec...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Erdem Kaya']::text[], 8.5, '{"poet":"Ahmet Erdem Kaya","poet_slug":"ahmet-erdem-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bana-bu-da-yeter-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutturma Birlikte Gülmeyi', 'unutturma-birlikte-gulmeyi-munevver-duver-3q2kv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Konuşma, söyleme, anlatma bana

Yalnızca kollarını dola boynuma

Kolların sımsıkı boynumdayken

Gözlerim her şeyi anlatır sana

Sevgilim senle hep böyle kalalım

Dertleri unutup, zevke dalalım

Aramıza başkaları girmeden

Aşkımızın sefasını yaşayalım

Ben seninim, sende benimsin

Yaşama sevincim, kanatsız meleğimsin

İkinci ve son aşkım, biricik sevdiğimsin

Paylaşamam bir tanem, sen yalnızca benimsin

İstersen kalbimi can evimi sökerim

Değersiz bir şey gibi yoluna dökerim

Paha biçilmez altınlar, yakışıklı erkeklerle

Sen rüyama girsen, seni tercih ederim

Heeey beni dinle sevgili

Üzerine giy, mavi çizgili gömleği

Hayatımızı yaşamadan, düşünme ölmeyi

Unutturma bana birlikte gülmeyi

06/04/2000..saat.03.35

Güzelyalı... Adana

www.munevverduver.com', 'Konuşma, söyleme, anlatma bana Yalnızca kollarını dola boynuma Kolların sımsıkı boynumdayken Gözlerim her şeyi anlatır sana Sevgilim senle h...', ARRAY['Türk Edebiyatı','Şiir','Münevver Düver']::text[], 8.5, '{"poet":"Münevver Düver","poet_slug":"munevver-duver","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/unutturma-birlikte-gulmeyi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haşmet Ağa', 'hasmet-aga-mehmet-sabit-ozmus-di8ff', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerini hep para hırsı bürümüş

                     Hep para deyip ayak sürümüş

                      Duyarız da bir gün hakka yürümüş

	    Halin nice olur senin Haşmet ağa

                                        

                       Sevincinden elin dilin oynardı 

                       Görenler seni adam sanardı

                        Riyakarın suyu fokur fokur kaynardı

	        Halin nice olur senin Haşmet ağa

                                           

                                          Duyun duymayan kalmasın ahali

                                          Bilin nedenmiş adamın bu hali

                                          Kızı vermekmiş en büyük hayali

                                           Halin nice olur senin Haşmet ağa  

	Kardeş  arasına hiç girilir mi

                Belleğadan  hiç su içilir mi 

	Riyadan haramdan kefen biçilirmi

	Halin nice olur senin Haşmet ağa

	Kisranın sarayı mülkünden sönük kalır

 	Senin servetin karunu satın alır

	Polyana ağlar iken mutlu olur

	Halin nice olur senin Haşmet ağa

	Dilinden dökülenler haysiyetten uzak

                Kölesin nefsine hürriyetten uzak 

                Hayırlı, uğurlu zürriyetten uzak

	Halin nice olur senin Haşmet ağa', 'Gözlerini hep para hırsı bürümüş                      Hep para deyip ayak sürümüş                       Duyarız da bir gün hakka yürümüş 	  ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sabit Özmüş']::text[], 8.5, '{"poet":"Mehmet Sabit Özmüş","poet_slug":"mehmet-sabit-ozmus","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/hasmet-aga-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baba', 'baba-mehmet-sabit-ozmus-i62p2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Âlemlerde hep acı olmaz bilirdik

                                    Gözyaşlarım şarıl şarıl akıyor baba

	Sensiz ikinci ramazanı da geçirdik

	Bayramlar hüzün kokuyor baba.

	Yaz ayı sıcaklar Dörtyol’da, beter

	Antakya serindir burnunda tüter

                Yar kucağında hayat nihayet biter

	Bülbül diller kuran okuyor baba.

	Arife geldim başında dua etmeye

	Birkaç çalı dalı, murcu dikmeye 

	Üç beş damla gözüm yaşı dökmeye

	Bu ayrılık yüreğim yakıyor baba.

	Senin yokluğuna alışamadık

	Azrail’in işine karışamadık 

	Şu yalan dünyaya sığışamadık 

	Çınarlar yaprağın döküyor baba.

	Güzel günler hep geride kalır

	Yaşananlar tarihin dilinde kalır

	Azrail bir gün beni de alır

	Rahmet sel olmuş mezarını yıkıyor baba.

	Daralır yüreğim can ateşte pişer 

	Sensizlik içimize kor gibi düşer

                 Gün gelir herkes ölüm şerbeti içer

                 Şafak attı artık gün söküyor baba.', 'Âlemlerde hep acı olmaz bilirdik                                     Gözyaşlarım şarıl şarıl akıyor baba 	Sensiz ikinci ramazanı da geçirdik...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sabit Özmüş']::text[], 8.5, '{"poet":"Mehmet Sabit Özmüş","poet_slug":"mehmet-sabit-ozmus","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/baba-54-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatın Sonu', 'hayatin-sonu-gul-erkan-0n5rf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dostlarım gelmiş teker teker ziyaretime

Kimi sevdiğinden gelmiş kimininki bahane

Yatıp kalmışsam kalkamamışsam bu yerde

Yaşamanın ne anlamı var söyle

Gün geçtikçe iyiye değil kötüye gidiyorsam

Doktorlar iyileşmez diyor da ondan bundan meded umuyorsam

Çocuklarımı torunlarımı öpüp koklayamıyorsam

Yaşamamın ne anlamı var söyle

Etrafımdakiler kuş gibi çırpınıpta derdime çare bulamıyorlarsa

Hayatım ellerimden kayıp gidiyorsa

Gençliğimde zaman yetmezken şimdi saatler geçmiyorsa

Yaşamanın ne anlamı var söyle', 'Dostlarım gelmiş teker teker ziyaretime Kimi sevdiğinden gelmiş kimininki bahane Yatıp kalmışsam kalkamamışsam bu yerde Yaşamanın ne anlamı ...', ARRAY['Türk Edebiyatı','Şiir','Gül Erkan']::text[], 8.5, '{"poet":"Gül Erkan","poet_slug":"gul-erkan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hayatin-sonu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-sinan-oktay-af34f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir rüzgar nehri süpürür,

                       gider sevdalarımı

Bir başıma bırakır beni yalnızlıgıma...

Tüter dumanı sevdamın yalnızlıgımda.', 'Bir rüzgar nehri süpürür,                        gider sevdalarımı Bir başıma bırakır beni yalnızlıgıma... Tüter dumanı sevdamın yalnızlıgım...', ARRAY['Türk Edebiyatı','Şiir','Sinan Oktay']::text[], 8.5, '{"poet":"Sinan Oktay","poet_slug":"sinan-oktay","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yalnizlik-308-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyandırın Silkinsin', 'uyandirin-silkinsin-ercan-cengiz-9ttfe', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uyandırın, beceriniz de varsa

Ellerinden tutup kaldırın ayağa

Karanlığa yatanı

En güzeli de olsa uykusunu,

Koysun yılanın koynuna.

Uyandırın derdine kadeh kaldıranı

Ellerinden tutun

Kadehini kaldırırken de birileri

Hizmet etmektedir ona.

Uyandırın,

Elinden çalınan ekmeğin kavgasına

Beynine girmeden korkunun duvarı

Uyandırın silkinsin.

...

Uyandırın yoğurmak için emeğini

Kan deryasında kaybolmadan izi,

Yük kaçkınları türemiş gezinirler

Gözlerini açıp parmaklarınızla gösterin

Ağırlaşır yükü bu sevdanın altında.

Ellerine bakarsın ateşlenmiş kalbinle

Yılların öfkesini çıkarırcasına yuvasından

Sevdası büyür ellerinin yükü de büyürdü

O nasırlı ellerin...

Geleceğini küçük adımlarında mı görürsün

Atamadan üstünden yük kaçkınlarının yükünü

Nesiller boyu gitmek istersin ya kök köke

Dedene kadar ancak, gözlerinin ışığı...

Bırakırsan olduğu yerde yük kaçkınlarını

İsyanındır, çığlığındır der kulak veririm

Sevdanın şarkısında dile gelen sesine...

(Ezgilerde Kaldı Yüreğim 1.Kitap)', 'Uyandırın, beceriniz de varsa Ellerinden tutup kaldırın ayağa Karanlığa yatanı En güzeli de olsa uykusunu, Koysun yılanın koynuna. Uyandırın...', ARRAY['Türk Edebiyatı','Şiir','Ercan Cengiz']::text[], 8.5, '{"poet":"Ercan Cengiz","poet_slug":"ercan-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/uyandirin-silkinsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ümit', 'umit-mehmet-sabit-ozmus-qlbch', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ceza vererek kanımı içecek

                       Çürüyen bedenimi dişleyen böcek

                        Belki bir gün mezarımda bir çiçek

                        Bana dua ile açmaya başlar.

                        Alevler içinde kül olan bedenim

                        Olmuyor,olmuyor dua edenim

                        Cennete girmem gerek yokki nedenim

	         Şeytan bile benden kaçmaya başlar.

                        Dilim tutulur kalır ezberim

                        Yangın yerinden gelir haberim

                         İşte o an yüce peygamberim

                         Maveradan gülücükler saçmaya başlar.', 'Ceza vererek kanımı içecek                        Çürüyen bedenimi dişleyen böcek                         Belki bir gün mezarımda bir çiçek ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sabit Özmüş']::text[], 8.5, '{"poet":"Mehmet Sabit Özmüş","poet_slug":"mehmet-sabit-ozmus","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/umit-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haberin var mı?', 'haberin-var-mi-ercan-akbay-y8evv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İsteyen gülsün, isteyen kınasın

   Seni seviyorum,haberin var mı

   Aşığım uğruna, düştüm dillere

   Seni seviyorum,haberin var mı

   Yüreğim bir bulut,gözlerim yağmur

   Seni arıyorum,haberin var mı

   En büyük fırtına,seninle diner

   Seni seviyorum,ötesi var mı....

                                   Hicaz şarkı

                                   Güfte...Ercan Akbay

                                   Beste..Tahir Sıral

                                   Solistler..Vedat Çetinkaya-Suat Yıldırım-İnci Yaman

                                                   Cavit Tanürek--Cem Kafkas

                                   TRT  REPERTUARINDADIR.        

                                                 

                                   TRT Repertuarındadır.', 'İsteyen gülsün, isteyen kınasın    Seni seviyorum,haberin var mı    Aşığım uğruna, düştüm dillere    Seni seviyorum,haberin var mı    Yüreği...', ARRAY['Türk Edebiyatı','Şiir','Ercan Akbay']::text[], 8.5, '{"poet":"Ercan Akbay","poet_slug":"ercan-akbay","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/haberin-var-mi-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tereciye', 'tereciye-mehmet-sabit-ozmus-7iq0t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Vatanımın meftunuyum

                        Yalan değil ölesiye

                        Asırlardır suskunuyum

                        Dilim gitti veresiye.

                        Milletim hayaller kurar

                        Cehalet tahta oturur

                        Alimse körebe oynar 

                        Tere satar tereciye.', 'Vatanımın meftunuyum                         Yalan değil ölesiye                         Asırlardır suskunuyum                         Dilim...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sabit Özmüş']::text[], 8.5, '{"poet":"Mehmet Sabit Özmüş","poet_slug":"mehmet-sabit-ozmus","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/tereciye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sükut-u İnat II', 'sukut-u-i-nat-ii-aysun-elagoz-uynhc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çocukluğumu, ortalarında bir yerde kaybettiğim 

Garip anıların gölgesinde ezilmekte tebessümlerim...

Vurdumduymaz kelimelerin, pervasızca yaraladığı yüreğim,

Yarım kalmış, baştan bitmiş, hiç başlayamamış

Güzel duyguların, matemiyle aheste atmakta artık..

Dönülmez yolların, acı dolu adımlarını sayarak

Tutunmadan kimseye, ayakta kalmaya  çalışarak, 

Sitemkar bakışlarımı öfkemle saklayarak

İçimde büyüttüğüm kinleri, sabırla yatıştırarak

Ve inatla susarak! ! ! başım dik yürümekteyim...', 'Çocukluğumu, ortalarında bir yerde kaybettiğim  Garip anıların gölgesinde ezilmekte tebessümlerim... Vurdumduymaz kelimelerin, pervasızca ya...', ARRAY['Türk Edebiyatı','Şiir','Aysun Elagöz']::text[], 8.5, '{"poet":"Aysun Elagöz","poet_slug":"aysun-elagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sukut-u-inat-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi melek', 'mavi-melek-seref-ozturk-usta-iduex', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Git sevdiceğim 

............Mavi meleğim 

Yüreğimden kaçamazsın ya 

Benim gözümde 

............fındık kadardır dünya 

Hayal ülkemin sınırlarını

........................ aşamazsın ya.', 'Git sevdiceğim  ............Mavi meleğim  Yüreğimden kaçamazsın ya  Benim gözümde  ............fındık kadardır dünya  Hayal ülkemin sınırlar...', ARRAY['Türk Edebiyatı','Şiir','Şeref Öztürk Usta']::text[], 8.5, '{"poet":"Şeref Öztürk Usta","poet_slug":"seref-ozturk-usta","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/mavi-melek-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostumsun', 'dostumsun-aysun-elagoz-vzz2f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '(Sevgili Pungare'' ye)

Dar zamanların, zor zamanların sığınağı...

Sırdaşım, dostum, canyoldaşım...

Anlatmadan anlayan, ağladığımda tebessümüm olan...

İki eli kanda olsa bana ulaşan...

Mutluluğumu da, mutsuzluğumu da sabırla taşıyan...

Canımın yarısı, yürek kardeşim.', '(Sevgili Pungare'' ye) Dar zamanların, zor zamanların sığınağı... Sırdaşım, dostum, canyoldaşım... Anlatmadan anlayan, ağladığımda tebessümüm...', ARRAY['Türk Edebiyatı','Şiir','Aysun Elagöz']::text[], 8.5, '{"poet":"Aysun Elagöz","poet_slug":"aysun-elagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/dostumsun-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küskünüm', 'kuskunum-naciye-bildim-vpz45', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'hayatta ilk defa bugün ağladım,

Ak düşen saçların farkına  vardım.

Aynalar yalancı,ben inanmadım,

Dünyaya küskünüm,kadere dargın..

Kaderin sillesi,vurdukça vurur

Sararan resimler,anlatır durur.

Geçip giden yıllar,şimdi kahrolur,

Dünyaya küskünüm,kadere dargın...

Anılarla sessiz,yanlız kayboldum,

Ağlayan resmine nelerde sordum.

O an gözlerinde bin sitem buldum,

Dünyaya küskünüm,kadere dargın...

Ak düşmüş saçlarım,nasılda yoldum,

Mazide perişan,derbeder oldum.

Yokluğun inletti,hasretle doldum,

Dünyaya küskünüm,kadere dargın...', 'hayatta ilk defa bugün ağladım, Ak düşen saçların farkına  vardım. Aynalar yalancı,ben inanmadım, Dünyaya küskünüm,kadere dargın.. Kaderin s...', ARRAY['Türk Edebiyatı','Şiir','Naciye Bildim']::text[], 8.5, '{"poet":"Naciye Bildim","poet_slug":"naciye-bildim","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kuskunum-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm', 'olum-dilek-hokkaomeroglu-ksse8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ÖLÜM

Ölümü düşünmek

Ölmek kadar

Can çekişiyor

Buz dağı eteklerinde

Ellerimi tutarken

Buz kesmiş bedeni

Gözlerinde sonsuz 

Bir acı

Ölümüne direniyor..

Dilek hokkaömeroğlu', 'ÖLÜM Ölümü düşünmek Ölmek kadar Can çekişiyor Buz dağı eteklerinde Ellerimi tutarken Buz kesmiş bedeni Gözlerinde sonsuz  Bir acı Ölümüne di...', ARRAY['Türk Edebiyatı','Şiir','Dilek Hokkaömeroğlu']::text[], 8.5, '{"poet":"Dilek Hokkaömeroğlu","poet_slug":"dilek-hokkaomeroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/olum-239-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatımı Anlattım', 'hayatimi-anlattim-naciye-bildim-hfagj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Karanlık odamda,Yalnız başıma

Resmini öpüpte,bastım bağrıma.

Usulca konuştum ben kulağına,

Hayatımı anlattım,dün gece sana....

Uzanan elimi,kimse tutmadı

Kanayan yaramı,kimse sarmadı.

Dostunum diyenler şimdi kalmadı,

Hayatımı anlattım,dün gece sana...

Ağlatma demiştim tut ellerimden,

Ayırma ne olur,beni kendinden.

Yalvarıp ağladım sana yürekten,

Hayatımı anlattım,dün gece sana...', 'Karanlık odamda,Yalnız başıma Resmini öpüpte,bastım bağrıma. Usulca konuştum ben kulağına, Hayatımı anlattım,dün gece sana.... Uzanan elimi,...', ARRAY['Türk Edebiyatı','Şiir','Naciye Bildim']::text[], 8.5, '{"poet":"Naciye Bildim","poet_slug":"naciye-bildim","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hayatimi-anlattim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* Kaldı Bende', 'kaldi-bende-salih-ozalasan-cplet', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seninle yaşamıştım aşkın en güzelini 

Şimdi sevda bahçemin çiçekleri soldu 

Bir sevdan kaldı bir de sen kaldın bende 

Ettiğin yeminler de yalanmış 

Senden ayrılmam dediğin sözlerde 

Hepsi yok oldu gitti 

Bir anılar bir sen kaldın bende 

İstesen de artık dönemem geri 

Yok ettin bütün sevgimi 

Viraneye döndürdün bu bedeni 

Yaşanan yaşandı bitti 

Bir anılar bir sen kaldın bende

Filiz Tekin', 'Seninle yaşamıştım aşkın en güzelini  Şimdi sevda bahçemin çiçekleri soldu  Bir sevdan kaldı bir de sen kaldın bende  Ettiğin yeminler de ya...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kaldi-bende-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkon', 'i-kon-sinan-oktay-fnpbu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni gözümde büyüttügüm zaman 

                                         kork benden.

Bu o olmalı dedigim zaman,

                                         kork benden.

Uzak yada yakın ikonların kırılacagı gün,

                                         kork benden.

Senden isteyecegim ve veremeyecegin gün,

                                                 kork benden.

Tükenecegim ve yücelecegim gündede,

                                             kork benden.

           En iyisi ikon olma sen..', 'Seni gözümde büyüttügüm zaman                                           kork benden. Bu o olmalı dedigim zaman,                             ...', ARRAY['Türk Edebiyatı','Şiir','Sinan Oktay']::text[], 8.5, '{"poet":"Sinan Oktay","poet_slug":"sinan-oktay","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ikon-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatım Bir Garip', 'hayatim-bir-garip-naciye-bildim-4kyfc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'geceler boyunca düşündüm durdum,

Hangi yola girsem,yolum kapanmış.

Sabaha merhaba diyecek oldum,

Gündüzüm gecemle,arkadaş olmuş.

Ne hale düştüm ben neden allah''ım

Yardım et ne olur,ben çok yalnızım.

Hayatım bir garip,gözlerim dolmuş,

Gündüzüm gecemle,arkadaş olmuş.

Kararmış yıllar esir almış beni,

zindana çevirmiş,yorgun kalbimi.

Ölüm kokusu sarmış,bedenimi,

Gündüzüm gecemle,arkadaş olmuş.', 'geceler boyunca düşündüm durdum, Hangi yola girsem,yolum kapanmış. Sabaha merhaba diyecek oldum, Gündüzüm gecemle,arkadaş olmuş. Ne hale düş...', ARRAY['Türk Edebiyatı','Şiir','Naciye Bildim']::text[], 8.5, '{"poet":"Naciye Bildim","poet_slug":"naciye-bildim","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hayatim-bir-garip-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Safiş''e', 'safis-e-seref-ozturk-usta-6dlrh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sohbetlerin 

.....benim için kıymetli

Sabah çayları gibi 

.....sıcak lezzetli.

Mektupların 

.....İkramiyeli aile mevduatı

Kelimelerin

.....dostluk dolu muhabbetli.

Usta''nız inanın 

.....Uşak''a zimmetli.', 'Sohbetlerin  .....benim için kıymetli Sabah çayları gibi  .....sıcak lezzetli. Mektupların  .....İkramiyeli aile mevduatı Kelimelerin .....d...', ARRAY['Türk Edebiyatı','Şiir','Şeref Öztürk Usta']::text[], 8.5, '{"poet":"Şeref Öztürk Usta","poet_slug":"seref-ozturk-usta","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/safis-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sezar', 'sezar-fevzi-gunenc-vbhgn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Öldürülmek değildi Sezar’ı yaralayan

Oğul dediği Brütüs’ün vurmasıydı onu

Hem de arkadan.

Brütüs de haklıydı kendince

tarihe geçmek istiyordu.

Biliyordu bunun için de

Ya kral olmak ya kral vurmak gerektiğini

yoksa kim sallardı Sezar’ın üvey veledini…

İşte tarihe geçtin. 

Mutlu musun? ..

Bir kişi bile yok Brütüs’ü adam sayan

yüzünü buruşturuyor yüzlerce yıl sonra bile

seni her hatırlayan.', 'Öldürülmek değildi Sezar’ı yaralayan Oğul dediği Brütüs’ün vurmasıydı onu Hem de arkadan. Brütüs de haklıydı kendince tarihe geçmek istiyord...', ARRAY['Türk Edebiyatı','Şiir','Fevzi Günenç']::text[], 8.5, '{"poet":"Fevzi Günenç","poet_slug":"fevzi-gunenc","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sezar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şey Olmasın da Sana', 'bir-sey-olmasin-da-sana-fevzi-gunenc-6a39u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'En son on dokuz ekim 2005''te yazmışım

bir balanın anasına seslenişi gibi

''Uzat ellerini

tut ellerimi,'' diye, ''Ana! ..''

Daha önceleri de yazdım elbet

kim bilir kaç kez

ama sen sustun hep...

kaygılandınm senin için

kan oturdu yüreğime.

Hani kasırgalar t sunamiler filan 

vuruyor ya dünyayı

yoksa sana

yoksa sizlere çocuklarına

da mı vurdu kırılası dalgalar diye

çok içlendim

çok hüzünlendim

çok ağladım sizin için.

Umarsızdım

kaçıncı kattakı evinin 

penceresinden caddeye bakarken

araba altında kalan yavrusuna

yardıma koşamayan ananın umarsızlığı içindeydim.

Sen ise hiç bir şey olmamış gibi

susuyormuşsun meğer.

Sus, zarar yok

hiç bir şey olmasın da sana...', 'En son on dokuz ekim 2005''te yazmışım bir balanın anasına seslenişi gibi ''Uzat ellerini tut ellerimi,'' diye, ''Ana! ..'' Daha önceleri de yazd...', ARRAY['Türk Edebiyatı','Şiir','Fevzi Günenç']::text[], 8.5, '{"poet":"Fevzi Günenç","poet_slug":"fevzi-gunenc","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bir-sey-olmasin-da-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalanlar incitmiyor', 'yalanlar-incitmiyor-sinan-oktay-ozvlf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gerçegi bile hayallerimden 

                                 güzel degil,

  Bu ev bu akşam

                        sinema perdesi gibi,

Düşler dokunulmamış.

Acımasızlık yok,

 yalanlar bile incitmiyor,kimi zaman.', 'Gerçegi bile hayallerimden                                   güzel degil,   Bu ev bu akşam                         sinema perdesi gibi, Düşl...', ARRAY['Türk Edebiyatı','Şiir','Sinan Oktay']::text[], 8.5, '{"poet":"Sinan Oktay","poet_slug":"sinan-oktay","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yalanlar-incitmiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül/Diken', 'gul-diken-fevzi-gunenc-x4miz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir gülü renklerinden

kokusundan 

dikenlerinden bildik bir de.

Rengini vermedi bize

kokusunu…

Verdiği dikeniydi

acıttı yüreklerimizi.

Bir gülü acısından unuttuk

unuttuk mu?', 'Bir gülü renklerinden kokusundan  dikenlerinden bildik bir de. Rengini vermedi bize kokusunu… Verdiği dikeniydi acıttı yüreklerimizi. Bir gü...', ARRAY['Türk Edebiyatı','Şiir','Fevzi Günenç']::text[], 8.5, '{"poet":"Fevzi Günenç","poet_slug":"fevzi-gunenc","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gul-diken-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fikret Otyam''a', 'fikret-otyam-a-seref-ozturk-usta-kof3a', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yedi küpeli geline

Tükenmeyen kalemine.

Sağlık  yürek ve eline.

Yetmiş milyonluk ülkemde

İşçi memur ve köylüne 

Örnek oldun öğrencine.

Tayfun mobil 

..........Coşkun idôl

Muhabirlik bilincinle

Yetiştirdin hem de bol,bol.

Yaşa Fikret baba sağ ol.', 'Yedi küpeli geline Tükenmeyen kalemine. Sağlık  yürek ve eline. Yetmiş milyonluk ülkemde İşçi memur ve köylüne  Örnek oldun öğrencine. Tayfu...', ARRAY['Türk Edebiyatı','Şiir','Şeref Öztürk Usta']::text[], 8.5, '{"poet":"Şeref Öztürk Usta","poet_slug":"seref-ozturk-usta","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/fikret-otyam-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş Görme Günü...', 'dus-gorme-gunu-fevzi-gunenc-ug4cr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gir düşlerime korkmadan

saklayacağım seni koynumda.

bugün düş görme günüm benim.

Bütün resimlerini yolla/olur 

olmaz saatlerde uçan kuşlarlı

seveceğim/resimlerini.

bugün kuş görme günüm benim.

Bütün savrukluğunu takın da gel

Sırasıdır/kabulümsün

Bugün boşu dolu

doluyu boş görme günüm benim

Bütün eski kötü aşklarını yolla, küşümlenme

göreceksin ne sevecenlikler yollayacağım yerine.

Bugün her şeyi hoş görme günüm benim.', 'Gir düşlerime korkmadan saklayacağım seni koynumda. bugün düş görme günüm benim. Bütün resimlerini yolla/olur  olmaz saatlerde uçan kuşlarlı...', ARRAY['Türk Edebiyatı','Şiir','Fevzi Günenç']::text[], 8.5, '{"poet":"Fevzi Günenç","poet_slug":"fevzi-gunenc","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/dus-gorme-gunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çadır', 'cadir-elazigli-mustafa-kaya-ge4dn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sen miydin..? gelen.

kulaklarım yanılmaz,

incir yaprakları gibidir

duyarım her sesi.

en küçük bir çıtırdı,

sen misin..? 

merdivenleri kaç basamaklı 

evinin.

yorgunsun çok

sobayı yaktım bak.

yer minderinin yerini değiştirdim

bir hasır iskemle aldım

oturup bazı 

kahvemi bunda içmeliyim.

evinin her eşyasına 

çehrelerine baktım.

sensizlik,

tahtalardaki lekeler gibi.

odalarda gezindim.

her nereye dokunsam,

taşta kırılan camların sesi.

seni hasta eden

soğukları kapattım

çadır yapıp gövdemi….

Mustafa kaya

13.12.2005 / bağlarbaşı

www.mustafakaya.net', 'sen miydin..? gelen. kulaklarım yanılmaz, incir yaprakları gibidir duyarım her sesi. en küçük bir çıtırdı, sen misin..?  merdivenleri kaç ba...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/cadir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kibrit parlayışı', 'kibrit-parlayisi-elazigli-mustafa-kaya-vmzkr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'rüyasını yaşadığım sevgilim

bir vehmin dişleri arasında

yüzü,

duvar kadar beyaz çiçeğim.

simsiyah sokaklar mı yine kaderim

büsbütün kimsesiz kaldım

hislerimi saklayamadım

bir kibritin parlayışı gibiyim

şimdi,

soluk bir ışık yeter bana

yeter bir aşk mahkumuna..

rüyasını yaşadığım sevgilim,

yaşadığım hicran

simsiyah bir çukur

hafif hafif is çıkaran

bir lamba,

oysa sen,

bal peteğindeki şiir

soluduğum hava

yaşadığım şehir

yalnızlığımın müziği

kalbimin nağmesi 

ruhumun utangaç  resmisin…

Mustafa kaya

13.12.2005 / Eminönü

www.mustafakaya.net', 'rüyasını yaşadığım sevgilim bir vehmin dişleri arasında yüzü, duvar kadar beyaz çiçeğim. simsiyah sokaklar mı yine kaderim büsbütün kimsesiz...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/kibrit-parlayisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazılmamış hikaye', 'yazilmamis-hikaye-sinan-oktay-biu0j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Unutulmuş ve var olmamış 

                                  bir hikaye.

Bir kaç dil söyler ama başlangıç 

                            noktasında mantık yok.

Bende işin ucunu kaçırdım; 

   Bir penceredir tutturmuşum

                                 kaç zamandan beri.', 'Unutulmuş ve var olmamış                                    bir hikaye. Bir kaç dil söyler ama başlangıç                              noktas...', ARRAY['Türk Edebiyatı','Şiir','Sinan Oktay']::text[], 8.5, '{"poet":"Sinan Oktay","poet_slug":"sinan-oktay","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yazilmamis-hikaye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dil-emek-çaresiz..', 'dil-emek-caresiz-i-brahim-asli2-91t4m', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her şey için geç demek di aslında bu

Buğulu diyarların son sevdalısı

Son defa bir gül kanatlandırdı 

Her şey için yok demek di  aslında bu

Güzel sözlerin aşk-ı ironik ressamı

Adını çizdirdi yağmurların ıslattığı 

Dönme dolap düşlerin kanattığı 

Kaldırım gönüllüsü ressamına

Yenileri taşıdı kucağında 

Hamal özentisinin telaşında 

Yanından  arkasından  kalpler vurunca kapısına

Telaşını dindirirdi müddeti saklama telaşında

Rekatlık ömrün hasırlı yollarında 

Hep gül batırırdı avuçlarına 

Kanayan  acıtan  ağrılar başlayınca yurdunda

İlmiklerini sayardı ördüğü ağların yarısında

Oysa  son defa yağan yağmurun peşi sıra

Adını  sayıklayınca  mabedi

Gidince sayıklamaların ardına her şey  ilk gibi geldi

Oysa  yine saklandı sevda gelenlerinin ardı sıra', 'Her şey için geç demek di aslında bu Buğulu diyarların son sevdalısı Son defa bir gül kanatlandırdı  Her şey için yok demek di  aslında bu G...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Aslı2']::text[], 8.5, '{"poet":"İbrahim Aslı2","poet_slug":"i-brahim-asli2","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dil-emek-caresiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkımın garibanı.', 'askimin-garibani-gulnare-leman-wzoz2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni kalbimin en güzel 

Köşesinde saklamışım..

Korkuyorum aşkım..

Sen damarımda akan kanım,

Gören gözüm,vuran kalbim,

Her şeyimsin...

Seni dağa benzetirim..

Gölgesine değil ama,

Bak  sinene sığınmışım..

Bu dağ benim kendi keşifim,

Adı “AŞKIM”..

Bazan kalem alıp ele..

Ben resmini çiziyorum..

Sonra yırtıp atıyorum.

Hiç olmuyor..

Sen özelsin bana aşkım..

Bilmiyorum neredesin,

Yerdemisin,ya göktesin..

Yürek şunu anlıyorki...

Sen güzelsin benim aşkım..

Aşkım seni arıyorum..

Ben denize gidiyorum..

Belki,belki haber verir

Mavi gözlü Hazar’ım..

Nerde kalmış o,yarım..

Benim güzellik tacım? ..

Kimse seni anlayamaz benim gibi,

Seni kendim yaratmışım..

Sen şarkımsın dudağımda,

Içimdeki  büyük ah’ım,

Gözlerimden  damla,damla

Akan aşkım..

Aynalara bakıyorum...

Sen ordasın,gözbebeğim

Sigaramın dumanında,

Sen çayımın yudumunda

Şekerimsin,her yerdesin.

Söyle aşkım neredesinnnn...

Ben unutmak istiyorum..

Içmek,içmek istiyorum..

Sarhoş olum,unutayım..

Şimdi bildim.....

Kadehimsin ellerimde

Acımasız kaderimsin..

Seni yazmak istiyorum...

Aşkım gibi..

Seni çalmak istiyorum.... 

Sazım gibi..

Seni yozmak istiyorum..

Yarım gibi...

Seni bozmak istiyorum...

Aramasın yüregimin paresini..

Hayal  bitti..

Bu son durak..

Ya gel, gerçekmisin..

Ol, kalbimin sultanı..

Ya da öldür,ecelmisin..

Sen  aşkımın garibanı? ..

  

(yozmak - yorum)', 'Seni kalbimin en güzel  Köşesinde saklamışım.. Korkuyorum aşkım.. Sen damarımda akan kanım, Gören gözüm,vuran kalbim, Her şeyimsin... Seni d...', ARRAY['Türk Edebiyatı','Şiir','Gulnare Leman']::text[], 8.5, '{"poet":"Gulnare Leman","poet_slug":"gulnare-leman","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/askimin-garibani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Gözlerimde', 'yagmur-gozlerimde-sacide-yaylaz-ihv6q', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nedendir bilmem bu gün 

Kalemim yazmaz, 

Dilim söylemez bir söz, 

Garip bir burukluk yüreğim de 

Nedendir bilinmez, 

Güllerim solmuş dalında, 

Bükmüş boynunu, 

Kar etmiyor şakıması bülbülün. 

Mevsim ha ilkbahar olmuş, 

Ha sonbahar, ne farkeder 

Yağmur gözlerimde 

Yüreğimde kışı yaşıyorsam eğer.', 'Nedendir bilmem bu gün  Kalemim yazmaz,  Dilim söylemez bir söz,  Garip bir burukluk yüreğim de  Nedendir bilinmez,  Güllerim solmuş dalında...', ARRAY['Türk Edebiyatı','Şiir','Sacide Yaylaz']::text[], 8.5, '{"poet":"Sacide Yaylaz","poet_slug":"sacide-yaylaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yagmur-gozlerimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köhne dünya', 'kohne-dunya-elazigli-mustafa-kaya-xe69r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ıhlamur ağaçlarının

kokuladığı bir sokaktayım

bir bahar mevsimi

yüzüne vurmuş kokusu

köhne dünyanın..

zapt olunmaz  çocuksuluğum

dinmek bilmez 

dereye dökülen sular gibi

ortaya çıkarır hislerimi..

Mustafa kaya

13.12.2005 / ıhlamur kasrı

www.mustafakaya.net', 'ıhlamur ağaçlarının kokuladığı bir sokaktayım bir bahar mevsimi yüzüne vurmuş kokusu köhne dünyanın.. zapt olunmaz  çocuksuluğum dinmek bilm...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kohne-dunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çember', 'cember-sinan-oktay-4fwo8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dert taşıyan şarkıların,

                         içinde olmak.

Dert olmak,zaman,mesafe,özlem,düşünce olmak.

   Uzayan zincir içinde çizgi olmak.

Aynı renk olmak.

   Büyük zincir olmak,

                   beklemek ölüp yaşamak...', 'Dert taşıyan şarkıların,                          içinde olmak. Dert olmak,zaman,mesafe,özlem,düşünce olmak.    Uzayan zincir içinde çizgi o...', ARRAY['Türk Edebiyatı','Şiir','Sinan Oktay']::text[], 8.5, '{"poet":"Sinan Oktay","poet_slug":"sinan-oktay","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/cember-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sükunetten Uzaktı Ortadoğu', 'sukunetten-uzakti-ortadogu-ercan-cengiz-dz117', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İlk cemresiydi daha toprağa düşen

Karanlığa inat bir cemre

İlk silkinişleri şimşek oldu beyinlere.

Çocuklar kurbağa toplardı

Arı kovanları etrafında dolaşamazdı yabancılar

Vietnam özgürlük savaşçılarının tekniğinde

Toprağa cemre düştü alnındaki yıldızdan,

Orada karanlığı döverdi bir başka mevsim.

Sükunetten uzaktı Ortadoğu

Kabullenmeyen bir ülkenin gerçekliğine

Onlu yıllarla darbeler bağlanırdı,

Kurulurdu sokaklara idam sehpaları

Tedirgindi çorlu toprak.

Bir başka mevsimin en uzun geceleri

Newrozlaşırdı günler karanlığa inat

Isınırdı meşenin damarı,

Toprağa cemre düşerdi

Kabullenmeyen bir ülke içinden

Alişer''in sözü gelirdi torunlarının kulaklarına

Sırdaştırlar, toprakla sözlü ezgileri,

Gelirdi gecenin melekleri

Giderdi gecenin melekleri

Newrozlaşan günlerdi ilk cemreden kalma.

Toprağın yüzü gülerdi hasat zamanı

Çatırdardı karanlık,

Yağmuru çekerdi toprağın yüzü

Çorlu toprak tedirgin.

Sükunetten uzaktı Ortadoğu

Hesap kitap içindeydi tüm dünya

Yürekler dağlanmıştı kor ateşinde

Alınteri ezilmişti çarkın dişlilerinde

Açlıktan kazınırken karınları

Sonbahar yakılırdı,

Kış kovulurdu ülkeden

Newrozlaşırdı günler.

Şafağa vuran bir başka mevsim

Bahardı, yazdı Mezopotamya

İnsanı yaratmaydı insanlığa

Toprağı kaplarken ezili alınteri...

(Ezgilerde Kaldı Yüreğim 1.Kitap)       

Uyandırın Silkinsin 

Uyandırın, beceriniz de varsa

Ellerinden tutup kaldırın ayağa

Karanlığa yatanı

En güzeli de olsa uykusunu,

Koysun yılanın koynuna.

Uyandırın derdine kadeh kaldıranı

Ellerinden tutun

Kadehini kaldırırken de birileri

Hizmet etmektedir ona.

Uyandırın,

Elinden çalınan ekmeğin kavgasına

Beynine girmeden korkunun duvarı

Uyandırın silkinsin.

...

Uyandırın yoğurmak için emeğini

Kan deryasında kaybolmadan izi,

Yük kaçkınları türemiş gezinirler

Gözlerini açıp parmaklarınızla gösterin

Ağırlaşır yükü bu sevdanın altında.

Ellerine bakarsın ateşlenmiş kalbinle

Yılların öfkesini çıkarırcasına yuvasından

Sevdası büyür ellerinin yükü de büyürdü

O nasırlı ellerin...

Geleceğini küçük adımlarında mı görürsün

Atamadan üstünden yük kaçkınlarının yükünü

Nesiller boyu gitmek istersin ya kök köke

Dedene kadar ancak, gözlerinin ışığı...

Bırakırsan olduğu yerde yük kaçkınlarını

İsyanındır, çığlığındır der kulak veririm

Sevdanın şarkısında dile gelen sesine...

(Ezgilerde Kaldı Yüreğim 1.Kitap)      

Duyanlarda mı Duymadılar 

Bizi bombaladılar önce,

Bir tek biz miydik? 

Bombalanan topraklarda

Gingko bitiyor şimdi.

Hiroşima''dan sonra

Ülkeme geldi sıra

Halepçe''ye düştü

Acı, kahır içinde,

Hardal gazında

Yumdu gözlerini

Beşbin Kürt

Beşbin yürek,

Beşbin insan çığlığı...

Çarkın dişlerinde 

Kayboldular,

Duyanlarda...

Duymadılar

Efendilerinin

Gölgelerinde

Kaldı kulakları

Görenlerde...

(Ezgilerde Kaldı Yüreğim 1.Kitap)     

Suya Kalır Berraklaşması 

Yağmurla,

Güneşle,

Buluşan toprak

Herkese yettiği kadar gülümser.

Şafağa vuran ülkenin ezgilerinde.

Nasıl ki veriyorsa güneş sıcaklığını

Şeftalinin çekirdeğine değin 

Rengini

Nasıl ki veriyorsa toprağa 

Gülümsemeyi

Ve yayıyorsa dört bir yana,

Rüzgara kalır taşıması 

Yağmura kalır okşaması 

Suya kalır berraklaşması...

Toprağa cemre düştüğünde

Newroz''dur

Hazreti Ali''nin doğumuna

Mazlum''un eylemine

Denk gelir

Güneş gülümseyerek bırakır

Kendini toprağın üstüne,

Katline koşan serserinin

Bilmezliği ne? ...

Yaprağından 

Dalından dökülen 

Külün üzerinden

Girmek için toprağın bir ucundan,

Filize durup yarınlara

Bir dal, bir fidan...

Ve bükülmeyen Çınar

Ape Musa doğdu

Bu topraklarda...

(Ezgilerde Kaldı Yüreğim 1.Kitap)    

Kanadı Kırık Kuş 

Bir ülke, gökyüzü kaplıydı dumanla

Ama baykuş, ötmüyordu henüz

Gecenin melekleri dibine çömeli

Dipnotunu düşerlerken 

Minnacık cep defterlerine...

Kanadı kırık kuş buruk kalbindeydi

Çatışmalar ortasında kalırdı,

Akbababalar konuşurlardı üzerine.

Gidilmezse bu yol,

Delinmezse gecenin karanlığı

Hiçbirineydi başlamaları...

Bir nehrin yatağından akarken

Toprağın ezgisi okyanusa doğru

Çağlayan sesleriydi vadilerden geçen

Yalınayaktılar gecenin melekleri...

Patladı patırtı, koptu tozu duman içinde

Zindan bakışlıydı gelenler

Yüreğine düşmüştü bomba

Patlarsa bir gün 

O yüreğinden patlardı...

Balık bilinir, su bilinirdi

Gecenin melekleri bilinirdi

Dağın sesinde

Her geçen gün 

Yenilenmiş umutları...

(Ezgilerde Kaldı Yüreğim 1.Kitap)   

İkirciklere Ağ Atarlar 

İkirciklerin 

İştahı kabarıyor

Yem gelirken 

Orta yere.

İkircikler aç,

Kendinden uzakta, 

Yabancı

On adım 

Gerisindedir sözleri.

Yem 

Açlıkları 

Kendine çekiyor

Koştururlar

Şimdi 

Suyun 

Yüzündedirler

Yarış içinde...

Ağ atılır tümüne.

İnsanlaşmanın 

Korkusudur

Donuk gözlerde

Yüzleri ürpek

Ağa tutunurlar

Namussuzca.

Korkaklar, 

Kaçkınlar

Soysuzlaşmalar

O ağdadır.

Estetik işe yaramadı

Korkuluğa da

Yaranmadan 

Kuruyacaklar...

(Ezgilerde Kaldı Yüreğim 1.Kitap)  

Düşüncenin Körlüğü Dilendirir 

Düşüncenin körlüğü 

Besmele okutur 

Karanlığa

Dilendirir.

Boş gözlerle 

Bakındırır

Burnunun tepesinden

Bir yanının felcidir.

Beynindeki

Kurt kemiriğidir

Karanlığın,

Korkuya eğilir mi dilin

Ve de elin

Üç kuruşa satarsa emeğini 

Tüccarlara

Ucuzca bir yaşam içinde

Gerçekliğinden uzaklara 

Düşersin...

Düşüncenin körlüğü 

İnsanı savurur

Aşktan, 

Topraktan edercesine

Ve de kendinin 

Olamayacak kadar

Boş bir esintide,

Ömür tüketir...

Boş gözlerde 

Düşünce körlüğü

Bakındırırsa eğer

Bir ışık,

Bir kıvılcım

Ancak yol boyu

Göbeğinden 

Yarıyorsa karanlığı

Benliğine

Alamayacak kadar da 

Derin

Silkelenmelerle

Üzerinden dökülür...

(Ezgilerde Kaldı Yüreğim 1.Kitap) 

Ayakta Kalırdı 

Bir lokma ekmeği tanır

Kokusundan anlardı 

Bir bardak suda görür,

Ayakta kalırdı, 

Zorluklara dayanmasını bilirdi

Üstüne çöken karanlığı

Oyunlarını...

Bir lokma ekmeği bilir

Bir bardak suda korkusuzca 

Ayağa kalkardı.

Zindan içinde,

Zindandaydı

Gönlünde tutmaya 

Çalışır, çabalardı

Gidenlerin arkasından,

Düşenleri görür

Ayakta kalırdı.

İhanete düşmemek için

Kendini tanır, bilirdi 

Bir lokma ekmekte 

Bir bardak suda anlardı

İhanet ki sarmaş dolaş, 

Ayağına dolanırdı 

Yürürdü üstüne üstüne

İnsan olabilmesi için.

Kendinin olduğunda

Ayakta kalır kavrardı 

Ve emeksiz hiç bir şeye

Dönüp bakmazdı bile...

(Ezgilerde Kaldı Yüreğim 1.Kitap)

Babadan Bilme Yaşardı 

Kaplumbağa sabrıyla bir demirci

Yapardı, spariş gelen orağı

Hava karardığında ikindi vaktiydi

Bedenini saran karanlık, sırtından girmişti

Soğurdu bedeni kara bulutun ardında...

İklimi değildi bu ülkenin

Bu coğrafyanın iklimi değil

Bir yanda düşünürdü ak saçınan

Soğumuş teri kor ateşe damlardı.

Bir ömür gelip geçerdi

İnadına çile yüklenirdi sanki,

Kendi toprağında ağzı dolu

Gülemezdi insan.

Babadan kalma miras

Gelip geçerdi bir ömür

Bir adım büyütmez,

Bir gün götürmezdi

Babadan bilme yaşardı

Günbegün, tam bir ömür

Sınır geçmez, yol geçmezdi

Çilesini yüklenirken omuzlarına...

(Ezgilerde Kaldı Yüreğim 1.Kitap) 

Emeğini Çalanlar Doyar mı 

Dilim dilim ekmeğinden çalınır

Karanlığın karasındasın 

Üstüne tutsak da olursun

Neyin açlığıdır ki bu, gizemlidir.

Emeğini çalanlar doyar mı sanırsın

Alçaklığın binbir türlüsü

Ve en son tekniğiyle

Emeğine saldırırlar

Kanında pıhtılaşan zalimin zulmüdür

Türlü türlü insan suretleri türerler

Koordineli ve

Aşağılık bir yaşam içinde

Soysuzca...

Tutulmaları, kara olmalarındandır

Karanlığın karası

Kılıf olacak kadar

Zalimin gözündedirler

Ne varsa emeğe dayalı 

Elinde bilirler.

Karanlıktan kopan bulut

Kollarında yağmur mu taşır? 

Bir bardak suda, emeğini 

Boğmaya da çalışırlar

Doyulmaz mı emeğine,

Doymaz mı toprağına? ...

(Ezgilerde Kaldı Yüreğim 1.Kitap)', 'İlk cemresiydi daha toprağa düşen Karanlığa inat bir cemre İlk silkinişleri şimşek oldu beyinlere. Çocuklar kurbağa toplardı Arı kovanları e...', ARRAY['Türk Edebiyatı','Şiir','Ercan Cengiz']::text[], 8.5, '{"poet":"Ercan Cengiz","poet_slug":"ercan-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":312,"source_url":"https://www.antoloji.com/sukunetten-uzakti-ortadogu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ﮭ ﮭ ﮭ Tereddüt ﮭ ﮭ ﮭ', 'tereddut-sair-ahrazi-6nno6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ﺀ İster bin kerre doğun isterseniz can değişin.ﺀ 

ﺀ Cahil misin ey varlık,nedendir baş eğmeyişinﺀ 

ﺀ ﺀ ﺀ', 'ﺀ İster bin kerre doğun isterseniz can değişin.ﺀ  ﺀ Cahil misin ey varlık,nedendir baş eğmeyişinﺀ  ﺀ ﺀ ﺀ...', ARRAY['Türk Edebiyatı','Şiir','Şair Ahrazi']::text[], 8.5, '{"poet":"Şair Ahrazi","poet_slug":"sair-ahrazi","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/64429-64429-64429-tereddut-64429-64429-64429-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutlarım', 'umutlarim-sacide-yaylaz-8vgdn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Merhaba ey umutlarım

Merhaba

Dün buradaydım 

Bugün de buradayım

Yarın, 

Yarında belki,

Kapımı hep açık tuttum

Gelirsiniz diye umutlarım,

Hiç yitirmedim umutlarımı,

Henüz geç olmadı

Ama yarın,

Yarın ne olacak,

Bilemem umutlarım

Kapım açık,

Sizleri bekliyorum,

Yeni güne,

Yeni başlangıçlara,

Merhaba diyebilmek için

Yüreğimde sevgiyle,

İçimde yaşama heyecanı,

Yüzümde en sıcak gülümsemeyle

Hoşgeldiniz umutlarım 

Bunca yıl neredeydiniz,

Demeyeceğim.....', 'Merhaba ey umutlarım Merhaba Dün buradaydım  Bugün de buradayım Yarın,  Yarında belki, Kapımı hep açık tuttum Gelirsiniz diye umutlarım, Hiç...', ARRAY['Türk Edebiyatı','Şiir','Sacide Yaylaz']::text[], 8.5, '{"poet":"Sacide Yaylaz","poet_slug":"sacide-yaylaz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/umutlarim-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
