INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine', 'yine-yasemin-sezer-tulgar-klxsz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerimle büyüttüğüm o soru

Hani güzellikti sonu

Kıyılarından geçerken

Sağanak oldu

Mavi buğulu bulutlar ardında

Erken aymış ayın bakışında

Yansıyor aynı

O manzara

Düşlüyorum içime

Günaydınla gerinen kırgın bedenimle

Düşlerimden sorguları söküp

Cevap oluyorum

Baş rol benim yine

Sağanaklar içinden

Gülümsüyorum yansımasında

Düşlerimin aydan seferine

Sormuyorum

Soluyorum

Sen ve ben

Yine...

14.12.05', 'Gözlerimle büyüttüğüm o soru Hani güzellikti sonu Kıyılarından geçerken Sağanak oldu Mavi buğulu bulutlar ardında Erken aymış ayın bakışında...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Sezer Tulgar']::text[], 8.5, '{"poet":"Yasemin Sezer Tulgar","poet_slug":"yasemin-sezer-tulgar","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yine-57-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümün karanlığı', 'olumun-karanligi-selda-arslan-g2ipp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'atımı dört nala 

ölümün karanlığına sürüyorum

yaşam denilen

alçaklığın rengine kanmadan

şimdi gerçekleri koyup insanların yüzlerine

KOŞUYORUM...', 'atımı dört nala  ölümün karanlığına sürüyorum yaşam denilen alçaklığın rengine kanmadan şimdi gerçekleri koyup insanların yüzlerine KOŞUYORU...', ARRAY['Türk Edebiyatı','Şiir','Selda Arslan']::text[], 8.5, '{"poet":"Selda Arslan","poet_slug":"selda-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/olumun-karanligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım Dedim.', 'canim-dedim-ugur-kilic-i3s6l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Alışkanlık



Saçları ince ipek gibi,

Beyaz teni nur gibi,

Sordular varmı sevgi,

Evet dedim.

Ne güzellik dediler,

Biraz nazar ettiler,

Cok bakınca eller,

Aman dedim.

Pembedir kıyafeti,

Süslüdür zerafeti,

Sordular varmı eşi benzeri,

Yok dedim.

İnsan halinden anlar,

Ruhuma huzur katar,

İnsanmıdır dediler,

Melek dedim.

Değiş değiş zevkleri,

Çok sever çiçekleri,

Sordular hangisini,

Gül dedim.

Mercan gibi gözler,

Baldan tatlı sözler,

Sordular kim bu güzel,

CANIM DEDİM.

Yüzler asık üzüldürler,

Böylesini istediler,

Mevlaya yalvardılar,

Amin dedim.', 'Alışkanlık Saçları ince ipek gibi, Beyaz teni nur gibi, Sordular varmı sevgi, Evet dedim. Ne güzellik dediler, Biraz nazar ettiler, Cok bakı...', ARRAY['Türk Edebiyatı','Şiir','Uğur Kılıç']::text[], 8.5, '{"poet":"Uğur Kılıç","poet_slug":"ugur-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/canim-dedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cesaretim Kırıldı', 'cesaretim-kirildi-mehmet-ayhan-gunaydin-0jr2u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'CESARETİM KIRILDI

Zengin olayım dedim,

Rahat etmek istedim.

Çalıştım da onca yıl,

Yine de edemedim.

Artık zaman daraldı,

Zorlayarak olmuyor.

Cesaretimde kırıldı,

Artık kafam basmıyor.

İstemiyorum da artık,

Yaş da erdi kemale.

Baktım durum da, batık,

Geçti artık hevesimde.

Zenginlik şöyle dursun,

Bir Ohhh! diyecektim.

Bir gün olsun, tek gün olsun

Çok şükür diyecektim.

Şu hayatı bir gün olsun,

‘Sidik zoruyla’ 

Geçirmeseydim.

M. Ayhan Günaydın.

    14 Aralık 2005 

          Ankara', 'CESARETİM KIRILDI Zengin olayım dedim, Rahat etmek istedim. Çalıştım da onca yıl, Yine de edemedim. Artık zaman daraldı, Zorlayarak olmuyor....', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ayhan Günaydın']::text[], 8.5, '{"poet":"Mehmet Ayhan Günaydın","poet_slug":"mehmet-ayhan-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/cesaretim-kirildi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emekli Olacaktım', 'emekli-olacaktim-mehmet-ayhan-gunaydin-33k8l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'EMEKLİ OLACAKTIM

Çalışmadan olmuyor.

Eve ekmek gitmiyor.

Yazık ki memlekette

Şiirle karın doymuyor.

Olmuyor çalışırken,

Kaçamak da yazılmıyor.

Çok denedim lakin,

Fazla bir şey çıkmıyor.

Emekli olacaktım,

Oturup yazacaktım.

Hesapladım günlerimi,

Tam da ayrılacaktım.

Ben böyle düşünürken,

Onlar erken davrandı.

Ve emeklilik yaşı,

Epeyce uzatıldı.

Denilebilir belki; 

Şair bu ilham alır.

Kolay, nerede olsa yazar.

Ben böyle zorlanıyorum,

Benim çapım bu kadar.

Bunca yıl çalıştım,

Hiçte zengin olmadım.

Bi bu kadar da çalışsam,

Yine olmayacaktım.

Kararımı almıştım,

Emekli olacaktım.

Sekeyim parasını,

Ben şiir yazacaktım.

Yahu! 

Ebemizi sevdiniz,

Çıkmadı hiç sesimiz.

Utanmadan, gözünüzü bir de

Bize mi çevirdiniz? 

Yahu niye uzattınız? 

Niye şu emeklilik yaşını.

Ben emekli olacaktım.

Sekeyim yaptığınızı,

Ben şiir yazacaktım.

M. Ayhan Günaydın.

13 Aralık 2005-Ankara', 'EMEKLİ OLACAKTIM Çalışmadan olmuyor. Eve ekmek gitmiyor. Yazık ki memlekette Şiirle karın doymuyor. Olmuyor çalışırken, Kaçamak da yazılmıyo...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ayhan Günaydın']::text[], 8.5, '{"poet":"Mehmet Ayhan Günaydın","poet_slug":"mehmet-ayhan-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/emekli-olacaktim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güz geldi ya hani, yazlar geçti ya üzerinden sevdanın?', 'guz-geldi-ya-hani-yazlar-gecti-ya-uzerinden-sevdanin-seckin-turk-o0b4c', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Güz geldi ya hani, yazlar geçti ya üzerinden sevdanın? 

mevsimleri saymanın peşine düşmüş, 

ağlar çoban kızım, bekler üşümeden oturabildiği taşların 

çamura bulanmış baharını! ! 

Sessiz sedasız geçen koca günün 

aklında kalan tek karesidir kardelenin uzamaya çabalayan boynu, 

beyaza inat sarılığı, güneşliği, diriliği! ! 

Küsmek nedir bilmemişliği! ! 

Hepsi tek karede, hepsi ömürlük birer ders, 

hepsi goncası baharın, sümbülü sonbaharın! ! 

Gezdi bitirdi dağlarını çoban kızım, kardelenlerin arasında! ! 

Baharı göremedi çoban kızı,donakaldığı memeleket semalarında 

başı gökyüzüne dönük 

günlerce bekledi umudu! ! 

Umut meşguldü, umudun kuruydu tuzu.....', 'Güz geldi ya hani, yazlar geçti ya üzerinden sevdanın?  mevsimleri saymanın peşine düşmüş,  ağlar çoban kızım, bekler üşümeden oturabildiği ...', ARRAY['Türk Edebiyatı','Şiir','Seçkin Türk']::text[], 8.5, '{"poet":"Seçkin Türk","poet_slug":"seckin-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/guz-geldi-ya-hani-yazlar-gecti-ya-uzerinden-sevdanin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalancı Aynalar', 'yalanci-aynalar-serkan-turna-nya21', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aynalar,zamana galip yansıtır hüznü

şimdi kalpler kırık, eşyalar kırık,

paramparça aynalar..

biri, yüz gösterir şimdi

bu yalancı aynalar….', 'Aynalar,zamana galip yansıtır hüznü şimdi kalpler kırık, eşyalar kırık, paramparça aynalar.. biri, yüz gösterir şimdi bu yalancı aynalar…....', ARRAY['Türk Edebiyatı','Şiir','Serkan Turna']::text[], 8.5, '{"poet":"Serkan Turna","poet_slug":"serkan-turna","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yalanci-aynalar-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessiz Güzel', 'sessiz-guzel-tekin-koc-0b1xr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ellerinde hayatın çizgileri

Yüzünde ise dünyanın güzelliği

Küçük kalbinde,

Yaşadığın aşkın bütün yükü

Gözlerin dalıyordu

Küçük odanın tek gözlü penceresinden 

O kimsenin erişemediği dünyaya

Yanlızlığındı belki

Seni böyle derinlere daldıran 

Belkide kalbideki yük

Aklın bir türlü baş edemiyordu

Kalbindeki duygulara karşı

İçinde yaşama isteği

Yanlızlık için bir mücadele

Hayata karşı 

Bu yanlızlığa son vermeye karşı', 'Ellerinde hayatın çizgileri Yüzünde ise dünyanın güzelliği Küçük kalbinde, Yaşadığın aşkın bütün yükü Gözlerin dalıyordu Küçük odanın tek gö...', ARRAY['Türk Edebiyatı','Şiir','Tekin Koç']::text[], 8.5, '{"poet":"Tekin Koç","poet_slug":"tekin-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sessiz-guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...YİĞİT YARENSİZ OLUR MU? ...(Görüntülü)', 'yi-gi-t-yarensi-z-olur-mu-goruntulu-i-lker-unlu-f1cig', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nice dağları sevdam ile aştımda geldim,

Sırtıma binbir yük vurdumda geldim,

İçimde saklı gizleri bilmedi kimse,

Sonuma bir umut katıpta geldim...

Çabam olmadı mertlik adına,

Ben babamdan gördüm de geldim...

Çocukken bindim yiğit atına,

Adımı kılıcıma yazıpta geldim! 

Sevdim amma sevdikçe sevildim,

Aşkımı Can''ıma sarıpta geldim...

Hep sevdik diye sevilmemek için,

Duygularımı içime atıpta geldim! 

Birçok söz ettim böyle bilindim,

Ben sözlerimle yaşayıp geldim...

Ne zaman bir bakışım anlattıysa sözleri; 

Ben bakışlarımla ölüpte geldim...

Yaşarken ölmeyi istemesem de ben,

Ölürken yaşama gülüpte geldim...

Uçurum kenarından bakınca yere,

Gözlerimi GÖKLERE dikipte geldim! 

Sevemedim birtürlü sahte sevdaları,

Ben neye sevdalanacağımı bilipte geldim...

Vatan deyince hep durdu zamanlar,

Şarjörüme TÜRKLÜĞÜ koyupta geldim! 

Sözlerimle anlatamam ben bu sevdamı,

Yüreğimi mısralara döküpte geldim...

Gözlerimdeki tebessüm sevdiklerim içindir,

Vatanıma yüreğimi sunupta geldim,

Yeminimi birkez daha tutupta geldim! ! ! 

Aralık 2005', 'Nice dağları sevdam ile aştımda geldim, Sırtıma binbir yük vurdumda geldim, İçimde saklı gizleri bilmedi kimse, Sonuma bir umut katıpta geld...', ARRAY['Türk Edebiyatı','Şiir','İlker Ünlü']::text[], 8.5, '{"poet":"İlker Ünlü","poet_slug":"i-lker-unlu","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yigit-yarensiz-olur-mu-goruntulu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Düşünmek Güzel Şey', 'seni-dusunmek-guzel-sey-orhan-mahir-kizilboga-dskb9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'seni düşünmek güzel şey

gecenin dipsiz karanlığında

yalnzılığım üşütsede

korkutsa da zamansızlığın

seni düşünmek güzel şey

kantinde gelmeyişini beklemek

gözlemek yollarını 

her telefonda aramanı düşlemek 

bir gece anzsızın gelişini

seni düşünmek güzel şey

gözlemek yollarını 

her telefonda aramanı düşlemek

bir gece ansızın gelişini

seni düşünmek güzel şey

anlamsız isteklerini

apansız gülüşlerini

gözlerinde sevinçlerini

seni düşünmek güzel şey

kırık dökük aynalarda 

parça parça yüzümün

sessiz kayboluşlarında

seni düşünmek güzel şey

aklıma düşmen bir sayfanın sessiz aklığında 

onca zaman sonra kalemi almak elime 

seslendirmek sessizliği

içimde binbir saçmalıkla

seni düşünmek güzel şey

konuşabilmek aynı dilden 

ortak korkularımızda 

seni düşünmek güzel şey...

GÜZELDİ....', 'seni düşünmek güzel şey gecenin dipsiz karanlığında yalnzılığım üşütsede korkutsa da zamansızlığın seni düşünmek güzel şey kantinde gelmeyiş...', ARRAY['Türk Edebiyatı','Şiir','Orhan Mahir Kızılboğa']::text[], 8.5, '{"poet":"Orhan Mahir Kızılboğa","poet_slug":"orhan-mahir-kizilboga","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/seni-dusunmek-guzel-sey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...! ! ! Acı Çekmekten Korkanlar Utansın! ! ! ...', 'aci-cekmekten-korkanlar-utansin-i-lker-unlu-51p81', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Acı çekmekten korkanlar utansın,

Varsın dertlerin hepsi toplansın,

Bu yürek kaldırmışsa hep en ağır yükü,

Bırak acı çekmekten korkanlar utansın! 

Uçurumun eşiğinde gülümsemenin tadını,

Üstesinden gelmenin direnişin adını,

Ben benliğime yazdım yıkılmama andını,

Bırak acı çekmekten korkanlar utansın! 

Sözüm andımdır dedim hep böyle yürüdüm,

İlkelerim dorukta dedim ne dağlar aştım,

Dayanılmaz acılara katlanmışsa bu yürek,

Bırak aslanım acıdan korkanlar utansın! 

Bana ne dertten ne korkudan bahset,

Dayanacak yürek var mı sen ondan söz et! 

Hala yaşıyorsun sen buna şükret,

Ben artık bıraktım sen gibiler utansın! ! 

Ekim 2005', 'Acı çekmekten korkanlar utansın, Varsın dertlerin hepsi toplansın, Bu yürek kaldırmışsa hep en ağır yükü, Bırak acı çekmekten korkanlar utan...', ARRAY['Türk Edebiyatı','Şiir','İlker Ünlü']::text[], 8.5, '{"poet":"İlker Ünlü","poet_slug":"i-lker-unlu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/aci-cekmekten-korkanlar-utansin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu an için katlanıyorum her türlü yokluğuna....', 'bu-an-icin-katlaniyorum-her-turlu-yokluguna-ayfer-ersoy-ybx6b', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir su damlası avuçlarımın içinde gözlerin

Bir an var oluyor, içimi titretiyor

Bir an da kayboluyor izi kalıyor geride...

Yolların, dağların ardında yüreğim....

Adım attığın yerde ayaklarım

Tuttuğun, dokunduğun her cisimde ellerim.

Yokluğu hissetmek mümkünmü böyle doluyken ruhum seninle

Aklıma düşüyorsun hiç olmadık yerde

Alt üst oluyorum bir anda

İçim titriyor; üşüyorum

Sesini duymak istiyorum...

Gecelerini ne sen sor ne ben anlatayım bu şehrin

Başımı yastığa koyduğumda 

Uzanıyor yokluğun boylu boyunca yanıma

Küçük bir tebessümle hayalin geliyor ardından uykuya dalıyorum...

Sokak çocukları gibi hissediyorum bazen kendimi

Üstü başı yırtık, elleri boyalı, yatacak yeri olmayan 

O canım cocuklar gibi

Yokluğun evsiz, barksız bırakıyor beni...

Her güne merhaba diyen güneş gibiyim bazen

Her yeni güne doğuyor, hasretini biriktiriyorum geceye

Ve her gün biraz daha çoğalıyorsun içimde...

Tan vaktinde buluşuyorum gözlerinle semanın...

Gökkuşağı oluyorum, binbir rengin karışımı

Meltem rüzgarı dağıtır kokunu

Avuçlarımın arasına getirir... 

Ölümsüzleriş o an

Gözlerimi gözlerine açtığımda

Sen yanımda olduğunda

Ve

Bu an için katlanıyorum her türlü yokluğuna....

                                                             26.09.2002', 'Bir su damlası avuçlarımın içinde gözlerin Bir an var oluyor, içimi titretiyor Bir an da kayboluyor izi kalıyor geride... Yolların, dağların...', ARRAY['Türk Edebiyatı','Şiir','Ayfer Ersoy']::text[], 8.5, '{"poet":"Ayfer Ersoy","poet_slug":"ayfer-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/bu-an-icin-katlaniyorum-her-turlu-yokluguna-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '..Uyanış..', 'uyanis-i-lker-unlu-iqaub', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yer gök yarılır,

Ey Rabbim,

O kadar büyüksün ki,

Derdi de veren sensin,

Derdin içindeki, dertten büyük mutluluğu da...

Ağlatan da sensin,

Gözyaşını güldüren de...

Nerede menzilim, nerede anam...

Nerede yârim, nerede özgürlük...

Ey insanlık,

Tanrı şahidimdir! 

Yakacağım dört yanı! ! ! 

18 Aralık 2003

Perşembe 

23.50', 'Yer gök yarılır, Ey Rabbim, O kadar büyüksün ki, Derdi de veren sensin, Derdin içindeki, dertten büyük mutluluğu da... Ağlatan da sensin, Gö...', ARRAY['Türk Edebiyatı','Şiir','İlker Ünlü']::text[], 8.5, '{"poet":"İlker Ünlü","poet_slug":"i-lker-unlu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/uyanis-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**-Namert-**', 'namert-i-lker-unlu-0ngkl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kimse halim anlamıyor,

Beni namertler değil; 

Bencil insanlar korkutuyor...

Bana yapılan hırlık, hırsızlık,

Çıkarcılık, yalakalık,

Kansızlık, namussuzluk,

Ve namertlik elbet cezasız kalmıyor! 

Ama NANKÖRLÜK kanıma dokunuyor...

İçimi soğutuyor...

Yalancı adamı sırattan önce,

Delik deşik edesim geliyor! 

Bu kahpe dünyanın,

Şerefsiz yüzü,

Benim içime sinmiyor...

Sinirleniyorum...

Şerefsizlere karşı,

Yüreğimi koyuyorum tam orta yere...

Hadi göster kendini...

Gel bırak menfaatleri, olduğun yere...

Sende de varsa iki gram yürek,

Çık karşıma! Delikanlı gibi! Meydan okuyorum! 

Dertleri paylaşacak er meydanı istiyorum! 

Hangi kitapta yazar ulan? 

Zaaf arayıp açmak arkadan çeneni,

Hançer sallamak arkadan, namertler gibi? 

Bu mu senin o delikanlı yüreğin? 

Şu kahpe dünyada bu kadarcık mı sesin? 

Mertlik ve onur üzerindedir her şeyin,

Teker teker değil ulan toplanın da gelin! 

21–23 Aralık 2003', 'Kimse halim anlamıyor, Beni namertler değil;  Bencil insanlar korkutuyor... Bana yapılan hırlık, hırsızlık, Çıkarcılık, yalakalık, Kansızlık...', ARRAY['Türk Edebiyatı','Şiir','İlker Ünlü']::text[], 8.5, '{"poet":"İlker Ünlü","poet_slug":"i-lker-unlu","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/namert-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '-İnsandaki tecellî', 'i-nsandaki-tecell-sair-ahrazi-ijyul', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ömrünce hayâl ettin ve umdun bir çok şeyi,

Gün oldu kederlendin

Gezdin yapayalnız,tek başına

Bir canlıya hasret vâdîler gibiydin

Ömrünce hayâl ettin yeşermeyi

Gördün nice yıl sonra

Ufkuyla örülmüş bir kaleydi insan! 

Devrilmez bilirdin oysa

Yıkılsa da bazen toprak avlusu

Bir taş gibi çarpan duygularla.

Ömrünce hayâl ettin,sığındın bir çok yere

Sandın ki,hayat,bilmekten ibârettir; 

Zehretmeyi hattâ sevdiğin herkese! 

Ulaşmak,gidebildiğince her köşesine

Ve hakkiyle sevmek; ne varsa doğru,iyi

Hayat,bir tek şeyden ibârettir idrâkimce; 

Fark edebilmektir en doğru sevgiliyi! 

İşte bu hayâldir cüssendeki varlık senin

Kalbindeki nûr ve rûhundaki tecellî.

* * *', 'Ömrünce hayâl ettin ve umdun bir çok şeyi, Gün oldu kederlendin Gezdin yapayalnız,tek başına Bir canlıya hasret vâdîler gibiydin Ömrünce hay...', ARRAY['Türk Edebiyatı','Şiir','Şair Ahrazi']::text[], 8.5, '{"poet":"Şair Ahrazi","poet_slug":"sair-ahrazi","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/insandaki-tecelli-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babakale', 'babakale-zeki-ergin-iammj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'gülen yüzünü özledim köyümün 

zeytin ve balık 

ve anason kokan sokaklarını

karayel ve poyrazını

kalenin karşı kıyılara selam verişini

özledim

meyhane masalarında 

rakıya meze olan 

muhabbet ve Ege türkülerini

özledim

gururlu ve mağrur Babakale

kır çiçeklerinle

kekik kokuların

nazlı sandallarınla

her şeyinle seni özledim

_erenköy 14ara''05

_şarkılar savrulur ege''den pencere yayınları mar''14', 'gülen yüzünü özledim köyümün  zeytin ve balık  ve anason kokan sokaklarını karayel ve poyrazını kalenin karşı kıyılara selam verişini özledi...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/babakale-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**Destan**', 'destan-i-lker-unlu-ocxq6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dostluk yüce kavram,

Kolay bulunmaz biliriz...

Ancak her arkadaşta,

Dost adayıdır biliniz...

Yıllar yılı çok arkadaş,

Gelip geçti ömrümden...

Adam gibi adam unutmaz! 

Çoğunun ismi kaldı...

Sevdiğimiz çok oldu, sevilmedikte,

Biz böyle gördük,

Yanlış yapmadık bir kere! 

Arkadaş dedik,

Delikanlı gibi bağlandık...

Hep mert bir yürek içinde,

Delikanlı bir dost aradık! ..

Gerçek değerlerinin farkını çözdük,

Anası tipli çömezlere,

Bizi sattıklarında gördük! 

Yaşananlara yazıktı,

Ne dert yandık, ne üzüldük...

Hep menfaatlerin ötesinde,

Beklemekteyiz dedik...

Yaptıkları şerefsizlikleri,

Hep hak diye gösterdiler...

Kendine inananlara,

Keriz lan bu dediler...

Dediler de bilmeden,

Yaşayarak gördüler,

Delikanlı bir bakışla,

Korku içinde eridiler! 

Böyle bir doğrulukla 21 yıl yaşadım,

Çıkarları değil, mert bir yürek aradım...

Yalan ile namert ile

Yalancı ile savaştım...

Bu kahpe dünyadan zarar gelmesin diye,

Sevdiğime severek, bir ömür adadım...

Benim mert kadınım, mağrur gözlü ceylanım,

Mezar olsam bana koşacak,

Delikanlı kadınım...

Gün geldi istemeden,

Acıyla kırdım seni...

Böyledir gözü kara,

Delikanlının kaderi...

Adam gibi adam olunca, mert olan insanı,

Galipte yıpratmaya çalışır Âlem-i cihanı! ...

Oda sevdikleriyle kendini korumak için yangından,

Benliğini siper eder kahpe dünyanın ardından! ! 

Anlayışlı olmak lazım, sinir harbidir yaptığı,

Silmez gözünden akan oluk oluk kanları...

Sormak lazım ''Bu kan niyedir yiğit? ''

Gel bu sinirle sen beni de öğüt! ..

Yeter ki cevval gelmesin bu yorgun savaşına,

Arkandaki kadının dünya varsın farkına! ! ! 

O yine de derki; bu sözlere cevap:

Bu yolda kan dökmek elbetteki sevap,

Lakin bil ki gözümden akanlara sebep,

Kırılmana rağmen yanımda olan, sendeki edep! ..

Aralık 2003', 'Dostluk yüce kavram, Kolay bulunmaz biliriz... Ancak her arkadaşta, Dost adayıdır biliniz... Yıllar yılı çok arkadaş, Gelip geçti ömrümden.....', ARRAY['Türk Edebiyatı','Şiir','İlker Ünlü']::text[], 8.5, '{"poet":"İlker Ünlü","poet_slug":"i-lker-unlu","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/destan-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgar', 'ruzgar-hasan-can-jxdt5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Haykır rüzgara karışsın sesin,

Bir günlük özlemimi götürsün.

Her sonbahar geldiğinde,

Bir rüzgarın peşine düşerim,

Sana gelirim belki diye,

Bir umut olur içimde.

Aşılmamış dağlara çıkarır beni,

Sonsuz karanlığına inerim gecenin.

Belki bir hayal, yada bir avuntu,

Ama sırf senden ibaret o rüzgar.

Haykır, sesini rüzgar fısıldasın kulaklarıma,

Bir gece lambasının altında gölge olsun vefesin.

Haykır, tenime vursun rüzgar sesini,

Sarsın ürpertisi her yanımı.

Sonbahar bitiyor...

Haykır, son kez haykır,

Son sesin,

Son nefesim olsun.', 'Haykır rüzgara karışsın sesin, Bir günlük özlemimi götürsün. Her sonbahar geldiğinde, Bir rüzgarın peşine düşerim, Sana gelirim belki diye, ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ruzgar-124-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olsun', 'olsun-gokhan-oflazoglu-eerrr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Belirsizin gerçekliği

tek gerçeğin olsun.

Madem böyle yaratıldın,

heryer kendinle dolsun.

Hayırlı veya uğurlu,

ölümcül ya da acılı,

basacaksın bu toprağa,

altından çekilse de yer

öptüğün anlam olsun.

Küçük eşikler açtır toprağa,

şehvetin daim olsun.

Varsın sevdiğin gök, yeryüzü

hiçliğe ortak olsun.

Umursama, önemseme

şu anda diri yarın ölü

gelecek zevkin olsun.

Biterse bitsin bu oyun,

imkansız avın olsun.

14/12/2005', 'Belirsizin gerçekliği tek gerçeğin olsun. Madem böyle yaratıldın, heryer kendinle dolsun. Hayırlı veya uğurlu, ölümcül ya da acılı, basacaks...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/olsun-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şafağın Kızıl Gülü', 'safagin-kizil-gulu-mehmet-dogan-8-9fxfe', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Akıverse gözlerime

Dalga dalga maviler

Ak ak köpüklere deniz ki

Akdeniz

Alsın alsın götürsün

Yelken açar yüreğim

Dolsun çocuk sevinciyle

Fora derim bu geceye

Şafağın kızıl gülüyle

Yolcuyum engin sulara

Bazı bazı durgunum

Dalar giderim yitik yıllara

Anıları arar tararım

İndirdim bak

İndirdim bütün acıları

Demir attım umuda

Erteledim isyanlarımı

Zamanın sabır kollarına

Dudağımda dualar

Baktım o rıhtıma

Hüsran mı var karşılarda

Hani seni sevmek

Sana kavuşmak vardı ya

Delice bayramlar mıydı ki

Çıka geldi bir anda

Bebeğimin ilk soluğunda

İlk nabzın atışında

Ninni

Ninniler söyleyen

Şu annemin ışığında

Kucakladım da sahipleniverdim

Unutulmuş sevinçleri…', 'Akıverse gözlerime Dalga dalga maviler Ak ak köpüklere deniz ki Akdeniz Alsın alsın götürsün Yelken açar yüreğim Dolsun çocuk sevinciyle For...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Doğan 8']::text[], 8.5, '{"poet":"Mehmet Doğan 8","poet_slug":"mehmet-dogan-8","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/safagin-kizil-gulu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Aşka Aşık Olanındır', 'ask-aska-asik-olanindir-serkan-turna-kj4tr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşk, yalancılara 

göre değildir..

Su gibidir aşk

şekil vermek 

imkansızdır..

Aşk,

kullanılmaz,

unutulmaz, 

yaşanır...! 

Aşk, 

aşka

aşık

olanındır….



Çocuk gözlerin anlamaz beni 

bir yıldız gibi kayar hayatım ellerinde

sen, dilek tutarsın....', 'Aşk, yalancılara  göre değildir.. Su gibidir aşk şekil vermek  imkansızdır.. Aşk, kullanılmaz, unutulmaz,  yaşanır...!  Aşk,  aşka aşık olan...', ARRAY['Türk Edebiyatı','Şiir','Serkan Turna']::text[], 8.5, '{"poet":"Serkan Turna","poet_slug":"serkan-turna","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ask-aska-asik-olanindir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok geç herşey için...', 'cok-gec-hersey-icin-pinar-koc-d308e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yalnız bir gecenin koynunda,

Yalnız bir sevdanın

Son dakikalarını yaşamaktayım…

Vurulmayı bekleyen atlar gibiyim…

Koparın artık uğurböceklerinin kanatlarını,

İçine göz yaşlarımı doldurmalıyım…

Ateşböceklerini söndürün,

Karanlıkta kalmalıyım ömür boyu…

Yalnız yaşamayı öğrenmeliyim,

Hem hayatı,

Hem aşkı…

Yalnız bir gecenin koynunda,

Yalnız bir sevdanın 

Son dakikalarını yaşamaktayım…

Yarın çok geç olabilir

Her şey için……….

                                                       04.06.2002   01:46', 'Yalnız bir gecenin koynunda, Yalnız bir sevdanın Son dakikalarını yaşamaktayım… Vurulmayı bekleyen atlar gibiyim… Koparın artık uğurböcekler...', ARRAY['Türk Edebiyatı','Şiir','Pınar Koç']::text[], 8.5, '{"poet":"Pınar Koç","poet_slug":"pinar-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/cok-gec-hersey-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aklımda sıcak ellerin...', 'aklimda-sicak-ellerin-pinar-koc-o2i4v', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aklımda sıcak ellerin,

Tenimde teninin kokusu…

Bahçendeki kırmızı gül bile olamadım! 

Bana dokunmadın,beni okşamadın,

Sabahın ayaz kızıllığında,

Asla benimle konuşmadın…

Aklımda sıcak ellerin,

Tenimde teninin kokusu…

Sofrandaki sıcak lokman bile olamadım! 

Ne içini ısıtabildim,

Nede dokundun bana…

Bir yudum su bile olamadım ağzında! ! ! 

Aklımda sıcak ellerin,

Tenimde teninin kokusu…

                                                      08.07.2002   21:14', 'Aklımda sıcak ellerin, Tenimde teninin kokusu… Bahçendeki kırmızı gül bile olamadım!  Bana dokunmadın,beni okşamadın, Sabahın ayaz kızıllığı...', ARRAY['Türk Edebiyatı','Şiir','Pınar Koç']::text[], 8.5, '{"poet":"Pınar Koç","poet_slug":"pinar-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/aklimda-sicak-ellerin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir nefes çektim', 'bir-nefes-cektim-atil-kesmen-w5dvs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaban ormanların da

Tek dalı kalmış ağaç gibi

Ne kadar yeşersem

O kadar gam giyiyordum

Bedelin okları

Yaşamın diğer dalları olmalıydı

Of çektikçe

Güneşin keskin izleri

Ter nefesime gizlenmiş

Hislerimi kesiyordu

Tutunamıyordum

İstesem de

Tutunamıyordum, tutkularıma

Ve kaybolup gidiyordum

Gönlüme oturmuş

Sen kokan yalnızlığımla

Zaman

Zamanı deliyordu

Sonsuz boşlukta kaybolmanın

kırıntıları damlıyordu

Küllenmiş,gönül bahçeme

Ve bir renk oluşuyordu

Gökyüzün de

Maviliklere panjur çekercesine

Yaban ormanları 

Baş kaldırmış olmalıydı

Sahipsiz kalmış, yaşam sevgime

Yalnızlığımın 

Ayak izleri

Çaresizliğim olarak kesiyordu

Kalp seslerimi

Avuçlarıma tünemiş,yaşam çizğileri

Umutsuzluk ışığını

Yakıp yakıp söndürüyordu

Ve ben

Tek dalı kalmış ağaç gibi

Hisler pedesine, saklıyordum sevgimi

Kaderin kör zincirleri

Ufkumun göz kıyılarını kesiyordu

Gönlüm de

Yalnızlığını soluduğum sevgim

Acılarla buluşmuş,içimi deliyordu

Ve yok oluşun başlanğıcına

Adım adım gidiyordum

Siyah tablo desenleri eşliğinde

Bir yerim daha ağrıyordu

Acaba

Bu tek daldamı kuruyordu

Başımı kaldırdım

Güneşi kokladım

Kendimi kendimle böldüm

Sevgi ustalığına büründüm

Yıldızları bir bir yalnızlığıma ekledim

Ve gönlümü

Yaban ormanlarına gömdüm

Bir nefes çektim

Şimdi

Evet…Şimdi

Yeniden yeşermenin sevincini yaşıyorum.', 'Yaban ormanların da Tek dalı kalmış ağaç gibi Ne kadar yeşersem O kadar gam giyiyordum Bedelin okları Yaşamın diğer dalları olmalıydı Of çek...', ARRAY['Türk Edebiyatı','Şiir','Atıl Kesmen']::text[], 8.5, '{"poet":"Atıl Kesmen","poet_slug":"atil-kesmen","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/bir-nefes-cektim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık zor...! ! !', 'artik-zor-pinar-koc-s07em', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gitmeliyim artık buralardan diyorum,

Bu sokaklar artık bana zor! ! ! 

Unutmalıyım diyorum geçmişi,

Bu hayat bana zor…

Kahpe faklara düştüm,

Yenildim ve 

Yendim…

Bu hayat benim diyorum,

Ben yaşamalıyım ve 

Yaşamalıydım…

Mutlu olmalıyım diyorum,

Ve olmalıydım…

Unutulmaz acıların sonu gelsin diyorum…

Gitmeliyim artık buralardan,

Bu sokaklar artık bana zor…

                                                      20.08.2002     21:00', 'Gitmeliyim artık buralardan diyorum, Bu sokaklar artık bana zor! ! !  Unutmalıyım diyorum geçmişi, Bu hayat bana zor… Kahpe faklara düştüm, ...', ARRAY['Türk Edebiyatı','Şiir','Pınar Koç']::text[], 8.5, '{"poet":"Pınar Koç","poet_slug":"pinar-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/artik-zor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç Yaşanmamış', 'hic-yasanmamis-sinan-bilici-i80uu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yıllanmış şarap gibi eskiydi felsefelerimiz

Birbiriyle dosttu ikisi

Kız alıp verilmiş çağlar boyunca 

Devrişler,hükümdarlar yetiştirmişti

Yine de bozulmamıştı gelenekler

Ta ki seni sevene dek bunlar

Zıtlaştı dini düşüncelerimiz,şaha kalktı

Sen alevi ben sunni diye 

Nedendir sanki bunca yaşananlar 

Hiç birşey olmamış gibi kapıyı vurup çekip gitmeler

Sanki boşuna mı demiş Ahmet Arif 

Hasretinden prangalar eskittim diye', 'Yıllanmış şarap gibi eskiydi felsefelerimiz Birbiriyle dosttu ikisi Kız alıp verilmiş çağlar boyunca  Devrişler,hükümdarlar yetiştirmişti Yi...', ARRAY['Türk Edebiyatı','Şiir','Sinan Bilici']::text[], 8.5, '{"poet":"Sinan Bilici","poet_slug":"sinan-bilici","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hic-yasanmamis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adına Dair Birşeyler', 'adina-dair-birseyler-unal-cagabey-g5z2j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Adının kaybettiğim anlamlarından birine rastlardım köşe       

başında

 Sokaklar etnik bir kavganın ayakları altında ezilirken

 Haber verirdi kuşlar bir Yılmaz''ın doğumunu

 Ve seni hatırlardım bir şehirden başka bir şehre göz ucuyla bakarken

 Adının bilmediğim anlamlarını çağırırdım yardıma

 Usulca,davetsiz misafirlerin kavşağına 

 Yürürdüm,durmadan yürürdüm geleceğe doğru

 Hazin sonbaharların gelişine kulak tıkayarak

 Tandırdan yeni çıkmış ekmek tadında bulmak isterdim ismini

 Yarı Anadolu yarı Avrupa,Mezopotamya koksun isterim.

Adının kaybettiğim anlamlarını sorardım kendime

Usulca,fısıldayarak beynime

Kavga ederdim,durmadan kavga ederdim kendimle

Kavganın dar sokaklarında rastlardım ismine

Ve sorardım geleceğe benimle paylaşsın diye

Ve sorardım geleceğe benimle paylaşır mısın diye...

Uzadıkça uzardı yollar

İçimde büyürdü bir çocuk

Sonra arkandan bakardım yitik bir ömrün bakışlarıyla

Ve saat dörde çeyrek kala murat taşardı yerinden

Adını bilmediğim şeyhler doğururdu kasya köyü

Derinden,hissettirmeden

Laik bir Cumhuriyetin kalbine doğru...

Sonra göçlerle tamamlanırdı eski öyküler

Ve vücuda yayılırdı bütün hastalık

İçten içe hissettiridi kendini

Gözlerdeki ikamet yerini alınca.

Ve sona ererdi herşey...

Adının kaybettiğim anlamlarından birine rastlardım köşe başında

Ve bilmediğim anlamlarını çağırırdım yardıma

Usulca,kavgasız,gürültüsüz,patırtısız

Karanfil kokulu fakir sokaklara...', 'Adının kaybettiğim anlamlarından birine rastlardım köşe        başında  Sokaklar etnik bir kavganın ayakları altında ezilirken  Haber verird...', ARRAY['Türk Edebiyatı','Şiir','Ünal Çağabey']::text[], 8.5, '{"poet":"Ünal Çağabey","poet_slug":"unal-cagabey","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/adina-dair-birseyler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep Yargısız İnfaz', 'hep-yargisiz-i-nfaz-sinan-bilici-qc7b2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kırmızı şarap kokusuydu sevgili

Tadı acemi,buruk; ama bir o kadar hoyratça

Damarlarıma saklandın

Hayın,ürkekçe yok edişinle

Nazlı seher sabah vakitlerimi korku çığlıklarınla kaşıyıp durdun

Ne gün ne var oluş

Sanki bilerek yaptın bunları

Seni sana şikayet ederim dinlemezsin

Bırakırsın bir başına insanı

Ne hekim ne yargıç

Hep yargısız infaz yaparsın

Darağacında sallandırır,tövbeye getirirsin adamı

Ne sev ne anla 

Bu yüzden beni bana bırak dersin

Son lafın bu,son seslenişin bu

Bir sabah görünmeden ayrılırsın bedenimden 

Beni emanet eder

Son sözümü bile dinlemeden

Hep yargısız infaz edersin', 'Kırmızı şarap kokusuydu sevgili Tadı acemi,buruk; ama bir o kadar hoyratça Damarlarıma saklandın Hayın,ürkekçe yok edişinle Nazlı seher saba...', ARRAY['Türk Edebiyatı','Şiir','Sinan Bilici']::text[], 8.5, '{"poet":"Sinan Bilici","poet_slug":"sinan-bilici","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/hep-yargisiz-infaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatırlamıyorum...', 'hatirlamiyorum-seynur-i-nal-29cu3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hatırlamıyorum,

En son ne vâkit tutunmuştum

Baharın eteklerine...

Ansızın mı geçmiştim

İlkyazdan güze...

Yoksa usul usul muydu uyanışım

Ayaz bir kimsesizliğin gözlerinde...

Bilmiyorum,

Kim, hangi masalla inandırmıştı  aşka

Çocuk yüreğimi,

Yıllardır silinmedi izi içimde...

Ve

Arık bir umuda rağmen

Nasıl, neresinden sarılmıştım hayata

Ki, hâlâ elleri ellerimde...', 'Hatırlamıyorum, En son ne vâkit tutunmuştum Baharın eteklerine... Ansızın mı geçmiştim İlkyazdan güze... Yoksa usul usul muydu uyanışım Ayaz...', ARRAY['Türk Edebiyatı','Şiir','Seynur İnal']::text[], 8.5, '{"poet":"Seynur İnal","poet_slug":"seynur-i-nal","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/hatirlamiyorum-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlemindeyim', 'ozlemindeyim-ozgur-kokturk-b31ig', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yalınayak bir şarkıyım

Yitik bir İstanbul akşamı

Gece karanlığında gökkuşağı

Güneş altında gölgesizim

Özlemindeyim...

Tüm iradem bir arzuya tutsak

Adına gebe bütün şiirlerim

İsyansız bekleyişteyim

Özlemindeyim...

Sana bakıyor şarkılar

Ezgiler seni mırıldanıyor

Yankılanırken sesin şafağımın kızıllığında

Sisler içindeyim

Özlemindeyim...

Sanrılara sarılırım belirsiz

Bitimsiz seraplardayım

Ilgımıyla yanarken bakışının

Sevdanın küçük avuçlarında yüreğim

Özlemindeyim...', 'Yalınayak bir şarkıyım Yitik bir İstanbul akşamı Gece karanlığında gökkuşağı Güneş altında gölgesizim Özlemindeyim... Tüm iradem bir arzuya ...', ARRAY['Türk Edebiyatı','Şiir','Özgür Köktürk']::text[], 8.5, '{"poet":"Özgür Köktürk","poet_slug":"ozgur-kokturk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ozlemindeyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine Sana', 'yine-sana-sinan-bilici-o83ec', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir kalem daha tükendi 

Sensizlikleri bıkmadan yazarak 

Bir özlemin en daniskası

Seni bekleyip,ağlayarak

Yağmurlu şehirlere inat bir gözyaşıyla

Yeniden baharı bekleyip aşka susamak

Bu bir isyandır belkide sana 

İsteyipte yapamadıklarına cevap olsun

Mühür vurulmuş diline sevgim

Ya da sesine ses katsın 

Bağırmalarımla Ağrı''yı delen haykırışlarım

Ve yine de yoldaş olsun sana

Zayıf bedenimdeki sana susamış her hücrem', 'Bir kalem daha tükendi  Sensizlikleri bıkmadan yazarak  Bir özlemin en daniskası Seni bekleyip,ağlayarak Yağmurlu şehirlere inat bir gözyaşı...', ARRAY['Türk Edebiyatı','Şiir','Sinan Bilici']::text[], 8.5, '{"poet":"Sinan Bilici","poet_slug":"sinan-bilici","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yine-sana-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonsuz Aşk', 'sonsuz-ask-aydin-gore-mcfk5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gökteki bulutlar dökseydi gözyaşlarını,Benim senin aşkından ağladıklarımı tamamlayamazlardı,Mazide kalan bütün aşıklar,Benim sana olan aşkımı yaşayamazlardı.', 'Gökteki bulutlar dökseydi gözyaşlarını,Benim senin aşkından ağladıklarımı tamamlayamazlardı,Mazide kalan bütün aşıklar,Benim sana olan aşkım...', ARRAY['Türk Edebiyatı','Şiir','Aydın Göre']::text[], 8.5, '{"poet":"Aydın Göre","poet_slug":"aydin-gore","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/sonsuz-ask-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'AzAt Et BeNi', 'azat-et-beni-yurdagul-kurnaz-lc7bm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Azat et beni, vuslatina eremedigim        

Benligimde kayboldum, parcalandi yüregim

Mahsere kaldi yasaklim,adi bende saklim

Seni en uzak kovabildigim yer yüregim 

Azat et beni, yedi veren güller agliyor

Boynu bükük gurbetin, kislalari prangali

Kaf daginda kardelen günese yalvariyor

Seni en uzak kovabildigim yer siirler

Azat et beni, dünden yarindan karalardan

Okyanusu getir mavi derin dalgalardan

Günes almasin sicakligimi kollarimdan

Seni en uzak kovabildigim yer hayaller', 'Azat et beni, vuslatina eremedigim         Benligimde kayboldum, parcalandi yüregim Mahsere kaldi yasaklim,adi bende saklim Seni en uzak kov...', ARRAY['Türk Edebiyatı','Şiir','Yurdagul Kurnaz']::text[], 8.5, '{"poet":"Yurdagul Kurnaz","poet_slug":"yurdagul-kurnaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/azat-et-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hz. ÜZEYR', 'hz-uzeyr-abdullah-yasar-erdogan-aslrh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '(23. Büyük Peygamber) 

    

        Hz.  ÜZEYR 

Kur’an’da fazla adı geçmez,

Veli mi Peygamber mi bilinmez? 

Yahudiler der: “Allah’ın oğlu”

Bu şirktir, “haşa” böyle söylenmez.

Rabbim anmışsa O’nu hoştur,

Uydurma kitaptaki boştur.

İslâm son din biliriz elbet,

O’ndan güvenli asla yoktur.

Sapık millet demiş, onlar belli.

Öğüdün hangisini dinledi? 

Bu yüzden onlara; uyarıcı,

Peygamber, Nebi ve Resûl geldi.,

Makbul olan sevilen kuldur O,

Hakk emirleri yaşamışsa O,

Bize de saygı duymak düşmekte,

Herkes gibi hesap verecek O.

Bil ki, sana uyarıcı gelmiş,

O gelen, bana tapın dememiş,

Nefs ve gurur öyle istemişse,

Nefsin sonu hep helak getirmiş.

Azgın kavmi incele şaşarsın,

İnanmayan tarihe bir baksın,

Peygamberlere düşman olanlar,

Firavun akibetine baksın.

Şair: Abdullah Yaşar Erdoğan', '(23. Büyük Peygamber)               Hz.  ÜZEYR  Kur’an’da fazla adı geçmez, Veli mi Peygamber mi bilinmez?  Yahudiler der: “Allah’ın oğlu” B...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yaşar Erdoğan']::text[], 8.5, '{"poet":"Abdullah Yaşar Erdoğan","poet_slug":"abdullah-yasar-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/hz-uzeyr-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tüm Bu Sözcükler Sana', 'tum-bu-sozcukler-sana-sinan-bilici-imfrh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sırf sen istedin diye

Çıplak ayaklarımın,yorgun düşmüş gözlerimin suskunluğuyla

Sana yazıyorum

Bir yanım buz kesilmiş bedenimin 

Bir yanım çöl sıcaklarında kavrulmuş

''Umrunda mı diyor'' şair

Oysaki tüm bu sözcükler sana 

Sırf sen istedin diye 

Cesaretimin ağırlığında,demir kesilmiş yüreğinle 

Sana yazıyorum

Kalkan olmuş ellerin,bakışların hezimete uğratır

Belki bir umut dedim

Kapılar hep sana çıkıyor 

Oysaki tüm bu sözcükler sana 

İdam hükmümü şimdi kendi elimle veriyorum

Arsız sevmelerin ortasında kanat çırpmış keklik ihanetine

Yine de yeminler olsun ki

Tüm bu sözcükler sana 

Yalnızlığından beri seni düşlemek 

İmkansızlığa mabet olmuş teninle 

Tenime değen her yağmur damlası ğözyaşına

Yine de yeminler olsun ki

Tüm bu sözükler sana', 'Sırf sen istedin diye Çıplak ayaklarımın,yorgun düşmüş gözlerimin suskunluğuyla Sana yazıyorum Bir yanım buz kesilmiş bedenimin  Bir yanım ç...', ARRAY['Türk Edebiyatı','Şiir','Sinan Bilici']::text[], 8.5, '{"poet":"Sinan Bilici","poet_slug":"sinan-bilici","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/tum-bu-sozcukler-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelirim Dağlar', 'gelirim-daglar-ahmet-sefer-kocer-6vma5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Öyle dargın dargın bakma karşıdan

Bir gün olur yine gelirim dağlar

Korkmam heybetinden kara kışından

Bir gün geçit bulur gelirim dağlar

Ötmüyor kekliğin sustu mu dağlar

Alıcı kuşların pustu mu dağlar

Yoksa kurdun kuşun küstü mü dağlar

Darılma gün olur gelirim dağlar

Ak başın dumanlı bağrın mı yanar

Kızıla büründün yaran mı kanar

Kesilmiş suların akmıyor pınar

Aldırma gün olur gelirim dağlar

Yıllar boyu hasretini gizledim 

Uzaktan uzağa durup gözledim

Mor üstüne beyazını özledim

Bakarsın duramam gelirim dağlar', 'Öyle dargın dargın bakma karşıdan Bir gün olur yine gelirim dağlar Korkmam heybetinden kara kışından Bir gün geçit bulur gelirim dağlar Ötmü...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Sefer Kocer']::text[], 8.5, '{"poet":"Ahmet Sefer Kocer","poet_slug":"ahmet-sefer-kocer","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gelirim-daglar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Memleketim', 'memleketim-ebru-rabia-berkul-qwate', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Beyaza imrenmenin

Tutkusu haline gelmiş,

Pamuk tarlalarıyla

Sevdaların,

Ömür boyu,

Doyasıya yaşandığı

Sıcaklıkların,

Çıkarsız gülümsemelere

Yansıtıldıkları

Düğünlerin,

Şenlik havasında

Geçtiği.

Bir sevda

Türküsü gibi

Dilden dile,

Dolaşan

Memleketim.', 'Beyaza imrenmenin Tutkusu haline gelmiş, Pamuk tarlalarıyla Sevdaların, Ömür boyu, Doyasıya yaşandığı Sıcaklıkların, Çıkarsız gülümsemelere ...', ARRAY['Türk Edebiyatı','Şiir','Ebru Rabia Berkul']::text[], 8.5, '{"poet":"Ebru Rabia Berkul","poet_slug":"ebru-rabia-berkul","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/memleketim-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Yeterki Ağla Göz Bebeklerimde', 'sen-yeterki-agla-goz-bebeklerimde-sinan-bilici-ux7uh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ağlarsan göz bebeklerimde toprağa düşerken

Bir tufan ki sarar ömrümün her yanını

Deli dolu sevmeler ve sevişmelerin

Hep izi kalsın mahçup suratında 

Belki hatırlarsın bir gece yankısı ağlamada 

Hiç umrunda olmasada 

Benim için iki damla gözyaşı dök istemeyerek

Ben yine sana tutsak kalırım düşlerimde 

Sen yeterki ağla göz bebeklerimde 

Ağla ki şehirler utansın zehir yağmurlarıyla 

Sana susasın caddeler ve sokaklar

Anlasın kendi muhtaçlığını

Güller biriktirsin bir buse yanağında 

Şarabın tadına inat

Acı bir tad bıraksın gülücüklerinde 

Sarhoş olsun bu akşam esmer teninde bakışların

Ben yine sana tutsak kalırım düşlerimde 

Sen yeterki ağla göz bebeklerimde 

Seninle ebedi düşler kurardık

Bir niceden bir niceye 

Bir ceylanın gözleriydi düşümüzde kalan 

Sen üzülme ey sevgili

Ben yine sana tutsak kalırım düşlerimde 

Sen yeterki ağla göz bebeklerimde 

Dayanamaz bir hal alırsam dualarımla 

Günahlarımla yargılanırsam sıratta 

Bir tanrısın ki beni sen kurtar

Bu sefer ben ağlarım göz bebeklerinde 

Sen yeterki ağlama', 'Ağlarsan göz bebeklerimde toprağa düşerken Bir tufan ki sarar ömrümün her yanını Deli dolu sevmeler ve sevişmelerin Hep izi kalsın mahçup su...', ARRAY['Türk Edebiyatı','Şiir','Sinan Bilici']::text[], 8.5, '{"poet":"Sinan Bilici","poet_slug":"sinan-bilici","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sen-yeterki-agla-goz-bebeklerimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut güzel şeydir', 'umut-guzel-seydir-ridvan-cetin-g7c0a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Umut güzel şeydir

Kalbinde taşıyorsan

Sevmek güzel şeydir

Gerçekten seviyorsan

Yaşamak güzeldir

Anlamını biliyorsan

Sevmek güzeldir

Gerçekten seviyorsan', 'Umut güzel şeydir Kalbinde taşıyorsan Sevmek güzel şeydir Gerçekten seviyorsan Yaşamak güzeldir Anlamını biliyorsan Sevmek güzeldir Gerçekte...', ARRAY['Türk Edebiyatı','Şiir','Rıdvan Çetin']::text[], 8.5, '{"poet":"Rıdvan Çetin","poet_slug":"ridvan-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/umut-guzel-seydir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutant', 'mutant-firat-ulker-3604l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İçimde fener yakma boşuna

Cisim yok ki

Neyi göreceksin

Duvarlarımdaki çatlakları

Yuva bilmiş örümcekleri

Bi de köşeden köşeye ağ örgüleri

Neyi göreceksin ki başka

Yok ki yok..

Şimdi ışık tutulabilir aslında

Sen varsın o boş odada

Müthiş bi resterasyon

Yaradanın nacizane süprizi

Ama neye yarar

Körken dünya''nın gözleri

Hadi kapatın lambaları

Durun

Gerek yok ki

Kimse görmüyor zaten

Ne gündüzleri,ne de geceleri

Güneşin üstüne 

Siyah perde atmış birileri

Bi gün herkes görecek biliyorum

Evrimleşip olunca uçan memeli

Ben oldum

Görünür yaptı herşeyi

Gırtlağımdaki ses telleri

Sizde görmek istiyorsanız

Emin çatlaklarımda sızan kanları

Duvarlarımın arkasında

Gece kuşu tırnakları..', 'İçimde fener yakma boşuna Cisim yok ki Neyi göreceksin Duvarlarımdaki çatlakları Yuva bilmiş örümcekleri Bi de köşeden köşeye ağ örgüleri Ne...', ARRAY['Türk Edebiyatı','Şiir','Fırat Ülker']::text[], 8.5, '{"poet":"Fırat Ülker","poet_slug":"firat-ulker","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/mutant-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik', 'sensizlik-aydin-cevik-qvddl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sensizlik; 

gözlerinin okyanusunda yüzerken

habersiz yakalandığım bir tsunami.

sensizlik; 

dünün amansız sellerinden kaçarken

bir kaşık suda boğulmuşluğumun resmi.

sensizlik; 

yıldızlara aldanıp gecelere sığınırken

üstüme çöken bulutların zifiri demi

sensizlik; 

anılardan avuç avuç güneş toplarken

ansızın yüreğime düşen çöl iklimi

sensizlik; 

kırklı yaşların gün dökümü sürerken

beni dize dize öldüren şiirden mermi...

01.06.1993', 'sensizlik;  gözlerinin okyanusunda yüzerken habersiz yakalandığım bir tsunami. sensizlik;  dünün amansız sellerinden kaçarken bir kaşık suda...', ARRAY['Türk Edebiyatı','Şiir','Aydın Çevik']::text[], 8.5, '{"poet":"Aydın Çevik","poet_slug":"aydin-cevik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sensizlik-229-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Exıt', 'exit-firat-ulker-k8vc8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Herkesin bir uzayı vardır aslında

İçinde bi çok şey bulunur

Ama simsiyah

Kocaman bi boşluktur işte

Ve sonsuz sanılan bu boşluk

Karanlık bir odadır

Sonsuzluklara açılan kapıları vardır

Ben içimdeki

Dağınık,pis odamdan bi kapı seçtim

Diğer kapıların ardındakileri merak etmiyorum

Çünkü bundan daha güzel 

Bir çıkış olamaz..', 'Herkesin bir uzayı vardır aslında İçinde bi çok şey bulunur Ama simsiyah Kocaman bi boşluktur işte Ve sonsuz sanılan bu boşluk Karanlık bir ...', ARRAY['Türk Edebiyatı','Şiir','Fırat Ülker']::text[], 8.5, '{"poet":"Fırat Ülker","poet_slug":"firat-ulker","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/exit-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir dostla sanal muhabbet', 'bir-dostla-sanal-muhabbet-huseyin-dogan-1oc7u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '....Mavi  masallar yüklü 

Kanatlarımda.

Güven bana

Tut ellerimi

Korkma uçurumlardan

Aşkı vurgulayan  sözler yok değil

Aksanı bozuk

Telafuzu zor çoğunun. 

Cazibesine kapılınca ilham perisi

ne dediğini bilmez

Şarabın..! ! 

Ağzından dökülüverir

Olur olmaz bir zamanda Aradığın.

Aşk sopasıyla dayak yemektir

Bazısının işi gücü

Ahları dize, Vahları şiirdir.

Dillere destan bir türkü

Akıp giden bir ömür

Uzayıp giden bir sarhoştur

Bazen konu.

Aşktan kalan  artık

Yürekte kalan  harabe

Güzel günler zamanından iki çift sözdür 

Çogu zaman anlatılmaya çalışılan

Birincinin devamını buraya yazıyorum atışma serbest; 

Hatırı sayılır ikramda bulunur çoğu

Değerli konuğuna

Gönlünü hoş eder tatlı sözler fısıldar kulağına

Gitme  kal derler

Ama  gidicidir o.

Kalmaz periler gece yatısına

“Güllerle bezesen yatağını 

Aşk yemişleriyle çeşnilendirsen sofrasını”

Periler kanmaz büyülü sözlerine

Sihir zaten onun işidir.

Güzel bir masa ve mum ışığında

Kendi kendine yaptığın servistir

Bazen anlatılan

Anlatan da anlayan da anlam da sendir çoğu zaman.

Kanatlarından raptiyelenmiş 

Kelebek koleksiyonun kadar güzel

Ve bir o kadar cansızsa anıların.

Hatırlayamaz olduysan sayısını koleksiyonunu gören kadınların 

Susuvermişse yüreğine şarkı söyleyen deniz kızıları birden

Şaşkınsan şaşırmışsan korkma...! ! 

Yaşlanıyorsun.

Ey Adem..! ! ellinden sonra

Yıldızlararası  bir yolculuğa 

Eski  kırkbeşliklerin eşliğinde

Roketi bozuk 

Altmış dokuz model  şavrolenle çıkmışsan

Yolunun üzerinde rastlayacağın otostopçu kızları

Alamama riskini de göze almışsın demektir.

Böyle olursa da gerçekten üzülme...! ! 

Yaşlanıyorsun. 

Hem artık o kızlar insansız uzay araçlarıyla ilgileniyorlar

Saybır alemlere giden yollarda.....

Ciddiyeti ele al Hüseyin Bey dediğini duyar gibi oldum peki; 

3. şiir ve elveda...

Çiçekler sana ilham veriyorsa

Rüzgarlardan esinleniyorsa bacakların 

Her esişte, yazmaya başladıysan anılarını 

İnce hassas ve kırılgan olmuşsan

Şaşkınsan şaşırmıssan korkma..! ! 

Yaşlanıyorsun.

Kollarını açtıpta iki yana

İşte gökyüzü

Kanatlarımın genişliğindesin diyemiyorsan.

En uzak yıldıza Hey uçuş mesafemdesin deyip küçümseyemiyorsan

Şaşkınsan şaşırmışsan korkma...! ! 

Yaşlanıyorsun.

Oysa sapanımla dünyayı mutluluğa giden gökyüzüne

Mancınıkla ülkemin ilk uzay gemisini gönderecektim uzaya diyorsan

Yeni saçmalıklar düşünemiyor daha az hata yapıyorsan

Şaşkınsan bu halinden şaşırmıssan korkma..! ! 

Yaşlanıyorsun.

Bana tüm bunları anlatmışsın mektubunda

Anlatırken de biraz ağlamışsın

Ah Be biraderim yaşlanan bir tek sen misin..

Ölüm tabii ki gelecek bir gün kapımıza

Ben geldim dediğinde

Korkmadan  ben hazırım diyebilecek kadar daha

Yaşama şansımız var hala

Birbirinin devamıdır çoğu zaman yaşanılan

Nasıl devam edeceğini bir türlü kestiremediğin.

Bana diğer tarafı soruyorsun ya

Daha farklı olduğunu düşünmüyorum.

Orası da buranın devamıdır herhalde.

Biz orada da şiirleriz senle daha uzun

Hadi iyi bak sağlığına.', '....Mavi  masallar yüklü  Kanatlarımda. Güven bana Tut ellerimi Korkma uçurumlardan Aşkı vurgulayan  sözler yok değil Aksanı bozuk Telafuzu ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Doğan']::text[], 8.5, '{"poet":"Hüseyin Doğan","poet_slug":"huseyin-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":90,"source_url":"https://www.antoloji.com/bir-dostla-sanal-muhabbet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sen', 'bir-sen-aydin-cevik-n15am', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dünün aynalarından ayrı ayrı sırlandım

ıssız çöllerin nice serabında yıkandım

tersine akan mecnun nehirlere dadandım

bir sende rastladım o masum çocuk yüzüme 

yıldızsız gecelerde çaresiz oyalandım

en derin kuyularda suya hasret dolandım

güzlere yakalandım, kışlara kovalandım 

bir sen düştün aklıma, feri yitik gözüme

yağmuru bol illere sürgüne gönderildim 

kem gözlerin köşküne halı diye serildim

acılarım kök saldı yaban diye yerildim

bir seni yazdım gizlim saklım diye özüme

tütün yapraklarına koca bir ömrü sardım

dağlar ovalar aştım pek çok ummanlar yardım

derde derman aradım, kandım bu yaşa vardım

bir seni vuslat bildim mecbur oldum sözüme.

26.08.1993', 'Dünün aynalarından ayrı ayrı sırlandım ıssız çöllerin nice serabında yıkandım tersine akan mecnun nehirlere dadandım bir sende rastladım o m...', ARRAY['Türk Edebiyatı','Şiir','Aydın Çevik']::text[], 8.5, '{"poet":"Aydın Çevik","poet_slug":"aydin-cevik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bir-sen-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onüç Mayıs Günü', 'onuc-mayis-gunu-sinan-bilici-rf1lv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bakışlarındaki o ihanetin yüzüme vurduğunda 

Kaygıları beslerimde hep içimde 

Gülerken dediklerine de 

Tuhaf bir hal alır,susardım

Susmak bir ifade olurmu bilmem; ama ona hep susadım

İçerken bile,susarken gözlerinde 

Bana birşeyler olurdu

Artık çok rahat ağlayabilirdim 

Çünkü ona susayarak ağladığımda 

Öylece toprağa dökülürdü kendisi bir filizi andırırcasına 

Üşenip koparamazdım ki onu topraktan

Onun sevgisiyle hep filizi bekledim

Büyüdü

Ve beni benden etti

Bir onüç mayıs günü...', 'Bakışlarındaki o ihanetin yüzüme vurduğunda  Kaygıları beslerimde hep içimde  Gülerken dediklerine de  Tuhaf bir hal alır,susardım Susmak bi...', ARRAY['Türk Edebiyatı','Şiir','Sinan Bilici']::text[], 8.5, '{"poet":"Sinan Bilici","poet_slug":"sinan-bilici","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/onuc-mayis-gunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaderin Kırmızı Kartı', 'kaderin-kirmizi-karti-celal-topo-3vgeq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bütün yıldızlar döküldü gökyüzünden

Susmak üzere dinlediğim şarkılar

Bir karanlık geceye gömülmüş duygularım

Besteler yas ta ağlıyor notalar...

Tutarak iki yakasından

Yalnızlığa düğüm atıyorum

Kalabalıklara inat

Geçmişin kalıntılarını boyuyorum

Bir şarkının son nağmelerinde

Gözyaşlarımla...

Uzun yıllar sonrası avuçlarımda

Ayrılığın ıslaklığıdır saklanan

Ben şimdi

Kaderin kırmızı kart gösterdiği oyuncuyum

Mutluluğa hayatın kıyısından bakan...

14 / 12 / 2005  Antalya', 'Bütün yıldızlar döküldü gökyüzünden Susmak üzere dinlediğim şarkılar Bir karanlık geceye gömülmüş duygularım Besteler yas ta ağlıyor notalar...', ARRAY['Türk Edebiyatı','Şiir','Celal Topo']::text[], 8.5, '{"poet":"Celal Topo","poet_slug":"celal-topo","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kaderin-kirmizi-karti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkirciklere Ağ Atarlar', 'i-kirciklere-ag-atarlar-ercan-cengiz-mpn3g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İkirciklerin 

İştahı kabarıyor

Yem gelirken 

Orta yere.

İkircikler aç,

Kendinden uzakta, 

Yabancı

On adım 

Gerisindedir sözleri.

Yem 

Açlıkları 

Kendine çekiyor

Koştururlar

Şimdi 

Suyun 

Yüzündedirler

Yarış içinde...

Ağ atılır tümüne.

İnsanlaşmanın 

Korkusudur

Donuk gözlerde

Yüzleri ürpek

Ağa tutunurlar

Namussuzca.

Korkaklar, 

Kaçkınlar

Soysuzlaşmalar

O ağdadır.

Estetik işe yaramadı

Korkuluğa da

Yaranmadan 

Kuruyacaklar...

(Ezgilerde Kaldı Yüreğim 1.Kitap)', 'İkirciklerin  İştahı kabarıyor Yem gelirken  Orta yere. İkircikler aç, Kendinden uzakta,  Yabancı On adım  Gerisindedir sözleri. Yem  Açlıkl...', ARRAY['Türk Edebiyatı','Şiir','Ercan Cengiz']::text[], 8.5, '{"poet":"Ercan Cengiz","poet_slug":"ercan-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ikirciklere-ag-atarlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş ve Gerçek', 'dus-ve-gercek-aydin-cevik-uctz3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'alışılmadık duygular aldatır 

bazen kalplerimizi maskelerle

oysa 

en bilinen oyunudur aşkın, 

aşıklara körebe.

düşlerimiz, 

bazen kumral olur gecelerde

bazen de  sarışın, güneşte

gerçekler ise 

daima tek renklidir 

vaat edilmemiş 

toprakların renginde.

18.07.1993', 'alışılmadık duygular aldatır  bazen kalplerimizi maskelerle oysa  en bilinen oyunudur aşkın,  aşıklara körebe. düşlerimiz,  bazen kumral olu...', ARRAY['Türk Edebiyatı','Şiir','Aydın Çevik']::text[], 8.5, '{"poet":"Aydın Çevik","poet_slug":"aydin-cevik","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/dus-ve-gercek-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tüm dünyada Bir tek seni sevdim seni', 'tum-dunyada-bir-tek-seni-sevdim-seni-ridvan-cetin-3vpy4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Beni kandıramazsın ama

Kandıracak birini bulursun sen

Ne zaman ki aklına geldim

O zaman arasın beni

Belki yeni,belki de eski

Tüm dünyada bir tek seni sevdim seni', 'Beni kandıramazsın ama Kandıracak birini bulursun sen Ne zaman ki aklına geldim O zaman arasın beni Belki yeni,belki de eski Tüm dünyada bir...', ARRAY['Türk Edebiyatı','Şiir','Rıdvan Çetin']::text[], 8.5, '{"poet":"Rıdvan Çetin","poet_slug":"ridvan-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/tum-dunyada-bir-tek-seni-sevdim-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-aydin-cevik-brvy4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bazen aşklar

kendini ayrılıkta tamamlar

sevgilim...

ay ışığını yitirdiğimiz gecelerden 

varamadığımızda sabahlara

içimizdeki ıssızlığı doyuramadan

uyku tutturamadığımızda anılarımıza 

birbirimizden sakladığımız o sözcükler

sarmaşık olup dolanır boynumuza

ayrılık acısı sarar tüm benliğimizi

çeker bizi  kendi karanlıklarımıza

bir yanda, günlerden gecelerime miras yara

öteki yanda, küllerinden doğan bir anka 

dedim ya

bazen aşklar 

kendini ayrılıkta tamamlar 

sevgilim...

19.10.1995', 'bazen aşklar kendini ayrılıkta tamamlar sevgilim... ay ışığını yitirdiğimiz gecelerden  varamadığımızda sabahlara içimizdeki ıssızlığı doyur...', ARRAY['Türk Edebiyatı','Şiir','Aydın Çevik']::text[], 8.5, '{"poet":"Aydın Çevik","poet_slug":"aydin-cevik","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ayrilik-315-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlhan Kayalar''a', 'i-lhan-kayalar-a-hulusi-kilic-e8ghb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seninle ilk nerede karşılaşmıştık,nasıl tanışmıştık,

Sen ne yapıyordun,ben ne işler peşindeydim,

Sen neleri yaşamıştın,ben neler yaşamıştım

Ve neleri düşünüyorduk? 

Bunların hiç birini anımsamıyorum şimdi

Bildiğim; bir çok güzel anları paylaşmıştık...

Her zaman:

-Bir an önce evlen de sıra bize gelsin,derdin.

Oysa geçen yaz seni de evlendirdik.

O gün senin kadar ben de mutluydum; 

Söz verdiğim gibi,düğününe Kilis''e gelmiştim ya...

Daha onbeş gün önce yine birlikte değil miydik? 

Sen yine beni evlendirme planları yapıyor

Ve yine sabaha kadar 

Sevda anılarımı anlatıp,halime gülüyordun; gülüyorduk.

Sonra bizlere sarılıp gitmiştin:

Nasıl olsa tatil dönüşü görüşecektik...

Biraz önce arkadaşlar söyledi; 

İnanmadım,inanamadım! 

Şaka olmalıydı,öyle olması gerekirdi.

Ama Hayır! ! ! 

Bu kez de yine yapacağını yaptın,

Beni ve tüm sevenlerini...

Filiz''ini de bırakıp gittin İlhan! 

Sensizliği düşünmek,sensiz kalmak

İçime yumruk gibi oturdu.

Seni unutmayacağım kardeşim...', 'Seninle ilk nerede karşılaşmıştık,nasıl tanışmıştık, Sen ne yapıyordun,ben ne işler peşindeydim, Sen neleri yaşamıştın,ben neler yaşamıştım ...', ARRAY['Türk Edebiyatı','Şiir','Hulusi Kılıç']::text[], 8.5, '{"poet":"Hulusi Kılıç","poet_slug":"hulusi-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/ilhan-kayalar-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Sevme', 'cok-sevme-aydin-cevik-e1oo8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'eğer seversen bir gün 

çok sevme beni

böğürtlenleri değdirme dudaklarıma

arsız bir sarmaşık gibi 

dadanma sana vurgunluğuma

heyecanlı yakarışlarıma aldanıp 

sakın deli divaneyim sanma

beni her gördüğünde

vazgeç üzerimdekileri

yıkamaktan ütülemekten 

bırak dağınık kalayım 

sana ve hayata

gözyaşlarınla sınama duygularını

sakla başka yazların düşlerine

iç yakan bakışlarım 

aldatmasın seni

sen yalnızca boş bir sayfayı 

doldurduğunu farzet günlüğümde

uzun yaz gecelerinden 

vardığımızda 

güzün yaprak döken gerçeğine

hiç vakit kaybetmeden, 

kararlı ol ve çal kapımı 

havadan sudan konuş benimle 

acelen varmış gibi 

içeri girme kal eşikte 

sonra da

içimdekilere hiç dokunmadan 

veda edip

çek git uzaklara...

07.08.1993', 'eğer seversen bir gün  çok sevme beni böğürtlenleri değdirme dudaklarıma arsız bir sarmaşık gibi  dadanma sana vurgunluğuma heyecanlı yakarı...', ARRAY['Türk Edebiyatı','Şiir','Aydın Çevik']::text[], 8.5, '{"poet":"Aydın Çevik","poet_slug":"aydin-cevik","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/cok-sevme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zehir', 'zehir-firat-ulker-tcb8e', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sigarayı içersin

Önce ciğerlerine gider zehir

Sonra kalbin kanı dağıttığı gibi 

Dağıtır ücralarına

Sonunda zehir sen olursun

Ve bir gün

Kağıda sarılmış içiliyor olursun

Yanarak can verirsin

Ve bittiğinde

Kendi küllüğüne gömmüş olurlar seni

Üzerinde fahişe rujlar ve

Kokmuş pis nefesler kalır

Yandığına ağlarsın..', 'Sigarayı içersin Önce ciğerlerine gider zehir Sonra kalbin kanı dağıttığı gibi  Dağıtır ücralarına Sonunda zehir sen olursun Ve bir gün Kağı...', ARRAY['Türk Edebiyatı','Şiir','Fırat Ülker']::text[], 8.5, '{"poet":"Fırat Ülker","poet_slug":"firat-ulker","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/zehir-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Seviyor musun', 'beni-seviyor-musun-aydin-cevik-3nkgg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gözlerine her baktığımda

yükselir içimdeki saklı denizin suları

bana her dokunduğunda, sorarım sana

beni seviyor musun

tatlı bir gülüşünle yetinmişken

bir dizi mutluluk incileri bulsam da yüzünde

yine de  sorarım sana

beni seviyor musun

her yeri sarmışken koyu renkli bulutlar

ayrı düşmekten korkarım,

sorarım  sana üzerime düşen ilk damlada 

beni seviyor musun

şimdi dört mevsim yaşarken  seni

çıkarım deli divane olmanın zirvesine

seslenirim sana yerçekimsizliğimden

beni seviyor musun

30.01.1994', 'gözlerine her baktığımda yükselir içimdeki saklı denizin suları bana her dokunduğunda, sorarım sana beni seviyor musun tatlı bir gülüşünle y...', ARRAY['Türk Edebiyatı','Şiir','Aydın Çevik']::text[], 8.5, '{"poet":"Aydın Çevik","poet_slug":"aydin-cevik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/beni-seviyor-musun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merhaba', 'merhaba-sinan-bilici-d8oyb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Merhaba gözlerimin ilk duası

Kelimelerimin sesi,sözcüklerimin soluğu

Kuytu odada ilk sevişmişliğim

Merhaba...

İçimi ısıtan şey

Dualarımdan dökülen beddualarım

Merhaba

Nasıl bakmamı istersin gözlerine 

Rüyalarımın azabı,nefesimin ilk kesilişi

Adını andıkça ilk nefretim

Solgun yüzümdeki ilk gülüşüm

Mısralarımın sahibi 

Merhaba sana', 'Merhaba gözlerimin ilk duası Kelimelerimin sesi,sözcüklerimin soluğu Kuytu odada ilk sevişmişliğim Merhaba... İçimi ısıtan şey Dualarımdan d...', ARRAY['Türk Edebiyatı','Şiir','Sinan Bilici']::text[], 8.5, '{"poet":"Sinan Bilici","poet_slug":"sinan-bilici","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/merhaba-135-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya', 'ruya-firat-ulker-x9qca', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gökyüzü güneş olsa 

Sensiz karanlıktayım

Gözümün önünden

Bir an olsun gitmiyorsun

Zaten ben seninle 

En güzel rüyadayım

Ne bu rüyada uyurum

Ne de bu rüyadan uyanırım..', 'Gökyüzü güneş olsa  Sensiz karanlıktayım Gözümün önünden Bir an olsun gitmiyorsun Zaten ben seninle  En güzel rüyadayım Ne bu rüyada uyurum ...', ARRAY['Türk Edebiyatı','Şiir','Fırat Ülker']::text[], 8.5, '{"poet":"Fırat Ülker","poet_slug":"firat-ulker","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ruya-222-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık Defterinden', 'yalnizlik-defterinden-aydin-cevik-1jpdy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ne zaman yumsa gözlerini

yalnızlığın baykuşu

kış tutsaklığından kurtulur

yazı bekleyen düşlerimiz

dudaklardan dökülenlerle 

yaşarız şelale coşkusu

sularımıza belki bir gül

düşer diye bekleriz...

24.06.1993', 'ne zaman yumsa gözlerini yalnızlığın baykuşu kış tutsaklığından kurtulur yazı bekleyen düşlerimiz dudaklardan dökülenlerle  yaşarız şelale c...', ARRAY['Türk Edebiyatı','Şiir','Aydın Çevik']::text[], 8.5, '{"poet":"Aydın Çevik","poet_slug":"aydin-cevik","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yalnizlik-defterinden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Solunum', 'solunum-firat-ulker-lur64', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sigarayı bıraktım

Dudak tiryakisi oldum

Seninle öpüşürken

Nefes almasam da

Ciğerlerime oksijen

İçime yaşama sevinci doluyor

Sanırım artık 

Dudak solunumu yapıyorum..', 'Sigarayı bıraktım Dudak tiryakisi oldum Seninle öpüşürken Nefes almasam da Ciğerlerime oksijen İçime yaşama sevinci doluyor Sanırım artık  D...', ARRAY['Türk Edebiyatı','Şiir','Fırat Ülker']::text[], 8.5, '{"poet":"Fırat Ülker","poet_slug":"firat-ulker","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/solunum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Melankoli', 'melankoli-aydin-cevik-gol8s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ey bedeni ölü, ruhu diri tutmanın nedeni

bırak ta kapansın perdeleri gençliğimin

seslen bana, iç ıslatan kara bulutlardan

Yaz sona erdi artık güze girdin diye

herşeyi yalın görmenin o acı tadını

bozgunlardan miras bırakırken yüzüme

ödünç verdiğin sevişmeleri de al geriye

kabuslarla beslensin yalnızlığım diye

beni terk ettiğin sıradanlığın girdabı 

yutarken tüm serüven arzulu gemilerimi

bir şiir yaz ardımdan,başlığı benden olan

denizin bittiği yerden çöl başlar diye

yasak bir aşka sobelenmenin utancı

günler kısaltıp geceleri uzatırken içimde

o vefasız dudaklar söylesin gerçeği 

seni hiç sevmedim hepsi bir oyundu diye.

10.06.2005', 'ey bedeni ölü, ruhu diri tutmanın nedeni bırak ta kapansın perdeleri gençliğimin seslen bana, iç ıslatan kara bulutlardan Yaz sona erdi artı...', ARRAY['Türk Edebiyatı','Şiir','Aydın Çevik']::text[], 8.5, '{"poet":"Aydın Çevik","poet_slug":"aydin-cevik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/melankoli-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Gözümle', 'benim-gozumle-muhammed-mehmet-gul-rsl6h', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Vaktiyle sana

Gözümde Meryemsin diyordum

Oysa şimdi

Hakaret mi ediyordum Meryeme diyorum.', 'Vaktiyle sana Gözümde Meryemsin diyordum Oysa şimdi Hakaret mi ediyordum Meryeme diyorum....', ARRAY['Türk Edebiyatı','Şiir','Muhammed Mehmet Gül']::text[], 8.5, '{"poet":"Muhammed Mehmet Gül","poet_slug":"muhammed-mehmet-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/benim-gozumle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nem', 'nem-firat-ulker-bai0d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gökyüzü ağlarsa yağmur

İnsan ağlarsa yaş olur

Ve yaralı kalpler ağlarsa kan

Baktığımız yer mi

Yoksa bakışlarımız mıdır ıslak

Bilemez 

Bir gram nemde boğuluruz..', 'Gökyüzü ağlarsa yağmur İnsan ağlarsa yaş olur Ve yaralı kalpler ağlarsa kan Baktığımız yer mi Yoksa bakışlarımız mıdır ıslak Bilemez  Bir gr...', ARRAY['Türk Edebiyatı','Şiir','Fırat Ülker']::text[], 8.5, '{"poet":"Fırat Ülker","poet_slug":"firat-ulker","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/nem-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sona Vardım', 'sona-vardim-aydin-cevik-a7bgo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir zamanlar

yarındım...

düşlerim büyüttü beni

bugüne uyandım 

açar açmaz büyüledin gözlerimi

aşkınla aydınlandım

yok saydım ayı, küçümsedim güneşi

aşkınla yazdım

beni taşıyan sende yaşayan şiirleri

ne zaman ki sensizliğe yakalandım

yüreğimde isyan çıkardı aşk yemini

kağıttan gemilerde denize bırakıldım

ruhumla birlikte terk ettiğinde bedenimi

bildim ki sana değil sona vardım...

17.07.1995', 'bir zamanlar yarındım... düşlerim büyüttü beni bugüne uyandım  açar açmaz büyüledin gözlerimi aşkınla aydınlandım yok saydım ayı, küçümsedim...', ARRAY['Türk Edebiyatı','Şiir','Aydın Çevik']::text[], 8.5, '{"poet":"Aydın Çevik","poet_slug":"aydin-cevik","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sona-vardim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yok muyum ne! ?', 'yok-muyum-ne-firat-ulker-rj9f4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tüm bu

Somutlukların içinde

Bir ben miyim soyut

Tüm bu

Belirginliğin içinde

Bir ben mi belirsiz,kimliksiz

Galiba gölgem de yok benim

Ben kimim,neyim

Bilemiyorum..', 'Tüm bu Somutlukların içinde Bir ben miyim soyut Tüm bu Belirginliğin içinde Bir ben mi belirsiz,kimliksiz Galiba gölgem de yok benim Ben kim...', ARRAY['Türk Edebiyatı','Şiir','Fırat Ülker']::text[], 8.5, '{"poet":"Fırat Ülker","poet_slug":"firat-ulker","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yok-muyum-ne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Yüzden', 'bu-yuzden-aydin-cevik-jp0t0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'olmazlığına vuruldum 

ben senin...

kardelenini koruyan

zirveler gibi

yaklaşılmazlığına...

akdenizin

saklı atlantisi  misali

ulaşılmazlığına...

içimde 

damlaya damlaya

göl olmana aldırmadım

bu yüzden...

hercailiğine tutuldum

ben senin

bir bakışınla 

yazıma güz düşüren 

fermanına

gecelerime

uykuyu haram  yapan

umarsızlığına

içimde 

denizinin çağırdığı ırmaklar gibi

çağlamana ses çıkarmadım

bu yüzden...

21.07.2005', 'olmazlığına vuruldum  ben senin... kardelenini koruyan zirveler gibi yaklaşılmazlığına... akdenizin saklı atlantisi  misali ulaşılmazlığına....', ARRAY['Türk Edebiyatı','Şiir','Aydın Çevik']::text[], 8.5, '{"poet":"Aydın Çevik","poet_slug":"aydin-cevik","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bu-yuzden-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutukluyum Şu an', 'tutukluyum-su-an-i-sa-tekin-act85', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kalbime girmişsin

Tüm damarlarımda

Filizlenmiş sevdan

Beynimdesin her an

Yüreğimi hapsettin

Tutukluyum şu an', 'Kalbime girmişsin Tüm damarlarımda Filizlenmiş sevdan Beynimdesin her an Yüreğimi hapsettin Tutukluyum şu an...', ARRAY['Türk Edebiyatı','Şiir','İsa Tekin']::text[], 8.5, '{"poet":"İsa Tekin","poet_slug":"i-sa-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/tutukluyum-su-an-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen ve Ben', 'sen-ve-ben-aydin-cevik-sylot', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sen el değmemişliğin ipek kervanı

üzerinde dolaşılmamış zenginlik coğrafyası...

ben ise  talan edilmişliğin binbir gece masalı

her köşesi örümcek ağlı yalnızlıklar sokağı...

sen nasıl  olsa vazgeçersin bir gün yalnızlıktan

en güzeli paylaşmaktır diye kaçmaktan...

ya  ben nasıl kurtulup ta varırım sana

geçmişin acımasız akrep ve yelkovanlarından...

21.07.1994', 'sen el değmemişliğin ipek kervanı üzerinde dolaşılmamış zenginlik coğrafyası... ben ise  talan edilmişliğin binbir gece masalı her köşesi ör...', ARRAY['Türk Edebiyatı','Şiir','Aydın Çevik']::text[], 8.5, '{"poet":"Aydın Çevik","poet_slug":"aydin-cevik","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sen-ve-ben-157-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esmer Adam', 'esmer-adam-i-sa-tekin-ttst9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '..........Sürgün

.....................Dipçik

...............................İskân

.......................................Talan

...............................................Köle

......................................................Zincir

Beyaza itaat

İşte  esmer adam', '..........Sürgün .....................Dipçik ...............................İskân .......................................Talan ................', ARRAY['Türk Edebiyatı','Şiir','İsa Tekin']::text[], 8.5, '{"poet":"İsa Tekin","poet_slug":"i-sa-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/esmer-adam-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaz Bittiğinde', 'yaz-bittiginde-aydin-cevik-en8ud', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bir yanda 

kendinde kendini görebilmenin renksizliği

diğer yanda 

toz pembe sözcüklerin dudaklardan dökülme ayini

besbelli 

vuruyor bizi de kıyılara

erken zaman gelgitleri

yüreklerimiz sen ve ben kavgasında

kırılganken şimdi

başka düşlerden varılan sabahlar da

ısıtmıyor artık içimizi

ben yine de söyleyemem sana

yaz bittiğinde güzün geleceğini

sen de söyleme sakın bana

elinde bir gülle geri döneceğini...

22.08.1995', 'bir yanda  kendinde kendini görebilmenin renksizliği diğer yanda  toz pembe sözcüklerin dudaklardan dökülme ayini besbelli  vuruyor bizi de ...', ARRAY['Türk Edebiyatı','Şiir','Aydın Çevik']::text[], 8.5, '{"poet":"Aydın Çevik","poet_slug":"aydin-cevik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yaz-bittiginde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Davet', 'davet-aydin-cevik-18hy6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'gel,

geçmişi bırakalım 

rengi soluk resimleriyle baş başa

isteyen bir kara kutu arasın

kendi enkazının altında          

gel,

yarım kalmış şiirleri

tamamlayalım dudaklarımızla

gözlerimizin ferleri tutuşsun yeniden

ilk günlerdekini  kıskandırırcasına

gel,

artık kaçmayalım yaz yağmurundan 

ele versin birbirimizden sakladıklarımızı

kenetlensin ellerimiz

sevdamızın gökkuşağı altında

gel,

değişken ruh mevsimlerine

yakalanmadan gidelim buralardan

bizden çalınmış günlerden varalım

görkemli aşk diyarına.

13.09.1993', 'gel, geçmişi bırakalım  rengi soluk resimleriyle baş başa isteyen bir kara kutu arasın kendi enkazının altında           gel, yarım kalmış ş...', ARRAY['Türk Edebiyatı','Şiir','Aydın Çevik']::text[], 8.5, '{"poet":"Aydın Çevik","poet_slug":"aydin-cevik","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/davet-61-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz', 'biz-firat-ulker-im1be', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yola üç kişi çıktık

Sen,ben ve biz

Şimdi sonsuza kadar

Biz''i yaşatacağız

Sen ve ben öldü

Hafızamızdan silindi

Yeni bir diliz artık

Yeni bir Türkçe

Birinci tekil,ikinci tekil yok

Alfabemizin ilk ve son harfi sonsuzluk

Homojen bir çözeltiyiz artık

Dipsizliğe akıyoruz

Üzerimizden buharlaşanlar

Sadece yaşadığımız

Olumsuzluklar olacak,geriye

Kristallenmiş mutluluklarımız kalacak

Arada bunları dengeleyen varlığımız

İzole bir sistemiz artık

Madde ve enerjiye kapalı

Biz artık biz oldu

Sen bilinmezdin

Ben bilinmez

Ve iki soru işareti birleşti

Biz oldu

Kalp oldu..', 'Yola üç kişi çıktık Sen,ben ve biz Şimdi sonsuza kadar Biz''i yaşatacağız Sen ve ben öldü Hafızamızdan silindi Yeni bir diliz artık Yeni bir ...', ARRAY['Türk Edebiyatı','Şiir','Fırat Ülker']::text[], 8.5, '{"poet":"Fırat Ülker","poet_slug":"firat-ulker","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/biz-95-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-aydin-cevik-5qfag', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kimine 

çorak toprakların nilüfer çiçeğidir 

aşk

kimine ise 

ölümcül deniz kızı efsanesi...

aşk

bazen

uzun nisan yağmurlarının ardından

gökkuşağı gibi doğar üzerimize... 

bazen de

yaşdönümü mevsiminin coşkun sellerinde 

tutunacağımız bir dal olur bizlere...

12.06.1993', 'kimine  çorak toprakların nilüfer çiçeğidir  aşk kimine ise  ölümcül deniz kızı efsanesi... aşk bazen uzun nisan yağmurlarının ardından gökk...', ARRAY['Türk Edebiyatı','Şiir','Aydın Çevik']::text[], 8.5, '{"poet":"Aydın Çevik","poet_slug":"aydin-cevik","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ask-497-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vazgeçmek', 'vazgecmek-bayram-cerit-ugz3y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'VAZGEÇMEK

Bugünlerde bir başka çarpıyor yüreğim.

yaşamım yüreğimin hızına tetişemezken 

beynim okyanuslar aşıyor.

yeni kıtalar keşfediyor.

ırmaklarım herp sana koşar,

sadece seni özler.

ve herp seni arar bulur.

sen bir mamçsan benim için, 

dağlar yollar engel değil bana

bu gece bir başka parlıyor gökyüzü

bir başka sarılmış ay yıldızlara

yatağımda ayrı bir huzur var

bu sabah güneş bir başka doğacak

saati aynı.

yeri aynı doğu.

ama benim yüreğime doğacak bu sabah güneş.

yıllardır tatmadığım hisleri 

hep merak eder dururdum.

bakardım; göremezdim,

duyar; anlamazdım.

adına aşk dedikleri tutkuyu artık keşfettim.

ve son noktayı koydum.

''aşk bir çift göz dışında 

herşeyden vazgeçmeyi bilmektir.

BAYRAM CERİT

21.05.2003

YOZGAT', 'VAZGEÇMEK Bugünlerde bir başka çarpıyor yüreğim. yaşamım yüreğimin hızına tetişemezken  beynim okyanuslar aşıyor. yeni kıtalar keşfediyor. ı...', ARRAY['Türk Edebiyatı','Şiir','Bayram Cerit']::text[], 8.5, '{"poet":"Bayram Cerit","poet_slug":"bayram-cerit","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/vazgecmek-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dün, Pişmanlık ve Hüzün', 'dun-pismanlik-ve-huzun-aydin-cevik-hsrkx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'masamda mektupların var

başlayalım diyen kaldığımız yerden...

oysa bir zamanlar

günlerimize geceler inmez iken	

sert bir rüzgardı 

belki de kara bir tren	

bölüşemeden gözlerimizde anıları

seni benden alıp götüren...

şimdi

ne zaman dönüp baksam geriye

sensizlik denizinde

alabora oluşum gelir aklıma…

iç yangınları yıllar sürer

derdin

yeniler kendini aşk yıllar içinde...

ah bir bilsen...

gidişinle beni kaç kez öldürdün sen...

satırlarında; 

saatinin durduğunu yazmışsın

dönüş yolundayken.

özledim hep yolunu gözledim diyorsun

dem vuruyorsun bitmeyen sevginden.

dökülen onca yapraktan sonra

çöle dönen onca topraktan sonra…

vazgeç artık sende

dün, dün kalsın bugüne

arama bende kendini boşuna

sanma ki ben de kök saldın

gitse de gitmese de hoşuna

ben çıktım rüyamdan sen rüya kaldın...

20.05.1993', 'masamda mektupların var başlayalım diyen kaldığımız yerden... oysa bir zamanlar günlerimize geceler inmez iken	 sert bir rüzgardı  belki de ...', ARRAY['Türk Edebiyatı','Şiir','Aydın Çevik']::text[], 8.5, '{"poet":"Aydın Çevik","poet_slug":"aydin-cevik","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/dun-pismanlik-ve-huzun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seçtim', 'sectim-firat-ulker-8zpzb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Allah insanları

Eşlerini

Kendi türlerinden seçmeleri

Ve soylarını 

Devam ettirmeleri için yaratmıştır

Ama benim yine 

Asiliğim tuttu

Eşimi 

Meleklerden seçtim..', 'Allah insanları Eşlerini Kendi türlerinden seçmeleri Ve soylarını  Devam ettirmeleri için yaratmıştır Ama benim yine  Asiliğim tuttu Eşimi  ...', ARRAY['Türk Edebiyatı','Şiir','Fırat Ülker']::text[], 8.5, '{"poet":"Fırat Ülker","poet_slug":"firat-ulker","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sectim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aklımdasın', 'aklimdasin-bayram-cerit-f4uw9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'AKLIMDASIN

Benim aklımda yalnız sen varsın.

Anılarımda, düşlerimde gözlerin gizli.

Bir fincan kahvenin kırk yılhatırı vardır derler.

Ben ise bir çift kahve göze

Bir ömür feda etmeye hazırım.

Hazırkıta seni özlüyorum,

Şafaklarımı sayarken.

Dakikalar geçmiyor sensiz.

Gözlerine bakmadan,

Ellerini okşamadan.

Saatlerin adı bile yok.

Saniyeleri tutamıyorum.

Nefesini hissettiğim bakışlarda.

Sen varsan benim ruhum senindir.

Ruhuna sahip olmaktır.

Düşlerinin kahramanı olmak,

Her anına yerleşmek,

Sadece benim güzel bir hülyam.

Unutmak yok,

Unutulmak yok,

Sayfaları tozlu lugatımda.

Sen de çıkar bu iki kelimeyi.

Öznenin gizli ben olduğu satırladan.

Beni özlemek yok,

Özlemin adı yok.

Hayat denen bu aşk savaşlarında.

Sadece anılara ve güzel düşlere yer var

Benim küçük yüreğimde.

BAYRAM CERİT	

30.08.2003

DENİZLİ', 'AKLIMDASIN Benim aklımda yalnız sen varsın. Anılarımda, düşlerimde gözlerin gizli. Bir fincan kahvenin kırk yılhatırı vardır derler. Ben ise...', ARRAY['Türk Edebiyatı','Şiir','Bayram Cerit']::text[], 8.5, '{"poet":"Bayram Cerit","poet_slug":"bayram-cerit","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/aklimdasin-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türk Filmi Rüyası', 'turk-filmi-ruyasi-bayram-cerit-m6cqx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ey düşlerimi süsleyen süs biberim.

Yine rüyalarımın senaryosu kaybedilmiş,

Başrol OYuncusu sensin.

filmin ne senaristi belli,

ne başı ne de mutlu sonu.

belli olan iki şey var.

esas kız sensin,

rüya da benim olduğu için 

esas oğlan tabi ki benim.

rüyayı mutlu yerinden görüyorum.

iyi de devam ediyor.

ama bu bir türk filmi rüyası ya

elbette bir erol taş,

bir aliye rona  olmalıydı.

kötülük yapacak,

bize zarar verecek.

tabi ki bir de filme heyecan  katacak.

hasılat rekoru kırmasa da 

beni rüyamda ağlatacaktı 

bu karaktersiz karakter oyuncuları.

nitekim.

amaçlarına da ulaşıyorlar.

ben zevkine oynuyorum.

para kazanmıyorum.

amaçlarına da ulaşıyorlar.

hüzünle ağlıyorum.

ağlayarak uyanıyorum.

ve yine sensiz bir sabaha uyanıyorum. 

sensiz bir tanyerine ağarıyorum.

BAYRAM CERİT	

20.08.2003

DENİZLİ', 'Ey düşlerimi süsleyen süs biberim. Yine rüyalarımın senaryosu kaybedilmiş, Başrol OYuncusu sensin. filmin ne senaristi belli, ne başı ne de ...', ARRAY['Türk Edebiyatı','Şiir','Bayram Cerit']::text[], 8.5, '{"poet":"Bayram Cerit","poet_slug":"bayram-cerit","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/turk-filmi-ruyasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz İnsanlar', 'biz-i-nsanlar-aydin-cevik-x6tpb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'biz insanlar hayatı hesapsızca  yaşarız

hep gönlü yakın bulur aklımızdan şaşarız

derler ki zıt mizaçlar birbirlerini iter 

bir özlemdir oysa bu kavuşulunca biter

güçlüyüzdür ne kalpler, kaleler fethederiz

gün gelir geçer heves gizlice terk ederiz

söz gümüş ise sükut altındır deriz sözde

haklıdır çığırtkanlar diye biliriz özde

kaybedeni avutur yalandan alkışlarız

kazananı soğutur üstün sayıp dışlarız

en güzel giysileri vitrinlerden seçeriz

moda değil denince giymekten vazgeçeriz

aşık olur her yere sevdamızı yazarız

aslı bizdedir deyip mezarını kazarız

yeriz, içeriz yaz kış düşünmeden yoksulu

Tanrının yokmuş gibi başka sevgili kulu

ikilemler çoğalır değişmez hikayeler

isyan bitmez kadere gizliyse de gayeler! ...

08.06.1993', 'biz insanlar hayatı hesapsızca  yaşarız hep gönlü yakın bulur aklımızdan şaşarız derler ki zıt mizaçlar birbirlerini iter  bir özlemdir oysa...', ARRAY['Türk Edebiyatı','Şiir','Aydın Çevik']::text[], 8.5, '{"poet":"Aydın Çevik","poet_slug":"aydin-cevik","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/biz-insanlar-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm Öpücüğü', 'olum-opucugu-firat-ulker-k7mie', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Köy kokar uzaklar

Saçına değip

Gelince rüzgar

Esintili bir akşam üstüdür

İçimi gıcıklar

Sensizlik işte

Hasretlerimi sarmaladım birbirine

Kocaman ipim oldu kocaman

Bi ucunu hilale bağladım

Diğer ucunu boynuma doladım

Son arzum minik bir buseydi

Olmadı..

Neyse serabı da yetti be güzelim

Artık ölebilirim

Ağzından çıktı ya ayrılık

Ben aslında orda öldüm

Bi de senin için öleyim istedim

Gökyüzüne yazmışsın ya yıldızlarla

Bitti diye

Şimdi ona bakıyorum

İdam sehpam dudaklarında

Son nefesimi veriyorum

Mucuk aşkım mucuk..', 'Köy kokar uzaklar Saçına değip Gelince rüzgar Esintili bir akşam üstüdür İçimi gıcıklar Sensizlik işte Hasretlerimi sarmaladım birbirine Koc...', ARRAY['Türk Edebiyatı','Şiir','Fırat Ülker']::text[], 8.5, '{"poet":"Fırat Ülker","poet_slug":"firat-ulker","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/olum-opucugu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Açelya', 'acelya-muhammed-mehmet-gul-37lyv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Köprülerin atıldığı dar vakitti

Her yer işgal altında 

Yalnız açelya kurtarılmış bölgeydi

Haricinde ki herşey artık,herşey gölgeydi

Şimdi ilişmesin bana kimse 

Gözümde saralıdır, gözümde acuze herkes

Kırıldı imame

Tutuştu pervane

Şimdi,

Alnımın ortasına kabartma harflerle yazıldı kaderim

Artık

.......Aç

.............El

..................Ya

.......................Hu', 'Köprülerin atıldığı dar vakitti Her yer işgal altında  Yalnız açelya kurtarılmış bölgeydi Haricinde ki herşey artık,herşey gölgeydi Şimdi il...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Mehmet Gül']::text[], 8.5, '{"poet":"Muhammed Mehmet Gül","poet_slug":"muhammed-mehmet-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/acelya-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zeynep’e', 'zeynep-e-aydin-cevik-h5jo2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'z aman akmıyor artık sensiz akreplerle yelkovanlarla

e n dokunaklı şiirlerimi yazdım, sensiz günbatımlarında

y alnız ismini fısıldıyor yaz meltemleri kulağıma

n asıl neden niçin diye sorma,yanıyorum aşkınla

e ngin duygularım çıktı soylu bekleyişinden,coşmakta

p ek yalnızdım,şimdiyse tüm gemileri yaktım uğruna.

25.05.1994', 'z aman akmıyor artık sensiz akreplerle yelkovanlarla e n dokunaklı şiirlerimi yazdım, sensiz günbatımlarında y alnız ismini fısıldıyor yaz m...', ARRAY['Türk Edebiyatı','Şiir','Aydın Çevik']::text[], 8.5, '{"poet":"Aydın Çevik","poet_slug":"aydin-cevik","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/zeynep-e-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ucum', 'ucum-firat-ulker-6hvgp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Damarlarımın 

Son bulduğu

Yerler olmalısın

Aşk duygusuyla

Dolu kalbimin

Pompaladığı kanı

Her saniye 

Alabilmek için..', 'Damarlarımın  Son bulduğu Yerler olmalısın Aşk duygusuyla Dolu kalbimin Pompaladığı kanı Her saniye  Alabilmek için.....', ARRAY['Türk Edebiyatı','Şiir','Fırat Ülker']::text[], 8.5, '{"poet":"Fırat Ülker","poet_slug":"firat-ulker","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ucum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varsın Dediğin Olsun!', 'varsin-dedigin-olsun-aydin-cevik-kl0wj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bir tomurcuk gibisin her gün gönlümde açan

bulutlarına vurgun yağmurla neşe saçan

akşam çökünce korkup düşen çiylerden kaçan

canımsın cananımsın, varsın dediğin olsun! 

dağlarıma yağan kar; üzerimi örtensin

düşlerimden kopan çığ; nefesimi kesensin

doğan kış güneşiyle  ilk eriyip gidensin 

özümde yananımsın, varsın dediğin olsun! 

dört mevsim rüzgârımsın,diyar diyar gezersin

ya adımı fısıldar ya resmimi çizersin

sonra da esmez olur, cilve yapar üzersin

en masum yalanımsın, varsın dediğin olsun! 

her gidişinle başlar, onmaz dert bitmez keder

döktüğüm gözyaşlarım  saymadım kaç göl eder

yeter mi sana ömrüm bilmem kaderim ne der

geriye kalanımsın, varsın dediğin olsun! 

15.08.1993 (R)    11.11.2006', 'bir tomurcuk gibisin her gün gönlümde açan bulutlarına vurgun yağmurla neşe saçan akşam çökünce korkup düşen çiylerden kaçan canımsın cananı...', ARRAY['Türk Edebiyatı','Şiir','Aydın Çevik']::text[], 8.5, '{"poet":"Aydın Çevik","poet_slug":"aydin-cevik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/varsin-dedigin-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdiğimsin', 'sevdigimsin-i-sa-tekin-guacl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Teslim oldum bu aşka

Tüm varlığımla

Sen yaşam kaynağım

Sen hayatın ta kendisi

Sevdiğimsin

Damarlarımdaki kan

Soluduğum hava

İçtiğim su

Yaşam pınarımsın

Sevdiğimsin', 'Teslim oldum bu aşka Tüm varlığımla Sen yaşam kaynağım Sen hayatın ta kendisi Sevdiğimsin Damarlarımdaki kan Soluduğum hava İçtiğim su Yaşam...', ARRAY['Türk Edebiyatı','Şiir','İsa Tekin']::text[], 8.5, '{"poet":"İsa Tekin","poet_slug":"i-sa-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sevdigimsin-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söz Verdim', 'soz-verdim-aydin-cevik-p1m3d', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'üzdüm mü seni

çok mu ağlattım

giderken uzaklara

neleri aldım senden

neleri bıraktım ardım da

düşünmeliyim yeniden 

nasıl yenik düştüm gururuma

seni çılgınca severken

niçin kapıldım

öfke bulutlarının sel sularına

sormalıyım kalbime

ne oldu neden oldu 

acaba yeterince

vurgulayamadım mı seni mısralarım da 

beni küle çeviren o iç yangınımı,

havale geçirten en ateşli hastalığımı

iyi yazamadım mı yoksa dağa taşa kumlara

şimdi anladım ki

eskisinden de çok seviyormuşum seni

terk edip de giden ben değilmişim gibi 

devam etmeliyim kaldığım yerden

seni bende beni sende yaşatan nedeni 

çekmeliyim içime tükenmeden

bilmelisin ki

bu kez kararlıyım 

söz verdim kendime

günlerimi gecelerimi katmayı ömrüne.

05.07.2005', 'üzdüm mü seni çok mu ağlattım giderken uzaklara neleri aldım senden neleri bıraktım ardım da düşünmeliyim yeniden  nasıl yenik düştüm gururu...', ARRAY['Türk Edebiyatı','Şiir','Aydın Çevik']::text[], 8.5, '{"poet":"Aydın Çevik","poet_slug":"aydin-cevik","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/soz-verdim-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Nöbeti', 'ask-nobeti-aydin-cevik-3eg7k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'tamam 

nasıl istersen sevgilim

vazgeçtim bende artık

gözlerim de aramazsa seni

biter belki şu içimdeki

kendime yabancılık

o kadar kırdın ki beni

bir gün gelir de bir yerde, 

başlar mıyız yeniden 

diye geçirsem de aklımdan 

söyleyemezdim asla,

çünkü sen “biz bu aşkla,

geçmişteki yarımlarımızı tamamladık

en olmazlardan kendimize yol yaptık 

ama hepsi de bir düştü sonunda uyandık

çok kalabalığız ikimiz, tek çare yalnızlık”

demiştin hatırlasana...

tamam

nasıl istersen bir tanem

alıştım sensizliğe artık

sona erdi, bendeki yerçekimine aykırılık

dudaklarım da anmazsa  adını, 

durur belki zaman

acıtmaz içimi, duyduğum her çığlık

son kez geldiğimizde göz göze,

sorumu yanıtlayabilseydin keşke

tam sevmeyi öğrendik derken birbirimize

neden biriktirdiğin o yılların kiniyle,

süpürmüştün ne kaldıysa bizden geriye 

ya çok sevmiştin beni ya da acıdığından

ardında  bırakıp ta gittiğin tek şeydi

geceli gündüzlü bir aşkın nöbeti...

11.07.2005', 'tamam  nasıl istersen sevgilim vazgeçtim bende artık gözlerim de aramazsa seni biter belki şu içimdeki kendime yabancılık o kadar kırdın ki ...', ARRAY['Türk Edebiyatı','Şiir','Aydın Çevik']::text[], 8.5, '{"poet":"Aydın Çevik","poet_slug":"aydin-cevik","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ask-nobeti-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşüncenin Körlüğü Dilendirir', 'dusuncenin-korlugu-dilendirir-ercan-cengiz-prw05', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Düşüncenin körlüğü 

Besmele okutur 

Karanlığa

Dilendirir.

Boş gözlerle 

Bakındırır

Burnunun tepesinden

Bir yanının felcidir.

Beynindeki

Kurt kemiriğidir

Karanlığın,

Korkuya eğilir mi dilin

Ve de elin

Üç kuruşa satarsa emeğini 

Tüccarlara

Ucuzca bir yaşam içinde

Gerçekliğinden uzaklara 

Düşersin...

Düşüncenin körlüğü 

İnsanı savurur

Aşktan, 

Topraktan edercesine

Ve de kendinin 

Olamayacak kadar

Boş bir esintide,

Ömür tüketir...

Boş gözlerde 

Düşünce körlüğü

Bakındırırsa eğer

Bir ışık,

Bir kıvılcım

Ancak yol boyu

Göbeğinden 

Yarıyorsa karanlığı

Benliğine

Alamayacak kadar da 

Derin

Silkelenmelerle

Üzerinden dökülür...

(Ezgilerde Kaldı Yüreğim 1.Kitap)', 'Düşüncenin körlüğü  Besmele okutur  Karanlığa Dilendirir. Boş gözlerle  Bakındırır Burnunun tepesinden Bir yanının felcidir. Beynindeki Kurt...', ARRAY['Türk Edebiyatı','Şiir','Ercan Cengiz']::text[], 8.5, '{"poet":"Ercan Cengiz","poet_slug":"ercan-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/dusuncenin-korlugu-dilendirir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretin Aktörü', 'hasretin-aktoru-firat-ulker-xu3pl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yağmur damlaları

Kara çaldığında

Ben buzulları oynuyordum

Kasım geceleri

Sen yokluğunda

Ve bir elips film setinin 

Tam ortasında

Dublörüm yok benim

Hasretimi,yaşayarak oynuyorum

Repliğe gerek yok

Oynayarak ezberliyorum

Senaristim

Bana gelmeme zamanların

Senaryom 

Sen gelene kadar

Başladım ve ben

Önce çığlarımı dökeceğim eteklerimden

Sonra magma benden patlayacak

Kayalaşacağım

Tuzlarımı alacaklar

Yemeklerine katacaklar

Çakıllarımı alacaklar

Sersem başımda paralayacaklar

Kumlarımı alıp

Tepeme bilmem kaç kat çıkacaklar

Sonra küçük bir elektrik kesintisi

Sigortalarım atacak

Ve gözyaşlarında

Kısa devre olacağım

Kekremin dudaklarımı çatlatacak

Ben sade sana kalacağım..', 'Yağmur damlaları Kara çaldığında Ben buzulları oynuyordum Kasım geceleri Sen yokluğunda Ve bir elips film setinin  Tam ortasında Dublörüm yo...', ARRAY['Türk Edebiyatı','Şiir','Fırat Ülker']::text[], 8.5, '{"poet":"Fırat Ülker","poet_slug":"firat-ulker","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/hasretin-aktoru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zalim Dünya', 'zalim-dunya-aydin-cevik-g6log', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ey  zalim dünya

tüm şiirlerimi küstürdükten sonra,

o büyülü mıknatısınla

yakalayacak mısın beni bir daha,

ıssız bir adada tutsak etmişken

salacak mısın pupa yelken yarınlara

ey zalim dünya

günler batırırken yalnızlığımın girdabında, 

okyanuslara hükmeden rüzgarlarınla

uçuracak mısın beni, yeni yetme limanlara,

dalgakıranlara inat, batık özlemindeyken

ağıt yaktıracak mısın deniz kızlarına

ey zalim dünya

teslim almışken yüreğimi, ilk kanadığında 

bir demet karanfille varıp ta huzuruna 

enkazından sağ çıktığım son rüyam misali

sel olup taşacak mıyım kızgın ovalara,

söyle hangi yaşta, hangi zamanda

ey zalim dünya

yine de hakkını vermeyeceğimi sanma

içimi acıtan o gerçeği sen öğrettin bana

yalnız güle yüklemişken asaletin onurunu

dikenleriymiş onun gerçek sahibi aslında

yıllar gülleri soldurdu da, anladım sonunda.

30.07.1993', 'ey  zalim dünya tüm şiirlerimi küstürdükten sonra, o büyülü mıknatısınla yakalayacak mısın beni bir daha, ıssız bir adada tutsak etmişken sa...', ARRAY['Türk Edebiyatı','Şiir','Aydın Çevik']::text[], 8.5, '{"poet":"Aydın Çevik","poet_slug":"aydin-cevik","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/zalim-dunya-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk ve Ömür', 'ask-ve-omur-aydin-cevik-lxre8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bilseniz aşk uğruna, kaç güneş söndürmüşüm

Dolanmış ayaklarım, kuyulara düşmüşüm

Nice ay sofrasından aç sefil kalkmış ruhum

Ne gözler eskitmişim mahkûm kalmış ruhum

Çevirmişim tersine, kum saatimi kıştan

Derman, çare ummuşum, gelecek tek bakıştan

Kurmuşum da kurmuşum, toz tutan kırk yaşıma

Tek cemre değmemişken, pişmiş gönül aşıma

Ahlar boyu değmişim, bin bir dikenli güle

Mühre boyun eğmişim, dönmüşüm kuru küle

Sormamışken bir ahu, çektiğim şu günahı

Daha gün mü ışıldar, yitirmişken sabahı!

Kırpmışım yıldızları, gök dökülse ne keder

Saçıma dolsa aklar, miat dolsa kim ne der

Mum gibi erir bu can, kavuşamaz canana

Her düşüm birer damla, yeter bu ömür bana!

03.08.2005  Rev. 21.12.2024', 'Bilseniz aşk uğruna, kaç güneş söndürmüşüm Dolanmış ayaklarım, kuyulara düşmüşüm Nice ay sofrasından aç sefil kalkmış ruhum Ne gözler eskitm...', ARRAY['Türk Edebiyatı','Şiir','Aydın Çevik']::text[], 8.5, '{"poet":"Aydın Çevik","poet_slug":"aydin-cevik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yeter-400-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Böyle oluyor', 'boyle-oluyor-mehmet-cafer-ixwuu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'hep böyle oluyor biliyormusun? 

zamanlı,zamansız gelişlerinle,

bir dağ yamacında beni,

yellere teslim ediyorsun.

hep böyle oluyor biliyormusun? 

farklı,farklı sancıyor vücudum,

bir bardak,bir kaşık,bir aşık,

gecelere mahkum deiyorsun.

hep böyle oluyor biliyormusun? 

senli sensizliğimi,bilmem kaçla çarpıyorum,

bir kalem,bir kağıt,bir zabit,

kelimelere esir ediyorsun.

hep böyle oluyor,hep böyle ölüyorum.

sen aynı tahtında,

sen aynı bahtınla.

ben aynen kahrımla,

ben aynen ağrımla.

sensizliği sende çözmek,

ve dahi sensizliğini,seninle yitirmek,

ve dahi gülüm! 

seni içime gömmek istiyorum.

hep böyle oluyor,

hep böyle ölüyor,

ne seninle,

nede sensizliğimle başedemiyorum...', 'hep böyle oluyor biliyormusun?  zamanlı,zamansız gelişlerinle, bir dağ yamacında beni, yellere teslim ediyorsun. hep böyle oluyor biliyormus...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Cafer']::text[], 8.5, '{"poet":"Mehmet Cafer","poet_slug":"mehmet-cafer","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/boyle-oluyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tarih Yazar', 'tarih-yazar-aydin-cevik-1ak4o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ey sevgili,

gel bir kez olsun tut şu sözünü

terk edeceksen terk et beni

ister yanlışlarımın fiili ol

anlamsız bırak tümcelerimi

ister yalnızlığımın fili ol

ezip geç sevda çiçeklerimi

istersen bahtsız çölüme çekirge ol

vahasızlık utandırsın bedeviliğimi

istersen denizimde vurgun ol

balıklar çıkarsın su yüzüne canevimi

ya  gel ruhuma bir demet karanfil ol

yansın senden öte ölümün kandili

ya da düşlerimi zehirleyen kabus ol 

ayrılsın bedenimin cenneti cehennemi

haydi bu kez  sadık kal yeminine

sensizliğe mahkum edeceksen et beni

nasıl olsa tarih yazar asıl kaybedeni.

13.09.1995', 'Ey sevgili, gel bir kez olsun tut şu sözünü terk edeceksen terk et beni ister yanlışlarımın fiili ol anlamsız bırak tümcelerimi ister yalnız...', ARRAY['Türk Edebiyatı','Şiir','Aydın Çevik']::text[], 8.5, '{"poet":"Aydın Çevik","poet_slug":"aydin-cevik","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/tarih-yazar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çünkü Aşıktık', 'cunku-asiktik-aydin-cevik-yrith', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ayı söndürürdük biz şu gözlerin ferinde

buluştuğumuz yerde, o bildik tanyerinde

çünkü aşıktık tenim ayrılmazdı teninle

bir ömür biçtirmezdik sevdamıza seninle

ufku yakıştırmazdık engin denizimize

korsan gemileri hiç takmazdık peşimize

çünkü tutkunduk aşktı yanan kandilimizde

geçse bile seneler yaşardı dilimizde

kurutur kışa yolcu ederdik sinsi güzü

ardımızdaydı rüzgar dardı bize yeryüzü

çünkü yeminliydik biz kapılmak yoktu ele

sendelesek te dimdik ayakta ve elele

taşardık vadimize lavı tutmazdık özde

şüphe duymazdık asla ne sözde ne de gözde

çünkü bir şarkıydık hep söylenen dilden dile

dolaşırdık birlikte ecel ayırsa bile.

23.08.2005', 'ayı söndürürdük biz şu gözlerin ferinde buluştuğumuz yerde, o bildik tanyerinde çünkü aşıktık tenim ayrılmazdı teninle bir ömür biçtirmezdik...', ARRAY['Türk Edebiyatı','Şiir','Aydın Çevik']::text[], 8.5, '{"poet":"Aydın Çevik","poet_slug":"aydin-cevik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/cunku-asiktik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl Çıktıysan Öyle İnersin', 'nasil-ciktiysan-oyle-i-nersin-aydin-cevik-0lemv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'hey sen güzel kız

nasıl çıktın böyle doruklarıma

bir başına gece vakti, benden habersiz

patikalarımdan yukarı sessiz sessiz

yorgunsundur gel misafirim ol bu gece 

bırakamam karanlıkta yapayalnız, kimsesiz

beklerim buzdan sarayım emrine amade 

çığım düşmez korkma! 

çığ bende henüz tamamlanmamış bir tehlike

önce sakinleş, sonra kulak ver bana

ne sen öldürebilirsin beni

ne de ben değişirim kardelenimi zakkuma

uykun var saklama, gözlerinden belli

rahatça uyu şimdi

irkilme üstüne örttüğüm kar beyazımdan

dönülmez sözler çıktı artık dudaklarımdan

sabah olur da uyandığında 

duyarsan sayıklamaları

anla ki mazimdendir ansızın ziyaretime gelen

görürsen kara çadırları 

bil ki onlar bana yadigar göçebe kavimlerden

sende belki kısadır pişmanlıklar

bende ise uzundur dolmaz bir türlü boşluklar

oysa dipsiz kuyu değildir zaman... 

bak ne çabuk da doldu! 

istediğin sabahtı  sonunda o da oldu 

güneş şimdi seni ısıtır 

yüzün de kızarırsa anla ki baharın yakındır

kusuruma bakma, seni iyi ağırlayamadımsa

yalnız senden tek ricamdır

ardından el sallama, yolu da sorma

nasıl çıktıysan öyle inersin meraklanma! 

27.08.2005', 'hey sen güzel kız nasıl çıktın böyle doruklarıma bir başına gece vakti, benden habersiz patikalarımdan yukarı sessiz sessiz yorgunsundur gel...', ARRAY['Türk Edebiyatı','Şiir','Aydın Çevik']::text[], 8.5, '{"poet":"Aydın Çevik","poet_slug":"aydin-cevik","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/oyle-inersin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beşinci Mevsim', 'besinci-mevsim-aydin-cevik-ogqzo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ne zaman, nerede karşılaşsak 

gözlerimizi kaçırıyoruz  birbirimizden

korkuyoruz 

aşk adına söylenebilecek  sözlerden

oysa dokunabilseydik,

deva olabilseydik kanayan yaralarımıza

konuşamadıklarımız bir eylül bulutu gibi

ıslatabilir miydi böyle tepeden tırnağa...

terkedebilir miydik kendimizi

kum saatlerinden icat ettiğimiz çöllere...

hatırlar mısın 

ilk tanıştığımızda mevsim bahardı

ardından yaşadıklarımızdan bilmem kaç mevsim çıkardı

tek bildiğim birlikte yaşlandık 

her şeyi içimize gömmeye karar verdiğimizde ise hazandı 

ve geçmişle vedalaşıp ayrıldık

anlaşılan o ki 

yaşatamadıklarımızın  intikamını kollamış zaman

haber bile vermeden sinsice girmiş kapımızdan

tam da beşinci mevsimindeyken aşkın 

ayrılık ta denilen

tüm anılarımızı da alıp gitmiş 

yetişemeden peşinden...

pişmanlıklarımızla başbaşayız şimdi

ama cesaretimiz yok artık 

zamanla yarışmaya

saçlarımızda aklar...akıllarımızda uzaklar

bu ömür yetmez barışmaya...

04.09.2005', 'ne zaman, nerede karşılaşsak  gözlerimizi kaçırıyoruz  birbirimizden korkuyoruz  aşk adına söylenebilecek  sözlerden oysa dokunabilseydik, d...', ARRAY['Türk Edebiyatı','Şiir','Aydın Çevik']::text[], 8.5, '{"poet":"Aydın Çevik","poet_slug":"aydin-cevik","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/besinci-mevsim-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dörtlükler.', 'dortlukler-cemal-simsek-pvg45', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerimde ağlamaklığın kızıllığı varsa,

Kalbin ayrılmışlığın hüznüyle yanıyorsa,

Ve gözyaşlarım kirpiklerimde kuruyorsa,

Şunu bilki..sevğilim Seni seviyorum.

-------------

Bir kızıl bulut sarmışsa tüm benliğimizi,

Kapanmışsa tüm kapılar,göremiyorsak sevdiğimizi

Ve yaratan böyle yazmışsa kaderimizi

Dileğimdir tanrıdan versin bize sevdiğimizi

---------------

Baktıkça bir fırtına kopar,göbebeklerinde,

Baktıkça içim yanar.sessiz ve derinden.

Baktıkça bakışmak,bakıştıkça yaklaşmak,

Baktıkça öpmek ister gözlerim göz bebeklerinden.

-----------------

Arzuyla,şehvetle kıvrılan dudaklarında,

Arzuyla yanar,dudaklarım karşında

Arzuyla açılan yarı nemli dudaklara

Arzuyla dokunmak ister dudaklarım,kalbe giden yolda.

-----------------

Sevmek sevesiye sevmek demek,

Tıpkı ölesiye ölmek gibi.

Ölmekle sevmek,severken ölmek

Ölümlerin en güzeli

Sevdiğini söylemeden ölmek.', 'Gözlerimde ağlamaklığın kızıllığı varsa, Kalbin ayrılmışlığın hüznüyle yanıyorsa, Ve gözyaşlarım kirpiklerimde kuruyorsa, Şunu bilki..sevğil...', ARRAY['Türk Edebiyatı','Şiir','Cemal Şimşek']::text[], 8.5, '{"poet":"Cemal Şimşek","poet_slug":"cemal-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/dortlukler-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirlerim', 'siirlerim-sultan-mustafa-f928g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mecnun’dan nefes, Leyla’dan hasret aldı şiirlerim

Davut’tan bir ses, Rüstem’den kuvvet aldı şiirlerim

Koca ummanı bir damlaya sığdırmak emeliyle

Güzelden heves gönülden niyet aldı şiirlerim

Ben bir güzel mısra derdim, o illa güzel derdi

Sultanım şiirse amacın güzele gel derdi

Tezadın kafa sancılarında benimle yandı da

Fakirden servet Sultandan himmet aldı şiirlerim', 'Mecnun’dan nefes, Leyla’dan hasret aldı şiirlerim Davut’tan bir ses, Rüstem’den kuvvet aldı şiirlerim Koca ummanı bir damlaya sığdırmak emel...', ARRAY['Türk Edebiyatı','Şiir','Sultan Mustafa']::text[], 8.5, '{"poet":"Sultan Mustafa","poet_slug":"sultan-mustafa","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/siirlerim-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tartı', 'tarti-aydin-cevik-drlhk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şu aşkı yudumlarken, mevsim ilkti bahardı

Yağan yağmuru diner, elbet güneş açardı

Bir tüy kadar hafiftik, aynı ruh tek bir beden

Kana kana içerdik, sen ve ben iksirinden 

Şimdi saçlarda aklar, yorgunuz, darmaduman

Çalıyor sis çanları, ne kır belli ne orman

Tartamaz oldu dünü, zamane gökkuşağı

Sırlandık aynalar da, her yer örümcek ağı

05.09.2005 Rev: 21.12.2024', 'Şu aşkı yudumlarken, mevsim ilkti bahardı Yağan yağmuru diner, elbet güneş açardı Bir tüy kadar hafiftik, aynı ruh tek bir beden Kana kana i...', ARRAY['Türk Edebiyatı','Şiir','Aydın Çevik']::text[], 8.5, '{"poet":"Aydın Çevik","poet_slug":"aydin-cevik","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ask-tartildi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gizli Bahçe', 'gizli-bahce-aydin-cevik-kahtw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'varırsak son perdeye piyesimizde bu yaz

çıkar çıkmaz kostümler kalamayız bembeyaz

elveda derken gözler kınında bekler sözler

deli gibi çarpan kalpler ölümü bile özler

ressamı terketse de öksüz kalmaz resimler

unutulamaz düşler silinemez isimler

bitse de saltanatı gönüllü esaretin

damaklardan eksilmez tadı o cesaretin

korkum odur ki bir gün sona erer bu büyü

birleşemeyiz sonra kaybolur anka tüyü

sinsi sinsi yerleşir sineye hoyrat iklim

düşer o son kalemiz bizi de alır teslim

kine dönüşür sevda gireriz bir mezara

ne isteyerek olur dönüş ne de kazara

gel dinle beni gizli bahçemiz bize kalsın

solsa da çiçekleri bırak hepsi kök salsın.

11.09.2005', 'varırsak son perdeye piyesimizde bu yaz çıkar çıkmaz kostümler kalamayız bembeyaz elveda derken gözler kınında bekler sözler deli gibi çarpa...', ARRAY['Türk Edebiyatı','Şiir','Aydın Çevik']::text[], 8.5, '{"poet":"Aydın Çevik","poet_slug":"aydin-cevik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gizli-bahce-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömrümün Kışları', 'omrumun-kislari-aydin-cevik-zmido', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'düşbozumuna terk deli çağımı

ters yüz edilen solumu sağımı

şu biçare elimi ayağımı

sizden bilirim ömrümün kışları

kör talihe boyun eğen başımı

gece gündüz dinmeyen gözyaşımı

gülmeyen yüzümü çatık kaşımı

sizden bilirim ömrümün kışları

anılara sürgün ilk göz ağrımı

odlara mahkum şu garip bağrımı

üstüme çığ düşüren son çağrımı

sizden bilirim ömrümün kışları

hazan ehli yaz bilmez mizacımı

yarsız iflah olmaz gönül acımı

ak düşmüş saçımı bahtsız tacımı

sizden bilirim ömrümün kışları

sümbüle salkım durmuş ahlarımı

güle diken sunmuş günahlarımı

süsene kök olmuş eyvahlarımı

sizden bilirim ömrümün kışları.

18.09.2005', 'düşbozumuna terk deli çağımı ters yüz edilen solumu sağımı şu biçare elimi ayağımı sizden bilirim ömrümün kışları kör talihe boyun eğen başı...', ARRAY['Türk Edebiyatı','Şiir','Aydın Çevik']::text[], 8.5, '{"poet":"Aydın Çevik","poet_slug":"aydin-cevik","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/omrumun-kislari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karasevda', 'karasevda-aydin-cevik-f38d9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'adına karasevda denilen sen soysuz kin

silsem de tadı gitmez dudağımdan busenin

yaraların var ben de kanarlar sessiz sakin

anlatamam ki seni canı yetmez kimsenin

dünya döner dönerim aşılmaz ki  eşiğin

mum misali eririm, yalnız aydır kefilim

güler yüzün durmaz yaz kış sallanır beşiğin 

oysa özde biçare gözündeyse sefilim

kederi kader bilip tadarken ellerinden

ahde vefa beklersin gözlerimin ferinde

beni çekip alırsın dünün gazellerinden

sonra adıma meçhul dersin her seferinde

ruhu bedenden çalan  panzehirsiz bir oksun

çöller vahasız olur vahalar çölsüz değil

şimdi seni kimler ne diye kalbine soksun

ışık kırılır suda düz durma sende eğil! ...

24.09.2005', 'adına karasevda denilen sen soysuz kin silsem de tadı gitmez dudağımdan busenin yaraların var ben de kanarlar sessiz sakin anlatamam ki seni...', ARRAY['Türk Edebiyatı','Şiir','Aydın Çevik']::text[], 8.5, '{"poet":"Aydın Çevik","poet_slug":"aydin-cevik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/karasevda-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Deniz Dibi Hikayesi', 'bir-deniz-dibi-hikayesi-aydin-cevik-r8un0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sen ki; evvel zamandan bugüne miras testi

bil ki; batığım ben de, kaderim böyle esti

tam hasretle beklerken edalı bir güzeli

dibe çekti aniden deniz kızının eli

sevdalıymış meğerse, kal-ü beladan beri

gözlermiş kumsalları, buluştuğumuz yeri 

         

kapıldım anafora kapattım gözlerimi

zincir yaptım kendime en kalın sözlerimi

          

derinlerin soğuğu kısamadı sesimi

karası kıramadı aydınlık hevesimi 

yosunlarda çürüttüm uzak ihtimalimi

balıklardan yürüttüm yakın ihtilalimi

ne deniz kızı ne de denizin ahalisi

bulamadılar asla sevdamdan da halisi 

çözseler de ömrümün saklı bilmecesini 

söylemedim kimseye kalbimin ecesini

iç kabartan dalgalar sığındı kıyısına

kararan yakamozlar darıldı akısına

kötü bitti hikaye gönüller girdi yasa

bir taht kaldı geriye bir de kırık bir asa.

02.10.2005', 'sen ki; evvel zamandan bugüne miras testi bil ki; batığım ben de, kaderim böyle esti tam hasretle beklerken edalı bir güzeli dibe çekti anid...', ARRAY['Türk Edebiyatı','Şiir','Aydın Çevik']::text[], 8.5, '{"poet":"Aydın Çevik","poet_slug":"aydin-cevik","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bir-deniz-dibi-hikayesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kasım Yağmuru', 'kasim-yagmuru-aydin-cevik-duws8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sonunda

kalkıyordu gözlerimden

o dördüncü perondaki tren

ben olduğu yerde kalakalmış 

öylece bekliyorken... 

ah o bakışların yok mu... 

beni bende kaybettiren

şimdi kaçıyorlardı 

bir hoşça kal bile diyemeden 

tam da o anda radyoda çalarken şarkımız 

“November Rain” ile  “Guns N’ Roses”

 “eğer beni seviyorsan sevgilim ver elini bana

birlikte yürüyelim şu soğuk kasım yağmurunda”...

buz kesmişti çoktan her yanımız

ellerimiz titriyor gözlerimiz yalvarıyordu

yapamamıştık ne kadar denesek olmuyordu...

bir türlü yatıştıramamıştık denizlerimizi 

bir sokak lambasının altında 

aydınlatamamıştık en derin gizlerimizi

bilmezsin...

ben küçükken

hiç sevmezdim yağmurlarda ıslanmayı

tam büyüdüm

kabullendim derken sırılsıklam olmayı

bir kasım yağmuru ayırt etmeden, 

içimizde dışımızda ne varsa yıkıyordu

anılarımız kuru kaldı diyemiyorduk 

umutlar sulayamazken topraklarımızı

sabah güneşi kaynatamazken kanlarımızı...

ne çabuk unutuldu o günler

az mı  yuttuk aynı kentin tozunu çamurunu

az mı  söyledik birlikte şu kasım yağmurunu

keyifle yudumlarken vapurlarda beş çayımızı 

az mı seçtik simitleri bölüşeceğimiz martılarımızı

gökkuşaklarıyla

ne çok kelimeyi süsleyip boyadık seninle 

yaz kış demeden... 

ve ardından buruşturup attık 

birbirimize armağan edemeden.

şimdi

yıllardan sonra...

yaşadıklarımızdan sonra...

yeniden ayrıldığımız perondayım 

bir CD çaların kulaklığında maziyi çağırmaktayım

söylüyor “November Rain” ‘i  “Guns N’ Roses”

hani o bizi birbirimize bağlayıp ayıran şarkımız; 

“eğer beni seviyorsan sevgilim ver elini bana

birlikte yürüyelim şu soğuk kasım yağmurunda”

ve ardından devam ediyor; 

“herkes birine muhtaçtır

ekmeğe suya olduğu gibi ona açtır”

artık yapayalnızım çok üşüyorum

düşlerim tutamaz oldu düşüyorum

gel de dindireyim

şu yürek sızımı duyayım sesini 

soğuk kasım yağmurunda

içime çekeyim o ılık nefesini

ne olursun 

gittiğin gibi çık gel uzaklarımdan

sonra 

sımsıkı sarıl öp beni 

aradan beş yıl geçmiş gibi dudaklarımdan! 

26.09.2005', 'sonunda kalkıyordu gözlerimden o dördüncü perondaki tren ben olduğu yerde kalakalmış  öylece bekliyorken...  ah o bakışların yok mu...  beni...', ARRAY['Türk Edebiyatı','Şiir','Aydın Çevik']::text[], 8.5, '{"poet":"Aydın Çevik","poet_slug":"aydin-cevik","theme":"Türk Şiiri","is_hero":false,"total_lines":63,"source_url":"https://www.antoloji.com/kasim-yagmuru-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lirik 44 (yerim yok)', 'lirik-44-yerim-yok-fevzi-cebe-45rgn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bölüm bir

ayaklarımdan tutsalar beni

bağlasalar

ikizkenar bir diküçgen’e

metronom gibi sallansam

bu beni sevk eder mi

hayalsizliğe

veya kendinden habersiz hayallere

istediğim bunlar değildi

istemediklerim oldu hayallerim

beni neden anlamadın hiç

çok mu geldim az mı

ben seni sardım

sen kendi ruhunu

çekerken seni nefesimle

sen, sadece boynunu kaldırdın

bu kimin mutsuzluğu

umutsuzluğu

umarsızlığı

iki

bana uzaksan

bu kimin problemi

tutmuyorsan ellerimi

bu kimin sevgisizliği

bakmıyorsan gözlerime

kimin bu suçluluk

seni bırakırsam eğer

bu kimin acısı

bilgeliği

yabancıysan anılara

geçmişe ve 

halen benim için geçmemişlere...

ne yapmalıyım

olan oldu biten bitti ama

devrilecek dev kayalar var halen

peki bu ağırlık sarsmaz mı beni

git ve mutlu ol

hak ettiğinden değil, 

öyle istediğimden

senin mutsuzluğun beni

mutlu etmez

mutluluğun dudaklarımda küçük bir tebessüm olur

bensiz de olsa(n)

herkese açtığımdan çok açtıysam da

kollarımı sana

yaslamadın başını göğsüme

benim olmadın ne dün ne bugün

bırakmak zor değil seni

bir yalana inanmak kadar

beni bırak zaferin olsun bu

kayıtsız kalacağım

üç

ses var

söyleyecek sözlerim

söyleyemeyeceklerim için

söylemsizliğim için

suskunluğum için

ise

durgunluğum

yeni bir s.w. vakası mı? 

benim bu kurguda yerim yok

olamaz

06.02.2005 – 21.10', 'bölüm bir ayaklarımdan tutsalar beni bağlasalar ikizkenar bir diküçgen’e metronom gibi sallansam bu beni sevk eder mi hayalsizliğe veya kend...', ARRAY['Türk Edebiyatı','Şiir','Fevzi Cebe']::text[], 8.5, '{"poet":"Fevzi Cebe","poet_slug":"fevzi-cebe","theme":"Türk Şiiri","is_hero":false,"total_lines":63,"source_url":"https://www.antoloji.com/lirik-44-yerim-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı Aşktı....Sonu Ayrılıktı...', 'adi-askti-sonu-ayrilikti-aydin-cevik-r399p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ne güzel günlerdi onlar...

fesat karlara inat uykusunda süslenmiş bir vadiydik

sabahın çiyleri bile yeterdi düşlerimizi sulamaya

biz telaşlı arıların aradığı çiçeklerin soyaçekimiydik

henüz hazır değildi dallarımızdaki meyveler olmaya

o zamanlar...

yaşadıklarımızın adını 

hiç sormamıştık ki gözlerimize 

gecelerimizin aydınlığı

günleri giydirir dururdu üzerimize

ay ışığında dikerdik gönüllerimizin sığ yırtıklarını

şüphe öyle dörtnal koşturamazdı içimizde yağız atlarını

derken bir gün...

davetsiz bir kervan geldi yerleşti çimenlerimize

meraklı bakışlarımızda çözüldü hazanımızın kilitleri

nice yağmurun çamurunu taşıyıp durdu içimize

hoyrat adımlarda can verdi vadimizin kelebekleri

ne çok yaprak kaybettik seninle o kış 

sönük yıldızlara bile ulaştı tenlerimizdeki yakarış

ve dün geldi...

artık yastaydık ezilen onca masum tomurcukların ardından

önce adını sonra noktasını koyduğumuz neydi anlayamadan

“aşktı koynumuzda besleyip yarınlara büyüttüğümüz adı bebeğin

ayrılıktı bizi kendi kuyularımıza mahkum eden sondaki derbederliğin.”

02.10.2005', 'ne güzel günlerdi onlar... fesat karlara inat uykusunda süslenmiş bir vadiydik sabahın çiyleri bile yeterdi düşlerimizi sulamaya biz telaşlı...', ARRAY['Türk Edebiyatı','Şiir','Aydın Çevik']::text[], 8.5, '{"poet":"Aydın Çevik","poet_slug":"aydin-cevik","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/adi-askti-sonu-ayrilikti-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şu Dünya', 'su-dunya-aydin-cevik-onz59', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'şükür kavuşturana dostum,

bak birbirimizi bulduk sonunda! 

buraların yabancısı da değilmişiz aslında...

yavaş yavaş anımsıyorum 

biz seninle on yıl önce de buralardaydık

güzellerin bakışlarında aşka dair kanıtlar arardık

maziden bodoslamasına dalıp tosladığımız

şu iç karanlığı

sinmemişti henüz üzerimize

fiyakalı balkonlardan fırlattığımız 

bir göz kaçamağı 

yetiyordu içimizde ölenleri diriltmemize

bir günden diğerine kovalandığımızda 

nefessiz kalmıyorduk böylesine

adanın mimozalı sokaklarında 

muhtaç değildik martıların sesine

o zamanlar  daha gençtik

izin vermezdik varoluş güvertemizin suyla dolmasına 

uçurduğumuz güvercinlerin siste kaybolmasına...

dünü bugün sanmışız

oysa

bir geceden tam üç bin altı yüz elli gün sonraya uyanmışız... 

şimdi 

kime sorsak yanıt veremiyor bize; 

“şu içinde bulunduğumuz çağ kimin çağı? 

kim kimin eline verdi bıçağı? 

emekli olmuş mu yoksa mektup açacağı? 

hala yaşıyor mu o hain elektrik kaçağı? ”

bilmiyorlar... bilmiyoruz... bilmeyecekler...

hatırlar mısın? 

ne günlerdi onlar…

bozuk parayla alınan bir jetonla toplanırdık hepimiz

ne olduysa

cep telefonlarından sorulur olmuş yeni buluşma yerimiz 

eski alışkanlıkları biriktirmeyi unutmuşuz,

savurmuşuz avucumuzdan

gençliğimiz yittiğinden beri, 

karlar da kalkmıyor saçlarımızdan

eskiden bindiğimiz sandalı 

mehtapsız bir gecede batırmışız

bugünlerde hakim renk yalnızlıkmış 

biz modayı karıştırmışız...

yeter artık dostum

gönüllerde bırakalım o eski saltanatı

kopsun inceldiği yerden geçmişin halatı

ceplerimizde dokuz suaresine 

iki bilet alacak kadar para kalmışsa 

şanslı sayılırız

sanal gerçekliklerden dümdüz devam edip 

bilmem kaç metre öte gittik mi 

kesin ayılırız! 

haydi bırakalım 

bir kez de

umurumuzdan sınıfta kalsın şu dünya

daralmasın yollarımız varmadan aya! ...

10.10.2005', 'şükür kavuşturana dostum, bak birbirimizi bulduk sonunda!  buraların yabancısı da değilmişiz aslında... yavaş yavaş anımsıyorum  biz seninle...', ARRAY['Türk Edebiyatı','Şiir','Aydın Çevik']::text[], 8.5, '{"poet":"Aydın Çevik","poet_slug":"aydin-cevik","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/su-dunya-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönence', 'donence-aydin-cevik-upa9r', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'başlarken, 

tüm aşkların hedefi bellidir; ölümsüzlük

oysa ortaktır kaderleri 

o ayrılık denilen çözülmüşlük, öksüzlük

aşıklar,

gökkuşağını taşır o çocuk yüzlerinde

düşlerini bozarlar bir bir gündüzlerinde

ne edilen yeminler yenilir beddua’ya

ne tövbeler muhtaçtır, gerek duyar dua’ya

ne yazık ki her defasında,

kıskanç bir peri ele verir tüm masalları

medcezirler hırpalar en narin kumsalları

bir gün, bir yerde yakalandığınızda

kadranı kırılmıştır pusulalarınızın

bulamaz yönünü fersiz gözleriniz

hazanı gelmiştir yapraklarınızın

bir yazda tükenmiştir klorofilleriniz

ve... 

ne olduğunu anlayamadan

ayrı uçurumlarda bulursunuz kendinizi

sevdanızı koza örüp saklayamadan

avı olursunuz ayrılığın

hazin bir hikaye 

ya da yarım bir şiir kalır ancak geriye

işte o an anlarız eski rivayetleri

aşkla ayrılık arkadaşmış

aşk tüm aşıkları öldürürmüş kendinden önce

başka ölümsüz istemezlermiş sürsün diye bu dönence.

18.10.2005', 'başlarken,  tüm aşkların hedefi bellidir; ölümsüzlük oysa ortaktır kaderleri  o ayrılık denilen çözülmüşlük, öksüzlük aşıklar, gökkuşağını t...', ARRAY['Türk Edebiyatı','Şiir','Aydın Çevik']::text[], 8.5, '{"poet":"Aydın Çevik","poet_slug":"aydin-cevik","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/donence-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elimde Değildi', 'elimde-degildi-aydin-cevik-ed5fj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'üzgünüm

elimde değildi

aşkla birlikte geldiğinde

ben kırkına yakın bir çocuktum

düşlerim uyanıktı

bense üstü örtülecek kadar korkmuştum

gözlerim kamaşmıştı

tebdili mekân olsun diye aysız akşamlara sokulmuştum

oysa

yıllar fener alayları gibi geçip giderken ömrümden

yalnızlığımı gizliyordu gecenin gardırobunda gün ışığı

belki de ıslanmaktan bir türlü vazgeçemediğimden

her seferinde ele veriyordu beni günlerimin kuraklığı

gecikmiş bir yazın ardından 

hazanım oldun

büyülendim ay ışığıyla kumsallara yazılmış adından 

ev yaptım sana ışık sızdırmaz salyangoz kabuğundan

gün geldi yaşadıklarımızla sığamadık

kendimize ahşap bir sandık yaptık

çölleri yalnız bırakmanın utancıyla 

deniz çekilirken üzerimizden

bir gün bizi de alıp götürür başka diyarlara sandık

daha bedenlerimiz iç kanaması nedir bilmeden

tan ağarmamıştı derken sen giden biz kalandık

üzgünüm 

elimde değildi

aşkı bırakıp gittiğinde

ben kırkında bir çocuktum

onca bozdurduklarımın ardından

avuçlara düşen yeni kuruştum...

14.10.2005', 'üzgünüm elimde değildi aşkla birlikte geldiğinde ben kırkına yakın bir çocuktum düşlerim uyanıktı bense üstü örtülecek kadar korkmuştum gözl...', ARRAY['Türk Edebiyatı','Şiir','Aydın Çevik']::text[], 8.5, '{"poet":"Aydın Çevik","poet_slug":"aydin-cevik","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/elimde-degildi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmurun Farkı', 'yagmurun-farki-onur-ridvan-tozlu-1ywb6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gök yüzünden akan su yağmurdur 

ağladığımızda gözümüzden akan su gibi

Aralarındaki fark nedir? 

Biliyor musunuz? 

Koca bir hiçtir.

İkisi de insanı üzer,

İkisi de insanı ıslatır,

İkisi de hüzünlüdür,

Aralarındaki fark

Koca bir hiçtir 

Her canımız istediğinde ağlayamayız,

Tıpkı bulutlar gibi,

Neden biliyor musunuz? 

Güzel olan her şey zor olur.

(06/12/2005)', 'Gök yüzünden akan su yağmurdur  ağladığımızda gözümüzden akan su gibi Aralarındaki fark nedir?  Biliyor musunuz?  Koca bir hiçtir. İkisi de ...', ARRAY['Türk Edebiyatı','Şiir','Onur Rıdvan Tozlu']::text[], 8.5, '{"poet":"Onur Rıdvan Tozlu","poet_slug":"onur-ridvan-tozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yagmurun-farki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Susuyorum Diye', 'sana-susuyorum-diye-aydin-cevik-8eu9j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ah sevgili,

sana susuyorum diye

kasımlar sağanak bırakır oldu üzerime

çok hatalıydım biliyorum

bir elimde hoyrat bir güze terkedilmişliğim

diğerinde şafağı olmayan tekilliğim

yüküm ağırdı zor geçti yıllarım 

bense hala kıraçtım 

tek sırdaşımdı gözü yaşlı ıhlamur ağacı

paylaşır olduk 

erken yaprak dökmelerin verdiği  utancı...

ah sevgili,

sana susuyorum diye

kasımlar sağanak bırakır oldu üzerime

yılların hıncıyla vuruyorlar şimdi pencereme

camlar  duyarsız

ben buğulanıyorum

açamadım gözlerimi her yanım yıldırım

galiba artık çok yalnızım

bir türlü aşamadığım bulutlara değen surlarından

ekvatorundan yola çıkıp varamadığım kutuplarından 

anladım ki  ben unutulmuşum…

ah sevgili,

sana susuyorum diye

kasımlar sağanak bırakır oldu üzerime

bilmezler ki 

çağım değildi 

ödünç isteyemedim haritasını Piri Reis’ten

ne yapsam doğamadım gözlerinde yeniden 

anka kuşu gibi küllerimden

mevsimsiz geçse de yıllarım

çiçekleniverdi birden ıhlamur ağacım

kokundur diye içime çekip ağlar oldum...

ah sevgili,

sana susuyorum diye

kasımlar sağanak bırakır oldu üzerime

ama görmezler ki 

yanımda getirmişim geçtiğim ülkelerin güneşini 

sel olup bin suretinden koparsalar da beni

ayışığında demlemişim senliğimi

öyle bir aşk ki içimdeki bakılmaz rakımına 

soluk aldırmaz yarası varken göğsümde

aysız gecelerin zifiri bulaşınca endamına

vuslat diye diye nehirler kurutmuşum tenimde...

ah  sevgili,

gönlümde gün geçtikçe çoğalıyorsun 

karşı konulmaz bir salgın gibi

ne olursun 

affet artık beni 

bilinmez ama şimdiden

birgün düşecek yolun üzerimden geçeceksin

hazır buram buram toprak kokarken 

bir kez olsun çek içine nasıl da değişmişim göreceksin…

“ne zaman değse yağmur taneleri toprağa 

  biter actinomyces sporlarının korkusu

  sevinçle zıplarlar, karışırlar havaya 

  ve yayılır etrafa, buram buram toprak kokusu…”

01.11.2005', 'ah sevgili, sana susuyorum diye kasımlar sağanak bırakır oldu üzerime çok hatalıydım biliyorum bir elimde hoyrat bir güze terkedilmişliğim d...', ARRAY['Türk Edebiyatı','Şiir','Aydın Çevik']::text[], 8.5, '{"poet":"Aydın Çevik","poet_slug":"aydin-cevik","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/sana-susuyorum-diye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimdeki göz yaşım', 'i-cimdeki-goz-yasim-bilal-altuntas-mf71f', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu anlayıpta anlatamadığım,

Bir defaya mahasus kullanıp,

Bir dahada atamadığım,

Hiç kimsenin bilmediği,

Bilemeyeceği acım,

İçimdeki göz yaşım! ...

Yılların ardındaki saç ağrım,

Mazide  yitirdiğim,

Gelecekteki aradğım,

Bir gönül yaram kalp sızım,

Söküp söküp atamadığım,

AŞKIM! 

İçimdeki göz yaşım...

Geceleri yıldızım,

Gündüz güneşim,

Bazen duvardaki sazım,

Bazen şimşeklerleyim,

Bazen ıssızım,

Ama  benle hep  var olan,

Aşkım birtanem,

İçimdeki göz yaşım! ...

Ama aslı bu degil acımın,

Bir zalıim kıydı sevdama ansızın! 

Başımdaki tacımdı bilmedi bilemedi,

Ağlattı kararttı dünyamı yanlızım.

İsyanımdır bu sana isyanım,

Akacakmış aksın yıllarca,

İçimdeki göz yaşım! ...', 'Bu anlayıpta anlatamadığım, Bir defaya mahasus kullanıp, Bir dahada atamadığım, Hiç kimsenin bilmediği, Bilemeyeceği acım, İçimdeki göz yaşı...', ARRAY['Türk Edebiyatı','Şiir','Bilal Altuntaş']::text[], 8.5, '{"poet":"Bilal Altuntaş","poet_slug":"bilal-altuntas","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/icimdeki-goz-yasim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Filizî Yalnızlık', 'filiz-yalnizlik-nurdan-unsal-yxa5v', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'düğümlenir kelimeler

maziye yutkunarak

üşümelerde yeşil 

mor gecelerde ay sıcak 

yıldız nerede

zinciri boşalmış saatlerde sevinç 

yılan kabuğu geride

hüzünleri tırpanla 

kıymalı mı yeşile ki büyür 

camdan pabuçlarım dansa yazık 

kırılır/küçülürken zaman 

gülüşler incinir 

güneş yakamozu söndürür 

her gün aynı teranesi sıradan ufukların 

çevrimin nesi gönendirir günü 

gün! dünün alkışı 

oyun göksel beden topraksa 

şık durur mu yıldız gecede 

yeşili kim görür gece filizlense 

yağmur düşeceği yeri bilir 

gecenin ardı güneş 

susar keder bekçilerim

14.12.2005

Lacivert Sanat, Eylül 2006', 'düğümlenir kelimeler maziye yutkunarak üşümelerde yeşil  mor gecelerde ay sıcak  yıldız nerede zinciri boşalmış saatlerde sevinç  yılan kabu...', ARRAY['Türk Edebiyatı','Şiir','Nurdan Ünsal']::text[], 8.5, '{"poet":"Nurdan Ünsal","poet_slug":"nurdan-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/filizi-yalnizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Farkında Olsaydık', 'farkinda-olsaydik-onur-ridvan-tozlu-8uemh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çok farklıydı bu dünya bizim için,

Bilmiyordu kimse dünyanın karanlık yüzünü,

Kim bilir belki de herkes kendi kendine diyordur,

Keşke gelmeseydim bu dünyaya,

Kimsenin elinde değildir,

Dünyaya nasıl ve ne zaman geleceği,

Zaten insanların elinde olsaydı böyle bir fırsat,

Kim bu karanlık dünyaya gelmek isterdi ki.

Tabi ki dünyanın kötü tarafları olduğu gibi,

İyi tarafları da vardır,

Sevgi gibi,

Aşk gibi.

Zaten bu değerler olmasaydı,

Dünya yaşamaya değer miydi? 

Kim katlanabilirdi ki bu dünyaya 

Bir düşünün.

Keşke insanlar paraya bu kadar önem vermese,

Keşke insanlar para için birbirlerinin canını yakmasa.

Keşke…

Keşke…

Zaten insanlar paraya bu kadar önem vermese,

Para için birbirlerine zarar vermese,

Bu dünya tertemiz,

Yaşamaya değer bir dünya olurdu.

(12/12/2005)', 'Çok farklıydı bu dünya bizim için, Bilmiyordu kimse dünyanın karanlık yüzünü, Kim bilir belki de herkes kendi kendine diyordur, Keşke gelmes...', ARRAY['Türk Edebiyatı','Şiir','Onur Rıdvan Tozlu']::text[], 8.5, '{"poet":"Onur Rıdvan Tozlu","poet_slug":"onur-ridvan-tozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/farkinda-olsaydik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimin Güneşi', 'i-cimin-gunesi-aydin-cevik-wpgb5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kalk Neron! 

yangın var yüreğimde

bir yudum su ver Romanın hatırına.

sen şimdi; 

“o ateş ki bir armağandır Prometheus’ tan 

  korur seni saran zifiri karanlıklardan ”

diyeceksin biliyorum.

ben böyle değildim,

kovalanan ceylanları gizlerdim yurdumda

ıslak gelincikleri kuruturdum odumda.

düne kadar 

yalnızlık teknesinin battığı deniz bendim

dişlerini kaybetmiş filleri son görendim.

ne zaman ki

toy bir bulut düşürdü ağzından yıldırımı

eş oldu gül ateşe 

mabet yapıp yıktılar ağlama duvarımı 

yetiş Neron! 

yangın var yüreğimde

bir yudum su ver Romanın hatırına.

sen şimdi; 

“bir orkidenin peşinde koştuğundan beri

 gün çiçekleri bile ummaz oldu seheri ”

diyeceksin biliyorum.

ben böyle değildim,

serenatlar yapardım dargın yaseminlere

suretler resmederdim gözden ırak inlere.

düne kadar

çiğdemleri gönül dağlarına eken bendim

sarhoş sulardaki  balıklara hükmedendim

ne zaman ki 

meşalemi söndürdü kıskanç bir ayışığı

yön de bulamaz oldu 

düşlerimin vuslatı irem bilen kayığı                      

duy Neron! 

yangın var yüreğimde

bir yudum su ver Romanın hatırına.

sen şimdi; 

“tam divane olup sığınmışken bir bülbüle

 o öttükçe derman buldun dönemedin küle”

diyeceksin biliyorum.

ben böyle değildim,

tayları büyütürdüm bahar ninnileriyle

dereleri beslerdim kış temennileriyle.

düne kadar

can çekişen fermanların altın mührü bendim

göçer kuşların aklına yazı düşürendim

ne zaman ki

gitti badısaba boranlar geçti vadimden

sele kapıldı yıllarım

halkım bile anlamaz oldu artık dilimden.

dur Neron! 

Bırak beni yanayım tükenişime kadar 

bir damla gözyaşım da aksa olsun manidar

yüklesinler kıyameti

dünya bile taşıyorsa

kurulduğundan beri o sevdiği tek eşi

ben de özüm bilirim içimdeki güneşi! 

15.11.2005', 'kalk Neron!  yangın var yüreğimde bir yudum su ver Romanın hatırına. sen şimdi;  “o ateş ki bir armağandır Prometheus’ tan    korur seni sar...', ARRAY['Türk Edebiyatı','Şiir','Aydın Çevik']::text[], 8.5, '{"poet":"Aydın Çevik","poet_slug":"aydin-cevik","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/icimin-gunesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Işık Denizinde Yanılsamalar', 'isik-denizinde-yanilsamalar-aydin-cevik-4k9mi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '“Benim bu ışıktan başka ne dileğim olur ki. Onun ışığına kavuştum sonunda. Ama isterim o ışık sonsuza kadar üzerimden eksik olmasın.'' Zeus Endymion''un dileğini kabul etti ve onu ölümsüz bir uykuya yatırdı Latmos  dağlarının eteklerinde ” Endymion ve Selene- Derleme- YGS yayınları.

nerelerdesin Selene 

kaç aşık sevdiğini böyle zalimce sınar

taş olsa çatlar yürek gözde tükenir pınar

ben deli divane,

kavalımla dizerken yıldızları boynuna

sokulmuşsun iyice bulutların koynuna.

bundan böyle,

Zeus dinlemez beni hakkım var mı kaos’a

sereserpe yatamam senin için Latmos’a.

söyle yalan mı; 

suretinle yetinip aslımdan vazgeçtiğim

özgür dolaşmak varken tutsaklığı seçtiğim

bir zamanlar,

saçını saldığın göl için için ölüyor

akşam sefaları küs, hepsi dünü özlüyor

ilkdördün, son dördün 

hilaldi son göründüğün...

gel,

çok geç olmadan gel ki; 

düşlerim bilmesin aşk yitik mevsim karanlık

devinmesin içimde şu eliptik pişmanlık.

ey ruhumun ışığı,

inandım her sözüne suçum varsa bileyim

bu aşktan daha derin neler varsa sileyim

yetmez mi,

sensiz geçen her gece derdime dert kattığım 

hicran gemilerinin buyruğunda battığım.

son bulsun

rüzgârlarda biçare, dağ bayır savruluşum

o vahasız çöllerde durmadan kavruluşum.

ne olursun gel artık...

gel de

birdenbire artmasın perihelik sanrılar

başlamasın yeniden meteorit sancılar.

gittin gideli

her yer yabancı bana soğuk, bomboş bir diyar

her seferinde düşüp gözden kaybolduğum yar

yoksa 

o kökünde demlenen yaprağında emlenen

aşk bizim değil miydi gün be gün erdemlenen.

Seni çok özledim Selene

vazgeç aydan gerekçelerden

binlerce sene geçti bir adımı anmadın

mit dediler halime yine de kıskanmadın.

demek ki

toy bir sevda peşinden okyanusa dalmışız

dudak dudağa sönüp karanlıkta kalmışız.

oysa bir zamanlar

 “ beni böyle sevdikçe teninde erir tenim

   ayıramazlar bizi huzur bulur bedenim ”

derdin …

şimdi yalnızım

belki  yüreğim kanla dolacak istemeden

ölümlü olacağım seni hiç göremeden

artık

“tepeden tırnağa nur kesilmenin zencisi

yakamozların adsız muratsız dilencisi”

diyecekler adıma...

desinler! 

nerelerdesin Selene

Se…! ! ! 

yoksa o  gelen sen misin? ? ? 

sus söyleme istersen...

yeter ki tutuldum deme 

git yine gideceksen! ...

30.11.2005', '“Benim bu ışıktan başka ne dileğim olur ki. Onun ışığına kavuştum sonunda. Ama isterim o ışık sonsuza kadar üzerimden eksik olmasın.'' Zeus E...', ARRAY['Türk Edebiyatı','Şiir','Aydın Çevik']::text[], 8.5, '{"poet":"Aydın Çevik","poet_slug":"aydin-cevik","theme":"Türk Şiiri","is_hero":false,"total_lines":67,"source_url":"https://www.antoloji.com/isik-denizinde-yanilsamalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fotosentetik Yaramazlıklar', 'fotosentetik-yaramazliklar-aydin-cevik-mly0u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '“Ceza kaldırılabilir; ama suç insanın içinde sonsuza kadar yaşar.” - Ovidius

Allah aşkına Flora

söyle ne yaptım sana

ben kim seni aldatmak kim

yerin dibine batsın soyaçekim

uyuyordun...

lalesi, zambağı, sümbülü

yasemini, leylağı, gülü

öyle yalnızlardı ki dayanamadım

senden habersiz kokladım! 

boynu büküktü fesleğenlerin

acıdım onları da suladım! 

ve hala uyuyordun! ...

gördüm solmuş bir güzel avrat otu

okşanmakmış bilinen tek antidotu

yanından ayrılamadım! 

ne olur affet beni Flora

ne yaptıysam aşk adına! 

ben kim çapkınlık kim

gönlüm bilmez başka hekim

vallahi,

sarmaşıkların dillerinden anladığım yok

kozalaklıların burçlara karınları tok

ey yeşillerin ölümsüz ecesi

çöllerde var mı adımın tek hecesi

ne nergis ne nilüfer ne de hanım eli

değdiyse elime 

ceset çiçeğine* yar olayım emi

ah Flora

saçlarını toplasan Trakya

açsan Karadeniz

yani bendeniz

hani benzemezdik biz

bak gördün mü

dokunduğum elma duyunca sesini

korkudan yenemedi yerçekimini

bilmeden

hercai düşlerime  konan kelebekler 

koza örer tırtıla dönerler

meğer ne çok sevenin varmış  sevgili! 

Ah Flora

ne yalan söyleyeyim

hiç sevemedim ukala Ovidius’u

ona inat konuşturacağım Stradavarius’u

kasılma Vivaldi  seni de dirilteceğim

yazınca beşyüz keman konçertosu

affetmen için

ne yapsam ne yapsam

ateşböceklerini kandırsam

toplayıp ay mı yapsam

kayan yıldızları yakalasam

altlarına göktaşı mı koysam

belli çok kızgınsın Flora

kırağılar kaplamış saçlarını

sisler bürümüş anılarını

umut yok mu yoksa bu bahara

Flora biricik sevgilim

ben bana kefilim! 

şu senin boyçeçaklar**

söyle ne zaman açacaklar? 

vazgeç artık şu inadından 

bilmez misin

yese de kabuslarımı bir bir güveler

küçülmez içimde tarumar geceler

bana yeşilinden üfle

neminle küfle

yeniden can olayım Flora

insanlar sevmesine severler seni 

üşümeyesin diye

kumla örterler er geç bedenini! 

yazık! ...

bu kadar sevmişken birbirimizi

sen şimdi

aydan umuyorsun fotosentezi

son dileğim mi  o da  elimde! 

unutma beni...unutma beni...

          unutma beni***...  

 *Ceset çiçeği: “Titan arum ” 

 **Boyçeçak:Özbekçede Kardelen anlamındadır.

*** Unutma beni çiçeği: Myosotis Sylvatica 

12.12.2005', '“Ceza kaldırılabilir; ama suç insanın içinde sonsuza kadar yaşar.” - Ovidius Allah aşkına Flora söyle ne yaptım sana ben kim seni aldatmak k...', ARRAY['Türk Edebiyatı','Şiir','Aydın Çevik']::text[], 8.5, '{"poet":"Aydın Çevik","poet_slug":"aydin-cevik","theme":"Türk Şiiri","is_hero":false,"total_lines":81,"source_url":"https://www.antoloji.com/fotosentetik-yaramazliklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vakit Bulamadım', 'vakit-bulamadim-onur-ridvan-tozlu-kcweb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir düştü sevmek benim için

Zor işti ölmek benim için

Kahrolsun diyorum kendi kendime

Seviyorum bu dünyayı diyorum kendi kendime

Hiç vakit bulamadım sevmeye

Hiç vakit bulamadım ölmeye 

Kahrolsun

Yinede 

Seviyorum bu dünyayı.

(09/12/05)', 'Bir düştü sevmek benim için Zor işti ölmek benim için Kahrolsun diyorum kendi kendime Seviyorum bu dünyayı diyorum kendi kendime Hiç vakit b...', ARRAY['Türk Edebiyatı','Şiir','Onur Rıdvan Tozlu']::text[], 8.5, '{"poet":"Onur Rıdvan Tozlu","poet_slug":"onur-ridvan-tozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/vakit-bulamadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Severim Onu', 'severim-onu-onur-ridvan-tozlu-ph5cb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kim derdi ki onun böyle olacağını,

Kim derdi ki 8 tane zayıfı olacağını,

Gerçi hiç çalışmazdı

Ancak,

Garibim iyi çocuktur

Ne kadar kopya çekse de

Ne kadar yaramazlık yapsada

Ne kadar okuldan kaçsada

Severim onu,

Garibim iyi çocuktur

Ne kadar kopya ile geçsede 

Hiç çalışmasada elbet geçerdi

Ne kadar uyuşukta olsa

Severim onu,

Garibim iyi çocuktur

Beraber çok iş yaptık,

Çok gezdik,

Çok dolaştık

Severim onu

Garibim iyi çocuktur

(09/12/2005)', 'Kim derdi ki onun böyle olacağını, Kim derdi ki 8 tane zayıfı olacağını, Gerçi hiç çalışmazdı Ancak, Garibim iyi çocuktur Ne kadar kopya çek...', ARRAY['Türk Edebiyatı','Şiir','Onur Rıdvan Tozlu']::text[], 8.5, '{"poet":"Onur Rıdvan Tozlu","poet_slug":"onur-ridvan-tozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/severim-onu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatamadım', 'anlatamadim-perihan-dosgul-v1ylc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Neden bilinmez, haykırışlarımı

Anlatamadım, ağzımı açıp anlatacak

Gücü bulamadım, yıllarca

O güç hiç olmadı ki...

Anlayacak kimsede yoktu zaten.

Yanlızlaştırıldım yıllarca.

Tam anlatacak yerde de 

Yaşam son buldu...', 'Neden bilinmez, haykırışlarımı Anlatamadım, ağzımı açıp anlatacak Gücü bulamadım, yıllarca O güç hiç olmadı ki... Anlayacak kimsede yoktu za...', ARRAY['Türk Edebiyatı','Şiir','Perihan Dosgül']::text[], 8.5, '{"poet":"Perihan Dosgül","poet_slug":"perihan-dosgul","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/anlatamadim-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tebessüm Et', 'tebessum-et-ramazan-kurt-f5gs4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gör ağaran saçlarımı.

Sil dökülen yaşlarımı.

Zehir etme aşlarımı.

Tebessüm et barışalım.

		

Aşık oldu gönlüm sana.

Seviyorum anlasana! 

Son hakkını kullansana! 

Tebessüm et barışalım.

			

Mecnun ettin yarim beni.

Dargınlığın yok nedeni.

Deli gönlüm sever seni.

Tebessüm et barışalım.		

		

Gönlümü çaldın sen hırsız.

Çiçek soldu arı balsız.

Yaşanır mı hiç sevdasız.

Tebessüm et barışalım.		

Bahçede güller derelim.

Aşkın kıymetin bilelim. 

Senle murada erelim.

Tebessüm et barışalım.

El sözüne kanma gülüm.

Aşkın bana verdi zulüm.

İnan ki sonumuz ölüm.

Tebessüm et barışalım. 

			

Ramazanım düştüm dara.

Hiç gerek yok intizara.

Aşkın sinemde bir yara.

Tebessüm et barışalım.', 'Gör ağaran saçlarımı. Sil dökülen yaşlarımı. Zehir etme aşlarımı. Tebessüm et barışalım. 		 Aşık oldu gönlüm sana. Seviyorum anlasana!  Son ...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Kurt']::text[], 8.5, '{"poet":"Ramazan Kurt","poet_slug":"ramazan-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/tebessum-et-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Bana', 'sen-bana-ramazan-kurt-z4kzq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yol ettin üstümden çiğneyip geçtin.

		Sevilmek variken kaçmayı seçtin. 

		Yıllar gibi bana ihanet ettin.

		Sen bana Allah da sana çektirsin.

		Çiçekleri solmuş bağa çevirdin.

		Yaşlanmış bir çınar gibi devirdin.

		Acı verdin,keder verdin,dert verdin.

		Sen bana Allah da sana çektirsin.

		Dinmez göz yaşlarım sel olur akar.

		Bir vefasız benim yüreğim yakar.

		Başkası olsa sana bir kurşun sıkar.

		Sen bana Allah da sana çektirsin.

		Ramazanım kurşun değdi pençeme,

		Kara bahtım tokat vurdu enseme,

		Diken olup düştün gönül bahçeme.

		Sen bana Allah da sana çektirsin.', 'Yol ettin üstümden çiğneyip geçtin. 		Sevilmek variken kaçmayı seçtin.  		Yıllar gibi bana ihanet ettin. 		Sen bana Allah da sana çektirsin....', ARRAY['Türk Edebiyatı','Şiir','Ramazan Kurt']::text[], 8.5, '{"poet":"Ramazan Kurt","poet_slug":"ramazan-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-bana-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlamak', 'aglamak-perihan-dosgul-lvgxo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yıllardır hep ağlayan ben oldum,

Baktım etrafımda kimseler yoktu.

Dost dediğim insanlar hep güldü

Ağlayan yine hep ben oldum

Mutluluğu hep aradım durdum

Sen yanımdaydın, ama ben mutsuz

Demek ki mutluluk vermedin bana

Bu aşkın sonu başlamadan bitmeliydi.

Bu ısrar, bu inat neden

Anlayamadım.', 'Yıllardır hep ağlayan ben oldum, Baktım etrafımda kimseler yoktu. Dost dediğim insanlar hep güldü Ağlayan yine hep ben oldum Mutluluğu hep a...', ARRAY['Türk Edebiyatı','Şiir','Perihan Dosgül']::text[], 8.5, '{"poet":"Perihan Dosgül","poet_slug":"perihan-dosgul","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/aglamak-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eydost', 'eydost-fahrettin-selcik-ttiq4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'E Y D O S T

Gelen kurban,asrın son bayramıdır,

Yapılacak seçim ise,parlamentoya uyarıdır,

Bizlere düşen görev,uygun ve uygar seçim,

Neticesinde hedeflenen,yeterli geçim.

Umutluyuz çünkü çağ değişiyor,

Yavaş dahi olsa, ülkemiz gelişiyor,

İnsanların yapısı değişecek elbet,

Memlekete gelecek bolluk,bereket.

ELKİMA gelişime ayak uyduracak,

Sektöründe,rakipleri aşıp lider olacak,

Diliyorum işiniz bol aşınız tatlı olsun,

Bu vesile ile bayramınız kutlu olsu

F.Selçik  20 Aralık 1999 İzmir

,

.

Umutluyuz çünkü çağ değişiyor,

Yavaş dahi olsa, ülkemiz gelişiyor,

İnsanların yapısı değişecek elbet,

Memlekete gelecek bolluk,bereket.

ELKİMA gelişime ayak uyduracak,

Sektöründe,rakipleri aşıp lider olacak,

Diliyorum işiniz bol aşınız tatlı olsun,

Bu vesile ile bayramınız kutlu olsu

F.Selçik  20 Aralık 1999 İzmir', 'E Y D O S T Gelen kurban,asrın son bayramıdır, Yapılacak seçim ise,parlamentoya uyarıdır, Bizlere düşen görev,uygun ve uygar seçim, Neticesi...', ARRAY['Türk Edebiyatı','Şiir','Fahrettin Selçik']::text[], 8.5, '{"poet":"Fahrettin Selçik","poet_slug":"fahrettin-selcik","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/eydost-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektuplar-20 14/12/2005', 'mektuplar-20-14-12-2005-mahzun-doga-mqis3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Neydik biz.

Kimimiz vardı bizi bize hatırlatan.

Kimdik.

Neyimiz vardı kim olduğumuzu gösteren.

Eksikken eksiltilmiş, 

azken azaltılmış bir şeydik.

Tamamlanmayı bekleyen, 

çoğalmayı umutlayan adımlarımızla.

Son defa düşmeyi bekledik asırlarca.

Bizi bilen sadece biz.

Sadece ikimiz biliyorduk.

Ve ikimiz de bilmiyorduk ikimizin ikimiz olduğunu.

Nerdeydik.

Neremiz vardı bize bizi gösteren.

Kimindik. 

Kimimiz vardı bizi kendisinde barındıran.

Sadece ikimiz barındırıyorduk.

Biliştiğimiz yer.

Cehennemin ortasındaki cennet.

Biz varız orda.

Yığıldık birbirimizin yalnızlığına.

Mavi elbiselerimizi giydik.

Ve karışıyoruz şimdi birbirimizin kim? ’ine.

Ve iyi biliyoruz birbirimizin neyi? olduğumuzu.

Sadece ikimiz biliyoruz.

Bütün korkularımızı birbirimizin cesaretinde yargıladık.

Cevaplar sardık asırlık sorularımıza.

Yakalayıp indirdik bedenlerimizden dokunulmazlığımızı.

Seni sundum kendime.

Sen beni.

Kayıpsız gidiyoruz kayıplarımızı bulmaya.

Bulduklarımız şimdi yaşadıklarımız.

Koşuyoruz.

Her adımı bir diğerinden uzunca.

Biri diğerinden ağır ve asil.

Kutsal yerlerimizi keşfettik.

Emeğini soluyoruz sevginin.

En cazip yerlerindeyiz birbirimizin.

Dokunulmamış.

Kirlenmemiş.

En mahrem yerlerinde uyuyoruz şimdi birbirimizin.

Büyüdük.

Kocaman oluyoruz.

Ve sadece ikimiz biliyoruz.

Buluştuk.

Soyunduk.

Sadece ikimiz görüyoruz.

Sadece ikimiz biliyoruz.

Yaşadıklarımız asır.

Şimdimiz ebediyet.

Yarın sadece gün.

Kısa bir zaman sadece; 

Bize değince o zaman asır olacak.

Sadece ikimiz biliyoruz.', 'Neydik biz. Kimimiz vardı bizi bize hatırlatan. Kimdik. Neyimiz vardı kim olduğumuzu gösteren. Eksikken eksiltilmiş,  azken azaltılmış bir ş...', ARRAY['Türk Edebiyatı','Şiir','Mahzun Doğa']::text[], 8.5, '{"poet":"Mahzun Doğa","poet_slug":"mahzun-doga","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/mektuplar-20-14-12-2005-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ya Da! ..', 'ya-da-gokten-aydogdu-s5dkn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Biliyor musun? 

Özledim seni

Gizemli gözlerinle

Sırlarını çözmeye çalıştığım

Sıkışık anlarda

Derinden gelen sesini

Duymaya çalışıyorum

Issız zamanlarda

Arayışların belirsiz

Hiç ummadığım 

Ya da...

Sabırsızlandığım

İçim içimi yerken

Çırpındığım anlarda

Yürüyorum sensizlik üçgeninde

Ulaştığım nokta

Doğru yer değil

Çözmek kabil mi seni

Belki bir gün 

Ya da...', 'Biliyor musun?  Özledim seni Gizemli gözlerinle Sırlarını çözmeye çalıştığım Sıkışık anlarda Derinden gelen sesini Duymaya çalışıyorum Issız...', ARRAY['Türk Edebiyatı','Şiir','Gökten Aydoğdu']::text[], 8.5, '{"poet":"Gökten Aydoğdu","poet_slug":"gokten-aydogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ya-da-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Demler', 'sensiz-demler-gulseren-onay-6wvw9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Barba’nın meyhanesinde 

Sevda şarkıları söyler

Hanendeler…

Damla damla birikir

Gurbet acısı…

Bir dilim peynirle hayalin

Meze olur rakıma

Demlenirim….

Yokluğunun hüznü

Poyraz misali

Keser yüreğimi lime lime

Kaçamak aşklar 

Yaşarım kapı aralarında..

Dalarım koynuna,

Gördüğüm her güzelin,

Sabaha seninle uyanma 

İhtimaliyle…

Yağmur kokusu sarar havayı

Sigaramın dumanı 

Kaçar gözlerime,

Sen yoksun', 'Barba’nın meyhanesinde  Sevda şarkıları söyler Hanendeler… Damla damla birikir Gurbet acısı… Bir dilim peynirle hayalin Meze olur rakıma Dem...', ARRAY['Türk Edebiyatı','Şiir','Gülseren Onay']::text[], 8.5, '{"poet":"Gülseren Onay","poet_slug":"gulseren-onay","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sensiz-demler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gram ve kilo', 'gram-ve-kilo-omer-yildiz-1ctn5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ay

Geceye küsmüş,

Güneşse güne...

Değişmiş herşey

Dünya dönüyor tersine.

Ölüler doğuruyor,

Dirilerse kısır...

Daha

Farkında değil misin? ...

Grama boyun eğmiş,

Kilo da kusur...', 'Ay Geceye küsmüş, Güneşse güne... Değişmiş herşey Dünya dönüyor tersine. Ölüler doğuruyor, Dirilerse kısır... Daha Farkında değil misin? ......', ARRAY['Türk Edebiyatı','Şiir','Ömer Yıldız']::text[], 8.5, '{"poet":"Ömer Yıldız","poet_slug":"omer-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gram-ve-kilo-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul''u bilir misin', 'i-stanbul-u-bilir-misin-omer-yildiz-z61zz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İstanbul''u 

Bilir misin? 

Bilir misin

Ne kadar güzel? ...

Her yanı ayrı

Her yanı bir başka.

İllede boğazı

Aynı

Senin

Dudaklarına benzer', 'İstanbul''u  Bilir misin?  Bilir misin Ne kadar güzel? ... Her yanı ayrı Her yanı bir başka. İllede boğazı Aynı Senin Dudaklarına benzer...', ARRAY['Türk Edebiyatı','Şiir','Ömer Yıldız']::text[], 8.5, '{"poet":"Ömer Yıldız","poet_slug":"omer-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/istanbul-u-bilir-misin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek celse', 'tek-celse-sair-yaman-ckjm1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'istemiyorum ayrılığı bekle 

kalemler kırılmasın hakim bey

vurmasın duruşmaya damgasını

bir sevda uğruna akan göz yaşları

tek celse yetmez ayrılığa

uzat miadını bu aşkın

yürek dayanmaz tek celse sevdaya

delilim var hakim bey

bu aşkı yüreğime sormalı

sor hakim bey sor

sevmiş mi benim gibi? 

yanmış mı geceleri kor kor? 

ara ver bu duruşmaya hakim bey

hasret duvarlarını yıkmak inan çok zor

gözümün önünde her an zalim yar

kalemden önce kırılan bir gurur var

ben aşka aşık olmuşum sorun kendisine

benim aşkı bilmeyenlerin içinde işim ne

kır kalemi hakim bey

cezam neyse çekmeye hazırım

on yıl, yüz yıl, bin yıl

istersen aşk uğruna cezamı müebbet kıl

kır kalemi hakim bey tam on parçaya

parmak basma yeter ki bir asırlık yaraya...', 'istemiyorum ayrılığı bekle  kalemler kırılmasın hakim bey vurmasın duruşmaya damgasını bir sevda uğruna akan göz yaşları tek celse yetmez ay...', ARRAY['Türk Edebiyatı','Şiir','Şair Yaman']::text[], 8.5, '{"poet":"Şair Yaman","poet_slug":"sair-yaman","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/tek-celse-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anla Beni', 'anla-beni-zeliha-bicer-5qxol', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bilir misin ki? 

Sensizliklerim sancı

Bilir misin ki? 

Sesin tabum

Sensiz ne haldeyim

Anla beni...

Gelmesede resmin

Duymasamda sesin

Çağlasada gönlüm

Seni seviyorum

Anla beni...

Aldırma girdaplara

Bakma sen karanlık sabahlara

Sen benim ışığımsın

Anla beni...

Boşver desem

Yalan! 

Gelme desem

Yalan! 

Öyle özledim ki tenini

Her kadehte seni içer olduğumdan

Kadeh düşmüyor elimden

Anla beni....', 'Bilir misin ki?  Sensizliklerim sancı Bilir misin ki?  Sesin tabum Sensiz ne haldeyim Anla beni... Gelmesede resmin Duymasamda sesin Çağlasa...', ARRAY['Türk Edebiyatı','Şiir','Zeliha Bicer']::text[], 8.5, '{"poet":"Zeliha Bicer","poet_slug":"zeliha-bicer","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/anla-beni-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rekor', 'rekor-hulusi-kilic-wot1a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sanki kafamdan alevler fışkırıyor,

Yanıyorum! 

Başım kazan gibi kaynıyor,

Kaçmak, kaçmak...

Sonsuza kadar kaçmak istiyorum! 

Bir değil,bin kez deneyeceğim.

Ne olur ne olmaz; 

Belki rekor kırarım.', 'Sanki kafamdan alevler fışkırıyor, Yanıyorum!  Başım kazan gibi kaynıyor, Kaçmak, kaçmak... Sonsuza kadar kaçmak istiyorum!  Bir değil,bin k...', ARRAY['Türk Edebiyatı','Şiir','Hulusi Kılıç']::text[], 8.5, '{"poet":"Hulusi Kılıç","poet_slug":"hulusi-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/rekor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O dut ağacı - 8', 'o-dut-agaci-8-elazigli-mustafa-kaya-mw13s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'seke seke geldin

tılsımlı nağmeler getirdin.

her yaprağında

inci saklayan ağacınla.

ve,

her çizgisi,

ayrı bir yüz gövdesine

sarılıp kalmışsın.

kimse sezinleyemedi

vefakar ziyaretini.

misk kokulu bir hatıraya

kendini bağlamışsın

vücutsuz bir duaya

gümüş zincirlerle

o dut ağacına..

Mustafa kaya

15.12.2005 / üsküdar

www.mustafakaya.net', 'seke seke geldin tılsımlı nağmeler getirdin. her yaprağında inci saklayan ağacınla. ve, her çizgisi, ayrı bir yüz gövdesine sarılıp kalmışsı...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/o-dut-agaci-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Aşk', 'ah-ask-hulusi-kilic-hz8qc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kafamda bilmediğim düşünceler,

Bu ne biçim duygu Allahım; 

Kendime gelemedim,gelemeyeceğim

Çünkü son otobüsü de kaçırdım...

Niçin kendime hakim olamıyorum? 

İçim fokur fokur kaynıyor,

Sanki yemekhane tenceresi...

Kalkıp kendimi pencereden atmak

Ve o inişin oluşturduğu rüzgarla

Serinlemek istiyorum...', 'Kafamda bilmediğim düşünceler, Bu ne biçim duygu Allahım;  Kendime gelemedim,gelemeyeceğim Çünkü son otobüsü de kaçırdım... Niçin kendime ha...', ARRAY['Türk Edebiyatı','Şiir','Hulusi Kılıç']::text[], 8.5, '{"poet":"Hulusi Kılıç","poet_slug":"hulusi-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ah-ask-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hücrem', 'hucrem-elazigli-mustafa-kaya-6px40', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'poyraz  vuruyor,

delik deşik vücudum.

ruhuma batan,

kurşun kalem uçları.

bir yalnız adamım

karınca yuvası şehirde.

taştan karşılık aldım

insandan değil.

gurbetli ruhumu

rüzgarlar kokluyor

pas ve küf altında.

birkaç damla gözyaşı

birkaç nefeslik 

mutluluğum,

hücrem kadar.

şehrin taş gözleri

kendi körlüğüne inat

yalnızlığıma,

hislerime gülüyor.

ölüm içinde ölümü yaşar

sağır ve içine kapanık 

duvarlar.

Mustafa kaya

15.12.2005 / Pendik

www.mustafakaya.net', 'poyraz  vuruyor, delik deşik vücudum. ruhuma batan, kurşun kalem uçları. bir yalnız adamım karınca yuvası şehirde. taştan karşılık aldım ins...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/hucrem-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektup sevdiğime mektuplar son', 'mektup-sevdigime-mektuplar-son-durdane-demirkoparan-fjqj8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Merhabalarla başlayan 

Belkide son mektuptayım şimdi

Sensizlik 

Ve

Bu sonu belli olmayan yokluğun

Canımı acıtıyor

Konduramazdım hiç bize

Ayrılığı

Ve bilmezdim

Ayrılık bu kadar zor

Ayrılık bir zulüm

Ve sensizlik 

Kalbimi kanatan bir kor

Tarifi mümkün değil

İçimi yakan acının

Nasıl geçer ne zaman geçer belli değil

Geceleri sana  selam yollamıyorum artık

Kutup yıldızıyla

Ve senin sevdiğin  bluzumu giymiyorum geceleri

Resimlerimize bakamıyorum

Hala atamadım onları 

Sen yoksun

Bir tek onlar ve yüzüğümüz kaldı

Onlar benim işte sen olmasanda

Koklarım sen gibi

Saklarım koynumda

Öperim doya doya

Kızamazsın 

İncitemezsin artık

Sevdiğim için seni

Kış geldi yine

Ve ben üşüyorum sen yoksun

Sıcacık yatağımız ve yüreğin yok yanımda

Kokun sinmiş bedenime

Ve bu şehirde 

Yapayalnız yürüyorum geçtiğimiz sokaklarda

Ağlamaklı sanki onlarda

Ayrıldınız mı? der gibiler

Susuyorum

Düğümleniyor bişeyler boğazıma

Sensizlik sarıyor bedenimi

Ve delirme sınırında ben

Dayanamıyorum

Özlüyorum seni

İstiyorum bana gelmeni

Ve hiç gelmeyecek oluşun

Küstürüyor beni hayata

Sevdiğim kıyamadığım ya gel bana

Yada son kez bişey yap benim için dua et

Alsın bu canı yaradan

Seni tertemiz severken alsın

Yokluğun  zaten ölümden beter

Ve yine son mektubumda

Son kez

Seni seviyorum kıyamadığım…', 'Merhabalarla başlayan  Belkide son mektuptayım şimdi Sensizlik  Ve Bu sonu belli olmayan yokluğun Canımı acıtıyor Konduramazdım hiç bize Ayr...', ARRAY['Türk Edebiyatı','Şiir','Dürdane Demirkoparan']::text[], 8.5, '{"poet":"Dürdane Demirkoparan","poet_slug":"durdane-demirkoparan","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/mektup-sevdigime-mektuplar-son-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğmamış bebek', 'dogmamis-bebek-aysenur-yazici-limb9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'önce kirpiklerim döküldü

tuzla sulanmaktan..

kel oldu gözüm! 

sonra bir ağrı oturdu kasığıma

topal kalıverdi,

itlerden sayıldı sözüm...

üç ''lâ havle velâ'' dizdim 

üçü de kalben ve uzaktan 

sokağa atılmış kadın! 

sabır ırmağına karıştı...

...dibinde tevekkül 

ne aşkı? Tamamı  kan revân...

binlerce bebe feryad etti

yetimim dedi, al beni 

sağırdım! 

sakatlık altında ağırdım...

sadece ''sev'' dedim elimi

aylarca bunu bağırdım...

terkedilmiş öksüzler kimin dölü? 

Kalbimden kanlı bir çocuk doğurdum,

aldım koynuma uyudum...

kundaksız...ve  ölü! 

                (00:14) 

              Tarabya

              15.12.2005

             Andrea and', 'önce kirpiklerim döküldü tuzla sulanmaktan.. kel oldu gözüm!  sonra bir ağrı oturdu kasığıma topal kalıverdi, itlerden sayıldı sözüm... üç ''...', ARRAY['Türk Edebiyatı','Şiir','Ayşenur Yazıcı']::text[], 8.5, '{"poet":"Ayşenur Yazıcı","poet_slug":"aysenur-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/dogmamis-bebek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olur olur', 'olur-olur-bekir-mutlu-gokcesu-c4cij', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Olur tabi

Neden olmasın

Öyle de olur

Böyle de...

Bir dağ

Bir mevsim

Bir ağaç

Bir çiçek

...

Ne kadar uzak olursa olsun bize

Tebessümle hissetmektir yakın olan

Onu fikrimizde

Ve yaklaştıran bizi birbirimize

Bir aşkta öyle...

Olur tabi

Neden olmasın

Buluşmak bir şekilde

Bir yerde...

Ama nerede? 

Her yerde

Veya hiç bir yerde

Olur olur

Neden olmasın..', 'Olur tabi Neden olmasın Öyle de olur Böyle de... Bir dağ Bir mevsim Bir ağaç Bir çiçek ... Ne kadar uzak olursa olsun bize Tebessümle hisset...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/olur-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstiyorum', 'i-stiyorum-atila-gunal-k3u6i', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nerden esti bilmiyorum

Hiç böyle şeyler hissetmemiştim daha önce

Kontrolsüz.. Çok yoğun

Bir can dünyaya getirmek istiyorum

Günlük anlık da değil bu isteğim

Her bebek gözüme melek oldu

Dokunmak istiyorum

Sarılmak,öpmek istiyorum

Bu bir şiir ya da şiirimsi bile değil

Bu sadece içimdeki ateş....

İstiyorum işte yaaaaaa', 'Nerden esti bilmiyorum Hiç böyle şeyler hissetmemiştim daha önce Kontrolsüz.. Çok yoğun Bir can dünyaya getirmek istiyorum Günlük anlık da d...', ARRAY['Türk Edebiyatı','Şiir','Atila Günal']::text[], 8.5, '{"poet":"Atila Günal","poet_slug":"atila-gunal","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/istiyorum-65-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğine Sağlık', 'yuregine-saglik-melih-coskun-ao1mh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yüreğine sağlık diyorsun bana

Olmasa bu yara, 

Bu dert olmasa, 

Bu dizeler nasıl yazılırdı sanıyorsun 

Kandan satırlar kağıtlarımda

Ellerim ter içinde 

Tutmuyor artık dizlerim

Bin yıl büyüdüm sanki bir yılda 

Her kelimemde bir yıl 

Her cümlemde asırlar tükendi ömrümden

Ne olurdu sanki 

Kan akmasaydı nehirlerimden 

Kalmasaydı çocuk yüzün yaşlar içinde

Dönebilseydi o sebepsiz savaştan oğul 

Yaslayabilseydi göğsüne başını 

Hasretini koğuşunun duvarlarına 

Şafak şafak kazıdığı annesinin, 

Okul yolunda donup kalmasaydı

Köylü çocuğu.

Ne olurdu ziyan edilmeseydi emek 

Kavuşabilseydi her sürgün yürek sevdasına

Kurşunlanmasaydı delikanlı gecenin tenhasında

Ve satılmasaydı düşlerin üç kuruşa

Yazılmasa da olurdu

Söylenmese de 

Yeter ki yaşayabilseydik 

Hür 

Eşit

Ve insanca...

8 Mart 2003', 'Yüreğine sağlık diyorsun bana Olmasa bu yara,  Bu dert olmasa,  Bu dizeler nasıl yazılırdı sanıyorsun  Kandan satırlar kağıtlarımda Ellerim ...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yuregine-saglik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evrensel', 'evrensel-hulusi-kilic-szfxf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bak gülüm; 

Seni çok seviyorum! 

Sana olan sevgimin büyüklüğü

Ne yüksek dağlar gibi ölçülebilir,

Ne de en büyük denizler gibi geçilebilir.

Benim sevgimi her yerde görebilirsin:

Çünkü o her yerde,her şeyde var.

Sevgim tüm doğayı,

Evreni kaplayacak kadar yüce.

Ne bir canlı ömrü gibi biter,

Ne de büyük bir etki ile yıkılabilir.

Öyle içten bir sevgi ki; 

Ne senin engellemelerinle biter,

Ne de geçen uzun günlerde yiter...', 'Bak gülüm;  Seni çok seviyorum!  Sana olan sevgimin büyüklüğü Ne yüksek dağlar gibi ölçülebilir, Ne de en büyük denizler gibi geçilebilir. B...', ARRAY['Türk Edebiyatı','Şiir','Hulusi Kılıç']::text[], 8.5, '{"poet":"Hulusi Kılıç","poet_slug":"hulusi-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/evrensel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adım Adım', 'adim-adim-gul-aycan-xd2cb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her insan umutla başlar hayata.

Umutsuz hayatla geçmez bir ömür.

Bir yol belirir de uzar sahnede.

Yaşanır sahnede geçer bir ömür.

Yaşarsın ömrünü adımlarınla.

Her adım bir öykü anlatır sana.

Yürürsün, gidersin umutlarınla.

Attığın her adım güç verir sana.

Bir şeyler değişir olur ve biter.

Değişen değişsin, değişim bitsin.

Kalan son söz budur bu da değişir.

Geride kalanlar bu sözü bilsin.

Dediğim söz budur, her şey değişir.

Geleceği söylenen gün gelmiştir.

Hayat budur, yollar biter, tükenir.

Sözler söylenmeden yitip gitmiştir.

Her gün son bulur bir gün biter elbet.

Zaman geçer gider, kıymetini bil.

Sen hayat yoluna böyle devam et

Ya da bu yazıyı en başından sil.

5 Haziran 2004', 'Her insan umutla başlar hayata. Umutsuz hayatla geçmez bir ömür. Bir yol belirir de uzar sahnede. Yaşanır sahnede geçer bir ömür. Yaşarsın ö...', ARRAY['Türk Edebiyatı','Şiir','Gül Aycan']::text[], 8.5, '{"poet":"Gül Aycan","poet_slug":"gul-aycan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/adim-adim-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cama vuran bir kuş', 'cama-vuran-bir-kus-elazigli-mustafa-kaya-dfbr6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'süzülüp bulutlarla

insem,

kokusu misk ocağına.

razıyım,

ateş tozu olmaya.

kulağın kirişte olsun

bir kuş vursun

başını dayadığın cama

korkma kimmiş

korkma sevgilim

görmek için meraktan

gözlerini,

gözlerin sürmelenmiş.

ve,

en keskin mana renkleri

sinmiş..

Mustafa kaya

15.12.2005 / Sarayburnu

www.mustafakaya.net', 'süzülüp bulutlarla insem, kokusu misk ocağına. razıyım, ateş tozu olmaya. kulağın kirişte olsun bir kuş vursun başını dayadığın cama korkma ...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/cama-vuran-bir-kus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle', 'seninle-hulusi-kilic-6j1vp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şu eşitsizliklerle dolu evrende

En neşesiz,en acı günlerimde bile

Bu yaşamdan yılmadan,bıkmadan

Tüm gücümü kullanarak

Yaşamayı sürdürürdüm...

Çünkü biliyorum ki; 

Bu dengesiz evreni bile sevdirecek

Bir neden,bir kişi bulunur.

Sen benim bu evrendeki

En büyük yaşama kaynağımsın.

Bu yöreler,bu insanlar...Bu dünya! 

Seninle,sana olan sevgimle güzelleşiyor; 

Yaşam anlam kazanıyor SENİNLE!', 'Şu eşitsizliklerle dolu evrende En neşesiz,en acı günlerimde bile Bu yaşamdan yılmadan,bıkmadan Tüm gücümü kullanarak Yaşamayı sürdürürdüm.....', ARRAY['Türk Edebiyatı','Şiir','Hulusi Kılıç']::text[], 8.5, '{"poet":"Hulusi Kılıç","poet_slug":"hulusi-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/seninle-81-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitmeyen Yalnızlık', 'bitmeyen-yalnizlik-gul-aycan-lxp4p', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen gelince biter sanmıştım yalnızlığım; 

Ama şimdi eskisinden daha yalnızım.

Hep yanımdaymış gibi gelen varlığını

Sen benim yanıma gelince kaybettim.

Ete kemiğe bürünmeden önce vardın.

Demek ki özlemmiş aşkı yaratan.

Şimdi vücut buldun, şimdi yok oldun.

Ben asıl seni, seni görünce kaybettim.

			HAZİRAN  2004', 'Sen gelince biter sanmıştım yalnızlığım;  Ama şimdi eskisinden daha yalnızım. Hep yanımdaymış gibi gelen varlığını Sen benim yanıma gelince ...', ARRAY['Türk Edebiyatı','Şiir','Gül Aycan']::text[], 8.5, '{"poet":"Gül Aycan","poet_slug":"gul-aycan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bitmeyen-yalnizlik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu bir şiir değildir', 'bu-bir-siir-degildir-omer-yildiz-b6c5p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şimdilerde biz

Daha 

Beş adım ötemize   gidemezken…

Nesillerine 

Yurt bırakmak için

Kalkıp

Taaa Orta Asya’dan

Gelmek

Ve

Dayanmak

Tuna’nın kıyılarına,

Viyana surlarına…

Dünyanın tam 

Kalbine

Taht kurmak…

Ölmek

Yurt bırakmak için evlatlarına…

Evlatlarsa

Şimdilerde biçare…

Beslediği 

Kargalarca   gözü oyulmakta… 

Üç kuruşluk

Ne menem 

İnsanların oyuncağı durumunda…

EY EVLATLAR! ...

Övünürken,

Anlatırken 

Alparslan’dan

 Fatih’ten 

Atatürk’ten

Kül bırakmazsınız mangalda

Ve

Bin kere de övünseniz azdır 

Amma 

yarın, 

Bir avuç toprak kalmış vatanına

Sahip çıkamayarak, 

Dünyanın maskarası olmayın da…

Koşun, 

Koşun Avrupa Birliği kurtaracak sizi.

Elleriyle paralar koyacaklar

Cüzdanlarınıza,

Fabrikalar kuracaklar, 

Fatih’in torunları daha da güçlensin diye…

Mahkemelerinizde 

En iyi adaleti onlar sağlayacak, 

İnsanca yaşamanın kurallarını 

Onlar öğretecekler

Avrupa görmüş yöneticilerimize…

Döve döve! 

Adama döndürecekler sizi... 

Hani biz kuş beyinliyiz ya…

YARIN

ÖTME BÜLBÜL; 

Bir avuç darı peşinde koşan kargalar

Bülbüllerin sesini bastırırken 

Göklerin hakimi kartallar 

Şahinler nerede? ...

Bana kimse ölmekten bahsetmesin 

Hayatın en kolay yanı bu.

Bundan bana ne…

Bana ben fayda sağlayamıyorsam 

Elden gelecek faydanın anlamı ne...

Çalış

Haydi biraz daha çalış…

Tut elinden 

Bilim adamlarının

Ve 

Destek ver,

Yol ver genç beyinlere.

Hakimlerin

Hakim olsun düzene 

Cumhuriyet savcıların 

Yiğitçe yapışsın hırsızların 

Kanunsuzları yakasına…

Ordun güçlü dağ kadar 

Ellerini kırar vatana el uzatanın…

Şimdilerde gözleri uzaydaki yıldızlarda…

Gelmenin manası gitmektir...

Dünya arenasında elçilere nasihat

Askari Adalet…

Azami menfaat olmalıdır.

Ver ver kazan…

Kazan? ... 

Kazan ne kaynar dibinde…

Her gün el üstünde taşınanlar

Zafer kazananların mı? 

Yoksa 

Sessizce 

Senin için ölen adsız kahramanların mı? ... 

Analardan başka 

Yüreği yanan var mı? ... 

Türklerin memleketinde,

Türklük utanacak bir şeyse,. 

Konuşması gerekenler suskunsa

Yarın bülbül kesilseler kime  ne? ... 

Avrupa birliğinin; 

Ne pahasına olursa olsu 

Avrupa birliğine girelim

Düşüncesindeki 

Akılları Başka

Taraftarlarının; 

Milletimize baskısı

“HER KİM Kİ 

AVRUPA DENEN MEDENİYETTEN KORKARSA 

GİTSİN ORTAÇAĞ ZİNDANLARINA,

HER KİM Kİ 

ULUSAL ONURUNU VE  ÇIKARLARINI KORUSA

 VERECEĞİM İNSAN HAKLARI MAHKEMESİNE….

Bizler 

ATATÜRK ‘ den, 

Türk Devletinden, 

Türk Milletinden,

Türk Ordusundan,

Atatürk Milliyetçiliği çerçevesinde

Türklüğü ile övünen,

Türk Devletinin 

Ve 

Türk Milletinin 

Kesinlikle tarih boyunca 

IRKÇILIĞA karşı olduğu bilincinde   ki

Fertleri olarak,

Allaha dine imana katıksız inanan

Ancak 

Sonuna kadar

(bu ülkenin çimentosu olan)     

Laikliğe canı gönülden BAĞLI 

İnsanlarız…

AMACIMIZ

BÜYÜK BİR MİLLETİN 

YAŞAYAN NESLİ OLARAK; 

AVRUPADAN DA ÖTEDE, 

DAHA BÜYÜK İNSANİ DEĞER YUMAĞINA  SAHİP 

YÜKSEK VE GELİŞMİŞ MEDENİYET YARATMAK

TÜRK MİLLETİNİN

İÇİNDEN

BU MEDENİYETİ YARATACAK

BEYİNLERİ GÖREVE ÇAĞIRMAK

VE

TÜRK MİLLETİNİN FERDİ OLMAKTAN 

UTANMAYACAK İNSANLARI HAKİM KILMAKTIR…', 'Şimdilerde biz Daha  Beş adım ötemize   gidemezken… Nesillerine  Yurt bırakmak için Kalkıp Taaa Orta Asya’dan Gelmek Ve Dayanmak Tuna’nın kı...', ARRAY['Türk Edebiyatı','Şiir','Ömer Yıldız']::text[], 8.5, '{"poet":"Ömer Yıldız","poet_slug":"omer-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":141,"source_url":"https://www.antoloji.com/bu-bir-siir-degildir-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelmezsin ki', 'gelmezsin-ki-bekir-mutlu-gokcesu-me9xm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşk değildi benimki, aşk dizelerindi

Resmin yok bende tanımaz gözlerim seni

Zikreden seni her daim yüreğimdi

Usumda şiir sesin, nasıl özledim bilemezsin...

Gel desem gelmezsin ki...

Sen gittin ya aslında ne dururum bilmem

Çoktan çekip gitmeliydi...', 'Aşk değildi benimki, aşk dizelerindi Resmin yok bende tanımaz gözlerim seni Zikreden seni her daim yüreğimdi Usumda şiir sesin, nasıl özledi...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gelmezsin-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz', 'sensiz-hulusi-kilic-0rg4o', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Biliyorum bu gidişin sonu iyi değil

Ve ben bunu bile bile gidiyorum.

Daha erken gibi görünen sonumu hızlandırmak

Birazcık da olsa yaşamam gereken

Şu dengesiz dünyadan kopmak için...

Artık beni bu yaşama bağlayacak bir neden,

Bağlandığım dal kalmadı.

Tüm bağlarım

Daha gittiğin ilk günden koptu.

Bitmez sandığım ümitlerim

Daha o günden kayboldu.

Sen o gün beni terketmekle kalmadın,

Varımı yoğumu da sildin.

Yaşamak ise anlamsız SENSİZ!', 'Biliyorum bu gidişin sonu iyi değil Ve ben bunu bile bile gidiyorum. Daha erken gibi görünen sonumu hızlandırmak Birazcık da olsa yaşamam ge...', ARRAY['Türk Edebiyatı','Şiir','Hulusi Kılıç']::text[], 8.5, '{"poet":"Hulusi Kılıç","poet_slug":"hulusi-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sensiz-148-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zeynep''in şiiri', 'zeynep-in-siiri-samiha-i-kbal-bhfhh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Zeynep’in sarı saçları vardı

Koyu kahve gözleri

Bir de edalı bakışları

             

Zeynep’in kırmızı terlikleri vardı

Ve de yaramazlıktan kızarmış yanakları

Zeynep’in oyuncakları vardı

Ve de oynayacak arkadaşları

Zeynep’in her şeyi vardı şu dünyada

Bir şiiri yoktu

O da oldu.', 'Zeynep’in sarı saçları vardı Koyu kahve gözleri Bir de edalı bakışları               Zeynep’in kırmızı terlikleri vardı Ve de yaramazlıktan ...', ARRAY['Türk Edebiyatı','Şiir','Samiha İkbal']::text[], 8.5, '{"poet":"Samiha İkbal","poet_slug":"samiha-i-kbal","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/zeynep-in-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-hulusi-kilic-b8i6a', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Fındık bahçelerinde bir gülsün,

Koparmaya kıyamadığım...

Gökyüzünde en parlak yıldızsın,

Seyrine doyamadığım...

Yüce bir duygusun,

Etkisinden kurtulamadığım.

En büyük deniz,en yüce dağsın,

Geçmeye yol bulamadığım.

Senin sevgin çıkmaz bir sokak; 

Çıkışını bulamadığım.

Seni sevmek en büyük tutku; 

Hiç bir zaman vazgeçmeyeceğim!', 'Fındık bahçelerinde bir gülsün, Koparmaya kıyamadığım... Gökyüzünde en parlak yıldızsın, Seyrine doyamadığım... Yüce bir duygusun, Etkisinde...', ARRAY['Türk Edebiyatı','Şiir','Hulusi Kılıç']::text[], 8.5, '{"poet":"Hulusi Kılıç","poet_slug":"hulusi-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-706-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgür yaşamak', 'ozgur-yasamak-sinan-aydindag-af0w1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '11 Aralık 2005

Rahat ve huzurlu yaşamak bana göre değil bu dünyada

Ben kaybetmeye alışmısım hem ticarette hem aşkta

Sefil olsun rezil olsun

İsterse parasız pulsuz olsun

Ama bu ahir ömrüm sadece benim ve hür olsun

Hiçbir otoriteye boyun eymem

Hiçbir güç yıldıramaz beni

Hiçbir aşka eyvallah etmem

Hiçbir kız yaralayamaz beni

Ben atalarım gibi hür yaşarım

At üstünde ok atmasamda

Kalemimle özgürce şiirler karalarım', '11 Aralık 2005 Rahat ve huzurlu yaşamak bana göre değil bu dünyada Ben kaybetmeye alışmısım hem ticarette hem aşkta Sefil olsun rezil olsun ...', ARRAY['Türk Edebiyatı','Şiir','Sinan Aydındağ']::text[], 8.5, '{"poet":"Sinan Aydındağ","poet_slug":"sinan-aydindag","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ozgur-yasamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni yaşıyorum', 'seni-yasiyorum-sinan-aydindag-u8hon', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '13 Aralık 2005

İpek teninle güzel gözlerinle 

Her daim yaşatıyorum hayallerimle

Seni Daha yüzün görmedim 

Elin elime deymedim

Zor olacak bu sevda 

İş olsun diye seni sevmedim

Sen şimdi ipek yolunun bir ucundasın

Bense yola çıktım sana geliyorum

Belki bir umut belki bir hayal bir düş

Sanki aldıgım her nefeste seni yaşıyorum', '13 Aralık 2005 İpek teninle güzel gözlerinle  Her daim yaşatıyorum hayallerimle Seni Daha yüzün görmedim  Elin elime deymedim Zor olacak bu ...', ARRAY['Türk Edebiyatı','Şiir','Sinan Aydındağ']::text[], 8.5, '{"poet":"Sinan Aydındağ","poet_slug":"sinan-aydindag","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/seni-yasiyorum-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İpeksi teninle', 'i-peksi-teninle-sinan-aydindag-pmce9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '13 Aralık 2005

Kalbim her attıgında seni zikreder

Aldıgım her nefeste sen girersin ciğerlerime

Nasıl yalvarırım yaratana her gece

Bir kerecik olsun görsem diye

Ve güneş dogar seninle günüme

Ve kuşlar doğaya sesslenir seninle

Birden ilkbahar esintileriyle 

İpeksi bir koku sarar etrafımı

Bunu senin yolladıgını bilirim

İçim neşeyle dolar sevinirim

Ve ardından akşam ay seninle çıkar en tepeye

Yıldızlar parlar seninle

Ve boş yatagımda ben hergece

Bir ölür bin dogarım ipeksi teninle...', '13 Aralık 2005 Kalbim her attıgında seni zikreder Aldıgım her nefeste sen girersin ciğerlerime Nasıl yalvarırım yaratana her gece Bir kereci...', ARRAY['Türk Edebiyatı','Şiir','Sinan Aydındağ']::text[], 8.5, '{"poet":"Sinan Aydındağ","poet_slug":"sinan-aydindag","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ipeksi-teninle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ama', 'ama-gul-aycan-doqm9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Elimde olsaydı eğer,

Her şeyi unutur,

Sil baştan yaşardım.

Ama ne yazık ki,

Elimde değil. 

20 MART 2004', 'Elimde olsaydı eğer, Her şeyi unutur, Sil baştan yaşardım. Ama ne yazık ki, Elimde değil.  20 MART 2004...', ARRAY['Türk Edebiyatı','Şiir','Gül Aycan']::text[], 8.5, '{"poet":"Gül Aycan","poet_slug":"gul-aycan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ama-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masal', 'masal-gul-aycan-7yja8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gitmek isterim de gidemem.

Bir masal anlatırsın bana 

Tutulmayan sözlerden acı.

Ne gerçek  ne de yalan.

           AĞUSTOS 2003', 'Gitmek isterim de gidemem. Bir masal anlatırsın bana  Tutulmayan sözlerden acı. Ne gerçek  ne de yalan.            AĞUSTOS 2003...', ARRAY['Türk Edebiyatı','Şiir','Gül Aycan']::text[], 8.5, '{"poet":"Gül Aycan","poet_slug":"gul-aycan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/masal-109-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herşeyde Sen Varsın', 'herseyde-sen-varsin-hulusi-kilic-lldh9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Senden ayrı olmak o kadar zor ki:

Gecemde,gündüzümde,

Aklımda,düşüncemde,

Gördüğüm her güzellikte,

Duyduğum her sözde ve şarkıda,

Attığım her adımda,

Konuştuğum her konuda

Sen ve senin sevgin var...

Benim herşeyim,tüm düşüncem sensin...

Yalnızlığımı,dertlerimi,üzüntümü

Sana olan sevgim unutturur.

Mutluluğumu,sevincimi ve başarımı da

Sana olan sevgim unutturuyor.

Çünkü; sensiz olan ne mutluluğun

Ne sevincin ne de başarının hiç anlamı yok.

En güzel,en acı günlerimi hep seninle paylaşmak; 

Mutsuz ve acı günlerimde dert ortağım,

Sevinçli ve başarılı günlerimin

Vazgeçilmez tek ortağı olmanı istiyorum....', 'Senden ayrı olmak o kadar zor ki: Gecemde,gündüzümde, Aklımda,düşüncemde, Gördüğüm her güzellikte, Duyduğum her sözde ve şarkıda, Attığım he...', ARRAY['Türk Edebiyatı','Şiir','Hulusi Kılıç']::text[], 8.5, '{"poet":"Hulusi Kılıç","poet_slug":"hulusi-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/herseyde-sen-varsin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk (I)', 'ask-i-gul-aycan-ubqeb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir gün gelecek sen de anlayacaksın,

Aşk diye bir şey olmadığını! 

Aşk denen şeyin 

Göz kapaklarına kondurulan bir busenin 

Kirpiklerin ucundaki intiharından

Başka bir şey olmadığını! 

Aşk bir yalandır.

Kimi zaman insan ona öyle inanır ki,

Gerçek olduğunu sanır.

	            KASIM 2002', 'Bir gün gelecek sen de anlayacaksın, Aşk diye bir şey olmadığını!  Aşk denen şeyin  Göz kapaklarına kondurulan bir busenin  Kirpiklerin ucun...', ARRAY['Türk Edebiyatı','Şiir','Gül Aycan']::text[], 8.5, '{"poet":"Gül Aycan","poet_slug":"gul-aycan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ask-i-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sırası Mıydı?', 'sirasi-miydi-gul-aycan-7zpju', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir mavi deniz gelir yanına,

Beyaz kelebekler ıslatır ayaklarını,

Küçük bir çocuk olursun.

Aldırmazsın kimin ne dediğine.

Bir ses duyarsın uzaklardan

Gidersin adım adım, korkmadan 

Korkularının üzerine üzerine.

“Haydi kalk” diye biri çağırır seni.

Gözlerini açarsın, 

Karşında penceren vardır.

Sırası mıydı, dersin şimdi uyanmanın.

	

MART 2004', 'Bir mavi deniz gelir yanına, Beyaz kelebekler ıslatır ayaklarını, Küçük bir çocuk olursun. Aldırmazsın kimin ne dediğine. Bir ses duyarsın u...', ARRAY['Türk Edebiyatı','Şiir','Gül Aycan']::text[], 8.5, '{"poet":"Gül Aycan","poet_slug":"gul-aycan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sirasi-miydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Balon', 'balon-gul-aycan-kqp1y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aşk bir balona benzer,

Sen üfledikçe o da şişer; 

Ama küçük bir toplu iğne

Son verir bütün bir sevdaya.

13 ARALIK 2003', 'Aşk bir balona benzer, Sen üfledikçe o da şişer;  Ama küçük bir toplu iğne Son verir bütün bir sevdaya. 13 ARALIK 2003...', ARRAY['Türk Edebiyatı','Şiir','Gül Aycan']::text[], 8.5, '{"poet":"Gül Aycan","poet_slug":"gul-aycan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/balon-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Şey', 'cok-sey-gul-aycan-miszd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çok şey istiyorum çok şey.

Ne istediğimi bilmiyorum bile,

Ama gerçekleşmediğine göre

Çok şey istiyorumdur herhalde.

11 EKİM 2002', 'Çok şey istiyorum çok şey. Ne istediğimi bilmiyorum bile, Ama gerçekleşmediğine göre Çok şey istiyorumdur herhalde. 11 EKİM 2002...', ARRAY['Türk Edebiyatı','Şiir','Gül Aycan']::text[], 8.5, '{"poet":"Gül Aycan","poet_slug":"gul-aycan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/cok-sey-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım annem', 'canim-annem-ethem-turan-8zccg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Annem dedim canım dedim her şeyim din 

Canım annem iste uğrunda öleyim

Analık hakkını helal et dedim 

Gençliğime ver aşığım dedim

 Senin adın geçince ömrümün anlamı bir başka bu gece

Beni vursunlar ölsem gömülsem derinliklere

Senin sıcaklığın matemin bir başka annem 

Kaybetme korkusu yıkar bütün dünyamı 

Gözüm görmez benden olanı 

Anla güzel annem anla efkarımı 

Sen bir başka yarsın bana 

Sevdaların en temizi ve yücesi sana 

Sen benim vazgeçemeyeceğim yarsın 

Şiirler sana aşklar sana sadakat sana 

Sana güzel annem 

Sevda çekerim ama  ne ki senin sevdan  yanında 

İçerim güzel annem sakın kızma

Kahrımdan  aşkımdan yangınımdan içerim 

Bilirim anam  yanarsan benim için sen yanarsın 

Ne menfaat ne de çıkar ararsın birsen seversin

Sen benim kara sevdamsın 

Anamsın

Ölüm gelir aklıma senin yokluğunda 

İçim burkulur yüreğim dağlanır 

Gözlerim başlar buğulanmaya 

Nedendir benim güzel anam nedendir bilmem 

Ama ağlamak gelir hep içimden 

Seni kaybetmek ufacık yüreğime zor gelir 

Sensizlik acı verir varlığın da yokluğunu 

Düşünmesi zor gelir güzel annem 

İçtim seni düşündüm 

Senin yokluğunu düşündüm annem 

Sensiz ne yaparım benim annem 

Kime anlatırım söyleyemediğim sırlarımı 

Hüznümü sevincimi kimle paylaşırım 

Kime aşık olurum kimi doyasıya severim

Ölümsüz ol güzel annem 

Hiç ölmeyecekmiş gibi 

Hep yanımda ol

Sıcaklığınla ve şefkatinle yanımda güzel annem', 'Annem dedim canım dedim her şeyim din  Canım annem iste uğrunda öleyim Analık hakkını helal et dedim  Gençliğime ver aşığım dedim  Senin adı...', ARRAY['Türk Edebiyatı','Şiir','Ethem Turan']::text[], 8.5, '{"poet":"Ethem Turan","poet_slug":"ethem-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/canim-annem-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başka...', 'baska-gul-aycan-4fud5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Herkesin yalanı başka 

